--
-- Name: access_requests_referral(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.access_requests_referral() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_program record;
  v_referrer commerce.referrers%ROWTYPE;
BEGIN
  SELECT * INTO v_program FROM commerce.referral_program();
  IF NOT v_program.enabled THEN
    RETURN NULL;
  END IF;
  SELECT * INTO v_referrer FROM commerce.referrers r WHERE r.code = lower(trim(NEW.referral_code));
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  IF EXISTS (SELECT 1 FROM commerce.accounts a WHERE a.id = v_referrer.account_id AND lower(a.email) = lower(NEW.email))
     OR EXISTS (SELECT 1 FROM commerce.store_members m WHERE m.store_id = NEW.store_id AND m.account_id = v_referrer.account_id) THEN
    RETURN NULL;
  END IF;
  INSERT INTO commerce.referrals (referrer_account_id, store_id, access_request_id, commission_bps, months)
  VALUES (v_referrer.account_id, NEW.store_id, NEW.id, v_program.commission_bps, v_program.months)
  ON CONFLICT (store_id) DO NOTHING;
  RETURN NULL;
END;
$$;


--
-- Name: accounts_house_members_gone(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.accounts_house_members_gone() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  DELETE FROM commerce.store_members m USING commerce.stores s
   WHERE m.account_id = OLD.id AND s.id = m.store_id AND s.house;
  RETURN OLD;
END;
$$;


--
-- Name: add_demo_appointment(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.add_demo_appointment(p_store uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_product uuid;
  v_variant uuid;
  v_staff uuid;
  v_location uuid;
  v_market record;
BEGIN
  SELECT id INTO v_product FROM commerce.products WHERE store_id = p_store AND handle = 'demo-massasje';
  IF FOUND THEN
    RETURN v_product;
  END IF;

  UPDATE commerce.stores
     SET modules = (SELECT array_agg(DISTINCT m ORDER BY m) FROM unnest(modules || array['bookings']) m)
   WHERE id = p_store;

  INSERT INTO commerce.booking_resources (store_id, kind, name, hours, capacity, position)
  VALUES (
    p_store, 'staff', 'Demo: Kari',
    '{"week": {"mon": {"open": "09:00", "close": "17:00"}, "tue": {"open": "09:00", "close": "17:00"}, "wed": {"open": "09:00", "close": "17:00"}, "thu": {"open": "09:00", "close": "17:00"}, "fri": {"open": "09:00", "close": "17:00"}, "sat": {"open": "10:00", "close": "14:00"}, "sun": null}, "exceptions": []}'::jsonb,
    1, 0
  )
  RETURNING id INTO v_staff;

  SELECT id INTO v_location FROM commerce.store_locations WHERE store_id = p_store ORDER BY position, created_at LIMIT 1;

  INSERT INTO commerce.products (store_id, handle, tax_code, kind, vat_category)
  VALUES (p_store, 'demo-massasje', 'txcd_20030000', 'appointment', 'standard')
  RETURNING id INTO v_product;

  INSERT INTO commerce.product_translations (store_id, product_id, locale, title, description) VALUES
    (p_store, v_product, 'nb-NO', 'Demo: Massasje, 60 minutter',
     'En time med avslappende massasje. Velg dag og tid, så står timen klar når du kommer.'),
    (p_store, v_product, 'sv-SE', 'Demo: Massage, 60 minuter',
     'En timme avslappnande massage. Välj dag och tid, så är tiden bokad när du kommer.'),
    (p_store, v_product, 'da-DK', 'Demo: Massage, 60 minutter',
     'En time med afslappende massage. Vælg dag og tid, så er tiden klar, når du kommer.');

  INSERT INTO commerce.product_media (store_id, product_id, url, position, alt) VALUES
    (p_store, v_product, '/demo/massage.svg', 0,
     '{"nb-NO": "Massasjesteiner", "sv-SE": "Massagestenar", "da-DK": "Massagesten"}');

  INSERT INTO commerce.product_variants (store_id, product_id, sku, options, delivery)
  VALUES (p_store, v_product, 'DEMO-MASSAGE-60', '{}', 'service')
  RETURNING id INTO v_variant;

  FOR v_market IN
    SELECT code FROM commerce.markets WHERE store_id = p_store AND code IN ('NO', 'SE', 'DK')
  LOOP
    PERFORM commerce.set_price(v_variant, v_market.code,
      CASE v_market.code WHEN 'DK' THEN 64900 ELSE 89000 END);
  END LOOP;

  INSERT INTO commerce.appointment_settings (
    product_id, store_id, duration_minutes, buffer_before_minutes, buffer_after_minutes, step_minutes,
    min_notice_minutes, max_days_ahead, location_id
  ) VALUES (v_product, p_store, 60, 0, 15, 30, 120, 60, v_location);

  INSERT INTO commerce.product_resources (store_id, product_id, resource_id) VALUES (p_store, v_product, v_staff);

  UPDATE commerce.products SET status = 'active' WHERE id = v_product;
  RETURN v_product;
END;
$$;


--
-- Name: add_demo_bundle(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.add_demo_bundle(p_store uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_product uuid;
  v_variant uuid;
  v_mug record;
  v_tote uuid;
BEGIN
  SELECT id INTO v_product FROM commerce.products WHERE store_id = p_store AND handle = 'demo-kaffepakke';
  IF FOUND THEN
    RETURN v_product;
  END IF;
  SELECT v.id, p.manufacturer_id, p.responsible_person_id, p.vat_category INTO v_mug
    FROM commerce.product_variants v JOIN commerce.products p ON p.store_id = v.store_id AND p.id = v.product_id
   WHERE v.store_id = p_store AND v.sku = 'DEMO-MUG-WHITE';
  SELECT v.id INTO v_tote FROM commerce.product_variants v
    JOIN commerce.products p ON p.store_id = v.store_id AND p.id = v.product_id
   WHERE v.store_id = p_store AND v.sku = 'DEMO-TOTE' AND p.vat_category = v_mug.vat_category;
  IF v_mug.id IS NULL OR v_tote IS NULL THEN
    RETURN NULL;
  END IF;

  INSERT INTO commerce.products (store_id, handle, manufacturer_id, responsible_person_id, tax_code, kind, vat_category, bundle_pricing, bundle_percent_off)
  VALUES (p_store, 'demo-kaffepakke', v_mug.manufacturer_id, v_mug.responsible_person_id, 'txcd_99999999', 'bundle', v_mug.vat_category, 'computed', 10)
  RETURNING id INTO v_product;

  INSERT INTO commerce.product_translations (store_id, product_id, locale, title, description) VALUES
    (p_store, v_product, 'nb-NO', 'Demo: Kaffepakke',
     'To hvite keramikkopper og et handlenett, solgt sammen. Pakken er på lager så lenge koppene og nettet er det, og prisen følger deres.'),
    (p_store, v_product, 'sv-SE', 'Demo: Kaffepaket',
     'Två vita keramikmuggar och en tygkasse, sålda tillsammans. Paketet finns i lager så länge muggarna och kassen gör det, och priset följer deras.'),
    (p_store, v_product, 'da-DK', 'Demo: Kaffepakke',
     'To hvide keramikkrus og en indkøbsnet, solgt sammen. Pakken er på lager, så længe krusene og nettet er det, og prisen følger deres.');

  INSERT INTO commerce.product_media (store_id, product_id, url, position, alt) VALUES
    (p_store, v_product, '/demo/bundle.svg', 0, '{"nb-NO": "To kopper og et handlenett", "sv-SE": "Två muggar och en tygkasse", "da-DK": "To krus og et indkøbsnet"}');

  INSERT INTO commerce.product_variants (store_id, product_id, sku, weight_grams)
  VALUES (p_store, v_product, 'DEMO-VERDIPAKKE', 900)
  RETURNING id INTO v_variant;

  -- The price is the database's, set at commit from the components (`refresh_bundle_prices()`).
  INSERT INTO commerce.bundle_components (store_id, bundle_variant_id, component_variant_id, quantity, position) VALUES
    (p_store, v_variant, v_mug.id, 2, 0),
    (p_store, v_variant, v_tote, 1, 1);

  UPDATE commerce.products SET status = 'active' WHERE id = v_product;
  RETURN v_product;
END;
$$;


--
-- Name: add_demo_gift_card(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.add_demo_gift_card(p_store uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_product uuid;
  v_variant uuid;
  v_market record;
  v_amount record;
BEGIN
  SELECT id INTO v_product FROM commerce.products WHERE store_id = p_store AND handle = 'demo-gavekort';
  IF FOUND THEN
    RETURN v_product;
  END IF;

  INSERT INTO commerce.products (store_id, handle, tax_code, kind, vat_category)
  VALUES (p_store, 'demo-gavekort', 'txcd_00000000', 'gift_card', 'voucher')
  RETURNING id INTO v_product;

  INSERT INTO commerce.product_translations (store_id, product_id, locale, title, description) VALUES
    (p_store, v_product, 'nb-NO', 'Demo: Gavekort',
     'Et gavekort som kan brukes på alt i butikken. Det sendes på e-post, til deg eller rett til den du gir det til, på dagen du velger.'),
    (p_store, v_product, 'sv-SE', 'Demo: Presentkort',
     'Ett presentkort som kan användas på allt i butiken. Det skickas med e-post, till dig eller direkt till den du ger det till, på dagen du väljer.'),
    (p_store, v_product, 'da-DK', 'Demo: Gavekort',
     'Et gavekort, der kan bruges på alt i butikken. Det sendes på e-mail, til dig eller direkte til den, du giver det til, på dagen du vælger.');

  INSERT INTO commerce.product_media (store_id, product_id, url, position, alt) VALUES
    (p_store, v_product, '/demo/gift-card.svg', 0, '{"nb-NO": "Gavekort", "sv-SE": "Presentkort", "da-DK": "Gavekort"}');

  FOR v_amount IN
    SELECT * FROM (VALUES ('DEMO-GAVEKORT-500', 'small', 50000, 37500), ('DEMO-GAVEKORT-1000', 'large', 100000, 75000)) AS a(sku, option, amount, amount_dk)
  LOOP
    INSERT INTO commerce.product_variants (store_id, product_id, sku, options, delivery)
    VALUES (p_store, v_product, v_amount.sku, jsonb_build_object('amount', v_amount.option), 'digital')
    RETURNING id INTO v_variant;
    FOR v_market IN
      SELECT code FROM commerce.markets WHERE store_id = p_store AND code IN ('NO', 'SE', 'DK')
    LOOP
      PERFORM commerce.set_price(v_variant, v_market.code, CASE v_market.code WHEN 'DK' THEN v_amount.amount_dk ELSE v_amount.amount END);
    END LOOP;
  END LOOP;

  UPDATE commerce.products SET status = 'active' WHERE id = v_product;
  RETURN v_product;
END;
$$;


--
-- Name: add_demo_rental(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.add_demo_rental(p_store uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_product uuid;
  v_variant uuid;
  v_resource uuid;
  v_location uuid;
  v_market record;
BEGIN
  SELECT id INTO v_product FROM commerce.products WHERE store_id = p_store AND handle = 'demo-sykkelutleie';
  IF FOUND THEN
    RETURN v_product;
  END IF;

  UPDATE commerce.stores
     SET modules = (SELECT array_agg(DISTINCT m ORDER BY m) FROM unnest(modules || array['bookings']) m)
   WHERE id = p_store;

  INSERT INTO commerce.booking_resources (store_id, kind, name, hours, capacity, position)
  VALUES (
    p_store, 'item', 'Demo: Elsykkel',
    '{"week": {"mon": {"open": "00:00", "close": "23:59"}, "tue": {"open": "00:00", "close": "23:59"}, "wed": {"open": "00:00", "close": "23:59"}, "thu": {"open": "00:00", "close": "23:59"}, "fri": {"open": "00:00", "close": "23:59"}, "sat": {"open": "00:00", "close": "23:59"}, "sun": {"open": "00:00", "close": "23:59"}}, "exceptions": []}'::jsonb,
    3, (SELECT coalesce(max(position), -1) + 1 FROM commerce.booking_resources WHERE store_id = p_store)
  )
  RETURNING id INTO v_resource;

  SELECT id INTO v_location FROM commerce.store_locations WHERE store_id = p_store ORDER BY position, created_at LIMIT 1;

  INSERT INTO commerce.products (store_id, handle, tax_code, kind, vat_category)
  VALUES (p_store, 'demo-sykkelutleie', 'txcd_20030000', 'rental', 'standard')
  RETURNING id INTO v_product;

  INSERT INTO commerce.product_translations (store_id, product_id, locale, title, description) VALUES
    (p_store, v_product, 'nb-NO', 'Demo: Leie av elsykkel',
     'Elsykkel med hjelm og lås. Hentes om morgenen og leveres før stengetid siste dag; prisen er per dag.'),
    (p_store, v_product, 'sv-SE', 'Demo: Hyr en elcykel',
     'Elcykel med hjälm och lås. Hämtas på morgonen och lämnas före stängning sista dagen; priset är per dag.'),
    (p_store, v_product, 'da-DK', 'Demo: Lej en elcykel',
     'Elcykel med hjelm og lås. Hentes om morgenen og afleveres før lukketid sidste dag; prisen er pr. dag.');

  INSERT INTO commerce.product_media (store_id, product_id, url, position, alt) VALUES
    (p_store, v_product, '/demo/bike.svg', 0, '{"nb-NO": "Elsykkel", "sv-SE": "Elcykel", "da-DK": "Elcykel"}');

  INSERT INTO commerce.product_variants (store_id, product_id, sku, options, delivery)
  VALUES (p_store, v_product, 'DEMO-SYKKEL', '{"rental": "day"}', 'service')
  RETURNING id INTO v_variant;

  FOR v_market IN
    SELECT code FROM commerce.markets WHERE store_id = p_store AND code IN ('NO', 'SE', 'DK')
  LOOP
    PERFORM commerce.set_price(v_variant, v_market.code,
      CASE v_market.code WHEN 'DK' THEN 32500 ELSE 45000 END);
  END LOOP;

  INSERT INTO commerce.appointment_settings (
    product_id, store_id, min_notice_minutes, max_days_ahead, location_id,
    check_in_time, check_out_time, min_nights, max_nights, payment, deposit_percent, cancel_hours
  ) VALUES (v_product, p_store, 60, 180, v_location, '09:00', '17:00', 1, 14, 'now', 30, 24);

  INSERT INTO commerce.product_resources (store_id, product_id, resource_id) VALUES (p_store, v_product, v_resource);

  PERFORM commerce.add_demo_rental_periods(p_store);

  UPDATE commerce.products SET status = 'active' WHERE id = v_product;
  RETURN v_product;
END;
$$;


--
-- Name: add_demo_rental_periods(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.add_demo_rental_periods(p_store uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_product uuid;
  v_variant uuid;
  v_market record;
  v_kind record;
BEGIN
  SELECT id INTO v_product FROM commerce.products WHERE store_id = p_store AND handle = 'demo-sykkelutleie';
  IF NOT FOUND THEN
    RETURN;
  END IF;
  UPDATE commerce.product_variants SET options = '{"rental": "day"}', rental_period = 'day'
   WHERE store_id = p_store AND product_id = v_product AND sku = 'DEMO-SYKKEL';

  FOR v_kind IN
    SELECT * FROM (VALUES
      ('DEMO-SYKKEL-HALV', 'halfDay', 'half_day', 30000, 21500),
      ('DEMO-SYKKEL-TIME', 'hour', 'hour', 12000, 8500)
    ) AS k(sku, option, period, amount, amount_dk)
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM commerce.product_variants WHERE store_id = p_store AND product_id = v_product AND sku = v_kind.sku
    ) THEN
      INSERT INTO commerce.product_variants (store_id, product_id, sku, options, delivery, rental_period)
      VALUES (p_store, v_product, v_kind.sku, jsonb_build_object('rental', v_kind.option), 'service', v_kind.period)
      RETURNING id INTO v_variant;
      FOR v_market IN
        SELECT code FROM commerce.markets WHERE store_id = p_store AND code IN ('NO', 'SE', 'DK')
      LOOP
        PERFORM commerce.set_price(v_variant, v_market.code,
          CASE v_market.code WHEN 'DK' THEN v_kind.amount_dk ELSE v_kind.amount END);
      END LOOP;
    END IF;
  END LOOP;

  UPDATE commerce.product_translations
     SET description = CASE locale
       WHEN 'nb-NO' THEN 'Elsykkel med hjelm og lås. Lei den en time, en halv dag eller hele dager; hentes fra 09:00 og leveres innen 17:00.'
       WHEN 'sv-SE' THEN 'Elcykel med hjälm och lås. Hyr den en timme, en halv dag eller hela dagar; hämtas från 09:00 och lämnas senast 17:00.'
       WHEN 'da-DK' THEN 'Elcykel med hjelm og lås. Lej den en time, en halv dag eller hele dage; hentes fra 09:00 og afleveres senest 17:00.'
       ELSE description END
   WHERE store_id = p_store AND product_id = v_product;
END;
$$;


