  RETURNING id INTO v_product;

  INSERT INTO commerce.product_translations (store_id, product_id, locale, title, description) VALUES
    (p_store, v_product, 'nb-NO', 'Demo: Hytte ved vannet',
     'En liten hytte for fire ved vannet, med vedovn og båt. Velg ankomst og avreise; prisen er per natt.'),
    (p_store, v_product, 'sv-SE', 'Demo: Stuga vid sjön',
     'En liten stuga för fyra vid sjön, med vedspis och båt. Välj ankomst och avresa; priset är per natt.'),
    (p_store, v_product, 'da-DK', 'Demo: Hytte ved søen',
     'En lille hytte til fire ved søen, med brændeovn og båd. Vælg ankomst og afrejse; prisen er pr. nat.');

  INSERT INTO commerce.product_media (store_id, product_id, url, position, alt) VALUES
    (p_store, v_product, '/demo/cabin.svg', 0, '{"nb-NO": "Hytte ved vannet", "sv-SE": "Stuga vid sjön", "da-DK": "Hytte ved søen"}');

  INSERT INTO commerce.product_variants (store_id, product_id, sku, options, delivery)
  VALUES (p_store, v_product, 'DEMO-HYTTE', '{}', 'service')
  RETURNING id INTO v_variant;

  FOR v_market IN
    SELECT code FROM commerce.markets WHERE store_id = p_store AND code IN ('NO', 'SE', 'DK')
  LOOP
    PERFORM commerce.set_price(v_variant, v_market.code,
      CASE v_market.code WHEN 'DK' THEN 105000 ELSE 145000 END);
  END LOOP;

  INSERT INTO commerce.appointment_settings (
    product_id, store_id, min_notice_minutes, max_days_ahead, location_id,
    check_in_time, check_out_time, min_nights, max_nights, payment, deposit_percent, cancel_hours
  ) VALUES (v_product, p_store, 0, 365, v_location, '15:00', '11:00', 2, 14, 'deposit', 30, 72);

  INSERT INTO commerce.product_resources (store_id, product_id, resource_id) VALUES (p_store, v_product, v_resource);

  PERFORM commerce.add_demo_stay_pricing(p_store);

  UPDATE commerce.products SET status = 'active' WHERE id = v_product;
  RETURN v_product;
END;
$$;


--
-- Name: add_demo_stay_pricing(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.add_demo_stay_pricing(p_store uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_product uuid;
BEGIN
  SELECT id INTO v_product FROM commerce.products WHERE store_id = p_store AND handle = 'demo-hytte';
  IF NOT FOUND THEN
    RETURN;
  END IF;
  UPDATE commerce.appointment_settings
     SET booking_fee = (
       SELECT coalesce(jsonb_object_agg(code, CASE code WHEN 'DK' THEN 37500 ELSE 50000 END), '{}'::jsonb)
         FROM commerce.markets WHERE store_id = p_store AND code IN ('NO', 'SE', 'DK')
     )
   WHERE store_id = p_store AND product_id = v_product AND booking_fee = '{}'::jsonb;
  IF NOT EXISTS (SELECT 1 FROM commerce.booking_seasons WHERE store_id = p_store AND product_id = v_product) THEN
    INSERT INTO commerce.booking_seasons (store_id, product_id, name, names, from_day, to_day, weekdays, percent, position) VALUES
      (p_store, v_product, 'Høysesong', '{"sv-SE": "Högsäsong", "da-DK": "Højsæson"}', '06-15', '08-15', '{1,2,3,4,5,6,7}', 30, 0),
      (p_store, v_product, 'Helg', '{"sv-SE": "Helg", "da-DK": "Weekend"}', NULL, NULL, '{5,6}', 20, 1);
  END IF;
  UPDATE commerce.product_translations
     SET description = CASE locale
       WHEN 'nb-NO' THEN 'En liten hytte for fire ved vannet, med vedovn og båt. Velg ankomst og avreise; prisen er per natt, høyere om sommeren og i helgene, med sluttrengjøring i tillegg.'
       WHEN 'sv-SE' THEN 'En liten stuga för fyra vid sjön, med vedspis och båt. Välj ankomst och avresa; priset är per natt, högre på sommaren och helger, med slutstädning utöver.'
       WHEN 'da-DK' THEN 'En lille hytte til fire ved søen, med brændeovn og båd. Vælg ankomst og afrejse; prisen er pr. nat, højere om sommeren og i weekender, med slutrengøring oveni.'
       ELSE description END
   WHERE store_id = p_store AND product_id = v_product;
END;
$$;


--
-- Name: adopt_sandbox(uuid, text, text, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.adopt_sandbox(p_request_id uuid, p_slug text, p_store_name text, p_decided_by uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_request commerce.access_requests%ROWTYPE;
  v_sandbox commerce.sandboxes%ROWTYPE;
  v_account uuid;
  v_disabled timestamptz;
BEGIN
  SELECT * INTO v_request FROM commerce.access_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown access request %', p_request_id;
  END IF;
  IF v_request.status <> 'pending' THEN
    RAISE EXCEPTION 'the access request is already %', v_request.status USING ERRCODE = 'check_violation';
  END IF;
  IF v_request.sandbox_id IS NULL THEN
    RAISE EXCEPTION 'sandboxes.not_named: the request names no sandbox' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO v_sandbox FROM commerce.sandboxes WHERE id = v_request.sandbox_id FOR UPDATE;
  IF v_sandbox.state <> 'open' OR v_sandbox.expires_at <= now() THEN
    RAISE EXCEPTION 'sandboxes.not_open: the sandbox has ended' USING ERRCODE = 'check_violation';
  END IF;

  INSERT INTO commerce.accounts (email, name)
  VALUES (v_request.email, v_request.name)
  ON CONFLICT ((lower(email))) DO UPDATE
    SET name = coalesce(commerce.accounts.name, excluded.name)
  RETURNING id, disabled_at INTO v_account, v_disabled;
  IF v_disabled IS NOT NULL THEN
    RAISE EXCEPTION 'the account for % is disabled', v_request.email USING ERRCODE = 'check_violation';
  END IF;

  PERFORM set_config('commerce.sandbox_change', v_sandbox.store_id::text, true);
  UPDATE commerce.stores
     SET sandbox = false, slug = p_slug, name = p_store_name, created_by = v_account
   WHERE id = v_sandbox.store_id AND sandbox;
  PERFORM set_config('commerce.sandbox_change', '', true);

  UPDATE commerce.store_members
     SET account_id = v_account
   WHERE store_id = v_sandbox.store_id AND account_id = commerce.sandbox_account();

  DELETE FROM commerce.limit_overrides
   WHERE store_id = v_sandbox.store_id AND reason = 'Sandbox allowance (D457)';

  -- A priced theme live in it is owed, as on any store that has not opened (D286): a sandbox itself never owes one
  -- (`theme_installs_charge()`), so keeping it cannot give a premium theme away.
  INSERT INTO commerce.theme_purchases (store_id, preset_id, status, currency, amount_minor, chosen_by)
  SELECT i.store_id, i.preset_id, 'owed', pr.currency, pr.amount_minor, v_account
    FROM commerce.store_theme_installs i
   CROSS JOIN LATERAL commerce.theme_price_for(i.store_id, i.preset_id) pr
   WHERE i.store_id = v_sandbox.store_id AND i.live AND i.preset_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1 FROM commerce.theme_purchases p
        WHERE p.store_id = i.store_id AND p.preset_id = i.preset_id AND p.status IN ('owed', 'due', 'invoiced', 'paid', 'granted')
     );

  UPDATE commerce.sandboxes SET state = 'kept', ended_at = now() WHERE id = v_sandbox.id;

  UPDATE commerce.access_requests
     SET status = 'approved', decided_by = p_decided_by, decided_at = now(), store_id = v_sandbox.store_id
   WHERE id = p_request_id;

  INSERT INTO commerce.audit_log (store_id, account_id, action, details)
  VALUES (v_sandbox.store_id, p_decided_by, 'platform.access_approved',
          jsonb_build_object('email', v_request.email, 'slug', p_slug, 'sandbox', v_sandbox.id));

  RETURN v_sandbox.store_id;
END;
$$;


--
-- Name: affiliate_attribute_order(uuid, text, bigint); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.affiliate_attribute_order(p_order uuid, p_code text, p_discount bigint) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_o commerce.orders%ROWTYPE;
  v_r record;
BEGIN
  SELECT * INTO v_o FROM commerce.orders o WHERE o.id = p_order;
  IF NOT FOUND OR v_o.customer_id IS NULL OR v_o.copied_from IS NOT NULL OR v_o.host_id IS NOT NULL OR v_o.source = 'exchange' THEN
    RETURN 'none';
  END IF;
  SELECT * INTO v_r FROM commerce.affiliate_resolve(v_o.store_id, v_o.customer_id, p_code, p_order);
  IF v_r.verdict NOT IN ('ok', 'self', 'blocked', 'not_new') THEN
    RETURN v_r.verdict;
  END IF;
  INSERT INTO commerce.affiliate_attributions (
    store_id, order_id, affiliate_customer_id, friend_customer_id, code, discount_minor, status, reject_reason
  ) VALUES (
    v_o.store_id, p_order, v_r.affiliate_customer_id, v_o.customer_id, v_r.code,
    CASE WHEN v_r.verdict = 'ok' THEN greatest(coalesce(p_discount, 0), 0) ELSE 0 END,
    CASE WHEN v_r.verdict = 'ok' THEN 'pending' ELSE 'rejected' END,
    CASE WHEN v_r.verdict = 'ok' THEN NULL ELSE v_r.verdict END
  )
  ON CONFLICT (store_id, order_id) DO NOTHING;
  RETURN v_r.verdict;
END;
$$;


--
-- Name: affiliate_attributions_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.affiliate_attributions_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_o commerce.orders%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    -- Only with what it belongs to: the order, or the referrer's own account (cascades).
    IF NOT EXISTS (SELECT 1 FROM commerce.orders o WHERE o.store_id = OLD.store_id AND o.id = OLD.order_id)
       OR NOT EXISTS (SELECT 1 FROM commerce.affiliates a
                       WHERE a.store_id = OLD.store_id AND a.customer_id = OLD.affiliate_customer_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'commerce.affiliate_attributions is append-only; DELETE is not allowed' USING ERRCODE = 'restrict_violation';
  END IF;

  IF TG_OP = 'INSERT' THEN
    SELECT * INTO v_o FROM commerce.orders o WHERE o.store_id = NEW.store_id AND o.id = NEW.order_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'affiliate.no_order' USING ERRCODE = 'check_violation';
    END IF;
    -- A copied order is history (D129) and a host's order is the host's (D71): neither is attributed.
    IF v_o.copied_from IS NOT NULL OR v_o.host_id IS NOT NULL THEN
      RAISE EXCEPTION 'affiliate.not_attributable' USING ERRCODE = 'check_violation';
    END IF;
    IF v_o.customer_id IS DISTINCT FROM NEW.friend_customer_id THEN
      RAISE EXCEPTION 'affiliate.wrong_friend' USING ERRCODE = 'check_violation';
    END IF;
    -- The friend is never the affiliate: such an attribution can only be a rejected one.
    IF NEW.friend_customer_id = NEW.affiliate_customer_id AND (NEW.status <> 'rejected' OR NEW.reject_reason IS DISTINCT FROM 'self') THEN
      RAISE EXCEPTION 'affiliate.self' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status IN ('pending', 'rejected') AND NEW.reward_minor <> 0 THEN
      RAISE EXCEPTION 'affiliate.bad_reward' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE: who, where and what the friend got never change; the status only moves forward; a reward once given is
  -- not edited (taking it back is the ledger's).
  IF NEW.store_id <> OLD.store_id OR NEW.order_id <> OLD.order_id OR NEW.affiliate_customer_id <> OLD.affiliate_customer_id
     OR NEW.code <> OLD.code OR NEW.discount_minor IS DISTINCT FROM OLD.discount_minor OR NEW.created_at <> OLD.created_at
     OR (NEW.friend_customer_id IS DISTINCT FROM OLD.friend_customer_id AND NEW.friend_customer_id IS NOT NULL) THEN
    RAISE EXCEPTION 'commerce.affiliate_attributions is append-only; its order, people and discount do not change' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.status IN ('rejected', 'reversed') AND (NEW.status <> OLD.status OR NEW.reward_minor <> OLD.reward_minor) THEN
    RAISE EXCEPTION 'affiliate.settled' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.status = 'rewarded' AND (NEW.status NOT IN ('rewarded', 'reversed') OR NEW.reward_minor <> OLD.reward_minor) THEN
    RAISE EXCEPTION 'affiliate.settled' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: affiliate_count_visit(uuid, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.affiliate_count_visit(p_store uuid, p_code text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT (
       (commerce.affiliate_program_on(p_store)
        AND EXISTS (SELECT 1 FROM commerce.affiliates a WHERE a.store_id = p_store AND a.code = p_code AND a.blocked_at IS NULL))
    OR (commerce.creator_program_on(p_store)
        AND EXISTS (SELECT 1 FROM commerce.creators c WHERE c.store_id = p_store AND c.code = p_code AND c.status = 'approved'))
  ) THEN
    RETURN false;
  END IF;
  INSERT INTO commerce.referral_visits (store_id, code, day, visits)
  VALUES (p_store, p_code, (now() AT TIME ZONE 'UTC')::date, 1)
  ON CONFLICT (coalesce(store_id, '00000000-0000-0000-0000-000000000000'::uuid), code, day)
  DO UPDATE SET visits = commerce.referral_visits.visits + 1
    -- A ceiling for the day, so a code opened by a script cannot grow a counter without end (the row is one per day and code).
    WHERE commerce.referral_visits.visits < 100000;
  RETURN true;
END;
$$;


--
-- Name: affiliate_has_paid(uuid, uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.affiliate_has_paid(p_store uuid, p_customer uuid, p_except uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM commerce.orders o
      LEFT JOIN commerce.customers c ON c.store_id = p_store AND c.id = p_customer
     WHERE o.store_id = p_store AND o.id IS DISTINCT FROM p_except
       AND (o.customer_id = p_customer OR (o.email <> '' AND lower(o.email) = lower(c.email)))
       AND (o.status IN ('paid', 'fulfilled', 'closed')
            OR EXISTS (SELECT 1 FROM commerce.order_events e WHERE e.store_id = o.store_id AND e.order_id = o.id AND e.type = 'order.paid'))
  )
$$;


--
-- Name: affiliate_lock(uuid, uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.affiliate_lock(p_store uuid, p_a uuid, p_b uuid) RETURNS void
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  SELECT 1 FROM commerce.customers c WHERE c.store_id = p_store AND c.id IN (p_a, p_b) ORDER BY c.id FOR UPDATE
$$;


--
-- Name: affiliate_order_paid(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.affiliate_order_paid(p_order uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_o commerce.orders%ROWTYPE;
  v_a commerce.affiliate_attributions%ROWTYPE;
  v_s commerce.affiliate_settings%ROWTYPE;
  v_b commerce.bonus_settings%ROWTYPE;
  v_aff_email text;
  v_friend commerce.customers%ROWTYPE;
  v_reason text;
  v_base bigint;
  v_reward bigint;
  v_credits bigint;
  v_used bigint;
  v_from timestamptz;
  v_tz text;
  v_at timestamptz;
BEGIN
  SELECT * INTO v_o FROM commerce.orders o WHERE o.id = p_order;
  IF NOT FOUND OR v_o.copied_from IS NOT NULL OR v_o.host_id IS NOT NULL THEN
    RETURN;
  END IF;
  SELECT * INTO v_a FROM commerce.affiliate_attributions a WHERE a.store_id = v_o.store_id AND a.order_id = p_order;
  IF NOT FOUND OR v_a.status <> 'pending' THEN
    RETURN;
  END IF;
  PERFORM commerce.affiliate_lock(v_o.store_id, v_a.affiliate_customer_id, v_a.friend_customer_id);
  SELECT * INTO v_a FROM commerce.affiliate_attributions a WHERE a.id = v_a.id FOR UPDATE;
  IF v_a.status <> 'pending' THEN
    RETURN;
  END IF;

  SELECT * INTO v_s FROM commerce.affiliate_settings s WHERE s.store_id = v_o.store_id;
  SELECT * INTO v_b FROM commerce.bonus_settings b WHERE b.store_id = v_o.store_id;
  SELECT lower(c.email) INTO v_aff_email FROM commerce.customers c
   WHERE c.store_id = v_o.store_id AND c.id = v_a.affiliate_customer_id;
  SELECT * INTO v_friend FROM commerce.customers c WHERE c.store_id = v_o.store_id AND c.id = v_a.friend_customer_id;

  -- No 'off' here (D178): the order was attributed while the program was on, so its reward is granted when it is due even if the
  -- program, or the bonus program, has been switched off since. Orders placed while it is off are never attributed.
  IF v_friend.id IS NULL THEN
    v_reason := 'not_new';
  ELSIF v_friend.id = v_a.affiliate_customer_id OR lower(v_friend.email) = v_aff_email OR lower(v_o.email) = v_aff_email THEN
    v_reason := 'self';
  ELSIF EXISTS (SELECT 1 FROM commerce.affiliates a
                 WHERE a.store_id = v_o.store_id AND a.customer_id = v_a.affiliate_customer_id AND a.blocked_at IS NOT NULL) THEN
    v_reason := 'blocked';
  ELSIF commerce.affiliate_has_paid(v_o.store_id, v_friend.id, p_order)
        AND v_friend.referred_by_customer_id IS DISTINCT FROM v_a.affiliate_customer_id THEN
    v_reason := 'not_new';
  ELSIF v_s.reward_orders IS NOT NULL AND (
          SELECT count(*) FROM commerce.affiliate_attributions x
           WHERE x.store_id = v_o.store_id AND x.friend_customer_id = v_friend.id
             AND x.affiliate_customer_id = v_a.affiliate_customer_id AND x.status = 'rewarded' AND x.order_id <> p_order
        ) >= v_s.reward_orders THEN
    v_reason := 'limit';
  END IF;

  IF v_reason IS NULL THEN
    SELECT coalesce(sum(ol.total_minor - ol.venue_minor), 0) INTO v_base
      FROM commerce.order_lines ol WHERE ol.store_id = v_o.store_id AND ol.order_id = p_order
       AND NOT EXISTS (SELECT 1 FROM commerce.order_payment_terms t WHERE t.store_id = v_o.store_id AND t.order_id = p_order);
    v_reward := floor(v_base::numeric * v_s.reward_bps / 10000)::bigint;
    v_credits := CASE WHEN v_reward > 0 THEN commerce.bonus_convert(v_o.store_id, v_reward, v_o.currency, v_b.currency) END;
    IF v_credits IS NULL OR v_credits <= 0 THEN
      v_reason := 'zero';
    ELSIF v_s.monthly_cap_minor IS NOT NULL THEN
      -- A calendar month in the store's time zone; what the referrer has been rewarded in it (and not had taken back).
      SELECT coalesce((SELECT st.time_zone FROM commerce.stores st WHERE st.id = v_o.store_id), 'UTC') INTO v_tz;
      v_from := timezone(v_tz, date_trunc('month', timezone(v_tz, now())));
      SELECT coalesce(sum(x.reward_minor), 0) INTO v_used FROM commerce.affiliate_attributions x
       WHERE x.store_id = v_o.store_id AND x.affiliate_customer_id = v_a.affiliate_customer_id
         AND x.status = 'rewarded' AND x.rewarded_at >= v_from;
      v_credits := least(v_credits, greatest(v_s.monthly_cap_minor - v_used, 0));
      IF v_credits <= 0 THEN
        v_reason := 'cap';
      END IF;
    END IF;
  END IF;

  IF v_reason IS NOT NULL THEN
    UPDATE commerce.affiliate_attributions SET status = 'rejected', reject_reason = v_reason WHERE id = v_a.id;
    RETURN;
  END IF;

  v_at := now() + make_interval(days => v_b.pending_days);
  PERFORM commerce.bonus_grant(v_o.store_id, v_a.affiliate_customer_id, 'referral', v_credits, NULL, NULL, v_at,
                               commerce.bonus_expiry_from(v_o.store_id, v_at), '', NULL, 'referral:' || p_order);
  UPDATE commerce.affiliate_attributions SET status = 'rewarded', reward_minor = v_credits, rewarded_at = now() WHERE id = v_a.id;
  -- From now on the friend is the referrer's: their next orders earn too, as far as the store allows.
  UPDATE commerce.customers SET referred_by_customer_id = v_a.affiliate_customer_id
   WHERE store_id = v_o.store_id AND id = v_friend.id AND referred_by_customer_id IS NULL;
END;
$$;


--
-- Name: affiliate_order_paid_cancelled(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.affiliate_order_paid_cancelled(p_order uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_o commerce.orders%ROWTYPE;
  v_a commerce.affiliate_attributions%ROWTYPE;
  v_lot uuid;
  v_left bigint;
BEGIN
  SELECT * INTO v_o FROM commerce.orders o WHERE o.id = p_order;
  IF NOT FOUND THEN
    RETURN;
  END IF;
  SELECT * INTO v_a FROM commerce.affiliate_attributions a WHERE a.store_id = v_o.store_id AND a.order_id = p_order;
  IF NOT FOUND OR v_a.status <> 'rewarded' THEN
    RETURN;
  END IF;
  PERFORM commerce.affiliate_lock(v_o.store_id, v_a.affiliate_customer_id, v_a.friend_customer_id);
  SELECT e.id INTO v_lot FROM commerce.bonus_entries e
   WHERE e.store_id = v_o.store_id AND e.idempotency_key = 'referral:' || p_order;
  IF v_lot IS NOT NULL THEN
    SELECT l.remaining INTO v_left FROM commerce.bonus_lots(v_o.store_id, v_a.affiliate_customer_id) l WHERE l.id = v_lot;
    PERFORM commerce.bonus_take(v_o.store_id, v_a.affiliate_customer_id, 'reverse', coalesce(v_left, 0), 'lot', v_lot, NULL, NULL,
                                'the friend''s order was cancelled', NULL, 'referral-reverse-cancel:' || p_order);
  END IF;
  UPDATE commerce.affiliate_attributions SET status = 'reversed' WHERE id = v_a.id;
END;
$$;


--
-- Name: affiliate_program_on(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.affiliate_program_on(p_store uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT commerce.feature_on(p_store, 'referrals')
     AND coalesce((SELECT s.enabled FROM commerce.affiliate_settings s WHERE s.store_id = p_store), false)
     AND commerce.bonus_program_on(p_store)
$$;


--
-- Name: affiliate_refund_applied(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.affiliate_refund_applied(p_refund uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_r commerce.refunds%ROWTYPE;
  v_o commerce.orders%ROWTYPE;
  v_a commerce.affiliate_attributions%ROWTYPE;
  v_paid bigint;
  v_refunded bigint;
  v_lot uuid;
  v_granted bigint;
  v_target bigint;
  v_done bigint;
BEGIN
  SELECT * INTO v_r FROM commerce.refunds r WHERE r.id = p_refund;
  IF NOT FOUND OR v_r.status = 'failed' THEN
    RETURN;
  END IF;
  SELECT o.* INTO v_o FROM commerce.orders o
    JOIN commerce.payments p ON p.store_id = o.store_id AND p.order_id = o.id
   WHERE p.store_id = v_r.store_id AND p.id = v_r.payment_id;
  IF NOT FOUND OR v_o.copied_from IS NOT NULL THEN
    RETURN;
  END IF;
  SELECT * INTO v_a FROM commerce.affiliate_attributions a WHERE a.store_id = v_o.store_id AND a.order_id = v_o.id;
  IF NOT FOUND OR v_a.status <> 'rewarded' THEN
    RETURN;
  END IF;
  -- A change's payment that was never applied with it (D174: it came too late and is given back in full) is not the order's money.
  IF NOT commerce.payment_of_order(v_r.store_id, v_r.payment_id) THEN
    RETURN;
  END IF;
  SELECT coalesce(sum(p.amount_minor), 0) INTO v_paid FROM commerce.payments p
   WHERE p.store_id = v_o.store_id AND p.order_id = v_o.id AND p.status = 'captured' AND p.provider IN ('stripe', 'exchange', 'gift_card') /* D239 exchange base, D300 gift cards */
     AND commerce.payment_of_order(p.store_id, p.id);
  SELECT coalesce(sum(r.amount_minor), 0) INTO v_refunded FROM commerce.refunds r
    JOIN commerce.payments p ON p.store_id = r.store_id AND p.id = r.payment_id
   WHERE p.store_id = v_o.store_id AND p.order_id = v_o.id AND r.status <> 'failed'
     AND commerce.payment_of_order(p.store_id, p.id);
  IF v_paid <= 0 THEN
    RETURN;
  END IF;
  PERFORM commerce.affiliate_lock(v_o.store_id, v_a.affiliate_customer_id, v_a.friend_customer_id);
  SELECT e.id, e.amount_minor INTO v_lot, v_granted FROM commerce.bonus_entries e
   WHERE e.store_id = v_o.store_id AND e.idempotency_key = 'referral:' || v_o.id;
  IF v_lot IS NOT NULL THEN
    v_target := CASE WHEN v_refunded >= v_paid THEN v_granted ELSE floor(v_granted::numeric * v_refunded / v_paid)::bigint END;
    -- What was taken back from this lot so far (its other allocations are uses and expiry, which stay).
    SELECT coalesce(sum(al.amount_minor), 0) INTO v_done
      FROM commerce.bonus_allocations al JOIN commerce.bonus_entries e ON e.store_id = al.store_id AND e.id = al.entry_id
     WHERE al.store_id = v_o.store_id AND al.lot_id = v_lot AND e.kind = 'reverse';
    PERFORM commerce.bonus_take(v_o.store_id, v_a.affiliate_customer_id, 'reverse', v_target - v_done, 'lot', v_lot, NULL, p_refund,
                                'the friend''s order was refunded', NULL, 'referral-reverse:' || p_refund);
  END IF;
  IF v_refunded >= v_paid THEN
    UPDATE commerce.affiliate_attributions SET status = 'reversed' WHERE id = v_a.id;
  END IF;
END;
$$;


--
-- Name: affiliate_resolve(uuid, uuid, text, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.affiliate_resolve(p_store uuid, p_customer uuid, p_code text, p_except uuid DEFAULT NULL::uuid) RETURNS TABLE(affiliate_customer_id uuid, code text, verdict text, welcome boolean)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_s commerce.affiliate_settings%ROWTYPE;
  v_aff commerce.affiliates%ROWTYPE;
  v_c commerce.customers%ROWTYPE;
  v_ref uuid;
  v_first boolean := true;
  v_email text;
BEGIN
  IF NOT commerce.affiliate_program_on(p_store) THEN
    RETURN QUERY SELECT NULL::uuid, NULL::text, 'off'::text, false;
    RETURN;
  END IF;
  SELECT * INTO v_s FROM commerce.affiliate_settings s WHERE s.store_id = p_store;
  IF p_customer IS NOT NULL THEN
    SELECT * INTO v_c FROM commerce.customers c WHERE c.store_id = p_store AND c.id = p_customer;
    v_ref := v_c.referred_by_customer_id;
    v_first := NOT commerce.affiliate_has_paid(p_store, p_customer, p_except);
  END IF;
  IF p_code IS NOT NULL AND (p_customer IS NULL OR v_first OR v_ref IS NULL) THEN
    SELECT * INTO v_aff FROM commerce.affiliates a WHERE a.store_id = p_store AND a.code = p_code;
  END IF;
  IF v_aff.customer_id IS NULL AND v_ref IS NOT NULL THEN
    SELECT * INTO v_aff FROM commerce.affiliates a WHERE a.store_id = p_store AND a.customer_id = v_ref;
  END IF;
  IF v_aff.customer_id IS NULL THEN
    RETURN QUERY SELECT NULL::uuid, NULL::text, 'none'::text, false;
    RETURN;
  END IF;
  IF p_customer IS NULL THEN
    RETURN QUERY SELECT v_aff.customer_id, v_aff.code, 'guest'::text, false;
    RETURN;
  END IF;
  SELECT lower(c.email) INTO v_email FROM commerce.customers c WHERE c.store_id = p_store AND c.id = v_aff.customer_id;
  IF v_aff.customer_id = p_customer OR v_email = lower(v_c.email) THEN
    RETURN QUERY SELECT v_aff.customer_id, v_aff.code, 'self'::text, false;
    RETURN;
  END IF;
  IF v_aff.blocked_at IS NOT NULL THEN
    RETURN QUERY SELECT v_aff.customer_id, v_aff.code, 'blocked'::text, false;
    RETURN;
  END IF;
  IF NOT v_first THEN
    IF v_aff.customer_id IS DISTINCT FROM v_ref THEN
      RETURN QUERY SELECT v_aff.customer_id, v_aff.code, 'not_new'::text, false;
      RETURN;
    END IF;
    IF v_s.reward_orders IS NOT NULL AND (
         SELECT count(*) FROM commerce.affiliate_attributions x
          WHERE x.store_id = p_store AND x.friend_customer_id = p_customer AND x.affiliate_customer_id = v_aff.customer_id
            AND x.status = 'rewarded' AND x.order_id IS DISTINCT FROM p_except) >= v_s.reward_orders THEN
      RETURN QUERY SELECT v_aff.customer_id, v_aff.code, 'limit'::text, false;
      RETURN;
    END IF;
  END IF;
  RETURN QUERY SELECT v_aff.customer_id, v_aff.code, 'ok'::text, v_first;
END;
$$;


--
-- Name: analytics_targets_forms(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.analytics_targets_forms() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.starts_on IS NULL AND NEW.month IS NOT NULL THEN
    NEW.metric := 'net_sales';
    NEW.period := 'month';
    NEW.starts_on := NEW.month;
    NEW.ends_on := (NEW.month + interval '1 month - 1 day')::date;
    NEW.target_value := NEW.revenue_target_minor;
  ELSIF NEW.month IS NOT NULL AND NEW.revenue_target_minor IS NOT NULL AND NEW.target_value IS DISTINCT FROM NEW.revenue_target_minor
    AND NEW.starts_on = NEW.month AND TG_OP = 'UPDATE' AND NEW.revenue_target_minor IS DISTINCT FROM OLD.revenue_target_minor THEN
    -- The first form's upsert changes the amount only.
    NEW.target_value := NEW.revenue_target_minor;
  END IF;
  IF NEW.metric = 'net_sales' AND NEW.period = 'month' THEN
    NEW.month := NEW.starts_on;
    NEW.revenue_target_minor := NEW.target_value;
  ELSE
    NEW.month := NULL;
    NEW.revenue_target_minor := NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: anonymise_expired_documents(uuid, date); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.anonymise_expired_documents(p_store uuid, p_before date) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_n integer := 0;
  v_m integer;
BEGIN
  IF p_before IS NULL OR p_before > (current_date - interval '5 years')::date THEN
    RAISE EXCEPTION 'document.cutoff_too_young: documents are kept at least five years, so the cutoff cannot be after %', (current_date - interval '5 years')::date
      USING ERRCODE = 'check_violation';
  END IF;
  PERFORM set_config('commerce.anonymising', 'on', true);
  INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
  SELECT i.store_id, i.order_id, 'document.anonymised', jsonb_build_object('document', i.document_number), 'system'
    FROM commerce.invoices i WHERE i.store_id = p_store AND i.issued_on < p_before AND i.anonymised_at IS NULL;
  UPDATE commerce.invoices SET snapshot = commerce.anonymised_snapshot(snapshot), anonymised_at = now(), public_token = NULL, pdf_path = NULL, pdf_sha256 = NULL
   WHERE store_id = p_store AND issued_on < p_before AND anonymised_at IS NULL;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
  SELECT c.store_id, i.order_id, 'document.anonymised', jsonb_build_object('document', c.document_number), 'system'
    FROM commerce.credit_notes c JOIN commerce.invoices i ON i.store_id = c.store_id AND i.id = c.invoice_id
   WHERE c.store_id = p_store AND c.issued_on < p_before AND c.anonymised_at IS NULL;
  UPDATE commerce.credit_notes SET snapshot = commerce.anonymised_snapshot(snapshot), anonymised_at = now(), public_token = NULL, pdf_path = NULL, pdf_sha256 = NULL
   WHERE store_id = p_store AND issued_on < p_before AND anonymised_at IS NULL;
  GET DIAGNOSTICS v_m = ROW_COUNT;
  PERFORM set_config('commerce.anonymising', '', true);
  RETURN v_n + v_m;
END;
$$;


--
-- Name: anonymise_expired_orders(uuid, date, integer); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.anonymise_expired_orders(p_store uuid, p_today date, p_limit integer DEFAULT 5000) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  r record;
  v_n integer := 0;
  v_real date;
  v_country char(2);
  v_years integer;
  v_cutoff timestamp;
BEGIN
  v_real := commerce.store_day(p_store, now());
  IF p_today IS NULL OR p_today > v_real THEN
    RAISE EXCEPTION 'anonymise_today: the schedule is run for the store''s own day or an earlier one, not %', p_today USING ERRCODE = 'check_violation';
  END IF;
  -- A sale of year Y goes on 1 January of Y + years + 1, so nothing placed on or after 1 January of (this year - years) can be due: the shortest of the
  -- store's own periods (a host's order has its own, longer one; never under five years) bounds the candidates, with a day's margin for the store's time zone.
  SELECT s.country INTO v_country FROM commerce.stores s WHERE s.id = p_store;
  SELECT least(
           (SELECT greatest(ceil(CASE WHEN x.period_unit = 'months' THEN x.period_value / 12.0 ELSE x.period_value / 365.0 END)::integer, 5)
              FROM commerce.retention_rule('bookkeeping', v_country, p_today) x),
           (SELECT greatest(ceil(CASE WHEN x.period_unit = 'months' THEN x.period_value / 12.0 ELSE x.period_value / 365.0 END)::integer, 5)
              FROM commerce.retention_rule('host_bookkeeping', v_country, p_today) x)
         ) INTO v_years;
  v_cutoff := make_timestamp(extract(year FROM p_today)::integer - v_years, 1, 1, 0, 0, 0) + interval '1 day';
  -- The candidates are read in order into a set first and the (dearer) due-day function is asked of them one by one until the limit is
  -- reached, so a store with a hundred thousand old orders is not asked about all of them every day.
  FOR r IN
    WITH cand AS MATERIALIZED (
      SELECT o.id, o.placed_at FROM commerce.orders o
       WHERE o.store_id = p_store AND o.anonymised_at IS NULL
         AND (o.status IN ('pending_payment', 'cancelled') OR o.placed_at < v_cutoff)
       ORDER BY o.placed_at, o.id
    )
    SELECT c.id FROM cand c
     WHERE commerce.order_anonymisable_on(c.id) <= p_today
     LIMIT greatest(p_limit, 1)
  LOOP
    IF commerce.anonymise_order(p_store, r.id, 'retention') = 'anonymised' THEN v_n := v_n + 1; END IF;
  END LOOP;
  RETURN v_n;
END;
$$;


--
-- Name: anonymise_order(uuid, uuid, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.anonymise_order(p_store uuid, p_order uuid, p_mode text) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  o commerce.orders%ROWTYPE;
  v_class text;
  v_due date;
  v_today date;
BEGIN
  IF p_mode NOT IN ('erasure', 'retention') THEN
    RAISE EXCEPTION 'anonymise_mode: the mode is erasure or retention' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO o FROM commerce.orders x WHERE x.id = p_order AND x.store_id = p_store FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'anonymise_order: no such order in this store' USING ERRCODE = 'no_data_found';
  END IF;
  IF o.anonymised_at IS NOT NULL THEN RETURN 'already'; END IF;
  v_class := commerce.order_class(p_order);
  v_today := commerce.store_day(p_store, now());
  v_due := commerce.order_anonymisable_on(p_order);

  IF p_mode = 'retention' THEN
    IF v_due > v_today THEN
      RAISE EXCEPTION 'anonymise_not_due: the order is kept until %', v_due USING ERRCODE = 'check_violation';
    END IF;
  ELSIF v_class = 'sale' AND v_due > v_today THEN
    -- A sale the bookkeeping duty keeps: restricted, not anonymised.
    IF o.restricted_at IS NOT NULL THEN RETURN 'already'; END IF;
    UPDATE commerce.orders SET restricted_at = now(), customer_id = NULL WHERE id = p_order;
    INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
    VALUES (p_store, p_order, 'order.restricted', jsonb_build_object('until', v_due), 'system');
    RETURN 'restricted';
  END IF;

  PERFORM set_config('commerce.anonymising', 'on', true);
  UPDATE commerce.orders SET
    email = '[removed]',
    billing_address = '{}'::jsonb,
    shipping_address = '{}'::jsonb,
    company_name = NULL,
    organisation_number = NULL,
    is_gift = false,
    gift_to = NULL,
    gift_from = NULL,
    gift_message = NULL,
    customer_id = NULL,
    -- The buyer's VAT number and what VIES answered about them; the kind, reason, relief and seller's side stay.
    vat_treatment = CASE WHEN vat_treatment IS NULL THEN NULL ELSE
      jsonb_set(jsonb_set(jsonb_set(vat_treatment, '{buyerVatNumber}', 'null'::jsonb, false),
                          '{vies,registeredName}', 'null'::jsonb, false),
                '{vies,registeredAddress}', 'null'::jsonb, false) END,
    -- The postal code the delivery was priced for is the delivery address's: the service and its price stay.
    delivery = CASE WHEN delivery IS NULL THEN NULL ELSE delivery - 'postalCode' END,
    -- The note for the driver of a local delivery (D237) is the buyer's own words.
    delivery_note = NULL,
    -- The answers to the store's checkout fields (D357) are the buyer's own words.
    checkout_answers = NULL,
    anonymised_at = now()
   WHERE id = p_order;
  UPDATE commerce.withdrawal_requests SET name = '[removed]', email = '[removed]'
   WHERE store_id = p_store AND order_id = p_order AND (name <> '[removed]' OR email <> '[removed]');
  UPDATE commerce.returns SET
    reason_note = CASE WHEN coalesce(reason_note, '') = '' THEN reason_note ELSE '[removed]' END,
    decision_note = CASE WHEN coalesce(decision_note, '') = '' THEN decision_note ELSE '[removed]' END,
    staff_note = CASE WHEN coalesce(staff_note, '') = '' THEN staff_note ELSE '[removed]' END,
    refund_note = CASE WHEN coalesce(refund_note, '') = '' THEN refund_note ELSE '[removed]' END,
    label_url = NULL,
    exchange_wish_note = CASE WHEN coalesce(exchange_wish_note, '') = '' THEN exchange_wish_note ELSE '[removed]' END
   WHERE store_id = p_store AND order_id = p_order;
  -- Exchanges (D239): the new order's delivery address, kept on the exchange of either order.
  UPDATE commerce.return_exchanges SET delivery_address = '{}'::jsonb
   WHERE store_id = p_store AND (order_id = p_order OR exchange_order_id = p_order) AND delivery_address <> '{}'::jsonb;
  -- Free text staff typed: a refund's reason and the reason or note of an event (a name can be in them). The system's own reasons of refunds made in Stripe stay.
  UPDATE commerce.shipment_tracking SET events = '[]'::jsonb, updated_at = now()
   WHERE store_id = p_store AND order_id = p_order AND events <> '[]'::jsonb;
  UPDATE commerce.orders SET held_reason = '[removed]'
   WHERE id = p_order AND held_by IS NOT NULL AND held_reason IS NOT NULL AND held_reason <> '[removed]';
  UPDATE commerce.shipments SET undo_reason = '[removed]'
   WHERE store_id = p_store AND order_id = p_order AND undo_reason IS NOT NULL AND undo_reason <> '[removed]';
  UPDATE commerce.refunds r SET reason = '[removed]'
   WHERE r.store_id = p_store AND r.reason <> '[removed]' AND r.reason NOT IN ('Refunded in Stripe', 'Refund recorded from Stripe')
     AND r.payment_id IN (SELECT p.id FROM commerce.payments p WHERE p.store_id = p_store AND p.order_id = p_order);
  UPDATE commerce.order_events e SET data = e.data - ARRAY['reason', 'note']
   WHERE e.store_id = p_store AND e.order_id = p_order AND (e.data ? 'reason' OR e.data ? 'note');
  -- The postal codes a delivery price was set for and of the address (D237 2.7) are the buyer's.
  UPDATE commerce.order_events e SET data = e.data - ARRAY['priced', 'address']
   WHERE e.store_id = p_store AND e.order_id = p_order AND e.type = 'order.delivery_mismatch' AND (e.data ? 'priced' OR e.data ? 'address');
  -- The check of the buyer's VAT number, when no other order or cart still uses it (a check is shared by the orders of one cart only).
  UPDATE commerce.vat_checks SET name = NULL, address = NULL, number = country_prefix || '**'
   WHERE store_id = p_store AND id = o.vat_check_id AND purpose = 'buyer' AND number <> country_prefix || '**'
     AND NOT EXISTS (SELECT 1 FROM commerce.orders x WHERE x.store_id = p_store AND x.vat_check_id = vat_checks.id AND x.id <> p_order AND x.anonymised_at IS NULL)
     AND NOT EXISTS (SELECT 1 FROM commerce.carts c WHERE c.store_id = p_store AND c.vat_check_id = vat_checks.id);
  PERFORM set_config('commerce.anonymising', '', true);

  -- A copied order's events are refused by its own rule (it is history, with no events of its own).
  IF o.copied_from IS NULL THEN
    INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
    VALUES (p_store, p_order, 'order.anonymised', jsonb_build_object('mode', p_mode, 'was_restricted', o.restricted_at IS NOT NULL), 'system');
  END IF;
  RETURN 'anonymised';
END;
$$;


--
-- Name: anonymised_snapshot(jsonb); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.anonymised_snapshot(p_snapshot jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE
  v jsonb := p_snapshot;
  k text;
BEGIN
  FOREACH k IN ARRAY ARRAY['name', 'company', 'organisationNumber', 'vatNumber', 'email'] LOOP
    IF jsonb_typeof(v -> 'buyer' -> k) = 'string' THEN v := jsonb_set(v, ARRAY['buyer', k], '"[removed]"'); END IF;
  END LOOP;
  FOREACH k IN ARRAY ARRAY['line1', 'line2', 'postalCode', 'city', 'country'] LOOP
    IF jsonb_typeof(v -> 'buyer' -> 'address' -> k) = 'string' THEN v := jsonb_set(v, ARRAY['buyer', 'address', k], '"[removed]"'); END IF;
  END LOOP;
  FOREACH k IN ARRAY ARRAY['city', 'country'] LOOP
    IF jsonb_typeof(v -> 'order' -> 'deliveryPlace' -> k) = 'string' THEN v := jsonb_set(v, ARRAY['order', 'deliveryPlace', k], '"[removed]"'); END IF;
  END LOOP;
  IF jsonb_typeof(v -> 'treatment' -> 'buyerVatNumber') = 'string' THEN v := jsonb_set(v, ARRAY['treatment', 'buyerVatNumber'], '"[removed]"'); END IF;
  RETURN v;
END;
$$;


--
-- Name: app_installation_ended(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.app_installation_ended() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  UPDATE commerce.webhook_endpoints SET enabled = false, disabled_reason = 'uninstalled', updated_at = now()
  WHERE app_grant_id = NEW.id;
  INSERT INTO commerce.integration_deliveries (store_id, provider, event, subject_id, endpoint_id, next_attempt_at)
  SELECT e.store_id, 'webhook', x.event, NEW.id, e.id, now() + x.after
  FROM commerce.webhook_endpoints e
  CROSS JOIN (VALUES ('app.uninstalled', interval '0 hours'), ('store.erase_requested', interval '48 hours')) AS x(event, after)
  WHERE e.app_grant_id = NEW.id;
  RETURN NULL;
END;
$$;


--
-- Name: apply_business_change(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.apply_business_change(p_store uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  c commerce.store_business_changes%ROWTYPE;
  v_before jsonb;
  v_start jsonb;
  v_series text;
BEGIN
  SELECT * INTO c FROM commerce.store_business_changes
    WHERE store_id = p_store AND status = 'planned' AND starts_on <= commerce.store_day(p_store, now())
    FOR UPDATE;
  IF NOT FOUND THEN RETURN false; END IF;
  -- Not ready: it stays planned, documents go on under the business as it is, and the owner is shown what is missing.
  IF c.organisation_number IS NULL OR (c.vat_registered AND c.vat_number IS NULL) THEN RETURN false; END IF;

  SELECT jsonb_build_object(
      'legalName', s.legal_name,
      'organisationNumber', s.organisation_number,
      'postalAddress', s.postal_address,
      'vatRegistered', coalesce(tp.vat_registered, false),
      'vatNumber', tp.vat_number,
      'workVatRegistered', ws.vat_registered,
      'workVatNumber', ws.vat_number,
      'prefixes', coalesce((SELECT jsonb_object_agg(ds.series, ds.prefix) FROM commerce.document_series ds WHERE ds.store_id = p_store), '{}'::jsonb))
    INTO v_before
    FROM commerce.stores s
    LEFT JOIN commerce.store_tax_profile tp ON tp.store_id = s.id
    LEFT JOIN commerce.work_settings ws ON ws.store_id = s.id
    WHERE s.id = p_store;

  UPDATE commerce.stores
    SET legal_name = c.legal_name, organisation_number = c.organisation_number, postal_address = coalesce(c.postal_address, postal_address)
    WHERE id = p_store;

  INSERT INTO commerce.store_tax_profile (store_id, vat_registered, vat_number)
    VALUES (p_store, c.vat_registered, c.vat_number)
    ON CONFLICT (store_id) DO UPDATE
      SET vat_registered = excluded.vat_registered, vat_number = excluded.vat_number,
          vat_number_check_id = NULL, vat_number_checked_at = NULL, vat_number_valid = NULL, updated_at = now();

  UPDATE commerce.work_settings SET vat_registered = c.vat_registered, vat_number = c.vat_number WHERE store_id = p_store;

  -- The new business's own prefixes: the one way a sales series' prefix changes once it has issued numbers (sales_series_guard).
  PERFORM set_config('commerce.business_change', 'on', true);
  FOR v_series IN SELECT jsonb_object_keys(c.prefixes) LOOP
    IF v_series IN ('invoice', 'credit_note', 'work_invoice', 'work_credit_note') THEN
      UPDATE commerce.document_series SET prefix = c.prefixes ->> v_series WHERE store_id = p_store AND series = v_series;
    END IF;
  END LOOP;
  PERFORM set_config('commerce.business_change', '', true);

  SELECT coalesce(jsonb_object_agg(ds.series, coalesce(ds.prefix, '') || ds.next_number), '{}'::jsonb) INTO v_start
    FROM commerce.document_series ds
    WHERE ds.store_id = p_store AND ds.series IN ('invoice', 'credit_note', 'work_invoice', 'work_credit_note');

  UPDATE commerce.store_business_changes
    SET status = 'applied', applied_at = now(), before = v_before, series_start = v_start, updated_at = now()
    WHERE id = c.id;
  RETURN true;
END;
$$;


--
-- Name: approve_access_request(uuid, text, text, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.approve_access_request(p_request_id uuid, p_slug text, p_store_name text, p_decided_by uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_request commerce.access_requests%ROWTYPE;
  v_template uuid;
  v_fallback boolean := false;
  v_account uuid;
  v_disabled timestamptz;
  v_store uuid;
BEGIN
  SELECT * INTO v_request FROM commerce.access_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown access request %', p_request_id;
  END IF;
  IF v_request.status <> 'pending' THEN
    RAISE EXCEPTION 'the access request is already %', v_request.status
      USING ERRCODE = 'check_violation';
  END IF;

  -- The store template chosen while it is offered, else the default template.
  v_template := commerce.starter_offered_source(v_request.starter_id);
  IF v_template IS NULL THEN
    v_fallback := v_request.starter_id IS NOT NULL;
    v_template := commerce.starter_source(NULL);
  END IF;

  INSERT INTO commerce.accounts (email, name)
  VALUES (v_request.email, v_request.name)
  ON CONFLICT ((lower(email))) DO UPDATE
    SET name = coalesce(commerce.accounts.name, excluded.name)
  RETURNING id, disabled_at INTO v_account, v_disabled;
  IF v_disabled IS NOT NULL THEN
    RAISE EXCEPTION 'the account for % is disabled', v_request.email
      USING ERRCODE = 'check_violation';
  END IF;

  v_store := commerce.clone_store(v_template, p_slug, p_store_name, v_account);

  UPDATE commerce.access_requests
     SET status = 'approved', decided_by = p_decided_by, decided_at = now(), store_id = v_store
   WHERE id = p_request_id;

  INSERT INTO commerce.audit_log (store_id, account_id, action, details)
  VALUES (v_store, p_decided_by, 'platform.access_approved',
          jsonb_build_object('email', v_request.email, 'slug', p_slug, 'starter', v_request.starter_id, 'starterFallback', v_fallback));

  RETURN v_store;
END;
$$;


--
-- Name: assert_copy_running(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.assert_copy_running(p_source uuid, p_new uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM commerce.store_copies c
     WHERE c.source_store_id = p_source AND c.new_store_id = p_new AND c.status = 'running'
  ) THEN
    RAISE EXCEPTION 'no store copy is running from % into %', p_source, p_new;
  END IF;
END;
$$;


--
-- Name: assert_product_publishable(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.assert_product_publishable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_manufacturer_country char(2);
  v_responsible_country char(2);
  v_areas text[];
  v_area text;
BEGIN
  IF NEW.status <> 'active' THEN
    RETURN NEW;
  END IF;

  -- GPSR covers physical goods: a product sold only as downloads needs no
  -- manufacturer or responsible person (D24).
  IF NOT EXISTS (
    SELECT 1 FROM commerce.product_variants
     WHERE product_id = NEW.id AND active AND delivery = 'physical'
  ) THEN
    v_manufacturer_country := NULL;
  ELSIF NEW.manufacturer_id IS NULL THEN
    RAISE EXCEPTION 'product % cannot be active without a manufacturer', NEW.handle
      USING ERRCODE = 'check_violation';
  ELSE
    SELECT country INTO v_manufacturer_country
      FROM commerce.economic_operators
     WHERE store_id = NEW.store_id AND id = NEW.manufacturer_id;
  END IF;

  -- A responsible person established in each area the store's destinations ask for (D452).
  IF v_manufacturer_country IS NOT NULL THEN
    v_areas := commerce.responsible_person_areas(NEW.store_id, v_manufacturer_country);
    IF cardinality(v_areas) > 0 THEN
      SELECT country INTO v_responsible_country
        FROM commerce.economic_operators
       WHERE store_id = NEW.store_id AND id = NEW.responsible_person_id;
      FOREACH v_area IN ARRAY v_areas LOOP
        IF NOT commerce.is_established_in(v_area, v_responsible_country) THEN
          IF v_area = 'eu' THEN
            RAISE EXCEPTION 'product % has a manufacturer outside the EU and needs an EU responsible person', NEW.handle
              USING ERRCODE = 'check_violation';
          ELSE
            RAISE EXCEPTION 'product % has a manufacturer outside the EEA and needs an EEA responsible person', NEW.handle
              USING ERRCODE = 'check_violation';
          END IF;
        END IF;
      END LOOP;
    END IF;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM commerce.product_media WHERE product_id = NEW.id) THEN
    RAISE EXCEPTION 'product % cannot be active without a picture', NEW.handle
      USING ERRCODE = 'check_violation';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM commerce.product_translations
     WHERE product_id = NEW.id AND btrim(title) <> ''
  ) THEN
    RAISE EXCEPTION 'product % cannot be active without a title', NEW.handle
      USING ERRCODE = 'check_violation';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM commerce.product_variants
     WHERE product_id = NEW.id AND active
  ) THEN
    RAISE EXCEPTION 'product % cannot be active without an active variant', NEW.handle
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: audience_offered(text, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.audience_offered(p_store_audience text, p_product_audience text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT p_product_audience = 'all' OR p_store_audience = 'both'
      OR (p_product_audience = 'businesses') = (p_store_audience = 'businesses')
$$;


