--
-- Name: authorize_order_payment(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.authorize_order_payment(p_order_id uuid, p_reference text, p_capture_before timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_order commerce.orders%ROWTYPE;
BEGIN
  SELECT * INTO v_order FROM commerce.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown order %', p_order_id;
  END IF;
  -- Applied twice (the webhook and the shopper's return), or cancelled meanwhile: nothing more. The caller voids a hold on a cancelled order.
  IF v_order.status <> 'pending_payment' THEN
    RETURN false;
  END IF;
  IF v_order.capture_mode IS NULL OR v_order.copied_from IS NOT NULL THEN
    RAISE EXCEPTION 'orders.not_capture_later: order % was not checked out to be captured later', p_order_id USING ERRCODE = 'check_violation';
  END IF;
  UPDATE commerce.orders SET status = 'authorized', capture_before = p_capture_before WHERE id = p_order_id;
  -- The stock stays held until Stripe lets the hold go, and a day for the job to see it.
  UPDATE commerce.inventory_reservations SET expires_at = greatest(expires_at, p_capture_before + interval '1 day')
   WHERE order_id = p_order_id AND released_at IS NULL;
  UPDATE commerce.payments SET status = 'authorized', updated_at = now()
   WHERE store_id = v_order.store_id AND order_id = p_order_id AND provider = 'stripe' AND provider_reference = p_reference AND status = 'pending';
  UPDATE commerce.carts SET status = 'converted', updated_at = now()
   WHERE store_id = v_order.store_id AND id = v_order.cart_id;
  INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
  VALUES (v_order.store_id, p_order_id, 'order.authorized',
          jsonb_build_object('reference', p_reference, 'capture_before', p_capture_before, 'mode', v_order.capture_mode), 'stripe');
  RETURN true;
END;
$$;


--
-- Name: automations_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.automations_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.store_id <> OLD.store_id OR NEW.kind <> OLD.kind THEN
    RAISE EXCEPTION 'automations.identity: an automation stays itself' USING ERRCODE = 'check_violation';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: autopilot_plans_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.autopilot_plans_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.id <> OLD.id OR NEW.store_id IS DISTINCT FROM OLD.store_id OR NEW.account_id <> OLD.account_id
     OR NEW.conversation_id <> OLD.conversation_id OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'A plan''s store, person and conversation are fixed' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.status IN ('done', 'stopped') AND (NEW.status <> OLD.status OR NEW.version <> OLD.version) THEN
    RAISE EXCEPTION 'A plan that is % cannot change', OLD.status USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status <> OLD.status AND NOT (
       (OLD.status = 'draft' AND NEW.status IN ('running', 'stopped'))
    OR (OLD.status = 'running' AND NEW.status IN ('paused', 'done', 'stopped', 'draft'))
    OR (OLD.status = 'paused' AND NEW.status IN ('running', 'stopped', 'draft'))
  ) THEN
    RAISE EXCEPTION 'A plan cannot go from % to %', OLD.status, NEW.status USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.version < OLD.version THEN
    RAISE EXCEPTION 'A plan''s version only grows' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.version <> OLD.version AND NEW.status <> 'draft' THEN
    RAISE EXCEPTION 'A plan''s steps change only while it is a draft' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.status IN ('running', 'paused') AND NEW.status = 'draft' AND NEW.version = OLD.version THEN
    RAISE EXCEPTION 'A plan goes back to a draft only when its steps change' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status = 'running' AND OLD.status <> 'running' THEN
    NEW.started_at := coalesce(OLD.started_at, now());
    NEW.pause_reason := null;
  END IF;
  IF NEW.status IN ('done', 'stopped') AND OLD.status NOT IN ('done', 'stopped') THEN
    NEW.finished_at := now();
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: autopilot_steps_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.autopilot_steps_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_plan record;
  v_row record;
BEGIN
  v_row := CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  SELECT status, store_id INTO v_plan FROM commerce.assistant_plans WHERE id = v_row.plan_id;
  IF TG_OP = 'DELETE' THEN
    -- A plan (or its store) being deleted takes its steps with it.
    IF NOT FOUND THEN RETURN OLD; END IF;
    IF v_plan.status <> 'draft' OR OLD.status IN ('done', 'running') THEN
      RAISE EXCEPTION 'A step is removed only from a draft, and never once it ran' USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF v_plan.status IS DISTINCT FROM 'draft' THEN
      RAISE EXCEPTION 'Steps are added only to a draft plan' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.store_id IS DISTINCT FROM v_plan.store_id THEN
      RAISE EXCEPTION 'A step belongs to its plan''s store' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status <> 'pending' OR NEW.tries <> 0 OR NEW.answer IS NOT NULL THEN
      RAISE EXCEPTION 'A step starts pending' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.id <> OLD.id OR NEW.plan_id <> OLD.plan_id OR NEW.store_id IS DISTINCT FROM OLD.store_id OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'A step''s plan is fixed' USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW.key <> OLD.key OR NEW.kind <> OLD.kind OR NEW.spec <> OLD.spec OR NEW.after_keys <> OLD.after_keys
      OR NEW.done_check <> OLD.done_check OR NEW.title <> OLD.title OR NEW.position <> OLD.position)
     AND v_plan.status <> 'draft' THEN
    RAISE EXCEPTION 'A step is rewritten only while its plan is a draft' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.status IN ('done', 'skipped', 'cancelled') AND NEW.status <> OLD.status THEN
    RAISE EXCEPTION 'A step that is % cannot change', OLD.status USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status <> OLD.status AND NOT (
       (OLD.status = 'pending' AND NEW.status IN ('running', 'waiting', 'asking', 'done', 'skipped', 'cancelled'))
    OR (OLD.status = 'running' AND NEW.status IN ('pending', 'waiting', 'asking', 'done', 'skipped', 'cancelled'))
    OR (OLD.status = 'waiting' AND NEW.status IN ('pending', 'asking', 'done', 'skipped', 'cancelled'))
    OR (OLD.status = 'asking' AND NEW.status IN ('pending', 'done', 'skipped', 'cancelled'))
  ) THEN
    RAISE EXCEPTION 'A step cannot go from % to %', OLD.status, NEW.status USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status = 'running' AND OLD.status <> 'running' AND v_plan.status <> 'running' THEN
    RAISE EXCEPTION 'A step runs only while its plan runs' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.answer IS DISTINCT FROM OLD.answer AND OLD.status <> 'asking' THEN
    RAISE EXCEPTION 'A step is answered only while it asks' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.tries < OLD.tries AND NOT (OLD.status = 'asking' AND NEW.status = 'pending' AND NEW.tries = 0) THEN
    RAISE EXCEPTION 'A step''s tries start again only when the owner says try again' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status = 'running' AND OLD.status <> 'running' THEN
    NEW.started_at := now();
  END IF;
  IF NEW.status IN ('done', 'skipped', 'cancelled') AND OLD.status NOT IN ('done', 'skipped', 'cancelled') THEN
    NEW.finished_at := now();
    NEW.claimed_until := null;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: await_bank_payment(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.await_bank_payment(p_order_id uuid, p_reference text, p_until timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_order commerce.orders%ROWTYPE;
BEGIN
  SELECT * INTO v_order FROM commerce.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown order %', p_order_id;
  END IF;
  -- Paid or cancelled meanwhile, or already waiting (the webhook and the shopper's return both apply it): nothing more.
  IF v_order.status <> 'pending_payment' OR v_order.awaiting_bank_since IS NOT NULL THEN
    RETURN false;
  END IF;
  IF v_order.copied_from IS NOT NULL THEN
    RAISE EXCEPTION 'orders.copied: a copied order is history and is never paid' USING ERRCODE = 'check_violation';
  END IF;
  UPDATE commerce.orders SET awaiting_bank_since = now() WHERE id = p_order_id;
  UPDATE commerce.inventory_reservations SET expires_at = greatest(expires_at, p_until)
   WHERE order_id = p_order_id AND released_at IS NULL;
  UPDATE commerce.bookings SET hold_expires_at = greatest(hold_expires_at, p_until)
   WHERE store_id = v_order.store_id AND order_id = p_order_id AND status = 'held' AND hold_expires_at IS NOT NULL;
  UPDATE commerce.carts SET status = 'converted', updated_at = now()
   WHERE store_id = v_order.store_id AND id = v_order.cart_id;
  INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
  VALUES (v_order.store_id, p_order_id, 'order.awaiting_bank', jsonb_build_object('reference', p_reference, 'until', p_until), 'stripe');
  RETURN true;
END;
$$;


--
-- Name: blog_comments_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.blog_comments_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.store_id <> OLD.store_id OR NEW.page_id <> OLD.page_id OR NEW.name <> OLD.name OR NEW.email IS DISTINCT FROM OLD.email
     OR NEW.body <> OLD.body OR NEW.body_hash <> OLD.body_hash OR NEW.locale <> OLD.locale OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'blog_comments.fixed: a visitor''s comment is kept as they wrote it' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.status <> 'pending' AND NEW.status = 'pending' THEN
    RAISE EXCEPTION 'blog_comments.decided: a decided comment does not wait again' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: blogs_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.blogs_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.listing_page_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM commerce.pages p WHERE p.id = NEW.listing_page_id AND p.store_id = NEW.store_id AND p.type = 'page'
  ) THEN
    RAISE EXCEPTION 'blogs.listing_page: a blog lists on a page of its own store' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'UPDATE' AND (NEW.store_id <> OLD.store_id OR NEW.main <> OLD.main) THEN
    RAISE EXCEPTION 'blogs.fixed: a blog stays its store''s, and the first blog stays the first' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: bonus_adjust(uuid, uuid, bigint, text, uuid, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_adjust(p_store uuid, p_customer uuid, p_amount bigint, p_note text, p_by uuid, p_key text) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF p_amount = 0 THEN
    RAISE EXCEPTION 'bonus.zero';
  END IF;
  IF p_amount > 0 THEN
    PERFORM commerce.bonus_grant(p_store, p_customer, 'adjust', p_amount, NULL, NULL, now(),
                                 commerce.bonus_expiry_from(p_store, now()), p_note, p_by, p_key);
    RETURN p_amount;
  END IF;
  RETURN -commerce.bonus_take(p_store, p_customer, 'adjust', -p_amount, 'any', NULL, NULL, NULL, p_note, p_by, p_key, true);
END;
$$;


--
-- Name: bonus_allocation_within_lot(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_allocation_within_lot() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_lot commerce.bonus_entries%ROWTYPE;
  v_entry commerce.bonus_entries%ROWTYPE;
  v_taken bigint;
BEGIN
  SELECT * INTO v_lot FROM commerce.bonus_entries WHERE store_id = NEW.store_id AND id = NEW.lot_id;
  SELECT * INTO v_entry FROM commerce.bonus_entries WHERE store_id = NEW.store_id AND id = NEW.entry_id;
  IF v_lot.amount_minor IS NULL OR v_entry.amount_minor IS NULL OR v_lot.amount_minor <= 0 OR v_entry.amount_minor >= 0
     OR v_lot.customer_id <> v_entry.customer_id THEN
    RAISE EXCEPTION 'bonus.bad_allocation' USING ERRCODE = 'check_violation';
  END IF;
  SELECT coalesce(sum(a.amount_minor), 0) INTO v_taken
    FROM commerce.bonus_allocations a WHERE a.store_id = NEW.store_id AND a.lot_id = NEW.lot_id;
  IF v_taken > v_lot.amount_minor THEN
    RAISE EXCEPTION 'bonus.below_zero' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: bonus_balance(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_balance(p_store uuid, p_customer uuid) RETURNS TABLE(available_minor bigint, pending_minor bigint, expiring_minor bigint, expiring_at timestamp with time zone, pending_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  WITH l AS (
    SELECT * FROM commerce.bonus_lots(p_store, p_customer) x
     WHERE x.remaining > 0 AND (x.expires_at IS NULL OR x.expires_at > now())
  ), soon AS (SELECT min(expires_at) AS at FROM l WHERE expires_at IS NOT NULL)
  SELECT coalesce(sum(l.remaining) FILTER (WHERE l.available_at <= now()), 0)::bigint,
         coalesce(sum(l.remaining) FILTER (WHERE l.available_at > now()), 0)::bigint,
         coalesce((SELECT sum(l2.remaining) FROM l l2, soon WHERE l2.expires_at = soon.at), 0)::bigint,
         (SELECT at FROM soon),
         min(l.available_at) FILTER (WHERE l.available_at > now())
    FROM l
$$;


--
-- Name: bonus_birthday_grants(timestamp with time zone); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_birthday_grants(p_now timestamp with time zone DEFAULT now()) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_row record;
  v_count integer := 0;
BEGIN
  FOR v_row IN
    SELECT c.store_id, c.id AS customer_id, b.birthday_minor, (p_now AT TIME ZONE s.time_zone)::date AS today
    FROM commerce.bonus_settings b
    JOIN commerce.stores s ON s.id = b.store_id
    JOIN commerce.customers c ON c.store_id = b.store_id
    WHERE b.birthday_minor > 0
      AND NOT s.is_template AND NOT s.starter
      AND commerce.store_is_active(b.store_id)
      AND commerce.bonus_program_on(b.store_id)
      AND c.birthday IS NOT NULL
      AND c.email_verified_at IS NOT NULL
      AND c.birthday_set_at <= p_now - interval '30 days'
      AND (
        c.birthday = to_char((p_now AT TIME ZONE s.time_zone)::date, 'MM-DD')
        OR (c.birthday = '02-29' AND to_char((p_now AT TIME ZONE s.time_zone)::date, 'MM-DD') = '02-28'
            AND NOT (extract(year FROM (p_now AT TIME ZONE s.time_zone)) :: integer % 4 = 0
                     AND (extract(year FROM (p_now AT TIME ZONE s.time_zone)) :: integer % 100 <> 0
                          OR extract(year FROM (p_now AT TIME ZONE s.time_zone)) :: integer % 400 = 0)))
      )
      AND NOT EXISTS (
        SELECT 1 FROM commerce.bonus_entries e
        WHERE e.store_id = c.store_id
          AND e.idempotency_key = 'birthday:' || c.id || ':' || extract(year FROM (p_now AT TIME ZONE s.time_zone))::integer
      )
  LOOP
    PERFORM commerce.bonus_grant(v_row.store_id, v_row.customer_id, 'birthday', v_row.birthday_minor, NULL, NULL, p_now,
                                 commerce.bonus_expiry_from(v_row.store_id, p_now), '', NULL,
                                 'birthday:' || v_row.customer_id || ':' || extract(year FROM v_row.today)::integer);
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;


--
-- Name: bonus_convert(uuid, bigint, character, character); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_convert(p_store uuid, p_amount bigint, p_from character, p_to character) RETURNS bigint
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_from numeric;
  v_to numeric;
BEGIN
  IF p_from = p_to THEN
    RETURN p_amount;
  END IF;
  v_from := CASE WHEN p_from = 'EUR' THEN 1 ELSE
    (SELECT c.rate FROM commerce.store_currencies c WHERE c.store_id = p_store AND c.currency = p_from) END;
  v_to := CASE WHEN p_to = 'EUR' THEN 1 ELSE
    (SELECT c.rate FROM commerce.store_currencies c WHERE c.store_id = p_store AND c.currency = p_to) END;
  IF v_from IS NULL OR v_to IS NULL OR v_from <= 0 OR v_to <= 0 THEN
    RETURN NULL;
  END IF;
  RETURN floor(p_amount::numeric * v_to / v_from)::bigint;
END;
$$;


--
-- Name: bonus_currency(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_currency(p_store uuid) RETURNS character
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce(
    (SELECT b.currency FROM commerce.bonus_settings b WHERE b.store_id = p_store),
    (SELECT m.currency FROM commerce.markets m JOIN commerce.stores s ON s.id = m.store_id
      WHERE m.store_id = p_store AND m.active
      ORDER BY (m.code = s.country) DESC NULLS LAST, m.created_at, m.code LIMIT 1),
    'EUR')::char(3)
$$;


--
-- Name: bonus_earn_bps(uuid, uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_earn_bps(p_store uuid, p_customer uuid, p_order uuid) RETURNS integer
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_s commerce.bonus_settings%ROWTYPE;
  v_spent bigint;
  v_bps integer;
BEGIN
  SELECT * INTO v_s FROM commerce.bonus_settings WHERE store_id = p_store;
  IF NOT FOUND THEN RETURN 0; END IF;
  IF jsonb_array_length(v_s.levels) = 0 THEN RETURN v_s.earn_bps; END IF;
  v_spent := commerce.bonus_level_spend(p_store, p_customer, p_order);
  SELECT (l ->> 'earnBps')::integer INTO v_bps
    FROM jsonb_array_elements(v_s.levels) l
   WHERE (l ->> 'fromMinor')::bigint <= v_spent
   ORDER BY (l ->> 'fromMinor')::bigint DESC
   LIMIT 1;
  RETURN coalesce(v_bps, v_s.earn_bps);
END;
$$;


--
-- Name: bonus_entry_fully_allocated(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_entry_fully_allocated() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_taken bigint;
BEGIN
  IF NEW.amount_minor < 0 THEN
    SELECT coalesce(sum(a.amount_minor), 0) INTO v_taken
      FROM commerce.bonus_allocations a WHERE a.store_id = NEW.store_id AND a.entry_id = NEW.id;
    IF v_taken <> -NEW.amount_minor THEN
      RAISE EXCEPTION 'bonus.below_zero' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: bonus_expire_due(integer); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_expire_due(p_limit integer DEFAULT 1000) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_lot record;
  v_left bigint;
  v_count integer := 0;
BEGIN
  FOR v_lot IN
    SELECT e.store_id, e.customer_id, e.id
      FROM commerce.bonus_entries e
     WHERE e.amount_minor > 0 AND e.expires_at IS NOT NULL AND e.expires_at <= now()
       AND e.amount_minor > coalesce((SELECT sum(a.amount_minor) FROM commerce.bonus_allocations a
                                       WHERE a.store_id = e.store_id AND a.lot_id = e.id), 0)
       AND NOT EXISTS (SELECT 1 FROM commerce.bonus_settings b WHERE b.store_id = e.store_id AND b.paused_at IS NOT NULL)
     ORDER BY e.expires_at, e.id
     LIMIT p_limit
  LOOP
    SELECT l.remaining INTO v_left FROM commerce.bonus_lots(v_lot.store_id, v_lot.customer_id) l WHERE l.id = v_lot.id;
    IF commerce.bonus_take(v_lot.store_id, v_lot.customer_id, 'expire', coalesce(v_left, 0), 'lot', v_lot.id,
                           NULL, NULL, '', NULL, 'expire:' || v_lot.id) > 0 THEN
      v_count := v_count + 1;
    END IF;
  END LOOP;
  RETURN v_count;
END;
$$;


--
-- Name: bonus_expiring(integer); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_expiring(p_days integer) RETURNS TABLE(store_id uuid, customer_id uuid, first_at timestamp with time zone, amount_minor bigint)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT x.store_id, x.customer_id, min(x.expires_at), sum(x.remaining)::bigint
    FROM (
      SELECT e.store_id, e.customer_id, e.expires_at,
             e.amount_minor - coalesce((SELECT sum(a.amount_minor) FROM commerce.bonus_allocations a
                                         WHERE a.store_id = e.store_id AND a.lot_id = e.id), 0) AS remaining
        FROM commerce.bonus_entries e
       WHERE e.amount_minor > 0 AND e.expires_at > now() AND e.expires_at <= now() + make_interval(days => p_days)
         AND NOT EXISTS (SELECT 1 FROM commerce.bonus_settings b WHERE b.store_id = e.store_id AND b.paused_at IS NOT NULL)
    ) x
   WHERE x.remaining > 0
   GROUP BY x.store_id, x.customer_id
$$;


--
-- Name: bonus_expiry_from(uuid, timestamp with time zone); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_expiry_from(p_store uuid, p_from timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT CASE WHEN b.expires_months IS NULL THEN NULL ELSE p_from + make_interval(months => b.expires_months) END
    FROM commerce.bonus_settings b WHERE b.store_id = p_store
$$;


--
-- Name: bonus_grant(uuid, uuid, text, bigint, uuid, uuid, timestamp with time zone, timestamp with time zone, text, uuid, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_grant(p_store uuid, p_customer uuid, p_kind text, p_amount bigint, p_order uuid, p_refund uuid, p_available_at timestamp with time zone, p_expires_at timestamp with time zone, p_note text, p_by uuid, p_key text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_id uuid;
BEGIN
  PERFORM commerce.bonus_lock(p_store, p_customer);
  SELECT e.id INTO v_id FROM commerce.bonus_entries e WHERE e.store_id = p_store AND e.idempotency_key = p_key;
  IF FOUND THEN
    RETURN v_id;
  END IF;
  IF p_amount <= 0 THEN
    RETURN NULL;
  END IF;
  INSERT INTO commerce.bonus_entries (
    store_id, customer_id, kind, amount_minor, order_id, refund_id, available_at, expires_at, note, created_by, idempotency_key
  ) VALUES (
    p_store, p_customer, p_kind, p_amount, p_order, p_refund, p_available_at, p_expires_at, coalesce(p_note, ''), p_by, p_key
  ) RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: bonus_ledger_immutable(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_ledger_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF TG_TABLE_NAME = 'bonus_entries' THEN
      IF NOT EXISTS (SELECT 1 FROM commerce.customers c WHERE c.store_id = OLD.store_id AND c.id = OLD.customer_id) THEN
        RETURN OLD;
      END IF;
    ELSIF NOT EXISTS (SELECT 1 FROM commerce.bonus_entries e WHERE e.store_id = OLD.store_id AND e.id = OLD.entry_id) THEN
      -- An allocation goes with the entry that took the credits.
      RETURN OLD;
    END IF;
  END IF;
  RAISE EXCEPTION 'commerce.% is append-only; % is not allowed', TG_TABLE_NAME, TG_OP
    USING ERRCODE = 'restrict_violation';
END;
$$;


--
-- Name: bonus_level_spend(uuid, uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_level_spend(p_store uuid, p_customer uuid, p_except uuid) RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce(sum(greatest(0, coalesce(commerce.bonus_convert(o.store_id, goods.minor - coalesce(back.minor, 0), o.currency, commerce.bonus_currency(o.store_id)), 0))), 0)::bigint
    FROM commerce.orders o
    CROSS JOIN LATERAL (
      SELECT coalesce(sum(ol.total_minor - ol.venue_minor), 0)::bigint AS minor
        FROM commerce.order_lines ol WHERE ol.store_id = o.store_id AND ol.order_id = o.id
    ) goods
    LEFT JOIN LATERAL (
      SELECT sum(r.amount_minor)::bigint AS minor
        FROM commerce.refunds r JOIN commerce.payments p ON p.store_id = r.store_id AND p.id = r.payment_id
       WHERE r.store_id = o.store_id AND p.order_id = o.id AND r.status::text = 'succeeded'
    ) back ON true
   WHERE o.store_id = p_store AND o.customer_id = p_customer
     AND (p_except IS NULL OR o.id <> p_except)
     AND o.copied_from IS NULL AND o.host_id IS NULL
     AND o.placed_at > now() - interval '365 days'
     AND EXISTS (SELECT 1 FROM commerce.payments p WHERE p.store_id = o.store_id AND p.order_id = o.id AND p.status::text = 'captured');
$$;


--
-- Name: bonus_lock(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_lock(p_store uuid, p_customer uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM 1 FROM commerce.customers c WHERE c.store_id = p_store AND c.id = p_customer FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'bonus.no_customer';
  END IF;
END;
$$;


--
-- Name: bonus_lots(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_lots(p_store uuid, p_customer uuid) RETURNS TABLE(id uuid, amount_minor bigint, remaining bigint, available_at timestamp with time zone, expires_at timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT e.id, e.amount_minor,
         (e.amount_minor - coalesce((SELECT sum(a.amount_minor) FROM commerce.bonus_allocations a
                                      WHERE a.store_id = e.store_id AND a.lot_id = e.id), 0))::bigint,
         e.available_at, e.expires_at, e.created_at
    FROM commerce.bonus_entries e
   WHERE e.store_id = p_store AND e.customer_id = p_customer AND e.amount_minor > 0
$$;


--
-- Name: bonus_order_held(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_order_held(p_order uuid) RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce(-sum(e.amount_minor) FILTER (WHERE e.kind IN ('redeem', 'restore')), 0)::bigint
    FROM commerce.bonus_entries e WHERE e.order_id = p_order
$$;


--
-- Name: bonus_order_paid(uuid, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_order_paid(p_order uuid, p_was text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_o commerce.orders%ROWTYPE;
  v_s commerce.bonus_settings%ROWTYPE;
  v_used bigint;
  v_need bigint;
  v_taken bigint;
  v_base bigint;
  v_earn bigint;
  v_credits bigint;
  v_at timestamptz;
BEGIN
  SELECT * INTO v_o FROM commerce.orders WHERE id = p_order;
  IF NOT FOUND OR v_o.customer_id IS NULL OR v_o.copied_from IS NOT NULL THEN
    RETURN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM commerce.customers c WHERE c.store_id = v_o.store_id AND c.id = v_o.customer_id) THEN
    RETURN;
  END IF;
  -- Paid after it was cancelled: the credits that came back are taken again, as far as the customer still has them.
  IF p_was = 'cancelled' THEN
    SELECT coalesce(-e.amount_minor, 0) INTO v_used FROM commerce.bonus_entries e
     WHERE e.store_id = v_o.store_id AND e.idempotency_key = 'redeem:' || p_order;
    v_need := coalesce(v_used, 0) - commerce.bonus_order_held(p_order);
    IF v_need > 0 THEN
      v_taken := commerce.bonus_take(v_o.store_id, v_o.customer_id, 'redeem', v_need, 'available', NULL, p_order, NULL,
                                     'paid after the order was cancelled', NULL,
                                     'redeem-late:' || p_order || ':' || (SELECT count(*) FROM commerce.bonus_entries e
                                                                            WHERE e.order_id = p_order AND e.kind = 'redeem'));
      IF v_taken < v_need THEN
        INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
        VALUES (v_o.store_id, p_order, 'bonus.short', jsonb_build_object('missing', v_need - v_taken), 'system');
      END IF;
    END IF;
  END IF;
  -- A host is the seller of their own bookings (D71): the store's credits are not theirs to give or take.
  IF v_o.host_id IS NOT NULL THEN
    RETURN;
  END IF;
  SELECT * INTO v_s FROM commerce.bonus_settings WHERE store_id = v_o.store_id;
  IF NOT FOUND OR NOT v_s.enabled OR NOT commerce.feature_on(v_o.store_id, 'bonus') THEN
    RETURN;
  END IF;
  SELECT coalesce(sum(ol.total_minor - ol.venue_minor), 0) INTO v_base
    FROM commerce.order_lines ol WHERE ol.store_id = v_o.store_id AND ol.order_id = p_order
       AND NOT EXISTS (SELECT 1 FROM commerce.order_payment_terms t WHERE t.store_id = v_o.store_id AND t.order_id = p_order);
  v_earn := floor(v_base::numeric * commerce.bonus_earn_bps(v_o.store_id, v_o.customer_id, p_order) / 10000)::bigint;
  IF v_earn <= 0 THEN
    RETURN;
  END IF;
  v_credits := commerce.bonus_convert(v_o.store_id, v_earn, v_o.currency, v_s.currency);
  IF v_credits IS NULL OR v_credits <= 0 THEN
    RETURN;
  END IF;
  v_at := now() + make_interval(days => v_s.pending_days);
  PERFORM commerce.bonus_grant(v_o.store_id, v_o.customer_id, 'earn', v_credits, p_order, NULL, v_at,
                               commerce.bonus_expiry_from(v_o.store_id, v_at), '', NULL, 'earn:' || p_order);
  UPDATE commerce.orders SET bonus_earned_minor = v_earn, bonus_available_at = v_at WHERE id = p_order;
END;
$$;


--
-- Name: bonus_order_paid_cancelled(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_order_paid_cancelled(p_order uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_o commerce.orders%ROWTYPE;
  v_lot uuid;
  v_left bigint;
BEGIN
  SELECT * INTO v_o FROM commerce.orders WHERE id = p_order;
  IF NOT FOUND OR v_o.customer_id IS NULL THEN
    RETURN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM commerce.customers c WHERE c.store_id = v_o.store_id AND c.id = v_o.customer_id) THEN
    RETURN;
  END IF;
  SELECT e.id INTO v_lot FROM commerce.bonus_entries e WHERE e.store_id = v_o.store_id AND e.idempotency_key = 'earn:' || p_order;
  IF v_lot IS NOT NULL THEN
    SELECT l.remaining INTO v_left FROM commerce.bonus_lots(v_o.store_id, v_o.customer_id) l WHERE l.id = v_lot;
    PERFORM commerce.bonus_take(v_o.store_id, v_o.customer_id, 'reverse', coalesce(v_left, 0), 'lot', v_lot, p_order, NULL,
                                'the order was cancelled', NULL, 'reverse-cancel:' || p_order);
  END IF;
  PERFORM commerce.bonus_restore(p_order, commerce.bonus_order_held(p_order), NULL, 'restore-cancel:' || p_order,
                                 'the order was cancelled');
END;
$$;


--
-- Name: bonus_order_unpaid_cancelled(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_order_unpaid_cancelled(p_order uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM commerce.bonus_restore(p_order, commerce.bonus_order_held(p_order), NULL, 'restore-unpaid:' || p_order,
                                 'the order was not paid');
END;
$$;


--
-- Name: bonus_pause_sync(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_pause_sync(p_store uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_s commerce.bonus_settings%ROWTYPE;
  v_on boolean;
BEGIN
  SELECT * INTO v_s FROM commerce.bonus_settings b WHERE b.store_id = p_store FOR UPDATE;
  IF NOT FOUND THEN
    RETURN;
  END IF;
  v_on := v_s.enabled AND commerce.feature_on(p_store, 'bonus');
  IF v_on AND v_s.paused_at IS NOT NULL THEN
    PERFORM commerce.bonus_resume(p_store, v_s.paused_at);
    UPDATE commerce.bonus_settings SET paused_at = NULL WHERE store_id = p_store;
  ELSIF NOT v_on AND v_s.paused_at IS NULL THEN
    UPDATE commerce.bonus_settings SET paused_at = now() WHERE store_id = p_store;
  END IF;
END;
$$;


--
-- Name: bonus_program_on(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_program_on(p_store uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT commerce.feature_on(p_store, 'bonus')
     AND coalesce((SELECT b.enabled FROM commerce.bonus_settings b WHERE b.store_id = p_store), false)
$$;


--
-- Name: bonus_redeem(uuid, uuid, uuid, bigint, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_redeem(p_store uuid, p_customer uuid, p_order uuid, p_amount bigint, p_key text) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM commerce.bonus_entries e WHERE e.store_id = p_store AND e.idempotency_key = p_key)
     AND NOT commerce.bonus_program_on(p_store) THEN
    RAISE EXCEPTION 'bonus.off';
  END IF;
  RETURN commerce.bonus_take(p_store, p_customer, 'redeem', p_amount, 'available', NULL, p_order, NULL, '', NULL, p_key, true);
END;
$$;


--
-- Name: bonus_redeem_reward(uuid, uuid, uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_redeem_reward(p_store uuid, p_customer uuid, p_reward uuid, p_item uuid, p_code text, p_ends_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_reward commerce.bonus_rewards%ROWTYPE;
BEGIN
  PERFORM commerce.bonus_lock(p_store, p_customer);
  IF EXISTS (SELECT 1 FROM commerce.bonus_entries e WHERE e.store_id = p_store AND e.idempotency_key = 'reward:' || p_item) THEN
    RETURN p_item;
  END IF;
  IF NOT commerce.bonus_program_on(p_store) THEN
    RAISE EXCEPTION 'bonus.off';
  END IF;
  SELECT * INTO v_reward FROM commerce.bonus_rewards r WHERE r.store_id = p_store AND r.id = p_reward AND r.active FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'bonus.reward_gone';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM commerce.customers c WHERE c.store_id = p_store AND c.id = p_customer) THEN
    RAISE EXCEPTION 'bonus.customer';
  END IF;
  PERFORM commerce.bonus_take(p_store, p_customer, 'reward', v_reward.cost_minor, 'any', NULL, NULL, NULL,
                              v_reward.name, NULL, 'reward:' || p_item, true);
  INSERT INTO commerce.discount_code_items (id, store_id, discount_id, code, batch, customer_id, ends_at)
  VALUES (p_item, p_store, v_reward.discount_id, upper(p_code), 1, p_customer, p_ends_at);
  RETURN p_item;
END;
$$;


--
-- Name: bonus_refund_applied(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_refund_applied(p_refund uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_r commerce.refunds%ROWTYPE;
  v_o commerce.orders%ROWTYPE;
  v_paid bigint;
  v_refunded bigint;
  v_lot uuid;
  v_granted bigint;
  v_target bigint;
  v_done bigint;
  v_used bigint;
BEGIN
  SELECT * INTO v_r FROM commerce.refunds WHERE id = p_refund;
  IF NOT FOUND OR v_r.status = 'failed' THEN
    RETURN;
  END IF;
  SELECT o.* INTO v_o FROM commerce.orders o
    JOIN commerce.payments p ON p.store_id = o.store_id AND p.order_id = o.id
   WHERE p.store_id = v_r.store_id AND p.id = v_r.payment_id;
  IF NOT FOUND OR v_o.customer_id IS NULL OR v_o.copied_from IS NOT NULL THEN
    RETURN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM commerce.customers c WHERE c.store_id = v_o.store_id AND c.id = v_o.customer_id) THEN
    RETURN;
  END IF;
  -- A change's payment that was never applied with it (D174: it came too late and is given back in full) is not the order's money.
  IF NOT commerce.payment_of_order(v_r.store_id, v_r.payment_id) THEN
    RETURN;
  END IF;
  SELECT coalesce(sum(p.amount_minor), 0) INTO v_paid FROM commerce.payments p
   WHERE p.store_id = v_o.store_id AND p.order_id = v_o.id AND p.status = 'captured' AND p.provider IN ('stripe', 'exchange', 'gift_card') /* D239 exchange base, D300 gift cards */
     AND commerce.payment_of_order(p.store_id, p.id);
  SELECT coalesce(sum(r.amount_minor), 0) INTO v_refunded FROM commerce.refunds r
    JOIN commerce.payments p ON p.store_id = r.store_id AND p.id = r.payment_id
   WHERE p.store_id = v_o.store_id AND p.order_id = v_o.id AND r.status <> 'failed'
     AND commerce.payment_of_order(p.store_id, p.id);
  IF v_paid <= 0 THEN
    RETURN;
  END IF;

  SELECT e.id, e.amount_minor INTO v_lot, v_granted FROM commerce.bonus_entries e
   WHERE e.store_id = v_o.store_id AND e.idempotency_key = 'earn:' || v_o.id;
  IF v_lot IS NOT NULL THEN
    v_target := CASE WHEN v_refunded >= v_paid THEN v_granted ELSE floor(v_granted::numeric * v_refunded / v_paid)::bigint END;
    SELECT coalesce(-sum(e.amount_minor), 0) INTO v_done FROM commerce.bonus_entries e
     WHERE e.store_id = v_o.store_id AND e.order_id = v_o.id AND e.kind = 'reverse';
    PERFORM commerce.bonus_take(v_o.store_id, v_o.customer_id, 'reverse', v_target - v_done, 'lot', v_lot, v_o.id, p_refund,
                                'refunded', NULL, 'reverse:' || p_refund);
  END IF;

  SELECT coalesce(-e.amount_minor, 0) INTO v_used FROM commerce.bonus_entries e
   WHERE e.store_id = v_o.store_id AND e.idempotency_key = 'redeem:' || v_o.id;
  IF coalesce(v_used, 0) > 0 THEN
    v_target := CASE WHEN v_refunded >= v_paid THEN v_used ELSE floor(v_used::numeric * v_refunded / v_paid)::bigint END;
    SELECT coalesce(sum(e.amount_minor), 0) INTO v_done FROM commerce.bonus_entries e
     WHERE e.store_id = v_o.store_id AND e.order_id = v_o.id AND e.kind = 'restore';
    PERFORM commerce.bonus_restore(v_o.id, v_target - v_done, p_refund, 'restore:' || p_refund, 'refunded');
  END IF;
END;
$$;


--
-- Name: bonus_restore(uuid, bigint, uuid, text, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_restore(p_order uuid, p_amount bigint, p_refund uuid, p_key text, p_note text) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_o commerce.orders%ROWTYPE;
BEGIN
  SELECT * INTO v_o FROM commerce.orders WHERE id = p_order;
  IF NOT FOUND OR v_o.customer_id IS NULL OR p_amount <= 0 THEN
    RETURN 0;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM commerce.customers c WHERE c.store_id = v_o.store_id AND c.id = v_o.customer_id) THEN
    RETURN 0;
  END IF;
  PERFORM commerce.bonus_grant(v_o.store_id, v_o.customer_id, 'restore', p_amount, p_order, p_refund, now(),
                               commerce.bonus_expiry_from(v_o.store_id, now()), p_note, NULL, p_key);
  RETURN p_amount;
END;
$$;


--
-- Name: bonus_resume(uuid, timestamp with time zone); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_resume(p_store uuid, p_since timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_lot record;
  v_taken bigint;
  v_count integer := 0;
  v_shift interval := now() - p_since;
BEGIN
  IF p_since IS NULL OR v_shift <= interval '0' THEN
    RETURN 0;
  END IF;
  FOR v_lot IN
    SELECT e.id, e.customer_id, e.available_at, e.expires_at,
           (e.amount_minor - coalesce((SELECT sum(a.amount_minor) FROM commerce.bonus_allocations a
                                        WHERE a.store_id = e.store_id AND a.lot_id = e.id), 0))::bigint AS remaining
      FROM commerce.bonus_entries e
     WHERE e.store_id = p_store AND e.amount_minor > 0 AND e.expires_at IS NOT NULL
       AND e.expires_at >= p_since AND e.expires_at <= now()
     ORDER BY e.expires_at, e.id
  LOOP
    CONTINUE WHEN v_lot.remaining <= 0;
    v_taken := commerce.bonus_take(p_store, v_lot.customer_id, 'expire', v_lot.remaining, 'lot', v_lot.id, NULL::uuid, NULL::uuid,
                                   'the bonus program was off when these credits expired: moved', NULL::uuid, 'expire-paused:' || v_lot.id);
    IF v_taken > 0 THEN
      PERFORM commerce.bonus_grant(p_store, v_lot.customer_id, 'restore', v_taken, NULL::uuid, NULL::uuid,
                                   coalesce(v_lot.available_at, now()), v_lot.expires_at + v_shift,
                                   'the bonus program was off when these credits expired', NULL::uuid, 'resume:' || v_lot.id);
      v_count := v_count + 1;
    END IF;
  END LOOP;
  RETURN v_count;
END;
$$;


--
-- Name: bonus_settings_pause(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_settings_pause() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_on boolean := NEW.enabled AND commerce.feature_on(NEW.store_id, 'bonus');
  v_since timestamptz := CASE WHEN TG_OP = 'UPDATE' THEN OLD.paused_at END;
BEGIN
  IF v_on THEN
    IF v_since IS NOT NULL THEN
      PERFORM commerce.bonus_resume(NEW.store_id, v_since);
    END IF;
    NEW.paused_at := NULL;
  ELSE
    NEW.paused_at := coalesce(v_since, NEW.paused_at, now());
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: bonus_signup_grant(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_signup_grant() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_s commerce.bonus_settings%ROWTYPE;
BEGIN
  IF NEW.email_verified_at IS NULL OR (TG_OP = 'UPDATE' AND OLD.email_verified_at IS NOT NULL) THEN RETURN NEW; END IF;
  SELECT * INTO v_s FROM commerce.bonus_settings WHERE store_id = NEW.store_id;
  IF NOT FOUND OR v_s.signup_minor <= 0 OR NOT commerce.bonus_program_on(NEW.store_id) THEN RETURN NEW; END IF;
  IF NOT commerce.store_is_active(NEW.store_id) OR EXISTS (SELECT 1 FROM commerce.stores s WHERE s.id = NEW.store_id AND s.is_template) THEN RETURN NEW; END IF;
  PERFORM commerce.bonus_grant(NEW.store_id, NEW.id, 'signup', v_s.signup_minor, NULL, NULL, now(),
                               commerce.bonus_expiry_from(NEW.store_id, now()), '', NULL, 'signup:' || NEW.id);
  RETURN NEW;
END;
$$;


--
-- Name: bonus_take(uuid, uuid, text, bigint, text, uuid, uuid, uuid, text, uuid, text, boolean); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_take(p_store uuid, p_customer uuid, p_kind text, p_amount bigint, p_scope text, p_lot uuid, p_order uuid, p_refund uuid, p_note text, p_by uuid, p_key text, p_exact boolean DEFAULT false) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_done bigint;
  v_room bigint;
  v_amount bigint;
  v_id uuid;
  v_lot record;
  v_left bigint;
  v_take bigint;
BEGIN
  PERFORM commerce.bonus_lock(p_store, p_customer);
  SELECT -e.amount_minor INTO v_done FROM commerce.bonus_entries e WHERE e.store_id = p_store AND e.idempotency_key = p_key;
  IF FOUND THEN
    RETURN v_done;
  END IF;
  IF p_amount <= 0 THEN
    RETURN 0;
  END IF;
  SELECT coalesce(sum(u.remaining), 0) INTO v_room FROM commerce.bonus_usable_lots(p_store, p_customer, p_scope, p_lot) u;
  v_amount := least(p_amount, v_room);
  IF p_exact AND v_amount < p_amount THEN
    RAISE EXCEPTION 'bonus.insufficient';
  END IF;
  IF v_amount <= 0 THEN
    RETURN 0;
  END IF;
  INSERT INTO commerce.bonus_entries (store_id, customer_id, kind, amount_minor, order_id, refund_id, note, created_by, idempotency_key)
  VALUES (p_store, p_customer, p_kind, -v_amount, p_order, p_refund, coalesce(p_note, ''), p_by, p_key)
  RETURNING id INTO v_id;
  v_left := v_amount;
  FOR v_lot IN SELECT u.id, u.remaining FROM commerce.bonus_usable_lots(p_store, p_customer, p_scope, p_lot) u LOOP
    EXIT WHEN v_left = 0;
    v_take := least(v_lot.remaining, v_left);
    INSERT INTO commerce.bonus_allocations (store_id, lot_id, entry_id, amount_minor) VALUES (p_store, v_lot.id, v_id, v_take);
    v_left := v_left - v_take;
  END LOOP;
  RETURN v_amount;
END;
$$;


--
-- Name: bonus_usable_lots(uuid, uuid, text, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_usable_lots(p_store uuid, p_customer uuid, p_scope text, p_lot uuid) RETURNS TABLE(id uuid, remaining bigint)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT l.id, l.remaining
    FROM commerce.bonus_lots(p_store, p_customer) l
   WHERE l.remaining > 0
     AND CASE p_scope
           WHEN 'available' THEN l.available_at <= now() AND (l.expires_at IS NULL OR l.expires_at > now())
           WHEN 'any' THEN l.expires_at IS NULL OR l.expires_at > now()
           ELSE l.id = p_lot
         END
   ORDER BY (l.available_at <= now()) DESC, coalesce(l.expires_at, 'infinity'::timestamptz), l.available_at, l.created_at, l.id
$$;


--
-- Name: bonus_verify(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bonus_verify(p_store uuid, p_customer uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce((SELECT sum(e.amount_minor) FROM commerce.bonus_entries e
                    WHERE e.store_id = p_store AND e.customer_id = p_customer), 0)
       = coalesce((SELECT sum(l.remaining) FROM commerce.bonus_lots(p_store, p_customer) l), 0)
     AND NOT EXISTS (SELECT 1 FROM commerce.bonus_lots(p_store, p_customer) l WHERE l.remaining < 0)
$$;


--
-- Name: books_inbox_fixed(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.books_inbox_fixed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'books_inbox.fixed: a document of the inbox is never deleted' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.status <> 'waiting'
     OR (to_jsonb(NEW) - 'status' - 'entry_id' - 'decided_at' - 'decided_by') IS DISTINCT FROM (to_jsonb(OLD) - 'status' - 'entry_id' - 'decided_at' - 'decided_by') THEN
    RAISE EXCEPTION 'books_inbox.fixed: a document changes only when it is used or set aside, once' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: break_amounts_ok(jsonb, integer); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.break_amounts_ok(p_amounts jsonb, p_key_length integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  SELECT jsonb_typeof(p_amounts) = 'object' AND p_amounts <> '{}'::jsonb
     AND NOT EXISTS (
       SELECT 1 FROM jsonb_each(p_amounts) AS e(key, value)
        WHERE e.key !~ ('^[A-Z]{' || p_key_length || '}$')
           OR jsonb_typeof(e.value) <> 'number'
           OR (e.value #>> '{}')::numeric < 0
           OR (e.value #>> '{}')::numeric <> trunc((e.value #>> '{}')::numeric)
     )
$_$;


--
-- Name: broadcast_recipients_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.broadcast_recipients_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NOT EXISTS (
      SELECT 1 FROM commerce.broadcasts b WHERE b.id = NEW.broadcast_id AND b.store_id = NEW.store_id AND b.status = 'sending'
    ) THEN
      RAISE EXCEPTION 'broadcast_recipients.frozen: recipients are frozen only when a send starts' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status <> 'queued' THEN
      RAISE EXCEPTION 'broadcast_recipients.status: a recipient starts queued' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.store_id <> OLD.store_id OR NEW.broadcast_id <> OLD.broadcast_id OR NEW.subscriber_id <> OLD.subscriber_id
    OR NEW.email <> OLD.email OR NEW.locale <> OLD.locale OR NEW.market_code IS DISTINCT FROM OLD.market_code THEN
    RAISE EXCEPTION 'broadcast_recipients.identity: a recipient stays the address it was' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status <> OLD.status AND NOT (OLD.status = 'queued' AND NEW.status IN ('sent', 'failed', 'skipped')) THEN
    RAISE EXCEPTION 'broadcast_recipients.status: % cannot become %', OLD.status, NEW.status USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status = 'skipped' AND NEW.skip_reason IS NULL THEN
    RAISE EXCEPTION 'broadcast_recipients.skip: a skipped recipient says why' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: broadcasts_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.broadcasts_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status <> 'draft' THEN
      RAISE EXCEPTION 'broadcasts.delete: only a draft is deleted' USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  END IF;

  IF NEW.segment_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM commerce.segments s WHERE s.id = NEW.segment_id AND s.store_id = NEW.store_id
  ) THEN
    RAISE EXCEPTION 'broadcasts.segment: the segment is another store''s' USING ERRCODE = 'check_violation';
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'broadcasts.status: a broadcast starts as a draft' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.id <> OLD.id OR NEW.store_id <> OLD.store_id THEN
    RAISE EXCEPTION 'broadcasts.identity: a broadcast stays itself' USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.status <> OLD.status AND NOT (
    (OLD.status = 'draft' AND NEW.status IN ('scheduled', 'sending'))
    OR (OLD.status = 'scheduled' AND NEW.status IN ('draft', 'sending'))
    OR (OLD.status = 'sending' AND NEW.status IN ('sent', 'cancelled'))
  ) THEN
    RAISE EXCEPTION 'broadcasts.status: % cannot become %', OLD.status, NEW.status USING ERRCODE = 'check_violation';
  END IF;

  -- Once a send starts, its words, its audience and when it started stay as they were. A deleted segment may still clear `segment_id`.
  IF OLD.status IN ('sending', 'sent', 'cancelled') AND (
    NEW.title IS DISTINCT FROM OLD.title
    OR NEW.audience IS DISTINCT FROM OLD.audience
    OR (NEW.segment_id IS DISTINCT FROM OLD.segment_id AND NEW.segment_id IS NOT NULL)
    OR NEW.content IS DISTINCT FROM OLD.content
    OR NEW.started_at IS DISTINCT FROM OLD.started_at
    OR NEW.audience_words IS DISTINCT FROM OLD.audience_words
  ) THEN
    RAISE EXCEPTION 'broadcasts.fixed: a broadcast that was sent keeps what it said and who it went to' USING ERRCODE = 'check_violation';
  END IF;
  -- The count is written once the send's addresses are frozen, in the same transaction that starts it.
  IF OLD.status IN ('sent', 'cancelled') AND (NEW.finished_at IS DISTINCT FROM OLD.finished_at OR NEW.recipient_count IS DISTINCT FROM OLD.recipient_count) THEN
    RAISE EXCEPTION 'broadcasts.fixed: a finished broadcast keeps when it ended and how many it went to' USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.status = 'scheduled' AND NEW.scheduled_for IS NULL THEN
    RAISE EXCEPTION 'broadcasts.scheduled: a scheduled broadcast needs its time' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status IN ('sending', 'sent', 'cancelled') AND NEW.started_at IS NULL THEN
    RAISE EXCEPTION 'broadcasts.started: a send needs its start' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status IN ('sent', 'cancelled') AND NEW.finished_at IS NULL THEN
    RAISE EXCEPTION 'broadcasts.finished: a finished send needs its end' USING ERRCODE = 'check_violation';
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: bucket_index(numeric[], text[], numeric, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bucket_index(p_rates numeric[], p_basis text[], p_rate numeric, p_b text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce((SELECT i FROM generate_subscripts(p_rates, 1) AS i WHERE p_rates[i] = p_rate AND p_basis[i] = p_b ORDER BY i LIMIT 1), 0)
$$;


--
-- Name: build_invoice_snapshot(uuid, date, date); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.build_invoice_snapshot(p_order uuid, p_issued_on date, p_supply_date date) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  o commerce.orders%ROWTYPE;
  st commerce.stores%ROWTYPE;
  prof record;
  cfg commerce.invoice_settings%ROWTYPE;
  v_have boolean;
  v_tz text;
  rc boolean;
  v_lines jsonb;
  v_deferred jsonb;
  v_lines_total bigint;
  v_lines_tax bigint;
  v_physical boolean;
  v_rounded boolean;
  v_ship_gross bigint;
  v_ship_vat bigint;
  v_ship_net bigint;
  v_ship_rate numeric;
  v_ship_list bigint;
  v_ship jsonb;
  v_buckets jsonb;
  v_net bigint;
  v_vat bigint;
  v_gross bigint;
  v_code bigint;
  v_discounts jsonb;
  v_exempt boolean;
  v_statements jsonb;
  v_seller_vat text;
  v_buyer_vat text;
  v_home text;
  v_fx numeric;
  v_vat_home jsonb := NULL;
  v_vat_main jsonb := NULL;
  v_main text;
  v_payments jsonb;
  v_terms jsonb := NULL;
  v_settled bigint := 0;
  v_cards bigint := 0;
  v_cards_last4 jsonb := '[]'::jsonb;
  v_settled_from jsonb := NULL;
  v_online bigint;
  v_provider text;
  v_notes jsonb;
  v_b jsonb;
  v_billing jsonb;
  v_shipping_addr jsonb;
  v_pick jsonb;
  v_complete boolean;
  v_place jsonb;
BEGIN
  SELECT * INTO o FROM commerce.orders WHERE id = p_order;
  SELECT * INTO st FROM commerce.stores WHERE id = o.store_id;
  SELECT * INTO prof FROM commerce.store_tax_profile WHERE store_id = o.store_id;
  v_have := FOUND;
  SELECT * INTO cfg FROM commerce.invoice_settings WHERE store_id = o.store_id;
  v_tz := st.time_zone;
  rc := o.vat_kind = 'reverse_charge';

  -- Lines.
  WITH base AS (
    SELECT ol.ctid AS ord, ol.id, ol.sku, ol.title, ol.quantity, ol.unit_price_minor, ol.total_minor, ol.tax_minor, ol.tax_rate,
           ol.delivery, ol.gift, ol.booked_count, p.vat_category, bk.starts_at, bk.ends_at,
           (ol.selling_plan_id IS NOT NULL AND ol.unit_price_minor = 0 AND ol.total_minor = 0 AND NOT ol.gift) AS deferred
      FROM commerce.order_lines ol
      LEFT JOIN commerce.product_variants v ON v.store_id = ol.store_id AND v.id = ol.variant_id
      LEFT JOIN commerce.products p ON p.store_id = v.store_id AND p.id = v.product_id
      LEFT JOIN LATERAL (
        SELECT b.starts_at, b.ends_at FROM commerce.bookings b
         WHERE b.store_id = ol.store_id AND b.order_line_id = ol.id ORDER BY b.starts_at LIMIT 1
      ) bk ON true
     WHERE ol.store_id = o.store_id AND ol.order_id = o.id
  ), c1 AS (
    SELECT base.*,
           CASE WHEN rc THEN 0 ELSE tax_minor END AS vat,
           total_minor - CASE WHEN rc THEN 0 ELSE tax_minor END AS net
      FROM base
  ), c2 AS (
    SELECT c1.*,
           greatest(unit_price_minor * quantity - commerce.vat_incl(unit_price_minor * quantity, tax_rate), net) AS list_net
      FROM c1
  ), c3 AS (
    SELECT c2.*, (2 * list_net + quantity) / (2 * quantity::bigint) AS unit_net FROM c2
  )
  SELECT
    coalesce(jsonb_agg(jsonb_build_object(
      'lineId', id, 'sku', sku, 'title', title,
      'kind', CASE WHEN gift THEN 'gift' WHEN sku = 'SIGNUP-FEE' THEN 'fee' WHEN starts_at IS NOT NULL THEN 'booking'
                   WHEN delivery = 'digital' THEN 'download' WHEN delivery = 'service' THEN 'service' ELSE 'goods' END,
      'quantity', quantity, 'listNetMinor', list_net, 'discountNetMinor', list_net - net, 'netMinor', net,
      'vatRate', CASE WHEN rc THEN 0 ELSE tax_rate END,
      'basis', CASE WHEN rc THEN 'reverse_charge' WHEN vat_category = 'exempt' THEN 'exempt' ELSE 'standard' END,
      'vatMinor', vat, 'grossMinor', total_minor, 'unitNetMinor', unit_net,
      'serviceDate', CASE WHEN starts_at IS NOT NULL THEN to_char(starts_at AT TIME ZONE v_tz, 'YYYY-MM-DD') END,
      'service', CASE WHEN starts_at IS NOT NULL THEN jsonb_build_object(
          'startsAt', to_char(starts_at AT TIME ZONE v_tz, 'YYYY-MM-DD"T"HH24:MI'),
          'endsAt', to_char(ends_at AT TIME ZONE v_tz, 'YYYY-MM-DD"T"HH24:MI'), 'count', booked_count) END,
      'wouldHaveRate', CASE WHEN rc THEN tax_rate END
    ) || CASE WHEN vat_category = 'voucher' THEN '{"voucher": true}'::jsonb ELSE '{}'::jsonb END ORDER BY ord) FILTER (WHERE NOT deferred), '[]'::jsonb),
    coalesce(jsonb_agg(jsonb_build_object('lineId', id, 'title', title, 'grossMinor', NULL::bigint) ORDER BY ord) FILTER (WHERE deferred), '[]'::jsonb),
    coalesce(sum(total_minor), 0)::bigint, coalesce(sum(tax_minor), 0)::bigint,
    coalesce(bool_or(delivery = 'physical'), false),
    coalesce(bool_or(unit_net * quantity <> list_net) FILTER (WHERE NOT deferred), false)
    INTO v_lines, v_deferred, v_lines_total, v_lines_tax, v_physical, v_rounded
    FROM c3;

  -- Shipping: what the shopper paid for delivery after any discount and relief is the rest of the order's total.
  v_ship_gross := o.total_minor - v_lines_total;
  v_ship_vat := CASE WHEN rc THEN 0 ELSE o.tax_minor - v_lines_tax END;
  v_ship_net := v_ship_gross - v_ship_vat;
  v_ship_rate := coalesce(o.shipping_tax_rate, CASE WHEN o.shipping_minor > 0 THEN commerce.vat_rate(o.market_code, 'standard', o.placed_at) END, 0);
  v_ship_list := greatest(o.shipping_minor - commerce.vat_incl(o.shipping_minor, v_ship_rate), v_ship_net);
  IF o.shipping_minor = 0 AND v_ship_gross = 0 THEN
    v_ship := NULL;
  ELSE
    v_ship := jsonb_build_object(
      'label', commerce.nz(o.delivery ->> 'label'), 'netBeforeMinor', v_ship_list, 'discountNetMinor', v_ship_list - v_ship_net,
      'netMinor', v_ship_net, 'vatRate', CASE WHEN rc THEN 0 ELSE v_ship_rate END,
      'basis', CASE WHEN rc THEN 'reverse_charge' ELSE 'standard' END, 'vatMinor', v_ship_vat, 'grossMinor', v_ship_gross,
      'wouldHaveRate', CASE WHEN rc THEN v_ship_rate END);
  END IF;

  -- The VAT per rate: one bucket per rate and basis, highest rate first.
  SELECT coalesce(jsonb_agg(jsonb_build_object('rate', rate, 'basis', basis, 'netMinor', n, 'vatMinor', v, 'grossMinor', g) ORDER BY rate DESC, basis), '[]'::jsonb)
    INTO v_buckets
    FROM (
      SELECT rate, basis, sum(n)::bigint AS n, sum(v)::bigint AS v, sum(g)::bigint AS g FROM (
        SELECT (l ->> 'vatRate')::numeric AS rate, l ->> 'basis' AS basis, (l ->> 'netMinor')::bigint AS n, (l ->> 'vatMinor')::bigint AS v, (l ->> 'grossMinor')::bigint AS g
          FROM jsonb_array_elements(v_lines) AS l
        UNION ALL
        SELECT (v_ship ->> 'vatRate')::numeric, v_ship ->> 'basis', (v_ship ->> 'netMinor')::bigint, (v_ship ->> 'vatMinor')::bigint, (v_ship ->> 'grossMinor')::bigint
         WHERE v_ship IS NOT NULL
      ) x GROUP BY rate, basis HAVING sum(n) <> 0 OR sum(v) <> 0 OR sum(g) <> 0
    ) y;
  SELECT coalesce(sum((b ->> 'netMinor')::bigint), 0), coalesce(sum((b ->> 'vatMinor')::bigint), 0), coalesce(sum((b ->> 'grossMinor')::bigint), 0),
         coalesce(bool_or(b ->> 'basis' = 'exempt'), false)
    INTO v_net, v_vat, v_gross, v_exempt FROM jsonb_array_elements(v_buckets) AS b;

  -- The discounts as the shopper saw them (VAT-inclusive, informational); the code's is what is left of the order's.
  v_code := o.discount_minor - o.member_discount_minor - o.campaign_discount_minor - o.credit_minor - o.referral_discount_minor - o.vat_relief_minor - o.staff_discount_minor;
  SELECT coalesce(jsonb_agg(jsonb_build_object('kind', k, 'label', lbl, 'grossMinor', amt) ORDER BY ord), '[]'::jsonb) INTO v_discounts
    FROM (VALUES
      (1, 'campaign', commerce.nz(o.campaign_label), o.campaign_discount_minor),
      (2, 'member', commerce.nz(o.member_label), o.member_discount_minor),
      (3, 'welcome', NULL::text, o.referral_discount_minor),
      (4, 'code', commerce.nz(o.discount_code), v_code),
      (5, 'staff', commerce.nz(o.staff_discount_label), o.staff_discount_minor),
      (6, 'credit', NULL::text, o.credit_minor)
    ) AS d(ord, k, lbl, amt) WHERE amt > 0;

  -- The treatment is the order's, frozen when it was placed; the invoice never decides VAT.
  v_seller_vat := commerce.invoice_seller_vat(p_order);
  v_buyer_vat := CASE WHEN rc THEN commerce.nz(o.vat_treatment ->> 'buyerVatNumber') END;
  SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY ord), '[]'::jsonb) INTO v_statements
    FROM (VALUES
      (1, 'reverse_charge', rc),
      (2, 'ioss', o.vat_kind = 'ioss'),
      (3, 'not_registered', v_have AND NOT coalesce(prof.vat_registered, false)),
      (4, 'exempt', v_exempt)
    ) AS t(ord, s, cond) WHERE cond;

  -- The VAT in the seller's currency (Directive Art. 230), and in the store's main currency for the reports.
  SELECT c.currency::text INTO v_home FROM commerce.countries c WHERE c.code = st.country;
  IF v_vat > 0 AND commerce.home_vat_required(st.country::text, o.currency::text, v_home) THEN
    v_fx := commerce.fx_factor(o.store_id, o.currency::text, v_home);
    IF v_fx IS NOT NULL THEN
      v_vat_home := jsonb_build_object(
        'currency', v_home,
        'vatMinor', (SELECT coalesce(sum(commerce.convert_with((b ->> 'vatMinor')::bigint, v_fx)), 0) FROM jsonb_array_elements(v_buckets) AS b),
        'fxRate', v_fx, 'asOf', to_char(commerce.fx_as_of(o.store_id, o.currency::text, v_home), 'YYYY-MM-DD'),
        'source', CASE WHEN st.rates_auto THEN 'ecb_auto' ELSE 'owner' END);
    END IF;
  END IF;
  v_main := commerce.main_currency(o.store_id);
  IF o.currency::text = v_main THEN
    v_vat_main := jsonb_build_object('currency', v_main, 'vatMinor', v_vat, 'fxRate', NULL::numeric);
  ELSE
    v_fx := commerce.fx_factor(o.store_id, o.currency::text, v_main);
    IF v_fx IS NOT NULL THEN
      v_vat_main := jsonb_build_object(
        'currency', v_main,
        'vatMinor', (SELECT coalesce(sum(commerce.convert_with((b ->> 'vatMinor')::bigint, v_fx)), 0) FROM jsonb_array_elements(v_buckets) AS b),
        'fxRate', v_fx);
    END IF;
  END IF;

  -- Payment: what was paid online and what is left for the venue.
  v_online := o.total_minor - o.balance_minor;
  -- Exchanges (D239): the part paid with the credit of a return, named by the return and its order; the rest is paid online or outside.
  SELECT coalesce(sum(p.amount_minor), 0) INTO v_settled FROM commerce.payments p
   WHERE p.store_id = o.store_id AND p.order_id = o.id AND p.provider = 'exchange' AND p.status NOT IN ('failed', 'cancelled');
  IF v_settled > 0 THEN
    SELECT jsonb_build_object('returnNumber', rt.number, 'orderNumber', oo.number) INTO v_settled_from
      FROM commerce.return_exchanges x
      JOIN commerce.returns rt ON rt.store_id = x.store_id AND rt.id = x.return_id
      JOIN commerce.orders oo ON oo.store_id = x.store_id AND oo.id = x.order_id
     WHERE x.store_id = o.store_id AND x.id = o.exchange_id;
    v_online := v_online - v_settled;
  END IF;
  -- Gift cards (D300 F3): the part they paid, named by each card's last four; the rest is paid online or outside.
  SELECT coalesce(sum(p.amount_minor), 0), coalesce(jsonb_agg(g.last4 ORDER BY p.created_at, p.id), '[]'::jsonb) INTO v_cards, v_cards_last4
    FROM commerce.payments p JOIN commerce.gift_cards g ON g.store_id = p.store_id AND g.id = p.gift_card_id
   WHERE p.store_id = o.store_id AND p.order_id = o.id AND p.provider = 'gift_card' AND p.status NOT IN ('failed', 'cancelled');
  v_online := v_online - v_cards;
  SELECT p.provider INTO v_provider FROM commerce.payments p
   WHERE p.store_id = o.store_id AND p.order_id = o.id AND p.provider NOT IN ('venue', 'exchange', 'terms', 'gift_card') AND p.status NOT IN ('failed', 'cancelled')
   ORDER BY p.created_at, p.id LIMIT 1;
  v_provider := coalesce(v_provider, 'stripe');
  -- Payment terms (D293): the balance of an order bought on terms is due by its day, not left for a venue.
  SELECT jsonb_build_object('dueOn', to_char(t.due_on, 'YYYY-MM-DD'), 'terms', t.terms) INTO v_terms
    FROM commerce.order_payment_terms t WHERE t.store_id = o.store_id AND t.order_id = o.id;
  SELECT coalesce(jsonb_agg(x ORDER BY ord), '[]'::jsonb) INTO v_payments FROM (
    SELECT 0 AS ord, jsonb_build_object('kind', 'settled_by_return', 'amountMinor', v_settled, 'provider', 'exchange',
      'returnNumber', v_settled_from ->> 'returnNumber', 'orderNumber', v_settled_from ->> 'orderNumber') AS x WHERE v_settled > 0
    UNION ALL
    SELECT 0, jsonb_build_object('kind', 'paid_gift_card', 'amountMinor', v_cards, 'provider', 'gift_card', 'cards', v_cards_last4) WHERE v_cards > 0
    UNION ALL
    SELECT 1 AS ord, CASE WHEN v_provider = 'manual' THEN jsonb_build_object('kind', 'paid_outside', 'amountMinor', v_online, 'provider', 'manual',
      'method', (SELECT p.method FROM commerce.payments p WHERE p.store_id = o.store_id AND p.order_id = o.id AND p.provider = 'manual' AND p.status NOT IN ('failed', 'cancelled') ORDER BY p.created_at, p.id LIMIT 1))
      ELSE jsonb_build_object('kind', 'paid_online', 'amountMinor', v_online, 'provider', v_provider) END AS x WHERE v_online > 0
    UNION ALL
    SELECT 2, CASE WHEN v_terms IS NOT NULL
                   THEN jsonb_build_object('kind', 'due', 'amountMinor', o.balance_minor, 'provider', 'terms', 'dueOn', v_terms ->> 'dueOn', 'terms', v_terms ->> 'terms')
                   ELSE jsonb_build_object('kind', 'pay_at_venue', 'amountMinor', o.balance_minor, 'provider', 'venue') END
     WHERE o.balance_minor > 0
  ) pp;

  -- The buyer: the billing address if it has a street line, else the shipping address, else only the name, the email and the market's country.
  v_billing := coalesce(o.billing_address, '{}'::jsonb);
  v_shipping_addr := coalesce(o.shipping_address, '{}'::jsonb);
  v_pick := CASE WHEN commerce.nz(v_billing ->> 'line1') IS NOT NULL THEN v_billing
                 WHEN commerce.nz(v_shipping_addr ->> 'line1') IS NOT NULL THEN v_shipping_addr END;
  v_complete := v_pick IS NOT NULL;
  v_b := jsonb_build_object(
    'type', CASE WHEN commerce.nz(o.company_name) IS NOT NULL THEN 'business' ELSE 'consumer' END,
    'name', coalesce(commerce.nz(v_pick ->> 'name'), commerce.nz(v_billing ->> 'name'), commerce.nz(v_shipping_addr ->> 'name')),
    'company', commerce.nz(o.company_name), 'organisationNumber', commerce.nz(o.organisation_number), 'vatNumber', v_buyer_vat,
    'address', CASE WHEN v_complete THEN jsonb_build_object(
        'line1', commerce.nz(v_pick ->> 'line1'), 'line2', commerce.nz(v_pick ->> 'line2'), 'postalCode', commerce.nz(v_pick ->> 'postalCode'),
        'city', commerce.nz(v_pick ->> 'city'), 'country', coalesce(commerce.nz(v_pick ->> 'country'), o.market_code::text))
      ELSE jsonb_build_object('line1', NULL::text, 'line2', NULL::text, 'postalCode', NULL::text, 'city', NULL::text,
        'country', coalesce(commerce.nz(v_billing ->> 'country'), commerce.nz(v_shipping_addr ->> 'country'), o.market_code::text)) END,
    'email', o.email, 'complete', v_complete);

  v_place := CASE WHEN v_physical AND (commerce.nz(v_shipping_addr ->> 'city') IS NOT NULL OR commerce.nz(v_shipping_addr ->> 'country') IS NOT NULL)
    THEN jsonb_build_object('city', commerce.nz(v_shipping_addr ->> 'city'), 'country', coalesce(commerce.nz(v_shipping_addr ->> 'country'), o.market_code::text)) END;

  SELECT coalesce(jsonb_agg(n ORDER BY ord), '[]'::jsonb) INTO v_notes FROM (VALUES
    (1, 'buyer_incomplete', NOT v_complete),
    (2, 'unit_price_rounded', v_rounded),
    (3, 'trial_deferred', jsonb_array_length(v_deferred) > 0)
  ) AS t(ord, n, cond) WHERE cond;

  RETURN jsonb_build_object(
    'version', 1, 'documentType', 'invoice', 'issuedOn', to_char(p_issued_on, 'YYYY-MM-DD'), 'supplyDate', to_char(p_supply_date, 'YYYY-MM-DD'),
    'locale', o.locale, 'language', commerce.doc_language(o.locale), 'currency', o.currency,
    'seller', jsonb_build_object(
      'legalName', commerce.nz(st.legal_name), 'organisationNumber', commerce.nz(st.organisation_number),
      'vatRegistered', CASE WHEN v_have THEN prof.vat_registered ELSE false END, 'vatNumber', v_seller_vat,
      'address', commerce.nz(st.postal_address), 'country', st.country, 'email', commerce.nz(st.contact_email),
      'footerNote', commerce.nz(cfg.footer_note)),
    'buyer', v_b,
    'order', jsonb_build_object(
      'number', o.number, 'placedOn', to_char(commerce.store_day(o.store_id, o.placed_at), 'YYYY-MM-DD'),
      'paidOn', to_char(p_supply_date, 'YYYY-MM-DD'), 'deliveryPlace', v_place),
    'lines', v_lines, 'shipping', v_ship, 'discounts', v_discounts, 'buckets', v_buckets,
    'totals', jsonb_build_object('netMinor', v_net, 'vatMinor', v_vat, 'grossMinor', v_gross),
    'vatHome', v_vat_home, 'vatMain', v_vat_main,
    'treatment', jsonb_build_object(
      'kind', o.vat_kind, 'reason', commerce.nz(o.vat_treatment ->> 'reason'), 'sellerVatNumber', v_seller_vat, 'buyerVatNumber', v_buyer_vat,
      'iossNumber', CASE WHEN o.vat_kind = 'ioss' THEN commerce.nz(o.vat_treatment ->> 'iossNumber') END, 'statements', v_statements),
    'payments', v_payments, 'deferred', v_deferred, 'notes', v_notes);
END;
$$;


--
-- Name: bulk_edit_batches_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bulk_edit_batches_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_target commerce.bulk_edit_batches%ROWTYPE;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.undone_at IS NOT NULL THEN
      RAISE EXCEPTION 'bulk_edit.undone: a batch is made before it is undone' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.action = 'undo' THEN
      SELECT * INTO v_target FROM commerce.bulk_edit_batches WHERE store_id = NEW.store_id AND id = NEW.undo_of;
      IF v_target.action = 'undo' THEN
        RAISE EXCEPTION 'bulk_edit.undo_of_undo: an undo is not undone; make the change again' USING ERRCODE = 'check_violation';
      END IF;
      IF v_target.created_at < now() - interval '7 days' THEN
        RAISE EXCEPTION 'bulk_edit.undo_expired: a change can be undone for seven days' USING ERRCODE = 'check_violation';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE: only `undone_at`, once, and only when its undo is there.
  IF NEW.id <> OLD.id OR NEW.store_id <> OLD.store_id OR NEW.requested_by <> OLD.requested_by OR NEW.action <> OLD.action
     OR NEW.params IS DISTINCT FROM OLD.params OR NEW.undo_of IS DISTINCT FROM OLD.undo_of
     OR NEW.counts IS DISTINCT FROM OLD.counts OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'bulk_edit.append_only: a bulk edit is a record and is not changed' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.undone_at IS DISTINCT FROM OLD.undone_at THEN
    IF OLD.undone_at IS NOT NULL OR NEW.undone_at IS NULL THEN
      RAISE EXCEPTION 'bulk_edit.append_only: a batch is marked undone once and not taken back' USING ERRCODE = 'check_violation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM commerce.bulk_edit_batches u WHERE u.store_id = OLD.store_id AND u.undo_of = OLD.id) THEN
      RAISE EXCEPTION 'bulk_edit.undone: a batch is marked undone when its undo was made' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: bulk_edit_items_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bulk_edit_items_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  -- UPDATE only (a removal is the retention job's). A changed cell can be marked undone; nothing else about an item changes.
  IF NEW.store_id <> OLD.store_id OR NEW.batch_id <> OLD.batch_id OR NEW.seq <> OLD.seq OR NEW.product_id <> OLD.product_id
     OR NEW.variant_id IS DISTINCT FROM OLD.variant_id OR NEW.field <> OLD.field
     OR NEW.before IS DISTINCT FROM OLD.before OR NEW.after IS DISTINCT FROM OLD.after OR NEW.reason IS DISTINCT FROM OLD.reason THEN
    RAISE EXCEPTION 'bulk_edit.append_only: a bulk edit is a record and is not changed' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.outcome <> OLD.outcome AND NOT (OLD.outcome = 'changed' AND NEW.outcome = 'undone') THEN
    RAISE EXCEPTION 'bulk_edit.append_only: only a changed cell can be marked undone' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: bundle_components_on_request(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bundle_components_on_request() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_problem text;
BEGIN
  v_problem := commerce.bundle_on_request_problem(NEW.bundle_variant_id);
  IF v_problem IS NOT NULL THEN
    RAISE EXCEPTION '%', v_problem USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: bundle_components_refresh(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bundle_components_refresh() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM commerce.refresh_bundle_prices(CASE WHEN TG_OP = 'DELETE' THEN OLD.bundle_variant_id ELSE NEW.bundle_variant_id END);
  RETURN NULL;
END;
$$;


--
-- Name: bundle_components_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bundle_components_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_problem text;
BEGIN
  v_problem := commerce.bundle_problem(NEW.bundle_variant_id);
  IF v_problem IS NOT NULL THEN
    RAISE EXCEPTION '%', v_problem USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: bundle_on_request_problem(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bundle_on_request_problem(p_bundle_variant uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT 'bundle_components.price_on_request: a bundle priced from its components cannot hold a product priced on request; give the bundle a price of its own, or show the product''s price'
    FROM commerce.bundle_components bc
    JOIN commerce.product_variants bv ON bv.store_id = bc.store_id AND bv.id = bc.bundle_variant_id
    JOIN commerce.products bp ON bp.store_id = bv.store_id AND bp.id = bv.product_id
    JOIN commerce.product_variants cv ON cv.store_id = bc.store_id AND cv.id = bc.component_variant_id
    JOIN commerce.products cp ON cp.store_id = cv.store_id AND cp.id = cv.product_id
   WHERE bc.bundle_variant_id = p_bundle_variant
     AND bp.bundle_pricing = 'computed'
     AND cp.price_on_request
   LIMIT 1
$$;


--
-- Name: bundle_problem(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.bundle_problem(p_bundle_variant uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_bundle record;
  v_bad record;
  v_count integer;
BEGIN
  SELECT v.store_id, p.kind, p.vat_category INTO v_bundle
    FROM commerce.product_variants v JOIN commerce.products p ON p.store_id = v.store_id AND p.id = v.product_id
   WHERE v.id = p_bundle_variant;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT count(*) INTO v_count FROM commerce.bundle_components WHERE bundle_variant_id = p_bundle_variant;
  IF v_count = 0 THEN RETURN NULL; END IF;
  IF v_bundle.kind <> 'bundle' THEN
    RETURN 'bundle_components.bundle: only a bundle has components';
  END IF;
  IF v_count > 20 THEN
    RETURN 'bundle_components.max: a bundle has at most 20 components';
  END IF;
  SELECT cp.kind, cv.delivery::text AS delivery, cp.vat_category INTO v_bad
    FROM commerce.bundle_components bc
    JOIN commerce.product_variants cv ON cv.store_id = bc.store_id AND cv.id = bc.component_variant_id
    JOIN commerce.products cp ON cp.store_id = cv.store_id AND cp.id = cv.product_id
   WHERE bc.bundle_variant_id = p_bundle_variant
     AND (cp.kind <> 'goods' OR cv.delivery <> 'physical' OR cp.vat_category <> v_bundle.vat_category)
   LIMIT 1;
  IF FOUND THEN
    IF v_bad.kind <> 'goods' OR v_bad.delivery <> 'physical' THEN
      RETURN 'bundle_components.goods: a component is goods sent by post';
    END IF;
    RETURN 'bundle_components.vat_category: a bundle and its components take one VAT category';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: buyer_lists(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.buyer_lists(p_store uuid, p_customer uuid) RETURNS SETOF uuid
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT DISTINCT a.list_id
  FROM commerce.customers c
  LEFT JOIN commerce.customer_tiers t ON t.store_id = c.store_id AND t.id = c.tier_id AND t.active
  LEFT JOIN commerce.customer_companies co
    ON co.store_id = c.store_id AND co.id = c.company_id AND co.active
   AND c.company_role IN ('owner', 'employee') AND commerce.feature_on(c.store_id, 'business')
  LEFT JOIN commerce.customer_tiers ct ON ct.store_id = co.store_id AND ct.id = co.tier_id AND ct.active
  JOIN commerce.price_list_assignments a
    ON a.store_id = c.store_id AND (a.tier_id = t.id OR a.company_id = co.id OR a.tier_id = ct.id)
  JOIN commerce.price_lists l ON l.store_id = a.store_id AND l.id = a.list_id AND l.active
  WHERE c.store_id = p_store AND c.id = p_customer
$$;


--
-- Name: buyer_price(uuid, uuid, uuid, character, bigint); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.buyer_price(p_store uuid, p_customer uuid, p_variant uuid, p_market character, p_base bigint) RETURNS TABLE(amount_minor bigint, list_id uuid)
    LANGUAGE sql STABLE ROWS 1
    SET search_path TO ''
    AS $$
  WITH lists AS (
    SELECT id FROM commerce.buyer_lists(p_store, p_customer) AS id WHERE p_customer IS NOT NULL
  ),
  variant AS (
    SELECT v.product_id FROM commerce.product_variants v WHERE v.store_id = p_store AND v.id = p_variant
  ),
  market AS (
    SELECT m.currency FROM commerce.markets m WHERE m.store_id = p_store AND m.code = p_market
  ),
  offers AS (
    SELECT pp.amount_minor, pp.list_id
    FROM commerce.price_list_prices pp
    JOIN market ON pp.currency = market.currency
    WHERE pp.store_id = p_store AND pp.variant_id = p_variant AND pp.list_id IN (SELECT id FROM lists)
    UNION ALL
    SELECT (p_base * (100 - l.percent) + 50) / 100, l.id
    FROM commerce.price_lists l
    CROSS JOIN variant
    WHERE l.store_id = p_store AND l.id IN (SELECT id FROM lists) AND l.percent IS NOT NULL
      AND commerce.price_list_covers(p_store, l.id, variant.product_id)
  )
  SELECT o.amount_minor, o.list_id
  FROM offers o
  WHERE p_base IS NOT NULL AND o.amount_minor < p_base
  ORDER BY o.amount_minor, o.list_id
  LIMIT 1
$$;


--
-- Name: buyer_sees(uuid, uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.buyer_sees(p_store uuid, p_customer uuid, p_product uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT NOT commerce.product_exclusive(p_store, p_product)
      OR (p_customer IS NOT NULL AND EXISTS (
            SELECT 1 FROM commerce.buyer_lists(p_store, p_customer) AS mine(id)
            JOIN commerce.price_lists l ON l.store_id = p_store AND l.id = mine.id AND l.exclusive
            WHERE EXISTS (SELECT 1 FROM commerce.price_list_products s WHERE s.store_id = l.store_id AND s.list_id = l.id)
              AND commerce.price_list_covers(p_store, l.id, p_product)
          ))
$$;


--
-- Name: cancel_unpaid_order(uuid, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.cancel_unpaid_order(p_order_id uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_order commerce.orders%ROWTYPE;
BEGIN
  SELECT * INTO v_order FROM commerce.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND OR v_order.status NOT IN ('pending_payment', 'authorized') THEN
    RETURN false;
  END IF;
  UPDATE commerce.inventory_reservations SET released_at = now()
   WHERE order_id = p_order_id AND released_at IS NULL;
  UPDATE commerce.orders SET status = 'cancelled' WHERE id = p_order_id;
  INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
  VALUES (v_order.store_id, p_order_id, 'order.cancelled', jsonb_build_object('reason', p_reason), 'system');
  RETURN true;
END;
$$;


--
-- Name: carts_delivery_note_follows(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.carts_delivery_note_follows() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF OLD.local_area_id IS NOT NULL AND NEW.local_area_id IS NULL THEN
    NEW.delivery_note := NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: check_gift_card_product(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.check_gift_card_product() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_store uuid;
  v_product uuid;
  p commerce.products%ROWTYPE;
BEGIN
  IF TG_TABLE_NAME = 'products' THEN
    v_store := NEW.store_id;
    v_product := NEW.id;
  ELSE
    v_store := NEW.store_id;
    v_product := NEW.product_id;
  END IF;
  SELECT * INTO p FROM commerce.products WHERE store_id = v_store AND id = v_product;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  IF p.kind = 'gift_card' THEN
    IF p.vat_category <> 'voucher' OR p.subscription_only OR p.host_id IS NOT NULL OR p.sold_by_measure THEN
      RAISE EXCEPTION 'gift_card.product: a gift card takes the category voucher, is sold once, by the store itself, with no unit price'
        USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (SELECT 1 FROM commerce.product_variants v
                WHERE v.store_id = v_store AND v.product_id = v_product AND (v.delivery <> 'digital' OR v.measure_amount IS NOT NULL)) THEN
      RAISE EXCEPTION 'gift_card.variants: a gift card''s amounts are delivered by email, with no measure' USING ERRCODE = 'check_violation';
    END IF;
  ELSIF p.vat_category = 'voucher' THEN
    RAISE EXCEPTION 'gift_card.voucher: the category voucher is for gift cards only' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: check_unit_price(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.check_unit_price() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_store uuid := NEW.store_id;
  v_product uuid;
  v_kind text;
  v_status commerce.product_status;
  v_skus text;
BEGIN
  IF TG_TABLE_NAME = 'products' THEN
    v_product := NEW.id;
  ELSE
    v_product := NEW.product_id;
  END IF;

  SELECT p.kind, p.status INTO v_kind, v_status
    FROM commerce.products p
   WHERE p.store_id = v_store AND p.id = v_product;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- A measure is for physical goods only: not an appointment, stay or rental, and not a download.
  SELECT string_agg(v.sku, ', ' ORDER BY v.sku) INTO v_skus
    FROM commerce.product_variants v
   WHERE v.store_id = v_store AND v.product_id = v_product
     AND v.measure_amount IS NOT NULL
     AND (v_kind <> 'goods' OR v.delivery <> 'physical');
  IF v_skus IS NOT NULL THEN
    RAISE EXCEPTION 'unit_price.not_applicable' USING ERRCODE = 'check_violation', DETAIL = v_skus;
  END IF;

  IF v_status = 'active'
     AND v_kind = 'goods'
     AND COALESCE(current_setting('commerce.unit_price_copying', true), '') <> 'on'
     AND commerce.unit_price_required(v_store, v_product) THEN
    SELECT string_agg(v.sku, ', ' ORDER BY v.sku) INTO v_skus
      FROM commerce.product_variants v
     WHERE v.store_id = v_store AND v.product_id = v_product
       AND v.active AND v.delivery = 'physical' AND v.measure_amount IS NULL;
    IF v_skus IS NOT NULL THEN
      RAISE EXCEPTION 'unit_price.measure_required' USING ERRCODE = 'check_violation', DETAIL = v_skus;
    END IF;
  END IF;

  RETURN NULL;
END;
$$;


--
-- Name: claim_webhook_event(uuid, text, text, text, jsonb); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.claim_webhook_event(p_store uuid, p_provider text, p_event_id text, p_type text, p_payload jsonb) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  INSERT INTO commerce.webhook_events (store_id, provider, event_id, type, payload, claimed_at)
  VALUES (p_store, p_provider, p_event_id, p_type, p_payload, now())
  ON CONFLICT (store_id, provider, event_id) DO NOTHING;
  IF FOUND THEN
    RETURN true;
  END IF;

  UPDATE commerce.webhook_events
     SET attempts = attempts + 1, claimed_at = now()
   WHERE store_id = p_store AND provider = p_provider AND event_id = p_event_id
     AND processed_at IS NULL
     AND (claimed_at IS NULL OR claimed_at < now() - interval '5 minutes');
  IF FOUND THEN
    RETURN true;
  END IF;

  UPDATE commerce.webhook_events
     SET attempts = attempts + 1
   WHERE store_id = p_store AND provider = p_provider AND event_id = p_event_id;
  RETURN false;
END;
$$;


--
-- Name: clone_entry_refs(jsonb, uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.clone_entry_refs(p_json jsonb, p_template uuid, p_store uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_text text;
  v_old uuid;
BEGIN
  IF p_json IS NULL THEN
    RETURN NULL;
  END IF;
  v_text := p_json::text;
  FOR v_old IN
    SELECT DISTINCT lower(r.m[1])::uuid
      FROM regexp_matches(v_text, '"([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})"', 'g') AS r(m)
  LOOP
    IF EXISTS (SELECT 1 FROM commerce.content_entries e WHERE e.id = v_old AND e.store_id = p_template) THEN
      v_text := replace(v_text, '"' || v_old::text || '"', '"' || commerce.clone_id(p_store, v_old)::text || '"');
    END IF;
  END LOOP;
  RETURN v_text::jsonb;
END;
$$;


--
-- Name: clone_field_location(uuid, jsonb); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.clone_field_location(p_store uuid, p_location jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  SELECT coalesce(
    (SELECT jsonb_agg(rules ORDER BY position)
       FROM (
         SELECT o.position,
                jsonb_agg(
                  CASE WHEN r.rule->>'param' IN ('category', 'tag') AND r.rule->>'value' ~ '^[0-9a-f-]{36}$'
                       THEN jsonb_set(r.rule, '{value}', to_jsonb(commerce.clone_id(p_store, (r.rule->>'value')::uuid)::text))
                       ELSE r.rule END
                  ORDER BY r.position
                ) AS rules
           FROM jsonb_array_elements(p_location) WITH ORDINALITY AS o(anded, position),
                LATERAL jsonb_array_elements(o.anded) WITH ORDINALITY AS r(rule, position)
          GROUP BY o.position
       ) x),
    '[]'::jsonb);
$_$;


--
-- Name: clone_id(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.clone_id(p_store_id uuid, p_id uuid) RETURNS uuid
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
  SELECT (substr(h, 1, 12) || '4' || substr(h, 14, 3) || '8' || substr(h, 18, 15))::uuid
    FROM (SELECT md5(p_store_id::text || p_id::text) AS h) AS hashed;
$$;


--
-- Name: clone_page_content(uuid, uuid, jsonb); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.clone_page_content(p_store uuid, p_template uuid, p_content jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_text text := p_content::text;
  v_id uuid;
BEGIN
  IF p_content IS NULL THEN
    RETURN NULL;
  END IF;
  FOR v_id IN
    SELECT id FROM commerce.terms WHERE store_id = p_template
    UNION ALL
    SELECT id FROM commerce.menus WHERE store_id = p_template
  LOOP
    v_text := replace(v_text, '"' || v_id::text || '"', '"' || commerce.clone_id(p_store, v_id)::text || '"');
  END LOOP;
  v_text := replace(v_text, '"' || p_template::text || '"', '"' || p_store::text || '"');
  v_text := regexp_replace(v_text, '"recipients": \[[^]]*\]', '"recipients": []', 'g');
  RETURN v_text::jsonb;
END;
$$;


--
-- Name: clone_starter_setup(uuid, uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.clone_starter_setup(p_source uuid, p_store uuid, p_owner uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM commerce.stores WHERE id = p_source AND starter) THEN
    RAISE EXCEPTION 'store_starters.not_starter: % is not a store template', p_source USING ERRCODE = 'check_violation';
  END IF;

  -- Its features (D178), who it sells to, how the cart and checkout behave, its languages and the CSS its pages rely on; and where it came from.
  UPDATE commerce.stores n
     SET features = t.features,
         audience = t.audience,
         business_popup = t.business_popup,
         open_cart_on_add = t.open_cart_on_add,
         terms_at_checkout = t.terms_at_checkout,
         locales = t.locales,
         rates_auto = t.rates_auto,
         rates_updated_at = t.rates_updated_at,
         custom_css = t.custom_css,
         price_decimals = t.price_decimals,
         price_words = t.price_words,
         quantity_picker = t.quantity_picker,
         made_from_starter = COALESCE(
           (SELECT st.id FROM commerce.store_starters st WHERE st.store_id = p_source),
           t.starter_copy_of
         )
    FROM commerce.stores t
   WHERE n.id = p_store AND t.id = p_source;

  INSERT INTO commerce.store_currencies (store_id, currency, rate, round_to, position)
  SELECT p_store, currency, rate, round_to, position
    FROM commerce.store_currencies WHERE store_id = p_source
  ON CONFLICT DO NOTHING;

  -- Pages and articles not published yet (the legal page drafts among them), as drafts: never published for the new owner.
  INSERT INTO commerce.pages (id, store_id, type, slug, draft, published, published_at, first_published_at, created_by, updated_by)
  SELECT commerce.clone_id(p_store, p.id), p_store, p.type, p.slug,
         commerce.clone_page_content(p_store, p_source, p.draft), NULL, NULL, NULL, p_owner, p_owner
    FROM commerce.pages p
   WHERE p.store_id = p_source AND p.published_at IS NULL AND p.type <> 'variant'
  ON CONFLICT DO NOTHING;

  INSERT INTO commerce.field_values (store_id, entity, entity_id, locale, values)
  SELECT p_store, fv.entity, commerce.clone_id(p_store, fv.entity_id), fv.locale, fv.values
    FROM commerce.field_values fv
    JOIN commerce.pages p ON p.store_id = fv.store_id AND p.id = fv.entity_id
   WHERE fv.store_id = p_source AND fv.entity IN ('page', 'article') AND p.published_at IS NULL
     AND EXISTS (SELECT 1 FROM commerce.pages c WHERE c.id = commerce.clone_id(p_store, fv.entity_id))
  ON CONFLICT DO NOTHING;

  -- The places (D112, D113, D158) given to those drafts: a legal page keeps its place, still a draft.
  INSERT INTO commerce.page_roles (store_id, role, page_id)
  SELECT p_store, r.role, commerce.clone_id(p_store, r.page_id)
    FROM commerce.page_roles r
   WHERE r.store_id = p_source
     AND EXISTS (SELECT 1 FROM commerce.pages p WHERE p.store_id = p_store AND p.id = commerce.clone_id(p_store, r.page_id))
  ON CONFLICT DO NOTHING;

  -- Order handling (D173): gift messages, archiving and how long a draft's pay link lasts; never the power to record payments.
  INSERT INTO commerce.order_settings (store_id, gift_messages, auto_archive_days, draft_valid_days)
  SELECT p_store, gift_messages, auto_archive_days, draft_valid_days
    FROM commerce.order_settings WHERE store_id = p_source
  ON CONFLICT (store_id) DO UPDATE
    SET gift_messages = excluded.gift_messages, auto_archive_days = excluded.auto_archive_days, draft_valid_days = excluded.draft_valid_days;

  -- Invoices (D159): the note and the confirmation switch, as duplicate_store() copies them; the series start in the new store.
  INSERT INTO commerce.invoice_settings (store_id, enabled, footer_note, email_with_confirmation, updated_by)
  SELECT p_store, true, footer_note, email_with_confirmation, p_owner
    FROM commerce.invoice_settings WHERE store_id = p_source
  ON CONFLICT (store_id) DO NOTHING;

  -- Subscription boxes' delivery days (D102); never a shopper's list.
  INSERT INTO commerce.delivery_schedules (id, store_id, market_code, currency, name, delivery_weekday, cutoff_days, cutoff_time, active)
  SELECT commerce.clone_id(p_store, id), p_store, market_code, currency, name, delivery_weekday, cutoff_days, cutoff_time, active
    FROM commerce.delivery_schedules WHERE store_id = p_source;

  -- Customer groups (D108); never a company, which is a customer.
  INSERT INTO commerce.customer_tiers (id, store_id, name, percent, note, active)
  SELECT commerce.clone_id(p_store, id), p_store, name, percent, note, active
    FROM commerce.customer_tiers WHERE store_id = p_source;

  -- The bonus and referral programs' rules (D130, D131); never a balance, a code or an earning.
  INSERT INTO commerce.bonus_settings (
    store_id, enabled, earn_bps, pending_days, max_redeem_percent, min_redeem_minor, expires_months, levels, signup_minor, birthday_minor, currency, updated_by
  )
  SELECT p_store, enabled, earn_bps, pending_days, max_redeem_percent, min_redeem_minor, expires_months, levels, signup_minor, birthday_minor, currency, p_owner
    FROM commerce.bonus_settings WHERE store_id = p_source
  ON CONFLICT (store_id) DO NOTHING;

  INSERT INTO commerce.affiliate_settings (
    store_id, enabled, reward_bps, reward_orders, friend_percent, friend_max_minor, monthly_cap_minor, cookie_days, updated_by
  )
  SELECT p_store, enabled, reward_bps, reward_orders, friend_percent, friend_max_minor, monthly_cap_minor, cookie_days, p_owner
    FROM commerce.affiliate_settings WHERE store_id = p_source
  ON CONFLICT (store_id) DO NOTHING;

  -- Its text styles (D393), so the words of its pages that wear one look as they did.
  PERFORM commerce.copy_text_styles(p_source, p_store);
END;
$$;


--
-- Name: clone_store(uuid, text, text, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.clone_store(p_template_id uuid, p_slug text, p_name text, p_owner_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_store uuid;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM commerce.stores WHERE id = p_template_id) THEN
    RAISE EXCEPTION 'unknown template store %', p_template_id;
  END IF;

  INSERT INTO commerce.stores (slug, name, created_by, navigation, fonts, theme, modules, time_zone, booking_reminder_hours)
  SELECT p_slug, p_name, p_owner_id, navigation, fonts, theme - 'savedId', array_remove(array_remove(modules, 'bookings'), 'deliveries'), time_zone, booking_reminder_hours
    FROM commerce.stores WHERE id = p_template_id
  RETURNING id INTO v_store;

  INSERT INTO commerce.store_members (store_id, account_id, role)
  VALUES (v_store, p_owner_id, 'owner');

  -- The template's menus (D85), used where the template's were; their links
  -- name pages, products, categories and tags by address, which the copies keep.
  INSERT INTO commerce.menus (id, store_id, name, items, created_by, updated_by)
  SELECT commerce.clone_id(v_store, id), v_store, name, items, p_owner_id, p_owner_id
    FROM commerce.menus WHERE store_id = p_template_id;

  UPDATE commerce.stores s
     SET header_menu_id = commerce.clone_id(v_store, t.header_menu_id),
         footer_menu_id = commerce.clone_id(v_store, t.footer_menu_id)
    FROM commerce.stores t
   WHERE s.id = v_store AND t.id = p_template_id;

  INSERT INTO commerce.markets (store_id, code, currency, default_locale, locales, active, created_at)
  SELECT v_store, m.code, m.currency, m.default_locale, m.locales, m.active,
         now() + (row_number() OVER (ORDER BY (m.code = t.country) DESC NULLS LAST, m.created_at, m.code) - 1) * interval '1 microsecond'
    FROM commerce.markets m JOIN commerce.stores t ON t.id = m.store_id WHERE m.store_id = p_template_id;

  INSERT INTO commerce.shipping_rates (store_id, market_code, currency, amount_minor, free_over_minor)
  SELECT v_store, market_code, currency, amount_minor, free_over_minor
    FROM commerce.shipping_rates WHERE store_id = p_template_id;

  INSERT INTO commerce.payment_methods (store_id, market_code, method, enabled)
  SELECT v_store, market_code, method, enabled
    FROM commerce.payment_methods WHERE store_id = p_template_id;

  INSERT INTO commerce.economic_operators (id, store_id, name, postal_address, electronic_address, country)
  SELECT commerce.clone_id(v_store, id), v_store, name, postal_address, electronic_address, country
    FROM commerce.economic_operators WHERE store_id = p_template_id;

  INSERT INTO commerce.inventory_locations (id, store_id, name, country, active, priority, fulfils_online)
  SELECT commerce.clone_id(v_store, id), v_store, name, country, active, priority, fulfils_online
    FROM commerce.inventory_locations WHERE store_id = p_template_id AND supplier_id IS NULL;

  PERFORM set_config('commerce.unit_price_copying', 'on', true);

  -- Products arrive as drafts and are published below, once their pictures,
  -- titles and variants exist (the publishing check needs them).
  INSERT INTO commerce.products (
    id, store_id, handle, status, manufacturer_id, responsible_person_id,
    tax_code, withdrawal_exclusion, delivery, download_limit, download_days, subscription_only,
    kind, vat_category, audience, sold_by_measure, bundle_pricing, bundle_percent_off, standard_category, standard_attributes, price_on_request, price_words
  )
  SELECT commerce.clone_id(v_store, id), v_store, handle, 'draft',
         commerce.clone_id(v_store, manufacturer_id),
         commerce.clone_id(v_store, responsible_person_id),
         tax_code, withdrawal_exclusion, delivery, download_limit, download_days, subscription_only,
         kind, vat_category, audience, sold_by_measure, bundle_pricing, bundle_percent_off, standard_category, standard_attributes, price_on_request, price_words
    FROM commerce.products
   WHERE store_id = p_template_id AND status <> 'archived';

  INSERT INTO commerce.product_translations (
    store_id, product_id, locale, title, description, safety_information, seo_title, seo_description, excerpt
  )
  SELECT v_store, commerce.clone_id(v_store, t.product_id), t.locale, t.title, t.description, t.safety_information,
         t.seo_title, t.seo_description, t.excerpt
    FROM commerce.product_translations t
    JOIN commerce.products p ON p.id = t.product_id
   WHERE t.store_id = p_template_id AND p.status <> 'archived';

  INSERT INTO commerce.product_media (store_id, product_id, url, position, alt, thumbnail_url, kind, source, media_url)
  SELECT v_store, commerce.clone_id(v_store, m.product_id), m.url, m.position, m.alt, m.thumbnail_url, m.kind, m.source, m.media_url
    FROM commerce.product_media m
    JOIN commerce.products p ON p.id = m.product_id
   WHERE m.store_id = p_template_id AND p.status <> 'archived';

  INSERT INTO commerce.product_schemes (store_id, product_id, scheme)
  SELECT v_store, commerce.clone_id(v_store, s.product_id), s.scheme
    FROM commerce.product_schemes s
    JOIN commerce.products p ON p.id = s.product_id
   WHERE s.store_id = p_template_id AND p.status <> 'archived';

  -- Categories and tags (D50) come along with the products in them. Parents
  -- are set once every category exists, so the parent check finds them.
  INSERT INTO commerce.terms (id, store_id, content_type, kind, name, slug, position, requires_unit_price, seo, description, image_url, image_thumbnail_url, texts, rules)
  SELECT commerce.clone_id(v_store, id), v_store, content_type, kind, name, slug, position, requires_unit_price, seo, description, image_url, image_thumbnail_url, texts, commerce.clone_term_rules(v_store, rules)
    FROM commerce.terms WHERE store_id = p_template_id;

  UPDATE commerce.terms n
     SET parent_id = commerce.clone_id(v_store, t.parent_id)
    FROM commerce.terms t
   WHERE t.store_id = p_template_id
     AND t.parent_id IS NOT NULL
     AND n.id = commerce.clone_id(v_store, t.id);

  INSERT INTO commerce.product_terms (store_id, product_id, term_id, position)
  SELECT v_store, commerce.clone_id(v_store, pt.product_id), commerce.clone_id(v_store, pt.term_id), pt.position
    FROM commerce.product_terms pt
    JOIN commerce.products p ON p.id = pt.product_id
   WHERE pt.store_id = p_template_id AND p.status <> 'archived';

  INSERT INTO commerce.product_variants (
    id, store_id, product_id, sku, gtin, tax_code, options, weight_grams,
    hs_code, origin_country, active, delivery, rental_period, image_url, image_thumbnail_url, cost_minor,
    measure_amount, measure_unit, measure_base, stock_policy, backorder_days, preorder_until, low_stock_threshold,
    min_quantity, max_quantity, quantity_step
  )
  SELECT commerce.clone_id(v_store, v.id), v_store, commerce.clone_id(v_store, v.product_id),
         v.sku, v.gtin, v.tax_code, v.options, v.weight_grams, v.hs_code, v.origin_country, v.active, v.delivery,
         v.rental_period, v.image_url, v.image_thumbnail_url, v.cost_minor,
         v.measure_amount, v.measure_unit, v.measure_base, v.stock_policy, v.backorder_days, v.preorder_until, v.low_stock_threshold,
         v.min_quantity, v.max_quantity, v.quantity_step
    FROM commerce.product_variants v
    JOIN commerce.products p ON p.id = v.product_id
   WHERE v.store_id = p_template_id AND p.status <> 'archived';

  INSERT INTO commerce.selling_plans (
    id, store_id, product_id, interval, interval_count, discount_percent, trial_days, signup_fee, min_cycles,
    position, active
  )
  SELECT commerce.clone_id(v_store, sp.id), v_store, commerce.clone_id(v_store, sp.product_id),
         sp.interval, sp.interval_count, sp.discount_percent, sp.trial_days, sp.signup_fee, sp.min_cycles,
         sp.position, sp.active
    FROM commerce.selling_plans sp
    JOIN commerce.products p ON p.id = sp.product_id
   WHERE sp.store_id = p_template_id AND p.status <> 'archived';

  INSERT INTO commerce.product_market_texts (store_id, product_id, market_code, locale, description)
  SELECT v_store, commerce.clone_id(v_store, mt.product_id), mt.market_code, mt.locale, mt.description
    FROM commerce.product_market_texts mt
   WHERE mt.store_id = p_template_id
     AND EXISTS (SELECT 1 FROM commerce.products p WHERE p.store_id = v_store AND p.id = commerce.clone_id(v_store, mt.product_id))
     AND EXISTS (SELECT 1 FROM commerce.markets m WHERE m.store_id = v_store AND m.code = mt.market_code);

  INSERT INTO commerce.market_availability (store_id, product_id, variant_id, market_code)
  SELECT v_store, commerce.clone_id(v_store, ma.product_id), CASE WHEN ma.variant_id IS NULL THEN NULL ELSE commerce.clone_id(v_store, ma.variant_id) END, ma.market_code
    FROM commerce.market_availability ma
   WHERE ma.store_id = p_template_id
     AND EXISTS (SELECT 1 FROM commerce.products p WHERE p.store_id = v_store AND p.id = commerce.clone_id(v_store, ma.product_id))
     AND (ma.variant_id IS NULL OR EXISTS (SELECT 1 FROM commerce.product_variants v WHERE v.store_id = v_store AND v.id = commerce.clone_id(v_store, ma.variant_id)))
     AND EXISTS (SELECT 1 FROM commerce.markets m WHERE m.store_id = v_store AND m.code = ma.market_code);

  INSERT INTO commerce.bundle_components (store_id, bundle_variant_id, component_variant_id, quantity, position)
  SELECT v_store, commerce.clone_id(v_store, bc.bundle_variant_id), commerce.clone_id(v_store, bc.component_variant_id), bc.quantity, bc.position
    FROM commerce.bundle_components bc
   WHERE bc.store_id = p_template_id
     AND EXISTS (SELECT 1 FROM commerce.product_variants v WHERE v.store_id = v_store AND v.id = commerce.clone_id(v_store, bc.bundle_variant_id))
     AND EXISTS (SELECT 1 FROM commerce.product_variants v WHERE v.store_id = v_store AND v.id = commerce.clone_id(v_store, bc.component_variant_id));

  INSERT INTO commerce.search_synonyms (store_id, locale, kind, words, means, created_at, updated_at)
  SELECT v_store, s.locale, s.kind, s.words, s.means, s.created_at, s.updated_at FROM commerce.search_synonyms s WHERE s.store_id = p_template_id;

  INSERT INTO commerce.search_rules (store_id, action, product_id, term_id, target, queries, match, position, created_at, updated_at)
  SELECT v_store, r.action, CASE WHEN r.product_id IS NOT NULL THEN commerce.clone_id(v_store, r.product_id) END,
         CASE WHEN r.term_id IS NOT NULL THEN commerce.clone_id(v_store, r.term_id) END, r.target, r.queries, r.match, r.position, r.created_at, r.updated_at
    FROM commerce.search_rules r
   WHERE r.store_id = p_template_id
     AND (r.product_id IS NULL OR EXISTS (SELECT 1 FROM commerce.products p WHERE p.store_id = v_store AND p.id = commerce.clone_id(v_store, r.product_id)))
     AND (r.term_id IS NULL OR EXISTS (SELECT 1 FROM commerce.terms t WHERE t.store_id = v_store AND t.id = commerce.clone_id(v_store, r.term_id)));

  INSERT INTO commerce.price_breaks (store_id, product_id, variant_id, from_quantity, percent, amounts)
  SELECT v_store, commerce.clone_id(v_store, b.product_id), CASE WHEN b.variant_id IS NOT NULL THEN commerce.clone_id(v_store, b.variant_id) END,
         b.from_quantity, b.percent, b.amounts
    FROM commerce.price_breaks b
   WHERE b.store_id = p_template_id
     AND EXISTS (SELECT 1 FROM commerce.products p WHERE p.store_id = v_store AND p.id = commerce.clone_id(v_store, b.product_id))
     AND (b.variant_id IS NULL OR EXISTS (SELECT 1 FROM commerce.product_variants v WHERE v.store_id = v_store AND v.id = commerce.clone_id(v_store, b.variant_id)));

  INSERT INTO commerce.prices (store_id, variant_id, market_code, currency, amount_minor, valid_from)
  SELECT v_store, commerce.clone_id(v_store, pr.variant_id), pr.market_code, pr.currency, pr.amount_minor, now()
    FROM commerce.prices pr
   WHERE pr.store_id = p_template_id
     AND pr.valid_to IS NULL
     AND EXISTS (
       SELECT 1 FROM commerce.product_variants v
        WHERE v.store_id = v_store AND v.id = commerce.clone_id(v_store, pr.variant_id)
     );

  PERFORM commerce.stock_context('opening', 'copy', NULL, NULL, NULL, NULL, NULL);
  INSERT INTO commerce.inventory_levels (store_id, variant_id, location_id, on_hand)
  SELECT v_store, commerce.clone_id(v_store, l.variant_id), commerce.clone_id(v_store, l.location_id), greatest(l.on_hand, 0)
    FROM commerce.inventory_levels l
   WHERE l.store_id = p_template_id
     AND NOT EXISTS (SELECT 1 FROM commerce.inventory_locations sl WHERE sl.store_id = l.store_id AND sl.id = l.location_id AND sl.supplier_id IS NOT NULL)
     AND EXISTS (
       SELECT 1 FROM commerce.product_variants v
        WHERE v.store_id = v_store AND v.id = commerce.clone_id(v_store, l.variant_id) AND v.delivery = 'physical'
     );
  PERFORM commerce.stock_context_clear();

  -- Bookings (D65, D67): the template's staff, rooms and rental items, and how
  -- its appointments, stays and rentals are booked. Places are the store's own
  -- addresses and stay behind.
  INSERT INTO commerce.booking_resources (id, store_id, kind, name, email, hours, capacity, active, position)
  SELECT commerce.clone_id(v_store, id), v_store, kind, name, '', hours, capacity, active, position
    FROM commerce.booking_resources WHERE store_id = p_template_id;

  INSERT INTO commerce.appointment_settings (
    product_id, store_id, duration_minutes, buffer_before_minutes, buffer_after_minutes, step_minutes,
    min_notice_minutes, max_days_ahead, payment, deposit_percent, cancel_hours, no_show_percent,
    check_in_time, check_out_time, min_nights, max_nights, booking_fee
  )
  SELECT commerce.clone_id(v_store, a.product_id), v_store, a.duration_minutes, a.buffer_before_minutes,
         a.buffer_after_minutes, a.step_minutes, a.min_notice_minutes, a.max_days_ahead,
         a.payment, a.deposit_percent, a.cancel_hours, a.no_show_percent,
         a.check_in_time, a.check_out_time, a.min_nights, a.max_nights, a.booking_fee
    FROM commerce.appointment_settings a
    JOIN commerce.products p ON p.id = a.product_id
   WHERE a.store_id = p_template_id AND p.status <> 'archived';

  -- Seasons of stays' and rentals' prices (D70).
  INSERT INTO commerce.booking_seasons (store_id, product_id, name, names, from_day, to_day, weekdays, percent, position)
  SELECT v_store, commerce.clone_id(v_store, s.product_id), s.name, s.names, s.from_day, s.to_day, s.weekdays, s.percent, s.position
    FROM commerce.booking_seasons s
    JOIN commerce.products p ON p.id = s.product_id
   WHERE s.store_id = p_template_id AND p.status <> 'archived';

  INSERT INTO commerce.product_resources (store_id, product_id, resource_id)
  SELECT v_store, commerce.clone_id(v_store, pr.product_id), commerce.clone_id(v_store, pr.resource_id)
    FROM commerce.product_resources pr
    JOIN commerce.products p ON p.id = pr.product_id
   WHERE pr.store_id = p_template_id AND p.status <> 'archived';

  -- The template's published pages and articles (D53-D57), published in the copy, with
  -- the category and tag ids in them (the page's own and its grids') made the
  -- copies'; and its front page (D54).
  INSERT INTO commerce.pages (id, store_id, type, slug, draft, published, published_at, first_published_at, created_by, updated_by)
  SELECT commerce.clone_id(v_store, p.id), v_store, p.type, p.slug,
         commerce.clone_page_content(v_store, p_template_id, p.published),
         commerce.clone_page_content(v_store, p_template_id, p.published),
         now(), now(), p_owner_id, p_owner_id
    FROM commerce.pages p
   WHERE p.store_id = p_template_id AND p.published_at IS NOT NULL;

  UPDATE commerce.stores s
     SET front_page_id = commerce.clone_id(v_store, t.front_page_id)
    FROM commerce.stores t
   WHERE s.id = v_store AND t.id = p_template_id
     AND EXISTS (SELECT 1 FROM commerce.pages p WHERE p.id = commerce.clone_id(v_store, t.front_page_id));

  -- The All products page (D83), as the front page.
  UPDATE commerce.stores s
     SET products_page_id = commerce.clone_id(v_store, t.products_page_id)
    FROM commerce.stores t
   WHERE s.id = v_store AND t.id = p_template_id
     AND EXISTS (SELECT 1 FROM commerce.pages p WHERE p.id = commerce.clone_id(v_store, t.products_page_id));

  -- Product layouts (D79): the copies are used where the template's published
  -- ones were, for the store, its product categories and tags, and products.
  UPDATE commerce.stores s
     SET product_layout_id = commerce.clone_id(v_store, t.product_layout_id)
    FROM commerce.stores t
   WHERE s.id = v_store AND t.id = p_template_id
     AND EXISTS (SELECT 1 FROM commerce.pages p WHERE p.id = commerce.clone_id(v_store, t.product_layout_id));

  UPDATE commerce.terms c
     SET product_layout_id = commerce.clone_id(v_store, t.product_layout_id)
    FROM commerce.terms t
   WHERE t.store_id = p_template_id AND t.product_layout_id IS NOT NULL
     AND c.store_id = v_store AND c.id = commerce.clone_id(v_store, t.id)
     AND EXISTS (SELECT 1 FROM commerce.pages p WHERE p.id = commerce.clone_id(v_store, t.product_layout_id));

  UPDATE commerce.products c
     SET product_layout_id = commerce.clone_id(v_store, t.product_layout_id)
    FROM commerce.products t
   WHERE t.store_id = p_template_id AND t.product_layout_id IS NOT NULL
     AND c.store_id = v_store AND c.id = commerce.clone_id(v_store, t.id)
     AND EXISTS (SELECT 1 FROM commerce.pages p WHERE p.id = commerce.clone_id(v_store, t.product_layout_id));

  -- The header and footer (D80): the copies are used where the template's published ones were.
  UPDATE commerce.stores s
     SET header_id = commerce.clone_id(v_store, t.header_id)
    FROM commerce.stores t
   WHERE s.id = v_store AND t.id = p_template_id
     AND EXISTS (SELECT 1 FROM commerce.pages p WHERE p.id = commerce.clone_id(v_store, t.header_id));

  UPDATE commerce.stores s
     SET footer_id = commerce.clone_id(v_store, t.footer_id)
    FROM commerce.stores t
   WHERE s.id = v_store AND t.id = p_template_id
     AND EXISTS (SELECT 1 FROM commerce.pages p WHERE p.id = commerce.clone_id(v_store, t.footer_id));

  -- Download files stay with the template (they are its own), so a product
  -- sold as a download waits as a draft for the new owner's files (D24).
  UPDATE commerce.products p
     SET status = 'active'
    FROM commerce.products t
   WHERE t.store_id = p_template_id
     AND t.status = 'active'
     AND p.store_id = v_store
     AND p.id = commerce.clone_id(v_store, t.id)
     AND NOT EXISTS (
       SELECT 1 FROM commerce.product_variants v
        WHERE v.product_id = p.id AND v.active AND v.delivery = 'digital'
     );

  -- The blog, search and 404 pages (D112): the copies of the template's chosen pages.
  INSERT INTO commerce.page_roles (store_id, role, page_id)
  SELECT v_store, r.role, commerce.clone_id(v_store, r.page_id)
    FROM commerce.page_roles r
   WHERE r.store_id = p_template_id
     AND EXISTS (SELECT 1 FROM commerce.pages p WHERE p.id = commerce.clone_id(v_store, r.page_id));

  -- The template's custom field groups (D118), with the categories and tags in
  -- their rules made the copies'; and what was entered in the fields of the
  -- products, pages and articles copied above (values are keyed by field ids,
  -- which the copies keep).
  INSERT INTO commerce.field_groups (id, store_id, name, slug, entities, location, fields, position, active, sort)
  SELECT commerce.clone_id(v_store, g.id), v_store, g.name, g.slug, g.entities,
         commerce.clone_field_location(v_store, g.location), g.fields, g.position, g.active, g.sort
    FROM commerce.field_groups g WHERE g.store_id = p_template_id;

  INSERT INTO commerce.field_values (store_id, entity, entity_id, locale, values)
  SELECT v_store, fv.entity, commerce.clone_id(v_store, fv.entity_id), fv.locale, fv.values
    FROM commerce.field_values fv
   WHERE fv.store_id = p_template_id
     AND (
       (fv.entity = 'product'
         AND EXISTS (SELECT 1 FROM commerce.products p WHERE p.id = commerce.clone_id(v_store, fv.entity_id)))
       OR (fv.entity IN ('page', 'article')
         AND EXISTS (SELECT 1 FROM commerce.pages p WHERE p.id = commerce.clone_id(v_store, fv.entity_id)))
       OR (fv.entity = 'variant'
         AND EXISTS (SELECT 1 FROM commerce.product_variants v WHERE v.id = commerce.clone_id(v_store, fv.entity_id)))
       OR (fv.entity = 'term'
         AND EXISTS (SELECT 1 FROM commerce.terms t WHERE t.id = commerce.clone_id(v_store, fv.entity_id)))
     );

  -- What was entered in the template's own store fields (D120): the store's
  -- values are kept under its own id, so the copy's are under the new store's.
  -- Customers' and orders' values (personal data) are never copied.
  INSERT INTO commerce.field_values (store_id, entity, entity_id, locale, values)
  SELECT v_store, 'store', v_store, fv.locale, fv.values
    FROM commerce.field_values fv
   WHERE fv.store_id = p_template_id AND fv.entity = 'store' AND fv.entity_id = p_template_id;

  -- The template's content types and entries (D326), and every copied value naming an entry made to name the copy.
  INSERT INTO commerce.content_types (
    id, store_id, key, name, slug, fields, title_field, summary_field, picture_field, has_pages, layout_id, position, updated_by
  )
  SELECT commerce.clone_id(v_store, t.id), v_store, t.key, t.name, t.slug, t.fields, t.title_field, t.summary_field, t.picture_field,
         t.has_pages,
         CASE WHEN EXISTS (SELECT 1 FROM commerce.pages p WHERE p.id = commerce.clone_id(v_store, t.layout_id)) THEN commerce.clone_id(v_store, t.layout_id) END,
         t.position, p_owner_id
    FROM commerce.content_types t WHERE t.store_id = p_template_id;

  INSERT INTO commerce.content_entries (
    id, store_id, type_id, slug, draft, published, published_at, first_published_at, position, created_by, updated_by
  )
  SELECT commerce.clone_id(v_store, e.id), v_store, commerce.clone_id(v_store, e.type_id), e.slug,
         commerce.clone_entry_refs(e.draft, p_template_id, v_store), commerce.clone_entry_refs(e.published, p_template_id, v_store),
         e.published_at, e.first_published_at, e.position, p_owner_id, p_owner_id
    FROM commerce.content_entries e WHERE e.store_id = p_template_id;

  UPDATE commerce.field_values fv SET values = commerce.clone_entry_refs(fv.values, p_template_id, v_store)
   WHERE fv.store_id = v_store AND EXISTS (SELECT 1 FROM commerce.content_entries e WHERE e.store_id = p_template_id);

  -- What keyword search reads of the products' fields (D118).
  INSERT INTO commerce.field_search (store_id, entity, entity_id, locale, body)
  SELECT v_store, fs.entity, commerce.clone_id(v_store, fs.entity_id), fs.locale, fs.body
    FROM commerce.field_search fs
   WHERE fs.store_id = p_template_id
     AND EXISTS (SELECT 1 FROM commerce.products p WHERE p.id = commerce.clone_id(v_store, fs.entity_id));

  -- How the template store handles returns (D153); returns themselves are never copied.
  INSERT INTO commerce.return_settings (
    store_id, window_days, transit_days, who_pays_return, refund_when, accept_excluded, instructions, instructions_translations, return_address,
    b2b_returns, exchanges, updated_by
  )
  SELECT v_store, window_days, transit_days, who_pays_return, refund_when, accept_excluded, instructions, instructions_translations, return_address,
         b2b_returns, exchanges, p_owner_id
    FROM commerce.return_settings WHERE store_id = p_template_id;

  -- A store template (D175) brings the rest of its operational set-up.
  IF EXISTS (SELECT 1 FROM commerce.stores WHERE id = p_template_id AND starter) THEN
    PERFORM commerce.clone_starter_setup(p_template_id, v_store, p_owner_id);
  END IF;


  -- Shipping methods (D237): the settings, profiles (and which product is in which), zones, methods and their rates, with new ids. The template's places
  -- are not copied, so neither are its pickup options nor an area measured from a place; an area by postal codes that names no place is.
  INSERT INTO commerce.shipping_settings (store_id, default_weight_grams, updated_by)
  SELECT v_store, default_weight_grams, p_owner_id
    FROM commerce.shipping_settings WHERE store_id = p_template_id;

  INSERT INTO commerce.shipping_profiles (id, store_id, name, position)
  SELECT commerce.clone_id(v_store, id), v_store, name, position
    FROM commerce.shipping_profiles WHERE store_id = p_template_id;

  UPDATE commerce.products n
     SET shipping_profile_id = commerce.clone_id(v_store, p.shipping_profile_id)
    FROM commerce.products p
   WHERE p.store_id = p_template_id AND p.shipping_profile_id IS NOT NULL
     AND n.store_id = v_store AND n.id = commerce.clone_id(v_store, p.id);

  INSERT INTO commerce.shipping_zones (id, store_id, market_code, name, patterns, position)
  SELECT commerce.clone_id(v_store, id), v_store, market_code, name, patterns, position
    FROM commerce.shipping_zones WHERE store_id = p_template_id;

  INSERT INTO commerce.shipping_methods (
    id, store_id, market_code, currency, name, names, estimate_min_days, estimate_max_days, free_over_minor, active, position
  )
  SELECT commerce.clone_id(v_store, id), v_store, market_code, currency, name, names, estimate_min_days, estimate_max_days, free_over_minor, active, position
    FROM commerce.shipping_methods WHERE store_id = p_template_id;

  INSERT INTO commerce.shipping_method_rates (store_id, method_id, zone_id, profile_id, basis, min_value, max_value, amount_minor)
  SELECT v_store, commerce.clone_id(v_store, method_id), commerce.clone_id(v_store, zone_id), commerce.clone_id(v_store, profile_id),
         basis, min_value, max_value, amount_minor
    FROM commerce.shipping_method_rates WHERE store_id = p_template_id;

  INSERT INTO commerce.local_delivery_areas (
    id, store_id, location_id, market_code, currency, name, names, kind, patterns, radius_km, amount_minor, min_basket_minor, free_over_minor,
    info, info_t, active, position
  )
  SELECT commerce.clone_id(v_store, id), v_store, NULL, market_code, currency, name, names, kind, patterns, radius_km, amount_minor, min_basket_minor,
         free_over_minor, info, info_t, active, position
    FROM commerce.local_delivery_areas WHERE store_id = p_template_id AND location_id IS NULL;

  RETURN v_store;
END;
$$;


--
-- Name: clone_term_rules(uuid, jsonb); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.clone_term_rules(p_store uuid, p_rules jsonb) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $_$
  SELECT CASE
    WHEN p_rules IS NULL OR jsonb_typeof(p_rules -> 'conditions') <> 'array' THEN NULL
    ELSE jsonb_set(p_rules, '{conditions}', coalesce((
      SELECT jsonb_agg(CASE
        WHEN c ->> 'kind' = 'term' AND coalesce(c ->> 'termId', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN jsonb_set(c, '{termId}', to_jsonb(commerce.clone_id(p_store, (c ->> 'termId')::uuid)))
        WHEN c ->> 'kind' = 'manufacturer' AND jsonb_typeof(c -> 'ids') = 'array'
          THEN jsonb_set(c, '{ids}', coalesce((
            SELECT jsonb_agg(to_jsonb(commerce.clone_id(p_store, id::uuid)) ORDER BY n)
            FROM jsonb_array_elements_text(c -> 'ids') WITH ORDINALITY AS i (id, n)
            WHERE id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          ), '[]'::jsonb))
        ELSE c
      END ORDER BY n)
      FROM jsonb_array_elements(p_rules -> 'conditions') WITH ORDINALITY AS x (c, n)
    ), '[]'::jsonb))
  END
$_$;


--
-- Name: closed_quantity(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.closed_quantity(p_order_line uuid) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce(sum(c.quantity), 0)::integer FROM commerce.unsent_closures c WHERE c.order_line_id = p_order_line
$$;


--
-- Name: company_location_buyers_member(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.company_location_buyers_member() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM commerce.customers c
    JOIN commerce.company_locations l ON l.store_id = c.store_id AND l.company_id = c.company_id
    WHERE c.store_id = NEW.store_id AND c.id = NEW.customer_id AND l.id = NEW.location_id AND c.company_role = 'employee'
  ) THEN
    RAISE EXCEPTION 'company_location_buyers.member: only an employee of the location''s company buys there' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: company_locations_max(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.company_locations_max() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF (SELECT count(*) FROM commerce.company_locations l WHERE l.store_id = NEW.store_id AND l.company_id = NEW.company_id) > 50 THEN
    RAISE EXCEPTION 'company_locations.max: a company has at most 50 locations' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: complete_exchange_order(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.complete_exchange_order(p_exchange uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  e commerce.return_exchanges%ROWTYPE;
  o commerce.orders%ROWTYPE;
  v_paid bigint;
BEGIN
  SELECT * INTO e FROM commerce.return_exchanges WHERE id = p_exchange FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'exchange.unknown: no exchange %', p_exchange USING ERRCODE = 'no_data_found'; END IF;
  IF e.status = 'settled' THEN RETURN false; END IF;
  IF e.status <> 'processed' THEN
    RAISE EXCEPTION 'exchange.lifecycle: only a processed exchange is settled (it is %)', e.status USING ERRCODE = 'check_violation';
  END IF;
  IF coalesce(current_setting('kaizen.exchange', true), '') <> e.id::text THEN
    RAISE EXCEPTION 'exchange.context: an exchange is settled under its own context' USING ERRCODE = 'restrict_violation';
  END IF;
  SELECT * INTO o FROM commerce.orders WHERE store_id = e.store_id AND id = e.exchange_order_id FOR UPDATE;
  SELECT coalesce(sum(p.amount_minor), 0) INTO v_paid FROM commerce.payments p
   WHERE p.store_id = o.store_id AND p.order_id = o.id AND p.status = 'captured';
  IF v_paid <> o.total_minor THEN
    RAISE EXCEPTION 'exchange.underpaid: the exchange order''s payments (%) are not its total (%)', v_paid, o.total_minor USING ERRCODE = 'check_violation';
  END IF;
  PERFORM commerce.complete_order_payment(o.id, 'exchange:' || e.id::text);
  UPDATE commerce.return_exchanges SET status = 'settled' WHERE id = e.id;
  RETURN true;
END;
$$;


--
-- Name: complete_order_payment(uuid, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.complete_order_payment(p_order_id uuid, p_reference text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_order commerce.orders%ROWTYPE;
  v_line record;
  v_hold record;
  v_level record;
  v_left integer;
  v_take integer;
  v_have integer;
  v_short integer := 0;
BEGIN
  SELECT * INTO v_order FROM commerce.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown order %', p_order_id;
  END IF;
  IF v_order.status NOT IN ('pending_payment', 'authorized', 'cancelled') THEN
    RETURN false;
  END IF;

  v_short := commerce.draw_order_stock(p_order_id);

  UPDATE commerce.inventory_reservations SET released_at = now()
   WHERE order_id = p_order_id AND released_at IS NULL;

  UPDATE commerce.orders SET status = 'paid' WHERE id = p_order_id;

  -- Digital lines: a download link per file, with the product's limits.
  INSERT INTO commerce.order_downloads (store_id, order_id, file_id, token, max_downloads, expires_at)
  SELECT DISTINCT ON (f.id)
         v_order.store_id, p_order_id, f.id,
         replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''),
         p.download_limit,
         CASE WHEN p.download_days IS NULL THEN NULL
              ELSE now() + make_interval(days => p.download_days) END
    FROM commerce.order_lines ol
    JOIN commerce.product_variants v ON v.store_id = ol.store_id AND v.id = ol.variant_id
    JOIN commerce.products p ON p.store_id = v.store_id AND p.id = v.product_id
    JOIN commerce.product_files f
      ON f.store_id = p.store_id AND f.product_id = p.id AND f.removed_at IS NULL
     AND (f.variant_id IS NULL OR f.variant_id = v.id)
   WHERE ol.order_id = p_order_id AND ol.delivery = 'digital'
   ORDER BY f.id
  ON CONFLICT (order_id, file_id) DO NOTHING;
  UPDATE commerce.carts SET status = 'converted', updated_at = now()
   WHERE store_id = v_order.store_id AND id = v_order.cart_id;

  INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
  VALUES (v_order.store_id, p_order_id, 'order.paid',
          jsonb_build_object('reference', p_reference, 'was', v_order.status), 'stripe');
  IF v_short > 0 THEN
    INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
    VALUES (v_order.store_id, p_order_id, 'stock.short',
            jsonb_build_object('missing', v_short), 'system');
  END IF;
  -- The invoice (D159): numbered and frozen in this transaction; an invoice that cannot be made yet waits, and never stops the payment.
  PERFORM commerce.issue_order_invoice(v_order.store_id, p_order_id);
  RETURN true;
END;
$$;


--
-- Name: content_entries_leave_redirect(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.content_entries_leave_redirect() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_source text;
BEGIN
  IF NEW.store_id IS NOT NULL AND NEW.slug IS DISTINCT FROM OLD.slug AND OLD.first_published_at IS NOT NULL THEN
    SELECT '/' || t.slug || '/' || OLD.slug INTO v_source FROM commerce.content_types t WHERE t.id = NEW.type_id AND t.has_pages;
    IF v_source IS NOT NULL THEN
      DELETE FROM commerce.redirects r WHERE r.store_id = NEW.store_id AND r.source = v_source AND r.kind <> 'manual';
      INSERT INTO commerce.redirects (store_id, kind, source, entry_id, origin)
      VALUES (NEW.store_id, 'entry', v_source, NEW.id, 'system')
      ON CONFLICT ON CONSTRAINT redirects_store_source_key DO NOTHING;
    END IF;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: content_entries_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.content_entries_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NOT EXISTS (
      SELECT 1 FROM commerce.content_types t WHERE t.id = NEW.type_id AND t.store_id IS NOT DISTINCT FROM NEW.store_id
    ) THEN
      RAISE EXCEPTION 'An entry belongs to its type''s owner.' USING ERRCODE = 'check_violation', CONSTRAINT = 'content_entries_owner';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('content_entries:' || coalesce(NEW.store_id::text, 'kaizena'), 0));
    IF (SELECT count(*) FROM commerce.content_entries e WHERE e.store_id IS NOT DISTINCT FROM NEW.store_id) >= 10000 THEN
      RAISE EXCEPTION 'An owner keeps at most 10,000 entries.' USING ERRCODE = 'check_violation', CONSTRAINT = 'content_entries_max';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.type_id <> OLD.type_id OR NEW.store_id IS DISTINCT FROM OLD.store_id THEN
    RAISE EXCEPTION 'An entry keeps its type and owner.' USING ERRCODE = 'check_violation', CONSTRAINT = 'content_entries_fixed';
  END IF;
  IF OLD.first_published_at IS NOT NULL AND NEW.first_published_at IS DISTINCT FROM OLD.first_published_at THEN
    RAISE EXCEPTION 'An entry keeps the day it was first published.' USING ERRCODE = 'check_violation', CONSTRAINT = 'content_entries_first_published';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: content_entries_taken_address(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.content_entries_taken_address() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.store_id IS NOT NULL THEN
    DELETE FROM commerce.redirects r
     USING commerce.content_types t
     WHERE t.id = NEW.type_id AND r.store_id = NEW.store_id AND r.source = '/' || t.slug || '/' || NEW.slug AND r.kind <> 'manual';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: content_types_layout(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.content_types_layout() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.layout_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM commerce.pages p WHERE p.id = NEW.layout_id AND p.type = 'entry_layout' AND p.store_id IS NOT DISTINCT FROM NEW.store_id
  ) THEN
    RAISE EXCEPTION 'A content type''s layout is an entry layout of its own owner.' USING ERRCODE = 'check_violation', CONSTRAINT = 'content_types_layout';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: content_types_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.content_types_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('content_types:' || coalesce(NEW.store_id::text, 'kaizena'), 0));
    IF (SELECT count(*) FROM commerce.content_types t WHERE t.store_id IS NOT DISTINCT FROM NEW.store_id) >= 50 THEN
      RAISE EXCEPTION 'An owner keeps at most 50 content types.' USING ERRCODE = 'check_violation', CONSTRAINT = 'content_types_max';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.store_id IS DISTINCT FROM OLD.store_id OR NEW.key <> OLD.key THEN
    RAISE EXCEPTION 'A content type keeps its owner and key.' USING ERRCODE = 'check_violation', CONSTRAINT = 'content_types_fixed';
  END IF;
  IF NEW.slug <> OLD.slug AND EXISTS (
    SELECT 1 FROM commerce.content_entries e WHERE e.type_id = OLD.id AND e.first_published_at IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'A content type keeps its web name once an entry of it has been published.'
      USING ERRCODE = 'check_violation', CONSTRAINT = 'content_types_slug_fixed';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: convert_with(bigint, numeric); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.convert_with(p_amount bigint, p_fx numeric) RETURNS bigint
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT floor(p_amount * p_fx + 0.5)::bigint
$$;


--
-- Name: copied_order_is_history(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.copied_order_is_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.copied_from IS NOT NULL THEN
    IF NEW.status = 'pending_payment' THEN
      RAISE EXCEPTION 'copied_order: an order waiting for payment is not history and is not copied'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.cart_id IS NOT NULL OR NEW.subscription_id IS NOT NULL OR NEW.host_id IS NOT NULL
       OR NEW.commission_minor <> 0 OR NEW.balance_minor <> 0 THEN
      RAISE EXCEPTION 'copied_order: a copied order has no cart, subscription, host or balance'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: copied_order_lines_read_only(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.copied_order_lines_read_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_order uuid;
BEGIN
  IF current_setting('commerce.copying', true) = 'on' THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;
  v_order := CASE WHEN TG_OP = 'DELETE' THEN OLD.order_id ELSE NEW.order_id END;
  IF EXISTS (SELECT 1 FROM commerce.orders o WHERE o.id = v_order AND o.copied_from IS NOT NULL) THEN
    RAISE EXCEPTION 'copied_order: the lines of a copied order cannot be changed' USING ERRCODE = 'check_violation';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: copied_orders_read_only(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.copied_orders_read_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF OLD.copied_from IS NULL THEN
    IF NEW.copied_from IS NOT NULL THEN
      RAISE EXCEPTION 'copied_order: an order cannot be made a copy' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF current_setting('commerce.anonymising', true) = 'on' AND NEW.copied_from IS NOT DISTINCT FROM OLD.copied_from
     AND (to_jsonb(NEW) - ARRAY['customer_id', 'email', 'billing_address', 'shipping_address', 'company_name', 'organisation_number', 'vat_treatment', 'delivery', 'anonymised_at', 'restricted_at'])
         IS NOT DISTINCT FROM (to_jsonb(OLD) - ARRAY['customer_id', 'email', 'billing_address', 'shipping_address', 'company_name', 'organisation_number', 'vat_treatment', 'delivery', 'anonymised_at', 'restricted_at']) THEN
    RETURN NEW;
  END IF;
  IF NEW.copied_from IS DISTINCT FROM OLD.copied_from
     OR (NEW.customer_id IS NOT NULL AND NEW.customer_id IS DISTINCT FROM OLD.customer_id)
     OR (to_jsonb(NEW) - ARRAY['customer_id', 'archived_at']) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['customer_id', 'archived_at']) THEN
    RAISE EXCEPTION 'copied_order: an order copied from another store is history and cannot be changed'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: copy_customers(uuid, uuid, uuid, integer); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.copy_customers(p_source uuid, p_new uuid, p_after uuid, p_limit integer) RETURNS TABLE(last_id uuid, handled integer, copied integer)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_ids uuid[];
  v_copied integer := 0;
BEGIN
  PERFORM commerce.assert_copy_running(p_source, p_new);
  SELECT array_agg(x.id ORDER BY x.id) INTO v_ids
    FROM (
      SELECT c.id FROM commerce.customers c
       WHERE c.store_id = p_source AND (p_after IS NULL OR c.id > p_after)
       ORDER BY c.id LIMIT greatest(p_limit, 1)
    ) x;
  IF v_ids IS NULL THEN
    RETURN QUERY SELECT p_after, 0, 0;
    RETURN;
  END IF;

  WITH inserted AS (
    INSERT INTO commerce.customers (
      id, store_id, email, locale, created_at, name, phone, address, company_name, organisation_number, tier_id,
      company_id, company_role, copied_from
    )
    SELECT commerce.clone_id(p_new, c.id), p_new, c.email, c.locale, c.created_at, c.name, c.phone, c.address,
           c.company_name, c.organisation_number,
           CASE WHEN EXISTS (SELECT 1 FROM commerce.customer_tiers t
                              WHERE t.store_id = p_new AND t.id = commerce.clone_id(p_new, c.tier_id))
                THEN commerce.clone_id(p_new, c.tier_id) END,
           k.company_id, CASE WHEN k.company_id IS NOT NULL THEN c.company_role END, c.id
      FROM commerce.customers c
      CROSS JOIN LATERAL (
        SELECT CASE WHEN EXISTS (SELECT 1 FROM commerce.customer_companies k
                                  WHERE k.store_id = p_new AND k.id = commerce.clone_id(p_new, c.company_id))
                    THEN commerce.clone_id(p_new, c.company_id) END AS company_id
      ) k
     WHERE c.id = ANY (v_ids)
    ON CONFLICT DO NOTHING
    RETURNING 1
  )
  SELECT count(*)::integer INTO v_copied FROM inserted;

  INSERT INTO commerce.field_values (store_id, entity, entity_id, locale, values, updated_at)
  SELECT p_new, fv.entity, commerce.clone_id(p_new, fv.entity_id), fv.locale, fv.values, fv.updated_at
    FROM commerce.field_values fv
   WHERE fv.store_id = p_source AND fv.entity = 'customer' AND fv.entity_id = ANY (v_ids)
     AND EXISTS (SELECT 1 FROM commerce.customers c
                  WHERE c.store_id = p_new AND c.id = commerce.clone_id(p_new, fv.entity_id))
  ON CONFLICT DO NOTHING;

  RETURN QUERY SELECT v_ids[cardinality(v_ids)], cardinality(v_ids), v_copied;
END;
$$;


--
-- Name: copy_email_templates(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.copy_email_templates(p_source uuid, p_store uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_count integer;
BEGIN
  IF p_source = p_store THEN
    RAISE EXCEPTION 'copy_email_templates.same_store: a store''s texts are copied into another store' USING ERRCODE = 'check_violation';
  END IF;
  INSERT INTO commerce.email_templates (store_id, notification, locale, subject, heading, body, created_at)
  SELECT p_store, t.notification, t.locale, t.subject, t.heading, t.body, t.created_at
    FROM commerce.email_templates t
   WHERE t.store_id = p_source
  ON CONFLICT (store_id, notification, locale) DO NOTHING;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: copy_menu_items(uuid, jsonb); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.copy_menu_items(p_new uuid, p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_item jsonb;
  v_depth integer;
  v_skip integer := NULL;
  v_out jsonb := '[]'::jsonb;
BEGIN
  FOR v_item IN
    SELECT e.value FROM jsonb_array_elements(p_items) WITH ORDINALITY AS e(value, ord) ORDER BY e.ord
  LOOP
    v_depth := coalesce((v_item ->> 'depth')::integer, 0);
    IF v_skip IS NOT NULL AND v_depth > v_skip THEN
      CONTINUE;
    END IF;
    v_skip := NULL;
    IF v_item #>> '{link,kind}' = 'product'
       AND NOT EXISTS (
         SELECT 1 FROM commerce.products p WHERE p.store_id = p_new AND p.handle = v_item #>> '{link,handle}'
       ) THEN
      v_skip := v_depth;
      CONTINUE;
    END IF;
    v_out := v_out || jsonb_build_array(v_item);
  END LOOP;
  RETURN v_out;
END;
$$;


--
-- Name: copy_opt_outs(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.copy_opt_outs(p_source uuid, p_new uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_copied integer;
BEGIN
  PERFORM commerce.assert_copy_running(p_source, p_new);
  WITH inserted AS (
    INSERT INTO commerce.email_opt_outs (store_id, email, source, created_at)
    SELECT p_new, o.email, o.source, o.created_at FROM commerce.email_opt_outs o WHERE o.store_id = p_source
    ON CONFLICT DO NOTHING
    RETURNING 1
  )
  SELECT count(*)::integer INTO v_copied FROM inserted;
  RETURN v_copied;
END;
$$;


--
-- Name: copy_orders(uuid, uuid, uuid, integer); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.copy_orders(p_source uuid, p_new uuid, p_after uuid, p_limit integer) RETURNS TABLE(last_id uuid, handled integer, copied integer)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_ids uuid[];
  v_made uuid[];
BEGIN
  PERFORM commerce.assert_copy_running(p_source, p_new);
  SELECT array_agg(x.id ORDER BY x.id) INTO v_ids
    FROM (
      SELECT o.id FROM commerce.orders o
       WHERE o.store_id = p_source AND o.status <> 'pending_payment' AND o.restricted_at IS NULL AND o.anonymised_at IS NULL AND (p_after IS NULL OR o.id > p_after)
       ORDER BY o.id LIMIT greatest(p_limit, 1)
    ) x;
  IF v_ids IS NULL THEN
    RETURN QUERY SELECT p_after, 0, 0;
    RETURN;
  END IF;

  PERFORM set_config('commerce.copying', 'on', true);

  WITH inserted AS (
    INSERT INTO commerce.orders (
      id, store_id, number, market_code, currency, locale, customer_id, email, status, subtotal_minor,
      shipping_minor, discount_minor, tax_minor, total_minor, billing_address, shipping_address, placed_at,
      delivered_at, created_at, digital_consent_at, discount_code_id, discount_code, balance_minor, host_id,
      commission_minor, member_discount_minor, member_label, member_percent, campaign_discount_minor,
      campaign_label, company_name, organisation_number, copied_from, vat_kind, vat_relief_minor, shipping_tax_rate, delivery_method, delivery, pickup_location_id, ready_for_pickup_at
    )
    SELECT commerce.clone_id(p_new, o.id), p_new, 'C-' || o.number, o.market_code, o.currency, o.locale,
           CASE WHEN EXISTS (SELECT 1 FROM commerce.customers c
                              WHERE c.store_id = p_new AND c.id = commerce.clone_id(p_new, o.customer_id))
                THEN commerce.clone_id(p_new, o.customer_id) END,
           o.email, o.status, o.subtotal_minor, o.shipping_minor, o.discount_minor, o.tax_minor, o.total_minor,
           o.billing_address, o.shipping_address, o.placed_at, o.delivered_at, o.created_at, o.digital_consent_at,
           CASE WHEN EXISTS (SELECT 1 FROM commerce.discount_codes d
                              WHERE d.store_id = p_new AND d.id = commerce.clone_id(p_new, o.discount_code_id))
                THEN commerce.clone_id(p_new, o.discount_code_id) END,
           o.discount_code, 0, NULL, 0, o.member_discount_minor, o.member_label, o.member_percent,
           o.campaign_discount_minor, o.campaign_label, o.company_name, o.organisation_number, o.id, o.vat_kind, o.vat_relief_minor, o.shipping_tax_rate, o.delivery_method, o.delivery, commerce.clone_id(p_new, o.pickup_location_id), o.ready_for_pickup_at
      FROM commerce.orders o
     WHERE o.id = ANY (v_ids)
    ON CONFLICT DO NOTHING
    RETURNING copied_from
  )
  SELECT array_agg(copied_from) INTO v_made FROM inserted;

  IF v_made IS NOT NULL THEN
    INSERT INTO commerce.order_lines (
      id, store_id, order_id, variant_id, sku, title, quantity, unit_price_minor, discount_minor, total_minor,
      tax_minor, tax_rate, tax_code, withdrawal_exclusion, delivery, selling_plan_id, plan_interval,
      plan_interval_count, venue_minor, booked_count, member_discount_minor, campaign_discount_minor, campaign_id,
      gift, campaign_parts, unit_cost_minor, measure_amount, measure_unit, measure_base, vat_relief_minor
    )
    SELECT commerce.clone_id(p_new, l.id), p_new, commerce.clone_id(p_new, l.order_id),
           CASE WHEN EXISTS (SELECT 1 FROM commerce.product_variants v
                              WHERE v.store_id = p_new AND v.id = commerce.clone_id(p_new, l.variant_id))
                THEN commerce.clone_id(p_new, l.variant_id) END,
           l.sku, l.title, l.quantity, l.unit_price_minor, l.discount_minor, l.total_minor, l.tax_minor, l.tax_rate,
           l.tax_code, l.withdrawal_exclusion, l.delivery,
           CASE WHEN EXISTS (SELECT 1 FROM commerce.selling_plans sp
                              WHERE sp.store_id = p_new AND sp.id = commerce.clone_id(p_new, l.selling_plan_id))
                THEN commerce.clone_id(p_new, l.selling_plan_id) END,
           l.plan_interval, l.plan_interval_count, l.venue_minor, l.booked_count, l.member_discount_minor,
           l.campaign_discount_minor,
           CASE WHEN EXISTS (SELECT 1 FROM commerce.campaigns c
                              WHERE c.store_id = p_new AND c.id = commerce.clone_id(p_new, l.campaign_id))
                THEN commerce.clone_id(p_new, l.campaign_id) END,
           l.gift, l.campaign_parts, l.unit_cost_minor, l.measure_amount, l.measure_unit, l.measure_base, l.vat_relief_minor
      FROM commerce.order_lines l
     WHERE l.store_id = p_source AND l.order_id = ANY (v_made);

    INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
    SELECT p_new, commerce.clone_id(p_new, o.id), 'copied',
           jsonb_build_object('from_store', p_source, 'from_order', o.id, 'original_number', o.number,
                              'original_status', o.status, 'original_placed_at', o.placed_at),
           'system'
      FROM commerce.orders o WHERE o.id = ANY (v_made);

    INSERT INTO commerce.field_values (store_id, entity, entity_id, locale, values, updated_at)
    SELECT p_new, fv.entity, commerce.clone_id(p_new, fv.entity_id), fv.locale, fv.values, fv.updated_at
      FROM commerce.field_values fv
     WHERE fv.store_id = p_source AND fv.entity = 'order' AND fv.entity_id = ANY (v_made)
    ON CONFLICT DO NOTHING;
  END IF;

  PERFORM set_config('commerce.copying', 'off', true);
  RETURN QUERY SELECT v_ids[cardinality(v_ids)], cardinality(v_ids), coalesce(cardinality(v_made), 0);
END;
$$;


--
-- Name: copy_platform_site(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.copy_platform_site(p_by uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_house uuid := commerce.house_store();
  v_settings record;
  v_front uuid;
  v_counts jsonb;
  v_first boolean;
  v_last jsonb;
  v_now jsonb;
  v_have jsonb;
  v_take text[] := '{}';
BEGIN
  IF v_house IS NULL THEN
    RAISE EXCEPTION 'house_site.no_store: Kaizena Flow''s own store does not exist' USING ERRCODE = 'check_violation';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('house_site_copy'));
  -- The first copy ever brings every setting; later ones only those the store has not changed since (D474).
  v_first := NOT EXISTS (SELECT 1 FROM commerce.house_site_copies WHERE store_id = v_house);
  SELECT c.settings INTO v_last FROM commerce.house_site_copies c WHERE c.store_id = v_house AND c.kind = 'settings';

  -- Every source row with its copy's id: the one it was copied onto before, else a new one.
  DROP TABLE IF EXISTS pg_temp._site_src;
  CREATE TEMP TABLE _site_src (old_id uuid PRIMARY KEY, new_id uuid NOT NULL, kind text NOT NULL) ON COMMIT DROP;
  INSERT INTO pg_temp._site_src (old_id, new_id, kind)
  SELECT src.id, COALESCE(c.copy_id, gen_random_uuid()), src.kind
    FROM (
      SELECT id, 'page' AS kind FROM commerce.pages WHERE store_id IS NULL AND type IN ('page', 'article', 'header', 'footer', 'entry_layout')
      UNION ALL SELECT id, 'menu' FROM commerce.menus WHERE store_id IS NULL
      UNION ALL SELECT id, 'saved_part' FROM commerce.saved_parts WHERE store_id IS NULL
      UNION ALL SELECT id, 'text_style' FROM commerce.text_styles WHERE store_id IS NULL
      UNION ALL SELECT id, 'term' FROM commerce.terms WHERE store_id IS NULL
      UNION ALL SELECT id, 'content_type' FROM commerce.content_types WHERE store_id IS NULL
      UNION ALL SELECT id, 'content_entry' FROM commerce.content_entries WHERE store_id IS NULL
    ) src
    LEFT JOIN commerce.house_site_copies c ON c.store_id = v_house AND c.source_id = src.id;

  -- `copy_remap()` reads its map from `_copy_ids`.
  DROP TABLE IF EXISTS pg_temp._copy_ids;
  CREATE TEMP TABLE _copy_ids (old_id uuid PRIMARY KEY, new_id uuid) ON COMMIT DROP;
  INSERT INTO pg_temp._copy_ids (old_id, new_id) SELECT old_id, new_id FROM pg_temp._site_src;

  -- The copies of rows that are gone: removed, the pages last (menus and content may point at them).
  DELETE FROM commerce.content_entries e USING commerce.house_site_copies c
   WHERE c.store_id = v_house AND c.kind = 'content_entry' AND e.id = c.copy_id AND e.store_id = v_house
     AND NOT EXISTS (SELECT 1 FROM pg_temp._site_src s WHERE s.old_id = c.source_id);
  DELETE FROM commerce.content_types t USING commerce.house_site_copies c
   WHERE c.store_id = v_house AND c.kind = 'content_type' AND t.id = c.copy_id AND t.store_id = v_house
     AND NOT EXISTS (SELECT 1 FROM pg_temp._site_src s WHERE s.old_id = c.source_id);
  DELETE FROM commerce.menus m USING commerce.house_site_copies c
   WHERE c.store_id = v_house AND c.kind = 'menu' AND m.id = c.copy_id AND m.store_id = v_house
     AND NOT EXISTS (SELECT 1 FROM pg_temp._site_src s WHERE s.old_id = c.source_id);
  DELETE FROM commerce.saved_parts p USING commerce.house_site_copies c
   WHERE c.store_id = v_house AND c.kind = 'saved_part' AND p.id = c.copy_id AND p.store_id = v_house
     AND NOT EXISTS (SELECT 1 FROM pg_temp._site_src s WHERE s.old_id = c.source_id);
  DELETE FROM commerce.text_styles t USING commerce.house_site_copies c
   WHERE c.store_id = v_house AND c.kind = 'text_style' AND t.id = c.copy_id AND t.store_id = v_house
     AND NOT EXISTS (SELECT 1 FROM pg_temp._site_src s WHERE s.old_id = c.source_id);
  DELETE FROM commerce.terms t USING commerce.house_site_copies c
   WHERE c.store_id = v_house AND c.kind = 'term' AND t.id = c.copy_id AND t.store_id = v_house
     AND NOT EXISTS (SELECT 1 FROM pg_temp._site_src s WHERE s.old_id = c.source_id);
  UPDATE commerce.stores SET front_page_id = NULL
   WHERE id = v_house AND front_page_id IN (
     SELECT c.copy_id FROM commerce.house_site_copies c
      WHERE c.store_id = v_house AND c.kind = 'page' AND NOT EXISTS (SELECT 1 FROM pg_temp._site_src s WHERE s.old_id = c.source_id));
  DELETE FROM commerce.pages p USING commerce.house_site_copies c
   WHERE c.store_id = v_house AND c.kind = 'page' AND p.id = c.copy_id AND p.store_id = v_house
     AND NOT EXISTS (SELECT 1 FROM pg_temp._site_src s WHERE s.old_id = c.source_id);
  DELETE FROM commerce.house_site_copies c
   WHERE c.store_id = v_house AND c.kind <> 'settings' AND NOT EXISTS (SELECT 1 FROM pg_temp._site_src s WHERE s.old_id = c.source_id);

  -- Text styles, then categories and tags (their parents set once all are there).
  INSERT INTO commerce.text_styles (id, store_id, slug, name, kind, settings, css, position, created_by, updated_by)
  SELECT s.new_id, v_house, t.slug, t.name, t.kind, commerce.copy_remap(t.settings, v_house, v_house), t.css, t.position, p_by, p_by
    FROM commerce.text_styles t JOIN pg_temp._site_src s ON s.old_id = t.id
  ON CONFLICT (id) DO UPDATE SET slug = excluded.slug, name = excluded.name, kind = excluded.kind, settings = excluded.settings,
    css = excluded.css, position = excluded.position, updated_by = excluded.updated_by, updated_at = now();

  INSERT INTO commerce.terms (id, store_id, content_type, kind, parent_id, name, slug, position, seo)
  SELECT s.new_id, v_house, t.content_type, t.kind, NULL, t.name, t.slug, t.position, commerce.copy_remap(t.seo, v_house, v_house)
    FROM commerce.terms t JOIN pg_temp._site_src s ON s.old_id = t.id
  ON CONFLICT (id) DO UPDATE SET content_type = excluded.content_type, kind = excluded.kind, name = excluded.name, slug = excluded.slug,
    position = excluded.position, seo = excluded.seo, updated_at = now();
  UPDATE commerce.terms t SET parent_id = p.new_id
    FROM pg_temp._site_src s, commerce.terms src LEFT JOIN pg_temp._site_src p ON p.old_id = src.parent_id
   WHERE s.old_id = src.id AND t.id = s.new_id AND t.parent_id IS DISTINCT FROM p.new_id;

  -- Pages, headers and footers: their content's ids are the copies'.
  INSERT INTO commerce.pages (id, store_id, type, slug, draft, published, published_at, first_published_at, created_by, updated_by)
  SELECT s.new_id, v_house, p.type, p.slug, commerce.copy_remap(p.draft, v_house, v_house), commerce.copy_remap(p.published, v_house, v_house),
         p.published_at, p.first_published_at, p_by, p_by
    FROM commerce.pages p JOIN pg_temp._site_src s ON s.old_id = p.id
  ON CONFLICT (id) DO UPDATE SET slug = excluded.slug, draft = excluded.draft, published = excluded.published,
    published_at = excluded.published_at, first_published_at = excluded.first_published_at, updated_by = excluded.updated_by, updated_at = now();

  -- The old addresses of pages lead to the copies.
  INSERT INTO commerce.page_redirects (store_id, type, slug, page_id)
  SELECT v_house, r.type, r.slug, s.new_id
    FROM commerce.page_redirects r JOIN pg_temp._site_src s ON s.old_id = r.page_id
   WHERE r.store_id IS NULL
     AND NOT EXISTS (SELECT 1 FROM commerce.pages q WHERE q.store_id = v_house AND q.type = r.type AND q.slug = r.slug)
  ON CONFLICT (store_id, type, slug) DO UPDATE SET page_id = excluded.page_id;

  INSERT INTO commerce.menus (id, store_id, name, items, created_by, updated_by)
  SELECT s.new_id, v_house, m.name, commerce.copy_remap(m.items, v_house, v_house), p_by, p_by
    FROM commerce.menus m JOIN pg_temp._site_src s ON s.old_id = m.id
  ON CONFLICT (id) DO UPDATE SET name = excluded.name, items = excluded.items, updated_by = excluded.updated_by, updated_at = now();

  -- Saved parts: the store's own (private), as Kaizena Flow's are the marketplace's.
  INSERT INTO commerce.saved_parts (id, store_id, kind, name, content, global, translations, sharing, created_by, updated_by)
  SELECT s.new_id, v_house, p.kind, p.name, commerce.copy_remap(p.content, v_house, v_house), p.global,
         commerce.copy_remap(p.translations, v_house, v_house), 'private', p_by, p_by
    FROM commerce.saved_parts p JOIN pg_temp._site_src s ON s.old_id = p.id
  ON CONFLICT (id) DO UPDATE SET kind = excluded.kind, name = excluded.name, content = excluded.content, global = excluded.global,
    translations = excluded.translations, updated_by = excluded.updated_by, updated_at = now();

  INSERT INTO commerce.content_types (id, store_id, key, name, slug, fields, title_field, summary_field, picture_field, has_pages, layout_id,
    position, updated_by)
  SELECT s.new_id, v_house, t.key, t.name, t.slug, commerce.copy_remap(t.fields, v_house, v_house), t.title_field, t.summary_field,
         t.picture_field, t.has_pages, (SELECT l.new_id FROM pg_temp._site_src l WHERE l.old_id = t.layout_id), t.position, p_by
    FROM commerce.content_types t JOIN pg_temp._site_src s ON s.old_id = t.id
  ON CONFLICT (id) DO UPDATE SET key = excluded.key, name = excluded.name, slug = excluded.slug, fields = excluded.fields,
    title_field = excluded.title_field, summary_field = excluded.summary_field, picture_field = excluded.picture_field,
    has_pages = excluded.has_pages, layout_id = excluded.layout_id, position = excluded.position, updated_by = excluded.updated_by,
    updated_at = now();

  INSERT INTO commerce.content_entries (id, store_id, type_id, slug, draft, published, published_at, first_published_at, position, created_by,
    updated_by)
  SELECT s.new_id, v_house, ty.new_id, e.slug, commerce.copy_remap(e.draft, v_house, v_house), commerce.copy_remap(e.published, v_house, v_house),
         e.published_at, e.first_published_at, e.position, p_by, p_by
    FROM commerce.content_entries e JOIN pg_temp._site_src s ON s.old_id = e.id JOIN pg_temp._site_src ty ON ty.old_id = e.type_id
  ON CONFLICT (id) DO UPDATE SET type_id = excluded.type_id, slug = excluded.slug, draft = excluded.draft, published = excluded.published,
    published_at = excluded.published_at, first_published_at = excluded.first_published_at, position = excluded.position,
    updated_by = excluded.updated_by, updated_at = now();

  -- The site's look, logos, SEO, header, footer, menus and front page, onto the store (D474): each as the live site has it now (`v_now`),
  -- where the store still has it as the last copy left it (`v_last`), or on the first copy ever. A setting changed in the store's own
  -- Settings stays the store's, as does one the live site has none of. Before D474 no copy kept `v_last`: then every setting stays.
  SELECT * INTO v_settings FROM commerce.platform_settings LIMIT 1;
  SELECT s.new_id INTO v_front FROM commerce.platform_page_roles r JOIN pg_temp._site_src s ON s.old_id = r.page_id WHERE r.role = 'front';
  IF v_settings.id IS NOT NULL THEN
    v_now := jsonb_build_object(
      'theme', commerce.copy_remap(v_settings.theme, v_house, v_house),
      'fonts', v_settings.fonts,
      'custom_css', to_jsonb(v_settings.custom_css),
      'navigation', commerce.copy_remap(v_settings.navigation, v_house, v_house),
      'seo', commerce.copy_remap(v_settings.seo, v_house, v_house),
      'tracking', v_settings.tracking,
      'header_id', (SELECT to_jsonb(s.new_id) FROM pg_temp._site_src s WHERE s.old_id = v_settings.header_id),
      'footer_id', (SELECT to_jsonb(s.new_id) FROM pg_temp._site_src s WHERE s.old_id = v_settings.footer_id),
      'header_menu_id', (SELECT to_jsonb(s.new_id) FROM pg_temp._site_src s WHERE s.old_id = v_settings.header_menu_id),
      'footer_menu_id', (SELECT to_jsonb(s.new_id) FROM pg_temp._site_src s WHERE s.old_id = v_settings.footer_menu_id),
      'front_page_id', to_jsonb(v_front)
    );
    SELECT jsonb_build_object(
      'theme', st.theme, 'fonts', st.fonts, 'custom_css', to_jsonb(st.custom_css), 'navigation', st.navigation, 'seo', st.seo,
      'tracking', st.tracking, 'header_id', to_jsonb(st.header_id), 'footer_id', to_jsonb(st.footer_id),
      'header_menu_id', to_jsonb(st.header_menu_id), 'footer_menu_id', to_jsonb(st.footer_menu_id), 'front_page_id', to_jsonb(st.front_page_id)
    ) INTO v_have FROM commerce.stores st WHERE st.id = v_house;
    SELECT COALESCE(array_agg(k), '{}') INTO v_take FROM jsonb_object_keys(v_now) AS k
     WHERE v_first OR (v_last IS NOT NULL AND COALESCE(v_have -> k, 'null') = COALESCE(v_last -> k, 'null'));
    UPDATE commerce.stores SET
      theme = CASE WHEN 'theme' = ANY (v_take) THEN COALESCE(NULLIF(v_now -> 'theme', 'null'), theme) ELSE theme END,
      fonts = CASE WHEN 'fonts' = ANY (v_take) THEN COALESCE(NULLIF(v_now -> 'fonts', 'null'), fonts) ELSE fonts END,
      custom_css = CASE WHEN 'custom_css' = ANY (v_take) THEN COALESCE(v_now ->> 'custom_css', custom_css) ELSE custom_css END,
      navigation = CASE WHEN 'navigation' = ANY (v_take) THEN COALESCE(NULLIF(v_now -> 'navigation', 'null'), navigation) ELSE navigation END,
      seo = CASE WHEN 'seo' = ANY (v_take) THEN COALESCE(NULLIF(v_now -> 'seo', 'null'), seo) ELSE seo END,
      tracking = CASE WHEN 'tracking' = ANY (v_take) THEN COALESCE(NULLIF(v_now -> 'tracking', 'null'), tracking) ELSE tracking END,
      header_id = CASE WHEN 'header_id' = ANY (v_take) THEN (v_now ->> 'header_id')::uuid ELSE header_id END,
      footer_id = CASE WHEN 'footer_id' = ANY (v_take) THEN (v_now ->> 'footer_id')::uuid ELSE footer_id END,
      header_menu_id = CASE WHEN 'header_menu_id' = ANY (v_take) THEN (v_now ->> 'header_menu_id')::uuid ELSE header_menu_id END,
      footer_menu_id = CASE WHEN 'footer_menu_id' = ANY (v_take) THEN (v_now ->> 'footer_menu_id')::uuid ELSE footer_menu_id END,
      front_page_id = CASE WHEN 'front_page_id' = ANY (v_take) THEN (v_now ->> 'front_page_id')::uuid ELSE front_page_id END
    WHERE id = v_house;
    INSERT INTO commerce.house_site_copies (store_id, source_id, copy_id, kind, copied_at, settings)
    VALUES (v_house, v_house, v_house, 'settings', now(), v_now)
    ON CONFLICT (store_id, source_id) DO UPDATE SET copied_at = excluded.copied_at, settings = excluded.settings;
  END IF;

  INSERT INTO commerce.house_site_copies (store_id, source_id, copy_id, kind, copied_at)
  SELECT v_house, s.old_id, s.new_id, s.kind, now() FROM pg_temp._site_src s
  ON CONFLICT (store_id, source_id) DO UPDATE SET copied_at = excluded.copied_at;

  SELECT COALESCE(jsonb_object_agg(kind, n), '{}'::jsonb) INTO v_counts FROM (SELECT kind, count(*) AS n FROM pg_temp._site_src GROUP BY kind) k;
  -- How many settings the store kept as its own where the live site's differ, for the admin to say.
  IF v_settings.id IS NOT NULL THEN
    v_counts := v_counts || jsonb_build_object('settings_kept', (
      SELECT count(*) FROM jsonb_object_keys(v_now) AS k
       WHERE NOT (k = ANY (v_take)) AND COALESCE(v_have -> k, 'null') <> COALESCE(v_now -> k, 'null')
    ));
  END IF;
  RETURN v_counts;
END;
$$;


--
-- Name: copy_prune(jsonb, text[]); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.copy_prune(p_json jsonb, p_gone text[]) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
BEGIN
  IF jsonb_typeof(p_json) = 'array' THEN
    RETURN coalesce((
      SELECT jsonb_agg(commerce.copy_prune(e.value, p_gone) ORDER BY e.ord)
        FROM jsonb_array_elements(p_json) WITH ORDINALITY AS e(value, ord)
       WHERE NOT (jsonb_typeof(e.value) = 'string' AND (e.value #>> '{}') = ANY (p_gone))
         AND NOT (jsonb_typeof(e.value) = 'object' AND (e.value ->> 'ref') = ANY (p_gone))
    ), '[]'::jsonb);
  ELSIF jsonb_typeof(p_json) = 'object' THEN
    RETURN coalesce((
      SELECT jsonb_object_agg(m.key, commerce.copy_prune(m.value, p_gone))
        FROM jsonb_each(p_json) AS m(key, value)
       WHERE NOT (jsonb_typeof(m.value) = 'string' AND (m.value #>> '{}') = ANY (p_gone))
         AND NOT (jsonb_typeof(m.value) = 'object' AND (m.value ->> 'ref') = ANY (p_gone))
    ), '{}'::jsonb);
  END IF;
  RETURN p_json;
END;
$$;


--
-- Name: copy_remap(jsonb, uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.copy_remap(p_json jsonb, p_source uuid, p_new uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_text text;
  v_old uuid;
  v_new uuid;
  v_found boolean;
  v_gone text[] := '{}';
BEGIN
  IF p_json IS NULL THEN
    RETURN NULL;
  END IF;
  v_text := p_json::text;
  FOR v_old IN
    SELECT DISTINCT lower(r.m[1])::uuid
      FROM regexp_matches(v_text, '"([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})"', 'g') AS r(m)
  LOOP
    SELECT true, c.new_id INTO v_found, v_new FROM pg_temp._copy_ids c WHERE c.old_id = v_old;
    IF v_found IS NOT TRUE THEN
      CONTINUE;
    END IF;
    IF v_new IS NULL THEN
      v_gone := v_gone || v_old::text;
    ELSE
      v_text := replace(v_text, '"' || v_old::text || '"', '"' || v_new::text || '"');
    END IF;
    v_found := NULL;
    v_new := NULL;
  END LOOP;
  v_text := replace(v_text, '"' || p_source::text || '"', '"' || p_new::text || '"');
  IF cardinality(v_gone) > 0 THEN
    RETURN commerce.copy_prune(v_text::jsonb, v_gone);
  END IF;
  RETURN v_text::jsonb;
END;
$$;


--
-- Name: copy_text_styles(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.copy_text_styles(p_source uuid, p_store uuid) RETURNS void
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  INSERT INTO commerce.text_styles (store_id, slug, name, kind, settings, css, position)
  SELECT p_store, slug, name, kind, settings, css, position
    FROM commerce.text_styles WHERE store_id = p_source
  ON CONFLICT ON CONSTRAINT text_styles_owner_slug DO NOTHING;
$$;


--
-- Name: creator_attribute_order(uuid, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.creator_attribute_order(p_order uuid, p_code text) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_o commerce.orders%ROWTYPE;
  v_c commerce.creators%ROWTYPE;
  v_self boolean;
BEGIN
  SELECT * INTO v_o FROM commerce.orders o WHERE o.id = p_order;
  IF NOT FOUND OR p_code IS NULL OR v_o.copied_from IS NOT NULL OR v_o.host_id IS NOT NULL OR v_o.source = 'exchange' THEN
    RETURN 'none';
  END IF;
  IF NOT commerce.creator_program_on(v_o.store_id) THEN
    RETURN 'off';
  END IF;
  SELECT * INTO v_c FROM commerce.creators c WHERE c.store_id = v_o.store_id AND c.code = p_code AND c.status = 'approved';
  IF NOT FOUND THEN
    RETURN 'none';
  END IF;
  v_self := commerce.creator_is_self(v_o.store_id, v_c.id, v_o.customer_id, v_o.email);
  INSERT INTO commerce.creator_attributions (store_id, order_id, creator_id, code, status, reject_reason)
  VALUES (v_o.store_id, p_order, v_c.id, v_c.code, CASE WHEN v_self THEN 'rejected' ELSE 'pending' END, CASE WHEN v_self THEN 'self' END)
  ON CONFLICT (store_id, order_id) DO NOTHING;
  RETURN CASE WHEN v_self THEN 'self' ELSE 'ok' END;
END;
$$;


--
-- Name: creator_attributions_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.creator_attributions_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_o commerce.orders%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'commerce.creator_attributions is append-only' USING ERRCODE = 'restrict_violation';
  END IF;
  IF TG_OP = 'INSERT' THEN
    SELECT * INTO v_o FROM commerce.orders o WHERE o.store_id = NEW.store_id AND o.id = NEW.order_id;
    -- A copied order is history (D129), a host's the host's (D71), an exchange's a returned order's (D239): none is attributed.
    IF v_o.copied_from IS NOT NULL OR v_o.host_id IS NOT NULL OR v_o.source = 'exchange' THEN
      RAISE EXCEPTION 'creator.not_attributable' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status NOT IN ('pending', 'rejected') THEN
      RAISE EXCEPTION 'creator.bad_status' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.order_id <> OLD.order_id OR NEW.creator_id <> OLD.creator_id OR NEW.code <> OLD.code OR NEW.store_id <> OLD.store_id THEN
    RAISE EXCEPTION 'creator.fixed' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status <> OLD.status AND NOT (
       (OLD.status = 'pending' AND NEW.status IN ('earned', 'rejected', 'reversed'))
    OR (OLD.status = 'earned' AND NEW.status = 'reversed')
  ) THEN
    RAISE EXCEPTION 'creator.bad_status' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: creator_is_self(uuid, uuid, uuid, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.creator_is_self(p_store uuid, p_creator uuid, p_customer uuid, p_email text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM commerce.creators cr
      LEFT JOIN commerce.customers c ON c.store_id = cr.store_id AND c.id = cr.customer_id
     WHERE cr.store_id = p_store AND cr.id = p_creator
       AND (cr.customer_id = p_customer OR (c.email <> '' AND lower(c.email) = lower(coalesce(p_email, ''))))
  )
$$;


--
-- Name: creator_ledger_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.creator_ledger_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    RAISE EXCEPTION 'commerce.% is append-only', TG_TABLE_NAME USING ERRCODE = 'restrict_violation';
  END IF;
  IF TG_TABLE_NAME = 'creator_payouts' THEN
    PERFORM commerce.creator_lock(NEW.store_id, NEW.creator_id);
    IF NEW.amount_minor > commerce.creator_owed(NEW.store_id, NEW.creator_id, NEW.currency) THEN
      RAISE EXCEPTION 'creator.payout_over' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: creator_line_bps(uuid, uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.creator_line_bps(p_store uuid, p_creator uuid, p_product uuid) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce(
    (SELECT cr.commission_bps FROM commerce.creators cr WHERE cr.store_id = p_store AND cr.id = p_creator),
    (SELECT max((s.category_bps ->> t.id::text)::int)
       FROM commerce.creator_settings s
       JOIN commerce.terms t ON t.store_id = s.store_id AND s.category_bps ? t.id::text
      WHERE s.store_id = p_store AND t.content_type = 'product'
        AND (EXISTS (SELECT 1 FROM commerce.product_terms pt
                      WHERE pt.store_id = t.store_id AND pt.term_id = t.id AND pt.product_id = p_product)
             OR (t.rules IS NOT NULL AND commerce.product_matches_rules(p_store, p_product, t.rules)))),
    (SELECT s.commission_bps FROM commerce.creator_settings s WHERE s.store_id = p_store),
    0
  )
$$;


--
-- Name: creator_lock(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.creator_lock(p_store uuid, p_creator uuid) RETURNS void
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  SELECT pg_advisory_xact_lock(hashtext('creator:' || p_store::text || ':' || p_creator::text))
$$;


--
-- Name: creator_order_cancelled(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.creator_order_cancelled(p_order uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_o commerce.orders%ROWTYPE;
  v_a commerce.creator_attributions%ROWTYPE;
  v_earned commerce.creator_commissions%ROWTYPE;
  v_done bigint;
BEGIN
  SELECT * INTO v_o FROM commerce.orders o WHERE o.id = p_order;
  IF NOT FOUND THEN
    RETURN;
  END IF;
  SELECT * INTO v_a FROM commerce.creator_attributions a WHERE a.store_id = v_o.store_id AND a.order_id = p_order;
  IF NOT FOUND THEN
    RETURN;
  END IF;
  PERFORM commerce.creator_lock(v_o.store_id, v_a.creator_id);
  SELECT * INTO v_a FROM commerce.creator_attributions a WHERE a.id = v_a.id FOR UPDATE;
  IF v_a.status = 'pending' THEN
    UPDATE commerce.creator_attributions SET status = 'reversed' WHERE id = v_a.id;
    RETURN;
  END IF;
  IF v_a.status <> 'earned' THEN
    RETURN;
  END IF;
  SELECT * INTO v_earned FROM commerce.creator_commissions c
   WHERE c.store_id = v_o.store_id AND c.idempotency_key = 'creator:' || p_order;
  SELECT coalesce(sum(c.amount_minor), 0) INTO v_done FROM commerce.creator_commissions c
   WHERE c.store_id = v_o.store_id AND c.order_id = p_order AND c.kind = 'reversed';
  IF v_earned.id IS NOT NULL AND v_earned.amount_minor > v_done THEN
    INSERT INTO commerce.creator_commissions (store_id, creator_id, order_id, kind, currency, amount_minor, idempotency_key)
    VALUES (v_o.store_id, v_a.creator_id, p_order, 'reversed', v_earned.currency, v_earned.amount_minor - v_done,
            'creator-reverse-cancel:' || p_order)
    ON CONFLICT (store_id, idempotency_key) DO NOTHING;
  END IF;
  UPDATE commerce.creator_attributions SET status = 'reversed' WHERE id = v_a.id;
END;
$$;


--
-- Name: creator_order_paid(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.creator_order_paid(p_order uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_o commerce.orders%ROWTYPE;
  v_a commerce.creator_attributions%ROWTYPE;
  v_amount bigint;
BEGIN
  SELECT * INTO v_o FROM commerce.orders o WHERE o.id = p_order;
  IF NOT FOUND OR v_o.copied_from IS NOT NULL OR v_o.host_id IS NOT NULL OR v_o.status NOT IN ('paid', 'fulfilled', 'closed') THEN
    RETURN;
  END IF;
  SELECT * INTO v_a FROM commerce.creator_attributions a WHERE a.store_id = v_o.store_id AND a.order_id = p_order;
  IF NOT FOUND OR v_a.status <> 'pending' THEN
    RETURN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM commerce.payments p WHERE p.store_id = v_o.store_id AND p.order_id = p_order AND p.status = 'captured') THEN
    RETURN;
  END IF;
  PERFORM commerce.creator_lock(v_o.store_id, v_a.creator_id);
  SELECT * INTO v_a FROM commerce.creator_attributions a WHERE a.id = v_a.id FOR UPDATE;
  IF v_a.status <> 'pending' THEN
    RETURN;
  END IF;
  -- The creator bought for themselves under another account's address, or as a guest with their own.
  IF commerce.creator_is_self(v_o.store_id, v_a.creator_id, v_o.customer_id, v_o.email) THEN
    UPDATE commerce.creator_attributions SET status = 'rejected', reject_reason = 'self' WHERE id = v_a.id;
    RETURN;
  END IF;
  SELECT floor(coalesce(sum((ol.total_minor - ol.tax_minor)::numeric * commerce.creator_line_bps(v_o.store_id, v_a.creator_id, v.product_id)), 0) / 10000)::bigint
    INTO v_amount
    FROM commerce.order_lines ol
    JOIN commerce.product_variants v ON v.store_id = ol.store_id AND v.id = ol.variant_id
    JOIN commerce.products pr ON pr.store_id = v.store_id AND pr.id = v.product_id
   WHERE ol.store_id = v_o.store_id AND ol.order_id = p_order
     AND ol.delivery IN ('physical', 'digital') AND pr.kind <> 'gift_card' AND ol.total_minor > ol.tax_minor;
  IF v_amount IS NULL OR v_amount <= 0 THEN
    UPDATE commerce.creator_attributions SET status = 'rejected', reject_reason = 'zero' WHERE id = v_a.id;
    RETURN;
  END IF;
  INSERT INTO commerce.creator_commissions (store_id, creator_id, order_id, kind, currency, amount_minor, idempotency_key)
  VALUES (v_o.store_id, v_a.creator_id, p_order, 'earned', v_o.currency, v_amount, 'creator:' || p_order)
  ON CONFLICT (store_id, idempotency_key) DO NOTHING;
  UPDATE commerce.creator_attributions SET status = 'earned' WHERE id = v_a.id;
  -- A refund made before the payment was read is taken into account at once.
  PERFORM commerce.creator_settle_refunds(v_o.store_id, p_order, 'creator-reverse-paid:' || p_order);
END;
$$;


--
-- Name: creator_owed(uuid, uuid, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.creator_owed(p_store uuid, p_creator uuid, p_currency text) RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce((SELECT sum(CASE WHEN c.kind = 'earned' THEN c.amount_minor ELSE -c.amount_minor END)
                     FROM commerce.creator_commissions c
                    WHERE c.store_id = p_store AND c.creator_id = p_creator AND c.currency = p_currency), 0)
       - coalesce((SELECT sum(p.amount_minor) FROM commerce.creator_payouts p
                    WHERE p.store_id = p_store AND p.creator_id = p_creator AND p.currency = p_currency), 0)
$$;


--
-- Name: creator_paid_refunded(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.creator_paid_refunded(p_store uuid, p_order uuid, OUT paid bigint, OUT refunded bigint) RETURNS record
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT
    coalesce((SELECT sum(p.amount_minor) FROM commerce.payments p
               WHERE p.store_id = p_store AND p.order_id = p_order AND p.status = 'captured'
                 AND commerce.payment_of_order(p.store_id, p.id)), 0),
    coalesce((SELECT sum(r.amount_minor) FROM commerce.refunds r
                JOIN commerce.payments p ON p.store_id = r.store_id AND p.id = r.payment_id
               WHERE p.store_id = p_store AND p.order_id = p_order AND r.status <> 'failed' AND r.kind NOT IN ('release', 'void')
                 AND commerce.payment_of_order(p.store_id, p.id)), 0)
$$;


--
-- Name: creator_program_on(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.creator_program_on(p_store uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT commerce.feature_on(p_store, 'shop')
     AND coalesce((SELECT s.enabled FROM commerce.creator_settings s WHERE s.store_id = p_store), false)
$$;


--
-- Name: creator_settle_refunds(uuid, uuid, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.creator_settle_refunds(p_store uuid, p_order uuid, p_key text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_a commerce.creator_attributions%ROWTYPE;
  v_earned commerce.creator_commissions%ROWTYPE;
  v_paid bigint;
  v_refunded bigint;
  v_target bigint;
  v_done bigint;
BEGIN
  SELECT * INTO v_a FROM commerce.creator_attributions a WHERE a.store_id = p_store AND a.order_id = p_order;
  IF NOT FOUND OR v_a.status <> 'earned' THEN
    RETURN;
  END IF;
  SELECT * INTO v_earned FROM commerce.creator_commissions c
   WHERE c.store_id = p_store AND c.idempotency_key = 'creator:' || p_order;
  IF NOT FOUND THEN
    RETURN;
  END IF;
  SELECT x.paid, x.refunded INTO v_paid, v_refunded FROM commerce.creator_paid_refunded(p_store, p_order) x;
  IF v_paid <= 0 OR v_refunded <= 0 THEN
    RETURN;
  END IF;
  v_target := CASE WHEN v_refunded >= v_paid THEN v_earned.amount_minor
                   ELSE floor(v_earned.amount_minor::numeric * v_refunded / v_paid)::bigint END;
  SELECT coalesce(sum(c.amount_minor), 0) INTO v_done FROM commerce.creator_commissions c
   WHERE c.store_id = p_store AND c.order_id = p_order AND c.kind = 'reversed';
  IF v_target > v_done THEN
    INSERT INTO commerce.creator_commissions (store_id, creator_id, order_id, kind, currency, amount_minor, idempotency_key)
    VALUES (p_store, v_a.creator_id, p_order, 'reversed', v_earned.currency, v_target - v_done, p_key)
    ON CONFLICT (store_id, idempotency_key) DO NOTHING;
  END IF;
  IF v_refunded >= v_paid THEN
    UPDATE commerce.creator_attributions SET status = 'reversed' WHERE id = v_a.id;
  END IF;
END;
$$;


--
-- Name: creators_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.creators_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'applied' OR NEW.code IS NOT NULL THEN
      RAISE EXCEPTION 'creator.not_applied' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.store_id <> OLD.store_id OR NEW.id <> OLD.id OR NEW.consent_text <> OLD.consent_text OR NEW.consented_at <> OLD.consented_at THEN
    RAISE EXCEPTION 'creator.fixed' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.customer_id IS DISTINCT FROM OLD.customer_id AND NEW.customer_id IS NOT NULL THEN
    RAISE EXCEPTION 'creator.customer_fixed' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.code IS NOT NULL AND NEW.code IS DISTINCT FROM OLD.code THEN
    RAISE EXCEPTION 'creator.code_fixed' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status <> OLD.status AND NOT (
       (OLD.status = 'applied' AND NEW.status IN ('approved', 'declined'))
    OR (OLD.status = 'approved' AND NEW.status = 'stopped')
    OR (OLD.status IN ('stopped', 'declined') AND NEW.status = 'approved')
  ) THEN
    RAISE EXCEPTION 'creator.bad_status' USING ERRCODE = 'check_violation';
  END IF;
  -- A creator forgotten (erasure) never works again.
  IF NEW.customer_id IS NULL AND NEW.status = 'approved' THEN
    RAISE EXCEPTION 'creator.erased' USING ERRCODE = 'check_violation';
  END IF;
  -- A code is the store's once, across the referral program's codes too.
  IF NEW.code IS NOT NULL AND OLD.code IS NULL
     AND EXISTS (SELECT 1 FROM commerce.affiliates a WHERE a.store_id = NEW.store_id AND a.code = NEW.code) THEN
    RAISE EXCEPTION 'creator.code_taken' USING ERRCODE = 'unique_violation';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: credit_vat(bigint, numeric, bigint, bigint, bigint); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.credit_vat(p_gross bigint, p_rate numeric, p_gross_left bigint, p_net_left bigint, p_vat_left bigint) RETURNS bigint
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT CASE
    WHEN p_gross <= 0 THEN 0::bigint
    WHEN p_gross >= p_gross_left THEN p_vat_left
    ELSE greatest(least(commerce.vat_incl(p_gross, p_rate), p_vat_left), p_gross - p_net_left)
  END
$$;


--
-- Name: credit_vat_converted(jsonb, bigint[], bigint[], numeric); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.credit_vat_converted(p_buckets jsonb, p_left bigint[], p_vat bigint[], p_fx numeric) RETURNS bigint
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce(sum(commerce.convert_with(z.before + p_vat[z.i], p_fx) - commerce.convert_with(z.before, p_fx)), 0)::bigint
    FROM (
      SELECT i, ((p_buckets -> (i - 1)) ->> 'vatMinor')::bigint - p_left[i] AS before
        FROM generate_series(1, coalesce(array_length(p_vat, 1), 0)) AS i
    ) z
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: work_credit_notes; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.work_credit_notes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    invoice_id uuid NOT NULL,
    series text DEFAULT 'work_credit_note'::text NOT NULL,
    number bigint NOT NULL,
    document_number text NOT NULL,
    issued_on date NOT NULL,
    currency character(3) NOT NULL,
    reason text,
    subtotal_minor bigint NOT NULL,
    vat_minor bigint NOT NULL,
    total_minor bigint NOT NULL,
    vat_home_minor bigint,
    fx_rate numeric(18,8),
    lines jsonb NOT NULL,
    seller jsonb NOT NULL,
    buyer jsonb NOT NULL,
    vat_notes jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT work_credit_notes_amounts CHECK (((subtotal_minor >= 0) AND (vat_minor >= 0) AND (total_minor > 0) AND (total_minor = (subtotal_minor + vat_minor)))),
    CONSTRAINT work_credit_notes_currency CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT work_credit_notes_lines CHECK (((jsonb_typeof(lines) = 'array'::text) AND (jsonb_array_length(lines) > 0))),
    CONSTRAINT work_credit_notes_reason CHECK ((length(COALESCE(reason, ''::text)) <= 1000)),
    CONSTRAINT work_credit_notes_series CHECK ((series = 'work_credit_note'::text))
);


--
-- Name: credit_work_invoice(uuid, uuid, uuid, text, jsonb, date, boolean); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.credit_work_invoice(p_store uuid, p_invoice uuid, p_account uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_lines jsonb DEFAULT NULL::jsonb, p_issued_on date DEFAULT NULL::date, p_allow_earlier_date boolean DEFAULT false) RETURNS commerce.work_credit_notes
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_inv commerce.work_invoices;
  v_note commerce.work_credit_notes;
  v_today date;
  v_issued date;
  v_prev date;
  v_number bigint;
  v_prefix text;
  v_lines jsonb;
  v_sub bigint;
  v_vat bigint;
  v_element jsonb;
  v_seen uuid[] := '{}';
  v_line_id uuid;
BEGIN
  -- A change of the business behind the store whose day has come takes effect before anything is numbered (D473).
  PERFORM commerce.apply_business_change(p_store);
  SELECT * INTO v_inv FROM commerce.work_invoices WHERE store_id = p_store AND id = p_invoice FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'work_credit_note.not_found' USING ERRCODE = 'no_data_found';
  END IF;
  IF v_inv.status NOT IN ('sent', 'paid') THEN
    RAISE EXCEPTION 'work_credit_note.status: only an issued invoice that is not already credited can be credited'
      USING ERRCODE = 'check_violation';
  END IF;

  IF p_lines IS NOT NULL THEN
    IF jsonb_typeof(p_lines) <> 'array' OR jsonb_array_length(p_lines) = 0 THEN
      RAISE EXCEPTION 'work_credit_note.lines: lines must be a list of { line_id, quantity_hundredths }' USING ERRCODE = 'check_violation';
    END IF;
    FOR v_element IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
      v_line_id := (v_element ->> 'line_id')::uuid;
      IF v_line_id IS NULL OR v_line_id = ANY (v_seen) THEN
        RAISE EXCEPTION 'work_credit_note.lines: each line once' USING ERRCODE = 'check_violation';
      END IF;
      v_seen := v_seen || v_line_id;
    END LOOP;
  END IF;

  -- What each line has left to credit, and the part being credited now.
  WITH done AS (
    SELECT (e ->> 'line_id')::uuid AS line_id,
           sum((e ->> 'quantity_hundredths')::integer)::integer AS qty,
           sum((e ->> 'excl_minor')::bigint)::bigint AS excl,
           sum((e ->> 'vat_minor')::bigint)::bigint AS vat
      FROM commerce.work_credit_notes c, jsonb_array_elements(c.lines) e
     WHERE c.store_id = p_store AND c.invoice_id = p_invoice
     GROUP BY 1
  ), asked AS (
    SELECT l.id AS line_id, l.position, l.description, l.unit, l.quantity_hundredths, l.unit_price_minor,
           l.discount_bp, l.vat_category, l.vat_rate, l.excl_minor, l.vat_minor,
           (l.quantity_hundredths - coalesce(d.qty, 0))::integer AS remaining,
           coalesce(d.excl, 0) AS done_excl, coalesce(d.vat, 0) AS done_vat,
           CASE WHEN p_lines IS NULL THEN NULL
                ELSE (SELECT nullif(e ->> 'quantity_hundredths', '')::integer
                        FROM jsonb_array_elements(p_lines) e WHERE (e ->> 'line_id')::uuid = l.id) END AS wanted,
           CASE WHEN p_lines IS NULL THEN true
                ELSE EXISTS (SELECT 1 FROM jsonb_array_elements(p_lines) e WHERE (e ->> 'line_id')::uuid = l.id) END AS included
      FROM commerce.work_invoice_lines l LEFT JOIN done d ON d.line_id = l.id
     WHERE l.store_id = p_store AND l.invoice_id = p_invoice
  ), part AS (
    SELECT a.*, coalesce(a.wanted, a.remaining) AS qty FROM asked a WHERE a.included AND a.remaining > 0
  ), priced AS (
    SELECT p.*,
           CASE WHEN p.qty = p.remaining THEN p.excl_minor - p.done_excl
                ELSE commerce.work_line_excl(p.qty, p.unit_price_minor, p.discount_bp) END AS c_excl
      FROM part p
  ), finished AS (
    SELECT p.*, CASE WHEN p.qty = p.remaining THEN p.vat_minor - p.done_vat
                     ELSE commerce.work_line_vat(p.c_excl, p.vat_rate) END AS c_vat
      FROM priced p
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'line_id', f.line_id, 'position', f.position, 'description', f.description, 'unit', f.unit,
           'quantity_hundredths', f.qty, 'unit_price_minor', f.unit_price_minor, 'discount_bp', f.discount_bp,
           'vat_category', f.vat_category, 'vat_rate', f.vat_rate,
           'excl_minor', f.c_excl, 'vat_minor', f.c_vat, 'incl_minor', f.c_excl + f.c_vat) ORDER BY f.position, f.line_id), '[]'::jsonb),
         coalesce(sum(f.c_excl), 0), coalesce(sum(f.c_vat), 0)
    INTO v_lines, v_sub, v_vat
    FROM finished f;

  IF p_lines IS NOT NULL THEN
    -- Every line asked for must exist on the invoice, have something left, and not more than it has.
    IF jsonb_array_length(v_lines) <> jsonb_array_length(p_lines) THEN
      RAISE EXCEPTION 'work_credit_note.lines: a line is not on the invoice or has nothing left to credit' USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (
      SELECT 1 FROM jsonb_array_elements(p_lines) e
       WHERE nullif(e ->> 'quantity_hundredths', '') IS NOT NULL AND (e ->> 'quantity_hundredths')::integer <= 0
    ) OR EXISTS (
      SELECT 1 FROM jsonb_array_elements(p_lines) e
        JOIN commerce.work_invoice_lines l ON l.store_id = p_store AND l.invoice_id = p_invoice AND l.id = (e ->> 'line_id')::uuid
       WHERE nullif(e ->> 'quantity_hundredths', '') IS NOT NULL
         AND (e ->> 'quantity_hundredths')::integer > l.quantity_hundredths - coalesce((
               SELECT sum((x ->> 'quantity_hundredths')::integer)
                 FROM commerce.work_credit_notes c, jsonb_array_elements(c.lines) x
                WHERE c.store_id = p_store AND c.invoice_id = p_invoice AND (x ->> 'line_id')::uuid = l.id), 0)
    ) THEN
      RAISE EXCEPTION 'work_credit_note.quantity: more than is left of a line' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF v_sub + v_vat <= 0 THEN
    RAISE EXCEPTION 'work_credit_note.nothing_to_credit: there is nothing left to credit' USING ERRCODE = 'check_violation';
  END IF;

  v_today := commerce.work_today(p_store);
  v_issued := coalesce(p_issued_on, v_today);
  IF v_issued > v_today THEN
    RAISE EXCEPTION 'work_credit_note.date_in_future: a credit note cannot be issued for a later day' USING ERRCODE = 'check_violation';
  END IF;
  IF v_issued < v_inv.issued_on THEN
    RAISE EXCEPTION 'work_credit_note.date_before_invoice: the invoice is dated %', v_inv.issued_on USING ERRCODE = 'check_violation';
  END IF;

  v_number := commerce.next_document_number(p_store, 'work_credit_note');
  SELECT ds.prefix INTO v_prefix FROM commerce.document_series ds WHERE ds.store_id = p_store AND ds.series = 'work_credit_note';
  SELECT max(c.issued_on) INTO v_prev FROM commerce.work_credit_notes c WHERE c.store_id = p_store;
  IF v_prev IS NOT NULL AND v_issued < v_prev AND NOT p_allow_earlier_date THEN
    RAISE EXCEPTION 'work_credit_note.date_before_previous: the previous credit note is dated %', v_prev USING ERRCODE = 'check_violation';
  END IF;

  INSERT INTO commerce.work_credit_notes (
    store_id, invoice_id, number, document_number, issued_on, currency, reason,
    subtotal_minor, vat_minor, total_minor, vat_home_minor, fx_rate, lines, seller, buyer, vat_notes, created_by)
  VALUES (
    p_store, p_invoice, v_number, v_prefix || v_number::text, v_issued, v_inv.currency, nullif(trim(p_reason), ''),
    v_sub, v_vat, v_sub + v_vat,
    CASE WHEN v_inv.fx_rate IS NULL THEN NULL ELSE floor(v_vat * v_inv.fx_rate + 0.5)::bigint END,
    v_inv.fx_rate, v_lines, v_inv.seller, v_inv.buyer, v_inv.vat_notes, p_account)
  RETURNING * INTO v_note;

  PERFORM commerce.work_event(
    p_store, 'invoice', p_invoice, 'invoice.credited',
    jsonb_build_object('credit_note_id', v_note.id, 'document_number', v_note.document_number,
                       'total_minor', v_note.total_minor, 'currency', v_note.currency),
    p_account);

  -- Fully credited: the invoice is void (set by the credit note's trigger), and its time is free again.
  IF (SELECT i.status FROM commerce.work_invoices i WHERE i.store_id = p_store AND i.id = p_invoice) = 'void' THEN
    UPDATE commerce.work_time_entries e SET invoice_line_id = NULL, updated_at = now()
     WHERE e.store_id = p_store
       AND e.invoice_line_id IN (SELECT l.id FROM commerce.work_invoice_lines l WHERE l.store_id = p_store AND l.invoice_id = p_invoice);
  END IF;
  RETURN v_note;
END;
$$;


--
-- Name: customer_addresses_max(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.customer_addresses_max() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM 1 FROM commerce.customers WHERE store_id = NEW.store_id AND id = NEW.customer_id FOR UPDATE;
  IF (SELECT count(*) FROM commerce.customer_addresses WHERE store_id = NEW.store_id AND customer_id = NEW.customer_id) >= 20 THEN
    RAISE EXCEPTION 'customer_addresses.too_many' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: customer_notes_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.customer_notes_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.id <> OLD.id OR NEW.store_id <> OLD.store_id OR NEW.body <> OLD.body
     OR NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'customer_notes.fixed: a note is never edited, only moved with its person' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: customer_tags_limit(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.customer_tags_limit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('customer_tags:' || NEW.store_id::text || ':' || NEW.email, 0));
  IF (SELECT count(*) FROM commerce.customer_tags t WHERE t.store_id = NEW.store_id AND t.email = NEW.email) >= 50 THEN
    RAISE EXCEPTION 'customer_tags.limit: a person has at most 50 tags' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: customers_leave_locations(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.customers_leave_locations() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  DELETE FROM commerce.company_location_buyers b
  USING commerce.company_locations l
  WHERE b.store_id = NEW.store_id AND b.customer_id = NEW.id AND l.store_id = b.store_id AND l.id = b.location_id
    AND (l.company_id IS DISTINCT FROM NEW.company_id OR NEW.company_role IS DISTINCT FROM 'employee');
  RETURN NULL;
END;
$$;


--
-- Name: customers_referred_by_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.customers_referred_by_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.referred_by_customer_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.referred_by_customer_id IS NOT NULL
     AND OLD.referred_by_customer_id IS DISTINCT FROM NEW.referred_by_customer_id THEN
    RAISE EXCEPTION 'affiliate.moved' USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW.referred_by_customer_id = NEW.id THEN
    RAISE EXCEPTION 'affiliate.self' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM commerce.affiliates a
                  WHERE a.store_id = NEW.store_id AND a.customer_id = NEW.referred_by_customer_id) THEN
    RAISE EXCEPTION 'affiliate.unknown' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: data_job_move_allowed(text, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.data_job_move_allowed(p_from text, p_to text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT p_from = p_to OR CASE p_from
    WHEN 'uploaded'  THEN p_to IN ('checking', 'cancelled', 'failed', 'expired')
    WHEN 'checking'  THEN p_to IN ('checked', 'cancelled', 'failed')
    WHEN 'checked'   THEN p_to IN ('checking', 'queued', 'cancelled', 'failed', 'expired')
    WHEN 'queued'    THEN p_to IN ('running', 'cancelled', 'failed')
    WHEN 'running'   THEN p_to IN ('done', 'failed', 'cancelled')
    WHEN 'done'      THEN p_to = 'expired'
    WHEN 'failed'    THEN p_to = 'expired'
    WHEN 'cancelled' THEN p_to = 'expired'
    ELSE false
  END
$$;


--
-- Name: data_jobs_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.data_jobs_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_import boolean := NEW.kind IN ('product_import', 'redirect_import', 'inventory_import', 'customer_import', 'order_history_import');
  v_ended boolean;
BEGIN
  IF TG_OP = 'UPDATE' AND (NEW.id <> OLD.id OR NEW.store_id <> OLD.store_id OR NEW.kind <> OLD.kind OR NEW.requested_by <> OLD.requested_by) THEN
    RAISE EXCEPTION 'data_job.fixed: a job stays with its store, kind and requester' USING ERRCODE = 'check_violation';
  END IF;

  -- What states a kind of job can be in: an export never uploads, checks or waits to be applied.
  IF NOT v_import AND NEW.status IN ('uploaded', 'checking', 'checked') THEN
    RAISE EXCEPTION 'data_job.status_kind: an export has no upload or check step' USING ERRCODE = 'check_violation';
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF (v_import AND NEW.status <> 'uploaded') OR (NOT v_import AND NEW.status <> 'queued') THEN
      RAISE EXCEPTION 'data_job.start: an import starts as uploaded and an export as queued' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE
  IF NOT commerce.data_job_move_allowed(OLD.status, NEW.status) THEN
    RAISE EXCEPTION 'data_job.status: a job cannot go from % to %', OLD.status, NEW.status USING ERRCODE = 'check_violation';
  END IF;

  -- The file an import was registered with is the one it is checked and applied against; it can only be cleared when purged.
  IF OLD.input_sha256 IS NOT NULL THEN
    IF (NEW.input_sha256 IS DISTINCT FROM OLD.input_sha256 AND NOT (NEW.input_sha256 IS NULL AND NEW.purged_at IS NOT NULL))
       OR (NEW.input_path IS DISTINCT FROM OLD.input_path AND NOT (NEW.input_path IS NULL AND NEW.purged_at IS NOT NULL))
       OR (NEW.input_bytes IS DISTINCT FROM OLD.input_bytes AND NOT (NEW.input_bytes IS NULL AND NEW.purged_at IS NOT NULL)) THEN
      RAISE EXCEPTION 'data_job.file_fixed: a job cannot be pointed at another file; upload it again as a new job' USING ERRCODE = 'check_violation';
    END IF;
  ELSIF NEW.input_sha256 IS NOT NULL AND OLD.status NOT IN ('uploaded', 'checking') THEN
    RAISE EXCEPTION 'data_job.file_fixed: the file is registered while the job is uploaded' USING ERRCODE = 'check_violation';
  END IF;

  -- The choices: an export's are fixed from the start; an import's until it is applied (a checked import whose options change
  -- is checked again, which is the one move back).
  IF NEW.options IS DISTINCT FROM OLD.options THEN
    IF NOT v_import OR NOT (OLD.status IN ('uploaded', 'checking') OR (OLD.status = 'checked' AND NEW.status = 'checking')) THEN
      RAISE EXCEPTION 'data_job.options_fixed: the options of a job are fixed once it is checked; check it again to change them' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF OLD.status = 'checked' AND NEW.status = 'queued' AND NEW.options IS DISTINCT FROM OLD.options THEN
    RAISE EXCEPTION 'data_job.options_fixed: the options changed since the check' USING ERRCODE = 'check_violation';
  END IF;

  -- An ended job's figures are final (its files may still be purged, and its status become expired).
  v_ended := OLD.status IN ('done', 'failed', 'cancelled', 'expired');
  IF v_ended AND (NEW.counts IS DISTINCT FROM OLD.counts OR NEW.cursor IS DISTINCT FROM OLD.cursor
                  OR NEW.rows_total IS DISTINCT FROM OLD.rows_total OR NEW.rows_done IS DISTINCT FROM OLD.rows_done
                  OR NEW.started_at IS DISTINCT FROM OLD.started_at OR NEW.finished_at IS DISTINCT FROM OLD.finished_at
                  OR NEW.attempts IS DISTINCT FROM OLD.attempts OR NEW.format IS DISTINCT FROM OLD.format) THEN
    RAISE EXCEPTION 'data_job.ended: a job that has ended keeps its figures' USING ERRCODE = 'check_violation';
  END IF;
  IF v_ended AND NEW.files IS DISTINCT FROM OLD.files AND NEW.purged_at IS NULL THEN
    RAISE EXCEPTION 'data_job.ended: the files of an ended job are only removed, by marking it purged' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.purged_at IS NOT NULL AND NEW.purged_at IS DISTINCT FROM OLD.purged_at THEN
    RAISE EXCEPTION 'data_job.ended: a purge is not taken back' USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.status IN ('done', 'failed', 'cancelled', 'expired') AND NEW.finished_at IS NULL THEN
    NEW.finished_at := now();
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: deal_links_quote_sent(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.deal_links_quote_sent() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM commerce.draft_orders o WHERE o.store_id = NEW.store_id AND o.id = NEW.draft_id AND o.sent_at IS NOT NULL) THEN
    PERFORM commerce.deal_quote_sent(NEW.store_id, NEW.draft_id);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: deal_links_win(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.deal_links_win() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF (NEW.kind = 'order' AND EXISTS (
        SELECT 1 FROM commerce.orders o
         WHERE o.store_id = NEW.store_id AND o.id = NEW.order_id AND o.copied_from IS NULL AND o.status IN ('paid', 'fulfilled', 'closed')))
     OR (NEW.kind = 'draft' AND EXISTS (
        SELECT 1 FROM commerce.orders o
         WHERE o.store_id = NEW.store_id AND o.draft_id = NEW.draft_id AND o.copied_from IS NULL AND o.status IN ('paid', 'fulfilled', 'closed'))) THEN
    PERFORM commerce.deal_win(NEW.store_id, ARRAY[NEW.deal_id], 'order');
  ELSIF NEW.kind = 'work_assignment' AND EXISTS (
        SELECT 1 FROM commerce.work_invoices w
         WHERE w.store_id = NEW.store_id AND w.assignment_id = NEW.assignment_id AND w.status <> 'draft' AND NOT w.imported) THEN
    PERFORM commerce.deal_win(NEW.store_id, ARRAY[NEW.deal_id], 'work_invoice');
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: deal_quote_sent(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.deal_quote_sent(p_store uuid, p_draft uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  d record;
  v_moved integer := 0;
BEGIN
  FOR d IN
    SELECT dd.id AS deal_id, q.id AS quote_stage
      FROM commerce.deal_links dl
      JOIN commerce.deals dd ON dd.store_id = dl.store_id AND dd.id = dl.deal_id
      JOIN commerce.deal_stages q ON q.store_id = dd.store_id AND q.pipeline_id = dd.pipeline_id AND q.quote_stage
      JOIN commerce.deal_stages cur ON cur.store_id = dd.store_id AND cur.id = dd.stage_id
     WHERE dl.store_id = p_store AND dl.kind = 'draft' AND dl.draft_id = p_draft AND dd.status = 'open' AND cur.position < q.position
  LOOP
    PERFORM set_config('commerce.deal_move_via', 'quote', true);
    UPDATE commerce.deals SET stage_id = d.quote_stage, updated_by = NULL, updated_at = now() WHERE store_id = p_store AND id = d.deal_id;
    PERFORM set_config('commerce.deal_move_via', '', true);
    v_moved := v_moved + 1;
  END LOOP;
  RETURN v_moved;
END;
$$;


--
-- Name: deal_win(uuid, uuid[], text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.deal_win(p_store uuid, p_deals uuid[], p_via text) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  n integer;
BEGIN
  IF p_deals IS NULL OR cardinality(p_deals) = 0 THEN
    RETURN 0;
  END IF;
  UPDATE commerce.deals
     SET status = 'won', closed_at = now(), closed_via = p_via, close_reason = NULL, updated_by = NULL, updated_at = now()
   WHERE store_id = p_store AND id = ANY (p_deals) AND status = 'open';
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END;
$$;


--
-- Name: deals_history(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.deals_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' OR NEW.stage_id IS DISTINCT FROM OLD.stage_id OR NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO commerce.deal_moves (store_id, deal_id, stage_id, status, via, moved_by)
    VALUES (NEW.store_id, NEW.id, NEW.stage_id, NEW.status,
      coalesce(NEW.closed_via, nullif(current_setting('commerce.deal_move_via', true), '')), NEW.updated_by);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: deals_stage_clock(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.deals_stage_clock() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.stage_id IS DISTINCT FROM OLD.stage_id THEN
    NEW.stage_entered_at := now();
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: delete_copied_order(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.delete_copied_order(p_store uuid, p_order uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM commerce.orders WHERE store_id = p_store AND id = p_order AND copied_from IS NOT NULL) THEN
    RETURN false;
  END IF;
  PERFORM set_config('kaizen.copied_order_delete', p_order::text, true);
  -- A copied order holds its lines, its tags and its history; anything else made for it since (a review request, say) keeps it.
  -- The lines of a copied order are read-only but to the writer that copies (`commerce.copying`): this one, for its own order alone.
  PERFORM set_config('commerce.copying', 'on', true);
  DELETE FROM commerce.order_lines WHERE order_id = p_order;
  PERFORM set_config('commerce.copying', '', true);
  DELETE FROM commerce.order_tags WHERE order_id = p_order;
  DELETE FROM commerce.order_events WHERE order_id = p_order;
  DELETE FROM commerce.orders WHERE store_id = p_store AND id = p_order AND copied_from IS NOT NULL;
  PERFORM set_config('kaizen.copied_order_delete', '', true);
  RETURN true;
END;
$$;


--
-- Name: design_preset_uses_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.design_preset_uses_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'design_preset_uses.kept: a use of a design profile is history, never deleted' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.store_id IS DISTINCT FROM OLD.store_id OR NEW.preset_id IS DISTINCT FROM OLD.preset_id
     OR NEW.previous IS DISTINCT FROM OLD.previous OR NEW.applied_by IS DISTINCT FROM OLD.applied_by
     OR NEW.applied_at IS DISTINCT FROM OLD.applied_at
     OR (NEW.saved_theme_id IS DISTINCT FROM OLD.saved_theme_id AND NEW.saved_theme_id IS NOT NULL)
     OR (NEW.install_id IS DISTINCT FROM OLD.install_id AND NEW.install_id IS NOT NULL)
     OR (NEW.previous_install_id IS DISTINCT FROM OLD.previous_install_id AND NEW.previous_install_id IS NOT NULL) THEN
    RAISE EXCEPTION 'design_preset_uses.fixed: a use of a design profile is not changed' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.restored_at IS NOT NULL
     AND (NEW.restored_at IS DISTINCT FROM OLD.restored_at OR NEW.restored_by IS DISTINCT FROM OLD.restored_by) THEN
    RAISE EXCEPTION 'design_preset_uses.restored: the look from before was put back already' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.restored_at IS NULL AND NEW.restored_at IS NULL AND NEW.restored_by IS DISTINCT FROM OLD.restored_by THEN
    RAISE EXCEPTION 'design_preset_uses.fixed: a use of a design profile is not changed' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: design_preset_versions_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.design_preset_versions_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    -- Only with its theme (the foreign key's cascade runs after the theme's row is gone).
    IF EXISTS (SELECT 1 FROM commerce.design_presets d WHERE d.id = OLD.preset_id) THEN
      RAISE EXCEPTION 'design_preset_versions.kept: a published version of a theme is never deleted' USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.preset_id IS DISTINCT FROM OLD.preset_id OR NEW.number IS DISTINCT FROM OLD.number
     OR NEW.snapshot IS DISTINCT FROM OLD.snapshot OR NEW.published_at IS DISTINCT FROM OLD.published_at OR NEW.notes IS DISTINCT FROM OLD.notes
     OR (NEW.published_by IS DISTINCT FROM OLD.published_by AND NEW.published_by IS NOT NULL) THEN
    RAISE EXCEPTION 'design_preset_versions.fixed: a published version of a theme is not changed' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: design_presets_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.design_presets_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF EXISTS (SELECT 1 FROM commerce.design_preset_uses u WHERE u.preset_id = OLD.id) THEN
      RAISE EXCEPTION 'design_presets.used: a store applied this design profile; archive it instead' USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (SELECT 1 FROM commerce.access_requests r WHERE r.design_preset_id = OLD.id) THEN
      RAISE EXCEPTION 'design_presets.requested: an access request chose this design profile; archive it instead' USING ERRCODE = 'check_violation';
    END IF;
    UPDATE commerce.store_starters SET recommended_design = NULL WHERE recommended_design = OLD.id;
    UPDATE commerce.store_starters SET draft = jsonb_set(draft, '{recommendedDesign}', 'null'::jsonb)
     WHERE draft ->> 'recommendedDesign' = OLD.id::text;
    RETURN OLD;
  END IF;
  IF NEW.workspace_store_id IS NOT NULL
     AND (TG_OP = 'INSERT' OR NEW.workspace_store_id IS DISTINCT FROM OLD.workspace_store_id) THEN
    IF TG_OP = 'UPDATE' AND OLD.workspace_store_id IS NOT NULL THEN
      RAISE EXCEPTION 'design_presets.workspace_fixed: a design profile keeps its workspace' USING ERRCODE = 'check_violation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM commerce.stores s WHERE s.id = NEW.workspace_store_id AND s.starter AND s.starter_copy_of IS NULL)
       OR EXISTS (SELECT 1 FROM commerce.store_starters st WHERE st.store_id = NEW.workspace_store_id) THEN
      RAISE EXCEPTION 'design_presets.not_workspace: a design profile''s workspace is a hidden store of its own' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NEW.workspace_store_id IS NULL AND OLD.workspace_store_id IS NOT NULL THEN
      RAISE EXCEPTION 'design_presets.workspace_fixed: a design profile keeps its workspace' USING ERRCODE = 'check_violation';
    END IF;
    NEW.updated_at := now();
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: design_variations_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.design_variations_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.preset_id IS DISTINCT FROM OLD.preset_id OR NEW.key IS DISTINCT FROM OLD.key
       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
      RAISE EXCEPTION 'design_variations.fixed: a preset keeps its theme and its key' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  PERFORM 1 FROM commerce.design_presets WHERE id = NEW.preset_id FOR UPDATE;
  IF (SELECT count(*) FROM commerce.design_variations WHERE preset_id = NEW.preset_id) >= 5 THEN
    RAISE EXCEPTION 'design_variations.limit: a theme has at most six presets, its own look and five more' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: discount_code_items_fixed(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.discount_code_items_fixed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.discount_id <> OLD.discount_id OR NEW.code <> OLD.code OR NEW.store_id <> OLD.store_id THEN
    RAISE EXCEPTION 'discount_code_items.fixed: a generated code stays itself' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: discount_code_text_unique(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.discount_code_text_unique() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_TABLE_NAME = 'discount_code_items' THEN
    IF EXISTS (SELECT 1 FROM commerce.discount_codes d WHERE d.store_id = NEW.store_id AND d.code = NEW.code) THEN
      RAISE EXCEPTION 'discount_code_items.code: the store has a code %', NEW.code USING ERRCODE = 'unique_violation';
    END IF;
  ELSIF EXISTS (SELECT 1 FROM commerce.discount_code_items i WHERE i.store_id = NEW.store_id AND i.code = NEW.code) THEN
    RAISE EXCEPTION 'discount_codes.code: the store has a generated code %', NEW.code USING ERRCODE = 'unique_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: dispute_evidence_forget(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.dispute_evidence_forget() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  UPDATE commerce.dispute_evidence e SET fields = '{}'::jsonb, updated_at = now()
    FROM commerce.payment_disputes d
   WHERE d.store_id = NEW.store_id AND d.order_id = NEW.id AND e.store_id = d.store_id AND e.dispute_id = d.id AND e.fields <> '{}'::jsonb;
  RETURN NEW;
END $$;


--
-- Name: dispute_evidence_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.dispute_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF OLD.submitted_at IS NOT NULL AND NEW.fields IS DISTINCT FROM OLD.fields AND NEW.fields <> '{}'::jsonb THEN
    RAISE EXCEPTION 'dispute_evidence.sent: evidence sent to Stripe is kept as it was sent' USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW.dispute_id IS DISTINCT FROM OLD.dispute_id OR NEW.store_id IS DISTINCT FROM OLD.store_id THEN
    RAISE EXCEPTION 'dispute_evidence.fixed: evidence stays with its dispute' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: distribute_minor(bigint, bigint[], numeric[]); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.distribute_minor(p_total bigint, p_weights bigint[], p_rates numeric[] DEFAULT NULL::numeric[]) RETURNS bigint[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_sum numeric;
  v_out bigint[];
BEGIN
  IF p_total < 0 THEN RAISE EXCEPTION 'distribute_minor: total must be 0 or more'; END IF;
  IF p_weights IS NULL OR coalesce(array_length(p_weights, 1), 0) = 0 THEN RETURN ARRAY[]::bigint[]; END IF;
  IF p_total = 0 THEN
    SELECT array_agg(0::bigint) INTO v_out FROM generate_subscripts(p_weights, 1);
    RETURN v_out;
  END IF;
  SELECT sum(w)::numeric INTO v_sum FROM unnest(p_weights) AS t(w);
  IF v_sum = 0 THEN RAISE EXCEPTION 'distribute_minor: nothing to share the amount over'; END IF;
  WITH w AS (
    SELECT i AS idx, p_weights[i]::numeric AS wt, coalesce(p_rates[i], 0) AS rate FROM generate_subscripts(p_weights, 1) AS i
  ), b AS (
    SELECT idx, rate, div(p_total::numeric * wt, v_sum) AS base, mod(p_total::numeric * wt, v_sum) AS frac FROM w
  ), r AS (
    SELECT idx, base, row_number() OVER (ORDER BY frac DESC, rate DESC, idx ASC) AS rk, p_total - sum(base) OVER () AS left_over FROM b
  )
  SELECT array_agg((base + CASE WHEN rk <= left_over THEN 1 ELSE 0 END)::bigint ORDER BY idx) INTO v_out FROM r;
  RETURN v_out;
END;
$$;


--
-- Name: dns_changes_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.dns_changes_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'dns_changes.kept: a DNS change is never deleted' USING ERRCODE = 'check_violation';
  END IF;
  IF (to_jsonb(NEW) - 'undone_at') IS DISTINCT FROM (to_jsonb(OLD) - 'undone_at') THEN
    RAISE EXCEPTION 'dns_changes.fixed: a DNS change is kept as it was made' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.undone_at IS NOT NULL AND NEW.undone_at IS DISTINCT FROM OLD.undone_at THEN
    RAISE EXCEPTION 'dns_changes.undone: a DNS change is undone once' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: dns_zones_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.dns_zones_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'dns_zones.kept: a DNS zone is never deleted (it is left)' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.apex IS DISTINCT FROM OLD.apex OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'dns_zones.fixed: a DNS zone keeps its name' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.status = 'left' AND NEW.status IS DISTINCT FROM OLD.status THEN
    RAISE EXCEPTION 'dns_zones.left: a zone that was left stays left' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: doc_language(text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.doc_language(p_locale text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT CASE WHEN left(lower(coalesce(p_locale, '')), 2) IN ('nb', 'nn', 'no') THEN 'nb'
              WHEN left(lower(coalesce(p_locale, '')), 2) = 'sv' THEN 'sv'
              WHEN left(lower(coalesce(p_locale, '')), 2) = 'da' THEN 'da'
              ELSE 'en' END
$$;


--
-- Name: document_audit(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.document_audit(p_store uuid) RETURNS TABLE(series text, documents bigint, first_number bigint, last_number bigint, missing bigint, first_missing bigint, off_format bigint, next_number bigint, ok boolean)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  WITH s AS (
    SELECT ds.series, ds.prefix, ds.next_number FROM commerce.document_series ds WHERE ds.store_id = p_store AND ds.series IN ('invoice', 'credit_note')
  ), d AS (
    SELECT 'invoice'::text AS series, i.number, i.document_number FROM commerce.invoices i WHERE i.store_id = p_store
    UNION ALL
    SELECT 'credit_note', c.number, c.document_number FROM commerce.credit_notes c WHERE c.store_id = p_store
  ), ends AS (
    SELECT d.series, min(d.number) AS lo, max(d.number) AS hi, count(*) AS c, count(DISTINCT d.number) AS cd FROM d GROUP BY d.series
  ), steps AS (
    SELECT x.series, x.number, lag(x.number) OVER (PARTITION BY x.series ORDER BY x.number) AS before
      FROM (SELECT DISTINCT d.series, d.number FROM d) x
  )
  SELECT s.series, coalesce(e.c, 0)::bigint, e.lo, e.hi,
         coalesce(e.hi - e.lo + 1 - e.cd, 0)::bigint,
         (SELECT min(st.before + 1) FROM steps st WHERE st.series = s.series AND st.before IS NOT NULL AND st.number > st.before + 1),
         (SELECT count(*) FROM d WHERE d.series = s.series AND d.document_number <> s.prefix || d.number::text),
         s.next_number,
         coalesce(e.hi - e.lo + 1 = e.cd, true) AND (e.hi IS NULL OR s.next_number = e.hi + 1)
    FROM s LEFT JOIN ends e ON e.series = s.series
   ORDER BY s.series
$$;


--
-- Name: document_insert_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.document_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_by text := current_setting('commerce.issuing_document', true);
  v_order uuid;
  v_order_row commerce.orders%ROWTYPE;
  v_edit commerce.order_edits%ROWTYPE;
  v_sum record;
  v_prefix text;
  v_over integer;
  v_expect bigint;
BEGIN
  SELECT s.prefix INTO v_prefix FROM commerce.document_series s WHERE s.store_id = NEW.store_id AND s.series = NEW.series;
  IF NEW.document_number IS DISTINCT FROM v_prefix || NEW.number::text THEN
    RAISE EXCEPTION 'document.number_format: % is not the series prefix and number', NEW.document_number USING ERRCODE = 'check_violation';
  END IF;

  SELECT coalesce(sum((b ->> 'netMinor')::bigint), 0) AS net, coalesce(sum((b ->> 'vatMinor')::bigint), 0) AS vat,
         coalesce(sum((b ->> 'grossMinor')::bigint), 0) AS gross
    INTO v_sum FROM jsonb_array_elements(NEW.snapshot -> 'buckets') AS b;
  IF v_sum.net <> NEW.net_minor OR v_sum.vat <> NEW.tax_minor OR v_sum.gross <> NEW.total_minor THEN
    RAISE EXCEPTION 'document.totals_mismatch: the totals are not the snapshot''s buckets' USING ERRCODE = 'check_violation';
  END IF;

  IF TG_TABLE_NAME = 'invoices' THEN
    IF NEW.kind = 'order_edit' THEN
      IF v_by IS DISTINCT FROM NEW.order_edit_id::text THEN
        RAISE EXCEPTION 'document.issuing_only: an additional invoice is made by commerce.issue_edit_documents()' USING ERRCODE = 'restrict_violation';
      END IF;
      SELECT * INTO v_edit FROM commerce.order_edits e WHERE e.store_id = NEW.store_id AND e.id = NEW.order_edit_id;
      IF NOT FOUND OR v_edit.order_id <> NEW.order_id OR v_edit.status <> 'applied' THEN
        RAISE EXCEPTION 'invoice.edit: an additional invoice is for an applied change of its own order' USING ERRCODE = 'check_violation';
      END IF;
      IF NOT EXISTS (SELECT 1 FROM commerce.invoices i WHERE i.store_id = NEW.store_id AND i.order_id = NEW.order_id AND i.kind = 'order') THEN
        RAISE EXCEPTION 'invoice.edit_original: an additional invoice refers to the order''s own invoice, which is not issued yet' USING ERRCODE = 'check_violation';
      END IF;
    ELSIF v_by IS DISTINCT FROM NEW.order_id::text THEN
      RAISE EXCEPTION 'document.issuing_only: an invoice is made by commerce.issue_order_invoice()' USING ERRCODE = 'restrict_violation';
    END IF;
    SELECT * INTO v_order_row FROM commerce.orders o WHERE o.store_id = NEW.store_id AND o.id = NEW.order_id;
    IF NOT FOUND OR v_order_row.copied_from IS NOT NULL OR v_order_row.host_id IS NOT NULL THEN
      RAISE EXCEPTION 'document.order: a copied or host order, or one that does not exist, is not invoiced' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.kind = 'order_edit' THEN
      SELECT coalesce(sum(ol.total_minor), 0) + greatest(0, v_edit.shipping_after - v_edit.shipping_before) INTO v_expect
        FROM commerce.order_lines ol WHERE ol.store_id = NEW.store_id AND ol.order_id = NEW.order_id AND ol.order_edit_id = NEW.order_edit_id;
      IF NEW.total_minor <> v_expect OR NEW.currency <> v_order_row.currency THEN
        RAISE EXCEPTION 'invoice.total_not_edit: the additional invoice is not for what the change added' USING ERRCODE = 'check_violation';
      END IF;
    ELSIF NEW.total_minor <> v_order_row.total_minor OR NEW.currency <> v_order_row.currency THEN
      RAISE EXCEPTION 'invoice.total_not_order: the invoice is not for the order''s total' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  -- Credit notes.
  SELECT i.order_id INTO v_order FROM commerce.invoices i WHERE i.store_id = NEW.store_id AND i.id = NEW.invoice_id;
  IF NEW.source = 'order_edit' THEN
    IF v_by IS DISTINCT FROM NEW.order_edit_id::text THEN
      RAISE EXCEPTION 'document.issuing_only: a change''s credit note is made by commerce.issue_edit_documents()' USING ERRCODE = 'restrict_violation';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM commerce.order_edits e JOIN commerce.invoices i ON i.store_id = e.store_id AND i.order_id = e.order_id AND i.kind = 'order'
       WHERE e.store_id = NEW.store_id AND e.id = NEW.order_edit_id AND e.status = 'applied' AND i.id = NEW.invoice_id
    ) THEN
      RAISE EXCEPTION 'credit_note.edit: a change''s credit note is for an applied change and refers to its order''s own invoice' USING ERRCODE = 'check_violation';
    END IF;
  ELSIF v_by IS DISTINCT FROM coalesce(NEW.refund_id, NEW.return_id)::text THEN
    RAISE EXCEPTION 'document.issuing_only: a credit note is made by commerce.issue_credit_note()' USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW.refund_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM commerce.refunds r JOIN commerce.payments p ON p.store_id = r.store_id AND p.id = r.payment_id
     WHERE r.store_id = NEW.store_id AND r.id = NEW.refund_id AND p.order_id = v_order AND r.status = 'succeeded'
  ) THEN
    RAISE EXCEPTION 'credit_note.refund: the refund is not a succeeded refund of the invoice''s order' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.return_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM commerce.returns r WHERE r.store_id = NEW.store_id AND r.id = NEW.return_id AND r.order_id = v_order
       AND ((NEW.source <> 'return_exchange' AND r.refund_outside) OR (NEW.source = 'return_exchange' AND r.outcome = 'exchanged'))
  ) THEN
    RAISE EXCEPTION 'credit_note.return: the return is not one refunded outside for the invoice''s order' USING ERRCODE = 'check_violation';
  END IF;
  -- Never above the order's invoices together, per rate bucket: net, VAT and gross, with what its earlier credit notes took.
  WITH pool AS (
    SELECT * FROM commerce.order_buckets_left(NEW.store_id, v_order)
  ), mine AS (
    SELECT (b ->> 'rate')::numeric AS rate, b ->> 'basis' AS basis, (b ->> 'netMinor')::bigint AS net, (b ->> 'vatMinor')::bigint AS vat, (b ->> 'grossMinor')::bigint AS gross
      FROM jsonb_array_elements(NEW.snapshot -> 'buckets') AS b
  )
  SELECT count(*) INTO v_over
    FROM mine m
    LEFT JOIN pool p ON p.rate = m.rate AND p.basis = m.basis
   WHERE p.rate IS NULL
      OR m.net < 0 OR m.vat < 0 OR m.gross <= 0
      OR m.net > p.net_left
      OR m.vat > p.vat_left
      OR m.gross > p.gross_left;
  IF v_over > 0 THEN
    RAISE EXCEPTION 'credit_note.over_invoice: a credit note cannot credit more than the order''s invoices left uncredited' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: documents_po_number(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.documents_po_number() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_po text;
BEGIN
  IF TG_TABLE_NAME = 'invoices' THEN
    IF NEW.kind <> 'order' THEN
      RETURN NEW;
    END IF;
    SELECT o.po_number INTO v_po FROM commerce.orders o WHERE o.store_id = NEW.store_id AND o.id = NEW.order_id;
  ELSE
    SELECT i.snapshot ->> 'poNumber' INTO v_po FROM commerce.invoices i WHERE i.store_id = NEW.store_id AND i.id = NEW.invoice_id;
  END IF;
  IF v_po IS NOT NULL THEN
    NEW.snapshot := NEW.snapshot || jsonb_build_object('poNumber', v_po);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: domain_purchases_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.domain_purchases_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'domain_purchases.kept: a domain purchase is never deleted' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.store_id IS DISTINCT FROM OLD.store_id OR NEW.apex IS DISTINCT FROM OLD.apex
     OR NEW.kind IS DISTINCT FROM OLD.kind OR NEW.years IS DISTINCT FROM OLD.years OR NEW.currency IS DISTINCT FROM OLD.currency
     OR NEW.amount_minor IS DISTINCT FROM OLD.amount_minor OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'domain_purchases.fixed: a domain purchase keeps its store, name, kind and price' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
       (OLD.status = 'quoted' AND NEW.status IN ('invoiced', 'void', 'failed'))
    OR (OLD.status = 'invoiced' AND NEW.status IN ('paid', 'void'))
    OR (OLD.status = 'paid' AND NEW.status IN ('registering', 'done', 'failed'))
    OR (OLD.status = 'registering' AND NEW.status IN ('done', 'failed'))
    OR (OLD.status = 'failed' AND NEW.status = 'refunded')
  ) THEN
    RAISE EXCEPTION 'domain_purchases.forward: a domain purchase cannot go from % to %', OLD.status, NEW.status USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.stripe_invoice_id IS NOT NULL AND NEW.stripe_invoice_id IS DISTINCT FROM OLD.stripe_invoice_id THEN
    RAISE EXCEPTION 'domain_purchases.invoice: a domain purchase keeps its invoice' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.registrar_order_id IS NOT NULL AND NEW.registrar_order_id IS DISTINCT FROM OLD.registrar_order_id THEN
    RAISE EXCEPTION 'domain_purchases.order: a domain purchase keeps its registrar order' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: domain_registrations_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.domain_registrations_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'domain_registrations.kept: a registration is never deleted' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.apex IS DISTINCT FROM OLD.apex OR NEW.registrar IS DISTINCT FROM OLD.registrar
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'domain_registrations.fixed: a registration keeps its name and registrar' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.status = 'transferred_out' AND NEW.status IS DISTINCT FROM OLD.status THEN
    RAISE EXCEPTION 'domain_registrations.ended: a domain moved to another registrar stays moved' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: draft_order_lines_limit(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.draft_order_lines_limit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('draft_lines:' || NEW.draft_id::text, 0));
  IF (SELECT count(*) FROM commerce.draft_order_lines l WHERE l.draft_id = NEW.draft_id) >= 100 THEN
    RAISE EXCEPTION 'draft_order.lines: a draft has at most 100 lines' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: draft_order_lines_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.draft_order_lines_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_status text;
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    SELECT d.status INTO v_status FROM commerce.draft_orders d WHERE d.store_id = OLD.store_id AND d.id = OLD.draft_id;
    IF FOUND AND v_status <> 'open' THEN
      RAISE EXCEPTION 'draft_order.frozen: the lines of a draft that is not open cannot be changed: reopen it first' USING ERRCODE = 'restrict_violation';
    END IF;
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    SELECT d.status INTO v_status FROM commerce.draft_orders d WHERE d.store_id = NEW.store_id AND d.id = NEW.draft_id;
    IF FOUND AND v_status <> 'open' THEN
      RAISE EXCEPTION 'draft_order.frozen: the lines of a draft that is not open cannot be changed: reopen it first' USING ERRCODE = 'restrict_violation';
    END IF;
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: draft_orders_quote_sent(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.draft_orders_quote_sent() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM commerce.deal_quote_sent(NEW.store_id, NEW.id);
  RETURN NULL;
END;
$$;


--
-- Name: draft_orders_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.draft_orders_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'open' THEN
      RAISE EXCEPTION 'draft_order.start: a draft is made open' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    IF OLD.status = 'sent' THEN
      RAISE EXCEPTION 'draft_order.delete: draft % is sent and its order waits for payment: reopen it first', OLD.number USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN OLD;
  END IF;

  IF (to_jsonb(NEW) - ARRAY['updated_at']) = (to_jsonb(OLD) - ARRAY['updated_at']) THEN
    RETURN NEW;
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.store_id IS DISTINCT FROM OLD.store_id OR NEW.number IS DISTINCT FROM OLD.number
     OR NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.created_by IS DISTINCT FROM OLD.created_by THEN
    RAISE EXCEPTION 'draft_order.fixed: a draft keeps its number, store and maker' USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW.version < OLD.version THEN
    RAISE EXCEPTION 'draft_order.version: the version of a draft only goes up' USING ERRCODE = 'restrict_violation';
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NOT (
         (OLD.status = 'open' AND NEW.status = 'sent')
      OR (OLD.status = 'sent' AND NEW.status IN ('paid', 'expired', 'cancelled', 'open'))
      OR (OLD.status IN ('expired', 'cancelled') AND NEW.status IN ('open', 'paid'))
    ) THEN
      RAISE EXCEPTION 'draft_order.move: a draft cannot go from % to %', OLD.status, NEW.status USING ERRCODE = 'check_violation';
    END IF;
    -- Ending a send, or paying late, leaves the order, the times and the link as they were.
    IF NEW.status IN ('paid', 'expired', 'cancelled')
       AND (NEW.order_id IS DISTINCT FROM OLD.order_id OR NEW.sent_at IS DISTINCT FROM OLD.sent_at
            OR NEW.expires_at IS DISTINCT FROM OLD.expires_at OR NEW.pay_token_hash IS DISTINCT FROM OLD.pay_token_hash) THEN
      RAISE EXCEPTION 'draft_order.fixed: the order, the times and the link of a draft are not changed when it ends' USING ERRCODE = 'restrict_violation';
    END IF;
  ELSE
    IF NEW.order_id IS DISTINCT FROM OLD.order_id OR NEW.sent_at IS DISTINCT FROM OLD.sent_at THEN
      RAISE EXCEPTION 'draft_order.fixed: the order and the time a draft was sent are written by sending it' USING ERRCODE = 'restrict_violation';
    END IF;
    IF OLD.status <> 'sent' AND (NEW.expires_at IS DISTINCT FROM OLD.expires_at OR NEW.pay_token_hash IS DISTINCT FROM OLD.pay_token_hash) THEN
      RAISE EXCEPTION 'draft_order.fixed: the expiry and the link of a draft change only while it is sent' USING ERRCODE = 'restrict_violation';
    END IF;
  END IF;

  IF OLD.status <> 'open' THEN
    IF NEW.customer_id IS DISTINCT FROM OLD.customer_id AND NEW.customer_id IS NOT NULL THEN
      RAISE EXCEPTION 'draft_order.frozen: a draft that is not open keeps its customer' USING ERRCODE = 'restrict_violation';
    END IF;
    IF (to_jsonb(NEW) - ARRAY['status', 'version', 'internal_note', 'order_id', 'sent_at', 'expires_at', 'paid_at', 'pay_token_hash',
                              'pay_sends_today', 'pay_sent_on', 'updated_at', 'edited_at', 'customer_id'])
       IS DISTINCT FROM
       (to_jsonb(OLD) - ARRAY['status', 'version', 'internal_note', 'order_id', 'sent_at', 'expires_at', 'paid_at', 'pay_token_hash',
                              'pay_sends_today', 'pay_sent_on', 'updated_at', 'edited_at', 'customer_id']) THEN
      RAISE EXCEPTION 'draft_order.frozen: a draft that is not open cannot be changed: reopen it first' USING ERRCODE = 'restrict_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: draw_edit_stock(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.draw_edit_stock(p_edit uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  e commerce.order_edits%ROWTYPE;
  v_var record;
  v_hold record;
  v_level record;
  v_line record;
  v_prev_stock text;
  v_prev_drawing text;
  v_left integer;
  v_take integer;
  v_before integer;
  v_claimed integer;
  v_back integer;
  v_alloc integer;
  v_home uuid;
  v_short integer := 0;
BEGIN
  SELECT * INTO e FROM commerce.order_edits WHERE id = p_edit;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown order change %', p_edit; END IF;

  v_prev_stock := current_setting('kaizen.stock', true);
  v_prev_drawing := current_setting('kaizen.drawing', true);
  PERFORM commerce.stock_context('sale', 'order_edit', e.made_by, e.order_id, NULL, NULL, NULL);
  PERFORM set_config('kaizen.drawing', 'on', true);

  FOR v_var IN
    SELECT ol.variant_id, sum(ol.quantity)::integer AS quantity, v.stock_policy, v.backorder_days
      FROM commerce.order_lines ol
      JOIN commerce.product_variants v ON v.store_id = ol.store_id AND v.id = ol.variant_id
     WHERE ol.store_id = e.store_id AND ol.order_id = e.order_id AND ol.order_edit_id = p_edit AND ol.variant_id IS NOT NULL AND ol.delivery = 'physical'
     GROUP BY ol.variant_id, v.stock_policy, v.backorder_days
     ORDER BY ol.variant_id
  LOOP
    PERFORM 1 FROM commerce.inventory_levels l
     WHERE l.store_id = e.store_id AND l.variant_id = v_var.variant_id
     ORDER BY l.location_id FOR UPDATE;
    v_left := v_var.quantity;
    v_back := 0;

    -- (1) The change's own holds.
    FOR v_hold IN
      SELECT loc.id AS location_id, sum(r.quantity)::integer AS quantity
        FROM commerce.inventory_reservations r
        JOIN commerce.inventory_locations loc ON loc.store_id = r.store_id AND loc.id = r.location_id
       WHERE r.store_id = e.store_id AND r.order_edit_id = p_edit AND r.variant_id = v_var.variant_id AND r.released_at IS NULL
       GROUP BY loc.id, loc.priority, loc.created_at
       ORDER BY loc.priority, loc.created_at, loc.id
    LOOP
      EXIT WHEN v_left = 0;
      SELECT l.on_hand INTO v_before FROM commerce.inventory_levels l
       WHERE l.store_id = e.store_id AND l.variant_id = v_var.variant_id AND l.location_id = v_hold.location_id;
      CONTINUE WHEN NOT FOUND;
      v_take := least(v_hold.quantity, v_left);
      IF v_var.stock_policy <> 'continue' THEN
        v_take := least(v_take, greatest(v_before, 0));
      END IF;
      IF v_take > 0 THEN
        UPDATE commerce.inventory_levels SET on_hand = on_hand - v_take, updated_at = now()
         WHERE store_id = e.store_id AND variant_id = v_var.variant_id AND location_id = v_hold.location_id;
        -- A unit beyond what the shelf held is a unit on backorder.
        v_back := v_back + greatest(0, v_take - greatest(v_before, 0));
        v_left := v_left - v_take;
      END IF;
    END LOOP;

    -- (2) Stock no other live hold claims, in rank order.
    FOR v_level IN
      SELECT l.location_id, l.on_hand
        FROM commerce.inventory_levels l
        JOIN commerce.inventory_locations loc ON loc.store_id = l.store_id AND loc.id = l.location_id AND loc.active
       WHERE l.store_id = e.store_id AND l.variant_id = v_var.variant_id AND l.on_hand > 0
       ORDER BY loc.priority, loc.created_at, loc.id
    LOOP
      EXIT WHEN v_left = 0;
      SELECT coalesce(sum(r.quantity), 0)::integer INTO v_claimed
        FROM commerce.inventory_reservations r
       WHERE r.store_id = e.store_id AND r.variant_id = v_var.variant_id AND r.location_id = v_level.location_id
         AND r.order_edit_id IS DISTINCT FROM p_edit AND r.released_at IS NULL AND r.expires_at > now();
      v_take := least(greatest(v_level.on_hand - v_claimed, 0), v_left);
      CONTINUE WHEN v_take = 0;
      UPDATE commerce.inventory_levels SET on_hand = on_hand - v_take, updated_at = now()
       WHERE store_id = e.store_id AND variant_id = v_var.variant_id AND location_id = v_level.location_id;
      v_left := v_left - v_take;
    END LOOP;

    -- (3) The remainder: backordered at the first location that stocks the variant, or short.
    IF v_left > 0 THEN
      IF v_var.stock_policy = 'continue' THEN
        SELECT loc.id INTO v_home
          FROM commerce.inventory_locations loc
          JOIN commerce.inventory_levels l ON l.store_id = loc.store_id AND l.location_id = loc.id AND l.variant_id = v_var.variant_id
         WHERE loc.store_id = e.store_id AND loc.active
         ORDER BY loc.priority, loc.created_at, loc.id LIMIT 1;
        IF v_home IS NULL THEN
          SELECT loc.id INTO v_home FROM commerce.inventory_locations loc
           WHERE loc.store_id = e.store_id AND loc.active
           ORDER BY loc.priority, loc.created_at, loc.id LIMIT 1;
          IF v_home IS NOT NULL THEN
            INSERT INTO commerce.inventory_levels (store_id, variant_id, location_id, on_hand)
            VALUES (e.store_id, v_var.variant_id, v_home, 0)
            ON CONFLICT (variant_id, location_id) DO NOTHING;
          END IF;
        END IF;
        IF v_home IS NULL THEN
          v_short := v_short + v_left;
        ELSE
          PERFORM 1 FROM commerce.inventory_levels l
           WHERE l.store_id = e.store_id AND l.variant_id = v_var.variant_id AND l.location_id = v_home FOR UPDATE;
          UPDATE commerce.inventory_levels SET on_hand = on_hand - v_left, updated_at = now()
           WHERE store_id = e.store_id AND variant_id = v_var.variant_id AND location_id = v_home;
          v_back := v_back + v_left;
        END IF;
      ELSE
        v_short := v_short + v_left;
      END IF;
    END IF;

    -- The backordered units go to the change's added lines of the variant, in id order (each line no more than its units).
    FOR v_line IN
      SELECT ol.id, ol.quantity FROM commerce.order_lines ol
       WHERE ol.store_id = e.store_id AND ol.order_id = e.order_id AND ol.order_edit_id = p_edit AND ol.variant_id = v_var.variant_id AND ol.delivery = 'physical'
       ORDER BY ol.id
    LOOP
      v_alloc := least(v_line.quantity, v_back);
      UPDATE commerce.order_lines
         SET backorder_quantity = v_alloc, backorder_days = CASE WHEN v_alloc > 0 THEN coalesce(backorder_days, v_var.backorder_days) ELSE backorder_days END
       WHERE id = v_line.id AND (backorder_quantity <> v_alloc OR (v_alloc > 0 AND backorder_days IS NULL));
      v_back := v_back - v_alloc;
    END LOOP;
  END LOOP;

  UPDATE commerce.inventory_reservations SET released_at = now()
   WHERE store_id = e.store_id AND order_edit_id = p_edit AND released_at IS NULL;

  PERFORM set_config('kaizen.stock', coalesce(v_prev_stock, ''), true);
  PERFORM set_config('kaizen.drawing', coalesce(v_prev_drawing, ''), true);
  RETURN v_short;
END;
$$;


--
-- Name: draw_order_stock(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.draw_order_stock(p_order_id uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_order commerce.orders%ROWTYPE;
  v_var record;
  v_hold record;
  v_level record;
  v_line record;
  v_prev_stock text;
  v_prev_drawing text;
  v_left integer;
  v_take integer;
  v_phys integer;
  v_before integer;
  v_claimed integer;
  v_extra integer;
  v_back integer;
  v_alloc integer;
  v_home uuid;
  v_short integer := 0;
  v_lines jsonb := '[]'::jsonb;
BEGIN
  SELECT * INTO v_order FROM commerce.orders WHERE id = p_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown order %', p_order_id;
  END IF;

  v_prev_stock := current_setting('kaizen.stock', true);
  v_prev_drawing := current_setting('kaizen.drawing', true);
  PERFORM commerce.stock_context('sale', 'order', NULL, p_order_id, NULL, NULL, NULL);
  PERFORM set_config('kaizen.drawing', 'on', true);

  FOR v_var IN
    SELECT x.variant_id, sum(x.quantity)::integer AS quantity, v.stock_policy, v.backorder_days
      FROM (
        SELECT ol.store_id, ol.variant_id, ol.quantity
          FROM commerce.order_lines ol
         WHERE ol.order_id = p_order_id AND ol.variant_id IS NOT NULL AND ol.delivery = 'physical'
           AND NOT EXISTS (SELECT 1 FROM commerce.order_line_components c WHERE c.store_id = ol.store_id AND c.order_line_id = ol.id)
        UNION ALL
        SELECT ol.store_id, c.variant_id, c.quantity * ol.quantity
          FROM commerce.order_lines ol
          JOIN commerce.order_line_components c ON c.store_id = ol.store_id AND c.order_line_id = ol.id
         WHERE ol.order_id = p_order_id
      ) x
      JOIN commerce.product_variants v ON v.store_id = x.store_id AND v.id = x.variant_id
     GROUP BY x.variant_id, v.stock_policy, v.backorder_days
     ORDER BY x.variant_id
  LOOP
    -- Every writer locks a variant's level rows in location order, so two payments cannot deadlock.
    PERFORM 1 FROM commerce.inventory_levels l
     WHERE l.store_id = v_order.store_id AND l.variant_id = v_var.variant_id
     ORDER BY l.location_id FOR UPDATE;
    v_left := v_var.quantity;
    v_back := 0;

    -- (1) Where the items were held for this order: its own claim first.
    FOR v_hold IN
      SELECT loc.id AS location_id, sum(r.quantity)::integer AS quantity, sum(r.backorder_quantity)::integer AS backordered,
             min(r.created_at) AS held_since
        FROM commerce.inventory_reservations r
        JOIN commerce.inventory_locations loc ON loc.store_id = r.store_id AND loc.id = r.location_id
       WHERE r.order_id = p_order_id AND r.order_edit_id IS NULL AND r.variant_id = v_var.variant_id AND r.released_at IS NULL
       GROUP BY loc.id, loc.priority, loc.created_at
       ORDER BY loc.priority, loc.created_at, loc.id
    LOOP
      EXIT WHEN v_left = 0;
      SELECT l.on_hand INTO v_before FROM commerce.inventory_levels l
       WHERE l.store_id = v_order.store_id AND l.variant_id = v_var.variant_id AND l.location_id = v_hold.location_id;
      CONTINUE WHEN NOT FOUND;
      -- The physical claim the checkout made when it started: what no later checkout paying first can take.
      v_phys := v_hold.quantity - v_hold.backordered;
      IF v_hold.backordered > 0 THEN
        -- Units that came in (or a checkout that let go) since: the backordered part is covered as far as the stock, less the claims of
        -- the other live checkouts here (an earlier one in full, a later one by its physical part) and this order's own claim, reaches.
        SELECT coalesce(sum(CASE WHEN r.created_at <= v_hold.held_since THEN r.quantity ELSE r.quantity - r.backorder_quantity END), 0)::integer
          INTO v_claimed
          FROM commerce.inventory_reservations r
         WHERE r.store_id = v_order.store_id AND r.variant_id = v_var.variant_id AND r.location_id = v_hold.location_id
           AND (r.order_id IS DISTINCT FROM p_order_id OR r.order_edit_id IS NOT NULL) AND r.released_at IS NULL AND r.expires_at > now();
        v_phys := v_phys + least(v_hold.backordered, greatest(v_before - v_claimed - v_phys, 0));
      END IF;
      v_take := least(v_phys, v_left);
      -- Only what is really there, unless the variant keeps selling past zero: a hold does not create stock.
      IF v_var.stock_policy <> 'continue' THEN
        v_take := least(v_take, greatest(v_before, 0));
      END IF;
      -- The rest of the hold is what the shopper was told is on backorder: drawn below the shelf, and written to the lines as such.
      -- One change of the level (so one movement) for the whole hold at this location.
      v_extra := 0;
      IF v_var.stock_policy = 'continue' AND v_hold.quantity > v_phys THEN
        v_extra := least(v_hold.quantity - v_phys, v_left - v_take);
      END IF;
      IF v_take + v_extra > 0 THEN
        UPDATE commerce.inventory_levels SET on_hand = on_hand - (v_take + v_extra), updated_at = now()
         WHERE store_id = v_order.store_id AND variant_id = v_var.variant_id AND location_id = v_hold.location_id;
        v_back := v_back + v_extra;
        v_left := v_left - v_take - v_extra;
      END IF;
    END LOOP;

    -- (2) Then the stock no other live checkout holds, anywhere (a hold that expired before payment, a renewal), in rank order.
    FOR v_level IN
      SELECT l.location_id, l.on_hand
        FROM commerce.inventory_levels l
        JOIN commerce.inventory_locations loc ON loc.store_id = l.store_id AND loc.id = l.location_id AND loc.active AND loc.fulfils_online
       WHERE l.store_id = v_order.store_id AND l.variant_id = v_var.variant_id AND l.on_hand > 0
       ORDER BY loc.priority, loc.created_at, loc.id
    LOOP
      EXIT WHEN v_left = 0;
      SELECT coalesce(sum(r.quantity), 0)::integer INTO v_claimed
        FROM commerce.inventory_reservations r
       WHERE r.store_id = v_order.store_id AND r.variant_id = v_var.variant_id AND r.location_id = v_level.location_id
         AND (r.order_id IS DISTINCT FROM p_order_id OR r.order_edit_id IS NOT NULL) AND r.released_at IS NULL AND r.expires_at > now();
      v_take := least(greatest(v_level.on_hand - v_claimed, 0), v_left);
      CONTINUE WHEN v_take = 0;
      UPDATE commerce.inventory_levels SET on_hand = on_hand - v_take, updated_at = now()
       WHERE store_id = v_order.store_id AND variant_id = v_var.variant_id AND location_id = v_level.location_id;
      v_left := v_left - v_take;
    END LOOP;

    -- (3) The remainder: backordered at the first location that stocks the variant, or short.
    IF v_left > 0 THEN
      IF v_var.stock_policy = 'continue' THEN
        SELECT loc.id INTO v_home
          FROM commerce.inventory_locations loc
          JOIN commerce.inventory_levels l ON l.store_id = loc.store_id AND l.location_id = loc.id AND l.variant_id = v_var.variant_id
         WHERE loc.store_id = v_order.store_id AND loc.active AND loc.fulfils_online
         ORDER BY loc.priority, loc.created_at, loc.id LIMIT 1;
        IF v_home IS NULL THEN
          SELECT loc.id INTO v_home FROM commerce.inventory_locations loc
           WHERE loc.store_id = v_order.store_id AND loc.active AND loc.fulfils_online
           ORDER BY loc.priority, loc.created_at, loc.id LIMIT 1;
          IF v_home IS NOT NULL THEN
            INSERT INTO commerce.inventory_levels (store_id, variant_id, location_id, on_hand)
            VALUES (v_order.store_id, v_var.variant_id, v_home, 0)
            ON CONFLICT (variant_id, location_id) DO NOTHING;
          END IF;
        END IF;
        IF v_home IS NULL THEN
          v_short := v_short + v_left;
        ELSE
          PERFORM 1 FROM commerce.inventory_levels l
           WHERE l.store_id = v_order.store_id AND l.variant_id = v_var.variant_id AND l.location_id = v_home FOR UPDATE;
          UPDATE commerce.inventory_levels SET on_hand = on_hand - v_left, updated_at = now()
           WHERE store_id = v_order.store_id AND variant_id = v_var.variant_id AND location_id = v_home;
          -- Beyond what any checkout had claimed: all of it is backordered.
          v_back := v_back + v_left;
        END IF;
      ELSE
        v_short := v_short + v_left;
      END IF;
    END IF;

    -- The backordered units go to the variant's lines: paid lines first, then a gift, in id order.
    IF v_back > 0 THEN
      FOR v_line IN
        SELECT ol.id, ol.quantity, ol.sku FROM commerce.order_lines ol
         WHERE ol.order_id = p_order_id AND ol.variant_id = v_var.variant_id AND ol.delivery = 'physical'
         ORDER BY ol.gift, ol.id
      LOOP
        v_alloc := least(v_line.quantity, v_back);
        UPDATE commerce.order_lines
           SET backorder_quantity = v_alloc, backorder_days = CASE WHEN v_alloc > 0 THEN coalesce(backorder_days, v_var.backorder_days) ELSE backorder_days END
         WHERE id = v_line.id;
        IF v_alloc > 0 THEN
          v_lines := v_lines || jsonb_build_array(jsonb_build_object('sku', v_line.sku, 'quantity', v_alloc));
        END IF;
        v_back := v_back - v_alloc;
      END LOOP;
    ELSE
      UPDATE commerce.order_lines SET backorder_quantity = 0
       WHERE order_id = p_order_id AND variant_id = v_var.variant_id AND backorder_quantity <> 0;
    END IF;
  END LOOP;

  IF jsonb_array_length(v_lines) > 0 THEN
    INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
    VALUES (v_order.store_id, p_order_id, 'stock.backordered', jsonb_build_object('lines', v_lines), 'system');
  END IF;

  PERFORM set_config('kaizen.stock', coalesce(v_prev_stock, ''), true);
  PERFORM set_config('kaizen.drawing', coalesce(v_prev_drawing, ''), true);
  RETURN v_short;
END;
$$;


--
-- Name: duplicate_store(uuid, text, text, uuid, uuid[], uuid[], uuid[]); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.duplicate_store(p_source uuid, p_slug text, p_name text, p_owner uuid, p_page_ids uuid[] DEFAULT NULL::uuid[], p_product_ids uuid[] DEFAULT NULL::uuid[], p_post_ids uuid[] DEFAULT NULL::uuid[]) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_store uuid;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM commerce.stores WHERE id = p_source) THEN
    RAISE EXCEPTION 'unknown store %', p_source;
  END IF;

  -- Tracking ids (analytics, pixels) and the store's own code belong to the original's site: the copy starts with
  -- none, so its visits are never sent to the original's tools.
  INSERT INTO commerce.stores (
    slug, name, created_by, legal_name, organisation_number, contact_email, postal_address, country, seo, navigation,
    cart_reminders, tracking, fonts, theme, custom_code, audience, business_popup, open_cart_on_add, modules, features,
    time_zone, booking_reminder_hours, custom_css, locales, rates_auto, rates_updated_at, price_decimals, price_words, quantity_picker, language_rule, currency_follows_language, language_currencies
  )
  SELECT p_slug, p_name, p_owner, s.legal_name, s.organisation_number, s.contact_email, s.postal_address, s.country,
         s.seo, s.navigation, s.cart_reminders, '{}'::jsonb, s.fonts, s.theme, '{}'::jsonb, s.audience,
         s.business_popup, s.open_cart_on_add, array_remove(s.modules, 'work'), s.features, s.time_zone,
         s.booking_reminder_hours, s.custom_css, s.locales, s.rates_auto, s.rates_updated_at, s.price_decimals, s.price_words, s.quantity_picker, s.language_rule, s.currency_follows_language, s.language_currencies
    FROM commerce.stores s WHERE s.id = p_source
  RETURNING id INTO v_store;

  -- Only the person copying owns the new store; the other members stay with the original.
  INSERT INTO commerce.store_members (store_id, account_id, role) VALUES (v_store, p_owner, 'owner');

  -- Which things are copied, and their new ids (null: left behind).
  CREATE TEMP TABLE IF NOT EXISTS _copy_ids (old_id uuid PRIMARY KEY, new_id uuid) ON COMMIT DROP;
  TRUNCATE pg_temp._copy_ids;
  INSERT INTO pg_temp._copy_ids (old_id, new_id)
  SELECT p.id, CASE WHEN p.status <> 'archived' AND (p_product_ids IS NULL OR p.id = ANY (p_product_ids))
                    THEN commerce.clone_id(v_store, p.id) END
    FROM commerce.products p WHERE p.store_id = p_source;
  INSERT INTO pg_temp._copy_ids (old_id, new_id)
  SELECT v.id, CASE WHEN m.new_id IS NOT NULL THEN commerce.clone_id(v_store, v.id) END
    FROM commerce.product_variants v
    JOIN pg_temp._copy_ids m ON m.old_id = v.product_id
   WHERE v.store_id = p_source;
  INSERT INTO pg_temp._copy_ids (old_id, new_id)
  SELECT p.id, CASE WHEN CASE p.type
                          WHEN 'page' THEN p_page_ids IS NULL OR p.id = ANY (p_page_ids)
                          WHEN 'article' THEN p_post_ids IS NULL OR p.id = ANY (p_post_ids)
                          ELSE true
                        END
                    THEN commerce.clone_id(v_store, p.id) END
    FROM commerce.pages p WHERE p.store_id = p_source;
  INSERT INTO pg_temp._copy_ids (old_id, new_id)
  SELECT id, commerce.clone_id(v_store, id) FROM commerce.terms WHERE store_id = p_source
  UNION ALL SELECT id, commerce.clone_id(v_store, id) FROM commerce.menus WHERE store_id = p_source
  UNION ALL SELECT id, commerce.clone_id(v_store, id) FROM commerce.field_groups WHERE store_id = p_source
  UNION ALL SELECT id, commerce.clone_id(v_store, id) FROM commerce.saved_parts WHERE store_id = p_source
  UNION ALL SELECT id, commerce.clone_id(v_store, id) FROM commerce.store_themes WHERE store_id = p_source
  UNION ALL SELECT id, commerce.clone_id(v_store, id) FROM commerce.customer_tiers WHERE store_id = p_source
  UNION ALL SELECT id, commerce.clone_id(v_store, id) FROM commerce.customer_companies WHERE store_id = p_source
  UNION ALL SELECT id, commerce.clone_id(v_store, id) FROM commerce.discount_codes WHERE store_id = p_source
  UNION ALL SELECT id, commerce.clone_id(v_store, id) FROM commerce.content_types WHERE store_id = p_source
  UNION ALL SELECT id, commerce.clone_id(v_store, id) FROM commerce.content_entries WHERE store_id = p_source;

  -- Settings ------------------------------------------------------------------------------------------------

  -- What the store accepts: the switches, never the keys (a new Stripe account is the new owner's to connect).
  UPDATE commerce.payment_providers n
     SET enabled = s.enabled, order_invoices = s.order_invoices
    FROM commerce.payment_providers s
   WHERE s.store_id = p_source AND n.store_id = v_store AND n.provider = s.provider;

  INSERT INTO commerce.markets (store_id, code, currency, default_locale, locales, active, created_at, price_decimals)
  SELECT v_store, code, currency, default_locale, locales, active, created_at, price_decimals
    FROM commerce.markets WHERE store_id = p_source;

  INSERT INTO commerce.store_currencies (store_id, currency, rate, round_to, position)
  SELECT v_store, currency, rate, round_to, position
    FROM commerce.store_currencies WHERE store_id = p_source;

  INSERT INTO commerce.shipping_rates (store_id, market_code, currency, amount_minor, free_over_minor)
  SELECT v_store, market_code, currency, amount_minor, free_over_minor
    FROM commerce.shipping_rates WHERE store_id = p_source;

  INSERT INTO commerce.payment_methods (store_id, market_code, method, enabled)
  SELECT v_store, market_code, method, enabled
    FROM commerce.payment_methods WHERE store_id = p_source;

  INSERT INTO commerce.economic_operators (id, store_id, name, postal_address, electronic_address, country, created_at)
  SELECT commerce.clone_id(v_store, id), v_store, name, postal_address, electronic_address, country, created_at
    FROM commerce.economic_operators WHERE store_id = p_source;

  INSERT INTO commerce.inventory_locations (id, store_id, name, country, active, created_at, priority, fulfils_online)
  SELECT commerce.clone_id(v_store, id), v_store, name, country, active, created_at, priority, fulfils_online
    FROM commerce.inventory_locations WHERE store_id = p_source AND supplier_id IS NULL;

  INSERT INTO commerce.store_locations (
    id, store_id, kind, name, street, postal_code, city, country, phone, notes, hours, position
  )
  SELECT commerce.clone_id(v_store, id), v_store, kind, name, street, postal_code, city, country, phone, notes, hours,
         position
    FROM commerce.store_locations WHERE store_id = p_source;

  -- Staff, rooms and rental items. A host's are the host's (hosts stay with the original), and a calendar's
  -- secret address is the original's; the copy gets its own when it is published.
  INSERT INTO commerce.booking_resources (
    id, store_id, kind, name, email, hours, capacity, active, position, host_id, property_address, land_registry_number
  )
  SELECT commerce.clone_id(v_store, id), v_store, kind, name, email, hours, capacity, active, position, NULL,
         property_address, land_registry_number
    FROM commerce.booking_resources WHERE store_id = p_source AND host_id IS NULL;

  INSERT INTO commerce.customer_tiers (id, store_id, name, percent, note, active, created_at)
  SELECT commerce.clone_id(v_store, id), v_store, name, percent, note, active, created_at
    FROM commerce.customer_tiers WHERE store_id = p_source;

  INSERT INTO commerce.customer_companies (
    id, store_id, name, organisation_number, tier_id, employee_share_percent, max_members, active, created_at
  )
  SELECT commerce.clone_id(v_store, id), v_store, name, organisation_number, commerce.clone_id(v_store, tier_id),
         employee_share_percent, max_members, active, created_at
    FROM commerce.customer_companies WHERE store_id = p_source;

  INSERT INTO commerce.store_themes (id, store_id, name, base, settings, created_by, created_at)
  SELECT commerce.clone_id(v_store, id), v_store, name, base, settings, p_owner, created_at
    FROM commerce.store_themes WHERE store_id = p_source;

  INSERT INTO commerce.cookie_notes (store_id, kind, name, domain, category, provider, purpose, updated_by)
  SELECT v_store, kind, name, domain, category, provider, purpose, p_owner
    FROM commerce.cookie_notes WHERE store_id = p_source;

  INSERT INTO commerce.chat_agents (
    store_id, enabled, name, occupation, avatar, avatar_style, greeting, instructions, voice, daily_limit, updated_by
  )
  SELECT v_store, enabled, name, occupation, avatar, avatar_style, greeting, instructions, voice, daily_limit, p_owner
    FROM commerce.chat_agents WHERE store_id = p_source;

  INSERT INTO commerce.knowledge_documents (id, store_id, title, file_name, content, created_at, updated_at, created_by)
  SELECT commerce.clone_id(v_store, id), v_store, title, file_name, content, created_at, updated_at, p_owner
    FROM commerce.knowledge_documents WHERE store_id = p_source;

  -- A code for some customers (D299) is copied without them, and switched off: the copy's customers are not yet there,
  -- and a code for nobody in particular would be a code for everyone. Its generated codes are never copied.
  INSERT INTO commerce.discount_codes (
    id, store_id, code, kind, percent, amounts, min_subtotals, product_ids, recurring, starts_at, ends_at,
    usage_limit, once_per_customer, active, created_at, updated_at, min_quantity, unique_codes, combines_with
  )
  SELECT commerce.clone_id(v_store, id), v_store, code, kind, percent, amounts, min_subtotals, product_ids, recurring,
         starts_at, ends_at, usage_limit, once_per_customer, active AND jsonb_array_length(customer_ids) = 0,
         created_at, updated_at, min_quantity, unique_codes, combines_with
    FROM commerce.discount_codes WHERE store_id = p_source AND NOT reward;

  INSERT INTO commerce.cart_reminder_steps (
    id, store_id, delay_minutes, active, discount_code_id, content, created_at, updated_at
  )
  SELECT commerce.clone_id(v_store, id), v_store, delay_minutes, active, commerce.clone_id(v_store, discount_code_id),
         content, created_at, updated_at
    FROM commerce.cart_reminder_steps WHERE store_id = p_source;

  -- The bonus program's settings (D130); the ledger never: customers' credits belong to the original's customers.
  INSERT INTO commerce.bonus_settings (
    store_id, enabled, earn_bps, pending_days, max_redeem_percent, min_redeem_minor, expires_months, levels, signup_minor, birthday_minor, currency, updated_by
  )
  SELECT v_store, enabled, earn_bps, pending_days, max_redeem_percent, min_redeem_minor, expires_months, levels, signup_minor, birthday_minor, currency, p_owner
    FROM commerce.bonus_settings WHERE store_id = p_source;

  -- The affiliate program's settings (D131); never its affiliates, attributions or visits: customers' codes, who referred
  -- whom and what was earned belong to the original store and its customers.
  INSERT INTO commerce.affiliate_settings (
    store_id, enabled, reward_bps, reward_orders, friend_percent, friend_max_minor, monthly_cap_minor, cookie_days, updated_by
  )
  SELECT v_store, enabled, reward_bps, reward_orders, friend_percent, friend_max_minor, monthly_cap_minor, cookie_days, p_owner
    FROM commerce.affiliate_settings WHERE store_id = p_source;

  INSERT INTO commerce.delivery_schedules (
    id, store_id, market_code, currency, name, delivery_weekday, cutoff_days, cutoff_time, active, created_at
  )
  SELECT commerce.clone_id(v_store, id), v_store, market_code, currency, name, delivery_weekday, cutoff_days,
         cutoff_time, active, created_at
    FROM commerce.delivery_schedules WHERE store_id = p_source;

  -- Categories and tags (D50) belong to the store's structure, so all come, whichever products do. Parents are
  -- set once every category exists, so the parent check finds them.
  INSERT INTO commerce.terms (id, store_id, content_type, kind, name, slug, position, created_at, updated_at, requires_unit_price, seo, description, image_url, image_thumbnail_url, texts, rules)
  SELECT commerce.clone_id(v_store, id), v_store, content_type, kind, name, slug, position, created_at, updated_at, requires_unit_price, seo, description, image_url, image_thumbnail_url, texts, commerce.clone_term_rules(v_store, rules)
    FROM commerce.terms WHERE store_id = p_source;

  UPDATE commerce.terms n
     SET parent_id = commerce.clone_id(v_store, t.parent_id)
    FROM commerce.terms t
   WHERE t.store_id = p_source AND t.parent_id IS NOT NULL AND n.id = commerce.clone_id(v_store, t.id);

  INSERT INTO commerce.field_groups (
    id, store_id, name, slug, entities, location, fields, position, active, sort, created_at, updated_at
  )
  SELECT commerce.clone_id(v_store, g.id), v_store, g.name, g.slug, g.entities,
         commerce.clone_field_location(v_store, g.location), g.fields, g.position, g.active, g.sort, g.created_at,
         g.updated_at
    FROM commerce.field_groups g WHERE g.store_id = p_source;

  -- The store's saved rows, columns and components (D46) as private ones: what the owner shared with other
  -- stores or the marketplace stays the original's to share. Global ones (D98) keep their ids' meaning, as the
  -- pages using them are remapped below.
  INSERT INTO commerce.saved_parts (
    id, store_id, kind, name, content, created_at, created_by, updated_at, updated_by, global, translations, sharing
  )
  SELECT commerce.clone_id(v_store, id), v_store, kind, name, commerce.copy_remap(content, p_source, v_store),
         created_at, p_owner, updated_at, p_owner, global, translations, 'private'
    FROM commerce.saved_parts WHERE store_id = p_source;

  INSERT INTO commerce.template_activations (store_id, part_id, active, changed_at, changed_by)
  SELECT v_store, a.part_id, a.active, a.changed_at, p_owner
    FROM commerce.template_activations a WHERE a.store_id = p_source;

  -- Products ------------------------------------------------------------------------------------------------

  PERFORM set_config('commerce.unit_price_copying', 'on', true);

  -- They arrive as drafts and are published below, once their pictures, titles and variants exist (the
  -- publishing check needs them).
  INSERT INTO commerce.products (
    id, store_id, handle, status, manufacturer_id, responsible_person_id, tax_code, withdrawal_exclusion, delivery,
    download_limit, download_days, subscription_only, kind, vat_category, audience, created_at, updated_at, sold_by_measure, bundle_pricing, bundle_percent_off, standard_category, standard_attributes, price_words, price_on_request
  )
  SELECT m.new_id, v_store, p.handle, 'draft', commerce.clone_id(v_store, p.manufacturer_id),
         commerce.clone_id(v_store, p.responsible_person_id), p.tax_code, p.withdrawal_exclusion, p.delivery,
         p.download_limit, p.download_days, p.subscription_only, p.kind, p.vat_category, p.audience, p.created_at,
         p.updated_at, p.sold_by_measure, p.bundle_pricing, p.bundle_percent_off, p.standard_category, p.standard_attributes, p.price_words, p.price_on_request
    FROM commerce.products p JOIN pg_temp._copy_ids m ON m.old_id = p.id
   WHERE p.store_id = p_source AND m.new_id IS NOT NULL;

  INSERT INTO commerce.product_translations (
    store_id, product_id, locale, title, description, safety_information, seo_title, seo_description, excerpt
  )
  SELECT v_store, m.new_id, t.locale, t.title, t.description, t.safety_information, t.seo_title, t.seo_description, t.excerpt
    FROM commerce.product_translations t JOIN pg_temp._copy_ids m ON m.old_id = t.product_id
   WHERE t.store_id = p_source AND m.new_id IS NOT NULL;

  INSERT INTO commerce.product_media (store_id, product_id, url, position, alt, thumbnail_url, kind, source, media_url)
  SELECT v_store, m.new_id, pm.url, pm.position, pm.alt, pm.thumbnail_url, pm.kind, pm.source, pm.media_url
    FROM commerce.product_media pm JOIN pg_temp._copy_ids m ON m.old_id = pm.product_id
   WHERE pm.store_id = p_source AND m.new_id IS NOT NULL;

  INSERT INTO commerce.product_schemes (store_id, product_id, scheme)
  SELECT v_store, m.new_id, s.scheme
    FROM commerce.product_schemes s JOIN pg_temp._copy_ids m ON m.old_id = s.product_id
   WHERE s.store_id = p_source AND m.new_id IS NOT NULL;

  INSERT INTO commerce.product_terms (store_id, product_id, term_id, content_type, position)
  SELECT v_store, m.new_id, commerce.clone_id(v_store, pt.term_id), pt.content_type, pt.position
    FROM commerce.product_terms pt JOIN pg_temp._copy_ids m ON m.old_id = pt.product_id
   WHERE pt.store_id = p_source AND m.new_id IS NOT NULL;

  INSERT INTO commerce.product_variants (
    id, store_id, product_id, sku, gtin, tax_code, options, weight_grams, hs_code, origin_country, active, delivery,
    rental_period, image_url, image_thumbnail_url, created_at, cost_minor,
    measure_amount, measure_unit, measure_base, stock_policy, backorder_days, preorder_until, low_stock_threshold,
    min_quantity, max_quantity, quantity_step
  )
  SELECT m.new_id, v_store, commerce.clone_id(v_store, v.product_id), v.sku, v.gtin, v.tax_code, v.options,
         v.weight_grams, v.hs_code, v.origin_country, v.active, v.delivery, v.rental_period, v.image_url,
         v.image_thumbnail_url, v.created_at, v.cost_minor,
         v.measure_amount, v.measure_unit, v.measure_base, v.stock_policy, v.backorder_days, v.preorder_until, v.low_stock_threshold,
         v.min_quantity, v.max_quantity, v.quantity_step
    FROM commerce.product_variants v JOIN pg_temp._copy_ids m ON m.old_id = v.id
   WHERE v.store_id = p_source AND m.new_id IS NOT NULL;

  INSERT INTO commerce.selling_plans (
    id, store_id, product_id, interval, interval_count, discount_percent, trial_days, signup_fee, min_cycles,
    position, active, created_at
  )
  SELECT commerce.clone_id(v_store, sp.id), v_store, commerce.clone_id(v_store, sp.product_id), sp.interval,
         sp.interval_count, sp.discount_percent, sp.trial_days, sp.signup_fee, sp.min_cycles, sp.position, sp.active,
         sp.created_at
    FROM commerce.selling_plans sp JOIN pg_temp._copy_ids m ON m.old_id = sp.product_id
   WHERE sp.store_id = p_source AND m.new_id IS NOT NULL;

  INSERT INTO commerce.product_market_texts (store_id, product_id, market_code, locale, description)
  SELECT v_store, mp.new_id, mt.market_code, mt.locale, mt.description
    FROM commerce.product_market_texts mt
    JOIN pg_temp._copy_ids mp ON mp.old_id = mt.product_id
   WHERE mt.store_id = p_source AND mp.new_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM commerce.markets m WHERE m.store_id = v_store AND m.code = mt.market_code);

  INSERT INTO commerce.market_availability (store_id, product_id, variant_id, market_code)
  SELECT v_store, mp.new_id, mv.new_id, ma.market_code
    FROM commerce.market_availability ma
    JOIN pg_temp._copy_ids mp ON mp.old_id = ma.product_id
    LEFT JOIN pg_temp._copy_ids mv ON mv.old_id = ma.variant_id
   WHERE ma.store_id = p_source AND mp.new_id IS NOT NULL
     AND (ma.variant_id IS NULL OR mv.new_id IS NOT NULL)
     AND EXISTS (SELECT 1 FROM commerce.markets m WHERE m.store_id = v_store AND m.code = ma.market_code);

  INSERT INTO commerce.bundle_components (store_id, bundle_variant_id, component_variant_id, quantity, position)
  SELECT v_store, mb.new_id, mc.new_id, bc.quantity, bc.position
    FROM commerce.bundle_components bc
    JOIN pg_temp._copy_ids mb ON mb.old_id = bc.bundle_variant_id
    JOIN pg_temp._copy_ids mc ON mc.old_id = bc.component_variant_id
   WHERE bc.store_id = p_source AND mb.new_id IS NOT NULL AND mc.new_id IS NOT NULL;

  INSERT INTO commerce.price_breaks (store_id, product_id, variant_id, from_quantity, percent, amounts)
  SELECT v_store, mp.new_id, mv.new_id, b.from_quantity, b.percent, b.amounts
    FROM commerce.price_breaks b
    JOIN pg_temp._copy_ids mp ON mp.old_id = b.product_id
    LEFT JOIN pg_temp._copy_ids mv ON mv.old_id = b.variant_id
   WHERE b.store_id = p_source AND mp.new_id IS NOT NULL AND (b.variant_id IS NULL OR mv.new_id IS NOT NULL);

  INSERT INTO commerce.search_synonyms (store_id, locale, kind, words, means, created_at, updated_at)
  SELECT v_store, s.locale, s.kind, s.words, s.means, s.created_at, s.updated_at FROM commerce.search_synonyms s WHERE s.store_id = p_source;

  INSERT INTO commerce.search_rules (store_id, action, product_id, term_id, target, queries, match, position, created_at, updated_at)
  SELECT v_store, r.action, mp.new_id, mt.new_id, r.target, r.queries, r.match, r.position, r.created_at, r.updated_at
    FROM commerce.search_rules r
    LEFT JOIN pg_temp._copy_ids mp ON mp.old_id = r.product_id
    LEFT JOIN pg_temp._copy_ids mt ON mt.old_id = r.term_id
   WHERE r.store_id = p_source AND (r.product_id IS NULL OR mp.new_id IS NOT NULL) AND (r.term_id IS NULL OR mt.new_id IS NOT NULL);

  -- The current price of each variant, as a new price: the copy shows no reduction it never made.
  INSERT INTO commerce.prices (store_id, variant_id, market_code, currency, amount_minor, valid_from)
  SELECT v_store, m.new_id, pr.market_code, pr.currency, pr.amount_minor, now()
    FROM commerce.prices pr JOIN pg_temp._copy_ids m ON m.old_id = pr.variant_id
   WHERE pr.store_id = p_source AND pr.valid_to IS NULL AND m.new_id IS NOT NULL;

  PERFORM commerce.stock_context('opening', 'copy', NULL, NULL, NULL, NULL, NULL);
  INSERT INTO commerce.inventory_levels (store_id, variant_id, location_id, on_hand)
  SELECT v_store, m.new_id, commerce.clone_id(v_store, l.location_id), greatest(l.on_hand, 0)
    FROM commerce.inventory_levels l JOIN pg_temp._copy_ids m ON m.old_id = l.variant_id
    JOIN commerce.product_variants sv ON sv.store_id = l.store_id AND sv.id = l.variant_id AND sv.delivery = 'physical'
   WHERE l.store_id = p_source AND m.new_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM commerce.inventory_locations sl WHERE sl.store_id = l.store_id AND sl.id = l.location_id AND sl.supplier_id IS NOT NULL);
  PERFORM commerce.stock_context_clear();

  INSERT INTO commerce.appointment_settings (
    product_id, store_id, duration_minutes, buffer_before_minutes, buffer_after_minutes, step_minutes,
    min_notice_minutes, max_days_ahead, location_id, payment, deposit_percent, cancel_hours, no_show_percent,
    check_in_time, check_out_time, min_nights, max_nights, booking_fee
  )
  SELECT m.new_id, v_store, a.duration_minutes, a.buffer_before_minutes, a.buffer_after_minutes, a.step_minutes,
         a.min_notice_minutes, a.max_days_ahead, commerce.clone_id(v_store, a.location_id), a.payment,
         a.deposit_percent, a.cancel_hours, a.no_show_percent, a.check_in_time, a.check_out_time, a.min_nights,
         a.max_nights, a.booking_fee
    FROM commerce.appointment_settings a JOIN pg_temp._copy_ids m ON m.old_id = a.product_id
   WHERE a.store_id = p_source AND m.new_id IS NOT NULL;

  INSERT INTO commerce.booking_seasons (store_id, product_id, name, names, from_day, to_day, weekdays, percent, position)
  SELECT v_store, m.new_id, s.name, s.names, s.from_day, s.to_day, s.weekdays, s.percent, s.position
    FROM commerce.booking_seasons s JOIN pg_temp._copy_ids m ON m.old_id = s.product_id
   WHERE s.store_id = p_source AND m.new_id IS NOT NULL;

  INSERT INTO commerce.product_resources (store_id, product_id, resource_id)
  SELECT v_store, m.new_id, commerce.clone_id(v_store, pr.resource_id)
    FROM commerce.product_resources pr JOIN pg_temp._copy_ids m ON m.old_id = pr.product_id
   WHERE pr.store_id = p_source AND m.new_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM commerce.booking_resources r
                  WHERE r.store_id = v_store AND r.id = commerce.clone_id(v_store, pr.resource_id));

  -- Menus (D85): their links name pages, categories and tags by address, which the copies keep; a link to a
  -- product that was not copied goes.
  INSERT INTO commerce.menus (id, store_id, name, items, created_at, created_by, updated_at, updated_by)
  SELECT commerce.clone_id(v_store, id), v_store, name,
         commerce.copy_remap(commerce.copy_menu_items(v_store, items), p_source, v_store), created_at, p_owner,
         updated_at, p_owner
    FROM commerce.menus WHERE store_id = p_source;

  -- Pages, posts, headers, footers and product layouts ----------------------------------------------------------

  -- The chosen pages and posts, and every header, footer and product layout (they are settings), with their
  -- draft and published content: category, tag, menu, field group and saved part ids made the copies'. Posts
  -- keep the dates they were first published on.
  INSERT INTO commerce.pages (
    id, store_id, type, slug, draft, published, published_at, first_published_at, created_at, created_by, updated_at,
    updated_by
  )
  SELECT m.new_id, v_store, p.type, p.slug, commerce.copy_remap(p.draft, p_source, v_store),
         commerce.copy_remap(p.published, p_source, v_store), p.published_at, p.first_published_at, p.created_at,
         p_owner, p.updated_at, p_owner
    FROM commerce.pages p JOIN pg_temp._copy_ids m ON m.old_id = p.id
   WHERE p.store_id = p_source AND m.new_id IS NOT NULL;

  UPDATE commerce.stores s
     SET front_page_id = (SELECT m.new_id FROM pg_temp._copy_ids m WHERE m.old_id = t.front_page_id),
         products_page_id = (SELECT m.new_id FROM pg_temp._copy_ids m WHERE m.old_id = t.products_page_id),
         product_layout_id = (SELECT m.new_id FROM pg_temp._copy_ids m WHERE m.old_id = t.product_layout_id),
         header_id = (SELECT m.new_id FROM pg_temp._copy_ids m WHERE m.old_id = t.header_id),
         footer_id = (SELECT m.new_id FROM pg_temp._copy_ids m WHERE m.old_id = t.footer_id),
         header_menu_id = (SELECT m.new_id FROM pg_temp._copy_ids m WHERE m.old_id = t.header_menu_id),
         footer_menu_id = (SELECT m.new_id FROM pg_temp._copy_ids m WHERE m.old_id = t.footer_menu_id),
         theme = commerce.copy_remap(t.theme, p_source, v_store)
    FROM commerce.stores t
   WHERE s.id = v_store AND t.id = p_source;

  UPDATE commerce.terms c
     SET product_layout_id = m.new_id
    FROM commerce.terms t JOIN pg_temp._copy_ids m ON m.old_id = t.product_layout_id
   WHERE t.store_id = p_source AND c.store_id = v_store AND c.id = commerce.clone_id(v_store, t.id)
     AND m.new_id IS NOT NULL;

  UPDATE commerce.products c
     SET product_layout_id = m.new_id
    FROM commerce.products t JOIN pg_temp._copy_ids m ON m.old_id = t.product_layout_id
   WHERE t.store_id = p_source AND c.store_id = v_store AND c.id = commerce.clone_id(v_store, t.id)
     AND m.new_id IS NOT NULL;

  -- The blog, search, 404 and working pages (D112, D113): the copies of the original's chosen pages.
  INSERT INTO commerce.page_roles (store_id, role, page_id)
  SELECT v_store, r.role, m.new_id
    FROM commerce.page_roles r JOIN pg_temp._copy_ids m ON m.old_id = r.page_id
   WHERE r.store_id = p_source AND m.new_id IS NOT NULL;

  -- Products' status: what it was, but a download waits as a draft for its files (they stay with the original).
  UPDATE commerce.products p
     SET status = 'active'
    FROM commerce.products t
   WHERE t.store_id = p_source AND t.status = 'active' AND p.store_id = v_store
     AND p.id = commerce.clone_id(v_store, t.id)
     AND NOT EXISTS (
       SELECT 1 FROM commerce.product_variants v
        WHERE v.product_id = p.id AND v.active AND v.delivery = 'digital'
     );

  -- Campaigns (D114) and what they name ----------------------------------------------------------------------------

  -- A campaign for products that were not copied is switched off rather than left to reach the whole store,
  -- and one giving a product that was not copied is left out (a gift needs its product).
  INSERT INTO commerce.campaigns (
    id, store_id, name, kind, percent, buy_quantity, pay_quantity, gift_variant_id, gift_quantity, thresholds,
    product_ids, term_ids, starts_at, ends_at, active, created_at, updated_at, tier_ids, usage_limit, stacks,
    per_customer_limit, markets, amounts, tier_basis, tiers, buy_min_quantity, buy_min_amounts,
    get_product_ids, get_term_ids, get_quantity, get_kind, get_percent, get_amounts, uses_per_order
  )
  SELECT commerce.clone_id(v_store, c.id), v_store, c.name, c.kind, c.percent, c.buy_quantity, c.pay_quantity,
         g.new_id, c.gift_quantity, c.thresholds, scoped.product_ids, commerce.copy_remap(c.term_ids, p_source, v_store),
         c.starts_at, c.ends_at,
         c.active AND NOT (
           jsonb_array_length(c.product_ids) + jsonb_array_length(c.term_ids) > 0
           AND jsonb_array_length(scoped.product_ids) + jsonb_array_length(c.term_ids) = 0
         ),
         c.created_at, c.updated_at, commerce.copy_remap(c.tier_ids, p_source, v_store), c.usage_limit, c.stacks,
         c.per_customer_limit, c.markets, c.amounts, c.tier_basis, c.tiers, c.buy_min_quantity, c.buy_min_amounts,
         commerce.copy_remap(c.get_product_ids, p_source, v_store), commerce.copy_remap(c.get_term_ids, p_source, v_store),
         c.get_quantity, c.get_kind, c.get_percent, c.get_amounts, c.uses_per_order
    FROM commerce.campaigns c
    LEFT JOIN pg_temp._copy_ids g ON g.old_id = c.gift_variant_id
    CROSS JOIN LATERAL (SELECT commerce.copy_remap(c.product_ids, p_source, v_store) AS product_ids) scoped
   WHERE c.store_id = p_source AND (c.gift_variant_id IS NULL OR g.new_id IS NOT NULL);

  UPDATE commerce.campaigns d
     SET active = false
    FROM commerce.campaigns t
   WHERE t.store_id = p_source AND t.kind = 'bxgy'
     AND jsonb_array_length(t.get_product_ids) + jsonb_array_length(t.get_term_ids) > 0
     AND d.store_id = v_store AND d.id = commerce.clone_id(v_store, t.id)
     AND jsonb_array_length(d.get_product_ids) + jsonb_array_length(d.get_term_ids) = 0;

  UPDATE commerce.discount_codes d
     SET product_ids = commerce.copy_remap(t.product_ids, p_source, v_store),
         active = t.active AND NOT (
           jsonb_array_length(t.product_ids) > 0
           AND jsonb_array_length(commerce.copy_remap(t.product_ids, p_source, v_store)) = 0
         )
    FROM commerce.discount_codes t
   WHERE t.store_id = p_source AND t.product_ids IS NOT NULL AND d.store_id = v_store
     AND d.id = commerce.clone_id(v_store, t.id);

  -- A code or campaign limited to a segment (D380) is copied switched off: the copy has no segments.
  UPDATE commerce.campaigns d
     SET active = false
    FROM commerce.campaigns t
   WHERE t.store_id = p_source AND t.segment_id IS NOT NULL
     AND d.store_id = v_store AND d.id = commerce.clone_id(v_store, t.id);
  UPDATE commerce.discount_codes d
     SET active = false
    FROM commerce.discount_codes t
   WHERE t.store_id = p_source AND t.segment_id IS NOT NULL
     AND d.store_id = v_store AND d.id = commerce.clone_id(v_store, t.id);

  -- Whether a campaign combines with codes, and a code with campaigns (D367), as the original says.
  UPDATE commerce.campaigns d
     SET combines_with_codes = t.combines_with_codes
    FROM commerce.campaigns t
   WHERE t.store_id = p_source AND NOT t.combines_with_codes
     AND d.store_id = v_store AND d.id = commerce.clone_id(v_store, t.id);
  UPDATE commerce.discount_codes d
     SET combines_with_campaigns = t.combines_with_campaigns
    FROM commerce.discount_codes t
   WHERE t.store_id = p_source AND NOT t.combines_with_campaigns
     AND d.store_id = v_store AND d.id = commerce.clone_id(v_store, t.id);

  -- Its categories, tags and customer groups (D299) are the copy's; one whose every one was left out is switched off.
  UPDATE commerce.discount_codes d
     SET term_ids = commerce.copy_remap(t.term_ids, p_source, v_store),
         tier_ids = commerce.copy_remap(t.tier_ids, p_source, v_store),
         active = d.active
           AND NOT (jsonb_array_length(t.term_ids) > 0 AND jsonb_array_length(commerce.copy_remap(t.term_ids, p_source, v_store)) = 0)
           AND NOT (jsonb_array_length(t.tier_ids) > 0 AND jsonb_array_length(commerce.copy_remap(t.tier_ids, p_source, v_store)) = 0)
    FROM commerce.discount_codes t
   WHERE t.store_id = p_source AND (jsonb_array_length(t.term_ids) > 0 OR jsonb_array_length(t.tier_ids) > 0)
     AND d.store_id = v_store AND d.id = commerce.clone_id(v_store, t.id);

  -- Custom fields (D118): what was entered for the things copied (a link or relation to something that was
  -- not copied is left out), the store's own values, and what keyword search reads of them.
  INSERT INTO commerce.field_values (store_id, entity, entity_id, locale, values, updated_at)
  SELECT v_store, fv.entity, m.new_id, fv.locale, commerce.copy_remap(fv.values, p_source, v_store), fv.updated_at
    FROM commerce.field_values fv JOIN pg_temp._copy_ids m ON m.old_id = fv.entity_id
   WHERE fv.store_id = p_source AND fv.entity IN ('product', 'page', 'article', 'variant', 'term')
     AND m.new_id IS NOT NULL;

  INSERT INTO commerce.field_values (store_id, entity, entity_id, locale, values, updated_at)
  SELECT v_store, 'store', v_store, fv.locale, commerce.copy_remap(fv.values, p_source, v_store), fv.updated_at
    FROM commerce.field_values fv
   WHERE fv.store_id = p_source AND fv.entity = 'store' AND fv.entity_id = p_source;

  -- Content types and entries (D326), what they name made the copy's (a page or product left behind is left out).
  INSERT INTO commerce.content_types (
    id, store_id, key, name, slug, fields, title_field, summary_field, picture_field, has_pages, layout_id, position, created_at, updated_by
  )
  SELECT m.new_id, v_store, t.key, t.name, t.slug, t.fields, t.title_field, t.summary_field, t.picture_field, t.has_pages,
         (SELECT ml.new_id FROM pg_temp._copy_ids ml WHERE ml.old_id = t.layout_id), t.position, t.created_at, p_owner
    FROM commerce.content_types t JOIN pg_temp._copy_ids m ON m.old_id = t.id
   WHERE t.store_id = p_source;

  INSERT INTO commerce.content_entries (
    id, store_id, type_id, slug, draft, published, published_at, first_published_at, position, created_at, created_by, updated_by
  )
  SELECT m.new_id, v_store, mt.new_id, e.slug, commerce.copy_remap(e.draft, p_source, v_store), commerce.copy_remap(e.published, p_source, v_store),
         e.published_at, e.first_published_at, e.position, e.created_at, p_owner, p_owner
    FROM commerce.content_entries e
    JOIN pg_temp._copy_ids m ON m.old_id = e.id
    JOIN pg_temp._copy_ids mt ON mt.old_id = e.type_id
   WHERE e.store_id = p_source;

  INSERT INTO commerce.field_search (store_id, entity, entity_id, locale, body)
  SELECT v_store, fs.entity, m.new_id, fs.locale, fs.body
    FROM commerce.field_search fs JOIN pg_temp._copy_ids m ON m.old_id = fs.entity_id
   WHERE fs.store_id = p_source AND m.new_id IS NOT NULL;

  -- How the store handles returns (D153); never its returns, withdrawals or their lines.
  INSERT INTO commerce.return_settings (
    store_id, window_days, transit_days, who_pays_return, refund_when, accept_excluded, instructions, instructions_translations, return_address,
    b2b_returns, exchanges, updated_by
  )
  SELECT v_store, window_days, transit_days, who_pays_return, refund_when, accept_excluded, instructions, instructions_translations, return_address,
         b2b_returns, exchanges, p_owner
    FROM commerce.return_settings WHERE store_id = p_source;

  -- The tax profile's choices (D157); never a VAT, OSS or IOSS number, a check or a registration date.
  INSERT INTO commerce.store_tax_profile (
    store_id, vat_registered, oss_scheme, oss_member_state, dispatch_country, ioss_markets, updated_by
  )
  SELECT v_store, vat_registered, oss_scheme, oss_member_state, dispatch_country, ioss_markets, p_owner
    FROM commerce.store_tax_profile WHERE store_id = p_source;

  -- The note printed on invoices and the confirmation switch (D159); the invoice and credit note numbers start again.
  INSERT INTO commerce.invoice_settings (store_id, enabled, footer_note, email_with_confirmation, updated_by)
  SELECT v_store, true, footer_note, email_with_confirmation, p_owner
    FROM commerce.invoice_settings WHERE store_id = p_source;


  -- Shipping methods (D237): the places' positions, the settings, profiles (and which copied product is in which), zones, methods and their rates, pickup
  -- options and local delivery areas, with new ids (the places were copied above under theirs).
  UPDATE commerce.store_locations n
     SET latitude = s.latitude, longitude = s.longitude
    FROM commerce.store_locations s
   WHERE s.store_id = p_source AND s.latitude IS NOT NULL
     AND n.store_id = v_store AND n.id = commerce.clone_id(v_store, s.id);

  INSERT INTO commerce.shipping_settings (store_id, default_weight_grams, updated_by)
  SELECT v_store, default_weight_grams, p_owner
    FROM commerce.shipping_settings WHERE store_id = p_source;

  INSERT INTO commerce.shipping_profiles (id, store_id, name, position, created_at)
  SELECT commerce.clone_id(v_store, id), v_store, name, position, created_at
    FROM commerce.shipping_profiles WHERE store_id = p_source;

  UPDATE commerce.products n
     SET shipping_profile_id = commerce.clone_id(v_store, p.shipping_profile_id)
    FROM commerce.products p
   WHERE p.store_id = p_source AND p.shipping_profile_id IS NOT NULL
     AND n.store_id = v_store AND n.id = commerce.clone_id(v_store, p.id);

  INSERT INTO commerce.shipping_zones (id, store_id, market_code, name, patterns, position, created_at)
  SELECT commerce.clone_id(v_store, id), v_store, market_code, name, patterns, position, created_at
    FROM commerce.shipping_zones WHERE store_id = p_source;

  INSERT INTO commerce.shipping_methods (
    id, store_id, market_code, currency, name, names, estimate_min_days, estimate_max_days, free_over_minor, active, position, created_at
  )
  SELECT commerce.clone_id(v_store, id), v_store, market_code, currency, name, names, estimate_min_days, estimate_max_days, free_over_minor, active,
         position, created_at
    FROM commerce.shipping_methods WHERE store_id = p_source;

  INSERT INTO commerce.shipping_method_rates (store_id, method_id, zone_id, profile_id, basis, min_value, max_value, amount_minor)
  SELECT v_store, commerce.clone_id(v_store, method_id), commerce.clone_id(v_store, zone_id), commerce.clone_id(v_store, profile_id),
         basis, min_value, max_value, amount_minor
    FROM commerce.shipping_method_rates WHERE store_id = p_source;

  INSERT INTO commerce.pickup_options (
    id, store_id, location_id, market_code, currency, amount_minor, ready_in_hours, instructions, instructions_t, active, position, created_at
  )
  SELECT commerce.clone_id(v_store, id), v_store, commerce.clone_id(v_store, location_id), market_code, currency, amount_minor, ready_in_hours,
         instructions, instructions_t, active, position, created_at
    FROM commerce.pickup_options WHERE store_id = p_source;

  INSERT INTO commerce.local_delivery_areas (
    id, store_id, location_id, market_code, currency, name, names, kind, patterns, radius_km, amount_minor, min_basket_minor, free_over_minor,
    info, info_t, active, position, created_at
  )
  SELECT commerce.clone_id(v_store, id), v_store, commerce.clone_id(v_store, location_id), market_code, currency, name, names, kind, patterns, radius_km,
         amount_minor, min_basket_minor, free_over_minor, info, info_t, active, position, created_at
    FROM commerce.local_delivery_areas WHERE store_id = p_source;


  -- Notifications (D238): the switches, the staff alert settings without their recipients (the defaults hold in the copy) and the automation rules, with
  -- a product condition kept to the copied products and a rule that lost one switched off.
  INSERT INTO commerce.notification_settings (store_id, notification, enabled, updated_by)
  SELECT v_store, notification, enabled, p_owner
    FROM commerce.notification_settings WHERE store_id = p_source;

  INSERT INTO commerce.staff_alert_settings (store_id, configured_at, summary, summary_weekday, summary_hour, contact_events, updated_by)
  SELECT v_store, NULL, summary, summary_weekday, summary_hour, contact_events, p_owner
    FROM commerce.staff_alert_settings WHERE store_id = p_source;

  INSERT INTO commerce.order_rules (id, store_id, name, event, match, conditions, actions, enabled, position, version, created_by, updated_by, created_at)
  SELECT commerce.clone_id(v_store, r.id), v_store, r.name, r.event, r.match, m.conditions, r.actions, r.enabled AND NOT m.lost, r.position, 1,
         p_owner, p_owner, r.created_at
    FROM commerce.order_rules r
    CROSS JOIN LATERAL (
      SELECT coalesce(jsonb_agg(c.mapped ORDER BY c.n) FILTER (WHERE c.mapped IS NOT NULL), '[]'::jsonb) AS conditions,
             coalesce(bool_or(c.lost), false) AS lost
        FROM (
          SELECT e.n,
                 CASE
                   WHEN e.value->>'kind' <> 'has_product' THEN e.value
                   WHEN jsonb_array_length(p.kept) = 0 THEN NULL
                   ELSE jsonb_set(e.value, '{productIds}', p.kept)
                 END AS mapped,
                 e.value->>'kind' = 'has_product' AND jsonb_array_length(p.kept) < jsonb_array_length(coalesce(e.value->'productIds', '[]'::jsonb)) AS lost
            FROM jsonb_array_elements(r.conditions) WITH ORDINALITY AS e(value, n)
            CROSS JOIN LATERAL (
              SELECT coalesce(jsonb_agg(to_jsonb(commerce.clone_id(v_store, pid.value::uuid)) ORDER BY pid.n), '[]'::jsonb) AS kept
                FROM jsonb_array_elements_text(CASE WHEN e.value->>'kind' = 'has_product' THEN coalesce(e.value->'productIds', '[]'::jsonb) ELSE '[]'::jsonb END)
                     WITH ORDINALITY AS pid(value, n)
               WHERE EXISTS (SELECT 1 FROM commerce.products np WHERE np.store_id = v_store AND np.id = commerce.clone_id(v_store, pid.value::uuid))
            ) p
        ) c
    ) m
   WHERE r.store_id = p_source;

  RETURN v_store;
END;
$$;


--
-- Name: entry_address(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.entry_address(p_entry uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT '/' || t.slug || '/' || e.slug
    FROM commerce.content_entries e
    JOIN commerce.content_types t ON t.id = e.type_id
   WHERE e.id = p_entry AND e.published IS NOT NULL AND t.has_pages;
$$;


--
-- Name: exchange_block(uuid, boolean); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.exchange_block(p_return uuid, p_claimed_ok boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  r commerce.returns%ROWTYPE;
  o commerce.orders%ROWTYPE;
BEGIN
  SELECT * INTO r FROM commerce.returns WHERE id = p_return;
  IF NOT FOUND THEN RETURN 'ended'; END IF;
  SELECT * INTO o FROM commerce.orders WHERE store_id = r.store_id AND id = r.order_id;
  IF o.copied_from IS NOT NULL THEN RETURN 'copied'; END IF;
  IF o.host_id IS NOT NULL THEN RETURN 'host'; END IF;
  IF o.vat_kind <> 'standard' THEN RETURN 'vat_kind'; END IF;
  IF o.restricted_at IS NOT NULL OR o.anonymised_at IS NOT NULL THEN RETURN 'restricted'; END IF;
  IF o.subscription_id IS NOT NULL OR EXISTS (
    SELECT 1 FROM commerce.order_lines ol WHERE ol.store_id = o.store_id AND ol.order_id = o.id AND ol.selling_plan_id IS NOT NULL
  ) THEN RETURN 'subscription'; END IF;
  IF EXISTS (SELECT 1 FROM commerce.standing_deliveries sd WHERE sd.store_id = o.store_id AND sd.order_id = o.id) THEN RETURN 'weekly_box'; END IF;
  IF EXISTS (SELECT 1 FROM commerce.bookings b WHERE b.store_id = o.store_id AND b.order_id = o.id) THEN RETURN 'booking'; END IF;
  IF NOT commerce.store_is_active(o.store_id) THEN RETURN 'store_closed'; END IF;
  IF NOT commerce.feature_on(o.store_id, 'shop') THEN RETURN 'shop_off'; END IF;
  IF EXISTS (SELECT 1 FROM commerce.return_settings rs WHERE rs.store_id = o.store_id AND NOT rs.exchanges) THEN RETURN 'off'; END IF;
  IF r.status IN ('closed', 'declined', 'cancelled') THEN RETURN 'ended'; END IF;
  IF r.status = 'requested' THEN RETURN 'requested'; END IF;
  IF r.refund_minor IS NOT NULL OR r.refunded_at IS NOT NULL OR (r.refund_claimed_at IS NOT NULL AND NOT p_claimed_ok) THEN RETURN 'refunded'; END IF;
  IF EXISTS (
    SELECT 1 FROM commerce.return_lines rl JOIN commerce.order_lines ol ON ol.store_id = rl.store_id AND ol.id = rl.order_line_id
     WHERE rl.return_id = r.id AND rl.decision = 'accept' AND (ol.delivery <> 'physical' OR ol.variant_id IS NULL)
  ) THEN RETURN 'not_goods'; END IF;
  IF EXISTS (SELECT 1 FROM commerce.order_edits e WHERE e.store_id = o.store_id AND e.order_id = o.id AND e.status = 'awaiting_payment') THEN
    RETURN 'edit_pending';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: exchange_refunds_of(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.exchange_refunds_of(p_exchange uuid) RETURNS TABLE(transfer_minor bigint, remainder_minor bigint)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce(sum(rf.amount_minor) FILTER (WHERE rf.kind = 'transfer'), 0)::bigint,
         coalesce(sum(rf.amount_minor) FILTER (WHERE rf.kind = 'money' AND rf.status <> 'failed'), 0)::bigint
    FROM commerce.return_exchanges e
    JOIN commerce.refunds rf ON rf.store_id = e.store_id AND rf.exchange_id = e.id
    JOIN commerce.payments p ON p.store_id = rf.store_id AND p.id = rf.payment_id AND p.order_id = e.order_id
   WHERE e.id = p_exchange
$$;


--
-- Name: exchange_transfers_paired(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.exchange_transfers_paired() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_refund uuid;
  v_n integer;
BEGIN
  IF TG_TABLE_NAME = 'refunds' THEN
    v_refund := NEW.id;
  ELSE
    v_refund := NEW.transfer_refund_id;
  END IF;
  IF v_refund IS NULL THEN RETURN NULL; END IF;
  SELECT count(*) INTO v_n
    FROM commerce.refunds rf
    JOIN commerce.return_exchanges e ON e.store_id = rf.store_id AND e.id = rf.exchange_id
    JOIN commerce.payments p ON p.store_id = rf.store_id AND p.transfer_refund_id = rf.id
   WHERE rf.id = v_refund AND rf.kind = 'transfer' AND p.provider = 'exchange' AND p.exchange_id = rf.exchange_id
     AND p.order_id = e.exchange_order_id AND p.amount_minor = rf.amount_minor;
  IF v_n <> 1 THEN
    RAISE EXCEPTION 'exchange.transfer_unpaired: a transfer and its exchange payment are written together, equal' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: experiment_events_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.experiment_events_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    RAISE EXCEPTION 'experiment_events.changed: an event is never changed' USING ERRCODE = 'restrict_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM commerce.experiments e WHERE e.id = NEW.experiment_id AND e.store_id = NEW.store_id AND e.status = 'running') THEN
    RAISE EXCEPTION 'experiment_events.closed: the test is not running' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM commerce.experiment_exposures x WHERE x.experiment_id = NEW.experiment_id AND x.visitor = NEW.visitor AND x.variant = NEW.variant) THEN
    RAISE EXCEPTION 'experiment_events.variant: an event belongs to the version the visitor was shown' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: experiment_exposures_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.experiment_exposures_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    RAISE EXCEPTION 'experiment_exposures.changed: what a visitor was shown is never changed' USING ERRCODE = 'restrict_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM commerce.experiments e WHERE e.id = NEW.experiment_id AND e.store_id = NEW.store_id AND e.status = 'running') THEN
    RAISE EXCEPTION 'experiment_exposures.closed: the test is not running' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: experiment_variants_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.experiment_variants_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_experiment uuid := CASE WHEN TG_OP = 'DELETE' THEN OLD.experiment_id ELSE NEW.experiment_id END;
  v_status text;
BEGIN
  SELECT e.status INTO v_status FROM commerce.experiments e WHERE e.id = v_experiment;
  IF v_status IS NULL THEN
    -- The test is being deleted with its store or by itself (cascade): nothing to protect.
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;
  IF v_status <> 'draft' THEN
    RAISE EXCEPTION 'experiment_variants.locked: the versions of a test that has started cannot be changed' USING ERRCODE = 'restrict_violation';
  END IF;
  IF TG_OP <> 'DELETE' AND NEW.page_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM commerce.pages p WHERE p.id = NEW.page_id AND p.store_id = NEW.store_id AND p.type = 'variant'
  ) THEN
    RAISE EXCEPTION 'experiment_variants.page: a variant is a page made for the test' USING ERRCODE = 'check_violation';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: experiments_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.experiments_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_count integer;
  v_sum numeric;
  v_running integer;
  v_page record;
  v_role text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'experiments.start: a test is made as a draft' USING ERRCODE = 'check_violation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM commerce.pages p WHERE p.id = NEW.target_page_id AND p.store_id = NEW.store_id AND p.type IN ('page', 'product_layout', 'header', 'footer')) THEN
      RAISE EXCEPTION 'experiments.target: only a page, a product layout, a header or a footer of the store can be tested' USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (SELECT 1 FROM commerce.page_roles r WHERE r.store_id = NEW.store_id AND r.page_id = NEW.target_page_id AND r.role = ANY (ARRAY['terms', 'privacy', 'returns_policy', 'shipping_policy', 'withdrawal_info', 'imprint', 'accessibility'])) THEN
      RAISE EXCEPTION 'experiments.target_legal: a legal page is never tested' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.id <> OLD.id OR NEW.store_id <> OLD.store_id THEN
    RAISE EXCEPTION 'experiments.moved: a test belongs to its store' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.status <> 'draft' AND (
    NEW.target_page_id <> OLD.target_page_id OR NEW.traffic_share <> OLD.traffic_share OR NEW.audience <> OLD.audience
    OR NEW.primary_goal <> OLD.primary_goal OR NEW.goal_params <> OLD.goal_params OR NEW.min_visitors <> OLD.min_visitors
    OR NEW.min_days <> OLD.min_days
    OR NEW.target_part IS DISTINCT FROM OLD.target_part OR NEW.target_part_kind IS DISTINCT FROM OLD.target_part_kind
  ) THEN
    -- A scheduled test goes back to draft to be changed; only the time of its start moves while it waits.
    IF NOT (OLD.status = 'scheduled' AND NEW.status = 'draft' AND NEW.target_page_id = OLD.target_page_id AND NEW.target_part IS NOT DISTINCT FROM OLD.target_part) THEN
      RAISE EXCEPTION 'experiments.locked: a test that has started cannot be changed' USING ERRCODE = 'restrict_violation';
    END IF;
  END IF;
  IF NEW.status = OLD.status THEN
    IF OLD.status IN ('applied', 'discarded') AND (NEW.name <> OLD.name OR NEW.hypothesis <> OLD.hypothesis OR NEW.planned_end IS DISTINCT FROM OLD.planned_end) THEN
      RAISE EXCEPTION 'experiments.locked: a finished test cannot be changed' USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF NOT ((OLD.status = 'draft' AND NEW.status IN ('scheduled', 'running', 'discarded'))
       OR (OLD.status = 'scheduled' AND NEW.status IN ('draft', 'running', 'discarded'))
       OR (OLD.status = 'running' AND NEW.status = 'stopped')
       OR (OLD.status = 'stopped' AND NEW.status IN ('applied', 'discarded'))) THEN
    RAISE EXCEPTION 'experiments.status: a test cannot go from % to %', OLD.status, NEW.status USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.status = 'scheduled' AND (NEW.scheduled_start IS NULL OR NEW.scheduled_start <= now()) THEN
    RAISE EXCEPTION 'experiments.schedule: choose a time in the future' USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.status IN ('scheduled', 'running') AND OLD.status = 'draft' OR (NEW.status = 'running' AND OLD.status = 'scheduled') THEN
    SELECT p.type, p.published_at, p.id INTO v_page FROM commerce.pages p WHERE p.id = NEW.target_page_id AND p.store_id = NEW.store_id;
    IF v_page.published_at IS NULL THEN
      RAISE EXCEPTION 'experiments.start: the page under test must be published' USING ERRCODE = 'check_violation';
    END IF;
    -- A page chosen for a place of its own: the working pages (the cart, the checkout, the order confirmation, My account, sign-in,
    -- wishlists, a subscription, weekly deliveries) can be tested by a part of them, never as a whole, since the shop's own component is on
    -- them; the front page and the All products page can be tested whole or by a part; the cookies page and the content pages (blog,
    -- search, 404, categories, tags) cannot be tested yet.
    IF v_page.type = 'page' THEN
      v_role := commerce.page_place(NEW.store_id, NEW.target_page_id);
      IF v_role = ANY (ARRAY['terms', 'privacy', 'returns_policy', 'shipping_policy', 'withdrawal_info', 'imprint', 'accessibility']) THEN
        RAISE EXCEPTION 'experiments.target_legal: a legal page is never tested' USING ERRCODE = 'check_violation';
      END IF;
      IF v_role IS NOT NULL AND v_role NOT IN ('front', 'products', 'cart', 'checkout', 'order', 'account', 'sign_in', 'wishlist', 'subscription', 'deliveries') THEN
        RAISE EXCEPTION 'experiments.start: the cookies page and the blog, search, 404, category and tag pages cannot be tested yet' USING ERRCODE = 'check_violation';
      END IF;
      IF v_role IN ('cart', 'checkout', 'order', 'account', 'sign_in', 'wishlist', 'subscription', 'deliveries') AND NEW.target_part IS NULL THEN
        RAISE EXCEPTION 'experiments.start: a working page can be tested by a part around its shop component, not as a whole' USING ERRCODE = 'check_violation';
      END IF;
    END IF;
    -- What every page shows is tested only where it is shown: the header or footer the store uses, a layout some product uses.
    IF v_page.type = 'header' AND NOT EXISTS (SELECT 1 FROM commerce.stores s WHERE s.id = NEW.store_id AND s.header_id = NEW.target_page_id) THEN
      RAISE EXCEPTION 'experiments.start: only the header the store uses can be tested' USING ERRCODE = 'check_violation';
    END IF;
    IF v_page.type = 'footer' AND NOT EXISTS (SELECT 1 FROM commerce.stores s WHERE s.id = NEW.store_id AND s.footer_id = NEW.target_page_id) THEN
      RAISE EXCEPTION 'experiments.start: only the footer the store uses can be tested' USING ERRCODE = 'check_violation';
    END IF;
    IF v_page.type = 'product_layout' AND NOT (
         EXISTS (SELECT 1 FROM commerce.stores s WHERE s.id = NEW.store_id AND s.product_layout_id = NEW.target_page_id)
         OR EXISTS (SELECT 1 FROM commerce.terms t WHERE t.store_id = NEW.store_id AND t.product_layout_id = NEW.target_page_id)
         OR EXISTS (SELECT 1 FROM commerce.products pr WHERE pr.store_id = NEW.store_id AND pr.product_layout_id = NEW.target_page_id)
       ) THEN
      RAISE EXCEPTION 'experiments.start: no product uses this layout yet, so nobody would see the test' USING ERRCODE = 'check_violation';
    END IF;
    SELECT count(*), COALESCE(sum(v.share), 0) INTO v_count, v_sum FROM commerce.experiment_variants v WHERE v.experiment_id = NEW.id;
    IF v_count < 2 OR v_count > 4 OR NOT EXISTS (SELECT 1 FROM commerce.experiment_variants v WHERE v.experiment_id = NEW.id AND v.key = 'a') THEN
      RAISE EXCEPTION 'experiments.variants: a test needs the original and one to three variants' USING ERRCODE = 'check_violation';
    END IF;
    IF abs(v_sum - 1) > 0.0005 THEN
      RAISE EXCEPTION 'experiments.split: the shares of the versions must add up to 100 %%' USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (
      SELECT 1 FROM commerce.experiment_variants v
      LEFT JOIN commerce.pages p ON p.id = v.page_id AND p.store_id = v.store_id
      WHERE v.experiment_id = NEW.id AND v.key <> 'a' AND (p.id IS NULL OR p.type <> 'variant' OR p.published_at IS NULL)
    ) THEN
      RAISE EXCEPTION 'experiments.variants: every variant must be published before the test starts' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF NEW.status = 'running' THEN
    SELECT count(*) INTO v_running FROM commerce.experiments e WHERE e.store_id = NEW.store_id AND e.status = 'running' AND e.id <> NEW.id;
    IF v_running >= 5 THEN
      RAISE EXCEPTION 'experiments.limit: a store can run five tests at a time' USING ERRCODE = 'check_violation';
    END IF;
    NEW.started_at := COALESCE(NEW.started_at, now());
    NEW.planned_end := COALESCE(NEW.planned_end, NEW.started_at + make_interval(days => NEW.min_days));
    NEW.schedule_problem := NULL;
  ELSIF NEW.status = 'stopped' THEN
    NEW.stopped_at := COALESCE(NEW.stopped_at, now());
    NEW.stop_reason := COALESCE(NEW.stop_reason, 'person');
  ELSIF NEW.status = 'applied' THEN
    IF NEW.applied_variant IS NULL OR NEW.applied_variant = 'a' OR NOT EXISTS (SELECT 1 FROM commerce.experiment_variants v WHERE v.experiment_id = NEW.id AND v.key = NEW.applied_variant) THEN
      RAISE EXCEPTION 'experiments.applied: choose one of the variants, not the original' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: experiments_no_delete(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.experiments_no_delete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF OLD.status NOT IN ('draft', 'discarded') AND EXISTS (SELECT 1 FROM commerce.stores s WHERE s.id = OLD.store_id) THEN
    RAISE EXCEPTION 'experiments.delete: a test that has run is kept' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN OLD;
END;
$$;


--
-- Name: expire_sandbox(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.expire_sandbox(p_sandbox uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_store uuid;
BEGIN
  UPDATE commerce.sandboxes SET state = 'expired', ended_at = now()
   WHERE id = p_sandbox AND state = 'open'
  RETURNING store_id INTO v_store;
  IF v_store IS NULL THEN
    RETURN false;
  END IF;
  UPDATE commerce.stores SET status = 'closed', status_reason = 'Sandbox ended'
   WHERE id = v_store AND status <> 'closed';
  RETURN true;
END;
$$;


--
-- Name: expire_withdrawal_requests(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.expire_withdrawal_requests() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_count integer;
BEGIN
  WITH gone AS (
    DELETE FROM commerce.withdrawal_requests w
     WHERE w.confirmed_at IS NULL AND w.status IN ('pending', 'expired') AND w.expires_at < now()
    RETURNING 1
  )
  SELECT count(*)::integer INTO v_count FROM gone;
  -- Hashed keys of guesses at the function are kept a day, only to limit them.
  DELETE FROM commerce.withdrawal_attempts WHERE at < now() - interval '1 day';
  RETURN v_count;
END;
$$;


--
-- Name: expired_document_files(uuid, date); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.expired_document_files(p_store uuid, p_before date) RETURNS TABLE(document_type text, document_id uuid, pdf_path text)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT 'invoice'::text, i.id, i.pdf_path FROM commerce.invoices i
   WHERE i.store_id = p_store AND i.issued_on < p_before AND i.anonymised_at IS NULL AND i.pdf_path IS NOT NULL
  UNION ALL
  SELECT 'credit_note'::text, c.id, c.pdf_path FROM commerce.credit_notes c
   WHERE c.store_id = p_store AND c.issued_on < p_before AND c.anonymised_at IS NULL AND c.pdf_path IS NOT NULL
$$;


--
-- Name: feature_needs(text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.feature_needs(p_feature text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT CASE p_feature
    WHEN 'shop' THEN '{}'::text[]
    WHEN 'countries' THEN '{}'::text[]
    WHEN 'languages' THEN '{}'::text[]
    WHEN 'sales' THEN '{}'::text[]
    WHEN 'referrals' THEN array['shop', 'bonus']
    ELSE array['shop']
  END
$$;


--
-- Name: feature_on(uuid, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.feature_on(p_store uuid, p_feature text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce((SELECT p_feature = ANY (s.features) AND commerce.feature_needs(p_feature) <@ s.features
                     FROM commerce.stores s WHERE s.id = p_store), false)
$$;


--
-- Name: features_effective(text[]); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.features_effective(p_features text[]) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce(array_agg(f ORDER BY f), '{}'::text[])
    FROM unnest(p_features) f
   WHERE commerce.feature_needs(f) <@ p_features
$$;


--
-- Name: forbid_change(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.forbid_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_TABLE_NAME = 'order_events' AND TG_OP = 'DELETE'
     AND coalesce(current_setting('kaizen.copied_order_delete', true), '') = to_jsonb(OLD) ->> 'order_id' THEN
    RETURN OLD;
  END IF;
  IF TG_TABLE_NAME = 'order_events' AND TG_OP = 'UPDATE' AND current_setting('commerce.anonymising', true) = 'on' THEN
    IF (to_jsonb(NEW) - 'data') IS NOT DISTINCT FROM (to_jsonb(OLD) - 'data')
       AND ((to_jsonb(NEW) -> 'data') - ARRAY['reason', 'note'] - (CASE WHEN to_jsonb(OLD) ->> 'type' = 'order.delivery_mismatch' THEN ARRAY['priced', 'address'] ELSE ARRAY[]::text[] END)) IS NOT DISTINCT FROM ((to_jsonb(OLD) -> 'data') - ARRAY['reason', 'note'] - (CASE WHEN to_jsonb(OLD) ->> 'type' = 'order.delivery_mismatch' THEN ARRAY['priced', 'address'] ELSE ARRAY[]::text[] END)) THEN
      RETURN NEW;
    END IF;
  END IF;
  RAISE EXCEPTION 'commerce.% is append-only; % is not allowed', TG_TABLE_NAME, TG_OP
    USING ERRCODE = 'restrict_violation';
END;
$$;


--
-- Name: forget_field_search(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.forget_field_search() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  DELETE FROM commerce.field_search WHERE store_id = OLD.store_id AND entity_id = OLD.id;
  RETURN OLD;
END;
$$;


--
-- Name: forget_field_values(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.forget_field_values() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  DELETE FROM commerce.field_values
   WHERE store_id = OLD.store_id
     AND entity = ANY (string_to_array(TG_ARGV[0], ','))
     AND entity_id = OLD.id;
  RETURN OLD;
END;
$$;


--
-- Name: freeze_starter(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.freeze_starter(p_starter uuid, p_by uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_starter commerce.store_starters%ROWTYPE;
  v_work commerce.stores%ROWTYPE;
  v_n integer;
  v_slug text;
  v_copy uuid;
BEGIN
  SELECT * INTO v_starter FROM commerce.store_starters WHERE id = p_starter FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown store template %', p_starter;
  END IF;
  IF v_starter.kind = 'demo' THEN
    RAISE EXCEPTION 'store_starters.demo_live: a demo store is live as it stands and is never frozen' USING ERRCODE = 'check_violation';
  END IF;
  IF v_starter.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'store_starters.archived: restore the store template before publishing it' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO v_work FROM commerce.stores WHERE id = v_starter.store_id;
  IF NOT v_work.starter OR v_work.status <> 'active' THEN
    RAISE EXCEPTION 'store_starters.not_open: the store template''s store is not open' USING ERRCODE = 'check_violation';
  END IF;

  SELECT count(*) + 1 INTO v_n FROM commerce.stores WHERE starter_copy_of = p_starter;
  LOOP
    v_slug := left(v_work.slug, 30) || '-v' || v_n;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM commerce.stores WHERE slug = v_slug);
    v_n := v_n + 1;
  END LOOP;

  v_copy := commerce.clone_store(v_starter.store_id, v_slug, v_work.name, p_by);
  UPDATE commerce.stores SET starter = true, starter_copy_of = p_starter, made_from_starter = NULL WHERE id = v_copy;
  UPDATE commerce.store_starters SET published_store_id = v_copy WHERE id = p_starter;
  IF v_starter.published_store_id IS NOT NULL THEN
    UPDATE commerce.stores
       SET status = 'closed', status_reason = 'A later publish of its store template replaced this copy.', status_changed_by = p_by
     WHERE id = v_starter.published_store_id AND status <> 'closed';
  END IF;
  RETURN v_copy;
END;
$$;


--
-- Name: fx_as_of(uuid, text, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.fx_as_of(p_store uuid, p_a text, p_b text) RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT commerce.store_day(p_store, coalesce(
    (SELECT s.rates_updated_at FROM commerce.stores s WHERE s.id = p_store),
    (SELECT max(c.updated_at) FROM commerce.store_currencies c WHERE c.store_id = p_store AND c.currency IN (p_a, p_b)),
    now()))
$$;


--
-- Name: fx_factor(uuid, text, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.fx_factor(p_store uuid, p_from text, p_to text) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_a numeric;
  v_b numeric;
BEGIN
  IF p_from = p_to THEN RETURN 1; END IF;
  v_a := CASE WHEN p_from = 'EUR' THEN 1 ELSE (SELECT c.rate FROM commerce.store_currencies c WHERE c.store_id = p_store AND c.currency = p_from) END;
  v_b := CASE WHEN p_to = 'EUR' THEN 1 ELSE (SELECT c.rate FROM commerce.store_currencies c WHERE c.store_id = p_store AND c.currency = p_to) END;
  IF v_a IS NULL OR v_b IS NULL OR v_a <= 0 OR v_b <= 0 THEN RETURN NULL; END IF;
  RETURN round(v_b * power(10::numeric, commerce.minor_unit_digits(p_to) - commerce.minor_unit_digits(p_from)) / v_a, 8);
END;
$$;


--
-- Name: gift_card_adjust(uuid, uuid, uuid, bigint, text, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.gift_card_adjust(p_store uuid, p_card uuid, p_account uuid, p_amount bigint, p_note text, p_key text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v commerce.gift_cards;
BEGIN
  v := commerce.gift_card_locked(p_store, p_card);
  IF v.status <> 'active' THEN
    RAISE EXCEPTION 'gift_cards.inactive: a deactivated gift card is not changed' USING ERRCODE = 'check_violation';
  END IF;
  RETURN commerce.gift_card_entry(p_store, p_card, 'adjust', p_amount, NULL, p_account, p_note, p_key);
END;
$$;


--
-- Name: gift_card_balance(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.gift_card_balance(p_card uuid) RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce(sum(e.amount_minor), 0)::bigint FROM commerce.gift_card_entries e WHERE e.card_id = p_card
$$;


--
-- Name: gift_card_entries_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.gift_card_entries_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'gift_card_entries.fixed: a gift card''s ledger is never changed' USING ERRCODE = 'check_violation';
  END IF;
  IF commerce.gift_card_balance(NEW.card_id) + NEW.amount_minor < 0 THEN
    RAISE EXCEPTION 'gift_card_entries.balance: a gift card''s balance cannot go below zero' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: gift_card_entry(uuid, uuid, text, bigint, uuid, uuid, text, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.gift_card_entry(p_store uuid, p_card uuid, p_kind text, p_amount bigint, p_order uuid, p_account uuid, p_note text, p_key text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_id uuid;
BEGIN
  SELECT e.id INTO v_id FROM commerce.gift_card_entries e WHERE e.store_id = p_store AND e.card_id = p_card AND e.idempotency_key = p_key;
  IF v_id IS NOT NULL THEN
    RETURN v_id;
  END IF;
  PERFORM set_config('kaizen.gift_card_ledger', 'on', true);
  INSERT INTO commerce.gift_card_entries (store_id, card_id, kind, amount_minor, order_id, account_id, note, idempotency_key)
  VALUES (p_store, p_card, p_kind, p_amount, p_order, p_account, coalesce(p_note, ''), p_key)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: gift_card_expire(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.gift_card_expire(p_store uuid, p_card uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v commerce.gift_cards;
  v_left bigint;
BEGIN
  v := commerce.gift_card_locked(p_store, p_card);
  IF v.expires_at IS NULL OR v.expires_at > now() THEN
    RETURN NULL;
  END IF;
  v_left := commerce.gift_card_balance(p_card);
  IF v_left <= 0 THEN
    RETURN NULL;
  END IF;
  RETURN commerce.gift_card_entry(p_store, p_card, 'expire', -v_left, NULL, NULL, '', 'expire:' || (SELECT count(*) FROM commerce.gift_card_entries e WHERE e.card_id = p_card AND e.kind = 'expire'));
END;
$$;


--
-- Name: gift_card_hold(uuid, uuid, uuid, text, boolean, bigint, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.gift_card_hold(p_store uuid, p_card uuid, p_order uuid, p_currency text, p_test boolean, p_amount bigint, p_key text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v commerce.gift_cards;
  v_done uuid;
BEGIN
  v := commerce.gift_card_locked(p_store, p_card);
  SELECT e.id INTO v_done FROM commerce.gift_card_entries e WHERE e.store_id = p_store AND e.card_id = p_card AND e.idempotency_key = p_key;
  IF v_done IS NOT NULL THEN
    RETURN v_done;
  END IF;
  IF p_amount <= 0 THEN
    RAISE EXCEPTION 'gift_cards.amount: hold a positive amount' USING ERRCODE = 'check_violation';
  END IF;
  IF v.status <> 'active' OR v.code_hash IS NULL THEN
    RAISE EXCEPTION 'gift_cards.inactive: this gift card cannot be used' USING ERRCODE = 'check_violation';
  END IF;
  IF v.expires_at IS NOT NULL AND v.expires_at <= now() THEN
    RAISE EXCEPTION 'gift_cards.expired: this gift card has expired' USING ERRCODE = 'check_violation';
  END IF;
  IF v.currency <> upper(p_currency) THEN
    RAISE EXCEPTION 'gift_cards.currency: this gift card is in another currency' USING ERRCODE = 'check_violation';
  END IF;
  IF v.test_mode IS DISTINCT FROM coalesce(p_test, false) THEN
    RAISE EXCEPTION 'gift_cards.mode: a test gift card is spent only in test mode, and a real one only for real' USING ERRCODE = 'check_violation';
  END IF;
  IF commerce.gift_card_balance(p_card) < p_amount THEN
    RAISE EXCEPTION 'gift_cards.balance: the gift card does not hold that much' USING ERRCODE = 'check_violation';
  END IF;
  RETURN commerce.gift_card_entry(p_store, p_card, 'hold', -p_amount, p_order, NULL, '', p_key);
END;
$$;


--
-- Name: gift_card_issue(uuid, text, text, bigint, uuid, uuid, integer, uuid, boolean, uuid, text, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.gift_card_issue(p_store uuid, p_source text, p_currency text, p_amount bigint, p_order uuid, p_line uuid, p_unit integer, p_account uuid, p_test boolean, p_customer uuid, p_recipient_email text, p_recipient_name text, p_message text, p_send_at timestamp with time zone, p_note text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_card uuid;
  v_months integer;
BEGIN
  IF p_source = 'order' THEN
    SELECT g.id INTO v_card FROM commerce.gift_cards g WHERE g.store_id = p_store AND g.order_line_id = p_line AND g.unit_index = p_unit;
    IF v_card IS NOT NULL THEN
      RETURN v_card;
    END IF;
  END IF;
  SELECT CASE WHEN s.store_id IS NULL THEN 36 ELSE s.expiry_months END INTO v_months
    FROM (SELECT 1) one LEFT JOIN commerce.gift_card_settings s ON s.store_id = p_store;
  PERFORM set_config('kaizen.gift_card_ledger', 'on', true);
  INSERT INTO commerce.gift_cards (store_id, currency, initial_minor, source, order_id, order_line_id, unit_index, issued_by, note,
                                   test_mode, customer_id, recipient_email, recipient_name, message, send_at, expires_at)
  VALUES (p_store, upper(p_currency), p_amount, p_source, p_order, p_line, p_unit, p_account, coalesce(p_note, ''),
          coalesce(p_test, false), p_customer, p_recipient_email, p_recipient_name, p_message, p_send_at,
          CASE WHEN v_months IS NULL THEN NULL ELSE now() + make_interval(months => v_months) END)
  RETURNING id INTO v_card;
  PERFORM commerce.gift_card_entry(p_store, v_card, 'issue', p_amount, p_order, p_account, '', 'issue');
  RETURN v_card;
END;
$$;


--
-- Name: gift_card_issue_moved(uuid, text, text, bigint, uuid, boolean, uuid, text, timestamp with time zone, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.gift_card_issue_moved(p_store uuid, p_moved_from text, p_currency text, p_amount bigint, p_account uuid, p_test boolean, p_customer uuid, p_recipient_email text, p_expires_at timestamp with time zone, p_note text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_card uuid;
BEGIN
  IF p_moved_from IS NULL OR btrim(p_moved_from) = '' THEN
    RAISE EXCEPTION 'gift_cards.moved: a moved card names the card it replaces' USING ERRCODE = 'check_violation';
  END IF;
  SELECT g.id INTO v_card FROM commerce.gift_cards g WHERE g.store_id = p_store AND g.moved_from = p_moved_from;
  IF v_card IS NOT NULL THEN
    RETURN v_card;
  END IF;
  PERFORM set_config('kaizen.gift_card_ledger', 'on', true);
  INSERT INTO commerce.gift_cards (store_id, currency, initial_minor, source, issued_by, note, test_mode, customer_id, recipient_email,
                                   expires_at, moved_from, moved_balance_minor)
  VALUES (p_store, upper(p_currency), p_amount, 'staff', p_account, left(coalesce(p_note, ''), 500), coalesce(p_test, false), p_customer,
          nullif(left(coalesce(p_recipient_email, ''), 254), ''), p_expires_at, p_moved_from, p_amount)
  RETURNING id INTO v_card;
  PERFORM commerce.gift_card_entry(p_store, v_card, 'issue', p_amount, NULL, p_account, '', 'issue');
  RETURN v_card;
END;
$$;


--
-- Name: gift_card_issue_refund(uuid, uuid[], uuid, boolean); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.gift_card_issue_refund(p_store uuid, p_refunds uuid[], p_account uuid, p_test boolean) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_first uuid := p_refunds[1];
  v_card uuid;
  v_order uuid;
  v_orders integer;
  v_amount bigint;
  v_rows integer;
  v_currency text;
  v_customer uuid;
  v_email text;
  v_months integer;
BEGIN
  IF v_first IS NULL THEN
    RAISE EXCEPTION 'gift_cards.refund: no refund to issue a card for' USING ERRCODE = 'check_violation';
  END IF;
  SELECT g.id INTO v_card FROM commerce.gift_cards g WHERE g.store_id = p_store AND g.refund_id = v_first;
  IF v_card IS NOT NULL THEN
    RETURN v_card;
  END IF;
  SELECT count(*), count(DISTINCT p.order_id), sum(r.amount_minor), min(p.order_id::text)::uuid
    INTO v_rows, v_orders, v_amount, v_order
    FROM commerce.refunds r JOIN commerce.payments p ON p.store_id = r.store_id AND p.id = r.payment_id
   WHERE r.store_id = p_store AND r.id = ANY (p_refunds) AND r.kind = 'store_credit' AND r.status = 'succeeded';
  IF v_rows <> cardinality(p_refunds) OR v_orders <> 1 OR coalesce(v_amount, 0) <= 0 THEN
    RAISE EXCEPTION 'gift_cards.refund: a card is issued only for succeeded store credit refunds of one order' USING ERRCODE = 'check_violation';
  END IF;
  SELECT o.currency, o.customer_id, o.email INTO v_currency, v_customer, v_email
    FROM commerce.orders o WHERE o.store_id = p_store AND o.id = v_order;
  SELECT CASE WHEN s.store_id IS NULL THEN 36 ELSE s.expiry_months END INTO v_months
    FROM (SELECT 1) one LEFT JOIN commerce.gift_card_settings s ON s.store_id = p_store;
  PERFORM set_config('kaizen.gift_card_ledger', 'on', true);
  INSERT INTO commerce.gift_cards (store_id, currency, initial_minor, source, order_id, refund_id, issued_by, note, test_mode, customer_id, recipient_email, expires_at)
  VALUES (p_store, upper(v_currency), v_amount, 'refund', v_order, v_first, p_account, '', coalesce(p_test, false), v_customer,
          nullif(left(coalesce(v_email, ''), 254), ''),
          CASE WHEN v_months IS NULL THEN NULL ELSE now() + make_interval(months => v_months) END)
  RETURNING id INTO v_card;
  PERFORM commerce.gift_card_entry(p_store, v_card, 'issue', v_amount, v_order, p_account, '', 'issue');
  RETURN v_card;
END;
$$;


--
-- Name: gift_cards; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.gift_cards (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    code_hash text,
    last4 text,
    currency character(3) NOT NULL,
    initial_minor bigint NOT NULL,
    source text NOT NULL,
    order_id uuid,
    order_line_id uuid,
    unit_index integer,
    issued_by uuid,
    note text DEFAULT ''::text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    test_mode boolean DEFAULT false NOT NULL,
    customer_id uuid,
    recipient_email text,
    recipient_name text,
    message text,
    send_at timestamp with time zone,
    sent_at timestamp with time zone,
    issued_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone,
    deactivated_at timestamp with time zone,
    deactivated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    refund_id uuid,
    moved_from text,
    moved_balance_minor bigint,
    CONSTRAINT gift_cards_code CHECK ((((code_hash IS NULL) = (last4 IS NULL)) AND ((last4 IS NULL) OR (last4 ~ '^[A-Z0-9]{4}$'::text)))),
    CONSTRAINT gift_cards_currency CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT gift_cards_initial CHECK ((initial_minor > 0)),
    CONSTRAINT gift_cards_note CHECK ((length(note) <= 500)),
    CONSTRAINT gift_cards_recipient CHECK ((((recipient_email IS NULL) OR (length(recipient_email) <= 254)) AND ((recipient_name IS NULL) OR (length(recipient_name) <= 80)) AND ((message IS NULL) OR (length(message) <= 500)))),
    CONSTRAINT gift_cards_source CHECK ((((source = 'order'::text) AND (order_id IS NOT NULL) AND (order_line_id IS NOT NULL) AND (unit_index >= 1)) OR ((source = 'staff'::text) AND (order_id IS NULL) AND (order_line_id IS NULL) AND (unit_index IS NULL) AND (issued_by IS NOT NULL)) OR ((source = 'refund'::text) AND (order_id IS NOT NULL) AND (refund_id IS NOT NULL) AND (order_line_id IS NULL) AND (unit_index IS NULL)))),
    CONSTRAINT gift_cards_status CHECK (((status = ANY (ARRAY['active'::text, 'deactivated'::text])) AND ((status = 'deactivated'::text) = (deactivated_at IS NOT NULL))))
);


--
-- Name: gift_card_locked(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.gift_card_locked(p_store uuid, p_card uuid) RETURNS commerce.gift_cards
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v commerce.gift_cards;
BEGIN
  SELECT * INTO v FROM commerce.gift_cards g WHERE g.store_id = p_store AND g.id = p_card FOR UPDATE;
  IF v.id IS NULL THEN
    RAISE EXCEPTION 'gift_cards.unknown: no such gift card in this store' USING ERRCODE = 'no_data_found';
  END IF;
  RETURN v;
END;
$$;


--
-- Name: gift_card_mark_sent(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.gift_card_mark_sent(p_store uuid, p_card uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v commerce.gift_cards;
BEGIN
  v := commerce.gift_card_locked(p_store, p_card);
  IF v.sent_at IS NOT NULL OR v.code_hash IS NULL THEN
    RETURN false;
  END IF;
  UPDATE commerce.gift_cards SET sent_at = now() WHERE id = p_card;
  RETURN true;
END;
$$;


--
-- Name: gift_card_moved_seen(uuid, uuid, bigint); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.gift_card_moved_seen(p_store uuid, p_card uuid, p_balance bigint) RETURNS void
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  UPDATE commerce.gift_cards SET moved_balance_minor = least(moved_balance_minor, greatest(p_balance, 0))
   WHERE store_id = p_store AND id = p_card AND moved_from IS NOT NULL;
$$;


--
-- Name: gift_card_new_code(uuid, uuid, text, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.gift_card_new_code(p_store uuid, p_card uuid, p_hash text, p_last4 text) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v commerce.gift_cards;
BEGIN
  IF p_hash IS NULL OR length(p_hash) < 32 OR p_last4 IS NULL OR length(p_last4) <> 4 THEN
    RAISE EXCEPTION 'gift_cards.code: a new code needs its hash and last four characters' USING ERRCODE = 'check_violation';
  END IF;
  v := commerce.gift_card_locked(p_store, p_card);
  -- What the answer means is for the caller to say: only a live, delivered card with money on it gets a new code.
  IF v.status <> 'active' THEN RETURN 'not_active'; END IF;
  IF v.sent_at IS NULL OR v.code_hash IS NULL THEN RETURN 'not_delivered'; END IF;
  IF v.expires_at IS NOT NULL AND v.expires_at <= now() THEN RETURN 'expired'; END IF;
  IF commerce.gift_card_balance(v.id) <= 0 THEN RETURN 'empty'; END IF;
  PERFORM set_config('kaizen.gift_card_new_code', v.id::text, true);
  UPDATE commerce.gift_cards SET code_hash = p_hash, last4 = p_last4 WHERE id = v.id;
  PERFORM set_config('kaizen.gift_card_new_code', '', true);
  RETURN 'ok';
END;
$$;


--
-- Name: gift_card_order_held(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.gift_card_order_held(p_card uuid, p_order uuid) RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce(-sum(e.amount_minor) FILTER (WHERE e.kind IN ('hold', 'release')), 0)::bigint
    FROM commerce.gift_card_entries e WHERE e.card_id = p_card AND e.order_id = p_order
$$;


--
-- Name: gift_card_refund(uuid, uuid, uuid, bigint, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.gift_card_refund(p_store uuid, p_card uuid, p_order uuid, p_amount bigint, p_key text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_done uuid;
  v_spent bigint;
  v_refunded bigint;
BEGIN
  PERFORM commerce.gift_card_locked(p_store, p_card);
  SELECT e.id INTO v_done FROM commerce.gift_card_entries e WHERE e.store_id = p_store AND e.card_id = p_card AND e.idempotency_key = p_key;
  IF v_done IS NOT NULL THEN
    RETURN v_done;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM commerce.gift_card_entries e WHERE e.card_id = p_card AND e.order_id = p_order AND e.kind = 'spend') THEN
    RAISE EXCEPTION 'gift_cards.not_spent: this order did not spend the gift card' USING ERRCODE = 'check_violation';
  END IF;
  v_spent := commerce.gift_card_order_held(p_card, p_order);
  SELECT coalesce(sum(e.amount_minor), 0) INTO v_refunded FROM commerce.gift_card_entries e WHERE e.card_id = p_card AND e.order_id = p_order AND e.kind = 'refund';
  IF p_amount <= 0 OR p_amount > v_spent - v_refunded THEN
    RAISE EXCEPTION 'gift_cards.refund: a refund goes back on the card up to what the order spent on it' USING ERRCODE = 'check_violation';
  END IF;
  RETURN commerce.gift_card_entry(p_store, p_card, 'refund', p_amount, p_order, NULL, '', p_key);
END;
$$;


--
-- Name: gift_card_release(uuid, uuid, uuid, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.gift_card_release(p_store uuid, p_card uuid, p_order uuid, p_key text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_held bigint;
BEGIN
  PERFORM commerce.gift_card_locked(p_store, p_card);
  IF EXISTS (SELECT 1 FROM commerce.gift_card_entries e WHERE e.card_id = p_card AND e.order_id = p_order AND e.kind = 'spend') THEN
    RAISE EXCEPTION 'gift_cards.spent: this order''s hold was spent; refund it instead' USING ERRCODE = 'check_violation';
  END IF;
  v_held := commerce.gift_card_order_held(p_card, p_order);
  IF v_held <= 0 THEN
    RETURN NULL;
  END IF;
  RETURN commerce.gift_card_entry(p_store, p_card, 'release', v_held, p_order, NULL, '', p_key);
END;
$$;


--
-- Name: gift_card_set_code(uuid, uuid, text, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.gift_card_set_code(p_store uuid, p_card uuid, p_hash text, p_last4 text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v commerce.gift_cards;
BEGIN
  v := commerce.gift_card_locked(p_store, p_card);
  IF v.sent_at IS NOT NULL THEN
    RETURN false;
  END IF;
  UPDATE commerce.gift_cards SET code_hash = p_hash, last4 = p_last4 WHERE id = p_card;
  RETURN true;
END;
$$;


--
-- Name: gift_card_spend(uuid, uuid, uuid, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.gift_card_spend(p_store uuid, p_card uuid, p_order uuid, p_key text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM commerce.gift_card_locked(p_store, p_card);
  IF commerce.gift_card_order_held(p_card, p_order) <= 0 THEN
    RAISE EXCEPTION 'gift_cards.nothing_held: this order holds nothing on the gift card' USING ERRCODE = 'check_violation';
  END IF;
  RETURN commerce.gift_card_entry(p_store, p_card, 'spend', 0, p_order, NULL, '', p_key);
END;
$$;


--
-- Name: gift_card_void(uuid, uuid, uuid, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.gift_card_void(p_store uuid, p_card uuid, p_account uuid, p_note text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v commerce.gift_cards;
  v_left bigint;
BEGIN
  v := commerce.gift_card_locked(p_store, p_card);
  IF v.status = 'deactivated' THEN
    RETURN NULL;
  END IF;
  UPDATE commerce.gift_cards SET status = 'deactivated', deactivated_at = now(), deactivated_by = p_account WHERE id = p_card;
  v_left := commerce.gift_card_balance(p_card);
  IF v_left <= 0 THEN
    RETURN NULL;
  END IF;
  RETURN commerce.gift_card_entry(p_store, p_card, 'void', -v_left, NULL, p_account, p_note, 'void');
END;
$$;


--
-- Name: gift_card_withdraw(uuid, uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.gift_card_withdraw(p_store uuid, p_card uuid, p_order uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v commerce.gift_cards;
  v_left bigint;
BEGIN
  v := commerce.gift_card_locked(p_store, p_card);
  IF v.order_id IS DISTINCT FROM p_order THEN
    RAISE EXCEPTION 'gift_card.order: this gift card was not bought with this order' USING ERRCODE = 'check_violation';
  END IF;
  IF v.status = 'deactivated' THEN
    RETURN NULL;
  END IF;
  v_left := commerce.gift_card_balance(p_card);
  IF v_left < v.initial_minor THEN
    RAISE EXCEPTION 'gift_card.spent: part of this gift card was spent' USING ERRCODE = 'check_violation';
  END IF;
  UPDATE commerce.gift_cards SET status = 'deactivated', deactivated_at = now() WHERE id = p_card;
  RETURN commerce.gift_card_entry(p_store, p_card, 'void', -v_left, p_order, NULL, 'Withdrawn', 'void');
END;
$$;


--
-- Name: gift_card_writer(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.gift_card_writer() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF coalesce(current_setting('kaizen.gift_card_ledger', true), '') <> 'on' THEN
    RAISE EXCEPTION 'gift_cards.writer: gift cards and their ledger are written only by the gift_card functions' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: gift_cards_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.gift_cards_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'gift_cards.kept: a gift card is never deleted (deactivate it)' USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW.store_id, NEW.currency, NEW.initial_minor, NEW.source, NEW.order_id, NEW.order_line_id, NEW.unit_index, NEW.refund_id, NEW.issued_by,
      NEW.issued_at, NEW.expires_at, NEW.test_mode, NEW.note, NEW.created_at)
     IS DISTINCT FROM
     (OLD.store_id, OLD.currency, OLD.initial_minor, OLD.source, OLD.order_id, OLD.order_line_id, OLD.unit_index, OLD.refund_id, OLD.issued_by,
      OLD.issued_at, OLD.expires_at, OLD.test_mode, OLD.note, OLD.created_at) THEN
    RAISE EXCEPTION 'gift_cards.fixed: a gift card''s amount, currency, source and dates stay as issued' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.code_hash IS NOT NULL AND OLD.sent_at IS NOT NULL AND (NEW.code_hash, NEW.last4) IS DISTINCT FROM (OLD.code_hash, OLD.last4)
     AND coalesce(current_setting('kaizen.gift_card_new_code', true), '') <> OLD.id::text THEN
    RAISE EXCEPTION 'gift_cards.code: a gift card''s code stays once it was delivered' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.code_hash IS NULL AND OLD.code_hash IS NOT NULL THEN
    RAISE EXCEPTION 'gift_cards.code: a gift card''s code is replaced, never taken away' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.sent_at IS NOT NULL AND NEW.code_hash IS NULL THEN
    RAISE EXCEPTION 'gift_cards.sent: a gift card is delivered with its code' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.status = 'deactivated' AND (NEW.status, NEW.deactivated_at, NEW.deactivated_by) IS DISTINCT FROM (OLD.status, OLD.deactivated_at, OLD.deactivated_by) THEN
    RAISE EXCEPTION 'gift_cards.deactivated: a deactivated gift card stays so' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.sent_at IS NOT NULL AND NEW.sent_at IS DISTINCT FROM OLD.sent_at THEN
    RAISE EXCEPTION 'gift_cards.sent: a gift card is sent once' USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW.customer_id IS DISTINCT FROM OLD.customer_id AND NEW.customer_id IS NOT NULL)
     OR (NEW.recipient_email IS DISTINCT FROM OLD.recipient_email AND NEW.recipient_email IS NOT NULL)
     OR (NEW.recipient_name IS DISTINCT FROM OLD.recipient_name AND NEW.recipient_name IS NOT NULL)
     OR (NEW.message IS DISTINCT FROM OLD.message AND NEW.message IS NOT NULL) THEN
    RAISE EXCEPTION 'gift_cards.person: who a gift card is for is kept as given, or cleared' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_audit_log(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.guard_audit_log() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF OLD.area IS NULL AND NEW.area IS NOT NULL
       AND NEW.id = OLD.id
       AND NEW.store_id IS NOT DISTINCT FROM OLD.store_id
       AND NEW.account_id IS NOT DISTINCT FROM OLD.account_id
       AND NEW.action = OLD.action
       AND NEW.details = OLD.details
       AND NEW.created_at = OLD.created_at
       AND NEW.target_type IS NOT DISTINCT FROM OLD.target_type
       AND NEW.target_id IS NOT DISTINCT FROM OLD.target_id
       AND NEW.changes IS NOT DISTINCT FROM OLD.changes THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'commerce.audit_log is append-only; % is not allowed', TG_OP USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.created_at < now() - interval '24 months' THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'commerce.audit_log is append-only for 24 months; % is not allowed', TG_OP USING ERRCODE = 'restrict_violation';
END;
$$;


--
-- Name: guard_document_change(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.guard_document_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_pdf text[] := ARRAY['pdf_path', 'pdf_sha256'];
  v_anonymise text[] := ARRAY['pdf_path', 'pdf_sha256', 'snapshot', 'anonymised_at', 'public_token'];
BEGIN
  IF TG_OP <> 'UPDATE' THEN
    RAISE EXCEPTION 'commerce.% is append-only; % is not allowed', TG_TABLE_NAME, TG_OP USING ERRCODE = 'restrict_violation';
  END IF;
  IF current_setting('commerce.anonymising', true) = 'on' THEN
    IF (to_jsonb(NEW) - v_anonymise) IS DISTINCT FROM (to_jsonb(OLD) - v_anonymise) THEN
      RAISE EXCEPTION 'commerce.% can only be anonymised, not otherwise changed', TG_TABLE_NAME USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.pdf_path IS NULL AND OLD.anonymised_at IS NULL AND NEW.pdf_path IS NOT NULL AND (to_jsonb(NEW) - v_pdf) = (to_jsonb(OLD) - v_pdf) THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'commerce.% is append-only; UPDATE is not allowed (only the PDF path, once)', TG_TABLE_NAME USING ERRCODE = 'restrict_violation';
END;
$$;


--
-- Name: guard_inventory_movements(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.guard_inventory_movements() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    RAISE EXCEPTION 'commerce.inventory_movements is append-only; % is not allowed', TG_OP USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.created_at < now() - interval '24 months' THEN
    IF EXISTS (SELECT 1 FROM commerce.inventory_movements n
                WHERE n.store_id = OLD.store_id AND n.variant_id = OLD.variant_id AND n.location_id = OLD.location_id AND n.id > OLD.id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'commerce.inventory_movements keeps the newest movement of a level, the baseline of the ledger; % is not allowed', TG_OP USING ERRCODE = 'restrict_violation';
  END IF;
  RAISE EXCEPTION 'commerce.inventory_movements is append-only for 24 months; % is not allowed', TG_OP USING ERRCODE = 'restrict_violation';
END;
$$;


--
-- Name: guard_order_terms(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.guard_order_terms() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_element jsonb;
BEGIN
  IF EXISTS (SELECT 1 FROM commerce.orders o WHERE o.store_id = NEW.store_id AND o.id = NEW.order_id AND o.copied_from IS NOT NULL) THEN
    RAISE EXCEPTION 'order_terms.copied: a copied order carries no record of accepted terms' USING ERRCODE = 'check_violation';
  END IF;
  -- Anything but a list is the check's to refuse (order_terms_snapshots).
  IF jsonb_typeof(NEW.snapshots) <> 'array' THEN
    RETURN NEW;
  END IF;
  FOR v_element IN SELECT e FROM jsonb_array_elements(NEW.snapshots) AS e LOOP
    IF NOT EXISTS (
      SELECT 1 FROM commerce.legal_snapshots s
       WHERE s.store_id = NEW.store_id
         AND s.id::text = v_element ->> 'snapshotId'
         AND s.role = v_element ->> 'role'
    ) THEN
      RAISE EXCEPTION 'order_terms.snapshot: every snapshot named must be one of the store''s, under its own role' USING ERRCODE = 'check_violation';
    END IF;
  END LOOP;
  RETURN NEW;
END;
$$;


--
-- Name: guard_price_history(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.guard_price_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'commerce.prices is append-only; DELETE is not allowed'
      USING ERRCODE = 'restrict_violation';
  END IF;

  -- Who wrote an open price (D335): the rule or the owner. Nothing about the price itself moves.
  IF OLD.valid_to IS NULL AND NEW.valid_to IS NULL
     AND NEW.store_id IS NOT DISTINCT FROM OLD.store_id
     AND NEW.variant_id IS NOT DISTINCT FROM OLD.variant_id
     AND NEW.market_code IS NOT DISTINCT FROM OLD.market_code
     AND NEW.currency IS NOT DISTINCT FROM OLD.currency
     AND NEW.amount_minor IS NOT DISTINCT FROM OLD.amount_minor
     AND NEW.valid_from IS NOT DISTINCT FROM OLD.valid_from THEN
    RETURN NEW;
  END IF;

  IF OLD.valid_to IS NOT NULL
     OR NEW.valid_to IS NULL
     OR NEW.store_id IS DISTINCT FROM OLD.store_id
     OR NEW.variant_id IS DISTINCT FROM OLD.variant_id
     OR NEW.market_code IS DISTINCT FROM OLD.market_code
     OR NEW.currency IS DISTINCT FROM OLD.currency
     OR NEW.amount_minor IS DISTINCT FROM OLD.amount_minor
     OR NEW.valid_from IS DISTINCT FROM OLD.valid_from
     OR NEW.derived IS DISTINCT FROM OLD.derived THEN
    RAISE EXCEPTION 'commerce.prices rows can only be closed, not changed'
      USING ERRCODE = 'restrict_violation';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: guard_recovery_code(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.guard_recovery_code() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.id <> OLD.id OR NEW.account_id <> OLD.account_id OR NEW.batch <> OLD.batch
     OR NEW.code_hash <> OLD.code_hash OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'recovery_codes.fixed: a recovery code only changes by being used or revoked' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.used_at IS NOT NULL AND NEW.used_at IS DISTINCT FROM OLD.used_at THEN
    RAISE EXCEPTION 'recovery_codes.single_use: a recovery code is used once' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at THEN
    RAISE EXCEPTION 'recovery_codes.revoked: a revoked recovery code stays revoked' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.revoked_at IS NOT NULL AND OLD.used_at IS NULL AND NEW.used_at IS NOT NULL THEN
    RAISE EXCEPTION 'recovery_codes.revoked: a revoked recovery code cannot be used' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_unsent_closures(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.guard_unsent_closures() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  RAISE EXCEPTION 'unsent_closure.append_only: commerce.unsent_closures is a record; % is not allowed', TG_OP USING ERRCODE = 'restrict_violation';
END;
$$;


--
-- Name: hold_booking(uuid, uuid, uuid, uuid, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.hold_booking(p_store_id uuid, p_product_id uuid, p_variant_id uuid, p_resource_id uuid, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_blocked_from timestamp with time zone, p_blocked_to timestamp with time zone, p_hold_until timestamp with time zone, p_order_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_capacity integer;
  v_taken integer;
  v_id uuid;
BEGIN
  SELECT capacity INTO v_capacity FROM commerce.booking_resources
   WHERE store_id = p_store_id AND id = p_resource_id AND active
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  v_taken := commerce.resource_peak(p_store_id, p_resource_id, p_blocked_from, p_blocked_to, NULL);
  IF v_taken >= v_capacity OR commerce.resource_blocked(p_store_id, p_resource_id, p_blocked_from, p_blocked_to) THEN
    RETURN NULL;
  END IF;
  INSERT INTO commerce.bookings (
    store_id, product_id, variant_id, resource_id, starts_at, ends_at, blocked_from, blocked_to,
    status, hold_expires_at, order_id
  ) VALUES (
    p_store_id, p_product_id, p_variant_id, p_resource_id, p_starts_at, p_ends_at, p_blocked_from, p_blocked_to,
    'held', p_hold_until, p_order_id
  )
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: home_market(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.home_market(p_store uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT m.code::text
    FROM commerce.markets m
    JOIN commerce.stores s ON s.id = m.store_id
   WHERE m.store_id = p_store AND m.active
   ORDER BY (m.code = s.country) DESC NULLS LAST, m.created_at, m.code
   LIMIT 1
$$;


--
-- Name: home_vat_required(text, text, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.home_vat_required(p_country text, p_currency text, p_home text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT p_country IS NOT NULL AND p_home IS NOT NULL AND p_currency <> p_home AND NOT (p_country = 'DK' AND p_currency = 'EUR')
$$;


--
-- Name: hosts_vat_follow(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.hosts_vat_follow() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT NEW.vat_registered AND OLD.vat_registered THEN
    UPDATE commerce.products SET vat_category = 'exempt', updated_at = now()
     WHERE store_id = NEW.store_id AND host_id = NEW.id AND vat_category <> 'exempt';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: house_customer_links_house(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.house_customer_links_house() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM commerce.stores s WHERE s.id = NEW.store_id AND s.house) THEN
    RAISE EXCEPTION 'house_customer_links.house: only Kaizena Flow''s own store links its customers to accounts and requests'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: house_members_sync(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.house_members_sync() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_store uuid := commerce.house_store();
BEGIN
  IF v_store IS NULL THEN
    RETURN NULL;
  END IF;
  IF NEW.platform_admin AND NEW.disabled_at IS NULL THEN
    INSERT INTO commerce.store_members (store_id, account_id, role)
    VALUES (v_store, NEW.id, 'owner')
    ON CONFLICT (store_id, account_id) DO UPDATE SET role = 'owner', disabled_at = NULL, expires_at = NULL, role_id = NULL, kind = 'staff'
      WHERE commerce.store_members.disabled_at IS NOT NULL OR commerce.store_members.role <> 'owner';
  ELSIF NEW.platform_role IS NOT NULL AND NEW.disabled_at IS NULL THEN
    -- A member: never the store's owner; the team page makes them an admin in their role's store role in the same transaction.
    UPDATE commerce.store_members SET disabled_at = now()
     WHERE store_id = v_store AND account_id = NEW.id AND disabled_at IS NULL AND role = 'owner';
  ELSIF TG_OP = 'UPDATE' THEN
    -- The last platform admin may stop being one: the store is then left without an owner until the next one (`keep_an_owner()`).
    UPDATE commerce.store_members SET disabled_at = now()
     WHERE store_id = v_store AND account_id = NEW.id AND disabled_at IS NULL;
  END IF;
  RETURN NULL;
END;
$$;


