CREATE FUNCTION commerce.initialise_store() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  INSERT INTO commerce.document_series (store_id, series, prefix, next_number) VALUES
    (NEW.id, 'invoice', 'F-', 1),
