--
-- Name: inventory_ledger_check(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.inventory_ledger_check(p_store uuid) RETURNS TABLE(variant_id uuid, location_id uuid, on_hand integer, moved bigint)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce(l.variant_id, m.variant_id), coalesce(l.location_id, m.location_id),
         coalesce(l.on_hand, 0), (coalesce(m.baseline, 0) + coalesce(m.total, 0))::bigint
    FROM (SELECT il.variant_id, il.location_id, il.on_hand
            FROM commerce.inventory_levels il WHERE il.store_id = p_store) l
    FULL JOIN (SELECT im.variant_id, im.location_id, sum(im.delta) AS total,
                      (array_agg(im.on_hand_after - im.delta ORDER BY im.id))[1] AS baseline
                 FROM commerce.inventory_movements im WHERE im.store_id = p_store
                GROUP BY im.variant_id, im.location_id) m
      ON m.variant_id = l.variant_id AND m.location_id = l.location_id
   WHERE coalesce(l.on_hand, 0) <> coalesce(m.baseline, 0) + coalesce(m.total, 0);
$$;


--
-- Name: inventory_levels_not_bundle(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.inventory_levels_not_bundle() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM commerce.product_variants v JOIN commerce.products p ON p.store_id = v.store_id AND p.id = v.product_id
     WHERE v.store_id = NEW.store_id AND v.id = NEW.variant_id AND p.kind = 'bundle'
  ) THEN
    RAISE EXCEPTION 'inventory_levels.bundle: a bundle holds no stock of its own; its components do' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: inventory_levels_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.inventory_levels_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_delivery text;
  v_policy text;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.on_hand = OLD.on_hand THEN RETURN NEW; END IF;
  SELECT v.delivery::text, v.stock_policy INTO v_delivery, v_policy
    FROM commerce.product_variants v WHERE v.store_id = NEW.store_id AND v.id = NEW.variant_id;
  -- A new level is for goods only. A level that was made while the variant was goods stays when it becomes a download or a service
  -- (nothing reads it any more) and may still be changed: the rule stops stock being made for what has none, not an old row.
  IF TG_OP = 'INSERT' AND v_delivery IS DISTINCT FROM 'physical' THEN
    RAISE EXCEPTION 'stock.not_goods: only goods that are shipped have a stock level' USING ERRCODE = 'check_violation';
  END IF;
  -- Below zero only by a variant that keeps selling on backorder; a rise is always allowed (a refund or a count on a variant
  -- switched back to "stop selling" while it was negative).
  IF NEW.on_hand < 0 AND v_policy <> 'continue' AND NOT (TG_OP = 'UPDATE' AND NEW.on_hand >= OLD.on_hand) THEN
    RAISE EXCEPTION 'stock.negative: a level goes below zero only for a variant that keeps selling on backorder' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: inventory_locations_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.inventory_locations_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF OLD.active AND NOT NEW.active THEN
    -- Two deactivations at once cannot both pass: the store's row is locked first (a lock that does not block references to it).
    PERFORM 1 FROM commerce.stores s WHERE s.id = NEW.store_id FOR NO KEY UPDATE;
    IF NOT EXISTS (SELECT 1 FROM commerce.inventory_locations o
                    WHERE o.store_id = NEW.store_id AND o.active AND o.id <> NEW.id) THEN
      RAISE EXCEPTION 'location.last_active: a store keeps at least one active stock location' USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (SELECT 1 FROM commerce.inventory_reservations r
                WHERE r.store_id = NEW.store_id AND r.location_id = NEW.id AND r.released_at IS NULL AND r.expires_at > now()) THEN
      RAISE EXCEPTION 'location.held: checkouts in progress hold stock at this location' USING ERRCODE = 'check_violation';
    END IF;
    NEW.deactivated_at := coalesce(NEW.deactivated_at, now());
  ELSIF NOT OLD.active AND NEW.active THEN
    NEW.deactivated_at := NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: inventory_locations_refresh_alerts(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.inventory_locations_refresh_alerts() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  BEGIN
    PERFORM commerce.refresh_stock_alert(l.store_id, l.variant_id)
      FROM commerce.inventory_levels l
     WHERE l.store_id = NEW.store_id AND l.location_id = NEW.id
       AND (EXISTS (SELECT 1 FROM commerce.product_variants v
                     WHERE v.store_id = l.store_id AND v.id = l.variant_id AND v.low_stock_threshold IS NOT NULL)
            OR EXISTS (SELECT 1 FROM commerce.stock_alerts a WHERE a.store_id = l.store_id AND a.variant_id = l.variant_id));
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'refreshing stock alerts after a location changed: % (%)', SQLERRM, SQLSTATE;
  END;
  RETURN NULL;
END;
$$;


--
-- Name: invoice_eligibility(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.invoice_eligibility(p_order uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  o commerce.orders%ROWTYPE;
  cfg commerce.invoice_settings%ROWTYPE;
  v_paid timestamptz;
  v_test boolean;
BEGIN
  SELECT * INTO o FROM commerce.orders WHERE id = p_order;
  IF NOT FOUND THEN RETURN 'not_paid'; END IF;
  IF o.copied_from IS NOT NULL THEN RETURN 'copied'; END IF;
  IF o.host_id IS NOT NULL THEN RETURN 'host'; END IF;
  SELECT min(e.created_at) INTO v_paid FROM commerce.order_events e
   WHERE e.store_id = o.store_id AND e.order_id = o.id AND e.type = 'order.paid';
  IF v_paid IS NULL THEN RETURN 'not_paid'; END IF;
  -- Paid in Stripe's test mode: a Stripe payment on a test account, or a venue payment made while the store was in test mode (`payments.test_mode`,
  -- frozen with the payment by a trigger, so a store that goes live later never gives a test order a number). A payment
  -- with no known account is treated as live, so a missing row can only produce an invoice, never lose one.
  SELECT EXISTS (
    SELECT 1 FROM commerce.payments p
     WHERE p.store_id = o.store_id AND p.order_id = o.id AND p.status NOT IN ('failed', 'cancelled')
       AND ((p.provider NOT IN ('venue', 'exchange', 'mollie', 'terms', 'gift_card') AND p.provider_account IS NOT NULL AND EXISTS (
              SELECT 1 FROM commerce.connected_accounts a WHERE a.store_id = o.store_id AND a.account_id = p.provider_account AND a.mode = 'test'))
         OR (p.provider IN ('venue', 'exchange', 'mollie', 'terms', 'gift_card') AND p.test_mode))
  ) INTO v_test;
  IF v_test THEN RETURN 'test_mode'; END IF;
  SELECT * INTO cfg FROM commerce.invoice_settings WHERE store_id = o.store_id;
  IF FOUND AND (NOT cfg.enabled OR (cfg.enabled_from IS NOT NULL AND v_paid < cfg.enabled_from)) THEN RETURN 'disabled'; END IF;
  IF o.total_minor = 0 THEN RETURN 'zero_total'; END IF;
  RETURN 'ok';
END;
$$;


--
-- Name: invoice_readiness(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.invoice_readiness(p_order uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  o commerce.orders%ROWTYPE;
  st commerce.stores%ROWTYPE;
  prof record;
  v_have boolean;
  v_vat bigint;
  v_home text;
BEGIN
  SELECT * INTO o FROM commerce.orders WHERE id = p_order;
  SELECT * INTO st FROM commerce.stores WHERE id = o.store_id;
  SELECT * INTO prof FROM commerce.store_tax_profile WHERE store_id = o.store_id;
  v_have := FOUND;
  IF commerce.nz(st.legal_name) IS NULL OR commerce.nz(st.postal_address) IS NULL OR commerce.nz(st.organisation_number) IS NULL
     OR commerce.nz(st.country::text) IS NULL
     OR (v_have AND prof.vat_registered AND commerce.nz(commerce.invoice_seller_vat(p_order)) IS NULL) THEN
    RETURN 'seller_details';
  END IF;
  IF NOT v_have THEN RETURN 'tax_profile_missing'; END IF;
  v_vat := CASE WHEN o.vat_kind = 'reverse_charge' THEN 0 ELSE o.tax_minor END;
  IF NOT prof.vat_registered AND v_vat > 0 THEN RETURN 'vat_charged_not_registered'; END IF;
  SELECT c.currency::text INTO v_home FROM commerce.countries c WHERE c.code = st.country;
  IF v_vat > 0 AND commerce.home_vat_required(st.country::text, o.currency::text, v_home)
     AND commerce.fx_factor(o.store_id, o.currency::text, v_home) IS NULL THEN
    RETURN 'no_exchange_rate';
  END IF;
  RETURN 'ready';
END;
$$;


--
-- Name: invoice_seller_vat(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.invoice_seller_vat(p_order uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_result text;
BEGIN
  SELECT CASE
      WHEN EXISTS (
        SELECT 1 FROM commerce.store_business_changes b
        WHERE b.store_id = o.store_id AND b.status = 'applied' AND b.applied_at > coalesce(o.placed_at, o.created_at))
      THEN (SELECT CASE WHEN tp.vat_registered THEN tp.vat_number END FROM commerce.store_tax_profile tp WHERE tp.store_id = o.store_id)
      ELSE coalesce(
        commerce.nz(o.vat_treatment ->> 'sellerVatNumber'),
        (SELECT CASE WHEN tp.vat_registered THEN tp.vat_number END FROM commerce.store_tax_profile tp WHERE tp.store_id = o.store_id))
    END
    INTO v_result FROM commerce.orders o WHERE o.id = p_order;
  RETURN v_result;
END;
$$;


--
-- Name: invoice_settings_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.invoice_settings_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NOT NEW.enabled THEN NEW.enabled_from := NULL; END IF;
    RETURN NEW;
  END IF;
  -- Switching on starts the count: invoices are issued from then on and never back-dated.
  IF NEW.enabled AND NOT OLD.enabled THEN NEW.enabled_from := now();
  ELSIF NOT NEW.enabled THEN NEW.enabled_from := NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: is_established_in(text, character); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.is_established_in(p_area text, p_code character) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce((
    SELECT CASE p_area WHEN 'eu' THEN m.eu WHEN 'eea' THEN m.eea ELSE false END
      FROM commerce.country_memberships m WHERE m.code = p_code
  ), false);
$$;


--
-- Name: is_eu_country(character); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.is_eu_country(p_code character) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce((SELECT in_eu FROM commerce.countries WHERE code = p_code), false);
$$;


--
-- Name: issue_credit_note(uuid, uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.issue_credit_note(p_store uuid, p_refund uuid, p_return uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_id uuid;
  v_order uuid;
BEGIN
  BEGIN
    v_id := commerce.make_credit_note(p_store, p_refund, p_return);
  EXCEPTION WHEN OTHERS THEN
    BEGIN
      IF p_refund IS NOT NULL THEN
        SELECT p.order_id INTO v_order FROM commerce.refunds r JOIN commerce.payments p ON p.store_id = r.store_id AND p.id = r.payment_id
         WHERE r.store_id = p_store AND r.id = p_refund;
      ELSE
        SELECT r.order_id INTO v_order FROM commerce.returns r WHERE r.store_id = p_store AND r.id = p_return;
      END IF;
      IF v_order IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM commerce.order_events e
         WHERE e.store_id = p_store AND e.order_id = v_order AND e.type = 'credit_note.failed'
           AND e.data ->> 'key' = coalesce(p_refund, p_return)::text AND e.created_at > now() - interval '1 hour'
      ) THEN
        INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
        VALUES (p_store, v_order, 'credit_note.failed', jsonb_build_object('key', coalesce(p_refund, p_return), 'error', left(SQLERRM, 300)), 'system');
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
    RETURN NULL;
  END;
  RETURN v_id;
END;
$$;


--
-- Name: issue_edit_documents(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.issue_edit_documents(p_store uuid, p_edit uuid) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_state text;
  v_order uuid;
BEGIN
  BEGIN
    v_state := commerce.make_edit_documents(p_store, p_edit);
  EXCEPTION WHEN OTHERS THEN
    BEGIN
      SELECT e.order_id INTO v_order FROM commerce.order_edits e WHERE e.store_id = p_store AND e.id = p_edit;
      UPDATE commerce.order_edits SET documents = 'waiting' WHERE store_id = p_store AND id = p_edit AND status = 'applied' AND documents = 'none';
      IF v_order IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM commerce.order_events x
         WHERE x.store_id = p_store AND x.order_id = v_order AND x.type = 'invoice.failed' AND x.data ->> 'edit' = p_edit::text AND x.created_at > now() - interval '1 hour'
      ) THEN
        INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
        VALUES (p_store, v_order, 'invoice.failed', jsonb_build_object('edit', p_edit, 'error', left(SQLERRM, 300)), 'system');
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
    RETURN 'waiting';
  END;
  RETURN v_state;
END;
$$;


--
-- Name: issue_missing_credit_notes(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.issue_missing_credit_notes(p_store uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  r record;
  v_n integer := 0;
BEGIN
  FOR r IN
    SELECT x.refund_id, x.return_id FROM (
      SELECT rf.id AS refund_id, NULL::uuid AS return_id, rf.created_at AS at
        FROM commerce.refunds rf
        JOIN commerce.payments p ON p.store_id = rf.store_id AND p.id = rf.payment_id
        JOIN commerce.invoices i ON i.store_id = rf.store_id AND i.order_id = p.order_id AND i.kind = 'order'
       WHERE rf.store_id = p_store AND rf.status = 'succeeded'
         AND NOT EXISTS (SELECT 1 FROM commerce.credit_notes c WHERE c.store_id = rf.store_id AND c.refund_id = rf.id)
         AND NOT EXISTS (SELECT 1 FROM commerce.order_events e WHERE e.store_id = rf.store_id AND e.order_id = p.order_id
                          AND e.type IN ('credit_note.short', 'credit_note.not_invoiced', 'credit_note.covered_by_edit', 'credit_note.covered_by_exchange') AND e.data ->> 'key' = rf.id::text)
      UNION ALL
      SELECT NULL::uuid, rt.id, coalesce(rt.refunded_at, rt.created_at)
        FROM commerce.returns rt
        JOIN commerce.invoices i ON i.store_id = rt.store_id AND i.order_id = rt.order_id AND i.kind = 'order'
       WHERE rt.store_id = p_store AND ((rt.refund_outside AND rt.refund_id IS NULL) OR rt.outcome = 'exchanged') AND coalesce(rt.refund_minor, 0) > 0
         AND NOT EXISTS (SELECT 1 FROM commerce.credit_notes c WHERE c.store_id = rt.store_id AND c.return_id = rt.id AND c.source IN ('return_outside', 'return_exchange'))
         AND NOT EXISTS (SELECT 1 FROM commerce.order_events e WHERE e.store_id = rt.store_id AND e.order_id = rt.order_id AND e.type = 'credit_note.short' AND e.data ->> 'key' = rt.id::text)
    ) x ORDER BY x.at, x.refund_id, x.return_id
  LOOP
    IF commerce.issue_credit_note(p_store, r.refund_id, r.return_id) IS NOT NULL THEN v_n := v_n + 1; END IF;
  END LOOP;
  RETURN v_n;
END;
$$;


--
-- Name: issue_order_gift_cards(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.issue_order_gift_cards(p_store uuid, p_order uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  o commerce.orders%ROWTYPE;
  v_line record;
  v_test boolean;
  v_zone text;
  v_n integer := 0;
BEGIN
  SELECT * INTO o FROM commerce.orders WHERE store_id = p_store AND id = p_order;
  IF NOT FOUND OR o.copied_from IS NOT NULL OR o.host_id IS NOT NULL OR o.status NOT IN ('paid', 'fulfilled') THEN
    RETURN 0;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM commerce.payments p WHERE p.store_id = p_store AND p.order_id = p_order AND p.status = 'captured') THEN
    RETURN 0;
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM commerce.payments p
      LEFT JOIN commerce.connected_accounts a ON a.store_id = p.store_id AND a.account_id = p.provider_account
     WHERE p.store_id = p_store AND p.order_id = p_order AND p.status = 'captured' AND (p.test_mode OR a.mode::text = 'test')
  ) INTO v_test;
  SELECT coalesce(s.time_zone, 'UTC') INTO v_zone FROM commerce.stores s WHERE s.id = p_store;

  FOR v_line IN
    SELECT ol.* FROM commerce.order_lines ol
      JOIN commerce.product_variants v ON v.store_id = ol.store_id AND v.id = ol.variant_id
      JOIN commerce.products pr ON pr.store_id = v.store_id AND pr.id = v.product_id
     WHERE ol.store_id = p_store AND ol.order_id = p_order AND pr.kind = 'gift_card' AND ol.delivery = 'digital' AND ol.unit_price_minor > 0
     ORDER BY ol.id
  LOOP
    FOR v_unit IN 1..v_line.quantity LOOP
      PERFORM commerce.gift_card_issue(
        p_store, 'order', o.currency, v_line.unit_price_minor,
        p_order, v_line.id, v_unit, NULL, v_test, o.customer_id,
        v_line.gift_card_to, v_line.gift_card_to_name, v_line.gift_card_message,
        CASE WHEN v_line.gift_card_send_on IS NULL THEN NULL
             ELSE greatest(now(), (v_line.gift_card_send_on + time '08:00') AT TIME ZONE v_zone) END,
        '');
      v_n := v_n + 1;
    END LOOP;
  END LOOP;
  RETURN v_n;
END;
$$;


--
-- Name: issue_order_invoice(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.issue_order_invoice(p_store uuid, p_order uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_id uuid;
BEGIN
  BEGIN
    v_id := commerce.make_order_invoice(p_store, p_order);
  EXCEPTION WHEN OTHERS THEN
    -- Everything the block wrote, the number it took included, is undone. The order waits and the job tries again; the error is
    -- written down at most once an hour so a failure that stays does not fill the order's history.
    BEGIN
      IF NOT EXISTS (
        SELECT 1 FROM commerce.order_events e
         WHERE e.store_id = p_store AND e.order_id = p_order AND e.type = 'invoice.failed' AND e.created_at > now() - interval '1 hour'
      ) THEN
        INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
        VALUES (p_store, p_order, 'invoice.failed', jsonb_build_object('error', left(SQLERRM, 300)), 'system');
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
    RETURN NULL;
  END;
  RETURN v_id;
END;
$$;


--
-- Name: issue_waiting_invoices(uuid, integer); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.issue_waiting_invoices(p_store uuid, p_limit integer DEFAULT 200) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  r record;
  v_n integer := 0;
BEGIN
  FOR r IN
    SELECT w.order_id FROM commerce.waiting_invoices(p_store) w WHERE w.reason = 'invoice_failed' LIMIT greatest(p_limit, 0)
  LOOP
    IF commerce.issue_order_invoice(p_store, r.order_id) IS NOT NULL THEN v_n := v_n + 1; END IF;
  END LOOP;
  FOR r IN
    SELECT e.id FROM commerce.order_edits e
     WHERE e.store_id = p_store AND e.status = 'applied' AND e.documents IN ('none', 'waiting')
     ORDER BY e.applied_at, e.order_id, e.seq
     LIMIT greatest(p_limit, 0)
  LOOP
    PERFORM commerce.issue_edit_documents(p_store, r.id);
  END LOOP;
  PERFORM commerce.issue_missing_credit_notes(p_store);
  RETURN v_n;
END;
$$;


--
-- Name: work_invoices; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.work_invoices (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    client_id uuid NOT NULL,
    assignment_id uuid,
    recurring_invoice_id uuid,
    recurring_period date,
    status text DEFAULT 'draft'::text NOT NULL,
    series text DEFAULT 'work_invoice'::text NOT NULL,
    number bigint,
    document_number text,
    issued_on date,
    due_on date,
    sent_at timestamp with time zone,
    paid_at timestamp with time zone,
    currency character(3) NOT NULL,
    locale text,
    payment_days integer,
    service_from date,
    service_to date,
    notes text,
    reference text,
    subtotal_minor bigint DEFAULT 0 NOT NULL,
    vat_minor bigint DEFAULT 0 NOT NULL,
    total_minor bigint DEFAULT 0 NOT NULL,
    vat_home_minor bigint,
    fx_rate numeric(18,8),
    seller jsonb,
    buyer jsonb,
    vat_notes jsonb DEFAULT '[]'::jsonb NOT NULL,
    public_token text,
    sent_to text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    imported boolean DEFAULT false NOT NULL,
    legacy_number text,
    CONSTRAINT work_invoices_amounts CHECK (((subtotal_minor >= 0) AND (vat_minor >= 0) AND (total_minor = (subtotal_minor + vat_minor)))),
    CONSTRAINT work_invoices_currency CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT work_invoices_fx CHECK (((fx_rate IS NULL) OR (fx_rate > (0)::numeric))),
    CONSTRAINT work_invoices_imported CHECK (((NOT imported) OR ((status <> 'draft'::text) AND (number IS NULL) AND (document_number IS NOT NULL)))),
    CONSTRAINT work_invoices_issued CHECK (((status = 'draft'::text) OR ((issued_on IS NOT NULL) AND (due_on IS NOT NULL) AND (sent_at IS NOT NULL) AND (seller IS NOT NULL) AND (buyer IS NOT NULL) AND (locale IS NOT NULL) AND (payment_days IS NOT NULL)))),
    CONSTRAINT work_invoices_legacy_number CHECK (((legacy_number IS NULL) OR (imported AND ((length(TRIM(BOTH FROM legacy_number)) >= 1) AND (length(TRIM(BOTH FROM legacy_number)) <= 60))))),
    CONSTRAINT work_invoices_number CHECK ((imported OR (((status = 'draft'::text) = (number IS NULL)) AND ((number IS NULL) = (document_number IS NULL))))),
    CONSTRAINT work_invoices_payment_days CHECK (((payment_days IS NULL) OR ((payment_days >= 1) AND (payment_days <= 90)))),
    CONSTRAINT work_invoices_recurring CHECK (((recurring_invoice_id IS NULL) = (recurring_period IS NULL))),
    CONSTRAINT work_invoices_series CHECK ((series = 'work_invoice'::text)),
    CONSTRAINT work_invoices_service CHECK (((service_from IS NULL) OR (service_to IS NULL) OR (service_from <= service_to))),
    CONSTRAINT work_invoices_status CHECK ((status = ANY (ARRAY['draft'::text, 'sent'::text, 'paid'::text, 'void'::text, 'lost'::text]))),
    CONSTRAINT work_invoices_texts CHECK (((length(COALESCE(notes, ''::text)) <= 5000) AND (length(COALESCE(reference, ''::text)) <= 200))),
    CONSTRAINT work_invoices_vat_notes CHECK ((jsonb_typeof(vat_notes) = 'array'::text))
);


--
-- Name: issue_work_invoice(uuid, uuid, uuid, date, bigint, numeric, boolean); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.issue_work_invoice(p_store uuid, p_invoice uuid, p_account uuid DEFAULT NULL::uuid, p_issued_on date DEFAULT NULL::date, p_expected_total_minor bigint DEFAULT NULL::bigint, p_fx_rate numeric DEFAULT NULL::numeric, p_allow_earlier_date boolean DEFAULT false) RETURNS commerce.work_invoices
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_inv commerce.work_invoices;
  v_problems text[];
  v_s record;
  v_c record;
  v_today date;
  v_issued date;
  v_prev date;
  v_number bigint;
  v_prefix text;
  v_days integer;
  v_sub bigint;
  v_vat bigint;
  v_locale text;
  v_home char(3);
  v_notes jsonb;
  v_from date;
  v_to date;
BEGIN
  -- A change of the business behind the store whose day has come takes effect before anything is numbered (D473).
  PERFORM commerce.apply_business_change(p_store);
  SELECT * INTO v_inv FROM commerce.work_invoices WHERE store_id = p_store AND id = p_invoice FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'work_invoice.not_found' USING ERRCODE = 'no_data_found';
  END IF;
  IF v_inv.status <> 'draft' THEN
    RAISE EXCEPTION 'work_invoice.not_draft: the invoice is already issued' USING ERRCODE = 'restrict_violation';
  END IF;
  v_problems := commerce.work_invoice_problems(p_store, p_invoice);
  IF cardinality(v_problems) > 0 THEN
    RAISE EXCEPTION 'work_invoice.not_ready: %', array_to_string(v_problems, ',') USING ERRCODE = 'check_violation';
  END IF;

  v_today := commerce.work_today(p_store);
  v_issued := coalesce(p_issued_on, v_today);
  IF v_issued > v_today THEN
    RAISE EXCEPTION 'work_invoice.date_in_future: an invoice cannot be issued for a later day' USING ERRCODE = 'check_violation';
  END IF;

  SELECT st.legal_name, st.organisation_number, st.postal_address, st.country, st.contact_email, st.locales[1] AS main_locale,
         coalesce(ws.vat_registered, true) AS registered, ws.vat_number, ws.bank_account, ws.bic, ws.payment_note,
         ws.invoice_footer, ws.late_payment_note, ws.default_payment_days, co.currency AS home_currency
    INTO v_s
    FROM commerce.stores st
    LEFT JOIN commerce.work_settings ws ON ws.store_id = st.id
    LEFT JOIN commerce.countries co ON co.code = st.country
   WHERE st.id = p_store;
  SELECT * INTO v_c FROM commerce.work_clients WHERE store_id = p_store AND id = v_inv.client_id;

  -- Takes the number; from here the series row is locked until this transaction ends.
  v_number := commerce.next_document_number(p_store, 'work_invoice');
  SELECT ds.prefix INTO v_prefix FROM commerce.document_series ds WHERE ds.store_id = p_store AND ds.series = 'work_invoice';
  SELECT max(i.issued_on) INTO v_prev FROM commerce.work_invoices i
   WHERE i.store_id = p_store AND i.number IS NOT NULL;
  IF v_prev IS NOT NULL AND v_issued < v_prev AND NOT p_allow_earlier_date THEN
    RAISE EXCEPTION 'work_invoice.date_before_previous: the previous invoice is dated %', v_prev USING ERRCODE = 'check_violation';
  END IF;

  -- Freeze the lines.
  UPDATE commerce.work_invoice_lines l
     SET vat_rate = x.rate, excl_minor = x.excl_minor, vat_minor = x.vat_minor,
         incl_minor = x.excl_minor + x.vat_minor, updated_at = now()
    FROM commerce.work_invoice_computed(p_store, p_invoice) x
   WHERE l.store_id = p_store AND l.id = x.line_id;
  SELECT sum(l.excl_minor), sum(l.vat_minor) INTO v_sub, v_vat
    FROM commerce.work_invoice_lines l WHERE l.store_id = p_store AND l.invoice_id = p_invoice;
  IF p_expected_total_minor IS NOT NULL AND p_expected_total_minor <> v_sub + v_vat THEN
    RAISE EXCEPTION 'work_invoice.total_changed: the total is now % (was %)', v_sub + v_vat, p_expected_total_minor
      USING ERRCODE = 'check_violation';
  END IF;

  -- VAT in the seller's own currency, when the invoice is in another.
  IF v_s.home_currency IS NOT NULL AND v_inv.currency <> v_s.home_currency THEN
    IF p_fx_rate IS NULL OR p_fx_rate <= 0 THEN
      RAISE EXCEPTION 'work_invoice.fx_rate_required: the invoice is in % and the seller''s currency is %', v_inv.currency, v_s.home_currency
        USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    p_fx_rate := NULL;
  END IF;

  IF v_s.registered THEN
    SELECT coalesce(jsonb_agg(DISTINCT l.vat_category ORDER BY l.vat_category), '[]'::jsonb) INTO v_notes
      FROM commerce.work_invoice_lines l
     WHERE l.store_id = p_store AND l.invoice_id = p_invoice AND l.vat_category <> 'standard';
  ELSE
    v_notes := '["not_registered"]'::jsonb;
  END IF;

  IF v_inv.service_from IS NULL AND v_inv.service_to IS NULL THEN
    SELECT min(e.work_date), max(e.work_date) INTO v_from, v_to
      FROM commerce.work_time_entries e
      JOIN commerce.work_invoice_lines l ON l.store_id = e.store_id AND l.id = e.invoice_line_id
     WHERE l.store_id = p_store AND l.invoice_id = p_invoice;
  ELSE
    v_from := v_inv.service_from;
    v_to := v_inv.service_to;
  END IF;

  v_days := coalesce(v_inv.payment_days, v_c.payment_days, v_s.default_payment_days, 14);
  v_locale := coalesce(v_inv.locale, v_c.locale, nullif(v_s.main_locale, ''), 'en');

  PERFORM set_config('commerce.work_issuing', p_invoice::text, true);
  UPDATE commerce.work_invoices SET
    status = 'sent',
    number = v_number,
    document_number = v_prefix || v_number::text,
    issued_on = v_issued,
    due_on = v_issued + v_days,
    sent_at = now(),
    payment_days = v_days,
    locale = v_locale,
    service_from = v_from,
    service_to = v_to,
    subtotal_minor = v_sub,
    vat_minor = v_vat,
    total_minor = v_sub + v_vat,
    vat_home_minor = CASE WHEN p_fx_rate IS NULL THEN NULL ELSE floor(v_vat * p_fx_rate + 0.5)::bigint END,
    fx_rate = p_fx_rate,
    vat_notes = v_notes,
    seller = jsonb_build_object(
      'legal_name', v_s.legal_name,
      'organisation_number', v_s.organisation_number,
      'vat_registered', v_s.registered,
      'vat_number', CASE WHEN v_s.registered THEN v_s.vat_number END,
      'address', v_s.postal_address,
      'country', v_s.country,
      'email', v_s.contact_email,
      'bank_account', v_s.bank_account,
      'bic', v_s.bic,
      'payment_note', v_s.payment_note,
      'invoice_footer', v_s.invoice_footer,
      'late_payment_note', v_s.late_payment_note),
    buyer = jsonb_build_object(
      'name', coalesce(nullif(trim(v_c.legal_name), ''), v_c.name),
      'client_name', v_c.name,
      'organisation_number', v_c.organisation_number,
      'vat_number', v_c.vat_number,
      'address', v_c.billing_address,
      'country', v_c.country,
      'email', v_c.billing_email,
      'contact_name', v_c.contact_name,
      'business', v_c.business,
      'vat_treatment', v_c.vat_treatment),
    updated_at = now()
  WHERE store_id = p_store AND id = p_invoice
  RETURNING * INTO v_inv;
  PERFORM set_config('commerce.work_issuing', '', true);

  PERFORM commerce.work_event(
    p_store, 'invoice', p_invoice, 'invoice.issued',
    jsonb_build_object('document_number', v_inv.document_number, 'total_minor', v_inv.total_minor,
                       'currency', v_inv.currency, 'client_id', v_inv.client_id),
    p_account);
  RETURN v_inv;
END;
$$;


--
-- Name: kaizen_life_accounts_fixed(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.kaizen_life_accounts_fixed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.account_id IS DISTINCT FROM OLD.account_id OR NEW.life_user_id IS DISTINCT FROM OLD.life_user_id THEN
    RAISE EXCEPTION 'kaizen_life_accounts.fixed: a link joins one account and one Kaizen Life user for good' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: kaizen_life_handoffs_fixed(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.kaizen_life_handoffs_fixed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.account_id IS DISTINCT FROM OLD.account_id OR NEW.direction IS DISTINCT FROM OLD.direction OR NEW.task IS DISTINCT FROM OLD.task THEN
    RAISE EXCEPTION 'kaizen_life_handoffs.fixed: a handoff is one task of one account, in one direction' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: keep_an_owner(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.keep_an_owner() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF (TG_OP = 'DELETE' OR NEW.role <> 'owner' OR NEW.disabled_at IS NOT NULL)
     AND OLD.role = 'owner' AND OLD.disabled_at IS NULL
     AND NOT EXISTS (SELECT 1 FROM commerce.stores s WHERE s.id = OLD.store_id AND s.house)
     AND NOT EXISTS (
       SELECT 1 FROM commerce.store_members
        WHERE store_id = OLD.store_id
          AND role = 'owner'
          AND disabled_at IS NULL
          AND account_id <> OLD.account_id
     ) THEN
    RAISE EXCEPTION 'the store must keep at least one active owner'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: kind_offered(uuid, text, boolean); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.kind_offered(p_store uuid, p_kind text, p_subscription_only boolean) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT CASE p_kind
           WHEN 'appointment' THEN commerce.feature_on(p_store, 'appointments')
           WHEN 'stay' THEN commerce.feature_on(p_store, 'bookings')
           WHEN 'rental' THEN commerce.feature_on(p_store, 'bookings')
           WHEN 'gift_card' THEN commerce.feature_on(p_store, 'gift_cards')
           ELSE true
         END
     AND (NOT p_subscription_only OR commerce.feature_on(p_store, 'subscriptions'))
$$;


--
-- Name: ledger_accounts_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.ledger_accounts_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF (NEW.store_id, NEW.book_id, NEW.number) IS DISTINCT FROM (OLD.store_id, OLD.book_id, OLD.number) THEN
    RAISE EXCEPTION 'ledger_accounts.fixed: an account keeps its book and number' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.kind <> OLD.kind AND EXISTS (SELECT 1 FROM commerce.ledger_lines l WHERE l.book_id = OLD.book_id AND l.account = OLD.number) THEN
    RAISE EXCEPTION 'ledger_accounts.kind: an account with postings keeps its kind' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: ledger_books_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.ledger_books_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'ledger_books.kept: a book is never deleted' USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW.store_id, NEW.country, NEW.currency, NEW.created_at) IS DISTINCT FROM (OLD.store_id, OLD.country, OLD.currency, OLD.created_at) THEN
    RAISE EXCEPTION 'ledger_books.fixed: a book keeps its store, country, currency and opening day' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.opened_on IS DISTINCT FROM OLD.opened_on THEN
    IF NEW.opened_on > OLD.opened_on OR OLD.closed_on IS NOT NULL OR NEW.locked_through IS NOT NULL THEN
      RAISE EXCEPTION 'ledger_books.fixed: a book keeps its store, country, currency and opening day' USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (SELECT 1 FROM commerce.ledger_books o WHERE o.store_id = NEW.store_id AND o.id <> NEW.id AND coalesce(o.closed_on, 'infinity'::date) >= NEW.opened_on) THEN
      RAISE EXCEPTION 'ledger_books.earlier: a book opens after the store''s earlier book closed' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF OLD.closed_on IS NOT NULL AND NEW.closed_on IS DISTINCT FROM OLD.closed_on THEN
    RAISE EXCEPTION 'ledger_books.closed: a book closes once' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.closed_on IS NOT NULL AND EXISTS (SELECT 1 FROM commerce.ledger_entries e WHERE e.book_id = NEW.id AND e.entry_date > NEW.closed_on) THEN
    RAISE EXCEPTION 'ledger_books.closed: a book closes after the last entry it holds' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: ledger_fixed(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.ledger_fixed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  RAISE EXCEPTION 'ledger.fixed: a posted entry is never changed or deleted (reverse it)' USING ERRCODE = 'check_violation';
END;
$$;


--
-- Name: ledger_post(uuid, text, date, text, text, text, jsonb, uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.ledger_post(p_book uuid, p_series text, p_date date, p_text text, p_source_kind text, p_source_id text, p_lines jsonb, p_by uuid, p_reverses uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  b commerce.ledger_books%ROWTYPE;
  o commerce.ledger_entries%ROWTYPE;
  v_id uuid;
  v_year integer := extract(year FROM p_date)::integer;
  v_number integer;
  v_count integer;
  v_zero integer;
  v_sum numeric;
BEGIN
  SELECT * INTO b FROM commerce.ledger_books WHERE id = p_book FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ledger.book: no such book' USING ERRCODE = 'check_violation';
  END IF;
  IF p_date < b.opened_on OR (b.closed_on IS NOT NULL AND p_date > b.closed_on) THEN
    RAISE EXCEPTION 'ledger.open: an entry is dated within its book''s days' USING ERRCODE = 'check_violation';
  END IF;
  IF b.locked_through IS NOT NULL AND p_date <= b.locked_through THEN
    RAISE EXCEPTION 'ledger.locked: the book is locked through %', b.locked_through USING ERRCODE = 'check_violation';
  END IF;
  IF p_source_kind IS NOT NULL THEN
    SELECT e.id INTO v_id FROM commerce.ledger_entries e
     WHERE e.book_id = p_book AND e.source_kind = p_source_kind AND e.source_id = p_source_id AND e.reverses IS NULL
       AND NOT EXISTS (SELECT 1 FROM commerce.ledger_entries r WHERE r.reverses = e.id)
     LIMIT 1;
    IF v_id IS NOT NULL THEN
      RETURN v_id;
    END IF;
  END IF;
  IF p_reverses IS NOT NULL THEN
    SELECT * INTO o FROM commerce.ledger_entries WHERE id = p_reverses;
    IF NOT FOUND OR o.book_id <> p_book THEN
      RAISE EXCEPTION 'ledger.reverses: an entry reverses one of its own book' USING ERRCODE = 'check_violation';
    END IF;
    IF o.reverses IS NOT NULL THEN
      RAISE EXCEPTION 'ledger.reverses: a reversal is not itself reversed' USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (SELECT 1 FROM commerce.ledger_entries r WHERE r.reverses = p_reverses) THEN
      RAISE EXCEPTION 'ledger.reversed: an entry is reversed once' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF jsonb_typeof(p_lines) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'ledger.lines: an entry''s lines are a list' USING ERRCODE = 'check_violation';
  END IF;
  SELECT count(*), count(*) FILTER (WHERE coalesce((l->>'amount')::numeric, 0) = 0), coalesce(sum((l->>'amount')::numeric), 0)
    INTO v_count, v_zero, v_sum
    FROM jsonb_array_elements(p_lines) AS l;
  IF v_count < 2 THEN
    RAISE EXCEPTION 'ledger.lines: an entry has two lines or more' USING ERRCODE = 'check_violation';
  END IF;
  IF v_zero > 0 THEN
    RAISE EXCEPTION 'ledger.zero: no line is zero' USING ERRCODE = 'check_violation';
  END IF;
  IF v_sum <> 0 THEN
    RAISE EXCEPTION 'ledger.balance: an entry''s lines sum to zero' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_lines) AS l
     WHERE NOT EXISTS (SELECT 1 FROM commerce.ledger_accounts a WHERE a.book_id = p_book AND a.number = (l->>'account')::integer AND a.active)
  ) THEN
    RAISE EXCEPTION 'ledger.account: every line is on an active account of the book' USING ERRCODE = 'check_violation';
  END IF;

  PERFORM set_config('kaizen.ledger_posting', 'on', true);
  INSERT INTO commerce.ledger_counters (store_id, book_id, series, year, last)
  VALUES (b.store_id, p_book, p_series, v_year, 1)
  ON CONFLICT (book_id, series, year) DO UPDATE SET last = commerce.ledger_counters.last + 1
  RETURNING last INTO v_number;
  INSERT INTO commerce.ledger_entries (store_id, book_id, series, year, number, entry_date, text, source_kind, source_id, reverses, posted_by)
  VALUES (b.store_id, p_book, p_series, v_year, v_number, p_date, p_text, p_source_kind, p_source_id, p_reverses, p_by)
  RETURNING id INTO v_id;
  INSERT INTO commerce.ledger_lines (entry_id, store_id, book_id, line, account, amount_minor, vat_code, text)
  SELECT v_id, b.store_id, p_book, l.n::integer, (l.v->>'account')::integer, (l.v->>'amount')::bigint, nullif(l.v->>'vat_code', ''), nullif(btrim(l.v->>'text'), '')
    FROM jsonb_array_elements(p_lines) WITH ORDINALITY AS l(v, n);
  PERFORM set_config('kaizen.ledger_posting', '', true);
  RETURN v_id;
END;
$$;


--
-- Name: ledger_reverse(uuid, date, text, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.ledger_reverse(p_entry uuid, p_date date, p_text text, p_by uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  o commerce.ledger_entries%ROWTYPE;
  v_lines jsonb;
BEGIN
  SELECT * INTO o FROM commerce.ledger_entries WHERE id = p_entry;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ledger.reverses: no such entry' USING ERRCODE = 'check_violation';
  END IF;
  SELECT jsonb_agg(jsonb_build_object('account', l.account, 'amount', -l.amount_minor, 'vat_code', l.vat_code, 'text', l.text) ORDER BY l.line)
    INTO v_lines
    FROM commerce.ledger_lines l WHERE l.entry_id = p_entry;
  RETURN commerce.ledger_post(o.book_id, o.series, coalesce(p_date, o.entry_date), p_text, NULL, NULL, v_lines, p_by, p_entry);
END;
$$;


