-- Name: ledger_voucher_fixed(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.ledger_voucher_fixed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  RAISE EXCEPTION 'ledger.voucher_fixed: a voucher of the books is never changed or deleted' USING ERRCODE = 'check_violation';
END;
