END;
$$;


--
-- Name: line_price(uuid, uuid, uuid, character, bigint, integer); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.line_price(p_store uuid, p_customer uuid, p_variant uuid, p_market character, p_base bigint, p_quantity integer) RETURNS TABLE(amount_minor bigint, list_id uuid, break_from integer)
    LANGUAGE sql STABLE ROWS 1
    SET search_path TO ''
    AS $$
  WITH shop AS (
    SELECT o.amount, o.from_quantity
    FROM (
      SELECT CASE WHEN b.percent IS NOT NULL THEN (p_base * (100 - b.percent) + 50) / 100 ELSE (b.amounts ->> p_market)::bigint END AS amount,
             b.from_quantity
      FROM commerce.product_variants v
      JOIN commerce.price_breaks b
        ON b.store_id = v.store_id AND b.product_id = v.product_id AND (b.variant_id IS NULL OR b.variant_id = v.id)
      WHERE v.store_id = p_store AND v.id = p_variant AND b.from_quantity <= p_quantity
    ) o
    WHERE p_base IS NOT NULL AND o.amount IS NOT NULL AND o.amount < p_base
    ORDER BY o.amount, o.from_quantity
    LIMIT 1
  ),
  listed AS (
    SELECT bp.amount_minor, bp.list_id, NULL::integer AS from_quantity
      FROM commerce.buyer_price(p_store, p_customer, p_variant, p_market, p_base) AS bp
    UNION ALL
    SELECT CASE WHEN lb.percent IS NOT NULL THEN (p_base * (100 - lb.percent) + 50) / 100 ELSE (lb.amounts ->> m.currency)::bigint END,
           lb.list_id, lb.from_quantity
      FROM commerce.buyer_lists(p_store, p_customer) AS mine(id)
      JOIN commerce.price_list_breaks lb ON lb.store_id = p_store AND lb.list_id = mine.id AND lb.variant_id = p_variant
      JOIN commerce.markets m ON m.store_id = p_store AND m.code = p_market
     WHERE p_customer IS NOT NULL AND p_base IS NOT NULL AND lb.from_quantity <= p_quantity
  ),
  best_list AS (
    SELECT l.amount_minor, l.list_id, l.from_quantity
      FROM listed l
     WHERE l.amount_minor IS NOT NULL AND l.amount_minor < p_base
     ORDER BY l.amount_minor, l.from_quantity NULLS FIRST, l.list_id
     LIMIT 1
  )
  SELECT x.amount_minor, x.list_id, x.break_from
  FROM (
    -- A list's price wins only where it is lower than the shop's own price at this quantity.
    SELECT l.amount_minor, l.list_id, l.from_quantity AS break_from
      FROM best_list l
     WHERE l.amount_minor < coalesce((SELECT s.amount FROM shop s), p_base)
    UNION ALL
    SELECT s.amount, NULL::uuid, s.from_quantity FROM shop s
  ) x
  ORDER BY x.amount_minor, x.list_id NULLS LAST
  LIMIT 1
$$;


--
-- Name: line_shipped(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.line_shipped(p_order_line uuid) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT CASE
           WHEN ol.delivery <> 'physical' OR ol.variant_id IS NULL THEN 0
           WHEN EXISTS (
             SELECT 1 FROM commerce.shipments s
              WHERE s.store_id = ol.store_id AND s.order_id = ol.order_id AND s.legacy AND s.undone_at IS NULL
           ) THEN ol.quantity
           ELSE least(ol.quantity, coalesce((
             SELECT sum(sl.quantity) FROM commerce.shipment_lines sl
               JOIN commerce.shipments s ON s.store_id = sl.store_id AND s.id = sl.shipment_id
              WHERE sl.order_line_id = ol.id AND s.undone_at IS NULL
           ), 0))::integer
         END
    FROM commerce.order_lines ol WHERE ol.id = p_order_line
$$;


--
-- Name: line_to_send(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.line_to_send(p_order_line uuid) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT CASE
           WHEN ol.delivery <> 'physical' OR ol.variant_id IS NULL THEN 0
           ELSE greatest(0, ol.quantity - commerce.line_shipped(ol.id) - commerce.withdrawn_quantity(ol.id) - commerce.closed_quantity(ol.id))
         END
    FROM commerce.order_lines ol WHERE ol.id = p_order_line
$$;


--
-- Name: line_unregistered(uuid, text, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.line_unregistered(p_store uuid, p_market text, p_variant uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM commerce.product_variants v
      CROSS JOIN LATERAL commerce.registration_blocks(p_store, p_market, v.product_id) b
     WHERE v.store_id = p_store AND v.id = p_variant
  ) OR EXISTS (
    SELECT 1
      FROM commerce.bundle_components bc
      JOIN commerce.product_variants cv ON cv.store_id = bc.store_id AND cv.id = bc.component_variant_id
      CROSS JOIN LATERAL commerce.registration_blocks(p_store, p_market, cv.product_id) b
     WHERE bc.store_id = p_store AND bc.bundle_variant_id = p_variant
  )
$$;


--
-- Name: local_delivery_areas_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.local_delivery_areas_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_place record;
  v_problem text;
BEGIN
  IF TG_OP = 'UPDATE' AND (NEW.store_id <> OLD.store_id OR NEW.market_code <> OLD.market_code OR NEW.currency <> OLD.currency) THEN
    RAISE EXCEPTION 'local_delivery_areas.market_fixed: an area stays in its country and currency' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.kind = 'postal' THEN
    v_problem := commerce.postal_patterns_problem(NEW.patterns);
    IF v_problem IS NOT NULL THEN
      RAISE EXCEPTION '%: the area''s postal codes are not a list of codes and prefixes (at most 10 characters each, 3,000 in all, none twice)', v_problem
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NEW.location_id IS NOT NULL THEN
    SELECT l.country, l.latitude FROM commerce.store_locations l WHERE l.store_id = NEW.store_id AND l.id = NEW.location_id INTO v_place;
    IF v_place.country <> NEW.market_code THEN
      RAISE EXCEPTION 'local_delivery_areas.place_country: the place is in %, not in the country %', v_place.country, NEW.market_code USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.kind = 'radius' AND NEW.active AND v_place.latitude IS NULL THEN
      RAISE EXCEPTION 'local_delivery_areas.no_position: a radius is measured from the place, which has no position yet' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF TG_OP = 'INSERT' OR NEW.location_id IS DISTINCT FROM OLD.location_id THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('local_delivery_areas:' || NEW.store_id::text, 0));
    IF TG_OP = 'INSERT' AND (SELECT count(*) FROM commerce.local_delivery_areas a WHERE a.store_id = NEW.store_id) >= 30 THEN
      RAISE EXCEPTION 'local_delivery_areas.limit: a store has at most 30 local delivery areas' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.location_id IS NOT NULL
       AND (SELECT count(*) FROM commerce.local_delivery_areas a WHERE a.store_id = NEW.store_id AND a.location_id = NEW.location_id AND a.id <> NEW.id) >= 10 THEN
      RAISE EXCEPTION 'local_delivery_areas.place_limit: a place has at most 10 local delivery areas' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: look_versions_fixed(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.look_versions_fixed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  -- Only an account deleted since is let go of (its foreign key sets it to null); the look as kept never changes.
  IF NEW.id <> OLD.id OR NEW.store_id <> OLD.store_id OR NEW.kind <> OLD.kind OR NEW.theme <> OLD.theme OR NEW.created_at <> OLD.created_at
     OR (NEW.created_by IS DISTINCT FROM OLD.created_by AND NEW.created_by IS NOT NULL) THEN
    RAISE EXCEPTION 'look_versions.fixed: a version of the look stays as it was kept' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: main_currency(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.main_currency(p_store uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce(
    (SELECT m.currency::text FROM commerce.markets m JOIN commerce.stores s ON s.id = m.store_id
      WHERE m.store_id = p_store AND m.active
      ORDER BY (m.code = s.country) DESC NULLS LAST, m.created_at, m.code LIMIT 1),
    'EUR')
$$;


--
-- Name: make_credit_note(uuid, uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.make_credit_note(p_store uuid, p_refund uuid, p_return uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_refund commerce.refunds%ROWTYPE;
  v_ret commerce.returns%ROWTYPE;
  v_have_ret boolean := false;
  v_order commerce.orders%ROWTYPE;
  v_order_id uuid;
  v_inv commerce.invoices%ROWTYPE;
  v_source text;
  v_key uuid;
  v_amount bigint;
  v_working jsonb := NULL;
  v_return_number text := NULL;
  v_id uuid;
  v_n integer;
  v_k integer;
  v_rate numeric[];
  v_basis text[];
  v_net_left bigint[];
  v_vat_left bigint[];
  v_gross_left bigint[];
  v_room bigint;
  v_target bigint;
  v_short bigint;
  v_sums bigint[];
  v_clamp bigint[];
  v_final bigint[];
  v_head bigint[];
  v_inw bigint[];
  v_weights bigint[];
  v_shares bigint[];
  v_d bigint;
  v_rows jsonb := '[]'::jsonb;
  v_used boolean := false;
  v_ok boolean;
  v_w jsonb;
  v_line jsonb;
  v_ship jsonb;
  v_vat bigint[];
  v_buckets jsonb := '[]'::jsonb;
  v_net bigint := 0;
  v_vat_sum bigint := 0;
  v_gross bigint := 0;
  v_before bigint;
  v_number bigint;
  v_prefix text;
  v_docno text;
  v_today date;
  v_notes jsonb;
  v_vh jsonb;
  v_vm jsonb;
  v_vat_home jsonb := NULL;
  v_vat_main jsonb := NULL;
  v_snap jsonb;
  v_event_key text;
  v_is_return boolean;
  v_fx numeric;
  v_pool jsonb;
  v_pool_total bigint;
BEGIN
  -- A change of the business behind the store whose day has come takes effect before anything is numbered (D473).
  PERFORM commerce.apply_business_change(p_store);
  IF p_refund IS NOT NULL THEN
    SELECT * INTO v_refund FROM commerce.refunds WHERE store_id = p_store AND id = p_refund;
    IF NOT FOUND OR v_refund.status <> 'succeeded' THEN RETURN NULL; END IF;
    SELECT p.order_id INTO v_order_id FROM commerce.payments p WHERE p.store_id = p_store AND p.id = v_refund.payment_id;
    SELECT * INTO v_ret FROM commerce.returns WHERE store_id = p_store AND refund_id = p_refund;
    v_have_ret := FOUND;
    v_source := 'refund';
    v_key := p_refund;
    v_amount := v_refund.amount_minor;
    SELECT c.id INTO v_id FROM commerce.credit_notes c WHERE c.store_id = p_store AND c.refund_id = p_refund;
  ELSE
    SELECT * INTO v_ret FROM commerce.returns WHERE store_id = p_store AND id = p_return;
    -- Exchanges (D239): an exchanged return is credited in full by a note of its own (its refunds get none).
    IF NOT FOUND OR coalesce(v_ret.refund_minor, 0) <= 0
       OR NOT (v_ret.outcome = 'exchanged' OR (v_ret.refund_outside AND v_ret.refund_id IS NULL)) THEN RETURN NULL; END IF;
    v_have_ret := true;
    v_order_id := v_ret.order_id;
    v_source := CASE WHEN v_ret.outcome = 'exchanged' THEN 'return_exchange' ELSE 'return_outside' END;
    v_key := p_return;
    v_amount := v_ret.refund_minor;
    SELECT c.id INTO v_id FROM commerce.credit_notes c WHERE c.store_id = p_store AND c.return_id = p_return AND c.source = v_source;
  END IF;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;
  IF v_have_ret THEN
    v_working := v_ret.refund_working;
    v_return_number := v_ret.number;
  END IF;
  v_is_return := v_have_ret;
  v_event_key := v_key::text;
  IF v_amount IS NULL OR v_amount <= 0 THEN RETURN NULL; END IF;

  SELECT * INTO v_order FROM commerce.orders WHERE store_id = p_store AND id = v_order_id;
  IF NOT FOUND OR v_order.copied_from IS NOT NULL OR v_order.host_id IS NOT NULL THEN RETURN NULL; END IF;
  -- One at a time per order: the order's own invoice is locked (a change's documents lock it too), so two refunds that succeed together cannot both take
  -- what is left.
  SELECT * INTO v_inv FROM commerce.invoices WHERE store_id = p_store AND order_id = v_order_id AND kind = 'order' FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF p_refund IS NOT NULL THEN
    SELECT c.id INTO v_id FROM commerce.credit_notes c WHERE c.store_id = p_store AND c.refund_id = p_refund;
  ELSE
    SELECT c.id INTO v_id FROM commerce.credit_notes c WHERE c.store_id = p_store AND c.return_id = p_return AND c.source = v_source;
  END IF;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;
  -- The refund of a change's lower total (D174) is credited by the change's own credit note: none of its own, and the order says so once. Every refund naming an
  -- applied change with a lower total is such a refund (one, or several when it was split over the order's payments); a refund naming a change that was never
  -- applied gave back a payment that came too late, which the next test handles.
  IF p_refund IS NOT NULL AND v_refund.order_edit_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM commerce.order_edits e WHERE e.store_id = p_store AND e.id = v_refund.order_edit_id AND e.status = 'applied' AND e.difference_minor < 0
  ) THEN
    IF NOT EXISTS (SELECT 1 FROM commerce.order_events e WHERE e.store_id = p_store AND e.order_id = v_order_id AND e.type = 'credit_note.covered_by_edit' AND e.data ->> 'key' = v_event_key) THEN
      INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
      VALUES (p_store, v_order_id, 'credit_note.covered_by_edit', jsonb_build_object('key', v_event_key, 'amountMinor', v_amount, 'edit', v_refund.order_edit_id), 'system');
    END IF;
    RETURN NULL;
  END IF;
  -- An exchange's own refund of the original order (the transfer to the exchange order, or the remainder through the provider, D239) is credited by the
  -- return's `return_exchange` note: none of its own, and the order says so once. A refund of the exchange order's payment is an ordinary refund of that order.
  IF p_refund IS NOT NULL AND v_refund.exchange_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM commerce.return_exchanges x WHERE x.store_id = p_store AND x.id = v_refund.exchange_id AND x.order_id = v_order_id
  ) THEN
    IF NOT EXISTS (SELECT 1 FROM commerce.order_events e WHERE e.store_id = p_store AND e.order_id = v_order_id AND e.type = 'credit_note.covered_by_exchange' AND e.data ->> 'key' = v_event_key) THEN
      INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
      VALUES (p_store, v_order_id, 'credit_note.covered_by_exchange', jsonb_build_object('key', v_event_key, 'amountMinor', v_amount, 'exchange', v_refund.exchange_id), 'system');
    END IF;
    RETURN NULL;
  END IF;
  -- A refund of a payment that is not on the invoice (a no-show fee charged afterwards, D65) reverses no sale: no credit note, and the order says so.
  IF p_refund IS NOT NULL AND NOT commerce.payment_on_invoice(p_store, v_refund.payment_id, v_inv.issued_at) THEN
    IF NOT EXISTS (SELECT 1 FROM commerce.order_events e WHERE e.store_id = p_store AND e.order_id = v_order_id AND e.type = 'credit_note.not_invoiced' AND e.data ->> 'key' = v_event_key) THEN
      INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
      VALUES (p_store, v_order_id, 'credit_note.not_invoiced', jsonb_build_object('key', v_event_key, 'amountMinor', v_amount, 'paymentId', v_refund.payment_id), 'system');
    END IF;
    RETURN NULL;
  END IF;

  -- What each bucket of the order's invoices (its own and every change's, D174) has left after all their credit notes so far: one pool.
  SELECT array_agg(p.rate ORDER BY p.ord), array_agg(p.basis ORDER BY p.ord), array_agg(p.net_left ORDER BY p.ord),
         array_agg(p.vat_left ORDER BY p.ord), array_agg(p.gross_left ORDER BY p.ord),
         jsonb_agg(jsonb_build_object('rate', p.rate, 'basis', p.basis, 'vatMinor', p.vat_invoiced) ORDER BY p.ord), coalesce(sum(p.gross_invoiced), 0)
    INTO v_rate, v_basis, v_net_left, v_vat_left, v_gross_left, v_pool, v_pool_total
    FROM commerce.order_buckets_left(p_store, v_order_id) p;
  v_n := coalesce(array_length(v_rate, 1), 0);
  v_room := coalesce((SELECT sum(g) FROM unnest(v_gross_left) AS t(g)), 0);
  v_target := least(v_amount, v_room);
  v_short := v_amount - v_target;
  IF v_n = 0 OR v_target <= 0 THEN
    IF NOT EXISTS (SELECT 1 FROM commerce.order_events e WHERE e.store_id = p_store AND e.order_id = v_order_id AND e.type = 'credit_note.short' AND e.data ->> 'key' = v_event_key) THEN
      INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
      VALUES (p_store, v_order_id, 'credit_note.short', jsonb_build_object('key', v_event_key, 'amountMinor', v_amount, 'creditedMinor', 0, 'shortMinor', v_amount), 'system');
    END IF;
    RETURN NULL;
  END IF;

  -- A return's working is used when it fits the invoice and the amount refunded; else the amount is shared as a plain refund.
  v_ok := v_working IS NOT NULL AND jsonb_typeof(v_working) = 'object' AND jsonb_typeof(v_working -> 'lines') = 'array'
          AND (v_working ->> 'amountMinor')::bigint IS NOT DISTINCT FROM v_amount;
  IF v_ok THEN
    v_sums := array_fill(0::bigint, ARRAY[v_n]);
    v_rows := '[]'::jsonb;
    FOR v_w IN SELECT x FROM jsonb_array_elements(v_working -> 'lines') AS x LOOP
      SELECT l INTO v_line FROM commerce.invoices i, jsonb_array_elements(i.snapshot -> 'lines') AS l
       WHERE i.store_id = p_store AND i.order_id = v_order_id AND l ->> 'lineId' = v_w ->> 'lineId'
       ORDER BY i.issued_at, i.number LIMIT 1;
      IF v_line IS NULL THEN v_ok := false; EXIT; END IF;
      v_k := commerce.bucket_index(v_rate, v_basis, (v_line ->> 'vatRate')::numeric, v_line ->> 'basis');
      IF v_k = 0 THEN v_ok := false; EXIT; END IF;
      IF (v_w ->> 'valueMinor')::bigint > 0 THEN
        v_sums[v_k] := v_sums[v_k] + (v_w ->> 'valueMinor')::bigint;
        v_rows := v_rows || jsonb_build_array(jsonb_build_object(
          'kind', 'goods', 'lineId', v_line ->> 'lineId', 'sku', v_line ->> 'sku', 'title', v_line ->> 'title', 'quantity', (v_w ->> 'quantity')::int,
          'vatRate', (v_line ->> 'vatRate')::numeric, 'basis', v_line ->> 'basis', 'grossMinor', (v_w ->> 'valueMinor')::bigint,
          'netMinor', NULL::bigint, 'vatMinor', NULL::bigint));
      END IF;
      IF (v_w ->> 'deductionMinor')::bigint > 0 THEN
        v_sums[v_k] := v_sums[v_k] - (v_w ->> 'deductionMinor')::bigint;
        v_rows := v_rows || jsonb_build_array(jsonb_build_object(
          'kind', 'deduction', 'lineId', v_line ->> 'lineId', 'sku', v_line ->> 'sku', 'title', v_line ->> 'title', 'quantity', NULL::int,
          'vatRate', (v_line ->> 'vatRate')::numeric, 'basis', v_line ->> 'basis', 'grossMinor', -(v_w ->> 'deductionMinor')::bigint,
          'netMinor', NULL::bigint, 'vatMinor', NULL::bigint));
      END IF;
    END LOOP;
    IF v_ok AND ((v_working ->> 'deliveryMinor')::bigint > 0 OR (v_working ->> 'returnShippingMinor')::bigint > 0) THEN
      v_ship := v_inv.snapshot -> 'shipping';
      IF v_ship IS NULL OR jsonb_typeof(v_ship) <> 'object' THEN
        v_ok := false;
      ELSE
        v_k := commerce.bucket_index(v_rate, v_basis, (v_ship ->> 'vatRate')::numeric, v_ship ->> 'basis');
        IF v_k = 0 THEN
          v_ok := false;
        ELSE
          IF (v_working ->> 'deliveryMinor')::bigint > 0 THEN
            v_sums[v_k] := v_sums[v_k] + (v_working ->> 'deliveryMinor')::bigint;
            v_rows := v_rows || jsonb_build_array(jsonb_build_object(
              'kind', 'delivery', 'lineId', NULL::text, 'sku', NULL::text, 'title', v_ship ->> 'label', 'quantity', NULL::int,
              'vatRate', (v_ship ->> 'vatRate')::numeric, 'basis', v_ship ->> 'basis', 'grossMinor', (v_working ->> 'deliveryMinor')::bigint,
              'netMinor', NULL::bigint, 'vatMinor', NULL::bigint));
          END IF;
          IF (v_working ->> 'returnShippingMinor')::bigint > 0 THEN
            v_sums[v_k] := v_sums[v_k] - (v_working ->> 'returnShippingMinor')::bigint;
            v_rows := v_rows || jsonb_build_array(jsonb_build_object(
              'kind', 'return_shipping', 'lineId', NULL::text, 'sku', NULL::text, 'title', NULL::text, 'quantity', NULL::int,
              'vatRate', (v_ship ->> 'vatRate')::numeric, 'basis', v_ship ->> 'basis', 'grossMinor', -(v_working ->> 'returnShippingMinor')::bigint,
              'netMinor', NULL::bigint, 'vatMinor', NULL::bigint));
          END IF;
        END IF;
      END IF;
    END IF;
  END IF;

  IF v_ok THEN
    v_used := true;
    v_clamp := ARRAY(SELECT greatest(0, least(v_sums[i], v_gross_left[i])) FROM generate_subscripts(v_sums, 1) AS i ORDER BY i);
    v_d := v_target - (SELECT sum(c) FROM unnest(v_clamp) AS t(c));
    v_final := v_clamp;
    IF v_d > 0 THEN
      v_head := ARRAY(SELECT v_gross_left[i] - v_clamp[i] FROM generate_subscripts(v_clamp, 1) AS i ORDER BY i);
      v_inw := ARRAY(SELECT CASE WHEN v_clamp[i] > 0 THEN v_head[i] ELSE 0 END FROM generate_subscripts(v_clamp, 1) AS i ORDER BY i);
      v_weights := CASE WHEN (SELECT sum(w) FROM unnest(v_inw) AS t(w)) >= v_d THEN v_inw ELSE v_head END;
      v_shares := commerce.distribute_minor(v_d, v_weights, v_rate);
      v_final := ARRAY(SELECT v_final[i] + v_shares[i] FROM generate_subscripts(v_final, 1) AS i ORDER BY i);
    ELSIF v_d < 0 THEN
      v_shares := commerce.distribute_minor(-v_d, v_clamp, v_rate);
      v_final := ARRAY(SELECT v_final[i] - v_shares[i] FROM generate_subscripts(v_final, 1) AS i ORDER BY i);
    END IF;
  ELSE
    v_used := false;
    v_final := commerce.distribute_minor(v_target, v_gross_left, v_rate);
  END IF;

  -- Net, VAT and gross per bucket.
  v_vat := ARRAY(SELECT commerce.credit_vat(v_final[i], v_rate[i], v_gross_left[i], v_net_left[i], v_vat_left[i]) FROM generate_subscripts(v_final, 1) AS i ORDER BY i);
  IF NOT v_used THEN
    v_rows := '[]'::jsonb;
    FOR v_k IN 1..v_n LOOP
      IF v_final[v_k] > 0 THEN
        v_rows := v_rows || jsonb_build_array(jsonb_build_object(
          'kind', 'refund', 'lineId', NULL::text, 'sku', NULL::text, 'title', NULL::text, 'quantity', NULL::int,
          'vatRate', v_rate[v_k], 'basis', v_basis[v_k], 'grossMinor', v_final[v_k],
          'netMinor', v_final[v_k] - v_vat[v_k], 'vatMinor', v_vat[v_k]));
      END IF;
    END LOOP;
  ELSE
    -- What the working did not fit into the buckets (a staff adjustment, a return shipping larger than the delivery given back) is shown as adjustment rows.
    FOR v_k IN 1..v_n LOOP
      IF v_final[v_k] - v_sums[v_k] <> 0 THEN
        v_rows := v_rows || jsonb_build_array(jsonb_build_object(
          'kind', 'adjustment', 'lineId', NULL::text, 'sku', NULL::text, 'title', NULL::text, 'quantity', NULL::int,
          'vatRate', v_rate[v_k], 'basis', v_basis[v_k], 'grossMinor', v_final[v_k] - v_sums[v_k],
          'netMinor', NULL::bigint, 'vatMinor', NULL::bigint));
      END IF;
    END LOOP;
  END IF;
  FOR v_k IN 1..v_n LOOP
    IF v_final[v_k] > 0 THEN
      v_buckets := v_buckets || jsonb_build_array(jsonb_build_object(
        'rate', v_rate[v_k], 'basis', v_basis[v_k], 'netMinor', v_final[v_k] - v_vat[v_k], 'vatMinor', v_vat[v_k], 'grossMinor', v_final[v_k]));
      v_net := v_net + v_final[v_k] - v_vat[v_k];
      v_vat_sum := v_vat_sum + v_vat[v_k];
      v_gross := v_gross + v_final[v_k];
    END IF;
  END LOOP;
  IF v_gross <= 0 THEN RETURN NULL; END IF;

  SELECT coalesce(sum(c.total_minor), 0) INTO v_before FROM commerce.credit_notes c JOIN commerce.invoices i ON i.store_id = c.store_id AND i.id = c.invoice_id
   WHERE c.store_id = p_store AND i.order_id = v_order_id;
  SELECT coalesce(jsonb_agg(n ORDER BY ord), '[]'::jsonb) INTO v_notes FROM (VALUES
    (1, 'credit_capped', v_short > 0),
    (2, 'working_not_used', v_working IS NOT NULL AND NOT v_used)
  ) AS t(ord, n, cond) WHERE cond;

  -- The VAT in the seller's currency and in the main currency, at the invoice's rate (a credit note reduces the VAT of the same supply), as
  -- the difference of the cumulative conversions per bucket, so the credit notes of an invoice add up to the invoice's own converted VAT.
  v_vh := v_inv.snapshot -> 'vatHome';
  IF v_vh IS NOT NULL AND jsonb_typeof(v_vh) = 'object' THEN
    v_fx := (v_vh ->> 'fxRate')::numeric;
    v_vat_home := v_vh || jsonb_build_object('vatMinor', commerce.credit_vat_converted(v_pool, v_vat_left, v_vat, v_fx));
  END IF;
  v_vm := v_inv.snapshot -> 'vatMain';
  IF v_vm IS NOT NULL AND jsonb_typeof(v_vm) = 'object' THEN
    IF jsonb_typeof(v_vm -> 'fxRate') = 'number' THEN
      v_fx := (v_vm ->> 'fxRate')::numeric;
      v_vat_main := v_vm || jsonb_build_object('vatMinor', commerce.credit_vat_converted(v_pool, v_vat_left, v_vat, v_fx));
    ELSE
      v_vat_main := v_vm || jsonb_build_object('vatMinor', v_vat_sum);
    END IF;
  END IF;

  v_today := commerce.store_day(p_store, now());
  -- The number last: the series' row lock is held from here to the end of the transaction.
  v_number := commerce.next_document_number(p_store, 'credit_note');
  SELECT s.prefix INTO v_prefix FROM commerce.document_series s WHERE s.store_id = p_store AND s.series = 'credit_note';
  v_docno := v_prefix || v_number::text;

  v_snap := jsonb_build_object(
    'version', 1, 'documentType', 'credit_note', 'number', v_docno, 'issuedOn', to_char(v_today, 'YYYY-MM-DD'),
    'locale', v_inv.snapshot -> 'locale', 'language', v_inv.snapshot -> 'language', 'currency', v_inv.snapshot -> 'currency',
    'seller', v_inv.snapshot -> 'seller', 'buyer', v_inv.snapshot -> 'buyer', 'order', v_inv.snapshot -> 'order',
    'refersTo', jsonb_build_object('invoiceId', v_inv.id, 'invoiceNumber', v_inv.snapshot ->> 'number', 'invoiceIssuedOn', v_inv.snapshot ->> 'issuedOn'),
    'reason', jsonb_build_object('kind', CASE WHEN v_is_return THEN 'return' ELSE 'refund' END, 'returnNumber', v_return_number),
    'source', v_source, 'lines', v_rows, 'buckets', v_buckets,
    'totals', jsonb_build_object('netMinor', v_net, 'vatMinor', v_vat_sum, 'grossMinor', v_gross),
    'vatHome', v_vat_home, 'vatMain', v_vat_main, 'treatment', v_inv.snapshot -> 'treatment',
    'position', jsonb_build_object(
      'invoiceTotalMinor', v_pool_total, 'creditedBeforeMinor', v_before,
      'creditedNowMinor', v_gross, 'leftOnInvoiceMinor', v_pool_total - v_before - v_gross),
    'notes', v_notes);

  PERFORM set_config('commerce.issuing_document', v_key::text, true);
  INSERT INTO commerce.credit_notes (
    store_id, invoice_id, refund_id, return_id, series, number, document_number, currency, total_minor, tax_minor, net_minor,
    source, issued_on, locale, vat_home_currency, vat_home_minor, fx_rate, fx_as_of, fx_source, snapshot, public_token
  ) VALUES (
    p_store, v_inv.id, p_refund, CASE WHEN p_refund IS NULL THEN p_return END, 'credit_note', v_number, v_docno, v_inv.currency, v_gross, v_vat_sum, v_net,
    v_source, v_today, v_inv.locale,
    v_vat_home ->> 'currency', (v_vat_home ->> 'vatMinor')::bigint, v_inv.fx_rate, v_inv.fx_as_of, v_inv.fx_source,
    v_snap, commerce.new_document_token('crn_')
  ) RETURNING id INTO v_id;
  PERFORM set_config('commerce.issuing_document', '', true);

  INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
  VALUES (p_store, v_order_id, 'credit_note.issued',
          jsonb_build_object('creditNoteId', v_id, 'number', v_docno, 'key', v_event_key, 'amountMinor', v_gross), 'system');
  IF v_short > 0 THEN
    INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
    VALUES (p_store, v_order_id, 'credit_note.short', jsonb_build_object('key', v_event_key, 'amountMinor', v_amount, 'creditedMinor', v_gross, 'shortMinor', v_short), 'system');
  END IF;
  RETURN v_id;
END;
$$;


--
-- Name: make_edit_documents(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.make_edit_documents(p_store uuid, p_edit uuid) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  e commerce.order_edits%ROWTYPE;
  o commerce.orders%ROWTYPE;
  st commerce.stores%ROWTYPE;
  v_inv commerce.invoices%ROWTYPE;
  v_tz text;
  v_today date;
  v_supply date;
  v_ship_rate numeric;
  v_ship_gross bigint;
  v_ship_vat bigint;
  v_label text;
  -- The credit side.
  v_rate numeric[];
  v_basis text[];
  v_net_left bigint[];
  v_vat_left bigint[];
  v_gross_left bigint[];
  v_pool jsonb;
  v_pool_total bigint;
  v_before bigint;
  v_n integer;
  v_k integer;
  v_want_g bigint[];
  v_want_v bigint[];
  v_final bigint[];
  v_vat bigint[];
  v_rows jsonb := '[]'::jsonb;
  v_r record;
  v_line jsonb;
  v_lrate numeric;
  v_lbasis text;
  v_buckets jsonb := '[]'::jsonb;
  v_net bigint := 0;
  v_vsum bigint := 0;
  v_gross bigint := 0;
  v_short bigint := 0;
  v_vh jsonb;
  v_vm jsonb;
  v_vat_home jsonb;
  v_vat_main jsonb;
  v_fx numeric;
  v_number bigint;
  v_prefix text;
  v_docno text;
  v_snap jsonb;
  v_id uuid;
  v_notes jsonb;
  -- The invoice side.
  v_lines jsonb;
  v_rounded boolean;
  v_ship jsonb;
  v_ibuckets jsonb;
  v_inet bigint;
  v_ivat bigint;
  v_igross bigint;
  v_exempt boolean;
  v_statements jsonb;
  v_home text;
  v_main text;
  v_paid_now bigint := 0;
  v_provider text;
  v_method text;
  v_received date;
  v_payments jsonb;
  v_inv_notes jsonb;
BEGIN
  -- A change of the business behind the store whose day has come takes effect before anything is numbered (D473).
  PERFORM commerce.apply_business_change(p_store);
  SELECT * INTO e FROM commerce.order_edits WHERE store_id = p_store AND id = p_edit FOR UPDATE;
  IF NOT FOUND OR e.status <> 'applied' THEN RETURN NULL; END IF;
  IF e.documents IN ('issued', 'not_invoiced', 'in_original') THEN RETURN e.documents; END IF;
  SELECT * INTO o FROM commerce.orders WHERE store_id = p_store AND id = e.order_id;
  IF o.copied_from IS NOT NULL OR o.host_id IS NOT NULL THEN
    UPDATE commerce.order_edits SET documents = 'not_invoiced' WHERE id = p_edit;
    RETURN 'not_invoiced';
  END IF;
  -- One at a time per order: the same lock as a refund's credit note.
  SELECT * INTO v_inv FROM commerce.invoices WHERE store_id = p_store AND order_id = e.order_id AND kind = 'order' FOR UPDATE;
  IF NOT FOUND THEN
    IF commerce.invoice_eligibility(o.id) <> 'ok' THEN
      UPDATE commerce.order_edits SET documents = 'not_invoiced' WHERE id = p_edit;
      RETURN 'not_invoiced';
    END IF;
    IF e.documents <> 'waiting' THEN UPDATE commerce.order_edits SET documents = 'waiting' WHERE id = p_edit; END IF;
    RETURN 'waiting';
  END IF;
  IF v_inv.issued_at > e.applied_at THEN
    UPDATE commerce.order_edits SET documents = 'in_original' WHERE id = p_edit;
    RETURN 'in_original';
  END IF;

  SELECT * INTO st FROM commerce.stores WHERE id = p_store;
  v_tz := coalesce(st.time_zone, 'UTC');
  v_today := commerce.store_day(p_store, now());
  v_label := commerce.nz(o.delivery ->> 'label');
  -- The shipping's VAT moved by what the change's VAT moved beyond its lines (the order keeps one shipping rate, frozen when it was placed).
  v_ship_rate := coalesce(o.shipping_tax_rate, (v_inv.snapshot -> 'shipping' ->> 'vatRate')::numeric, commerce.vat_rate(o.market_code, 'standard', o.placed_at), 0);
  v_ship_gross := e.shipping_after - e.shipping_before;
  v_ship_vat := e.tax_delta
    - coalesce((SELECT sum(ol.tax_minor) FROM commerce.order_lines ol WHERE ol.store_id = p_store AND ol.order_id = e.order_id AND ol.order_edit_id = p_edit), 0)
    + coalesce((SELECT sum(l.tax_minor) FROM commerce.order_edit_lines l WHERE l.store_id = p_store AND l.order_edit_id = p_edit AND l.kind IN ('remove', 'reduce')), 0);
  v_ship_vat := CASE WHEN v_ship_gross > 0 THEN greatest(0, least(v_ship_vat, v_ship_gross))
                     WHEN v_ship_gross < 0 THEN greatest(0, least(-v_ship_vat, -v_ship_gross))
                     ELSE 0 END;

  -- ---- The credit note: what the change took off ----
  SELECT array_agg(p.rate ORDER BY p.ord), array_agg(p.basis ORDER BY p.ord), array_agg(p.net_left ORDER BY p.ord),
         array_agg(p.vat_left ORDER BY p.ord), array_agg(p.gross_left ORDER BY p.ord),
         jsonb_agg(jsonb_build_object('rate', p.rate, 'basis', p.basis, 'vatMinor', p.vat_invoiced) ORDER BY p.ord), coalesce(sum(p.gross_invoiced), 0)
    INTO v_rate, v_basis, v_net_left, v_vat_left, v_gross_left, v_pool, v_pool_total
    FROM commerce.order_buckets_left(p_store, e.order_id) p;
  v_n := coalesce(array_length(v_rate, 1), 0);
  v_want_g := array_fill(0::bigint, ARRAY[greatest(v_n, 1)]);
  v_want_v := array_fill(0::bigint, ARRAY[greatest(v_n, 1)]);
  FOR v_r IN
    SELECT l.n, l.order_line_id, l.sku, l.title, l.quantity, l.total_minor, l.tax_minor, l.tax_rate
      FROM commerce.order_edit_lines l WHERE l.store_id = p_store AND l.order_edit_id = p_edit AND l.kind IN ('remove', 'reduce') AND l.total_minor > 0
     ORDER BY l.n
  LOOP
    -- The rate and basis the line had on its invoice (the order's own, or an earlier change's).
    SELECT x INTO v_line FROM commerce.invoices i, jsonb_array_elements(i.snapshot -> 'lines') AS x
     WHERE i.store_id = p_store AND i.order_id = e.order_id AND x ->> 'lineId' = v_r.order_line_id::text
     ORDER BY i.issued_at, i.number LIMIT 1;
    v_lrate := coalesce((v_line ->> 'vatRate')::numeric, v_r.tax_rate);
    v_lbasis := coalesce(v_line ->> 'basis', 'standard');
    v_k := commerce.bucket_index(v_rate, v_basis, v_lrate, v_lbasis);
    v_rows := v_rows || jsonb_build_array(jsonb_build_object(
      'kind', 'goods', 'lineId', v_r.order_line_id, 'sku', v_r.sku, 'title', v_r.title, 'quantity', v_r.quantity,
      'vatRate', v_lrate, 'basis', v_lbasis, 'grossMinor', v_r.total_minor, 'netMinor', NULL::bigint, 'vatMinor', NULL::bigint));
    IF v_k > 0 THEN
      v_want_g[v_k] := v_want_g[v_k] + v_r.total_minor;
      v_want_v[v_k] := v_want_v[v_k] + v_r.tax_minor;
    ELSE
      v_short := v_short + v_r.total_minor;
    END IF;
  END LOOP;
  IF v_ship_gross < 0 THEN
    v_lrate := coalesce((v_inv.snapshot -> 'shipping' ->> 'vatRate')::numeric, v_ship_rate);
    v_lbasis := coalesce(v_inv.snapshot -> 'shipping' ->> 'basis', 'standard');
    v_k := commerce.bucket_index(v_rate, v_basis, v_lrate, v_lbasis);
    v_rows := v_rows || jsonb_build_array(jsonb_build_object(
      'kind', 'delivery', 'lineId', NULL::text, 'sku', NULL::text, 'title', v_label, 'quantity', NULL::int,
      'vatRate', v_lrate, 'basis', v_lbasis, 'grossMinor', -v_ship_gross, 'netMinor', NULL::bigint, 'vatMinor', NULL::bigint));
    IF v_k > 0 THEN
      v_want_g[v_k] := v_want_g[v_k] - v_ship_gross;
      v_want_v[v_k] := v_want_v[v_k] + v_ship_vat;
    ELSE
      v_short := v_short - v_ship_gross;
    END IF;
  END IF;
  IF v_n > 0 THEN
    v_final := ARRAY(SELECT greatest(0, least(v_want_g[i], v_gross_left[i])) FROM generate_series(1, v_n) AS i ORDER BY i);
    v_short := v_short + (SELECT coalesce(sum(v_want_g[i] - v_final[i]), 0) FROM generate_series(1, v_n) AS i);
    -- The VAT the units carried when the whole of it fits; otherwise the VAT in what fits (credit_vat()), never more than is left or so little the net exceeds it.
    v_vat := ARRAY(SELECT CASE WHEN v_final[i] = 0 THEN 0::bigint
                               WHEN v_final[i] = v_want_g[i] THEN greatest(least(v_want_v[i], v_vat_left[i], v_final[i]), v_final[i] - v_net_left[i])
                               ELSE commerce.credit_vat(v_final[i], v_rate[i], v_gross_left[i], v_net_left[i], v_vat_left[i]) END
                     FROM generate_series(1, v_n) AS i ORDER BY i);
    FOR v_k IN 1..v_n LOOP
      IF v_final[v_k] - v_want_g[v_k] <> 0 THEN
        v_rows := v_rows || jsonb_build_array(jsonb_build_object(
          'kind', 'adjustment', 'lineId', NULL::text, 'sku', NULL::text, 'title', NULL::text, 'quantity', NULL::int,
          'vatRate', v_rate[v_k], 'basis', v_basis[v_k], 'grossMinor', v_final[v_k] - v_want_g[v_k], 'netMinor', NULL::bigint, 'vatMinor', NULL::bigint));
      END IF;
      IF v_final[v_k] > 0 THEN
        v_buckets := v_buckets || jsonb_build_array(jsonb_build_object(
          'rate', v_rate[v_k], 'basis', v_basis[v_k], 'netMinor', v_final[v_k] - v_vat[v_k], 'vatMinor', v_vat[v_k], 'grossMinor', v_final[v_k]));
        v_net := v_net + v_final[v_k] - v_vat[v_k];
        v_vsum := v_vsum + v_vat[v_k];
        v_gross := v_gross + v_final[v_k];
      END IF;
    END LOOP;
  END IF;

  IF v_gross > 0 THEN
    SELECT coalesce(sum(c.total_minor), 0) INTO v_before FROM commerce.credit_notes c JOIN commerce.invoices i ON i.store_id = c.store_id AND i.id = c.invoice_id
     WHERE c.store_id = p_store AND i.order_id = e.order_id;
    v_vh := v_inv.snapshot -> 'vatHome';
    v_vat_home := NULL;
    IF v_vh IS NOT NULL AND jsonb_typeof(v_vh) = 'object' THEN
      v_vat_home := v_vh || jsonb_build_object('vatMinor', commerce.credit_vat_converted(v_pool, v_vat_left, v_vat, (v_vh ->> 'fxRate')::numeric));
    END IF;
    v_vm := v_inv.snapshot -> 'vatMain';
    v_vat_main := NULL;
    IF v_vm IS NOT NULL AND jsonb_typeof(v_vm) = 'object' THEN
      IF jsonb_typeof(v_vm -> 'fxRate') = 'number' THEN
        v_vat_main := v_vm || jsonb_build_object('vatMinor', commerce.credit_vat_converted(v_pool, v_vat_left, v_vat, (v_vm ->> 'fxRate')::numeric));
      ELSE
        v_vat_main := v_vm || jsonb_build_object('vatMinor', v_vsum);
      END IF;
    END IF;
    SELECT coalesce(jsonb_agg(x ORDER BY ord), '[]'::jsonb) INTO v_notes FROM (VALUES (1, 'credit_capped', v_short > 0)) AS t(ord, x, cond) WHERE cond;
    v_number := commerce.next_document_number(p_store, 'credit_note');
    SELECT s.prefix INTO v_prefix FROM commerce.document_series s WHERE s.store_id = p_store AND s.series = 'credit_note';
    v_docno := v_prefix || v_number::text;
    v_snap := jsonb_build_object(
      'version', 1, 'documentType', 'credit_note', 'number', v_docno, 'issuedOn', to_char(v_today, 'YYYY-MM-DD'),
      'locale', v_inv.snapshot -> 'locale', 'language', v_inv.snapshot -> 'language', 'currency', v_inv.snapshot -> 'currency',
      'seller', v_inv.snapshot -> 'seller', 'buyer', v_inv.snapshot -> 'buyer', 'order', v_inv.snapshot -> 'order',
      'refersTo', jsonb_build_object('invoiceId', v_inv.id, 'invoiceNumber', v_inv.snapshot ->> 'number', 'invoiceIssuedOn', v_inv.snapshot ->> 'issuedOn'),
      'reason', jsonb_build_object('kind', 'order_edit', 'returnNumber', NULL::text, 'editSeq', e.seq),
      'source', 'order_edit', 'lines', v_rows, 'buckets', v_buckets,
      'totals', jsonb_build_object('netMinor', v_net, 'vatMinor', v_vsum, 'grossMinor', v_gross),
      'vatHome', v_vat_home, 'vatMain', v_vat_main, 'treatment', v_inv.snapshot -> 'treatment',
      'position', jsonb_build_object('invoiceTotalMinor', v_pool_total, 'creditedBeforeMinor', v_before, 'creditedNowMinor', v_gross,
                                     'leftOnInvoiceMinor', v_pool_total - v_before - v_gross),
      'notes', v_notes);
    PERFORM set_config('commerce.issuing_document', p_edit::text, true);
    INSERT INTO commerce.credit_notes (
      store_id, invoice_id, refund_id, return_id, order_edit_id, series, number, document_number, currency, total_minor, tax_minor, net_minor,
      source, issued_on, locale, vat_home_currency, vat_home_minor, fx_rate, fx_as_of, fx_source, snapshot, public_token
    ) VALUES (
      p_store, v_inv.id, NULL, NULL, p_edit, 'credit_note', v_number, v_docno, v_inv.currency, v_gross, v_vsum, v_net,
      'order_edit', v_today, v_inv.locale,
      v_vat_home ->> 'currency', (v_vat_home ->> 'vatMinor')::bigint, v_inv.fx_rate, v_inv.fx_as_of, v_inv.fx_source,
      v_snap, commerce.new_document_token('crn_')
    ) RETURNING id INTO v_id;
    PERFORM set_config('commerce.issuing_document', '', true);
    INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
    VALUES (p_store, e.order_id, 'credit_note.issued', jsonb_build_object('creditNoteId', v_id, 'number', v_docno, 'key', p_edit, 'amountMinor', v_gross, 'edit', e.seq), 'system');
  END IF;

  -- ---- The additional invoice: what the change added ----
  WITH base AS (
    SELECT ol.ctid AS ord, ol.id, ol.sku, ol.title, ol.quantity, ol.unit_price_minor, ol.total_minor, ol.tax_minor, ol.tax_rate, ol.delivery, ol.gift, p.vat_category
      FROM commerce.order_lines ol
      LEFT JOIN commerce.product_variants v ON v.store_id = ol.store_id AND v.id = ol.variant_id
      LEFT JOIN commerce.products p ON p.store_id = v.store_id AND p.id = v.product_id
     WHERE ol.store_id = p_store AND ol.order_id = e.order_id AND ol.order_edit_id = p_edit
  ), c2 AS (
    SELECT base.*, total_minor - tax_minor AS net,
           greatest(unit_price_minor * quantity - commerce.vat_incl(unit_price_minor * quantity, tax_rate), total_minor - tax_minor) AS list_net
      FROM base
  ), c3 AS (
    SELECT c2.*, (2 * list_net + quantity) / (2 * quantity::bigint) AS unit_net FROM c2
  )
  SELECT
    coalesce(jsonb_agg(jsonb_build_object(
      'lineId', id, 'sku', sku, 'title', title,
      'kind', CASE WHEN gift THEN 'gift' WHEN delivery = 'digital' THEN 'download' WHEN delivery = 'service' THEN 'service' ELSE 'goods' END,
      'quantity', quantity, 'listNetMinor', list_net, 'discountNetMinor', list_net - net, 'netMinor', net,
      'vatRate', tax_rate, 'basis', CASE WHEN vat_category = 'exempt' THEN 'exempt' ELSE 'standard' END,
      'vatMinor', tax_minor, 'grossMinor', total_minor, 'unitNetMinor', unit_net,
      'serviceDate', NULL::text, 'service', NULL::jsonb, 'wouldHaveRate', NULL::numeric
    ) ORDER BY ord), '[]'::jsonb),
    coalesce(bool_or(unit_net * quantity <> list_net), false)
    INTO v_lines, v_rounded
    FROM c3;
  v_ship := NULL;
  IF v_ship_gross > 0 THEN
    v_ship := jsonb_build_object(
      'label', v_label, 'netBeforeMinor', v_ship_gross - v_ship_vat, 'discountNetMinor', 0, 'netMinor', v_ship_gross - v_ship_vat,
      'vatRate', v_ship_rate, 'basis', 'standard', 'vatMinor', v_ship_vat, 'grossMinor', v_ship_gross, 'wouldHaveRate', NULL::numeric);
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('rate', rate, 'basis', basis, 'netMinor', n, 'vatMinor', v, 'grossMinor', g) ORDER BY rate DESC, basis), '[]'::jsonb)
    INTO v_ibuckets
    FROM (
      SELECT rate, basis, sum(n)::bigint AS n, sum(v)::bigint AS v, sum(g)::bigint AS g FROM (
        SELECT (l ->> 'vatRate')::numeric AS rate, l ->> 'basis' AS basis, (l ->> 'netMinor')::bigint AS n, (l ->> 'vatMinor')::bigint AS v, (l ->> 'grossMinor')::bigint AS g
          FROM jsonb_array_elements(v_lines) AS l
        UNION ALL
        SELECT (v_ship ->> 'vatRate')::numeric, v_ship ->> 'basis', (v_ship ->> 'netMinor')::bigint, (v_ship ->> 'vatMinor')::bigint, (v_ship ->> 'grossMinor')::bigint
         WHERE v_ship IS NOT NULL
      ) x GROUP BY rate, basis HAVING sum(n) <> 0 OR sum(v) <> 0 OR sum(g) <> 0
    ) y;
  SELECT coalesce(sum((b ->> 'netMinor')::bigint), 0), coalesce(sum((b ->> 'vatMinor')::bigint), 0), coalesce(sum((b ->> 'grossMinor')::bigint), 0),
         coalesce(bool_or(b ->> 'basis' = 'exempt'), false)
    INTO v_inet, v_ivat, v_igross, v_exempt FROM jsonb_array_elements(v_ibuckets) AS b;

  IF v_igross > 0 THEN
    -- The treatment is the original's; its statements are the original's but for `exempt`, which is this invoice's own.
    SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY ord), '[]'::jsonb) INTO v_statements
      FROM (VALUES
        (1, 'reverse_charge', (v_inv.snapshot -> 'treatment' -> 'statements') ? 'reverse_charge'),
        (2, 'ioss', (v_inv.snapshot -> 'treatment' -> 'statements') ? 'ioss'),
        (3, 'not_registered', (v_inv.snapshot -> 'treatment' -> 'statements') ? 'not_registered'),
        (4, 'exempt', v_exempt)
      ) AS t(ord, s, cond) WHERE cond;
    -- The VAT in the seller's currency (Art. 230) at the rates of the day it is issued (a supply of its own), and in the store's main currency.
    v_vat_home := NULL;
    SELECT c.currency::text INTO v_home FROM commerce.countries c WHERE c.code = st.country;
    IF v_ivat > 0 AND commerce.home_vat_required(st.country::text, o.currency::text, v_home) THEN
      v_fx := commerce.fx_factor(o.store_id, o.currency::text, v_home);
      IF v_fx IS NULL THEN
        RAISE EXCEPTION 'invoice.no_exchange_rate: the VAT of the change cannot be stated in % without a rate', v_home USING ERRCODE = 'check_violation';
      END IF;
      v_vat_home := jsonb_build_object(
        'currency', v_home,
        'vatMinor', (SELECT coalesce(sum(commerce.convert_with((b ->> 'vatMinor')::bigint, v_fx)), 0) FROM jsonb_array_elements(v_ibuckets) AS b),
        'fxRate', v_fx, 'asOf', to_char(commerce.fx_as_of(o.store_id, o.currency::text, v_home), 'YYYY-MM-DD'),
        'source', CASE WHEN st.rates_auto THEN 'ecb_auto' ELSE 'owner' END);
    END IF;
    v_main := commerce.main_currency(o.store_id);
    v_vat_main := NULL;
    IF o.currency::text = v_main THEN
      v_vat_main := jsonb_build_object('currency', v_main, 'vatMinor', v_ivat, 'fxRate', NULL::numeric);
    ELSE
      v_fx := commerce.fx_factor(o.store_id, o.currency::text, v_main);
      IF v_fx IS NOT NULL THEN
        v_vat_main := jsonb_build_object(
          'currency', v_main,
          'vatMinor', (SELECT coalesce(sum(commerce.convert_with((b ->> 'vatMinor')::bigint, v_fx)), 0) FROM jsonb_array_elements(v_ibuckets) AS b),
          'fxRate', v_fx);
      END IF;
    END IF;
    -- How it was paid: the change's own payment, and the rest settled against what was paid for the original invoice.
    IF e.payment_id IS NOT NULL THEN
      SELECT p.provider, p.method, p.received_on INTO v_provider, v_method, v_received FROM commerce.payments p WHERE p.store_id = p_store AND p.id = e.payment_id;
      v_paid_now := least(greatest(e.difference_minor, 0), v_igross);
    END IF;
    SELECT coalesce(jsonb_agg(x ORDER BY ord), '[]'::jsonb) INTO v_payments FROM (
      SELECT 1 AS ord, CASE WHEN v_provider = 'manual'
               THEN jsonb_build_object('kind', 'paid_outside', 'amountMinor', v_paid_now, 'provider', 'manual', 'method', v_method)
               ELSE jsonb_build_object('kind', 'paid_online', 'amountMinor', v_paid_now, 'provider', coalesce(v_provider, 'stripe')) END AS x
       WHERE v_paid_now > 0
      UNION ALL
      SELECT 2, jsonb_build_object('kind', 'settled_by_order', 'amountMinor', v_igross - v_paid_now, 'provider', 'order', 'invoiceNumber', v_inv.snapshot ->> 'number')
       WHERE v_igross - v_paid_now > 0
    ) pp;
    v_supply := CASE WHEN v_provider = 'manual' AND v_received IS NOT NULL THEN least(v_received, v_today) ELSE commerce.store_day(p_store, e.applied_at) END;
    SELECT coalesce(jsonb_agg(n ORDER BY ord), '[]'::jsonb) INTO v_inv_notes FROM (VALUES
      (1, 'buyer_incomplete', NOT coalesce((v_inv.snapshot -> 'buyer' ->> 'complete')::boolean, true)),
      (2, 'unit_price_rounded', v_rounded)
    ) AS t(ord, n, cond) WHERE cond;

    v_number := commerce.next_document_number(p_store, 'invoice');
    SELECT s.prefix INTO v_prefix FROM commerce.document_series s WHERE s.store_id = p_store AND s.series = 'invoice';
    v_docno := v_prefix || v_number::text;
    v_snap := jsonb_build_object(
      'version', 1, 'documentType', 'invoice', 'invoiceKind', 'order_edit', 'number', v_docno,
      'issuedOn', to_char(v_today, 'YYYY-MM-DD'), 'supplyDate', to_char(v_supply, 'YYYY-MM-DD'),
      'locale', v_inv.snapshot -> 'locale', 'language', v_inv.snapshot -> 'language', 'currency', v_inv.snapshot -> 'currency',
      'seller', v_inv.snapshot -> 'seller', 'buyer', v_inv.snapshot -> 'buyer', 'order', v_inv.snapshot -> 'order',
      'refersTo', jsonb_build_object('invoiceId', v_inv.id, 'invoiceNumber', v_inv.snapshot ->> 'number', 'invoiceIssuedOn', v_inv.snapshot ->> 'issuedOn'),
      'edit', jsonb_build_object('seq', e.seq),
      'lines', v_lines, 'shipping', v_ship, 'discounts', '[]'::jsonb, 'buckets', v_ibuckets,
      'totals', jsonb_build_object('netMinor', v_inet, 'vatMinor', v_ivat, 'grossMinor', v_igross),
      'vatHome', v_vat_home, 'vatMain', v_vat_main,
      'treatment', (v_inv.snapshot -> 'treatment') || jsonb_build_object('statements', v_statements),
      'payments', v_payments, 'deferred', '[]'::jsonb, 'notes', v_inv_notes);
    PERFORM set_config('commerce.issuing_document', p_edit::text, true);
    INSERT INTO commerce.invoices (
      store_id, order_id, order_edit_id, series, number, document_number, currency, total_minor, tax_minor, net_minor, kind, issued_on, supply_date,
      locale, vat_kind, vat_home_currency, vat_home_minor, fx_rate, fx_as_of, fx_source, snapshot, public_token
    ) VALUES (
      p_store, e.order_id, p_edit, 'invoice', v_number, v_docno, o.currency, v_igross, v_ivat, v_inet, 'order_edit', v_today, v_supply,
      v_inv.locale, o.vat_kind,
      (v_vat_home ->> 'currency'), (v_vat_home ->> 'vatMinor')::bigint, (v_vat_home ->> 'fxRate')::numeric, (v_vat_home ->> 'asOf')::date, (v_vat_home ->> 'source'),
      v_snap, commerce.new_document_token('inv_')
    ) RETURNING id INTO v_id;
    PERFORM set_config('commerce.issuing_document', '', true);
    INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
    VALUES (p_store, e.order_id, 'invoice.issued', jsonb_build_object('invoiceId', v_id, 'number', v_docno, 'edit', e.seq), 'system');
  END IF;

  UPDATE commerce.order_edits SET documents = 'issued' WHERE id = p_edit;
  RETURN 'issued';
END;
$$;


--
-- Name: make_house_store(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.make_house_store() RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_id uuid := commerce.house_store();
  v_business jsonb;
  v_locales text[];
BEGIN
  IF v_id IS NOT NULL THEN
    RETURN v_id;
  END IF;
  SELECT COALESCE(p.business, '{}'::jsonb), p.locales INTO v_business, v_locales FROM commerce.platform_settings p LIMIT 1;
  v_business := COALESCE(v_business, '{}'::jsonb);
  v_locales := ARRAY['en-GB'] || ARRAY(SELECT l FROM unnest(COALESCE(v_locales, '{}'::text[])) AS l WHERE l <> 'en-GB');

  PERFORM set_config('commerce.house_change', 'make', true);
  INSERT INTO commerce.stores (
    slug, name, house, features, sales_pilot, private_mode, locales, country, time_zone, require_two_step, setup_completed_at,
    legal_name, organisation_number, contact_email, postal_address
  ) VALUES (
    'kaizenaflow', 'Kaizena Flow', true, ARRAY['languages', 'sales'], true, true, v_locales, 'NO', 'Europe/Oslo', true, now(),
    NULLIF(btrim(v_business->>'legalName'), ''), NULLIF(btrim(v_business->>'organisationNumber'), ''),
    NULLIF(btrim(v_business->>'contactEmail'), ''), NULLIF(btrim(v_business->>'postalAddress'), '')
  )
  RETURNING id INTO v_id;
  PERFORM set_config('commerce.house_change', '', true);

  INSERT INTO commerce.markets (store_id, code, currency, default_locale, locales, active)
  VALUES (v_id, 'NO', 'NOK', 'en-GB', v_locales, true);

  INSERT INTO commerce.store_members (store_id, account_id, role)
  SELECT v_id, a.id, 'owner' FROM commerce.accounts a WHERE a.platform_admin AND a.disabled_at IS NULL;
  RETURN v_id;
END;
$$;


--
-- Name: make_order_invoice(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.make_order_invoice(p_store uuid, p_order uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  o commerce.orders%ROWTYPE;
  v_id uuid;
  v_paid timestamptz;
  v_issued date;
  v_supply date;
  v_snap jsonb;
  v_number bigint;
  v_prefix text;
  v_docno text;
  v_home jsonb;
BEGIN
  -- A change of the business behind the store whose day has come takes effect before anything is numbered (D473).
  PERFORM commerce.apply_business_change(p_store);
  -- One at a time per order: the payment's own transaction already holds this lock.
  SELECT * INTO o FROM commerce.orders WHERE store_id = p_store AND id = p_order FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT i.id INTO v_id FROM commerce.invoices i WHERE i.store_id = p_store AND i.order_id = p_order AND i.kind = 'order';
  IF FOUND THEN RETURN v_id; END IF;
  IF commerce.invoice_eligibility(p_order) <> 'ok' OR commerce.invoice_readiness(p_order) <> 'ready' THEN RETURN NULL; END IF;

  SELECT min(e.created_at) INTO v_paid FROM commerce.order_events e WHERE e.store_id = p_store AND e.order_id = p_order AND e.type = 'order.paid';
  v_issued := commerce.store_day(p_store, now());
  v_supply := coalesce(
    (SELECT least(p.received_on, v_issued) FROM commerce.payments p
      WHERE p.store_id = p_store AND p.order_id = p_order AND p.provider = 'manual' AND p.status NOT IN ('failed', 'cancelled') AND p.received_on IS NOT NULL
      ORDER BY p.created_at, p.id LIMIT 1),
    commerce.store_day(p_store, v_paid));
  v_snap := commerce.build_invoice_snapshot(p_order, v_issued, v_supply);

  -- The number last: the series' row lock is held from here to the end of the transaction.
  v_number := commerce.next_document_number(p_store, 'invoice');
  SELECT s.prefix INTO v_prefix FROM commerce.document_series s WHERE s.store_id = p_store AND s.series = 'invoice';
  v_docno := v_prefix || v_number::text;
  v_snap := jsonb_set(v_snap, '{number}', to_jsonb(v_docno));
  v_home := v_snap -> 'vatHome';

  PERFORM set_config('commerce.issuing_document', p_order::text, true);
  INSERT INTO commerce.invoices (
    store_id, order_id, series, number, document_number, currency, total_minor, tax_minor, net_minor, kind, issued_on, supply_date,
    locale, vat_kind, vat_home_currency, vat_home_minor, fx_rate, fx_as_of, fx_source, snapshot, public_token
  ) VALUES (
    p_store, p_order, 'invoice', v_number, v_docno, o.currency,
    (v_snap -> 'totals' ->> 'grossMinor')::bigint, (v_snap -> 'totals' ->> 'vatMinor')::bigint, (v_snap -> 'totals' ->> 'netMinor')::bigint,
    'order', v_issued, v_supply, o.locale, o.vat_kind,
    (v_home ->> 'currency'), (v_home ->> 'vatMinor')::bigint, (v_home ->> 'fxRate')::numeric, (v_home ->> 'asOf')::date, (v_home ->> 'source'),
    v_snap, commerce.new_document_token('inv_')
  ) RETURNING id INTO v_id;
  PERFORM set_config('commerce.issuing_document', '', true);

  INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
  VALUES (p_store, p_order, 'invoice.issued', jsonb_build_object('invoiceId', v_id, 'number', v_docno), 'system');
  RETURN v_id;
END;
$$;


--
-- Name: make_sandbox(uuid, text, text, integer); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.make_sandbox(p_starter uuid, p_slug text, p_pass_hash text, p_days integer) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
DECLARE
  v_owner uuid := commerce.sandbox_account();
  v_source uuid;
  v_store uuid;
  v_sandbox uuid;
BEGIN
  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'sandboxes.no_account: the sandbox account is missing' USING ERRCODE = 'check_violation';
  END IF;
  IF p_slug !~ '^try-[a-z0-9]{8}$' THEN
    RAISE EXCEPTION 'sandboxes.address: a sandbox''s address is try- and eight letters or digits' USING ERRCODE = 'check_violation';
  END IF;
  IF p_days IS NULL OR p_days < 1 OR p_days > 30 THEN
    RAISE EXCEPTION 'sandboxes.time: a sandbox lasts 1 to 30 days' USING ERRCODE = 'check_violation';
  END IF;
  v_source := commerce.starter_source(p_starter);
  v_store := commerce.clone_store(v_source, p_slug, (SELECT s.name FROM commerce.stores s WHERE s.id = v_source), v_owner);
  PERFORM set_config('commerce.sandbox_change', v_store::text, true);
  UPDATE commerce.stores
     SET sandbox = true, private_mode = true, shopping_agents = false, domain_buying = false, setup_completed_at = NULL
   WHERE id = v_store;
  PERFORM set_config('commerce.sandbox_change', '', true);
  INSERT INTO commerce.limit_overrides (store_id, key, value, reason)
  SELECT v_store, k.key, k.value, 'Sandbox allowance (D457)'
    FROM commerce.platform_settings p
   CROSS JOIN LATERAL (VALUES ('ai_cost_month_micros', p.sandbox_ai_micros), ('storage_bytes', p.sandbox_storage_bytes)) AS k(key, value);
  INSERT INTO commerce.sandboxes (store_id, source_store_id, pass_hash, expires_at)
  VALUES (v_store, v_source, p_pass_hash, now() + make_interval(days => p_days))
  RETURNING id INTO v_sandbox;
  RETURN v_sandbox;
END;
$_$;


--
-- Name: market_availability_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.market_availability_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.variant_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM commerce.product_variants v
     WHERE v.id = NEW.variant_id AND v.store_id = NEW.store_id AND v.product_id = NEW.product_id
  ) THEN
    RAISE EXCEPTION 'market_availability.variant: the variant is not one of the product''s'
      USING ERRCODE = 'check_violation', CONSTRAINT = 'market_availability_variant';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: market_offered(uuid, text, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.market_offered(p_store uuid, p_market text, p_currency text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM commerce.markets m
     WHERE m.store_id = p_store AND m.code = p_market AND m.active
       AND (commerce.feature_on(p_store, 'countries') OR m.code = commerce.home_market(p_store))
       AND (m.currency = p_currency OR commerce.feature_on(p_store, 'currencies'))
  )
$$;


--
-- Name: market_price_rules_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.market_price_rules_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM commerce.market_price_rules r WHERE r.store_id = NEW.store_id AND r.market_code = NEW.base_market) THEN
    RAISE EXCEPTION 'market_price_rules.chain: the base market has a rule of its own'
      USING ERRCODE = 'check_violation', CONSTRAINT = 'market_price_rules_chain';
  END IF;
  IF EXISTS (SELECT 1 FROM commerce.market_price_rules r WHERE r.store_id = NEW.store_id AND r.base_market = NEW.market_code) THEN
    RAISE EXCEPTION 'market_price_rules.chain: another market takes its prices from this one'
      USING ERRCODE = 'check_violation', CONSTRAINT = 'market_price_rules_chain';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: marketing_consent_events_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.marketing_consent_events_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF current_setting('kaizen.consent_event', true) IS DISTINCT FROM 'on' THEN
      RAISE EXCEPTION 'marketing_consent_events.writer: the history is written by the subscribers'' rules' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    RAISE EXCEPTION 'marketing_consent_events.fixed: the history is never changed' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (SELECT 1 FROM commerce.marketing_subscribers s WHERE s.store_id = OLD.store_id AND s.id = OLD.subscriber_id) THEN
    RAISE EXCEPTION 'marketing_consent_events.kept: the history goes only with its subscriber' USING ERRCODE = 'check_violation';
  END IF;
  RETURN OLD;
END;
$$;


--
-- Name: marketing_subscribers_first_event(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.marketing_subscribers_first_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM set_config('kaizen.consent_event', 'on', true);
  INSERT INTO commerce.marketing_consent_events (store_id, subscriber_id, kind, source, consent_text)
  VALUES (NEW.store_id, NEW.id, CASE NEW.status WHEN 'pending' THEN 'requested' ELSE NEW.status END, NEW.source, NEW.consent_text);
  PERFORM set_config('kaizen.consent_event', '', true);
  RETURN NULL;
END;
$$;


--
-- Name: marketing_subscribers_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.marketing_subscribers_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_kind text;
  v_source text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status NOT IN ('pending', 'subscribed') THEN
      RAISE EXCEPTION 'marketing_subscribers.insert: a subscriber starts pending or subscribed' USING ERRCODE = 'check_violation';
    END IF;
    NEW.unsubscribed_at := NULL;
    NEW.unsubscribe_source := NULL;
  ELSE
    IF NEW.id <> OLD.id OR NEW.store_id <> OLD.store_id OR NEW.email <> OLD.email OR NEW.token <> OLD.token OR NEW.created_at <> OLD.created_at
       OR (OLD.customer_id IS NOT NULL AND NEW.customer_id IS DISTINCT FROM OLD.customer_id
           AND NOT (NEW.customer_id IS NULL AND coalesce(current_setting('kaizen.customer_merge', true), '') = OLD.customer_id::text)) THEN
      RAISE EXCEPTION 'marketing_subscribers.fixed: the address, its token, its store and its customer are fixed' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status = OLD.status AND OLD.status = 'subscribed'
       AND (NEW.consent_text <> OLD.consent_text OR NEW.consented_at <> OLD.consented_at OR NEW.source <> OLD.source
            OR NEW.source_ref IS DISTINCT FROM OLD.source_ref OR NEW.confirmed_at IS DISTINCT FROM OLD.confirmed_at) THEN
      RAISE EXCEPTION 'marketing_subscribers.consent: a subscribed address keeps the consent it gave' USING ERRCODE = 'check_violation';
    END IF;
    IF NOT (
      (OLD.status = 'pending' AND NEW.status IN ('pending', 'subscribed', 'unsubscribed'))
      OR (OLD.status = 'subscribed' AND NEW.status IN ('subscribed', 'unsubscribed'))
      OR (OLD.status = 'unsubscribed' AND NEW.status IN ('unsubscribed', 'pending', 'subscribed'))
    ) THEN
      RAISE EXCEPTION 'marketing_subscribers.move: % cannot become %', OLD.status, NEW.status USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status = 'unsubscribed' AND OLD.status = 'unsubscribed'
       AND (NEW.unsubscribed_at IS DISTINCT FROM OLD.unsubscribed_at OR NEW.unsubscribe_source IS DISTINCT FROM OLD.unsubscribe_source) THEN
      RAISE EXCEPTION 'marketing_subscribers.left: an address that left keeps when and how' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF NEW.status = 'pending' THEN
    IF NEW.confirm_hash IS NULL OR NEW.confirm_until IS NULL THEN
      RAISE EXCEPTION 'marketing_subscribers.pending: a waiting address has a confirmation link' USING ERRCODE = 'check_violation';
    END IF;
    NEW.unsubscribed_at := NULL;
    NEW.unsubscribe_source := NULL;
  ELSIF NEW.status = 'subscribed' THEN
    NEW.confirm_hash := NULL;
    NEW.confirm_until := NULL;
    NEW.unsubscribed_at := NULL;
    NEW.unsubscribe_source := NULL;
  ELSE
    IF NEW.unsubscribe_source IS NULL THEN
      RAISE EXCEPTION 'marketing_subscribers.unsubscribed: leaving says how' USING ERRCODE = 'check_violation';
    END IF;
    NEW.confirm_hash := NULL;
    NEW.confirm_until := NULL;
    IF TG_OP = 'INSERT' OR OLD.status <> 'unsubscribed' THEN
      NEW.unsubscribed_at := now();
    END IF;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    NEW.updated_at := now();
  END IF;

  -- The history: a new request (a new link), a subscription, or leaving.
  IF TG_OP = 'INSERT' OR NEW.status <> OLD.status OR (NEW.status = 'pending' AND NEW.confirm_hash IS DISTINCT FROM OLD.confirm_hash) THEN
    v_kind := CASE NEW.status WHEN 'pending' THEN 'requested' ELSE NEW.status END;
    v_source := CASE WHEN NEW.status = 'unsubscribed' THEN NEW.unsubscribe_source ELSE NEW.source END;
    PERFORM set_config('kaizen.consent_event', 'on', true);
    -- For an update the row exists, so the event is written here; a new row's first event is written after its insert.
    IF TG_OP = 'UPDATE' THEN
      INSERT INTO commerce.marketing_consent_events (store_id, subscriber_id, kind, source, consent_text)
      VALUES (NEW.store_id, NEW.id, v_kind, v_source, CASE WHEN NEW.status = 'unsubscribed' THEN NULL ELSE NEW.consent_text END);
    END IF;
    PERFORM set_config('kaizen.consent_event', '', true);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: media_alt(text, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.media_alt(p_url text, p_locale text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce(nullif(m.alt_translations ->> p_locale, ''), nullif(m.alt, ''))
    FROM commerce.media m
   WHERE p_url IS NOT NULL AND (m.url = p_url OR m.thumbnail_url = p_url)
   ORDER BY m.url = p_url DESC
   LIMIT 1
$$;


--
-- Name: menus_store_page_links(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.menus_store_page_links() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.store_id IS NULL OR jsonb_typeof(NEW.items) <> 'array'
     OR NOT EXISTS (SELECT 1 FROM jsonb_array_elements(NEW.items) e WHERE jsonb_typeof(e -> 'link') = 'object' AND (e -> 'link') ? 'pageId') THEN
    RETURN NEW;
  END IF;
  NEW.items := (
    SELECT coalesce(jsonb_agg(
             CASE WHEN jsonb_typeof(x.e -> 'link') = 'object' AND (x.e -> 'link') ? 'pageId' AND p.slug IS NOT NULL
                       AND (x.e -> 'link' ->> 'kind') IN ('page', 'article')
                  THEN jsonb_set(x.e, '{link}', jsonb_build_object('kind', x.e -> 'link' ->> 'kind', 'slug', p.slug))
                  ELSE x.e END
             ORDER BY x.n), '[]'::jsonb)
      FROM jsonb_array_elements(NEW.items) WITH ORDINALITY x(e, n)
      LEFT JOIN commerce.pages p ON p.id::text = x.e -> 'link' ->> 'pageId' AND p.store_id = NEW.store_id
  );
  RETURN NEW;
END
$$;


--
-- Name: minor_unit_digits(text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.minor_unit_digits(p_currency text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT 2
$$;


--
-- Name: move_booking(uuid, uuid, uuid, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.move_booking(p_store_id uuid, p_booking_id uuid, p_resource_id uuid, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_blocked_from timestamp with time zone, p_blocked_to timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_capacity integer;
  v_taken integer;
BEGIN
  SELECT capacity INTO v_capacity FROM commerce.booking_resources
   WHERE store_id = p_store_id AND id = p_resource_id AND active
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  v_taken := commerce.resource_peak(p_store_id, p_resource_id, p_blocked_from, p_blocked_to, p_booking_id);
  IF v_taken >= v_capacity OR commerce.resource_blocked(p_store_id, p_resource_id, p_blocked_from, p_blocked_to) THEN
    RETURN false;
  END IF;
  UPDATE commerce.bookings
     SET resource_id = p_resource_id, starts_at = p_starts_at, ends_at = p_ends_at,
         blocked_from = p_blocked_from, blocked_to = p_blocked_to,
         sequence = sequence + 1, reminded_at = NULL, updated_at = now()
   WHERE store_id = p_store_id AND id = p_booking_id AND status = 'confirmed';
  RETURN FOUND;
END;
$$;


--
-- Name: new_document_token(text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.new_document_token(p_prefix text) RETURNS text
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  SELECT p_prefix || replace(translate(
    encode(decode(replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''), 'hex'), 'base64'),
    '+/', '-_'), '=', '')
$$;


--
-- Name: next_document_number(uuid, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.next_document_number(p_store_id uuid, p_series text) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_number bigint;
BEGIN
  UPDATE commerce.document_series
     SET next_number = next_number + 1
   WHERE store_id = p_store_id AND series = p_series
  RETURNING next_number - 1 INTO v_number;

  IF v_number IS NULL THEN
    RAISE EXCEPTION 'unknown document series %', p_series;
  END IF;

  RETURN v_number;
END;
$$;


--
-- Name: next_draft_number(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.next_draft_number(p_store uuid) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_n bigint;
BEGIN
  INSERT INTO commerce.order_settings (store_id) VALUES (p_store) ON CONFLICT (store_id) DO NOTHING;
  UPDATE commerce.order_settings SET next_draft_number = next_draft_number + 1, updated_at = now()
   WHERE store_id = p_store
  RETURNING next_draft_number - 1 INTO v_n;
  RETURN 'D-' || v_n;
END;
$$;


--
-- Name: nz(text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.nz(p_text text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT CASE WHEN btrim(p_text) = '' THEN NULL ELSE p_text END
$$;


--
-- Name: order_anchor(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_anchor(p_order uuid) RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT greatest(
    commerce.store_day(o.store_id, o.placed_at),
    (SELECT max(commerce.store_day(o.store_id, p.updated_at)) FROM commerce.payments p
      WHERE p.store_id = o.store_id AND p.order_id = o.id AND p.status = 'captured'),
    (SELECT max(commerce.store_day(o.store_id, rf.created_at)) FROM commerce.refunds rf
       JOIN commerce.payments p ON p.store_id = rf.store_id AND p.id = rf.payment_id
      WHERE p.store_id = o.store_id AND p.order_id = o.id),
    (SELECT max(i.issued_on) FROM commerce.invoices i WHERE i.store_id = o.store_id AND i.order_id = o.id),
    (SELECT max(c.issued_on) FROM commerce.credit_notes c
       JOIN commerce.invoices i ON i.store_id = c.store_id AND i.id = c.invoice_id
      WHERE i.store_id = o.store_id AND i.order_id = o.id),
    (SELECT max(commerce.store_day(o.store_id, r.refunded_at)) FROM commerce.returns r
      WHERE r.store_id = o.store_id AND r.order_id = o.id AND r.refunded_at IS NOT NULL)
  )
    FROM commerce.orders o WHERE o.id = p_order
$$;


--
-- Name: order_anonymisable_on(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_anonymisable_on(p_order uuid) RETURNS date
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  o commerce.orders%ROWTYPE;
  v_country char(2);
  v_today date;
  v_rule record;
  v_years integer;
  v_placed date;
BEGIN
  SELECT * INTO o FROM commerce.orders x WHERE x.id = p_order;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT s.country INTO v_country FROM commerce.stores s WHERE s.id = o.store_id;
  v_today := commerce.store_day(o.store_id, now());
  v_placed := commerce.store_day(o.store_id, o.placed_at);
  IF commerce.order_class(p_order) = 'unpaid' THEN
    SELECT * INTO v_rule FROM commerce.retention_rule('unpaid_orders', v_country, v_today);
    RETURN CASE WHEN v_rule.period_unit = 'months' THEN (v_placed + make_interval(months => v_rule.period_value))::date
                ELSE v_placed + v_rule.period_value END;
  END IF;
  SELECT * INTO v_rule FROM commerce.retention_rule(CASE WHEN o.host_id IS NOT NULL THEN 'host_bookkeeping' ELSE 'bookkeeping' END, v_country, v_today);
  v_years := greatest(ceil(CASE WHEN v_rule.period_unit = 'months' THEN v_rule.period_value / 12.0 ELSE v_rule.period_value / 365.0 END)::integer, 5);
  RETURN make_date(extract(year FROM commerce.order_anchor(p_order))::integer + v_years + 1, 1, 1);
END;
$$;


--
-- Name: order_bookings_follow(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_bookings_follow() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_booking record;
  v_capacity integer;
  v_taken integer;
BEGIN
  IF NEW.status = 'paid' AND OLD.status IS DISTINCT FROM 'fulfilled' THEN
    UPDATE commerce.bookings
       SET status = 'confirmed', hold_expires_at = NULL, cancelled_at = NULL, updated_at = now()
     WHERE store_id = NEW.store_id AND order_id = NEW.id AND status = 'held' AND hold_expires_at > now();
    FOR v_booking IN
      SELECT b.* FROM commerce.bookings b
       WHERE b.store_id = NEW.store_id AND b.order_id = NEW.id AND b.status IN ('held', 'cancelled')
       ORDER BY b.starts_at
    LOOP
      SELECT r.capacity INTO v_capacity FROM commerce.booking_resources r
       WHERE r.store_id = NEW.store_id AND r.id = v_booking.resource_id FOR UPDATE;
      v_taken := commerce.resource_peak(NEW.store_id, v_booking.resource_id, v_booking.blocked_from, v_booking.blocked_to, v_booking.id);
      IF v_taken < coalesce(v_capacity, 0)
         AND NOT commerce.resource_blocked(NEW.store_id, v_booking.resource_id, v_booking.blocked_from, v_booking.blocked_to) THEN
        UPDATE commerce.bookings
           SET status = 'confirmed', hold_expires_at = NULL, cancelled_at = NULL, updated_at = now()
         WHERE id = v_booking.id;
      ELSE
        UPDATE commerce.bookings
           SET status = 'cancelled', cancelled_at = coalesce(cancelled_at, now()), updated_at = now()
         WHERE id = v_booking.id;
        INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
        VALUES (NEW.store_id, NEW.id, 'booking.lost',
                jsonb_build_object('booking', v_booking.id, 'starts_at', v_booking.starts_at), 'system');
      END IF;
    END LOOP;
  ELSIF NEW.status = 'cancelled' THEN
    UPDATE commerce.bookings
       SET status = 'cancelled', cancelled_at = now(), updated_at = now()
     WHERE store_id = NEW.store_id AND order_id = NEW.id AND status IN ('held', 'confirmed');
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: order_buckets_left(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_buckets_left(p_store uuid, p_order uuid) RETURNS TABLE(ord integer, rate numeric, basis text, net_invoiced bigint, vat_invoiced bigint, gross_invoiced bigint, net_left bigint, vat_left bigint, gross_left bigint)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  WITH inv AS (
    SELECT (b ->> 'rate')::numeric AS rate, b ->> 'basis' AS basis, sum((b ->> 'netMinor')::bigint) AS net,
           sum((b ->> 'vatMinor')::bigint) AS vat, sum((b ->> 'grossMinor')::bigint) AS gross
      FROM commerce.invoices i, jsonb_array_elements(i.snapshot -> 'buckets') AS b
     WHERE i.store_id = p_store AND i.order_id = p_order
     GROUP BY 1, 2
  ), cr AS (
    SELECT (b ->> 'rate')::numeric AS rate, b ->> 'basis' AS basis, sum((b ->> 'netMinor')::bigint) AS net,
           sum((b ->> 'vatMinor')::bigint) AS vat, sum((b ->> 'grossMinor')::bigint) AS gross
      FROM commerce.credit_notes c
      JOIN commerce.invoices i ON i.store_id = c.store_id AND i.id = c.invoice_id,
           jsonb_array_elements(c.snapshot -> 'buckets') AS b
     WHERE c.store_id = p_store AND i.order_id = p_order
     GROUP BY 1, 2
  )
  SELECT (row_number() OVER (ORDER BY inv.rate DESC, inv.basis))::integer, inv.rate, inv.basis, inv.net::bigint, inv.vat::bigint, inv.gross::bigint,
         greatest(0, inv.net - coalesce(cr.net, 0))::bigint, greatest(0, inv.vat - coalesce(cr.vat, 0))::bigint, greatest(0, inv.gross - coalesce(cr.gross, 0))::bigint
    FROM inv LEFT JOIN cr ON cr.rate = inv.rate AND cr.basis = inv.basis
   ORDER BY inv.rate DESC, inv.basis
$$;


--
-- Name: order_class(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_class(p_order uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT CASE
    WHEN o.copied_from IS NOT NULL THEN 'copied'
    WHEN o.status = 'pending_payment' THEN 'unpaid'
    WHEN o.status = 'cancelled' AND NOT EXISTS (
      SELECT 1 FROM commerce.payments p WHERE p.store_id = o.store_id AND p.order_id = o.id AND p.status = 'captured'
    ) THEN 'unpaid'
    ELSE 'sale'
  END
    FROM commerce.orders o WHERE o.id = p_order
$$;


--
-- Name: order_discount_codes_fixed(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_discount_codes_fixed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  RAISE EXCEPTION 'order_discount_codes.fixed: an order''s codes stay as they were used' USING ERRCODE = 'check_violation';
END;
$$;


--
-- Name: order_edit_lines_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_edit_lines_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  e record;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'order_edit.append_only: the lines of a change are a record and are never deleted' USING ERRCODE = 'restrict_violation';
  END IF;
  IF TG_OP = 'INSERT' THEN
    SELECT x.created_at, x.status INTO e FROM commerce.order_edits x WHERE x.store_id = NEW.store_id AND x.id = NEW.order_edit_id;
    IF e IS NULL OR e.created_at <> now() THEN
      RAISE EXCEPTION 'order_edit.lines_fixed: the lines of a change are written with it' USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.kind = 'add' AND OLD.order_line_id IS NULL AND NEW.order_line_id IS NOT NULL
     AND (to_jsonb(NEW) - 'order_line_id') = (to_jsonb(OLD) - 'order_line_id') THEN
    IF NOT EXISTS (
      SELECT 1 FROM commerce.order_lines ol JOIN commerce.order_edits x ON x.store_id = ol.store_id AND x.id = NEW.order_edit_id AND x.order_id = ol.order_id
       WHERE ol.store_id = NEW.store_id AND ol.id = NEW.order_line_id AND ol.order_edit_id = NEW.order_edit_id
    ) THEN
      RAISE EXCEPTION 'order_edit.line: an added line names the order line its change added' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'order_edit.lines_fixed: the lines of a change are not changed after it is made' USING ERRCODE = 'restrict_violation';
END;
$$;


--
-- Name: order_edit_money_ref(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_edit_money_ref() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_order uuid;
BEGIN
  IF NEW.order_edit_id IS NULL THEN RETURN NEW; END IF;
  IF TG_TABLE_NAME = 'payments' THEN
    v_order := NEW.order_id;
  ELSE
    SELECT p.order_id INTO v_order FROM commerce.payments p WHERE p.store_id = NEW.store_id AND p.id = NEW.payment_id;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM commerce.order_edits e WHERE e.store_id = NEW.store_id AND e.id = NEW.order_edit_id AND e.order_id = v_order) THEN
    RAISE EXCEPTION 'order_edit.money: a % names a change of its own order only', left(TG_TABLE_NAME, -1) USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.order_edit_id IS NOT NULL AND NEW.order_edit_id IS DISTINCT FROM OLD.order_edit_id THEN
    RAISE EXCEPTION 'order_edit.money: the change a % is for is written with it', left(TG_TABLE_NAME, -1) USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: order_edits_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_edits_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_order record;
  v_next integer;
  v_fixed text[] := ARRAY['id', 'store_id', 'order_id', 'seq', 'reason', 'notify', 'restock', 'currency', 'base', 'total_before', 'total_after',
                          'subtotal_delta', 'shipping_before', 'shipping_after', 'discount_delta', 'tax_delta', 'difference_minor', 'made_by', 'created_at'];
  v_k text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'order_edit.append_only: a change to an order is a record and is never deleted' USING ERRCODE = 'restrict_violation';
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.status NOT IN ('awaiting_payment', 'applied') THEN
      RAISE EXCEPTION 'order_edit.start: a change is made applied or waiting for payment' USING ERRCODE = 'check_violation';
    END IF;
    SELECT o.store_id, o.status, o.copied_from, o.host_id, o.vat_kind, o.currency, o.number INTO v_order
      FROM commerce.orders o WHERE o.store_id = NEW.store_id AND o.id = NEW.order_id FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'order_edit.order: no such order in this store' USING ERRCODE = 'foreign_key_violation';
    END IF;
    IF v_order.copied_from IS NOT NULL THEN
      RAISE EXCEPTION 'copied_order: an order copied from another store is history and cannot get a row in %', TG_TABLE_NAME USING ERRCODE = 'check_violation';
    END IF;
    IF v_order.status <> 'paid' THEN
      RAISE EXCEPTION 'order_edit.not_paid: only a paid order that is not sent can be changed (order % is %)', v_order.number, v_order.status USING ERRCODE = 'check_violation';
    END IF;
    IF v_order.host_id IS NOT NULL THEN
      RAISE EXCEPTION 'order_edit.host: a host''s order is not changed' USING ERRCODE = 'check_violation';
    END IF;
    IF v_order.vat_kind <> 'standard' THEN
      RAISE EXCEPTION 'order_edit.vat_kind: an order with reverse charge or IOSS is not changed' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.currency IS DISTINCT FROM v_order.currency THEN
      RAISE EXCEPTION 'order_edit.currency: a change is in the order''s currency' USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (SELECT 1 FROM commerce.shipments s WHERE s.store_id = NEW.store_id AND s.order_id = NEW.order_id AND s.undone_at IS NULL) THEN
      RAISE EXCEPTION 'order_edit.sent: something of this order is sent, so it is not changed' USING ERRCODE = 'check_violation';
    END IF;
    IF NOT commerce.store_is_active(NEW.store_id) THEN
      RAISE EXCEPTION 'order_edit.store_closed: a store that is not open does not change orders' USING ERRCODE = 'check_violation';
    END IF;
    SELECT coalesce(max(e.seq), 0) + 1 INTO v_next FROM commerce.order_edits e WHERE e.store_id = NEW.store_id AND e.order_id = NEW.order_id;
    IF v_next > 20 THEN
      RAISE EXCEPTION 'order_edit.limit: an order is changed at most 20 times' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.seq IS NULL THEN
      NEW.seq := v_next;
    ELSIF NEW.seq <> v_next THEN
      RAISE EXCEPTION 'order_edit.seq: the next change of this order is E%', v_next USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status = 'applied' AND NEW.applied_at IS NULL THEN NEW.applied_at := now(); END IF;
    RETURN NEW;
  END IF;

  -- UPDATE.
  FOREACH v_k IN ARRAY v_fixed LOOP
    IF (to_jsonb(NEW) -> v_k) IS DISTINCT FROM (to_jsonb(OLD) -> v_k) THEN
      RAISE EXCEPTION 'order_edit.fixed: % of a change is written when it is made', v_k USING ERRCODE = 'restrict_violation';
    END IF;
  END LOOP;
  IF NEW.status IS DISTINCT FROM OLD.status AND NOT (OLD.status = 'awaiting_payment' AND NEW.status IN ('applied', 'cancelled', 'expired')) THEN
    RAISE EXCEPTION 'order_edit.move: a change cannot go from % to %', OLD.status, NEW.status USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status = 'applied' AND OLD.status = 'awaiting_payment' AND NEW.applied_at IS NULL THEN NEW.applied_at := now(); END IF;
  IF NEW.status IN ('cancelled', 'expired') AND OLD.status = 'awaiting_payment' AND NEW.ended_at IS NULL THEN NEW.ended_at := now(); END IF;
  -- The link and its end change only while it waits; after that they stay so the page can say what became of it.
  IF OLD.status <> 'awaiting_payment' AND (NEW.pay_token_hash IS DISTINCT FROM OLD.pay_token_hash OR NEW.expires_at IS DISTINCT FROM OLD.expires_at) THEN
    RAISE EXCEPTION 'order_edit.link_fixed: the link of a change that is not waiting does not change' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.status = 'awaiting_payment' AND NEW.status IN ('applied', 'cancelled', 'expired')
     AND (NEW.pay_token_hash IS DISTINCT FROM OLD.pay_token_hash OR NEW.expires_at IS DISTINCT FROM OLD.expires_at) THEN
    RAISE EXCEPTION 'order_edit.link_fixed: the link of a change is not replaced when it ends' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.applied_at IS NOT NULL AND NEW.applied_at IS DISTINCT FROM OLD.applied_at THEN
    RAISE EXCEPTION 'order_edit.fixed: when a change was applied is written once' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.ended_at IS NOT NULL AND NEW.ended_at IS DISTINCT FROM OLD.ended_at THEN
    RAISE EXCEPTION 'order_edit.fixed: when a change ended is written once' USING ERRCODE = 'restrict_violation';
  END IF;
  -- The payment and the refund are named once, by an applied change.
  IF (OLD.payment_id IS NOT NULL AND NEW.payment_id IS DISTINCT FROM OLD.payment_id) OR (OLD.refund_id IS NOT NULL AND NEW.refund_id IS DISTINCT FROM OLD.refund_id) THEN
    RAISE EXCEPTION 'order_edit.fixed: the payment and the refund of a change are named once' USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW.documents IS DISTINCT FROM OLD.documents AND NOT (
       (OLD.documents = 'none' AND NEW.documents IN ('issued', 'waiting', 'not_invoiced', 'in_original'))
    OR (OLD.documents = 'waiting' AND NEW.documents IN ('issued', 'not_invoiced', 'in_original'))
  ) THEN
    RAISE EXCEPTION 'order_edit.documents: the documents of a change cannot go from % to %', OLD.documents, NEW.documents USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.documents IS DISTINCT FROM OLD.documents AND NEW.status <> 'applied' THEN
    RAISE EXCEPTION 'order_edit.documents: only an applied change has documents' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: order_edits_settled(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_edits_settled() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  e commerce.order_edits%ROWTYPE;
BEGIN
  SELECT * INTO e FROM commerce.order_edits WHERE id = NEW.id;
  IF NOT FOUND OR e.status <> 'applied' THEN RETURN NULL; END IF;
  IF e.difference_minor > 0 AND NOT EXISTS (
    SELECT 1 FROM commerce.payments p
     WHERE p.store_id = e.store_id AND p.id = e.payment_id AND p.order_id = e.order_id AND p.order_edit_id = e.id
       AND p.status = 'captured' AND p.amount_minor = e.difference_minor
  ) THEN
    RAISE EXCEPTION 'order_edit.unpaid: change E% of the order has a higher total and is applied only with its payment of the difference', e.seq
      USING ERRCODE = 'check_violation';
  END IF;
  -- The refunds of the difference may be more than one (split over the order's payments, each capped at what it took): they all name the change, the change
  -- names one of them, and together they are exactly the difference.
  IF e.difference_minor < 0 AND (NOT EXISTS (
    SELECT 1 FROM commerce.refunds r JOIN commerce.payments p ON p.store_id = r.store_id AND p.id = r.payment_id
     WHERE r.store_id = e.store_id AND r.id = e.refund_id AND p.order_id = e.order_id AND r.order_edit_id = e.id AND r.status <> 'failed'
  ) OR (
    SELECT coalesce(sum(r.amount_minor), 0) FROM commerce.refunds r JOIN commerce.payments p ON p.store_id = r.store_id AND p.id = r.payment_id
     WHERE r.store_id = e.store_id AND r.order_edit_id = e.id AND p.order_id = e.order_id AND r.status <> 'failed'
  ) <> -e.difference_minor) THEN
    RAISE EXCEPTION 'order_edit.unrefunded: change E% of the order has a lower total and is applied only with its refund of the difference', e.seq
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: order_edits_unsent_closed(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_edits_unsent_closed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM commerce.unsent_closures c WHERE c.store_id = NEW.store_id AND c.order_id = NEW.order_id) THEN
    RAISE EXCEPTION 'order_edit.unsent_closed: units of this order were taken off what is still to send, so its items cannot be changed'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: order_fulfilment(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_fulfilment(p_order uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  WITH o AS (
    SELECT o.id, o.store_id FROM commerce.orders o WHERE o.id = p_order
  ), l AS (
    SELECT count(*) AS physical, coalesce(sum(commerce.line_to_send(ol.id)), 0) AS to_send, coalesce(sum(commerce.closed_quantity(ol.id)), 0) AS closed
      FROM commerce.order_lines ol JOIN o ON ol.store_id = o.store_id AND ol.order_id = o.id
     WHERE ol.delivery = 'physical' AND ol.variant_id IS NOT NULL
  ), s AS (
    SELECT EXISTS (SELECT 1 FROM commerce.shipments sh JOIN o ON sh.store_id = o.store_id AND sh.order_id = o.id WHERE sh.undone_at IS NULL) AS shipped
  )
  SELECT CASE
           WHEN NOT EXISTS (SELECT 1 FROM o) THEN NULL
           WHEN l.physical = 0 THEN 'none'
           WHEN NOT s.shipped AND l.to_send > 0 THEN 'unsent'
           WHEN s.shipped AND l.to_send > 0 THEN 'partly_sent'
           WHEN s.shipped THEN 'sent'
           WHEN l.closed > 0 THEN 'closed'
           ELSE 'withdrawn'
         END
    FROM l, s
$$;


--
-- Name: order_line_components_frozen(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_line_components_frozen() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  RAISE EXCEPTION 'order_line_components.frozen: a bundle''s components on an order are kept as sold' USING ERRCODE = 'restrict_violation';
END;
$$;


--
-- Name: order_lines_backorder_frozen(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_lines_backorder_frozen() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF current_setting('kaizen.drawing', true) = 'on' THEN
    -- The draw may rewrite the units once the order is paid, and state the days once; the stated days never change.
    IF OLD.backorder_days IS NOT NULL AND NEW.backorder_days IS DISTINCT FROM OLD.backorder_days THEN
      RAISE EXCEPTION 'order_line.backorder_fixed: the delivery time stated on an order line does not change' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  -- Inside a change of the order (D174) the units on backorder may go down with the units kept; the days stated stay.
  IF coalesce(current_setting('kaizen.order_edit', true), '') = OLD.order_id::text
     AND NEW.backorder_quantity <= OLD.backorder_quantity AND NEW.backorder_days IS NOT DISTINCT FROM OLD.backorder_days THEN
    RETURN NEW;
  END IF;
  IF NEW.backorder_quantity IS DISTINCT FROM OLD.backorder_quantity OR NEW.backorder_days IS DISTINCT FROM OLD.backorder_days THEN
    RAISE EXCEPTION 'order_line.backorder_fixed: the backorder of an order line is set when the order is placed and settled when it is paid' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: order_lines_exchange_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_lines_exchange_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  o commerce.orders%ROWTYPE;
BEGIN
  SELECT * INTO o FROM commerce.orders x WHERE x.store_id = NEW.store_id AND x.id = NEW.order_id;
  IF o.exchange_id IS NULL OR o.status <> 'pending_payment' OR o.edited_at IS NOT NULL THEN RETURN NEW; END IF;
  IF NEW.delivery <> 'physical' OR NEW.variant_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM commerce.return_exchange_lines l
     WHERE l.store_id = NEW.store_id AND l.exchange_id = o.exchange_id AND l.variant_id = NEW.variant_id AND l.quantity = NEW.quantity
       AND l.unit_price_minor = NEW.unit_price_minor
  ) THEN
    RAISE EXCEPTION 'order_exchange.line: an exchange''s order holds its replacements only' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: order_lines_measure_frozen(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_lines_measure_frozen() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.measure_amount IS DISTINCT FROM OLD.measure_amount
     OR NEW.measure_unit IS DISTINCT FROM OLD.measure_unit
     OR NEW.measure_base IS DISTINCT FROM OLD.measure_base THEN
    RAISE EXCEPTION 'unit_price.frozen' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: order_lines_settled_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_lines_settled_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_order uuid := CASE WHEN TG_OP = 'DELETE' THEN OLD.order_id ELSE NEW.order_id END;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.order_edit_id IS DISTINCT FROM OLD.order_edit_id THEN
    RAISE EXCEPTION 'order_line.edit_fixed: the change that added an order line is written with it' USING ERRCODE = 'restrict_violation';
  END IF;
  IF TG_OP = 'INSERT' AND NEW.order_edit_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM commerce.order_edits e
     WHERE e.store_id = NEW.store_id AND e.id = NEW.order_edit_id AND e.order_id = NEW.order_id AND e.status IN ('awaiting_payment', 'applied')
  ) THEN
    RAISE EXCEPTION 'order_line.edit: a line is added by a change of its own order' USING ERRCODE = 'check_violation';
  END IF;
  IF current_setting('commerce.copying', true) = 'on' THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NEW.order_id IS NOT DISTINCT FROM OLD.order_id AND NEW.quantity IS NOT DISTINCT FROM OLD.quantity
       AND NEW.unit_price_minor IS NOT DISTINCT FROM OLD.unit_price_minor AND NEW.total_minor IS NOT DISTINCT FROM OLD.total_minor
       AND NEW.tax_minor IS NOT DISTINCT FROM OLD.tax_minor AND NEW.tax_rate IS NOT DISTINCT FROM OLD.tax_rate
       AND NEW.discount_minor IS NOT DISTINCT FROM OLD.discount_minor AND NEW.member_discount_minor IS NOT DISTINCT FROM OLD.member_discount_minor
       AND NEW.campaign_discount_minor IS NOT DISTINCT FROM OLD.campaign_discount_minor AND NEW.bonus_discount_minor IS NOT DISTINCT FROM OLD.bonus_discount_minor
       AND NEW.referral_discount_minor IS NOT DISTINCT FROM OLD.referral_discount_minor AND NEW.staff_discount_minor IS NOT DISTINCT FROM OLD.staff_discount_minor
       AND NEW.vat_relief_minor IS NOT DISTINCT FROM OLD.vat_relief_minor AND NEW.variant_id IS NOT DISTINCT FROM OLD.variant_id
       AND NEW.sku IS NOT DISTINCT FROM OLD.sku AND NEW.delivery IS NOT DISTINCT FROM OLD.delivery THEN
      RETURN NEW;
    END IF;
    IF NEW.order_id IS DISTINCT FROM OLD.order_id AND commerce.order_settled(OLD.order_id) THEN
      RAISE EXCEPTION 'order_line.settled: a line of a paid order does not move to another order' USING ERRCODE = 'restrict_violation';
    END IF;
  END IF;
  IF NOT commerce.order_settled(v_order) OR commerce.in_order_edit(v_order) THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;
  RAISE EXCEPTION 'order_line.settled: the lines of a paid order change only through an order change (applyOrderEdit)' USING ERRCODE = 'restrict_violation';
END;
$$;


--
-- Name: order_number_audit(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_number_audit(p_store uuid) RETURNS TABLE(orders bigint, first_number bigint, last_number bigint, missing bigint, first_missing bigint, off_format bigint, next_number bigint, ok boolean)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $_$
DECLARE
  v_prefix text;
  v_next bigint;
BEGIN
  SELECT s.prefix, s.next_number INTO v_prefix, v_next
    FROM commerce.document_series s WHERE s.store_id = p_store AND s.series = 'order';
  IF NOT FOUND THEN
    RETURN QUERY SELECT 0::bigint, NULL::bigint, NULL::bigint, 0::bigint, NULL::bigint, 0::bigint, NULL::bigint, false;
    RETURN;
  END IF;
  RETURN QUERY
  WITH mine AS (
    SELECT o.number FROM commerce.orders o WHERE o.store_id = p_store AND o.copied_from IS NULL
  ),
  numbered AS (
    SELECT substr(m.number, length(v_prefix) + 1)::bigint AS n
      FROM mine m
     WHERE left(m.number, length(v_prefix)) = v_prefix AND substr(m.number, length(v_prefix) + 1) ~ '^[0-9]{1,15}$'
  ),
  ends AS (SELECT min(n) AS lo, max(n) AS hi, count(*) AS c FROM numbered),
  -- Gaps are found from the numbers' neighbours, so a wild number never makes this walk through every value between.
  steps AS (SELECT n, lag(n) OVER (ORDER BY n) AS before FROM (SELECT DISTINCT n FROM numbered) d)
  SELECT (SELECT count(*) FROM mine),
         e.lo, e.hi,
         COALESCE(e.hi - e.lo + 1 - (SELECT count(DISTINCT n) FROM numbered), 0),
         (SELECT min(st.before + 1) FROM steps st WHERE st.before IS NOT NULL AND st.n > st.before + 1),
         (SELECT count(*) FROM mine) - e.c,
         v_next,
         COALESCE(e.hi - e.lo + 1 = (SELECT count(DISTINCT n) FROM numbered), true)
           AND (SELECT count(*) FROM mine) = e.c AND (e.hi IS NULL OR v_next = e.hi + 1)
    FROM ends e;
END;
$_$;


--
-- Name: order_number_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_number_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.copied_from IS NULL AND EXISTS (SELECT 1 FROM commerce.stores s WHERE s.id = OLD.store_id) THEN
      RAISE EXCEPTION 'order_number.deleted: order % cannot be deleted: its number would leave a gap', OLD.number USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN OLD;
  END IF;
  IF OLD.copied_from IS NULL AND (NEW.number IS DISTINCT FROM OLD.number OR NEW.store_id IS DISTINCT FROM OLD.store_id) THEN
    RAISE EXCEPTION 'order_number.changed: order % keeps its number', OLD.number USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: order_payment_terms_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_payment_terms_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'order_payment_terms.delete: an order''s payment terms are kept' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.company_id IS NULL OR NOT EXISTS (
      SELECT 1 FROM commerce.orders o
       WHERE o.store_id = NEW.store_id AND o.id = NEW.order_id AND o.status = 'pending_payment' AND o.copied_from IS NULL AND o.host_id IS NULL
    ) THEN
      RAISE EXCEPTION 'order_payment_terms.order: terms are given to an order of a company while it is placed' USING ERRCODE = 'check_violation';
    END IF;
    NEW.reminder_sent_at := NULL;
    NEW.overdue_sent_at := NULL;
    NEW.paid_at := NULL;
    RETURN NEW;
  END IF;
  IF NEW.order_id <> OLD.order_id OR NEW.store_id <> OLD.store_id OR NEW.terms <> OLD.terms OR NEW.due_on <> OLD.due_on
     OR NEW.created_at <> OLD.created_at OR (NEW.company_id IS DISTINCT FROM OLD.company_id AND NEW.company_id IS NOT NULL) THEN
    RAISE EXCEPTION 'order_payment_terms.fixed: an order''s terms, due day and company are fixed' USING ERRCODE = 'check_violation';
  END IF;
  IF (OLD.reminder_sent_at IS NOT NULL AND NEW.reminder_sent_at IS DISTINCT FROM OLD.reminder_sent_at)
     OR (OLD.overdue_sent_at IS NOT NULL AND NEW.overdue_sent_at IS DISTINCT FROM OLD.overdue_sent_at)
     OR (OLD.paid_at IS NOT NULL AND NEW.paid_at IS DISTINCT FROM OLD.paid_at) THEN
    RAISE EXCEPTION 'order_payment_terms.once: a reminder, an overdue notice and the payment are recorded once' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: order_payment_terms_sold(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_payment_terms_sold() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' OR NEW.paid_at IS DISTINCT FROM OLD.paid_at THEN
    UPDATE commerce.orders SET sold_at = coalesce(NEW.paid_at, 'infinity'::timestamptz)
     WHERE store_id = NEW.store_id AND id = NEW.order_id AND sold_at IS DISTINCT FROM coalesce(NEW.paid_at, 'infinity'::timestamptz);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: order_rules_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_rules_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.store_id <> OLD.store_id THEN
    RAISE EXCEPTION 'order_rules.store_fixed: a rule stays with its store' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'INSERT' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('order_rules:' || NEW.store_id::text, 0));
    IF (SELECT count(*) FROM commerce.order_rules r WHERE r.store_id = NEW.store_id) >= 50 THEN
      RAISE EXCEPTION 'order_rules.limit: a store has at most 50 automation rules' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: order_settled(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_settled(p_order uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce((
    SELECT o.status <> 'pending_payment' AND o.copied_from IS NULL
           AND EXISTS (SELECT 1 FROM commerce.order_events e WHERE e.store_id = o.store_id AND e.order_id = o.id AND e.type = 'order.paid')
      FROM commerce.orders o WHERE o.id = p_order), false)
$$;


--
-- Name: order_tag_counts(uuid, integer); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_tag_counts(p_store uuid, p_limit integer DEFAULT 200) RETURNS TABLE(key text, label text, orders bigint)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT t.key, (array_agg(t.label ORDER BY t.created_at, t.order_id))[1] AS label, count(*) AS orders
    FROM commerce.order_tags t
   WHERE t.store_id = p_store
   GROUP BY t.key
   ORDER BY count(*) DESC, t.key
   LIMIT greatest(p_limit, 0)
$$;


--
-- Name: order_tags_limit(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_tags_limit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('order_tags:' || NEW.order_id::text, 0));
  IF (SELECT count(*) FROM commerce.order_tags t WHERE t.order_id = NEW.order_id) >= 250 THEN
    RAISE EXCEPTION 'order_tags.limit: an order has at most 250 tags' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: order_views_limit(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.order_views_limit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('order_views:' || NEW.store_id::text, 0));
  IF (SELECT count(*) FROM commerce.order_views v WHERE v.store_id = NEW.store_id) >= 30 THEN
    RAISE EXCEPTION 'order_views.limit: a store has at most 30 saved views' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: orders_ad_consent(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.orders_ad_consent() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.cart_id IS NOT NULL THEN
      SELECT c.ad_consent_at, c.ad_signals INTO NEW.ad_consent_at, NEW.ad_signals
      FROM commerce.carts c WHERE c.id = NEW.cart_id AND c.store_id = NEW.store_id;
    ELSE
      NEW.ad_consent_at := NULL;
      NEW.ad_signals := NULL;
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.ad_consent_at IS DISTINCT FROM OLD.ad_consent_at THEN
    RAISE EXCEPTION 'orders.ad_consent_fixed' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.ad_signals IS DISTINCT FROM OLD.ad_signals AND NEW.ad_signals IS NOT NULL THEN
    RAISE EXCEPTION 'orders.ad_signals_fixed' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: orders_affiliate(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.orders_affiliate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.copied_from IS NOT NULL THEN
    RETURN NULL;
  END IF;
  IF NEW.status = 'paid' AND OLD.status IN ('pending_payment', 'authorized', 'cancelled') THEN
    PERFORM commerce.affiliate_order_paid(NEW.id);
  ELSIF NEW.status = 'cancelled' AND OLD.status IN ('paid', 'fulfilled') THEN
    PERFORM commerce.affiliate_order_paid_cancelled(NEW.id);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: orders_bonus(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.orders_bonus() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.copied_from IS NOT NULL THEN
    RETURN NULL;
  END IF;
  IF NEW.status = 'paid' AND OLD.status IN ('pending_payment', 'authorized', 'cancelled') THEN
    PERFORM commerce.bonus_order_paid(NEW.id, OLD.status::text);
  ELSIF NEW.status = 'cancelled' AND OLD.status IN ('pending_payment', 'authorized') THEN
    PERFORM commerce.bonus_order_unpaid_cancelled(NEW.id);
  ELSIF NEW.status = 'cancelled' AND OLD.status IN ('paid', 'fulfilled') THEN
    PERFORM commerce.bonus_order_paid_cancelled(NEW.id);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: orders_company_purchase(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.orders_company_purchase() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.po_number IS DISTINCT FROM OLD.po_number OR NEW.company_location_id IS DISTINCT FROM OLD.company_location_id THEN
    RAISE EXCEPTION 'orders.company_purchase: an order keeps the location and PO number it was placed with' USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW.approval IS DISTINCT FROM OLD.approval AND NOT coalesce(OLD.approval = 'waiting' AND NEW.approval IN ('approved', 'declined'), false) THEN
    RAISE EXCEPTION 'orders.approval: an approval only moves from waiting to approved or declined' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: orders_creator(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.orders_creator() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.copied_from IS NOT NULL THEN
    RETURN NULL;
  END IF;
  IF NEW.status IN ('paid', 'fulfilled') AND OLD.status IN ('pending_payment', 'authorized', 'cancelled') THEN
    PERFORM commerce.creator_order_paid(NEW.id);
  ELSIF NEW.status = 'cancelled' THEN
    PERFORM commerce.creator_order_cancelled(NEW.id);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: orders_deal_win(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.orders_deal_win() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.copied_from IS NOT NULL THEN
    RETURN NULL;
  END IF;
  PERFORM commerce.deal_win(
    NEW.store_id,
    ARRAY(
      SELECT l.deal_id FROM commerce.deal_links l
       WHERE l.store_id = NEW.store_id AND (l.order_id = NEW.id OR (NEW.draft_id IS NOT NULL AND l.draft_id = NEW.draft_id))
    ),
    'order'
  );
  RETURN NULL;
END;
$$;


--
-- Name: orders_delivered_source(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.orders_delivered_source() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.delivered_source = 'carrier'
     AND (TG_OP = 'INSERT' OR OLD.delivered_source IS DISTINCT FROM 'carrier' OR NEW.delivered_at IS DISTINCT FROM OLD.delivered_at)
     AND coalesce(current_setting('kaizen.carrier_delivery', true), '') <> NEW.id::text THEN
    RAISE EXCEPTION 'orders.delivered_source: a delivery from a carrier is recorded only by commerce.record_carrier_delivery()' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: orders_delivery_frozen(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.orders_delivery_frozen() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF OLD.status <> 'pending_payment'
     AND (NEW.delivery_method IS DISTINCT FROM OLD.delivery_method OR NEW.pickup_location_id IS DISTINCT FROM OLD.pickup_location_id
          OR NEW.delivery IS DISTINCT FROM OLD.delivery) THEN
    IF coalesce(current_setting('commerce.anonymising', true), '') = 'on'
       AND NEW.delivery_method IS NOT DISTINCT FROM OLD.delivery_method AND NEW.pickup_location_id IS NOT DISTINCT FROM OLD.pickup_location_id
       AND NEW.delivery IS NOT DISTINCT FROM (OLD.delivery - 'postalCode') THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'order_delivery.frozen: how order % is delivered was chosen when it was bought and cannot be changed', OLD.number USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.ready_for_pickup_at IS NOT NULL AND NEW.ready_for_pickup_at IS DISTINCT FROM OLD.ready_for_pickup_at THEN
    RAISE EXCEPTION 'order_delivery.ready_once: order % was marked ready for pickup at %', OLD.number, OLD.ready_for_pickup_at USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: orders_draft_follow(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.orders_draft_follow() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.draft_id IS NULL THEN
    RETURN NULL;
  END IF;
  IF NEW.status = 'paid' THEN
    UPDATE commerce.draft_orders SET status = 'paid', paid_at = now(), updated_at = now()
     WHERE store_id = NEW.store_id AND id = NEW.draft_id AND order_id = NEW.id AND status IN ('sent', 'expired', 'cancelled');
  ELSIF NEW.status = 'cancelled' AND OLD.status = 'pending_payment' THEN
    UPDATE commerce.draft_orders SET status = 'expired', updated_at = now()
     WHERE store_id = NEW.store_id AND id = NEW.draft_id AND order_id = NEW.id AND status = 'sent';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: orders_exchange_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.orders_exchange_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  e commerce.return_exchanges%ROWTYPE;
  o commerce.orders%ROWTYPE;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.exchange_id IS DISTINCT FROM OLD.exchange_id THEN
      RAISE EXCEPTION 'order_exchange.frozen: the exchange an order was made for is written with the order' USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.exchange_id IS NULL THEN RETURN NEW; END IF;
  IF coalesce(current_setting('kaizen.exchange', true), '') <> NEW.exchange_id::text THEN
    RAISE EXCEPTION 'order_exchange.context: an exchange''s order is made only by processing that exchange' USING ERRCODE = 'restrict_violation';
  END IF;
  SELECT * INTO e FROM commerce.return_exchanges x WHERE x.store_id = NEW.store_id AND x.id = NEW.exchange_id;
  IF NOT FOUND OR e.status <> 'confirmed' THEN
    RAISE EXCEPTION 'order_exchange.state: an exchange''s order is made from a confirmed exchange' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO o FROM commerce.orders x WHERE x.store_id = e.store_id AND x.id = e.order_id;
  IF NEW.currency <> o.currency OR NEW.market_code <> o.market_code OR NEW.currency <> e.currency THEN
    RAISE EXCEPTION 'order_exchange.market: an exchange''s order is in the original order''s market and currency' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status <> 'pending_payment' OR NEW.host_id IS NOT NULL OR NEW.subscription_id IS NOT NULL OR NEW.copied_from IS NOT NULL THEN
    RAISE EXCEPTION 'order_exchange.kind: an exchange''s order is an ordinary order of the store''s own, waiting for payment' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: orders_gift_card_payments(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.orders_gift_card_payments() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_unpaid bigint;
BEGIN
  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NULL;
  END IF;
  IF NEW.status = 'paid' AND OLD.status IN ('pending_payment', 'authorized') THEN
    UPDATE commerce.payments SET status = 'captured', updated_at = now()
     WHERE store_id = NEW.store_id AND order_id = NEW.id AND provider = 'gift_card' AND status = 'pending';
  ELSIF NEW.status = 'paid' AND OLD.status = 'cancelled' THEN
    SELECT coalesce(sum(p.amount_minor), 0) INTO v_unpaid
      FROM commerce.payments p
     WHERE p.store_id = NEW.store_id AND p.order_id = NEW.id AND p.provider = 'gift_card' AND p.status = 'cancelled';
    IF v_unpaid > 0 THEN
      INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
      VALUES (NEW.store_id, NEW.id, 'gift_card.unpaid', jsonb_build_object('amountMinor', v_unpaid, 'currency', NEW.currency), 'system');
    END IF;
  ELSIF NEW.status = 'cancelled' AND OLD.status IN ('pending_payment', 'authorized') THEN
    UPDATE commerce.payments SET status = 'cancelled', updated_at = now()
     WHERE store_id = NEW.store_id AND order_id = NEW.id AND provider = 'gift_card' AND status = 'pending';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: orders_gift_card_people(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.orders_gift_card_people() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.anonymised_at IS NOT NULL AND OLD.anonymised_at IS NULL AND NEW.copied_from IS NULL THEN
    UPDATE commerce.order_lines
       SET gift_card_to = NULL, gift_card_to_name = NULL, gift_card_from = NULL, gift_card_message = NULL, gift_card_send_on = NULL
     WHERE store_id = NEW.store_id AND order_id = NEW.id AND gift_card_to IS NOT NULL;
    UPDATE commerce.gift_cards
       SET recipient_email = NULL, recipient_name = NULL, message = NULL, customer_id = NULL
     WHERE store_id = NEW.store_id AND order_id = NEW.id
       AND (recipient_email IS NOT NULL OR recipient_name IS NOT NULL OR message IS NOT NULL OR customer_id IS NOT NULL);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: orders_gift_frozen(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.orders_gift_frozen() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.is_gift IS DISTINCT FROM OLD.is_gift OR NEW.gift_to IS DISTINCT FROM OLD.gift_to
     OR NEW.gift_from IS DISTINCT FROM OLD.gift_from OR NEW.gift_message IS DISTINCT FROM OLD.gift_message THEN
    IF current_setting('commerce.anonymising', true) = 'on'
       AND NOT NEW.is_gift AND NEW.gift_to IS NULL AND NEW.gift_from IS NULL AND NEW.gift_message IS NULL THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'order_gift.frozen: the gift message of order % is the buyer''s and cannot be changed', OLD.number USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: orders_issue_gift_cards(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.orders_issue_gift_cards() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.status IN ('paid', 'fulfilled') AND OLD.status NOT IN ('paid', 'fulfilled') THEN
    PERFORM commerce.issue_order_gift_cards(NEW.store_id, NEW.id);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: orders_origin_frozen(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.orders_origin_frozen() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.source IS DISTINCT FROM OLD.source OR NEW.draft_id IS DISTINCT FROM OLD.draft_id OR NEW.made_by IS DISTINCT FROM OLD.made_by
     OR (NEW.staff_discount_minor IS DISTINCT FROM OLD.staff_discount_minor
         AND NOT (coalesce(current_setting('kaizen.order_edit', true), '') = OLD.id::text AND NEW.staff_discount_minor < OLD.staff_discount_minor))
     OR (NEW.staff_discount_label IS DISTINCT FROM OLD.staff_discount_label
         AND NOT (coalesce(current_setting('kaizen.order_edit', true), '') = OLD.id::text AND NEW.staff_discount_label IS NULL AND NEW.staff_discount_minor = 0)) THEN
    RAISE EXCEPTION 'order_origin.frozen: where order % came from and its staff discount are written with the order', OLD.number USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: orders_settled_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.orders_settled_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.subtotal_minor IS NOT DISTINCT FROM OLD.subtotal_minor AND NEW.shipping_minor IS NOT DISTINCT FROM OLD.shipping_minor
     AND NEW.discount_minor IS NOT DISTINCT FROM OLD.discount_minor AND NEW.member_discount_minor IS NOT DISTINCT FROM OLD.member_discount_minor
     AND NEW.campaign_discount_minor IS NOT DISTINCT FROM OLD.campaign_discount_minor AND NEW.credit_minor IS NOT DISTINCT FROM OLD.credit_minor
     AND NEW.referral_discount_minor IS NOT DISTINCT FROM OLD.referral_discount_minor AND NEW.staff_discount_minor IS NOT DISTINCT FROM OLD.staff_discount_minor
     AND NEW.tax_minor IS NOT DISTINCT FROM OLD.tax_minor
     AND NEW.total_minor IS NOT DISTINCT FROM OLD.total_minor AND NEW.edited_at IS NOT DISTINCT FROM OLD.edited_at THEN
    RETURN NEW;
  END IF;
  IF OLD.status = 'pending_payment' OR OLD.copied_from IS NOT NULL OR commerce.in_order_edit(OLD.id) OR NOT commerce.order_settled(OLD.id) THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'order.settled: the amounts of paid order % change only through an order change (applyOrderEdit)', OLD.number USING ERRCODE = 'restrict_violation';
END;
$$;


--
-- Name: orders_store_open(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.orders_store_open() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  -- A store template (D175) takes no order of any kind, not even a copied one: it is a preview.
  IF EXISTS (SELECT 1 FROM commerce.stores s WHERE s.id = NEW.store_id AND s.starter) THEN
    RAISE EXCEPTION 'orders.store_starter: a store template takes no orders' USING ERRCODE = 'check_violation';
  END IF;
  -- A sandbox (D457) takes no order of any kind either: it is a visitor's try of the builder.
  IF EXISTS (SELECT 1 FROM commerce.stores s WHERE s.id = NEW.store_id AND s.sandbox) THEN
    RAISE EXCEPTION 'orders.store_sandbox: a sandbox takes no orders' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.copied_from IS NOT NULL THEN
    RETURN NEW;
  END IF;
  IF NOT commerce.store_is_active(NEW.store_id) THEN
    RAISE EXCEPTION 'orders.store_not_open: the store is not open for sale' USING ERRCODE = 'check_violation';
  END IF;
  -- A website (D178 step 5: the online shop off) sells nothing.
  IF NOT commerce.feature_on(NEW.store_id, 'shop') THEN
    RAISE EXCEPTION 'orders.shop_off: the store''s online shop is switched off' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: orders_vat_frozen(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.orders_vat_frozen() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF OLD.status <> 'pending_payment' AND (
       NEW.vat_kind IS DISTINCT FROM OLD.vat_kind
    OR NEW.vat_relief_minor IS DISTINCT FROM OLD.vat_relief_minor
    OR (NEW.vat_treatment IS DISTINCT FROM OLD.vat_treatment AND current_setting('commerce.anonymising', true) IS DISTINCT FROM 'on')
    OR NEW.shipping_tax_rate IS DISTINCT FROM OLD.shipping_tax_rate
    OR NEW.vat_check_id IS DISTINCT FROM OLD.vat_check_id
  ) THEN
    RAISE EXCEPTION 'order_vat_frozen: the VAT treatment of an order is fixed once it has left pending payment'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: page_place(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.page_place(p_store uuid, p_page uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT COALESCE(
    (SELECT r.role FROM commerce.page_roles r WHERE r.store_id = p_store AND r.page_id = p_page),
    (SELECT CASE WHEN s.front_page_id = p_page THEN 'front' WHEN s.products_page_id = p_page THEN 'products' END FROM commerce.stores s WHERE s.id = p_store)
  );
$$;


--
-- Name: page_redirects_not_taken(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.page_redirects_not_taken() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  SELECT p.type INTO NEW.type FROM commerce.pages p WHERE p.id = NEW.page_id;
  IF EXISTS (
    SELECT 1 FROM commerce.pages p
    WHERE p.slug = NEW.slug AND p.type = NEW.type AND p.store_id IS NOT DISTINCT FROM NEW.store_id
  ) THEN
    RAISE EXCEPTION 'page address % is in use', NEW.slug USING ERRCODE = 'unique_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: page_roles_experiment_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.page_roles_experiment_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE') AND EXISTS (SELECT 1 FROM commerce.experiments e WHERE e.store_id = OLD.store_id AND e.status = 'running' AND e.target_page_id = OLD.page_id)
     AND (TG_OP = 'DELETE' OR NEW.page_id IS DISTINCT FROM OLD.page_id OR NEW.role IS DISTINCT FROM OLD.role) THEN
    RAISE EXCEPTION 'page_roles.experiment: the page is in a running test: stop the test before choosing another page for this place' USING ERRCODE = 'restrict_violation';
  END IF;
  -- Choosing the page already chosen again (an upsert that changes nothing) is not a change.
  IF TG_OP IN ('INSERT', 'UPDATE') AND (TG_OP = 'INSERT' OR NEW.page_id IS DISTINCT FROM OLD.page_id)
     AND NOT EXISTS (SELECT 1 FROM commerce.page_roles r WHERE r.store_id = NEW.store_id AND r.role = NEW.role AND r.page_id = NEW.page_id)
     AND EXISTS (SELECT 1 FROM commerce.experiments e WHERE e.store_id = NEW.store_id AND e.status = 'running' AND e.target_page_id = NEW.page_id) THEN
    RAISE EXCEPTION 'page_roles.experiment: the page is in a running test: stop the test before choosing it for a place of its own' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: page_schedules_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.page_schedules_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.store_id <> OLD.store_id OR NEW.page_id <> OLD.page_id OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'page_schedules.fixed: a schedule stays its page''s' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.status <> 'waiting' AND (NEW.status <> OLD.status OR NEW.publish_at <> OLD.publish_at) THEN
    RAISE EXCEPTION 'page_schedules.settled: a schedule that ran or was cancelled is kept as it ended' USING ERRCODE = 'check_violation';
  END IF;
  -- The way back (D340).
  IF OLD.status <> 'waiting' AND (
    NEW.revert_at IS DISTINCT FROM OLD.revert_at
    OR NEW.before_content IS DISTINCT FROM OLD.before_content
    OR NEW.published_hash IS DISTINCT FROM OLD.published_hash
  ) THEN
    RAISE EXCEPTION 'page_schedules.revert_fixed: the way back is fixed once the publish ran' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.revert_status IN ('done', 'failed', 'cancelled') AND NEW.revert_status IS DISTINCT FROM OLD.revert_status THEN
    RAISE EXCEPTION 'page_schedules.revert_settled: a way back that ran or was cancelled is kept as it ended' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.revert_status IN ('done', 'failed') AND OLD.revert_status = 'waiting' AND NEW.status <> 'done' THEN
    RAISE EXCEPTION 'page_schedules.revert_order: a way back runs only after its publish' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status IN ('failed', 'cancelled') AND NEW.revert_status = 'waiting' THEN
    RAISE EXCEPTION 'page_schedules.revert_orphan: a publish that did not happen has no way back waiting' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: page_theme_detaches_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.page_theme_detaches_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.store_id IS DISTINCT FROM OLD.store_id OR NEW.run_id IS DISTINCT FROM OLD.run_id
     OR NEW.page_id IS DISTINCT FROM OLD.page_id OR NEW.draft_before IS DISTINCT FROM OLD.draft_before
     OR NEW.draft_after IS DISTINCT FROM OLD.draft_after OR NEW.published_before IS DISTINCT FROM OLD.published_before
     OR NEW.published_after IS DISTINCT FROM OLD.published_after OR NEW.followed IS DISTINCT FROM OLD.followed
     OR NEW.kept IS DISTINCT FROM OLD.kept OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR (NEW.created_by IS DISTINCT FROM OLD.created_by AND NEW.created_by IS NOT NULL) THEN
    RAISE EXCEPTION 'page_theme_detaches.fixed: a run of the theme migration keeps what it recorded' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.undone_at IS NOT NULL AND NEW.undone_at IS DISTINCT FROM OLD.undone_at THEN
    RAISE EXCEPTION 'page_theme_detaches.undone: this run was undone already' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: page_versions_fixed(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.page_versions_fixed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  RAISE EXCEPTION 'page_versions.fixed: a page''s version stays as it was kept' USING ERRCODE = 'check_violation';
END;
$$;


--
-- Name: pages_experiment_published_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.pages_experiment_published_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.published_at IS NULL AND OLD.published_at IS NOT NULL AND EXISTS (
    SELECT 1 FROM commerce.experiments e
    LEFT JOIN commerce.experiment_variants v ON v.experiment_id = e.id
    WHERE e.status = 'running' AND (e.target_page_id = OLD.id OR v.page_id = OLD.id)
  ) THEN
    RAISE EXCEPTION 'pages.experiment: a page in a running test stays published' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: pages_experiment_type_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.pages_experiment_type_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.type <> OLD.type AND (
    EXISTS (SELECT 1 FROM commerce.experiments e WHERE e.target_page_id = OLD.id)
    OR EXISTS (SELECT 1 FROM commerce.experiment_variants v WHERE v.page_id = OLD.id)
  ) THEN
    RAISE EXCEPTION 'pages.experiment: a page in a test keeps its kind' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: pages_keep_addresses(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.pages_keep_addresses() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  DELETE FROM commerce.page_redirects r
  WHERE r.slug = NEW.slug AND r.type = NEW.type AND r.store_id IS NOT DISTINCT FROM NEW.store_id;
  IF TG_OP = 'UPDATE' AND NEW.slug <> OLD.slug AND OLD.published_at IS NOT NULL THEN
    INSERT INTO commerce.page_redirects (store_id, type, slug, page_id)
    VALUES (NEW.store_id, NEW.type, OLD.slug, NEW.id)
    ON CONFLICT ON CONSTRAINT page_redirects_store_slug_key DO UPDATE SET page_id = EXCLUDED.page_id, created_at = now();
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: payment_disputes_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.payment_disputes_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_payment record;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'payment_disputes.no_delete: a dispute is part of its order''s history' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'INSERT' THEN
    SELECT p.order_id, p.currency, p.provider INTO v_payment FROM commerce.payments p WHERE p.store_id = NEW.store_id AND p.id = NEW.payment_id;
    IF v_payment.order_id IS DISTINCT FROM NEW.order_id THEN
      RAISE EXCEPTION 'payment_disputes.other_order: the payment is not this order''s' USING ERRCODE = 'check_violation';
    END IF;
    IF v_payment.currency IS DISTINCT FROM NEW.currency THEN
      RAISE EXCEPTION 'payment_disputes.currency: a dispute is in its payment''s currency' USING ERRCODE = 'check_violation';
    END IF;
    IF v_payment.provider IS DISTINCT FROM NEW.provider THEN
      RAISE EXCEPTION 'payment_disputes.provider: a dispute is its payment''s provider''s' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.store_id IS DISTINCT FROM OLD.store_id OR NEW.order_id IS DISTINCT FROM OLD.order_id OR NEW.payment_id IS DISTINCT FROM OLD.payment_id
     OR NEW.provider IS DISTINCT FROM OLD.provider OR NEW.provider_reference IS DISTINCT FROM OLD.provider_reference
     OR NEW.currency IS DISTINCT FROM OLD.currency OR NEW.opened_at IS DISTINCT FROM OLD.opened_at THEN
    RAISE EXCEPTION 'payment_disputes.fixed: what identifies a dispute never changes' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.closed_at IS NOT NULL AND (NEW.closed_at IS DISTINCT FROM OLD.closed_at OR NEW.outcome IS DISTINCT FROM OLD.outcome) THEN
    RAISE EXCEPTION 'payment_disputes.closed: a closed dispute stays as it closed' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.reminded_at IS NOT NULL AND NEW.reminded_at IS DISTINCT FROM OLD.reminded_at THEN
    RAISE EXCEPTION 'payment_disputes.reminded: a reminder is sent once' USING ERRCODE = 'check_violation';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: payment_of_order(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.payment_of_order(p_store uuid, p_payment uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce((
    SELECT p.order_edit_id IS NULL OR EXISTS (
             SELECT 1 FROM commerce.order_edits e
              WHERE e.store_id = p.store_id AND e.id = p.order_edit_id AND e.status = 'applied' AND e.payment_id = p.id)
      FROM commerce.payments p WHERE p.store_id = p_store AND p.id = p_payment
  ), true)
$$;


--
-- Name: payment_on_invoice(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.payment_on_invoice(p_store uuid, p_payment uuid, p_issued_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce((
    SELECT CASE
             WHEN p.order_edit_id IS NOT NULL THEN EXISTS (
               SELECT 1 FROM commerce.order_edits e
                WHERE e.store_id = p.store_id AND e.id = p.order_edit_id AND e.status = 'applied'
                  AND (e.documents = 'in_original'
                       OR EXISTS (SELECT 1 FROM commerce.invoices i WHERE i.store_id = e.store_id AND i.order_edit_id = e.id AND i.kind = 'order_edit')))
             ELSE (p.created_at <= p_issued_at
                   OR EXISTS (SELECT 1 FROM commerce.order_payment_terms t WHERE t.store_id = p.store_id AND t.order_id = p.order_id))
                  AND NOT EXISTS (SELECT 1 FROM commerce.order_events e
                                   WHERE e.store_id = p.store_id AND e.order_id = p.order_id AND e.type = 'booking.no_show' AND e.data ->> 'payment' = p.id::text)
           END
      FROM commerce.payments p WHERE p.store_id = p_store AND p.id = p_payment), true)
$$;


--
-- Name: payments_creator(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.payments_creator() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.order_id IS NOT NULL THEN
    PERFORM commerce.creator_order_paid(NEW.order_id);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: payments_exchange_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.payments_exchange_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  e commerce.return_exchanges%ROWTYPE;
  src commerce.payments%ROWTYPE;
  rf commerce.refunds%ROWTYPE;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.exchange_id IS DISTINCT FROM OLD.exchange_id OR NEW.transfer_refund_id IS DISTINCT FROM OLD.transfer_refund_id THEN
      RAISE EXCEPTION 'payment_exchange.frozen: a payment keeps its exchange and its transfer' USING ERRCODE = 'restrict_violation';
    END IF;
    IF OLD.provider = 'exchange' AND (to_jsonb(NEW) - 'updated_at') IS DISTINCT FROM (to_jsonb(OLD) - 'updated_at') THEN
      RAISE EXCEPTION 'payment_exchange.final: the credit moved to an exchange order is a record' USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.exchange_id IS NULL THEN
    IF NEW.provider = 'exchange' THEN
      RAISE EXCEPTION 'payment_exchange.transfer: an exchange payment names its exchange' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  SELECT * INTO e FROM commerce.return_exchanges x WHERE x.store_id = NEW.store_id AND x.id = NEW.exchange_id;
  IF NOT FOUND OR e.exchange_order_id IS DISTINCT FROM NEW.order_id THEN
    RAISE EXCEPTION 'payment_exchange.order: an exchange''s payment is on the order made for it' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.provider = 'exchange' THEN
    IF coalesce(current_setting('kaizen.exchange', true), '') <> NEW.exchange_id::text THEN
      RAISE EXCEPTION 'payment_exchange.context: an exchange payment is made only by settling its exchange' USING ERRCODE = 'restrict_violation';
    END IF;
    SELECT * INTO rf FROM commerce.refunds x WHERE x.store_id = NEW.store_id AND x.id = NEW.transfer_refund_id;
    IF NOT FOUND OR rf.kind <> 'transfer' OR rf.exchange_id <> NEW.exchange_id THEN
      RAISE EXCEPTION 'payment_exchange.transfer: an exchange payment is paid from a transfer of the same exchange' USING ERRCODE = 'check_violation';
    END IF;
    SELECT * INTO src FROM commerce.payments x WHERE x.store_id = NEW.store_id AND x.id = rf.payment_id;
    IF NEW.status <> 'captured' OR NEW.currency <> src.currency OR NEW.amount_minor <> rf.amount_minor THEN
      RAISE EXCEPTION 'payment_exchange.transfer: an exchange payment is captured, in the transfer''s currency and amount' USING ERRCODE = 'check_violation';
    END IF;
    NEW.provider_account := NULL;
    NEW.kaizen_fee_minor := 0;
    -- A test order's credit stays a test: its exchange order gets no legal invoice number either.
    NEW.test_mode := src.test_mode OR (src.provider_account IS NOT NULL AND EXISTS (
      SELECT 1 FROM commerce.connected_accounts a WHERE a.store_id = src.store_id AND a.account_id = src.provider_account AND a.mode = 'test'));
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: payments_fee_once(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.payments_fee_once() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF OLD.provider_fee_minor IS NOT NULL AND (NEW.provider_fee_minor IS DISTINCT FROM OLD.provider_fee_minor
     OR NEW.application_fee_minor IS DISTINCT FROM OLD.application_fee_minor OR NEW.fee_currency IS DISTINCT FROM OLD.fee_currency) THEN
    RAISE EXCEPTION 'payments.fee_once: a payment''s fee from Stripe is kept as it was read' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: payments_gift_card(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.payments_gift_card() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_payable bigint;
  v_taken bigint;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.provider <> 'gift_card' THEN
      RETURN NULL;
    END IF;
    IF NEW.status NOT IN ('pending', 'captured') THEN
      RAISE EXCEPTION 'payments.gift_card_status: a gift card payment starts held or captured' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.order_edit_id IS NOT NULL OR NEW.exchange_id IS NOT NULL THEN
      RAISE EXCEPTION 'payments.gift_card_purpose: a gift card pays an order at checkout, never a change or an exchange' USING ERRCODE = 'check_violation';
    END IF;
    SELECT o.total_minor - o.balance_minor
           - coalesce((SELECT sum(ol.total_minor) FROM commerce.order_lines ol
                        JOIN commerce.product_variants v ON v.store_id = ol.store_id AND v.id = ol.variant_id
                        JOIN commerce.products p ON p.store_id = v.store_id AND p.id = v.product_id
                       WHERE ol.store_id = o.store_id AND ol.order_id = o.id AND p.kind = 'gift_card'), 0)
      INTO v_payable
      FROM commerce.orders o WHERE o.store_id = NEW.store_id AND o.id = NEW.order_id;
    SELECT coalesce(sum(p.amount_minor), 0) INTO v_taken
      FROM commerce.payments p
     WHERE p.store_id = NEW.store_id AND p.order_id = NEW.order_id AND p.provider = 'gift_card' AND p.status NOT IN ('failed', 'cancelled');
    IF v_taken > coalesce(v_payable, 0) THEN
      RAISE EXCEPTION 'payments.gift_card_over: gift cards pay at most what the order costs online, without its gift cards' USING ERRCODE = 'check_violation';
    END IF;
    PERFORM commerce.gift_card_hold(NEW.store_id, NEW.gift_card_id, NEW.order_id, NEW.currency, NEW.test_mode, NEW.amount_minor, 'hold:' || NEW.id);
    IF NEW.status = 'captured' THEN
      PERFORM commerce.gift_card_spend(NEW.store_id, NEW.gift_card_id, NEW.order_id, 'spend:' || NEW.id);
    END IF;
    RETURN NULL;
  END IF;
  IF OLD.provider <> 'gift_card' AND NEW.provider <> 'gift_card' THEN
    RETURN NULL;
  END IF;
  IF (NEW.provider, NEW.gift_card_id, NEW.order_id, NEW.amount_minor, NEW.currency, NEW.test_mode)
     IS DISTINCT FROM (OLD.provider, OLD.gift_card_id, OLD.order_id, OLD.amount_minor, OLD.currency, OLD.test_mode) THEN
    RAISE EXCEPTION 'payments.gift_card_fixed: a gift card payment''s card, order and amount stay as made' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NULL;
  END IF;
  IF OLD.status <> 'pending' THEN
    RAISE EXCEPTION 'payments.gift_card_settled: a gift card payment that was spent or ended stays so' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status = 'captured' THEN
    PERFORM commerce.gift_card_spend(NEW.store_id, NEW.gift_card_id, NEW.order_id, 'spend:' || NEW.id);
  ELSIF NEW.status IN ('cancelled', 'failed') THEN
    PERFORM commerce.gift_card_release(NEW.store_id, NEW.gift_card_id, NEW.order_id, 'release:' || NEW.id);
  ELSE
    RAISE EXCEPTION 'payments.gift_card_status: a held gift card payment is spent or ended' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: payments_issue_gift_cards(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.payments_issue_gift_cards() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.status = 'captured' AND NEW.order_id IS NOT NULL THEN
    PERFORM commerce.issue_order_gift_cards(NEW.store_id, NEW.order_id);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: payments_referral(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.payments_referral() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.status = 'captured' AND coalesce(NEW.kaizen_fee_minor, 0) > 0
     AND NOT EXISTS (SELECT 1 FROM commerce.orders o WHERE o.store_id = NEW.store_id AND o.id = NEW.order_id AND o.copied_from IS NOT NULL) THEN
    PERFORM commerce.referral_earn(NEW.store_id, NEW.kaizen_fee_minor, NEW.currency, 'sale_fee', NEW.id::text,
                                   'Kaizen''s fee on an order', now());
  END IF;
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'referral commission for payment % failed: %', NEW.id, SQLERRM;
  RETURN NULL;
END;
$$;


--
-- Name: payments_venue_mode(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.payments_venue_mode() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.provider IN ('venue', 'terms', 'gift_card') THEN
    NEW.test_mode := EXISTS (
      SELECT 1 FROM commerce.payment_providers pp WHERE pp.store_id = NEW.store_id AND pp.provider = 'stripe' AND pp.active_mode = 'test');
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: payout_lines_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.payout_lines_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_currency text;
  v_order uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'payout_lines.no_delete: a payout''s line is part of it' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'INSERT' THEN
    SELECT p.currency INTO v_currency FROM commerce.payouts p WHERE p.store_id = NEW.store_id AND p.id = NEW.payout_id;
    IF v_currency IS DISTINCT FROM NEW.currency THEN
      RAISE EXCEPTION 'payout_lines.currency: a line is in its payout''s currency' USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    IF NEW.store_id IS DISTINCT FROM OLD.store_id OR NEW.payout_id IS DISTINCT FROM OLD.payout_id OR NEW.provider_reference IS DISTINCT FROM OLD.provider_reference
       OR NEW.kind IS DISTINCT FROM OLD.kind OR NEW.provider_type IS DISTINCT FROM OLD.provider_type OR NEW.source_reference IS DISTINCT FROM OLD.source_reference
       OR NEW.amount_minor IS DISTINCT FROM OLD.amount_minor OR NEW.fee_minor IS DISTINCT FROM OLD.fee_minor OR NEW.net_minor IS DISTINCT FROM OLD.net_minor
       OR NEW.currency IS DISTINCT FROM OLD.currency OR NEW.provider_created_at IS DISTINCT FROM OLD.provider_created_at THEN
      RAISE EXCEPTION 'payout_lines.fixed: a payout''s line is as Stripe gave it' USING ERRCODE = 'check_violation';
    END IF;
    IF (OLD.payment_id IS NOT NULL AND NEW.payment_id IS DISTINCT FROM OLD.payment_id)
       OR (OLD.refund_id IS NOT NULL AND NEW.refund_id IS DISTINCT FROM OLD.refund_id)
       OR (OLD.dispute_id IS NOT NULL AND NEW.dispute_id IS DISTINCT FROM OLD.dispute_id)
       OR (OLD.order_id IS NOT NULL AND NEW.order_id IS DISTINCT FROM OLD.order_id) THEN
      RAISE EXCEPTION 'payout_lines.tied: a line''s tie is set once' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  -- What it is tied to belongs to the order it names.
  IF NEW.payment_id IS NOT NULL THEN
    SELECT p.order_id INTO v_order FROM commerce.payments p WHERE p.store_id = NEW.store_id AND p.id = NEW.payment_id;
    IF NEW.order_id IS DISTINCT FROM v_order THEN
      RAISE EXCEPTION 'payout_lines.other_order: the payment is not this order''s' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NEW.refund_id IS NOT NULL THEN
    SELECT p.order_id INTO v_order FROM commerce.refunds r JOIN commerce.payments p ON p.store_id = r.store_id AND p.id = r.payment_id
     WHERE r.store_id = NEW.store_id AND r.id = NEW.refund_id;
    IF NEW.order_id IS DISTINCT FROM v_order THEN
      RAISE EXCEPTION 'payout_lines.other_order: the refund is not this order''s' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NEW.dispute_id IS NOT NULL THEN
    SELECT d.order_id INTO v_order FROM commerce.payment_disputes d WHERE d.store_id = NEW.store_id AND d.id = NEW.dispute_id;
    IF NEW.order_id IS DISTINCT FROM v_order THEN
      RAISE EXCEPTION 'payout_lines.other_order: the dispute is not this order''s' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: payouts_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.payouts_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'payouts.no_delete: a payout is the store''s money record' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NEW.store_id IS DISTINCT FROM OLD.store_id OR NEW.provider IS DISTINCT FROM OLD.provider OR NEW.provider_reference IS DISTINCT FROM OLD.provider_reference
       OR NEW.provider_account IS DISTINCT FROM OLD.provider_account OR NEW.currency IS DISTINCT FROM OLD.currency OR NEW.test_mode IS DISTINCT FROM OLD.test_mode
       OR NEW.automatic IS DISTINCT FROM OLD.automatic OR NEW.provider_created_at IS DISTINCT FROM OLD.provider_created_at THEN
      RAISE EXCEPTION 'payouts.fixed: what identifies a payout never changes' USING ERRCODE = 'check_violation';
    END IF;
    NEW.updated_at := now();
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: pickup_options_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.pickup_options_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_place record;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.store_id <> OLD.store_id THEN
    RAISE EXCEPTION 'pickup_options.store_fixed: a pickup option stays with its store' USING ERRCODE = 'check_violation';
  END IF;
  SELECT l.kind, l.country INTO v_place FROM commerce.store_locations l WHERE l.store_id = NEW.store_id AND l.id = NEW.location_id;
  IF v_place.kind IS NULL OR v_place.kind NOT IN ('shop', 'pickup') THEN
    RAISE EXCEPTION 'pickup_options.place_kind: customers collect at a shop or a pickup place, not at the office' USING ERRCODE = 'check_violation';
  END IF;
  IF v_place.country <> NEW.market_code THEN
    RAISE EXCEPTION 'pickup_options.place_country: the place is in %, not in the country %', v_place.country, NEW.market_code USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'INSERT' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('pickup_options:' || NEW.store_id::text, 0));
    IF (SELECT count(*) FROM commerce.pickup_options o WHERE o.store_id = NEW.store_id) >= 20 THEN
      RAISE EXCEPTION 'pickup_options.limit: a store has at most 20 pickup places' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: plan_moves_track(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.plan_moves_track() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_before_currency char(3);
  v_before bigint := 0;
  v_after_currency char(3);
  v_after bigint := 0;
  v_mode text := NEW.mode::text;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    SELECT m.currency, m.minor INTO v_before_currency, v_before FROM commerce.plan_mrr(OLD.status, OLD.price_id) m;
  END IF;
  SELECT m.currency, m.minor INTO v_after_currency, v_after FROM commerce.plan_mrr(NEW.status, NEW.price_id) m;
  v_before := COALESCE(v_before, 0);
  v_after := COALESCE(v_after, 0);
  IF v_before = v_after AND v_before_currency IS NOT DISTINCT FROM v_after_currency THEN
    RETURN NULL;
  END IF;
  IF v_before > 0 AND v_after > 0 AND v_before_currency IS DISTINCT FROM v_after_currency THEN
    INSERT INTO commerce.plan_moves (store_id, kind, plan_id, mode, currency, mrr_before_minor, mrr_after_minor)
    VALUES (NEW.store_id, 'cancelled', OLD.plan_id, COALESCE(OLD.mode::text, v_mode), v_before_currency, v_before, 0);
    INSERT INTO commerce.plan_moves (store_id, kind, plan_id, mode, currency, mrr_before_minor, mrr_after_minor)
    VALUES (NEW.store_id, 'started', NEW.plan_id, v_mode, v_after_currency, 0, v_after);
    RETURN NULL;
  END IF;
  INSERT INTO commerce.plan_moves (store_id, kind, plan_id, mode, currency, mrr_before_minor, mrr_after_minor)
  VALUES (
    NEW.store_id,
    CASE
      WHEN v_before = 0 AND TG_OP = 'UPDATE' AND OLD.status = 'unpaid' THEN 'resumed'
      WHEN v_before = 0 THEN 'started'
      WHEN v_after = 0 AND NEW.status = 'unpaid' THEN 'paused'
      WHEN v_after = 0 THEN 'cancelled'
      WHEN v_after > v_before THEN 'upgraded'
      ELSE 'downgraded'
    END,
    COALESCE(NEW.plan_id, CASE WHEN TG_OP = 'UPDATE' THEN OLD.plan_id END),
    COALESCE(v_mode, CASE WHEN TG_OP = 'UPDATE' THEN OLD.mode::text END),
    COALESCE(v_after_currency, v_before_currency),
    v_before,
    v_after
  );
  RETURN NULL;
END;
$$;


--
-- Name: plan_mrr(text, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.plan_mrr(p_status text, p_price uuid) RETURNS TABLE(currency character, minor bigint)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT pp.currency::char(3), CASE WHEN pp.interval = 'year' THEN round(pp.amount_minor / 12.0)::bigint ELSE pp.amount_minor::bigint END
    FROM commerce.plan_prices pp
   WHERE pp.id = p_price AND p_status IN ('active', 'past_due')
$$;


--
-- Name: platform_menus_are_kaizens(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.platform_menus_are_kaizens() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM commerce.menus m
     WHERE m.id IN (NEW.header_menu_id, NEW.footer_menu_id) AND m.store_id IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'Kaizen''s header and footer can only show Kaizen''s own menus';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: platform_page_role_is_kaizens_page(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.platform_page_role_is_kaizens_page() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM commerce.pages p WHERE p.id = NEW.page_id AND p.store_id IS NULL AND p.type = 'page') THEN
    RAISE EXCEPTION 'platform_page_roles.page: only one of Kaizen''s own pages can have a place on its site' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: platform_plan_events(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.platform_plan_events() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  was_status text := CASE WHEN TG_OP = 'UPDATE' THEN OLD.status END;
  was_plan uuid := CASE WHEN TG_OP = 'UPDATE' THEN OLD.plan_id END;
  was_subscription text := CASE WHEN TG_OP = 'UPDATE' THEN OLD.subscription_id END;
  was_cancelling boolean := CASE WHEN TG_OP = 'UPDATE' THEN OLD.cancel_at_period_end ELSE false END;
  was_on boolean := coalesce(was_status IN ('active', 'trialing', 'past_due'), false);
BEGIN
  IF NEW.status IN ('active', 'trialing')
     AND (NOT was_on OR was_subscription IS DISTINCT FROM NEW.subscription_id) THEN
    PERFORM commerce.queue_platform_event('plan.started', NEW.store_id);
  ELSIF NEW.status IN ('active', 'trialing', 'past_due') AND was_on
     AND was_subscription IS NOT DISTINCT FROM NEW.subscription_id
     AND was_plan IS DISTINCT FROM NEW.plan_id THEN
    PERFORM commerce.queue_platform_event('plan.changed', NEW.store_id);
  END IF;
  IF (NEW.cancel_at_period_end AND NOT was_cancelling AND NEW.status IN ('active', 'trialing', 'past_due'))
     OR (NEW.status = 'canceled' AND was_status IS DISTINCT FROM 'canceled' AND was_on AND NOT was_cancelling) THEN
    PERFORM commerce.queue_platform_event('plan.cancelled', NEW.store_id);
  END IF;
  IF NEW.status IN ('past_due', 'unpaid') AND coalesce(was_status NOT IN ('past_due', 'unpaid'), true) THEN
    PERFORM commerce.queue_platform_event('plan.payment_failed', NEW.store_id);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: platform_report_events(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.platform_report_events() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM commerce.queue_platform_event('report.received', NEW.id);
  RETURN NULL;
END;
$$;


--
-- Name: platform_request_erased(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.platform_request_erased() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  UPDATE commerce.platform_integration_deliveries
  SET payload = NULL,
      status = CASE WHEN status = 'pending' THEN 'failed' ELSE status END,
      last_error = 'Erased'
  WHERE subject_id = NEW.id AND event = 'request.received';
  RETURN NULL;
END;
$$;


--
-- Name: platform_request_events(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.platform_request_events() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT NEW.self_serve THEN
    PERFORM commerce.queue_platform_event('request.received', NEW.id);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: platform_site_from_store(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.platform_site_from_store() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.site_from_store IS DISTINCT FROM OLD.site_from_store THEN
    NEW.site_from_store_at := now();
  END IF;
  IF NEW.site_from_store AND NOT EXISTS (
    SELECT 1 FROM commerce.stores s WHERE s.house AND s.status = 'active' AND NOT s.private_mode
  ) THEN
    RAISE EXCEPTION 'platform_settings.site_from_store: Kaizena Flow''s own store must be open and public to serve the site'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: platform_store_created(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.platform_store_created() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NOT (OLD.sandbox AND NOT NEW.sandbox) THEN
    RETURN NULL;
  END IF;
  IF EXISTS (
    SELECT 1 FROM commerce.stores s
    WHERE s.id = NEW.id AND NOT s.starter AND NOT s.sandbox AND NOT s.is_template AND NOT s.house
  ) THEN
    PERFORM commerce.queue_platform_event('store.created', NEW.id);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: platform_store_opened(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.platform_store_opened() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT NEW.starter AND NOT NEW.sandbox AND NOT NEW.is_template AND NOT NEW.house THEN
    PERFORM commerce.queue_platform_event('store.opened', NEW.id);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: platform_theme_install_updates_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.platform_theme_install_updates_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.install_id IS DISTINCT FROM OLD.install_id
     OR NEW.before IS DISTINCT FROM OLD.before OR NEW.after IS DISTINCT FROM OLD.after OR NEW.kept IS DISTINCT FROM OLD.kept
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR (NEW.from_version_id IS DISTINCT FROM OLD.from_version_id AND NEW.from_version_id IS NOT NULL)
     OR (NEW.to_version_id IS DISTINCT FROM OLD.to_version_id AND NEW.to_version_id IS NOT NULL)
     OR (NEW.updated_by IS DISTINCT FROM OLD.updated_by AND NEW.updated_by IS NOT NULL) THEN
    RAISE EXCEPTION 'platform_theme_install_updates.fixed: an update of a theme keeps what it recorded' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.undone_at IS NOT NULL AND NEW.undone_at IS DISTINCT FROM OLD.undone_at THEN
    RAISE EXCEPTION 'platform_theme_install_updates.undone: this update was undone already' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: platform_theme_installs_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.platform_theme_installs_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.live THEN
      RAISE EXCEPTION 'platform_theme_installs.live: the live theme is not removed; switch to another first' USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.preset_id IS DISTINCT FROM OLD.preset_id
     OR NEW.installed_at IS DISTINCT FROM OLD.installed_at
     OR (NEW.installed_by IS DISTINCT FROM OLD.installed_by AND NEW.installed_by IS NOT NULL) THEN
    RAISE EXCEPTION 'platform_theme_installs.fixed: an install keeps the theme it came from' USING ERRCODE = 'check_violation';
  END IF;
  -- The preset it was added with stays (its key, kept even while a version has no such preset).
  IF NEW.variation IS DISTINCT FROM OLD.variation THEN
    RAISE EXCEPTION 'platform_theme_installs.variation: an install keeps the preset it was added with' USING ERRCODE = 'check_violation';
  END IF;
  -- An update (D253) moves the version, only ever to another version of the install's own theme.
  IF NEW.version_id IS DISTINCT FROM OLD.version_id AND (
       NEW.version_id IS NULL OR NEW.preset_id IS NULL
       OR NOT EXISTS (SELECT 1 FROM commerce.design_preset_versions v WHERE v.id = NEW.version_id AND v.preset_id = NEW.preset_id)
     ) THEN
    RAISE EXCEPTION 'platform_theme_installs.version: an install moves only to another version of its own theme' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: postal_patterns_problem(text[]); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.postal_patterns_problem(p_patterns text[]) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  SELECT CASE
           WHEN p_patterns IS NULL THEN 'postal_patterns.missing'
           WHEN EXISTS (SELECT 1 FROM unnest(p_patterns) p WHERE p IS NULL OR p !~ '^[A-Z0-9-]{1,10}\*?$') THEN 'postal_patterns.malformed'
           WHEN (SELECT count(DISTINCT p) FROM unnest(p_patterns) p) <> cardinality(p_patterns) THEN 'postal_patterns.duplicate'
           WHEN (SELECT coalesce(sum(char_length(p)), 0) FROM unnest(p_patterns) p) > 3000 THEN 'postal_patterns.too_long'
         END
$_$;


--
-- Name: preview_links_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.preview_links_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.page_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM commerce.pages p WHERE p.id = NEW.page_id AND p.store_id = NEW.store_id AND p.type IN ('page', 'article')
    ) THEN
      RAISE EXCEPTION 'preview_links.page: a link opens one of the store''s own pages or articles' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.install_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM commerce.store_theme_installs i WHERE i.id = NEW.install_id AND i.store_id = NEW.store_id
    ) THEN
      RAISE EXCEPTION 'preview_links.install: a link opens one of the store''s own installed themes' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.revoked_at IS NOT NULL OR NEW.revoked_by IS NOT NULL THEN
      RAISE EXCEPTION 'preview_links.new: a link starts open' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.store_id <> OLD.store_id OR NEW.page_id IS DISTINCT FROM OLD.page_id OR NEW.install_id IS DISTINCT FROM OLD.install_id
     OR NEW.token_hash <> OLD.token_hash OR NEW.expires_at <> OLD.expires_at OR NEW.created_at <> OLD.created_at
     OR (NEW.created_by IS DISTINCT FROM OLD.created_by AND NEW.created_by IS NOT NULL) THEN
    RAISE EXCEPTION 'preview_links.fixed: a link stays as it was made' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at THEN
    RAISE EXCEPTION 'preview_links.revoked: a revoked link stays revoked' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.revoked_by IS DISTINCT FROM OLD.revoked_by AND NEW.revoked_by IS NOT NULL AND OLD.revoked_at IS NOT NULL THEN
    RAISE EXCEPTION 'preview_links.revoked: who revoked a link is written when it is revoked' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: price_breaks_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.price_breaks_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.variant_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM commerce.product_variants v WHERE v.store_id = NEW.store_id AND v.id = NEW.variant_id AND v.product_id = NEW.product_id
  ) THEN
    RAISE EXCEPTION 'price_breaks.variant: a break''s variant is one of its product''s' USING ERRCODE = 'check_violation';
  END IF;
  IF (SELECT count(*) FROM commerce.price_breaks b WHERE b.store_id = NEW.store_id AND b.product_id = NEW.product_id AND b.id <> NEW.id) >= 10 THEN
    RAISE EXCEPTION 'price_breaks.max: a product has at most 10 price breaks' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: price_list_breaks_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.price_list_breaks_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF (SELECT count(*) FROM commerce.price_list_breaks b
       WHERE b.store_id = NEW.store_id AND b.list_id = NEW.list_id AND b.variant_id = NEW.variant_id AND b.id <> NEW.id) >= 10 THEN
    RAISE EXCEPTION 'price_list_breaks.max: a variant has at most 10 price breaks in a list' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: price_list_covers(uuid, uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.price_list_covers(p_store uuid, p_list uuid, p_product uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT NOT EXISTS (SELECT 1 FROM commerce.price_list_products s WHERE s.store_id = p_store AND s.list_id = p_list)
      OR EXISTS (SELECT 1 FROM commerce.price_list_products s WHERE s.store_id = p_store AND s.list_id = p_list AND s.product_id = p_product)
      OR EXISTS (
        WITH RECURSIVE picked AS (
          SELECT t.id, t.rules FROM commerce.terms t
          JOIN commerce.price_list_products s ON s.term_id = t.id AND s.store_id = p_store AND s.list_id = p_list
          WHERE t.store_id = p_store
          UNION
          SELECT ch.id, ch.rules FROM commerce.terms ch JOIN picked ON ch.parent_id = picked.id WHERE ch.store_id = p_store
        )
        SELECT 1 FROM picked
        WHERE EXISTS (SELECT 1 FROM commerce.product_terms pt WHERE pt.store_id = p_store AND pt.product_id = p_product AND pt.term_id = picked.id)
           OR (picked.rules IS NOT NULL AND commerce.product_matches_rules(p_store, p_product, picked.rules))
      )
$$;


--
-- Name: prices_bundle_refresh(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.prices_bundle_refresh() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_bundle uuid;
BEGIN
  FOR v_bundle IN
    SELECT bc.bundle_variant_id FROM commerce.bundle_components bc
     WHERE bc.store_id = NEW.store_id AND bc.component_variant_id = NEW.variant_id
  LOOP
    PERFORM commerce.refresh_bundle_prices(v_bundle, NEW.market_code);
  END LOOP;
  RETURN NULL;
END;
$$;


--
-- Name: prior_price(uuid, character, timestamp with time zone); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.prior_price(p_variant_id uuid, p_market_code character, p_at timestamp with time zone) RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT min(amount_minor)
    FROM commerce.prices
   WHERE variant_id = p_variant_id
     AND market_code = p_market_code
     AND valid_from < p_at
     AND coalesce(valid_to, 'infinity'::timestamptz) > p_at - interval '30 days';
$$;


--
-- Name: privacy_requests_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.privacy_requests_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    -- The retention job's one deletion: a request answered more than 24 months ago.
    IF OLD.completed_at IS NULL OR OLD.completed_at >= now() - interval '24 months' THEN
      RAISE EXCEPTION 'privacy_request_kept: a request is kept for 24 months after it was answered' USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN OLD;
  END IF;

  IF TG_OP = 'INSERT' THEN
    -- The clock runs from receipt: one month, the same day of the next month (clamped to its last day).
    NEW.due_at := coalesce(NEW.due_at, NEW.received_at + interval '1 month');
    IF NEW.extended_until IS NOT NULL THEN
      RAISE EXCEPTION 'privacy_request_extension: a request is extended after it is logged, with a reason' USING ERRCODE = 'check_violation';
    END IF;
    NEW.updated_at := now();
    RETURN NEW;
  END IF;

  -- UPDATE
  IF NEW.id <> OLD.id OR NEW.store_id <> OLD.store_id OR NEW.kind <> OLD.kind OR NEW.channel <> OLD.channel
     OR NEW.received_at <> OLD.received_at OR NEW.due_at <> OLD.due_at OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'privacy_request_fixed: a request keeps its store, kind, channel and dates (a mistake is cancelled and logged again)'
      USING ERRCODE = 'check_violation';
  END IF;

  IF OLD.status <> 'open' THEN
    -- An answered request is a record: only the address and the account's id may be forgotten (set to null).
    IF NEW.status <> OLD.status OR NEW.outcome IS DISTINCT FROM OLD.outcome OR NEW.completed_at IS DISTINCT FROM OLD.completed_at
       OR NEW.refusal_reason IS DISTINCT FROM OLD.refusal_reason OR NEW.refusal_note IS DISTINCT FROM OLD.refusal_note
       OR NEW.extended_until IS DISTINCT FROM OLD.extended_until OR NEW.extension_reason IS DISTINCT FROM OLD.extension_reason
       OR (NEW.subject_email IS DISTINCT FROM OLD.subject_email AND NEW.subject_email IS NOT NULL)
       OR (NEW.subject_customer_id IS DISTINCT FROM OLD.subject_customer_id AND NEW.subject_customer_id IS NOT NULL) THEN
      RAISE EXCEPTION 'privacy_request_answered: an answered request is a record and is not changed' USING ERRCODE = 'check_violation';
    END IF;
  ELSIF NEW.extended_until IS DISTINCT FROM OLD.extended_until THEN
    -- Art. 12(3): once, before the month is out, with the reasons.
    IF OLD.extended_until IS NOT NULL THEN
      RAISE EXCEPTION 'privacy_request_extension: a request is extended once' USING ERRCODE = 'check_violation';
    END IF;
    IF now() > OLD.due_at THEN
      RAISE EXCEPTION 'privacy_request_extension: the extension must be told within the first month' USING ERRCODE = 'check_violation';
    END IF;
    IF length(btrim(coalesce(NEW.extension_reason, ''))) = 0 THEN
      RAISE EXCEPTION 'privacy_request_extension: an extension needs its reason' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: product_exclusive(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.product_exclusive(p_store uuid, p_product uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM commerce.price_lists l
    WHERE l.store_id = p_store AND l.exclusive AND l.active
      AND EXISTS (SELECT 1 FROM commerce.price_list_products s WHERE s.store_id = l.store_id AND s.list_id = l.id)
      AND commerce.price_list_covers(p_store, l.id, p_product)
  )
$$;


--
-- Name: product_layout_is_layout(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.product_layout_is_layout() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.product_layout_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM commerce.pages p WHERE p.id = NEW.product_layout_id AND p.type = 'product_layout'
  ) THEN
    RAISE EXCEPTION 'a product layout must be a product layout, not a page or an article';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: product_matches_condition(uuid, uuid, jsonb); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.product_matches_condition(p_store uuid, p_product uuid, c jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $_$
DECLARE
  v_kind text := c ->> 'kind';
  v_hit boolean;
  v_low numeric := CASE WHEN jsonb_typeof(c -> 'min') = 'number' THEN (c ->> 'min')::numeric END;
  v_high numeric := CASE WHEN jsonb_typeof(c -> 'max') = 'number' THEN (c ->> 'max')::numeric END;
BEGIN
  IF v_kind = 'term' THEN
    IF coalesce(c ->> 'termId', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RETURN false; END IF;
    SELECT EXISTS (
      WITH RECURSIVE tree AS (
        SELECT t.id FROM commerce.terms t
        WHERE t.store_id = p_store AND t.content_type = 'product' AND t.id = (c ->> 'termId')::uuid
        UNION
        SELECT ch.id FROM commerce.terms ch JOIN tree ON ch.parent_id = tree.id WHERE ch.store_id = p_store
      )
      SELECT 1 FROM commerce.product_terms pt
      WHERE pt.store_id = p_store AND pt.product_id = p_product AND pt.term_id IN (SELECT id FROM tree)
    ) INTO v_hit;
    RETURN v_hit <> coalesce(c -> 'not' = 'true'::jsonb, false);
  ELSIF v_kind = 'price' THEN
    -- Any active variant priced in the store's own country, as shown with VAT.
    RETURN EXISTS (
      SELECT 1 FROM commerce.product_variants v
      JOIN commerce.current_prices cp ON cp.variant_id = v.id AND cp.store_id = p_store
      WHERE v.product_id = p_product AND v.active AND cp.market_code = commerce.home_market(p_store)
        AND (v_low IS NULL OR cp.amount_minor >= v_low)
        AND (v_high IS NULL OR cp.amount_minor <= v_high)
    );
  ELSIF v_kind = 'inStock' THEN
    -- As `inStockNow()` (src/server/product-conditions.ts): goods in stock now at an active place, or digital; bookings count as available.
    RETURN EXISTS (
      SELECT 1 FROM commerce.products p
      WHERE p.id = p_product AND p.store_id = p_store AND (p.kind <> 'goods' OR EXISTS (
        SELECT 1 FROM commerce.product_variants v
        WHERE v.product_id = p.id AND v.active AND (v.delivery = 'digital' OR EXISTS (
          SELECT 1 FROM commerce.variant_availability va
          WHERE va.store_id = p.store_id AND va.variant_id = v.id AND va.in_stock > 0
        ))
      ))
    );
  ELSIF v_kind = 'manufacturer' THEN
    IF jsonb_typeof(c -> 'ids') <> 'array' THEN RETURN false; END IF;
    RETURN EXISTS (
      SELECT 1 FROM commerce.products p
      WHERE p.id = p_product AND p.store_id = p_store AND p.manufacturer_id IS NOT NULL
        AND p.manufacturer_id::text IN (SELECT jsonb_array_elements_text(c -> 'ids'))
    );
  ELSIF v_kind = 'option' THEN
    -- The option's name and value as the store writes them, without regard to case.
    RETURN EXISTS (
      SELECT 1 FROM commerce.product_variants v
      CROSS JOIN LATERAL jsonb_each_text(CASE WHEN jsonb_typeof(v.options) = 'object' THEN v.options ELSE '{}'::jsonb END) o
      WHERE v.product_id = p_product AND v.active
        AND lower(o.key) = lower(c ->> 'name') AND lower(o.value) = lower(c ->> 'value')
    );
  ELSIF v_kind = 'field' THEN
    -- What was entered in the language-neutral row: a value equal (or held in a list), else a number, or a measurement in the condition's unit, in
    -- the range. The field is one of the store's public filter fields when the rule is saved.
    RETURN EXISTS (
      SELECT 1 FROM commerce.field_values fv
      CROSS JOIN LATERAL (SELECT fv.values -> (c ->> 'fieldId') AS held) h
      WHERE fv.store_id = p_store AND fv.entity = 'product' AND fv.entity_id = p_product AND fv.locale = '' AND h.held IS NOT NULL
        AND CASE
          WHEN jsonb_typeof(c -> 'value') = 'string' THEN
            (jsonb_typeof(h.held) IN ('string', 'number', 'boolean') AND h.held #>> '{}' = c ->> 'value')
            OR (jsonb_typeof(h.held) = 'array' AND h.held ? (c ->> 'value'))
          WHEN v_low IS NULL AND v_high IS NULL THEN false
          ELSE coalesce((
            SELECT (v_low IS NULL OR n >= v_low) AND (v_high IS NULL OR n <= v_high)
            FROM (SELECT CASE
              WHEN jsonb_typeof(h.held) = 'number' THEN (h.held #>> '{}')::numeric
              WHEN jsonb_typeof(h.held) = 'object' AND jsonb_typeof(h.held -> 'value') = 'number'
                AND (jsonb_typeof(c -> 'unit') <> 'string' OR coalesce(h.held ->> 'unit', '') = c ->> 'unit') THEN (h.held ->> 'value')::numeric
            END AS n) x
          ), false)
        END
    );
  ELSIF v_kind = 'kind' THEN
    IF jsonb_typeof(c -> 'values') <> 'array' THEN RETURN false; END IF;
    RETURN EXISTS (
      SELECT 1 FROM commerce.products p
      WHERE p.id = p_product AND p.store_id = p_store AND p.kind IN (SELECT jsonb_array_elements_text(c -> 'values'))
    );
  ELSIF v_kind = 'newWithin' THEN
    IF jsonb_typeof(c -> 'days') <> 'number' THEN RETURN false; END IF;
    RETURN EXISTS (
      SELECT 1 FROM commerce.products p
      WHERE p.id = p_product AND p.store_id = p_store
        AND p.created_at >= now() - make_interval(days => least(greatest((c ->> 'days')::numeric, 1), 365)::int)
    );
  END IF;
  RETURN false;
END
$_$;


--
-- Name: product_matches_rules(uuid, uuid, jsonb); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.product_matches_rules(p_store uuid, p_product uuid, p_rules jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_any boolean := coalesce(p_rules ->> 'match' = 'any', false);
  v_condition jsonb;
  v_hit boolean;
BEGIN
  IF p_rules IS NULL OR jsonb_typeof(p_rules -> 'conditions') <> 'array' OR jsonb_array_length(p_rules -> 'conditions') = 0 THEN RETURN false; END IF;
  IF NOT EXISTS (SELECT 1 FROM commerce.products p WHERE p.id = p_product AND p.store_id = p_store AND p.status = 'active') THEN RETURN false; END IF;
  FOR v_condition IN SELECT value FROM jsonb_array_elements(p_rules -> 'conditions') LOOP
    v_hit := commerce.product_matches_condition(p_store, p_product, v_condition);
    IF v_any AND v_hit THEN RETURN true; END IF;
    IF NOT v_any AND NOT v_hit THEN RETURN false; END IF;
  END LOOP;
  RETURN NOT v_any;
END
$$;


--
-- Name: product_offered(uuid, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.product_offered(p_store uuid, p_product_audience text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT p_product_audience = 'all'
      OR coalesce((SELECT commerce.audience_offered(commerce.store_audience(s.audience, s.features), p_product_audience)
                     FROM commerce.stores s WHERE s.id = p_store), false)
$$;


--
-- Name: product_reviews_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.product_reviews_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  writer text := coalesce(current_setting('kaizen.review_writer', true), '');
  author boolean;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF coalesce(current_setting('kaizen.review_delete', true), '') <> 'on' AND pg_trigger_depth() < 2 THEN
      RAISE EXCEPTION 'product_reviews.delete: a review is deleted only by its author or the person''s erasure' USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF (NEW.source = 'buyer' AND writer <> 'author') OR (NEW.source = 'import' AND writer <> 'import') THEN
      RAISE EXCEPTION 'product_reviews.writer: a review is written only by its buyer or imported' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status = 'hidden' THEN
      RAISE EXCEPTION 'product_reviews.status: a review starts waiting or published' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.source = 'buyer' AND NOT EXISTS (
      SELECT 1 FROM commerce.order_lines l
      JOIN commerce.product_variants v ON v.store_id = l.store_id AND v.id = l.variant_id
      WHERE l.store_id = NEW.store_id AND l.id = NEW.order_line_id AND l.order_id = NEW.order_id
        AND l.variant_id = NEW.variant_id AND v.product_id = NEW.product_id
    ) THEN
      RAISE EXCEPTION 'product_reviews.line: a review is of a line of its order and of a variant of its product' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.moderated_at IS NOT NULL OR NEW.answer IS NOT NULL THEN
      RAISE EXCEPTION 'product_reviews.fresh: a new review has no moderation or answer yet' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE: who and what it is about never changes.
  IF NEW.store_id <> OLD.store_id OR NEW.product_id <> OLD.product_id OR NEW.variant_id IS DISTINCT FROM OLD.variant_id
    OR NEW.source <> OLD.source OR NEW.order_id IS DISTINCT FROM OLD.order_id OR NEW.order_line_id IS DISTINCT FROM OLD.order_line_id
    OR NEW.buyer_key IS DISTINCT FROM OLD.buyer_key OR NEW.customer_id IS DISTINCT FROM OLD.customer_id
    OR NEW.imported_from IS DISTINCT FROM OLD.imported_from OR NEW.written_on IS DISTINCT FROM OLD.written_on
    OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'product_reviews.fixed: a review''s product, order and author are fixed' USING ERRCODE = 'check_violation';
  END IF;

  author := OLD.source = 'buyer' AND coalesce(current_setting('kaizen.review_author', true), '') = OLD.id::text;

  IF NEW.rating <> OLD.rating OR NEW.title IS DISTINCT FROM OLD.title OR NEW.body IS DISTINCT FROM OLD.body
    OR NEW.author_name <> OLD.author_name OR NEW.locale <> OLD.locale OR NEW.edited_at IS DISTINCT FROM OLD.edited_at THEN
    IF NOT author THEN
      RAISE EXCEPTION 'product_reviews.words: only the author changes a review''s stars or words' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF author THEN
    -- The author's write touches only the words and sends the review back to the queue (or keeps it as it was, never shown while hidden).
    IF NEW.moderated_at IS DISTINCT FROM OLD.moderated_at OR NEW.moderated_by IS DISTINCT FROM OLD.moderated_by
      OR NEW.answer IS DISTINCT FROM OLD.answer OR NEW.answered_at IS DISTINCT FROM OLD.answered_at OR NEW.answered_by IS DISTINCT FROM OLD.answered_by THEN
      RAISE EXCEPTION 'product_reviews.author: the author changes only the words' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status <> OLD.status AND NEW.status <> 'pending' THEN
      RAISE EXCEPTION 'product_reviews.status: an edited review goes back to waiting' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status = 'hidden' THEN
      RAISE EXCEPTION 'product_reviews.status: an edited review is checked again' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.status <> OLD.status AND NOT (
    (OLD.status = 'pending' AND NEW.status IN ('published', 'hidden'))
    OR (OLD.status = 'published' AND NEW.status = 'hidden')
    OR (OLD.status = 'hidden' AND NEW.status = 'published')
  ) THEN
    RAISE EXCEPTION 'product_reviews.status: % cannot become %', OLD.status, NEW.status USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status <> OLD.status AND NEW.moderated_at IS NOT DISTINCT FROM OLD.moderated_at THEN
    RAISE EXCEPTION 'product_reviews.moderated: a change of state says when' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: product_search_doc(text, text, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.product_search_doc(p_locale text, p_title text, p_description text) RETURNS tsvector
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
  SELECT setweight(pg_catalog.to_tsvector(commerce.search_config(p_locale), coalesce(p_title, '')), 'A')
      || setweight(pg_catalog.to_tsvector(commerce.search_config(p_locale), coalesce(p_description, '')), 'C')
$$;


--
-- Name: product_terms_not_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.product_terms_not_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM commerce.terms t WHERE t.id = NEW.term_id AND t.rules IS NOT NULL) THEN
    RAISE EXCEPTION 'A collection filled by rules has no products of its own' USING ERRCODE = 'check_violation', HINT = 'product_terms.rules_term';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: product_variants_limit(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.product_variants_limit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_key text := 'kaizen.variants_checked_' || replace(NEW.product_id::text, '-', '');
  v_count integer;
BEGIN
  IF NOT NEW.active OR coalesce(current_setting(v_key, true), '') = 'yes' THEN
    RETURN NULL;
  END IF;
  PERFORM set_config(v_key, 'yes', true);
  SELECT count(*) INTO v_count
    FROM commerce.product_variants v
   WHERE v.store_id = NEW.store_id AND v.product_id = NEW.product_id AND v.active;
  IF v_count > 2048 THEN
    RAISE EXCEPTION 'variants.too_many: a product has at most 2048 variants for sale (this one would have %)', v_count
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: product_variants_refresh_alert(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.product_variants_refresh_alert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM commerce.refresh_stock_alert(NEW.store_id, NEW.id);
  RETURN NULL;
END;
$$;


--
-- Name: products_bundle_on_request(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.products_bundle_on_request() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_variant uuid;
  v_problem text;
  v_bundles text;
BEGIN
  FOR v_variant IN
    SELECT v.id FROM commerce.product_variants v
     WHERE v.store_id = NEW.store_id AND v.product_id = NEW.id
       AND EXISTS (SELECT 1 FROM commerce.bundle_components bc WHERE bc.store_id = v.store_id AND bc.bundle_variant_id = v.id)
  LOOP
    v_problem := commerce.bundle_on_request_problem(v_variant);
    IF v_problem IS NOT NULL THEN
      RAISE EXCEPTION '%', v_problem USING ERRCODE = 'check_violation';
    END IF;
  END LOOP;

  SELECT string_agg(DISTINCT bp.handle, ', ' ORDER BY bp.handle) INTO v_bundles
    FROM commerce.products cp
    JOIN commerce.product_variants cv ON cv.store_id = cp.store_id AND cv.product_id = cp.id
    JOIN commerce.bundle_components bc ON bc.store_id = cv.store_id AND bc.component_variant_id = cv.id
    JOIN commerce.product_variants bv ON bv.store_id = bc.store_id AND bv.id = bc.bundle_variant_id
    JOIN commerce.products bp ON bp.store_id = bv.store_id AND bp.id = bv.product_id
   WHERE cp.store_id = NEW.store_id AND cp.id = NEW.id
     AND cp.price_on_request
     AND bp.bundle_pricing = 'computed';
  IF v_bundles IS NOT NULL THEN
    RAISE EXCEPTION 'products.price_on_request_bundle: a product in a bundle priced from its components cannot be priced on request; give the bundle a price of its own first'
      USING ERRCODE = 'check_violation', DETAIL = v_bundles;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: products_bundle_refresh(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.products_bundle_refresh() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_variant uuid;
BEGIN
  FOR v_variant IN SELECT id FROM commerce.product_variants WHERE store_id = NEW.store_id AND product_id = NEW.id LOOP
    PERFORM commerce.refresh_bundle_prices(v_variant);
  END LOOP;
  RETURN NULL;
END;
$$;


--
-- Name: products_bundle_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.products_bundle_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_variant uuid;
  v_problem text;
BEGIN
  FOR v_variant IN
    SELECT DISTINCT bc.bundle_variant_id
      FROM commerce.bundle_components bc
      JOIN commerce.product_variants v ON v.store_id = bc.store_id AND v.id = bc.bundle_variant_id
     WHERE v.store_id = NEW.store_id AND v.product_id = NEW.id
  LOOP
    v_problem := commerce.bundle_problem(v_variant);
    IF v_problem IS NOT NULL THEN
      RAISE EXCEPTION '%', v_problem USING ERRCODE = 'check_violation';
    END IF;
  END LOOP;
  RETURN NULL;
END;
$$;


--
-- Name: products_first_active(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.products_first_active() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.first_active_at IS NOT NULL THEN
    NEW.first_active_at := OLD.first_active_at;
  ELSIF NEW.status = 'active' AND NEW.first_active_at IS NULL THEN
    NEW.first_active_at := now();
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: products_host_vat(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.products_host_vat() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.host_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM commerce.hosts h
     WHERE h.store_id = NEW.store_id AND h.id = NEW.host_id AND NOT h.vat_registered
  ) THEN
    NEW.vat_category := 'exempt';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: products_leave_redirect(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.products_leave_redirect() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.handle IS DISTINCT FROM OLD.handle AND (OLD.status <> 'draft' OR OLD.first_active_at IS NOT NULL) THEN
    DELETE FROM commerce.redirects r WHERE r.store_id = NEW.store_id AND r.source = '/p/' || OLD.handle AND r.kind <> 'manual';
    INSERT INTO commerce.redirects (store_id, kind, source, product_id, origin)
    VALUES (NEW.store_id, 'product', '/p/' || OLD.handle, NEW.id, 'system')
    ON CONFLICT ON CONSTRAINT redirects_store_source_key DO NOTHING;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: products_taken_address(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.products_taken_address() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  DELETE FROM commerce.redirects r WHERE r.store_id = NEW.store_id AND r.source = '/p/' || NEW.handle AND r.kind <> 'manual';
  RETURN NULL;
END;
$$;


--
-- Name: purge_sandbox(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.purge_sandbox(p_sandbox uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
DECLARE
  v_store uuid;
  v_table text;
  v_left text[];
  v_count integer;
  v_round_count integer;
  v_total integer := 0;
  v_round integer := 0;
BEGIN
  SELECT x.store_id INTO v_store
    FROM commerce.sandboxes x JOIN commerce.stores s ON s.id = x.store_id
   WHERE x.id = p_sandbox AND x.state = 'expired' AND s.sandbox AND s.status = 'closed'
     FOR UPDATE OF x;
  IF v_store IS NULL THEN
    RAISE EXCEPTION 'sandboxes.not_expired: only an expired sandbox is purged' USING ERRCODE = 'check_violation';
  END IF;
  PERFORM set_config('commerce.sandbox_purge', v_store::text, true);
  LOOP
    v_round := v_round + 1;
    v_round_count := 0;
    v_left := '{}';
    FOR v_table IN
      SELECT c.relname::text
        FROM pg_catalog.pg_class c
        JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace AND n.nspname = 'commerce'
        JOIN pg_catalog.pg_attribute a ON a.attrelid = c.oid AND a.attname = 'store_id' AND NOT a.attisdropped
       WHERE c.relkind IN ('r', 'p') AND NOT c.relispartition AND c.relname NOT IN ('sandboxes', 'ai_usage')
       ORDER BY c.relname
    LOOP
      BEGIN
        EXECUTE format('DELETE FROM commerce.%I WHERE store_id = $1', v_table) USING v_store;
        GET DIAGNOSTICS v_count = ROW_COUNT;
        v_round_count := v_round_count + v_count;
      EXCEPTION WHEN foreign_key_violation THEN
        v_left := v_left || v_table;
      END;
    END LOOP;
    v_total := v_total + v_round_count;
    EXIT WHEN cardinality(v_left) = 0 AND v_round_count = 0;
    IF v_round_count = 0 OR v_round >= 20 THEN
      RAISE EXCEPTION 'sandboxes.purge_stuck: rows of % are still pointed at', array_to_string(v_left, ', ') USING ERRCODE = 'foreign_key_violation';
    END IF;
  END LOOP;
  UPDATE commerce.stores
     SET custom_css = '', theme = '{}'::jsonb, front_page_id = NULL, products_page_id = NULL, header_menu_id = NULL, footer_menu_id = NULL
   WHERE id = v_store;
  PERFORM set_config('commerce.sandbox_purge', '', true);
  UPDATE commerce.sandboxes SET state = 'purged', purged_at = now() WHERE id = p_sandbox;
  RETURN v_total;
END;
$_$;


--
-- Name: quantity_rule(uuid, uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.quantity_rule(p_store uuid, p_customer uuid, p_variant uuid) RETURNS TABLE(min_quantity integer, max_quantity integer, quantity_step integer, list_id uuid)
    LANGUAGE sql STABLE ROWS 1
    SET search_path TO ''
    AS $$
  SELECT r.min_quantity, r.max_quantity, r.quantity_step, r.list_id
  FROM (
    SELECT q.min_quantity, q.max_quantity, q.quantity_step, q.list_id, 0 AS rank
      FROM commerce.buyer_lists(p_store, p_customer) AS mine(id)
      JOIN commerce.price_list_quantity_rules q ON q.store_id = p_store AND q.list_id = mine.id AND q.variant_id = p_variant
     WHERE p_customer IS NOT NULL
    UNION ALL
    SELECT v.min_quantity, v.max_quantity, v.quantity_step, NULL::uuid, 1
      FROM commerce.product_variants v
     WHERE v.store_id = p_store AND v.id = p_variant
  ) r
  ORDER BY r.rank, r.min_quantity, r.max_quantity DESC NULLS FIRST, r.quantity_step, r.list_id
  LIMIT 1
$$;


--
-- Name: queue_integration_event(uuid, text, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.queue_integration_event(p_store uuid, p_event text, p_subject uuid) RETURNS void
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  INSERT INTO commerce.integration_deliveries (store_id, provider, event, subject_id)
  SELECT i.store_id, i.provider, p_event, p_subject
  FROM commerce.store_integrations i
  WHERE i.store_id = p_store AND i.enabled AND p_event = ANY (i.events);
  -- A delivery not yet built carries the subject as it is when it is sent, so a second change of the same subject before then (a product
  -- saved twice, a product made and then saved in one transaction, a variant's stock moved twice within its minute) needs no delivery of
  -- its own.
  INSERT INTO commerce.integration_deliveries (store_id, provider, event, subject_id, endpoint_id, next_attempt_at)
  SELECT e.store_id, 'webhook', p_event, p_subject, e.id,
    CASE WHEN p_event = 'inventory.updated' THEN date_trunc('minute', now()) + interval '1 minute' ELSE now() END
  FROM commerce.webhook_endpoints e
  WHERE e.store_id = p_store AND e.enabled AND p_event = ANY (e.topics)
    AND NOT (p_subject IS NOT NULL AND EXISTS (
      SELECT 1 FROM commerce.integration_deliveries d
      WHERE d.endpoint_id = e.id AND d.subject_id = p_subject AND d.status = 'pending' AND d.payload IS NULL
        AND (d.event = p_event OR (p_event = 'product.updated' AND d.event = 'product.created'))
    ));
  INSERT INTO commerce.workflow_runs (store_id, workflow_id, event, subject_id, event_key, status)
  SELECT w.store_id, w.id, p_event, p_subject, p_event || ':' || coalesce(p_subject::text, '-') || ':' || txid_current()::text,
    CASE WHEN (SELECT count(*) FROM commerce.workflow_runs r WHERE r.workflow_id = w.id AND r.created_at > now() - interval '1 hour') >= 100
      THEN 'capped' ELSE 'pending' END
  FROM commerce.workflows w
  WHERE w.store_id = p_store AND w.enabled AND w.trigger = p_event
  ON CONFLICT ON CONSTRAINT workflow_runs_once_key DO NOTHING;
$$;


--
-- Name: queue_platform_event(text, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.queue_platform_event(p_event text, p_subject uuid) RETURNS void
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  INSERT INTO commerce.platform_integration_deliveries (provider, event, subject_id)
  SELECT i.provider, p_event, p_subject
  FROM commerce.platform_integrations i
  WHERE i.enabled AND p_event = ANY (i.events);
  INSERT INTO commerce.platform_integration_deliveries (provider, event, subject_id, endpoint_id)
  SELECT 'webhook', p_event, p_subject, e.id
  FROM commerce.platform_webhook_endpoints e
  WHERE e.enabled AND p_event = ANY (e.topics);
  INSERT INTO commerce.platform_workflow_runs (workflow_id, event, subject_id, event_key, status)
  SELECT w.id, p_event, p_subject, p_event || ':' || coalesce(p_subject::text, '-') || ':' || txid_current()::text,
    CASE WHEN (SELECT count(*) FROM commerce.platform_workflow_runs r WHERE r.workflow_id = w.id AND r.created_at > now() - interval '1 hour') >= 100
      THEN 'capped' ELSE 'pending' END
  FROM commerce.platform_workflows w
  WHERE w.enabled AND w.trigger = p_event
  ON CONFLICT ON CONSTRAINT platform_workflow_runs_once_key DO NOTHING;
$$;


--
-- Name: queue_store_event(uuid, text, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.queue_store_event(p_store uuid, p_event text, p_subject uuid) RETURNS void
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  INSERT INTO commerce.store_events (store_id, event, subject_id)
  VALUES (p_store, p_event, p_subject)
  ON CONFLICT ON CONSTRAINT store_events_once_key DO NOTHING
$$;


--
-- Name: record_carrier_delivery(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.record_carrier_delivery(p_store uuid, p_order uuid, p_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_order record;
  v_latest timestamptz;
  v_carrier text;
  v_missing integer;
  v_at timestamptz;
BEGIN
  SELECT o.id, o.status::text AS status, o.copied_from, o.delivered_at, o.placed_at INTO v_order
    FROM commerce.orders o WHERE o.store_id = p_store AND o.id = p_order FOR UPDATE;
  IF v_order IS NULL OR v_order.copied_from IS NOT NULL OR v_order.delivered_at IS NOT NULL OR v_order.status <> 'fulfilled' THEN
    RETURN false;
  END IF;
  SELECT count(*) FILTER (WHERE t.delivered_at IS NULL)::integer, max(t.delivered_at)
    INTO v_missing, v_latest
    FROM commerce.shipments s
    LEFT JOIN commerce.shipment_tracking t ON t.store_id = s.store_id AND t.shipment_id = s.id
   WHERE s.store_id = p_store AND s.order_id = p_order AND s.undone_at IS NULL;
  IF v_latest IS NULL OR v_missing > 0 THEN
    RETURN false;
  END IF;
  SELECT t.carrier INTO v_carrier
    FROM commerce.shipment_tracking t JOIN commerce.shipments s ON s.store_id = t.store_id AND s.id = t.shipment_id
   WHERE t.store_id = p_store AND t.order_id = p_order AND s.undone_at IS NULL
   ORDER BY t.delivered_at DESC LIMIT 1;
  v_at := least(greatest(v_latest, coalesce(p_at, v_latest), v_order.placed_at), now());

  PERFORM set_config('kaizen.carrier_delivery', p_order::text, true);
  UPDATE commerce.orders SET delivered_at = v_at, delivered_source = 'carrier' WHERE store_id = p_store AND id = p_order;
  PERFORM set_config('kaizen.carrier_delivery', '', true);

  INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
  VALUES (p_store, p_order, 'order.delivered', jsonb_build_object('by', 'carrier', 'carrier', v_carrier, 'at', v_at), 'system');
  RETURN true;
END;
$$;


--
-- Name: record_inventory_movement(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.record_inventory_movement() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_store uuid;
  v_variant uuid;
  v_location uuid;
  v_delta integer;
  v_after integer;
  v_ctx jsonb;
  v_raw text;
  v_reason text;
  v_source text;
  v_note text;
  v_account uuid;
  v_order uuid;
  v_return uuid;
  v_job uuid;
BEGIN
  IF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN
    v_store := NEW.store_id; v_variant := NEW.variant_id; v_location := NEW.location_id;
    v_after := NEW.on_hand;
    v_delta := NEW.on_hand - CASE WHEN TG_OP = 'UPDATE' THEN OLD.on_hand ELSE 0 END;
  ELSE
    -- The level was removed: what it held leaves with it.
    v_store := OLD.store_id; v_variant := OLD.variant_id; v_location := OLD.location_id;
    v_delta := -OLD.on_hand; v_after := 0;
  END IF;
  -- A write that changes nothing is not a movement.
  IF v_delta = 0 THEN RETURN NULL; END IF;

  -- Why: a context that cannot be read is no context, never an error.
  BEGIN
    v_raw := current_setting('kaizen.stock', true);
    IF v_raw IS NOT NULL AND v_raw <> '' THEN v_ctx := v_raw::jsonb; END IF;
    IF v_ctx IS NOT NULL AND jsonb_typeof(v_ctx) <> 'object' THEN v_ctx := NULL; END IF;
  EXCEPTION WHEN OTHERS THEN
    v_ctx := NULL;
  END;
  v_reason := v_ctx ->> 'reason';
  v_source := v_ctx ->> 'source';
  IF v_reason IS NULL OR v_reason NOT IN ('received', 'correction', 'count', 'damaged', 'lost', 'promotion', 'sale',
                                         'order_restock', 'return_restock', 'opening', 'system', 'transfer_out', 'transfer_in') THEN
    v_reason := CASE WHEN TG_OP = 'INSERT' THEN 'opening' ELSE 'correction' END;
    v_source := 'system';
  ELSIF v_source IS NULL OR v_source NOT IN ('inventory_page', 'editor', 'bulk', 'file', 'order', 'return', 'checkout',
                                            'ai_manager', 'copy', 'system', 'order_edit', 'exchange', 'api', 'transfer', 'purchase_order') THEN
    v_source := 'system';
  END IF;
  v_account := commerce.stock_context_uuid(v_ctx, 'account');
  v_order := commerce.stock_context_uuid(v_ctx, 'order');
  v_return := commerce.stock_context_uuid(v_ctx, 'return');
  v_job := commerce.stock_context_uuid(v_ctx, 'job');
  v_note := left(nullif(btrim(coalesce(v_ctx ->> 'note', '')), ''), 200);

  BEGIN
    INSERT INTO commerce.inventory_movements (store_id, variant_id, location_id, delta, on_hand_after, reason, source,
                                              actor_account_id, order_id, return_id, job_id, note)
    VALUES (v_store, v_variant, v_location, v_delta, v_after, v_reason, v_source, v_account, v_order, v_return, v_job, v_note);
  EXCEPTION WHEN foreign_key_violation THEN
    -- An order or a return in the context that is not this store's: record the change without it, rather than stop a payment.
    RAISE WARNING 'inventory movement without its context: %', SQLERRM;
    INSERT INTO commerce.inventory_movements (store_id, variant_id, location_id, delta, on_hand_after, reason, source)
    VALUES (v_store, v_variant, v_location, v_delta, v_after,
            CASE WHEN TG_OP = 'INSERT' THEN 'opening' ELSE 'correction' END, 'system');
  END;

  PERFORM commerce.refresh_stock_alert(v_store, v_variant);
  RETURN NULL;
END;
$$;


--
-- Name: record_not_found(uuid, text, boolean, integer); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.record_not_found(p_store uuid, p_path text, p_crawler boolean, p_cap integer) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_day date := (now() AT TIME ZONE 'utc')::date;
  v_crawler integer := CASE WHEN p_crawler THEN 1 ELSE 0 END;
  v_distinct integer;
BEGIN
  IF p_path IS NULL THEN
    RAISE EXCEPTION 'not_found.path: an address is needed' USING ERRCODE = 'check_violation';
  END IF;
  UPDATE commerce.not_found_hits h
     SET hits = h.hits + 1, crawler_hits = h.crawler_hits + v_crawler, last_seen_at = now()
   WHERE h.store_id = p_store AND h.day = v_day AND h.path = p_path;
  IF FOUND THEN RETURN; END IF;

  SELECT count(*)::integer INTO v_distinct
    FROM commerce.not_found_hits h
   WHERE h.store_id = p_store AND h.day = v_day AND h.path IS NOT NULL;

  INSERT INTO commerce.not_found_hits (store_id, day, path, hits, crawler_hits)
  VALUES (p_store, v_day, CASE WHEN v_distinct < p_cap THEN p_path ELSE NULL END, 1, v_crawler)
  ON CONFLICT ON CONSTRAINT not_found_hits_key
  DO UPDATE SET hits = commerce.not_found_hits.hits + 1,
                crawler_hits = commerce.not_found_hits.crawler_hits + v_crawler,
                last_seen_at = now();
END;
$$;


--
-- Name: redirect_path_of(text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.redirect_path_of(p_target text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  SELECT CASE
    WHEN p ~ '^/+$' THEN '/'
    ELSE regexp_replace(p, '/+$', '')
  END
  FROM (SELECT lower(split_part(split_part(p_target, '#', 1), '?', 1)) AS p) q
$_$;


--
-- Name: redirects_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.redirects_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- An automatic redirect is the address of a thing of this store, in the shape its kind has.
    IF NEW.kind = 'product' AND left(NEW.source, 3) <> '/p/' THEN
      RAISE EXCEPTION 'redirect.source: a product redirect is from /p/{handle}' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.kind = 'category' AND left(NEW.source, 10) <> '/category/' THEN
      RAISE EXCEPTION 'redirect.source: a category redirect is from /category/{slug}' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.kind = 'tag' AND left(NEW.source, 5) <> '/tag/' THEN
      RAISE EXCEPTION 'redirect.source: a tag redirect is from /tag/{slug}' USING ERRCODE = 'check_violation';
    END IF;
    -- A term's key is (store, content type, id) and a redirect's store and kind must be the term's own.
    IF NEW.term_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM commerce.terms t
       WHERE t.id = NEW.term_id AND t.store_id = NEW.store_id AND t.content_type = 'product' AND t.kind = NEW.kind
    ) THEN
      RAISE EXCEPTION 'redirect.entity: the category or tag is not one of this store''s product terms of this kind' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE
  IF NEW.id <> OLD.id OR NEW.store_id <> OLD.store_id OR NEW.kind <> OLD.kind
     OR NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'redirect.fixed: a redirect keeps its store, kind and maker' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.kind <> 'manual' AND (
       NEW.source <> OLD.source OR NEW.target IS DISTINCT FROM OLD.target OR NEW.product_id IS DISTINCT FROM OLD.product_id
       OR NEW.term_id IS DISTINCT FROM OLD.term_id OR NEW.origin <> OLD.origin) THEN
    RAISE EXCEPTION 'redirect.automatic: an automatic redirect follows its product, category or tag and is only deleted' USING ERRCODE = 'check_violation';
  END IF;
  -- Counting a request is not a change of the redirect.
  IF NEW.source <> OLD.source OR NEW.target IS DISTINCT FROM OLD.target OR NEW.origin <> OLD.origin THEN
    NEW.updated_at := now();
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: redirects_no_loop(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.redirects_no_loop() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_cur text;
  v_next text;
  v_hops integer := 0;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('redirects:' || NEW.store_id::text, 0));
  v_cur := commerce.redirect_path_of(NEW.target);
  WHILE v_hops <= 20 LOOP
    IF v_cur = NEW.source THEN
      RAISE EXCEPTION 'redirect.loop: this redirect would lead back to its own address' USING ERRCODE = 'check_violation';
    END IF;
    v_next := NULL;
    SELECT commerce.redirect_path_of(r.target) INTO v_next
      FROM commerce.redirects r
     WHERE r.store_id = NEW.store_id AND r.kind = 'manual' AND r.source = v_cur AND r.id <> NEW.id;
    EXIT WHEN v_next IS NULL;
    v_cur := v_next;
    v_hops := v_hops + 1;
  END LOOP;
  RETURN NEW;
END;
$$;


--
-- Name: referral_adjust(uuid, character, bigint, text, uuid, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.referral_adjust(p_account uuid, p_currency character, p_amount bigint, p_note text, p_by uuid, p_key text) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF p_amount = 0 THEN
    RAISE EXCEPTION 'referral.zero';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM commerce.referrers r WHERE r.account_id = p_account) THEN
    RAISE EXCEPTION 'referral.no_referrer';
  END IF;
  IF p_amount > 0 THEN
    PERFORM commerce.referral_grant(p_account, p_currency, 'adjust', p_amount, 'adjust', p_key, NULL, NULL, now(), p_note, p_by, p_key);
    RETURN p_amount;
  END IF;
  RETURN -commerce.referral_take(p_account, p_currency, 'adjust', -p_amount, 'any', NULL, 'adjust', p_key, NULL, NULL, p_note, p_by, p_key, true);
END;
$$;


--
-- Name: referral_allocation_within_lot(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.referral_allocation_within_lot() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_lot commerce.referral_entries%ROWTYPE;
  v_entry commerce.referral_entries%ROWTYPE;
  v_taken bigint;
BEGIN
  SELECT * INTO v_lot FROM commerce.referral_entries WHERE id = NEW.lot_id;
  SELECT * INTO v_entry FROM commerce.referral_entries WHERE id = NEW.entry_id;
  IF v_lot.amount_minor IS NULL OR v_entry.amount_minor IS NULL OR v_lot.amount_minor <= 0 OR v_entry.amount_minor >= 0
     OR v_lot.account_id <> v_entry.account_id OR v_lot.currency <> v_entry.currency THEN
    RAISE EXCEPTION 'referral.bad_allocation' USING ERRCODE = 'check_violation';
  END IF;
  SELECT coalesce(sum(a.amount_minor), 0) INTO v_taken FROM commerce.referral_allocations a WHERE a.lot_id = NEW.lot_id;
  IF v_taken > v_lot.amount_minor THEN
    RAISE EXCEPTION 'referral.below_zero' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: referral_apply_invoice(uuid, character, text, bigint); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.referral_apply_invoice(p_account uuid, p_currency character, p_invoice_ref text, p_max bigint) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_held bigint;
  v_n integer;
BEGIN
  PERFORM commerce.referral_lock(p_account);
  v_held := commerce.referral_invoice_held(p_account, p_currency, p_invoice_ref);
  IF v_held > 0 THEN
    RETURN v_held;
  END IF;
  IF p_max <= 0 OR EXISTS (SELECT 1 FROM commerce.referrers r WHERE r.account_id = p_account AND r.blocked_at IS NOT NULL) THEN
    RETURN 0;
  END IF;
  SELECT count(*) INTO v_n FROM commerce.referral_entries e
   WHERE e.account_id = p_account AND e.currency = p_currency AND e.invoice_ref = p_invoice_ref AND e.kind = 'apply';
  RETURN commerce.referral_take(p_account, p_currency, 'apply', p_max, 'available', NULL, 'invoice', p_invoice_ref, NULL, p_invoice_ref,
                                'Put on invoice ' || p_invoice_ref, NULL, 'apply:' || p_invoice_ref || ':' || v_n);
END;
$$;


--
-- Name: referral_balance(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.referral_balance(p_account uuid) RETURNS TABLE(currency character, available_minor bigint, pending_minor bigint, pending_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT c.currency,
         coalesce(sum(l.remaining) FILTER (WHERE l.available_at <= now()), 0)::bigint,
         coalesce(sum(l.remaining) FILTER (WHERE l.available_at > now()), 0)::bigint,
         min(l.available_at) FILTER (WHERE l.available_at > now() AND l.remaining > 0)
    FROM (SELECT DISTINCT e.currency FROM commerce.referral_entries e WHERE e.account_id = p_account) c
    CROSS JOIN LATERAL commerce.referral_lots(p_account, c.currency) l
   WHERE l.remaining > 0
   GROUP BY c.currency
$$;


--
-- Name: referral_earn(uuid, bigint, character, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.referral_earn(p_store uuid, p_fee_minor bigint, p_currency character, p_source_kind text, p_source_ref text, p_note text, p_at timestamp with time zone DEFAULT now()) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_ref commerce.referrals%ROWTYPE;
  v_program record;
  v_earn bigint;
  v_id uuid;
BEGIN
  SELECT * INTO v_ref FROM commerce.referrals r WHERE r.store_id = p_store;
  IF NOT FOUND OR v_ref.status <> 'active' OR p_fee_minor IS NULL OR p_fee_minor <= 0 THEN
    RETURN 0;
  END IF;
  SELECT e.amount_minor INTO v_earn FROM commerce.referral_entries e WHERE e.idempotency_key = p_source_kind || ':' || p_source_ref;
  IF FOUND THEN
    RETURN v_earn;
  END IF;
  SELECT * INTO v_program FROM commerce.referral_program();
  IF NOT v_program.enabled THEN
    RETURN 0;
  END IF;
  IF p_at < v_ref.created_at OR p_at >= v_ref.created_at + make_interval(months => v_ref.months) THEN
    RETURN 0;
  END IF;
  IF EXISTS (SELECT 1 FROM commerce.referrers r WHERE r.account_id = v_ref.referrer_account_id AND r.blocked_at IS NOT NULL) THEN
    RETURN 0;
  END IF;
  v_earn := floor(p_fee_minor::numeric * v_ref.commission_bps / 10000)::bigint;
  IF v_earn <= 0 THEN
    RETURN 0;
  END IF;
  v_id := commerce.referral_grant(v_ref.referrer_account_id, p_currency, 'earn', v_earn, p_source_kind, p_source_ref, v_ref.id,
                                  NULL, p_at + make_interval(days => v_program.pending_days), p_note, NULL,
                                  p_source_kind || ':' || p_source_ref);
  RETURN CASE WHEN v_id IS NULL THEN 0 ELSE v_earn END;
END;
$$;


--
-- Name: referral_entry_fully_allocated(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.referral_entry_fully_allocated() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_taken bigint;
BEGIN
  IF NEW.amount_minor < 0 THEN
    SELECT coalesce(sum(a.amount_minor), 0) INTO v_taken FROM commerce.referral_allocations a WHERE a.entry_id = NEW.id;
    IF v_taken <> -NEW.amount_minor THEN
      RAISE EXCEPTION 'referral.below_zero' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: referral_grant(uuid, character, text, bigint, text, text, uuid, text, timestamp with time zone, text, uuid, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.referral_grant(p_account uuid, p_currency character, p_kind text, p_amount bigint, p_source_kind text, p_source_ref text, p_referral uuid, p_invoice_ref text, p_available_at timestamp with time zone, p_note text, p_by uuid, p_key text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_id uuid;
BEGIN
  PERFORM commerce.referral_lock(p_account);
  SELECT e.id INTO v_id FROM commerce.referral_entries e WHERE e.idempotency_key = p_key;
  IF FOUND THEN
    RETURN v_id;
  END IF;
  IF p_amount <= 0 THEN
    RETURN NULL;
  END IF;
  INSERT INTO commerce.referral_entries (
    account_id, currency, kind, amount_minor, source_kind, source_ref, referral_id, invoice_ref, available_at, note,
    created_by, idempotency_key
  ) VALUES (
    p_account, p_currency, p_kind, p_amount, p_source_kind, p_source_ref, p_referral, p_invoice_ref, p_available_at,
    left(coalesce(p_note, ''), 500), p_by, p_key
  ) RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: referral_invoice_held(uuid, character, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.referral_invoice_held(p_account uuid, p_currency character, p_invoice_ref text) RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce(-sum(e.amount_minor), 0)::bigint FROM commerce.referral_entries e
   WHERE e.account_id = p_account AND e.currency = p_currency AND e.invoice_ref = p_invoice_ref AND e.kind IN ('apply', 'restore')
$$;


--
-- Name: referral_ledger_immutable(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.referral_ledger_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF TG_TABLE_NAME = 'referral_entries' THEN
      IF NOT EXISTS (SELECT 1 FROM commerce.accounts a WHERE a.id = OLD.account_id) THEN
        RETURN OLD;
      END IF;
    ELSIF NOT EXISTS (SELECT 1 FROM commerce.referral_entries e WHERE e.id = OLD.entry_id) THEN
      -- An allocation goes with the entry that took the credit.
      RETURN OLD;
    END IF;
  END IF;
  RAISE EXCEPTION 'commerce.% is append-only; % is not allowed', TG_TABLE_NAME, TG_OP
    USING ERRCODE = 'restrict_violation';
END;
$$;


--
-- Name: referral_lock(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.referral_lock(p_account uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('kaizen:referral:' || p_account::text, 0));
END;
$$;


--
-- Name: referral_lots(uuid, character); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.referral_lots(p_account uuid, p_currency character) RETURNS TABLE(id uuid, amount_minor bigint, remaining bigint, available_at timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT e.id, e.amount_minor,
         (e.amount_minor - coalesce((SELECT sum(a.amount_minor) FROM commerce.referral_allocations a WHERE a.lot_id = e.id), 0))::bigint,
         e.available_at, e.created_at
    FROM commerce.referral_entries e
   WHERE e.account_id = p_account AND e.currency = p_currency AND e.amount_minor > 0
$$;


--
-- Name: referral_program(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.referral_program() RETURNS TABLE(enabled boolean, commission_bps integer, months integer, pending_days integer, cookie_days integer)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce(s.enabled, false), coalesce(s.commission_bps, 1000), coalesce(s.months, 12),
         coalesce(s.pending_days, 30), coalesce(s.cookie_days, 30)
    FROM (SELECT 1) one LEFT JOIN commerce.referral_settings s ON true
$$;


--
-- Name: referral_restore_invoice(text, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.referral_restore_invoice(p_invoice_ref text, p_note text) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_row record;
  v_held bigint;
  v_n integer;
  v_total bigint := 0;
BEGIN
  FOR v_row IN
    SELECT e.account_id, e.currency FROM commerce.referral_entries e
     WHERE e.invoice_ref = p_invoice_ref AND e.kind IN ('apply', 'restore') GROUP BY e.account_id, e.currency
  LOOP
    PERFORM commerce.referral_lock(v_row.account_id);
    v_held := commerce.referral_invoice_held(v_row.account_id, v_row.currency, p_invoice_ref);
    IF v_held > 0 THEN
      SELECT count(*) INTO v_n FROM commerce.referral_entries e
       WHERE e.account_id = v_row.account_id AND e.currency = v_row.currency AND e.invoice_ref = p_invoice_ref AND e.kind = 'restore';
      PERFORM commerce.referral_grant(v_row.account_id, v_row.currency, 'restore', v_held, 'invoice', p_invoice_ref, NULL,
                                      p_invoice_ref, now(), p_note, NULL, 'restore:' || p_invoice_ref || ':' || v_n);
      v_total := v_total + v_held;
    END IF;
  END LOOP;
  RETURN v_total;
END;
$$;


--
-- Name: referral_reverse(text, text, bigint, bigint, boolean, text, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.referral_reverse(p_source_kind text, p_source_ref text, p_num bigint, p_den bigint, p_cumulative boolean, p_key text, p_note text) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_lot commerce.referral_entries%ROWTYPE;
  v_done bigint;
  v_target bigint;
  v_amount bigint;
BEGIN
  SELECT * INTO v_lot FROM commerce.referral_entries e
   WHERE e.idempotency_key = p_source_kind || ':' || p_source_ref AND e.amount_minor > 0;
  IF NOT FOUND OR p_den <= 0 OR p_num <= 0 THEN
    RETURN 0;
  END IF;
  PERFORM commerce.referral_lock(v_lot.account_id);
  SELECT coalesce(-sum(e.amount_minor), 0) INTO v_done FROM commerce.referral_entries e
   WHERE e.account_id = v_lot.account_id AND e.kind = 'reverse' AND e.source_kind = p_source_kind AND e.source_ref = p_source_ref;
  v_target := CASE WHEN p_num >= p_den THEN v_lot.amount_minor ELSE floor(v_lot.amount_minor::numeric * p_num / p_den)::bigint END;
  v_amount := CASE WHEN p_cumulative THEN v_target - v_done ELSE least(v_target, v_lot.amount_minor - v_done) END;
  IF v_amount <= 0 THEN
    RETURN 0;
  END IF;
  RETURN commerce.referral_take(v_lot.account_id, v_lot.currency, 'reverse', v_amount, 'lot', v_lot.id, p_source_kind, p_source_ref,
                                v_lot.referral_id, NULL, p_note, NULL, p_key);
END;
$$;


--
-- Name: referral_take(uuid, character, text, bigint, text, uuid, text, text, uuid, text, text, uuid, text, boolean); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.referral_take(p_account uuid, p_currency character, p_kind text, p_amount bigint, p_scope text, p_lot uuid, p_source_kind text, p_source_ref text, p_referral uuid, p_invoice_ref text, p_note text, p_by uuid, p_key text, p_exact boolean DEFAULT false) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_done bigint;
  v_room bigint;
  v_amount bigint;
  v_id uuid;
  v_lot record;
  v_left bigint;
  v_take bigint;
BEGIN
  PERFORM commerce.referral_lock(p_account);
  SELECT -e.amount_minor INTO v_done FROM commerce.referral_entries e WHERE e.idempotency_key = p_key;
  IF FOUND THEN
    RETURN v_done;
  END IF;
  IF p_amount <= 0 THEN
    RETURN 0;
  END IF;
  SELECT coalesce(sum(u.remaining), 0) INTO v_room FROM commerce.referral_usable_lots(p_account, p_currency, p_scope, p_lot) u;
  v_amount := least(p_amount, v_room);
  IF p_exact AND v_amount < p_amount THEN
    RAISE EXCEPTION 'referral.insufficient';
  END IF;
  IF v_amount <= 0 THEN
    RETURN 0;
  END IF;
  INSERT INTO commerce.referral_entries (
    account_id, currency, kind, amount_minor, source_kind, source_ref, referral_id, invoice_ref, note, created_by, idempotency_key
  ) VALUES (
    p_account, p_currency, p_kind, -v_amount, p_source_kind, p_source_ref, p_referral, p_invoice_ref,
    left(coalesce(p_note, ''), 500), p_by, p_key
  ) RETURNING id INTO v_id;
  v_left := v_amount;
  FOR v_lot IN SELECT u.id, u.remaining FROM commerce.referral_usable_lots(p_account, p_currency, p_scope, p_lot) u LOOP
    EXIT WHEN v_left = 0;
    v_take := least(v_lot.remaining, v_left);
    INSERT INTO commerce.referral_allocations (lot_id, entry_id, amount_minor) VALUES (v_lot.id, v_id, v_take);
    v_left := v_left - v_take;
  END LOOP;
  RETURN v_amount;
END;
$$;


--
-- Name: referral_usable_lots(uuid, character, text, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.referral_usable_lots(p_account uuid, p_currency character, p_scope text, p_lot uuid) RETURNS TABLE(id uuid, remaining bigint)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT l.id, l.remaining
    FROM commerce.referral_lots(p_account, p_currency) l
   WHERE l.remaining > 0
     AND CASE p_scope
           WHEN 'available' THEN l.available_at <= now()
           WHEN 'any' THEN true
           ELSE l.id = p_lot
         END
   ORDER BY (l.available_at <= now()) DESC, l.available_at, l.created_at, l.id
$$;


--
-- Name: referral_verify(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.referral_verify(p_account uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT NOT EXISTS (
    SELECT 1
      FROM (SELECT DISTINCT e.currency FROM commerce.referral_entries e WHERE e.account_id = p_account) c
     WHERE coalesce((SELECT sum(e.amount_minor) FROM commerce.referral_entries e
                      WHERE e.account_id = p_account AND e.currency = c.currency), 0)
        <> coalesce((SELECT sum(l.remaining) FROM commerce.referral_lots(p_account, c.currency) l), 0)
        OR EXISTS (SELECT 1 FROM commerce.referral_lots(p_account, c.currency) l WHERE l.remaining < 0)
  )
$$;


--
-- Name: referral_visit(text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.referral_visit(p_code text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM commerce.referrers r WHERE r.code = p_code AND r.blocked_at IS NULL) THEN
    RETURN false;
  END IF;
  INSERT INTO commerce.referral_visits (store_id, code, day, visits)
  VALUES (NULL, p_code, (now() AT TIME ZONE 'utc')::date, 1)
  ON CONFLICT (coalesce(store_id, '00000000-0000-0000-0000-000000000000'::uuid), code, day)
  DO UPDATE SET visits = commerce.referral_visits.visits + 1;
  RETURN true;
END;
$$;


--
-- Name: refresh_bundle_prices(uuid, character); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.refresh_bundle_prices(p_bundle_variant uuid, p_market character DEFAULT NULL::bpchar) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_bundle record;
  v_market record;
  v_count integer;
  v_priced integer;
  v_total bigint;
  v_amount bigint;
  v_current record;
BEGIN
  SELECT v.store_id, p.bundle_pricing, p.bundle_percent_off INTO v_bundle
    FROM commerce.product_variants v JOIN commerce.products p ON p.store_id = v.store_id AND p.id = v.product_id
   WHERE v.id = p_bundle_variant;
  IF NOT FOUND OR v_bundle.bundle_pricing IS DISTINCT FROM 'computed' THEN RETURN; END IF;
  FOR v_market IN
    SELECT m.code FROM commerce.markets m
     WHERE m.store_id = v_bundle.store_id AND (p_market IS NULL OR m.code = p_market)
     ORDER BY m.code
  LOOP
    SELECT count(*), count(pr.amount_minor), sum(pr.amount_minor * bc.quantity)
      INTO v_count, v_priced, v_total
      FROM commerce.bundle_components bc
      LEFT JOIN commerce.prices pr ON pr.variant_id = bc.component_variant_id AND pr.market_code = v_market.code AND pr.valid_to IS NULL
     WHERE bc.store_id = v_bundle.store_id AND bc.bundle_variant_id = p_bundle_variant;
    CONTINUE WHEN v_count = 0 OR v_priced < v_count;
    v_amount := (v_total * (100 - v_bundle.bundle_percent_off) + 50) / 100;
    SELECT amount_minor, valid_from INTO v_current FROM commerce.prices
     WHERE variant_id = p_bundle_variant AND market_code = v_market.code AND valid_to IS NULL;
    CONTINUE WHEN FOUND AND v_current.amount_minor = v_amount;
    PERFORM commerce.set_price(
      p_bundle_variant, v_market.code, v_amount,
      CASE WHEN v_current.valid_from IS NOT NULL AND v_current.valid_from >= now() THEN v_current.valid_from + interval '1 microsecond' ELSE now() END
    );
  END LOOP;
END;
$$;


--
-- Name: refresh_fulfilment(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.refresh_fulfilment(p_store uuid, p_order uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_n integer;
BEGIN
  UPDATE commerce.orders o SET status = 'fulfilled'
   WHERE o.store_id = p_store AND o.id = p_order AND o.status = 'paid'
     AND commerce.order_fulfilment(o.id) = 'sent';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n > 0;
END;
$$;


--
-- Name: refresh_stock_alert(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.refresh_stock_alert(p_store uuid, p_variant uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_threshold integer;
  v_stock integer;
  v_prev text;
  v_state text;
BEGIN
  -- A failure here never stops a sale or a count: it becomes a warning and the next change refreshes the row.
  BEGIN
    SELECT v.low_stock_threshold INTO v_threshold
      FROM commerce.product_variants v WHERE v.store_id = p_store AND v.id = p_variant;
    IF NOT FOUND THEN RETURN; END IF;
    IF v_threshold IS NULL AND NOT EXISTS (
         SELECT 1 FROM commerce.stock_alerts a WHERE a.store_id = p_store AND a.variant_id = p_variant) THEN
      RETURN;
    END IF;
    -- Lock the row first, then count, so two changes of one variant at two locations both see the other's.
    INSERT INTO commerce.stock_alerts (store_id, variant_id, state) VALUES (p_store, p_variant, 'off')
      ON CONFLICT (store_id, variant_id) DO NOTHING;
    SELECT a.state INTO v_prev FROM commerce.stock_alerts a
     WHERE a.store_id = p_store AND a.variant_id = p_variant FOR UPDATE;
    SELECT coalesce(sum(l.on_hand), 0)::integer INTO v_stock
      FROM commerce.inventory_levels l
      JOIN commerce.inventory_locations loc ON loc.store_id = l.store_id AND loc.id = l.location_id AND loc.active
     WHERE l.store_id = p_store AND l.variant_id = p_variant;
    v_state := CASE WHEN v_threshold IS NULL THEN 'off' WHEN v_stock <= v_threshold THEN 'low' ELSE 'ok' END;
    UPDATE commerce.stock_alerts SET
      state = v_state,
      crossed_at = CASE WHEN v_state <> 'low' THEN NULL WHEN v_prev = 'low' THEN crossed_at ELSE now() END,
      notified_at = CASE WHEN v_state = 'low' AND v_prev = 'ok' THEN NULL
                         WHEN v_state = 'low' AND v_prev = 'off' THEN now()
                         ELSE notified_at END,
      stock_at_crossing = CASE WHEN v_state <> 'low' THEN NULL WHEN v_prev = 'low' THEN stock_at_crossing ELSE v_stock END,
      updated_at = now()
     WHERE store_id = p_store AND variant_id = p_variant;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'refresh_stock_alert: % (%)', SQLERRM, SQLSTATE;
  END;
END;
$$;


