--
-- Name: refunds_creator(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.refunds_creator() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_order uuid;
  v_creator uuid;
BEGIN
  IF NEW.status = 'failed' OR NEW.kind IN ('release', 'void') THEN
    RETURN NULL;
  END IF;
  SELECT p.order_id INTO v_order FROM commerce.payments p WHERE p.store_id = NEW.store_id AND p.id = NEW.payment_id;
  SELECT a.creator_id INTO v_creator FROM commerce.creator_attributions a WHERE a.store_id = NEW.store_id AND a.order_id = v_order;
  IF v_creator IS NULL OR NOT commerce.payment_of_order(NEW.store_id, NEW.payment_id) THEN
    RETURN NULL;
  END IF;
  PERFORM commerce.creator_lock(NEW.store_id, v_creator);
  PERFORM commerce.creator_settle_refunds(NEW.store_id, v_order, 'creator-reverse:' || NEW.id);
  RETURN NULL;
END;
$$;


--
-- Name: refunds_exchange_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.refunds_exchange_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  e commerce.return_exchanges%ROWTYPE;
  p commerce.payments%ROWTYPE;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.exchange_id IS DISTINCT FROM OLD.exchange_id OR NEW.kind <> OLD.kind THEN
      RAISE EXCEPTION 'refund_exchange.frozen: a refund keeps its kind and its exchange' USING ERRCODE = 'restrict_violation';
    END IF;
    IF OLD.kind = 'transfer' AND to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD) AND current_setting('commerce.anonymising', true) IS DISTINCT FROM 'on' THEN
      RAISE EXCEPTION 'refund_exchange.transfer_final: a transfer to an exchange order is a record' USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.exchange_id IS NULL THEN
    IF NEW.kind = 'transfer' THEN
      RAISE EXCEPTION 'refund_exchange.transfer: a transfer names its exchange' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  SELECT * INTO e FROM commerce.return_exchanges x WHERE x.store_id = NEW.store_id AND x.id = NEW.exchange_id;
  SELECT * INTO p FROM commerce.payments x WHERE x.store_id = NEW.store_id AND x.id = NEW.payment_id;
  IF NOT FOUND OR (p.order_id <> e.order_id AND p.order_id IS DISTINCT FROM e.exchange_order_id) THEN
    RAISE EXCEPTION 'refund_exchange.order: an exchange''s refund is of its original order''s payment, or of its own order''s' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.kind = 'transfer' THEN
    IF coalesce(current_setting('kaizen.exchange', true), '') <> NEW.exchange_id::text THEN
      RAISE EXCEPTION 'refund_exchange.context: a transfer is made only by settling its exchange' USING ERRCODE = 'restrict_violation';
    END IF;
    IF p.order_id <> e.order_id OR p.provider = 'exchange' OR p.status <> 'captured' THEN
      RAISE EXCEPTION 'refund_exchange.transfer: a transfer is of a captured payment of the original order' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: refunds_gift_card(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.refunds_gift_card() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_payment commerce.payments%ROWTYPE;
BEGIN
  IF NEW.status <> 'succeeded' OR (TG_OP = 'UPDATE' AND OLD.status = 'succeeded') THEN
    RETURN NULL;
  END IF;
  SELECT * INTO v_payment FROM commerce.payments p WHERE p.store_id = NEW.store_id AND p.id = NEW.payment_id;
  IF v_payment.provider IS DISTINCT FROM 'gift_card' THEN
    RETURN NULL;
  END IF;
  IF NEW.kind <> 'money' THEN
    RAISE EXCEPTION 'refunds.gift_card_kind: a refund of a gift card goes back on the card' USING ERRCODE = 'check_violation';
  END IF;
  PERFORM commerce.gift_card_refund(NEW.store_id, v_payment.gift_card_id, v_payment.order_id, NEW.amount_minor, 'refund:' || NEW.id);
  RETURN NULL;
END;
$$;


