END;
$$;


--
-- Name: refunds_manual_cap(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.refunds_manual_cap() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_amount bigint;
  v_provider text;
  v_other bigint;
BEGIN
  IF NEW.status = 'failed' THEN RETURN NEW; END IF;
  SELECT p.amount_minor, p.provider INTO v_amount, v_provider
    FROM commerce.payments p WHERE p.store_id = NEW.store_id AND p.id = NEW.payment_id FOR UPDATE;
  -- Exchanges (D239): an exchange payment, and a payment that carries a transfer, are capped as well.
  IF v_provider IS DISTINCT FROM 'manual' AND v_provider IS DISTINCT FROM 'exchange' AND v_provider IS DISTINCT FROM 'terms' AND v_provider IS DISTINCT FROM 'gift_card' AND NEW.kind NOT IN ('transfer', 'store_credit') AND NOT EXISTS (
    SELECT 1 FROM commerce.refunds t WHERE t.store_id = NEW.store_id AND t.payment_id = NEW.payment_id AND t.kind = 'transfer'
  ) THEN RETURN NEW; END IF;
  SELECT coalesce(sum(r.amount_minor), 0) INTO v_other
    FROM commerce.refunds r
   WHERE r.store_id = NEW.store_id AND r.payment_id = NEW.payment_id AND r.status <> 'failed' AND r.id <> NEW.id;
  IF v_other + NEW.amount_minor > v_amount THEN
    RAISE EXCEPTION 'refund.over_payment: the refunds of a payment taken outside Kaizen cannot exceed the payment (% of %)', v_other + NEW.amount_minor, v_amount
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: refunds_referral(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.refunds_referral() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_paid bigint;
  v_refunded bigint;
BEGIN
  IF NEW.status = 'failed' THEN
    RETURN NULL;
  END IF;
  SELECT p.amount_minor INTO v_paid FROM commerce.payments p WHERE p.store_id = NEW.store_id AND p.id = NEW.payment_id;
  SELECT coalesce(sum(r.amount_minor), 0) INTO v_refunded FROM commerce.refunds r
   WHERE r.store_id = NEW.store_id AND r.payment_id = NEW.payment_id AND r.status <> 'failed';
  PERFORM commerce.referral_reverse('sale_fee', NEW.payment_id::text, v_refunded, v_paid, true, 'reverse:' || NEW.id, 'Kaizen''s fee was refunded');
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'referral commission reversal for refund % failed: %', NEW.id, SQLERRM;
  RETURN NULL;
END;
$$;


--
-- Name: refunds_succeeded_final(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.refunds_succeeded_final() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF OLD.status = 'succeeded' AND NEW.status <> 'succeeded' THEN
    RAISE EXCEPTION 'refund.succeeded_final: a refund that has succeeded cannot become % (a credit note may stand for it)', NEW.status USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: refuse_copied_order(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.refuse_copied_order() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.order_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM commerce.orders o WHERE o.id = NEW.order_id AND o.copied_from IS NOT NULL) THEN
    RAISE EXCEPTION 'copied_order: an order copied from another store is history and cannot get a row in %', TG_TABLE_NAME
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: refuse_copied_order_event(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.refuse_copied_order_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.type NOT IN ('copied', 'order.tags_changed', 'order.archived', 'order.unarchived')
     AND EXISTS (SELECT 1 FROM commerce.orders o WHERE o.id = NEW.order_id AND o.copied_from IS NOT NULL) THEN
    RAISE EXCEPTION 'copied_order: an order copied from another store is history and cannot get the event %', NEW.type
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: registration_blocks(uuid, text, uuid, date); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.registration_blocks(p_store uuid, p_market text DEFAULT NULL::text, p_product uuid DEFAULT NULL::uuid, p_on date DEFAULT NULL::date) RETURNS TABLE(product_id uuid, market_code text, scheme commerce.producer_scheme)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT g.product_id, g.market_code, g.scheme
    FROM commerce.registration_gaps(p_store, p_market, p_product, p_on) g
   WHERE NOT EXISTS (SELECT 1 FROM commerce.stores s WHERE s.id = p_store AND (s.is_template OR s.starter))
$$;


--
-- Name: registration_gaps(uuid, text, uuid, date); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.registration_gaps(p_store uuid, p_market text DEFAULT NULL::text, p_product uuid DEFAULT NULL::uuid, p_on date DEFAULT NULL::date) RETURNS TABLE(product_id uuid, market_code text, scheme commerce.producer_scheme, recorded boolean)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT ps.product_id, m.code::text, ps.scheme,
         EXISTS (
           SELECT 1 FROM commerce.producer_registrations a
            WHERE a.store_id = ps.store_id AND a.market_code = m.code AND a.scheme = ps.scheme
         )
    FROM commerce.product_schemes ps
    JOIN commerce.stores s ON s.id = ps.store_id
    JOIN commerce.markets m ON m.store_id = ps.store_id AND m.active
   WHERE ps.store_id = p_store
     AND (p_market IS NULL OR m.code = p_market)
     AND (p_product IS NULL OR ps.product_id = p_product)
     AND NOT EXISTS (
       SELECT 1 FROM commerce.producer_registrations r
        WHERE r.store_id = ps.store_id
          AND r.market_code = m.code
          AND r.scheme = ps.scheme
          AND r.valid_from <= coalesce(p_on, (now() AT TIME ZONE s.time_zone)::date)
          AND (r.valid_to IS NULL OR r.valid_to >= coalesce(p_on, (now() AT TIME ZONE s.time_zone)::date))
     )
$$;


--
-- Name: resource_blocked(uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.resource_blocked(p_store_id uuid, p_resource_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM commerce.resource_blocks k
     WHERE k.store_id = p_store_id AND k.resource_id = p_resource_id
       AND k.starts_at < p_to AND k.ends_at > p_from
  );
$$;


--
-- Name: resource_peak(uuid, uuid, timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.resource_peak(p_store_id uuid, p_resource_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_except uuid) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  WITH live AS (
    SELECT b.blocked_from, b.blocked_to FROM commerce.bookings b
     WHERE b.store_id = p_store_id AND b.resource_id = p_resource_id
       AND b.id IS DISTINCT FROM p_except
       AND (b.status = 'confirmed' OR (b.status = 'held' AND b.hold_expires_at > now()))
       AND b.blocked_from < p_to AND b.blocked_to > p_from
  )
  SELECT coalesce(max((
    SELECT count(*) FROM live l2 WHERE l2.blocked_from <= pt.at AND l2.blocked_to > pt.at
  )), 0)::integer
  FROM (SELECT greatest(l.blocked_from, p_from) AS at FROM live l) pt;
$$;


--
-- Name: responsible_person_areas(uuid, character); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.responsible_person_areas(p_store uuid, p_maker character) RETURNS text[]
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce(array_agg(DISTINCT t.area ORDER BY t.area DESC), '{}')
    FROM (
      SELECT coalesce(r.responsible_person, CASE WHEN commerce.is_established_in('eu', mk.code) THEN 'eu' ELSE 'none' END) AS area
        FROM commerce.markets mk
        LEFT JOIN commerce.product_safety_rules r ON r.destination = mk.code
       WHERE mk.store_id = p_store AND mk.active
    ) t
   WHERE t.area <> 'none' AND NOT commerce.is_established_in(t.area, p_maker);
$$;


--
-- Name: retention_rule(text, character, date); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.retention_rule(p_kind text, p_country character, p_at date) RETURNS TABLE(period_value integer, period_unit text, counts_from text)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  WITH hit AS (
    SELECT r.period_value, r.period_unit, r.counts_from
      FROM commerce.retention_rules r
     WHERE r.kind = p_kind
       AND (r.country IS NULL OR r.country = p_country)
       AND r.valid_from <= p_at AND (r.valid_to IS NULL OR p_at < r.valid_to)
     ORDER BY (r.country IS NOT NULL) DESC, r.valid_from DESC
     LIMIT 1
  )
  SELECT h.period_value, h.period_unit, h.counts_from FROM hit h
  UNION ALL
  SELECT 120, 'months', CASE WHEN p_kind IN ('bookkeeping', 'host_bookkeeping') THEN 'end_of_year' ELSE 'event' END
   WHERE NOT EXISTS (SELECT 1 FROM hit)
$$;


--
-- Name: retention_rules_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.retention_rules_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'retention_rule_kept: a retention rule is history and is never deleted (add a new one)' USING ERRCODE = 'restrict_violation';
  END IF;
  IF (to_jsonb(NEW) - 'valid_to' - 'verified_at' - 'verified_by') IS DISTINCT FROM (to_jsonb(OLD) - 'valid_to' - 'verified_at' - 'verified_by') THEN
    RAISE EXCEPTION 'retention_rule_fixed: a retention rule is not edited in place (add a new one)' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.valid_to IS NOT NULL AND NEW.valid_to IS DISTINCT FROM OLD.valid_to THEN
    RAISE EXCEPTION 'retention_rule_fixed: the end of a rule is set once' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.verified_at IS NOT NULL AND (NEW.verified_at IS DISTINCT FROM OLD.verified_at OR NEW.verified_by IS DISTINCT FROM OLD.verified_by) THEN
    RAISE EXCEPTION 'retention_rule_fixed: a review is kept as it was made' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: return_exchange_lines_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.return_exchange_lines_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  e commerce.return_exchanges%ROWTYPE;
  v_delivery text;
BEGIN
  SELECT * INTO e FROM commerce.return_exchanges x WHERE x.id = CASE WHEN TG_OP = 'DELETE' THEN OLD.exchange_id ELSE NEW.exchange_id END FOR NO KEY UPDATE;
  IF TG_OP = 'DELETE' THEN
    IF e.status <> 'draft' THEN
      RAISE EXCEPTION 'exchange_line.frozen: the replacements of a proposal are a record' USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN OLD;
  END IF;
  IF NOT FOUND OR e.store_id <> NEW.store_id THEN
    RAISE EXCEPTION 'exchange_line.exchange: a replacement belongs to an exchange of its own store' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'UPDATE' AND (e.status <> 'draft' OR NEW.exchange_id <> OLD.exchange_id) THEN
    RAISE EXCEPTION 'exchange_line.frozen: the replacements of a proposal are a record' USING ERRCODE = 'restrict_violation';
  END IF;
  IF TG_OP = 'INSERT' AND NOT (e.status = 'draft' OR (e.status = 'proposed' AND e.created_at = now())) THEN
    RAISE EXCEPTION 'exchange_line.frozen: replacements are added to a draft, or with the proposal itself' USING ERRCODE = 'restrict_violation';
  END IF;
  SELECT v.delivery INTO v_delivery FROM commerce.product_variants v WHERE v.store_id = NEW.store_id AND v.id = NEW.variant_id;
  IF v_delivery IS DISTINCT FROM 'physical' THEN
    RAISE EXCEPTION 'exchange.not_goods: a replacement is goods that are shipped' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: return_exchanges_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.return_exchanges_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  r commerce.returns%ROWTYPE;
  o commerce.orders%ROWTYPE;
  v_block text;
  v_old text;
  v_new text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'exchange.kept: an exchange is a record and is never deleted (cancel it)' USING ERRCODE = 'restrict_violation';
  END IF;

  IF TG_OP = 'INSERT' THEN
    -- The return's row is locked, so two proposals at once get two numbers and only one stays open (the partial unique index).
    SELECT * INTO r FROM commerce.returns WHERE store_id = NEW.store_id AND id = NEW.return_id FOR NO KEY UPDATE;
    IF NOT FOUND OR r.order_id <> NEW.order_id THEN
      RAISE EXCEPTION 'exchange.return: an exchange belongs to a return of its own order' USING ERRCODE = 'check_violation';
    END IF;
    SELECT * INTO o FROM commerce.orders WHERE store_id = NEW.store_id AND id = NEW.order_id;
    IF NEW.status NOT IN ('draft', 'proposed') THEN
      RAISE EXCEPTION 'exchange.lifecycle: an exchange starts as a draft or a proposal' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.currency <> o.currency THEN
      RAISE EXCEPTION 'exchange.currency: an exchange is in its order''s currency (%)', o.currency USING ERRCODE = 'check_violation';
    END IF;
    v_block := commerce.exchange_block(NEW.return_id, false);
    IF v_block IS NOT NULL THEN
      RAISE EXCEPTION 'exchange.%: this return cannot be exchanged', v_block USING ERRCODE = 'check_violation';
    END IF;
    SELECT coalesce(max(e.seq), 0) + 1 INTO NEW.seq FROM commerce.return_exchanges e WHERE e.store_id = NEW.store_id AND e.return_id = NEW.return_id;
    IF NEW.seq > 5 THEN
      RAISE EXCEPTION 'exchange.limit: a return has at most 5 exchange proposals' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.confirmed_at IS NOT NULL OR NEW.exchange_order_id IS NOT NULL OR NEW.refund_id IS NOT NULL OR NEW.transfer_refund_id IS NOT NULL
       OR NEW.credit_at_processing IS NOT NULL OR NEW.processed_at IS NOT NULL OR NEW.settled_at IS NOT NULL OR NEW.ended_at IS NOT NULL THEN
      RAISE EXCEPTION 'exchange.lifecycle: a new exchange is not confirmed, processed, settled or ended' USING ERRCODE = 'check_violation';
    END IF;
    NEW.created_at := now();
    NEW.updated_at := now();
    RETURN NEW;
  END IF;

  -- UPDATE ------------------------------------------------------------------------------------------------------
  IF current_setting('commerce.anonymising', true) = 'on' THEN
    IF (to_jsonb(NEW) - ARRAY['delivery_address', 'updated_at']) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['delivery_address', 'updated_at']) THEN
      RAISE EXCEPTION 'exchange.fixed: only the delivery address of an exchange is anonymised' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.id <> OLD.id OR NEW.store_id <> OLD.store_id OR NEW.return_id <> OLD.return_id OR NEW.order_id <> OLD.order_id OR NEW.seq <> OLD.seq
     OR NEW.currency <> OLD.currency OR NEW.market_slug <> OLD.market_slug OR NEW.made_by <> OLD.made_by OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'exchange.fixed: an exchange keeps its return, order, number, currency, market and maker' USING ERRCODE = 'restrict_violation';
  END IF;
  v_old := OLD.status;
  v_new := NEW.status;
  NEW.updated_at := now();

  -- An exchange that has ended (settled included) only loses its token hash, 90 days after (application code).
  IF v_old IN ('settled', 'declined_by_customer', 'cancelled', 'expired', 'superseded') THEN
    IF (to_jsonb(NEW) - ARRAY['token_hash', 'updated_at']) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['token_hash', 'updated_at'])
       OR (NEW.token_hash IS DISTINCT FROM OLD.token_hash AND NEW.token_hash IS NOT NULL) THEN
      RAISE EXCEPTION 'exchange.ended: an exchange that has ended is a record and does not change' USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
  END IF;

  -- What was proposed (and confirmed) is frozen once it leaves the draft: the prices as shown, the shipping, the address, the credit.
  IF v_old <> 'draft' AND (
       NEW.shipping_kind <> OLD.shipping_kind OR NEW.shipping_minor <> OLD.shipping_minor OR NEW.delivery_address IS DISTINCT FROM OLD.delivery_address
       OR NEW.credit_minor <> OLD.credit_minor OR NEW.total_minor <> OLD.total_minor OR NEW.difference_minor <> OLD.difference_minor) THEN
    RAISE EXCEPTION 'exchange.frozen: a proposal is not changed; propose again' USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW.terms IS DISTINCT FROM OLD.terms AND v_old NOT IN ('draft', 'proposed') THEN
    RAISE EXCEPTION 'exchange.frozen: the terms are kept as the customer confirmed them' USING ERRCODE = 'restrict_violation';
  END IF;
  IF (OLD.confirmed_at IS NOT NULL AND (NEW.confirmed_at IS DISTINCT FROM OLD.confirmed_at OR NEW.confirmed_by IS DISTINCT FROM OLD.confirmed_by
                                         OR NEW.confirmed_channel IS DISTINCT FROM OLD.confirmed_channel))
     OR (OLD.processed_at IS NOT NULL AND NEW.processed_at IS DISTINCT FROM OLD.processed_at)
     OR (OLD.exchange_order_id IS NOT NULL AND NEW.exchange_order_id IS DISTINCT FROM OLD.exchange_order_id)
     OR (OLD.credit_at_processing IS NOT NULL AND (NEW.credit_at_processing IS DISTINCT FROM OLD.credit_at_processing
                                                  OR NEW.difference_at_processing IS DISTINCT FROM OLD.difference_at_processing))
     OR (OLD.refund_id IS NOT NULL AND NEW.refund_id IS DISTINCT FROM OLD.refund_id)
     OR (OLD.transfer_refund_id IS NOT NULL AND NEW.transfer_refund_id IS DISTINCT FROM OLD.transfer_refund_id) THEN
    RAISE EXCEPTION 'exchange.times: a step and what it recorded are kept once set' USING ERRCODE = 'restrict_violation';
  END IF;

  IF v_new <> v_old THEN
    IF NOT (
      (v_old = 'draft' AND v_new IN ('proposed', 'cancelled'))
      OR (v_old = 'proposed' AND v_new IN ('confirmed', 'declined_by_customer', 'cancelled', 'expired', 'superseded'))
      OR (v_old = 'confirmed' AND v_new IN ('processed', 'cancelled', 'expired', 'superseded'))
      OR (v_old = 'processed' AND v_new IN ('settled', 'cancelled', 'expired'))
    ) THEN
      RAISE EXCEPTION 'exchange.lifecycle: an exchange cannot go from % to %', v_old, v_new USING ERRCODE = 'check_violation';
    END IF;
    IF v_new = 'confirmed' THEN
      NEW.confirmed_at := coalesce(NEW.confirmed_at, now());
      IF NEW.confirmed_by = 'staff' AND EXISTS (SELECT 1 FROM commerce.returns rt WHERE rt.id = NEW.return_id AND rt.kind = 'withdrawal') THEN
        RAISE EXCEPTION 'exchange.withdrawal_needs_customer: a withdrawal''s refund goes another way only on the customer''s own confirmation (CRD Art. 13(1))'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
    IF v_new = 'processed' THEN
      NEW.processed_at := coalesce(NEW.processed_at, now());
      v_block := commerce.exchange_block(NEW.return_id, true);
      IF v_block IS NOT NULL THEN
        RAISE EXCEPTION 'exchange.%: this return can no longer be exchanged', v_block USING ERRCODE = 'check_violation';
      END IF;
      IF NOT EXISTS (SELECT 1 FROM commerce.orders x WHERE x.store_id = NEW.store_id AND x.id = NEW.exchange_order_id AND x.exchange_id = NEW.id) THEN
        RAISE EXCEPTION 'exchange.order: a processed exchange names the order made for it' USING ERRCODE = 'check_violation';
      END IF;
    END IF;
    IF v_new = 'settled' THEN NEW.settled_at := coalesce(NEW.settled_at, now()); END IF;
    IF v_new IN ('declined_by_customer', 'cancelled', 'expired', 'superseded') THEN NEW.ended_at := coalesce(NEW.ended_at, now()); END IF;
  ELSE
    IF NEW.confirmed_at IS DISTINCT FROM OLD.confirmed_at OR NEW.processed_at IS DISTINCT FROM OLD.processed_at
       OR NEW.settled_at IS DISTINCT FROM OLD.settled_at OR NEW.ended_at IS DISTINCT FROM OLD.ended_at
       OR NEW.exchange_order_id IS DISTINCT FROM OLD.exchange_order_id OR NEW.credit_at_processing IS DISTINCT FROM OLD.credit_at_processing THEN
      RAISE EXCEPTION 'exchange.times: a step''s record is written with the step' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: return_exchanges_settled(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.return_exchanges_settled() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  e commerce.return_exchanges%ROWTYPE;
  r commerce.returns%ROWTYPE;
  o commerce.orders%ROWTYPE;
  v_transfer bigint;
  v_remainder bigint;
BEGIN
  SELECT * INTO e FROM commerce.return_exchanges WHERE id = NEW.id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF e.status <> 'draft' AND e.status NOT IN ('declined_by_customer', 'cancelled', 'expired', 'superseded')
     AND NOT EXISTS (SELECT 1 FROM commerce.return_exchange_lines l WHERE l.exchange_id = e.id) THEN
    RAISE EXCEPTION 'exchange.no_lines: a proposal has at least one replacement' USING ERRCODE = 'check_violation';
  END IF;
  IF e.exchange_order_id IS NOT NULL THEN
    SELECT * INTO o FROM commerce.orders WHERE store_id = e.store_id AND id = e.exchange_order_id;
    -- The order's goods are the replacements, line for line (variant, units, price charged), as it was made.
    IF e.status IN ('processed', 'settled') AND EXISTS (
      (SELECT l.variant_id, l.quantity, l.unit_price_minor FROM commerce.return_exchange_lines l WHERE l.exchange_id = e.id
       EXCEPT ALL
       SELECT ol.variant_id, ol.quantity, ol.unit_price_minor FROM commerce.order_lines ol WHERE ol.store_id = o.store_id AND ol.order_id = o.id)
      UNION ALL
      (SELECT ol.variant_id, ol.quantity, ol.unit_price_minor FROM commerce.order_lines ol WHERE ol.store_id = o.store_id AND ol.order_id = o.id
       EXCEPT ALL
       SELECT l.variant_id, l.quantity, l.unit_price_minor FROM commerce.return_exchange_lines l WHERE l.exchange_id = e.id)
    ) AND o.edited_at IS NULL THEN
      RAISE EXCEPTION 'exchange.order_lines: the exchange order holds exactly the replacements' USING ERRCODE = 'check_violation';
    END IF;
    IF e.status IN ('declined_by_customer', 'cancelled', 'expired', 'superseded') AND o.status <> 'cancelled' THEN
      RAISE EXCEPTION 'exchange.order_live: an exchange that ended leaves its order cancelled' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF e.status = 'settled' THEN
    SELECT * INTO r FROM commerce.returns WHERE store_id = e.store_id AND id = e.return_id;
    IF o.status IN ('pending_payment', 'cancelled') THEN
      RAISE EXCEPTION 'exchange.not_paid: a settled exchange''s order is paid' USING ERRCODE = 'check_violation';
    END IF;
    IF r.outcome IS DISTINCT FROM 'exchanged' OR r.refund_minor IS DISTINCT FROM e.credit_at_processing THEN
      RAISE EXCEPTION 'exchange.return: a settled exchange''s return ends exchanged, with the credit as its refund' USING ERRCODE = 'check_violation';
    END IF;
    SELECT x.transfer_minor, x.remainder_minor INTO v_transfer, v_remainder FROM commerce.exchange_refunds_of(e.id) x;
    IF v_transfer <> least(e.credit_at_processing, o.total_minor) THEN
      RAISE EXCEPTION 'exchange.transfer: the credit moved to the order is the lesser of the credit and the order''s total (% is not %)', v_transfer,
        least(e.credit_at_processing, o.total_minor) USING ERRCODE = 'check_violation';
    END IF;
    IF v_transfer + v_remainder <> r.refund_minor THEN
      RAISE EXCEPTION 'exchange.refunds: the transfer and the remainder add up to the return''s refund (% + % is not %)', v_transfer, v_remainder, r.refund_minor
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: return_line_value_cap(uuid, integer); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.return_line_value_cap(p_order_line uuid, p_quantity integer) RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT CASE WHEN ol.quantity = 0 THEN 0
              ELSE ceil(ol.total_minor::numeric * p_quantity / ol.quantity)::bigint END
    FROM commerce.order_lines ol WHERE ol.id = p_order_line
$$;


--
-- Name: return_lines_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.return_lines_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_ret commerce.returns%ROWTYPE;
  v_line commerce.order_lines%ROWTYPE;
  v_req_qty integer;
  v_taken integer;
  v_counts boolean;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'return_kept: the lines of a return are history and are never deleted (decline the line)' USING ERRCODE = 'check_violation';
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF NEW.return_id <> OLD.return_id OR NEW.order_line_id <> OLD.order_line_id OR NEW.quantity <> OLD.quantity THEN
      RAISE EXCEPTION 'return_fixed: what was returned of a line is not changed (decline it and return the rest)' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  SELECT * INTO v_ret FROM commerce.returns r WHERE r.store_id = NEW.store_id AND r.id = NEW.return_id;
  IF v_ret.status IN ('closed', 'declined', 'cancelled') THEN
    RAISE EXCEPTION 'return_ended: a return that has ended cannot be changed' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'INSERT' AND v_ret.status NOT IN ('requested', 'approved') THEN
    RAISE EXCEPTION 'return_locked: lines are added only before the goods are on their way' USING ERRCODE = 'check_violation';
  END IF;

  -- Inspection results are written once the goods are there.
  IF TG_OP = 'UPDATE' THEN
    IF (NEW.condition IS DISTINCT FROM OLD.condition OR NEW.deduction_minor <> OLD.deduction_minor
        OR NEW.deduction_note IS DISTINCT FROM OLD.deduction_note)
       AND v_ret.status NOT IN ('received', 'inspected') THEN
      RAISE EXCEPTION 'return_not_received: the condition and any deduction are set when the goods have arrived' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  -- The line is locked while its quantity is counted, so two returns at once cannot both take the last unit.
  SELECT * INTO v_line FROM commerce.order_lines ol WHERE ol.store_id = NEW.store_id AND ol.id = NEW.order_line_id FOR NO KEY UPDATE;
  IF v_line.order_id <> v_ret.order_id THEN
    RAISE EXCEPTION 'return_line_order: the line belongs to another order' USING ERRCODE = 'check_violation';
  END IF;

  v_counts := NEW.decision = 'accept';
  IF v_counts AND TG_OP = 'UPDATE' THEN v_counts := OLD.decision = 'decline'; END IF;
  IF v_counts THEN
    v_taken := commerce.returned_quantity(v_line.id, NEW.return_id);
    IF NEW.quantity > v_line.quantity - v_taken THEN
      RAISE EXCEPTION 'return_quantity: only % of % is left to return', v_line.quantity - v_taken, v_line.quantity
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF v_ret.kind = 'withdrawal' THEN
    -- Only what the shopper declared, and only a line the law leaves with the right; one the law excludes is declined.
    SELECT l.quantity INTO v_req_qty FROM commerce.withdrawal_request_lines l
     WHERE l.store_id = NEW.store_id AND l.withdrawal_request_id = v_ret.withdrawal_request_id AND l.order_line_id = NEW.order_line_id;
    IF v_req_qty IS NULL OR NEW.quantity > v_req_qty THEN
      RAISE EXCEPTION 'return_not_declared: a withdrawal return holds only what the withdrawal declared' USING ERRCODE = 'check_violation';
    END IF;
    -- Sealed goods (hygiene, audio, video, software) lose the right only once unsealed after delivery (CRD Art. 16(e), (i)):
    -- a withdrawal of them is accepted, and whether the seal was broken is for the inspection (a deduction, or declining the line).
    IF NEW.decision = 'accept' AND v_line.withdrawal_exclusion NOT IN ('none', 'sealed_hygiene', 'sealed_media') THEN
      RAISE EXCEPTION 'return_excluded: the law excludes this line from the right of withdrawal, so it is declined' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.decision = 'decline' AND v_line.withdrawal_exclusion = 'none' THEN
      RAISE EXCEPTION 'return_decline_withdrawal: a line with the right of withdrawal is not declined' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF NEW.deduction_minor > commerce.return_line_value_cap(NEW.order_line_id, NEW.quantity) THEN
    RAISE EXCEPTION 'return_deduction: a deduction is never more than the value of the goods' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: return_refund_parts_sum(uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.return_refund_parts_sum(p_store uuid, p_order uuid, p_named uuid, p_named_amount bigint) RETURNS bigint
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
    DECLARE
      v_parts uuid[];
      v_sum bigint;
      v_ours int;
    BEGIN
      -- kaizen.return_refund_parts: the refunds one refund of a return was split into, named by the writer in this transaction.
      v_parts := nullif(current_setting('kaizen.return_refund_parts', true), '')::uuid[];
      IF v_parts IS NULL OR NOT (p_named = ANY (v_parts)) THEN RETURN p_named_amount; END IF;
      SELECT coalesce(sum(rf.amount_minor), 0), count(*) INTO v_sum, v_ours
        FROM commerce.refunds rf JOIN commerce.payments p ON p.store_id = rf.store_id AND p.id = rf.payment_id
       WHERE rf.store_id = p_store AND p.order_id = p_order AND rf.id = ANY (v_parts);
      -- Every part named must be a refund of this order; otherwise nothing matches.
      IF v_ours <> cardinality(v_parts) THEN RETURN -1; END IF;
      RETURN v_sum;
    END;
    $$;


--
-- Name: return_transferred(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.return_transferred(p_store uuid, p_return uuid) RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce(sum(rf.amount_minor), 0)::bigint
    FROM commerce.return_exchanges e
    JOIN commerce.refunds rf ON rf.store_id = e.store_id AND rf.exchange_id = e.id AND rf.kind = 'transfer'
   WHERE e.store_id = p_store AND e.return_id = p_return
$$;


--
-- Name: returned_quantity(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.returned_quantity(p_order_line uuid, p_except_return uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce(sum(rl.quantity), 0)::integer
    FROM commerce.return_lines rl
    JOIN commerce.returns r ON r.store_id = rl.store_id AND r.id = rl.return_id
   WHERE rl.order_line_id = p_order_line
     AND rl.decision = 'accept'
     AND r.status NOT IN ('declined', 'cancelled')
     AND (p_except_return IS NULL OR r.id <> p_except_return)
$$;


--
-- Name: returns_issue_credit_note(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.returns_issue_credit_note() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM commerce.issue_credit_note(NEW.store_id, NULL, NEW.id);
  RETURN NULL;
END;
$$;


--
-- Name: returns_label_pasted(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.returns_label_pasted() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.label_url IS NOT NULL AND NEW.label_source IS NULL THEN
    NEW.label_source := 'pasted';
  ELSIF NEW.label_url IS NULL AND NEW.label_source = 'pasted' THEN
    NEW.label_source := NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: returns_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.returns_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
DECLARE
  v_order commerce.orders%ROWTYPE;
  v_req commerce.withdrawal_requests%ROWTYPE;
  v_n integer;
  v_old text;
  v_new text;
  v_paid bigint;
  v_total_refund bigint;
  v_refund commerce.refunds%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'return_kept: a return is history and is never deleted (cancel it)' USING ERRCODE = 'check_violation';
  END IF;

  IF TG_OP = 'INSERT' THEN
    -- The order's row is locked, so two returns at once get two numbers, and the order is read as it is now.
    SELECT * INTO v_order FROM commerce.orders o WHERE o.store_id = NEW.store_id AND o.id = NEW.order_id FOR NO KEY UPDATE;
    IF v_order.status NOT IN ('paid', 'fulfilled', 'closed') THEN
      RAISE EXCEPTION 'return_order_not_paid: an order that was not paid has nothing to return' USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.kind = 'withdrawal' THEN
      SELECT * INTO v_req FROM commerce.withdrawal_requests w WHERE w.store_id = NEW.store_id AND w.id = NEW.withdrawal_request_id;
      IF NOT FOUND OR v_req.status <> 'confirmed' OR v_req.confirmed_at IS NULL OR v_req.order_id <> NEW.order_id THEN
        RAISE EXCEPTION 'return_needs_confirmed_withdrawal: a withdrawal return needs a confirmed withdrawal of the same order'
          USING ERRCODE = 'check_violation';
      END IF;
      IF nullif(btrim(coalesce(v_order.company_name, '')), '') IS NOT NULL THEN
        RAISE EXCEPTION 'return_business_order: a company has no statutory right of withdrawal, so the return is a voluntary one'
          USING ERRCODE = 'check_violation';
      END IF;
      -- The right is not the store's to refuse: a withdrawal return starts approved.
      IF NEW.status <> 'approved' THEN
        RAISE EXCEPTION 'return_lifecycle: a withdrawal return starts as approved' USING ERRCODE = 'check_violation';
      END IF;
      NEW.refund_deadline := coalesce(NEW.refund_deadline, v_req.confirmed_at + interval '14 days');
    ELSIF NEW.status NOT IN ('requested', 'approved') THEN
      RAISE EXCEPTION 'return_lifecycle: a return starts as requested (or approved, when the store makes it)' USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.received_at IS NOT NULL OR NEW.inspected_at IS NOT NULL OR NEW.closed_at IS NOT NULL OR NEW.outcome IS NOT NULL
       OR NEW.refund_id IS NOT NULL OR NEW.refund_minor IS NOT NULL OR NEW.refunded_at IS NOT NULL OR NEW.refund_outside
       OR NEW.shipped_at IS NOT NULL THEN
      RAISE EXCEPTION 'return_lifecycle: a new return has not been sent, received, inspected, refunded or closed' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status = 'approved' THEN NEW.approved_at := coalesce(NEW.approved_at, now()); END IF;

    -- {order number}-R{n}, the next one for this order.
    SELECT coalesce(max(substring(r.number FROM '-R([0-9]+)$')::integer), 0) + 1 INTO v_n
      FROM commerce.returns r WHERE r.store_id = NEW.store_id AND r.order_id = NEW.order_id;
    NEW.number := v_order.number || '-R' || v_n::text;
    NEW.updated_at := now();
    RETURN NEW;
  END IF;

  IF current_setting('commerce.anonymising', true) = 'on' THEN
    IF (to_jsonb(NEW) - ARRAY['reason_note', 'decision_note', 'staff_note', 'refund_note', 'label_url', 'label_source', 'exchange_wish_note', 'updated_at'])
       IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['reason_note', 'decision_note', 'staff_note', 'refund_note', 'label_url', 'label_source', 'exchange_wish_note', 'updated_at']) THEN
      RAISE EXCEPTION 'return_fixed: only the free-text notes of a return are anonymised' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  -- UPDATE ------------------------------------------------------------------------------------------------------
  IF NEW.id <> OLD.id OR NEW.store_id <> OLD.store_id OR NEW.order_id <> OLD.order_id OR NEW.kind <> OLD.kind
     OR NEW.withdrawal_request_id IS DISTINCT FROM OLD.withdrawal_request_id OR NEW.number <> OLD.number
     OR NEW.public_token <> OLD.public_token OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'return_fixed: a return keeps its order, kind, request, number and address' USING ERRCODE = 'check_violation';
  END IF;
  NEW.updated_at := now();
  v_old := OLD.status::text;
  v_new := NEW.status::text;

  -- An ended return is only annotated.
  IF v_old IN ('closed', 'declined', 'cancelled') THEN
    IF to_jsonb(NEW) - 'staff_note' - 'updated_at' IS DISTINCT FROM to_jsonb(OLD) - 'staff_note' - 'updated_at' THEN
      RAISE EXCEPTION 'return_ended: a return that has ended cannot be changed' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF v_new <> v_old THEN
    -- The right of withdrawal is not the store's to refuse; a voluntary return is declined with a reason.
    IF v_new = 'declined' THEN
      IF OLD.kind = 'withdrawal' THEN
        RAISE EXCEPTION 'return_withdrawal_not_declinable: the right of withdrawal is not the store''s to refuse (a line the law excludes is declined as a line)'
          USING ERRCODE = 'check_violation';
      END IF;
      IF length(btrim(coalesce(NEW.decision_note, ''))) = 0 THEN
        RAISE EXCEPTION 'return_decline_reason: say why a return is declined' USING ERRCODE = 'check_violation';
      END IF;
    END IF;
    -- A withdrawal is effective on the statement and is not the store's to cancel either: when the goods never come back
    -- it is closed without a refund (a decision the store confirms), so the withdrawal and its deadline stay on record.
    IF v_new = 'cancelled' AND OLD.kind = 'withdrawal' THEN
      RAISE EXCEPTION 'return_withdrawal_not_cancellable: a withdrawal is closed, not cancelled (close it without a refund if the goods never come back)'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NOT (
      (v_old = 'requested' AND v_new IN ('approved', 'declined', 'cancelled'))
      OR (v_old = 'approved' AND v_new IN ('in_transit', 'received', 'closed', 'cancelled'))
      OR (v_old = 'in_transit' AND v_new IN ('received', 'closed', 'cancelled'))
      OR (v_old = 'received' AND v_new IN ('inspected', 'closed', 'cancelled'))
      OR (v_old = 'inspected' AND v_new = 'closed')
    ) THEN
      RAISE EXCEPTION 'return_lifecycle: a return cannot go from % to %', v_old, v_new USING ERRCODE = 'check_violation';
    END IF;
    IF v_new = 'declined' THEN NEW.outcome := 'declined'; END IF;
    IF v_new = 'cancelled' THEN NEW.outcome := 'cancelled'; END IF;
    IF v_new = 'approved' THEN NEW.approved_at := coalesce(NEW.approved_at, now()); END IF;
    IF v_new = 'in_transit' THEN NEW.shipped_at := coalesce(NEW.shipped_at, now()); END IF;
    IF v_new = 'received' THEN NEW.received_at := coalesce(NEW.received_at, now()); END IF;
    IF v_new = 'inspected' THEN NEW.inspected_at := coalesce(NEW.inspected_at, now()); END IF;
    IF v_new = 'closed' THEN
      NEW.closed_at := coalesce(NEW.closed_at, now());
      IF NEW.outcome IS NULL THEN
        NEW.outcome := CASE WHEN coalesce(NEW.refund_minor, 0) > 0 THEN 'refunded' ELSE 'no_refund' END;
      END IF;
      IF NEW.outcome NOT IN ('refunded', 'no_refund', 'exchanged') OR (NEW.outcome = 'exchanged' AND NEW.refund_minor IS NULL)
         OR (NEW.outcome = 'refunded') <> (coalesce(NEW.refund_minor, 0) > 0 AND NEW.outcome <> 'exchanged') THEN
        RAISE EXCEPTION 'return_outcome: a closed return is refunded (with its refund) or closed with no refund' USING ERRCODE = 'check_violation';
      END IF;
    END IF;
  ELSIF NEW.outcome IS DISTINCT FROM OLD.outcome AND NOT (OLD.outcome IS NULL AND NEW.outcome = 'exchanged') THEN
    RAISE EXCEPTION 'return_outcome: the outcome is set when the return ends' USING ERRCODE = 'check_violation';
  END IF;
  -- Exchanges (D239): a return ends exchanged only by settling one of its exchanges, with its refund recorded in the same step.
  IF NEW.outcome = 'exchanged' AND OLD.outcome IS DISTINCT FROM 'exchanged' AND (
       NEW.refund_minor IS NULL OR NOT EXISTS (
         SELECT 1 FROM commerce.return_exchanges x
          WHERE x.store_id = NEW.store_id AND x.return_id = NEW.id AND x.id::text = coalesce(current_setting('kaizen.exchange', true), '')
            AND x.status IN ('processed', 'settled'))) THEN
    RAISE EXCEPTION 'return_outcome: a return is exchanged only by settling its exchange' USING ERRCODE = 'check_violation';
  END IF;
  -- While an exchange of the return is processed (its order made, its stock held), the return's refund is recorded only by that exchange.
  IF NEW.refund_minor IS DISTINCT FROM OLD.refund_minor AND EXISTS (
       SELECT 1 FROM commerce.return_exchanges x
        WHERE x.store_id = NEW.store_id AND x.return_id = NEW.id AND x.status = 'processed'
          AND x.id::text IS DISTINCT FROM coalesce(current_setting('kaizen.exchange', true), '')) THEN
    RAISE EXCEPTION 'return_exchange_pending: an exchange of this return is being processed; settle or cancel it first' USING ERRCODE = 'check_violation';
  END IF;
  -- A booked label is written while the return is approved or in transit (the job's tries are counted any time it is open).
  IF (NEW.label_carrier_id IS DISTINCT FROM OLD.label_carrier_id OR NEW.label_service IS DISTINCT FROM OLD.label_service
      OR NEW.label_consignment_number IS DISTINCT FROM OLD.label_consignment_number OR NEW.label_tracking_number IS DISTINCT FROM OLD.label_tracking_number
      OR NEW.label_tracking_url IS DISTINCT FROM OLD.label_tracking_url OR NEW.label_carrier_url IS DISTINCT FROM OLD.label_carrier_url
      OR NEW.label_cost_minor IS DISTINCT FROM OLD.label_cost_minor OR NEW.label_cost_carrier IS DISTINCT FROM OLD.label_cost_carrier
      OR NEW.label_test IS DISTINCT FROM OLD.label_test OR NEW.label_booked_at IS DISTINCT FROM OLD.label_booked_at
      OR ((NEW.label_source IS NOT DISTINCT FROM 'carrier') <> (OLD.label_source IS NOT DISTINCT FROM 'carrier')))
     AND v_new NOT IN ('approved', 'in_transit') THEN
    RAISE EXCEPTION 'return_label_state: a return label is booked while the return is approved or on its way' USING ERRCODE = 'check_violation';
  END IF;
  -- The customer's exchange wish is kept as it was made.
  IF OLD.exchange_wish_at IS NOT NULL AND (NEW.exchange_wish_at IS DISTINCT FROM OLD.exchange_wish_at OR NEW.exchange_wish_note IS DISTINCT FROM OLD.exchange_wish_note) THEN
    RAISE EXCEPTION 'return_exchange_wish: the customer''s wish is kept as it was made' USING ERRCODE = 'restrict_violation';
  END IF;

  -- The steps' timestamps are set by the step, once, and never before it was reached.
  IF (OLD.approved_at IS NOT NULL AND NEW.approved_at IS DISTINCT FROM OLD.approved_at)
     OR (OLD.received_at IS NOT NULL AND NEW.received_at IS DISTINCT FROM OLD.received_at)
     OR (OLD.inspected_at IS NOT NULL AND NEW.inspected_at IS DISTINCT FROM OLD.inspected_at)
     OR (OLD.closed_at IS NOT NULL AND NEW.closed_at IS DISTINCT FROM OLD.closed_at) THEN
    RAISE EXCEPTION 'return_times: a step''s time is kept once it is set' USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW.received_at IS NOT NULL AND v_new NOT IN ('received', 'inspected', 'closed', 'cancelled'))
     OR (NEW.inspected_at IS NOT NULL AND v_new NOT IN ('inspected', 'closed', 'cancelled'))
     OR (NEW.closed_at IS NOT NULL AND v_new <> 'closed')
     OR (NEW.approved_at IS NOT NULL AND v_new IN ('requested', 'declined') ) THEN
    RAISE EXCEPTION 'return_times: a step is set when the return reaches it' USING ERRCODE = 'check_violation';
  END IF;

  -- A refund: recorded once, while the return is alive and approved, never above what was paid, and for a Stripe refund
  -- of the same order. One refund pays one return (the unique index).
  IF NEW.refund_minor IS DISTINCT FROM OLD.refund_minor OR NEW.refund_id IS DISTINCT FROM OLD.refund_id
     OR NEW.refund_outside <> OLD.refund_outside OR NEW.refunded_at IS DISTINCT FROM OLD.refunded_at
     OR NEW.shipping_refund_minor <> OLD.shipping_refund_minor THEN
    IF OLD.refund_minor IS NOT NULL THEN
      RAISE EXCEPTION 'return_refund_recorded: the refund of a return is recorded once' USING ERRCODE = 'check_violation';
    END IF;
    IF v_old NOT IN ('approved', 'in_transit', 'received', 'inspected') THEN
      RAISE EXCEPTION 'return_refund_state: a return is refunded after it is approved and before it is closed' USING ERRCODE = 'check_violation';
    END IF;
    SELECT * INTO v_order FROM commerce.orders o WHERE o.store_id = NEW.store_id AND o.id = NEW.order_id FOR NO KEY UPDATE;
    SELECT coalesce(sum(p.amount_minor) FILTER (WHERE p.status = 'captured'), 0) INTO v_paid
      FROM commerce.payments p WHERE p.store_id = NEW.store_id AND p.order_id = NEW.order_id;
    IF v_paid = 0 THEN v_paid := v_order.total_minor; END IF;
    SELECT coalesce(sum(r.refund_minor), 0) INTO v_total_refund
      FROM commerce.returns r WHERE r.store_id = NEW.store_id AND r.order_id = NEW.order_id AND r.id <> NEW.id;
    IF NEW.refund_minor IS NOT NULL AND v_total_refund + NEW.refund_minor > v_paid THEN
      RAISE EXCEPTION 'return_refund_over_paid: the returns of an order cannot be refunded more than was paid' USING ERRCODE = 'check_violation';
    END IF;
    -- The delivery a return gave back is part of its refund, and an order's delivery is given back once in all.
    IF NEW.shipping_refund_minor > coalesce(NEW.refund_minor, 0) THEN
      RAISE EXCEPTION 'return_refund_shipping: the delivery refunded is part of the refund' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.shipping_refund_minor > 0 AND (
      SELECT coalesce(sum(r.shipping_refund_minor), 0) FROM commerce.returns r
       WHERE r.store_id = NEW.store_id AND r.order_id = NEW.order_id AND r.id <> NEW.id
    ) + NEW.shipping_refund_minor > v_order.shipping_minor THEN
      RAISE EXCEPTION 'return_refund_shipping: the delivery of an order is refunded once, and never more than was paid for it'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.refund_id IS NOT NULL THEN
      SELECT rf.* INTO v_refund
        FROM commerce.refunds rf JOIN commerce.payments p ON p.store_id = rf.store_id AND p.id = rf.payment_id
       WHERE rf.store_id = NEW.store_id AND rf.id = NEW.refund_id AND p.order_id = NEW.order_id;
      IF NOT FOUND OR commerce.return_refund_parts_sum(NEW.store_id, NEW.order_id, NEW.refund_id, v_refund.amount_minor)
                        <> NEW.refund_minor - commerce.return_transferred(NEW.store_id, NEW.id) THEN
        RAISE EXCEPTION 'return_refund_match: the refund must be one of this order''s, for the amount recorded' USING ERRCODE = 'check_violation';
      END IF;
    END IF;
    NEW.refunded_at := coalesce(NEW.refunded_at, now());
  END IF;
  RETURN NEW;
END;
$_$;


--
-- Name: returns_working_once(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.returns_working_once() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF OLD.refund_working IS NOT NULL AND NEW.refund_working IS DISTINCT FROM OLD.refund_working THEN
    RAISE EXCEPTION 'return.working_once: the working of a refund is written once' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.refund_minor IS NOT NULL AND OLD.refund_working IS NULL AND NEW.refund_working IS NOT NULL THEN
    RAISE EXCEPTION 'return.working_once: the working is written with the refund' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: review_pictures_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.review_pictures_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  review uuid := CASE WHEN TG_OP = 'DELETE' THEN OLD.review_id ELSE NEW.review_id END;
  author boolean := coalesce(current_setting('kaizen.review_author', true), '') = review::text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF NOT author AND coalesce(current_setting('kaizen.review_delete', true), '') <> 'on' AND pg_trigger_depth() < 2 THEN
      RAISE EXCEPTION 'review_pictures.delete: a picture is taken out by its author or goes with its review' USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NOT author AND coalesce(current_setting('kaizen.review_writer', true), '') <> 'author' THEN
      RAISE EXCEPTION 'review_pictures.writer: a picture is added only by its review''s author' USING ERRCODE = 'check_violation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM commerce.product_reviews r WHERE r.store_id = NEW.store_id AND r.id = NEW.review_id AND r.source = 'buyer') THEN
      RAISE EXCEPTION 'review_pictures.review: only a buyer''s review has pictures' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.hidden_at IS NOT NULL THEN
      RAISE EXCEPTION 'review_pictures.fresh: a new picture is not hidden' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE: only staff's hiding changes.
  IF NEW.id <> OLD.id OR NEW.store_id <> OLD.store_id OR NEW.review_id <> OLD.review_id OR NEW.position <> OLD.position OR NEW.type <> OLD.type
    OR NEW.width <> OLD.width OR NEW.height <> OLD.height OR NEW.bytes <> OLD.bytes OR NEW.thumb_bytes <> OLD.thumb_bytes
    OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'review_pictures.fixed: a picture is never changed, only hidden or shown' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sales_series_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.sales_series_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_issued boolean;
BEGIN
  IF OLD.series NOT IN ('order', 'invoice', 'credit_note') THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;
  v_issued := CASE OLD.series
    WHEN 'order' THEN EXISTS (SELECT 1 FROM commerce.orders o WHERE o.store_id = OLD.store_id AND o.copied_from IS NULL)
    WHEN 'invoice' THEN EXISTS (SELECT 1 FROM commerce.invoices i WHERE i.store_id = OLD.store_id)
    ELSE EXISTS (SELECT 1 FROM commerce.credit_notes c WHERE c.store_id = OLD.store_id)
  END;
  IF TG_OP = 'DELETE' THEN
    IF v_issued AND EXISTS (SELECT 1 FROM commerce.stores s WHERE s.id = OLD.store_id) THEN
      RAISE EXCEPTION 'document_series.issued: the % series has issued numbers and cannot be removed', OLD.series USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.series <> OLD.series OR NEW.store_id <> OLD.store_id THEN
    RAISE EXCEPTION 'document_series.moved: a document series cannot be renamed or moved' USING ERRCODE = 'restrict_violation';
  END IF;
  IF v_issued AND NEW.prefix IS DISTINCT FROM OLD.prefix
     AND coalesce(current_setting('commerce.business_change', true), '') <> 'on' THEN
    RAISE EXCEPTION 'document_series.prefix: the prefix of the % series cannot change once numbers are issued', OLD.series USING ERRCODE = 'restrict_violation';
  END IF;
  IF v_issued AND NEW.next_number <> OLD.next_number AND NEW.next_number <> OLD.next_number + 1 THEN
    RAISE EXCEPTION 'document_series.sequence: numbers in the % series go up one at a time, with no gaps and no reuse', OLD.series USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sandbox_account(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.sandbox_account() RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT id FROM commerce.accounts WHERE lower(email) = 'sandbox@kaizenaflow.invalid'
$$;


--
-- Name: sandbox_doors(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.sandbox_doors() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM commerce.stores s WHERE s.id = NEW.store_id AND s.sandbox) THEN
    RAISE EXCEPTION '%.sandbox: a sandbox has no domain and takes no payment', TG_TABLE_NAME USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sandbox_purging(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.sandbox_purging(p_store uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
BEGIN
  IF p_store IS NULL OR COALESCE(current_setting('commerce.sandbox_purge', true), '') <> p_store::text THEN
    RETURN false;
  END IF;
  RETURN EXISTS (
    SELECT 1 FROM commerce.sandboxes x JOIN commerce.stores s ON s.id = x.store_id
     WHERE x.store_id = p_store AND x.state = 'expired' AND s.sandbox AND s.status = 'closed'
  );
END;
$$;


--
-- Name: sandboxes_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.sandboxes_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'sandboxes.no_delete: a sandbox''s row is kept' USING ERRCODE = 'restrict_violation';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NOT EXISTS (SELECT 1 FROM commerce.stores s WHERE s.id = NEW.store_id AND s.sandbox) THEN
      RAISE EXCEPTION 'sandboxes.not_sandbox: the store is not a sandbox' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.state <> 'open' THEN
      RAISE EXCEPTION 'sandboxes.state_step: a sandbox starts open' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.store_id IS DISTINCT FROM OLD.store_id OR NEW.source_store_id IS DISTINCT FROM OLD.source_store_id
     OR NEW.pass_hash IS DISTINCT FROM OLD.pass_hash OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR (OLD.first_change_at IS NOT NULL AND NEW.first_change_at IS DISTINCT FROM OLD.first_change_at)
     OR (OLD.first_publish_at IS NOT NULL AND NEW.first_publish_at IS DISTINCT FROM OLD.first_publish_at) THEN
    RAISE EXCEPTION 'sandboxes.fixed: a sandbox keeps its store, source, pass and first times' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.state IS DISTINCT FROM OLD.state AND NOT (
    (OLD.state = 'open' AND NEW.state IN ('expired', 'kept'))
    OR (OLD.state = 'expired' AND NEW.state = 'purged')
  ) THEN
    RAISE EXCEPTION 'sandboxes.state_step: a sandbox cannot go from % to %', OLD.state, NEW.state USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: search_config(text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.search_config(p_locale text) RETURNS regconfig
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
  SELECT (CASE split_part(lower(coalesce(p_locale, '')), '-', 1)
    WHEN 'nb' THEN 'pg_catalog.norwegian'
    WHEN 'nn' THEN 'pg_catalog.norwegian'
    WHEN 'no' THEN 'pg_catalog.norwegian'
    WHEN 'sv' THEN 'pg_catalog.swedish'
    WHEN 'da' THEN 'pg_catalog.danish'
    WHEN 'en' THEN 'pg_catalog.english'
    WHEN 'de' THEN 'pg_catalog.german'
    WHEN 'fi' THEN 'pg_catalog.finnish'
    WHEN 'nl' THEN 'pg_catalog.dutch'
    WHEN 'fr' THEN 'pg_catalog.french'
    WHEN 'es' THEN 'pg_catalog.spanish'
    WHEN 'it' THEN 'pg_catalog.italian'
    WHEN 'pt' THEN 'pg_catalog.portuguese'
    ELSE 'pg_catalog.simple'
  END)::regconfig
$$;


--
-- Name: search_rules_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.search_rules_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('search_rules:' || NEW.store_id::text, 0));
  IF (SELECT count(*) FROM commerce.search_rules r WHERE r.store_id = NEW.store_id) >= 200 THEN
    RAISE EXCEPTION 'A store keeps at most 200 search rules.' USING ERRCODE = 'check_violation', CONSTRAINT = 'search_rules_max';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: search_synonyms_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.search_synonyms_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('search_synonyms:' || NEW.store_id::text, 0));
  IF (SELECT count(*) FROM commerce.search_synonyms s WHERE s.store_id = NEW.store_id) >= 500 THEN
    RAISE EXCEPTION 'A store keeps at most 500 synonym groups.' USING ERRCODE = 'check_violation', CONSTRAINT = 'search_synonyms_max';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: segments_limit(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.segments_limit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('segments:' || NEW.store_id::text, 0));
  IF (SELECT count(*) FROM commerce.segments s WHERE s.store_id = NEW.store_id) >= 100 THEN
    RAISE EXCEPTION 'segments.limit: a store has at most 100 segments' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: set_price(uuid, character, bigint, timestamp with time zone); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.set_price(p_variant_id uuid, p_market_code character, p_amount_minor bigint, p_at timestamp with time zone DEFAULT now()) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_store_id uuid;
  v_currency char(3);
  v_current commerce.prices%ROWTYPE;
  v_id bigint;
BEGIN
  SELECT store_id INTO v_store_id
    FROM commerce.product_variants
   WHERE id = p_variant_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown variant %', p_variant_id;
  END IF;

  SELECT currency INTO v_currency
    FROM commerce.markets
   WHERE store_id = v_store_id AND code = p_market_code;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'the store does not sell to market %', p_market_code;
  END IF;

  SELECT * INTO v_current
    FROM commerce.prices
   WHERE variant_id = p_variant_id
     AND market_code = p_market_code
     AND valid_to IS NULL
     FOR UPDATE;

  IF FOUND THEN
    IF v_current.amount_minor = p_amount_minor THEN
      RETURN v_current.id;
    END IF;
    IF p_at <= v_current.valid_from THEN
      RAISE EXCEPTION 'a new price must start after the current one (%)',
        v_current.valid_from;
    END IF;
    UPDATE commerce.prices SET valid_to = p_at WHERE id = v_current.id;
  END IF;

  INSERT INTO commerce.prices (store_id, variant_id, market_code, currency, amount_minor, valid_from)
  VALUES (v_store_id, p_variant_id, p_market_code, v_currency, p_amount_minor, p_at)
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: set_retention_rule(text, character, integer, text, text, text, text, text, date, date, text, text, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.set_retention_rule(p_kind text, p_country character, p_value integer, p_unit text, p_counts_from text, p_source text, p_source_url text, p_basis text, p_checked_on date, p_valid_from date, p_enforced_by text, p_note text, p_account uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_latest date;
  v_previous record;
  v_months integer;
  v_id uuid;
BEGIN
  IF p_country IS NOT NULL AND NOT EXISTS (SELECT 1 FROM commerce.countries c WHERE c.code = p_country) THEN
    RAISE EXCEPTION 'retention_rule_country: unknown country %', p_country USING ERRCODE = 'check_violation';
  END IF;
  IF p_value IS NULL OR p_value <= 0 OR p_unit NOT IN ('days', 'months') THEN
    RAISE EXCEPTION 'retention_rule_period: a period is a whole number of days or months above zero' USING ERRCODE = 'check_violation';
  END IF;
  v_months := CASE WHEN p_unit = 'months' THEN p_value ELSE ceil(p_value / 30.0)::integer END;
  IF v_months > 600 THEN
    RAISE EXCEPTION 'retention_rule_ceiling: a period above fifty years is refused' USING ERRCODE = 'check_violation';
  END IF;
  IF p_kind IN ('bookkeeping', 'host_bookkeeping') AND (p_unit <> 'months' OR p_value < 60) THEN
    RAISE EXCEPTION 'retention_rule_floor: bookkeeping data is kept at least five years (60 months)' USING ERRCODE = 'check_violation';
  END IF;
  IF p_valid_from IS NULL OR p_checked_on IS NULL THEN
    RAISE EXCEPTION 'retention_rule_dates: a rule needs the date it starts and the date it was checked' USING ERRCODE = 'check_violation';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('retention_rule:' || p_kind || ':' || coalesce(p_country, '__'), 0));

  SELECT max(r.valid_from) INTO v_latest FROM commerce.retention_rules r
   WHERE r.kind = p_kind AND coalesce(r.country, '__') = coalesce(p_country, '__');
  IF v_latest IS NOT NULL AND p_valid_from <= v_latest THEN
    RAISE EXCEPTION 'retention_rule_backdated: the new rule must start after the latest one (%)', v_latest USING ERRCODE = 'check_violation';
  END IF;

  SELECT r.period_value, r.period_unit, r.enforced_by INTO v_previous FROM commerce.retention_rules r
   WHERE r.kind = p_kind AND coalesce(r.country, '__') = coalesce(p_country, '__') AND r.valid_to IS NULL;

  UPDATE commerce.retention_rules SET valid_to = p_valid_from
   WHERE kind = p_kind AND coalesce(country, '__') = coalesce(p_country, '__') AND valid_to IS NULL;

  INSERT INTO commerce.retention_rules (kind, country, period_value, period_unit, counts_from, source, source_url, basis, checked_on, valid_from, enforced_by, note, created_by)
  VALUES (p_kind, p_country, p_value, p_unit, p_counts_from, p_source, p_source_url, p_basis, p_checked_on, p_valid_from,
          coalesce(p_enforced_by, v_previous.enforced_by, 'runRetention'), coalesce(p_note, ''), p_account)
  RETURNING id INTO v_id;

  INSERT INTO commerce.audit_log (store_id, account_id, action, area, details)
  VALUES (NULL, p_account, 'retention.rule_set', 'platform', jsonb_build_object(
    'kind', p_kind, 'country', p_country, 'period_value', p_value, 'period_unit', p_unit,
    'previous_value', v_previous.period_value, 'previous_unit', v_previous.period_unit,
    'valid_from', p_valid_from, 'basis', p_basis, 'checked_on', p_checked_on));
  RETURN v_id;
END;
$$;


--
-- Name: set_sales_series(uuid, text, text, bigint); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.set_sales_series(p_store uuid, p_series text, p_prefix text, p_next_number bigint) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
BEGIN
  IF p_series NOT IN ('invoice', 'credit_note') THEN
    RAISE EXCEPTION 'document_series.unknown: % is not an invoice or credit note series', p_series USING ERRCODE = 'check_violation';
  END IF;
  IF p_prefix IS NULL OR p_prefix !~ '^[A-Za-z0-9._/-]{0,10}$' THEN
    RAISE EXCEPTION 'document_series.prefix: a prefix is up to 10 letters, digits and . _ / -' USING ERRCODE = 'check_violation';
  END IF;
  IF p_next_number IS NULL OR p_next_number < 1 THEN
    RAISE EXCEPTION 'document_series.number: the first number must be 1 or more' USING ERRCODE = 'check_violation';
  END IF;
  IF (p_series = 'invoice' AND EXISTS (SELECT 1 FROM commerce.invoices i WHERE i.store_id = p_store))
     OR (p_series = 'credit_note' AND EXISTS (SELECT 1 FROM commerce.credit_notes c WHERE c.store_id = p_store)) THEN
    RAISE EXCEPTION 'document_series.issued: numbers already issued cannot be changed' USING ERRCODE = 'restrict_violation';
  END IF;
  UPDATE commerce.document_series SET prefix = p_prefix, next_number = p_next_number
   WHERE store_id = p_store AND series = p_series;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'document_series.unknown: the store has no series %', p_series USING ERRCODE = 'no_data_found';
  END IF;
END;
$_$;


--
-- Name: set_shipping_vat_rule(character, text, text, date, text, boolean, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.set_shipping_vat_rule(p_country character, p_rule text, p_source text, p_checked_on date, p_note text, p_verified boolean, p_account uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM commerce.countries c WHERE c.code = p_country) THEN
    RAISE EXCEPTION 'shipping_vat_country: unknown country %', p_country USING ERRCODE = 'check_violation';
  END IF;
  IF p_verified AND (p_account IS NULL OR p_checked_on IS NULL OR length(trim(coalesce(p_source, ''))) < 8) THEN
    RAISE EXCEPTION 'shipping_vat_verified: a verified rule names its source, the date checked and the person' USING ERRCODE = 'check_violation';
  END IF;
  INSERT INTO commerce.shipping_vat_rules (country_code, rule, source, checked_on, note, verified_by, verified_at, updated_at)
  VALUES (p_country, p_rule, coalesce(p_source, ''), p_checked_on, coalesce(p_note, ''),
          CASE WHEN p_verified THEN p_account END, CASE WHEN p_verified THEN now() END, now())
  ON CONFLICT (country_code) DO UPDATE SET
    rule = EXCLUDED.rule, source = EXCLUDED.source, checked_on = EXCLUDED.checked_on, note = EXCLUDED.note,
    verified_by = EXCLUDED.verified_by, verified_at = EXCLUDED.verified_at, updated_at = now();
  INSERT INTO commerce.audit_log (store_id, account_id, action, details)
  VALUES (NULL, p_account, 'vat.shipping_rule_set', jsonb_build_object(
    'country', p_country, 'rule', p_rule, 'verified', p_verified, 'source', p_source, 'checked_on', p_checked_on));
END;
$$;


--
-- Name: set_site_from_store(boolean, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.set_site_from_store(p_on boolean, p_account uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_store uuid := commerce.house_store();
  v_now boolean;
BEGIN
  IF v_store IS NULL THEN
    RAISE EXCEPTION 'set_site_from_store: Kaizena Flow''s own store does not exist' USING ERRCODE = 'no_data_found';
  END IF;
  SELECT site_from_store INTO v_now FROM commerce.platform_settings FOR UPDATE;
  IF v_now IS NOT DISTINCT FROM p_on THEN
    RETURN false;
  END IF;
  IF p_on THEN
    UPDATE commerce.stores SET private_mode = false WHERE id = v_store AND private_mode;
    UPDATE commerce.platform_settings SET site_from_store = true, site_from_store_by = p_account;
  ELSE
    UPDATE commerce.platform_settings SET site_from_store = false, site_from_store_by = p_account;
    UPDATE commerce.stores SET private_mode = true WHERE id = v_store AND NOT private_mode;
  END IF;
  RETURN true;
END;
$$;


--
-- Name: set_vat_rate(character, text, numeric, date, text, date, text, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.set_vat_rate(p_country character, p_category text, p_rate numeric, p_valid_from date, p_source text, p_checked_on date, p_note text, p_account uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_latest date;
  v_previous numeric;
BEGIN
  IF p_category = 'exempt' THEN
    RAISE EXCEPTION 'vat_rate_exempt: exempt goods always carry no VAT and have no rate' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM commerce.countries c WHERE c.code = p_country) THEN
    RAISE EXCEPTION 'vat_rate_country: unknown country %', p_country USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM commerce.vat_categories k WHERE k.code = p_category) THEN
    RAISE EXCEPTION 'vat_rate_category: unknown category %', p_category USING ERRCODE = 'check_violation';
  END IF;
  IF p_rate IS NULL OR p_rate < 0 OR p_rate >= 1 THEN
    RAISE EXCEPTION 'vat_rate_value: a rate is a fraction from 0 up to, not including, 1' USING ERRCODE = 'check_violation';
  END IF;
  IF p_valid_from IS NULL OR p_checked_on IS NULL THEN
    RAISE EXCEPTION 'vat_rate_dates: a rate needs the date it starts and the date it was checked' USING ERRCODE = 'check_violation';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('vat_rate:' || p_country || ':' || p_category, 0));

  SELECT max(r.valid_from) INTO v_latest
    FROM commerce.vat_rates r WHERE r.country_code = p_country AND r.category = p_category;
  IF v_latest IS NOT NULL AND p_valid_from <= v_latest THEN
    RAISE EXCEPTION 'vat_rate_backdated: the new rate must start after the latest one (%); correct a mistake by adding a rate with a note', v_latest
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT r.rate INTO v_previous
    FROM commerce.vat_rates r
   WHERE r.country_code = p_country AND r.category = p_category AND r.valid_to IS NULL;

  UPDATE commerce.vat_rates SET valid_to = p_valid_from
   WHERE country_code = p_country AND category = p_category AND valid_to IS NULL;

  INSERT INTO commerce.vat_rates (country_code, category, rate, valid_from, source, checked_on, note, created_by)
  VALUES (p_country, p_category, p_rate, p_valid_from, p_source, p_checked_on, coalesce(p_note, ''), p_account);

  -- The country's cached standard rate follows the standard category (a date in the future by sync_standard_vat_rates()).
  IF p_category = 'standard' THEN
    UPDATE commerce.countries SET standard_vat_rate = commerce.vat_rate(p_country, 'standard', now()) WHERE code = p_country;
  END IF;

  INSERT INTO commerce.audit_log (store_id, account_id, action, details)
  VALUES (NULL, p_account, 'vat.rate_set', jsonb_build_object(
    'country', p_country, 'category', p_category, 'rate', p_rate, 'previous_rate', v_previous,
    'valid_from', p_valid_from, 'source', p_source, 'checked_on', p_checked_on));
END;
$$;


--
-- Name: shipment_has_lines(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.shipment_has_lines() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM commerce.shipments s WHERE s.id = NEW.id AND NOT s.legacy)
     AND NOT EXISTS (SELECT 1 FROM commerce.shipment_lines sl WHERE sl.shipment_id = NEW.id) THEN
    RAISE EXCEPTION 'shipment.no_lines: a parcel names the lines and units in it' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: shipment_lines_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.shipment_lines_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_line record;
  v_ship record;
  v_sent integer;
  v_closed integer;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'shipment_line.append_only: the lines of a parcel are a record and are not changed or removed' USING ERRCODE = 'restrict_violation';
  END IF;
  SELECT ol.store_id, ol.order_id, ol.quantity, ol.delivery, ol.variant_id INTO v_line
    FROM commerce.order_lines ol WHERE ol.id = NEW.order_line_id FOR NO KEY UPDATE;
  SELECT s.store_id, s.order_id, s.undone_at INTO v_ship FROM commerce.shipments s WHERE s.id = NEW.shipment_id;
  IF v_line IS NULL OR v_ship IS NULL OR v_line.store_id <> NEW.store_id OR v_ship.store_id <> NEW.store_id OR v_line.order_id <> v_ship.order_id THEN
    RAISE EXCEPTION 'shipment_line.order: a parcel holds lines of its own order only' USING ERRCODE = 'check_violation';
  END IF;
  IF v_ship.undone_at IS NOT NULL THEN
    RAISE EXCEPTION 'shipment_line.undone: an undone parcel takes no lines' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (SELECT 1 FROM commerce.orders o WHERE o.id = v_ship.order_id AND o.copied_from IS NOT NULL) THEN
    RAISE EXCEPTION 'copied_order: an order copied from another store is history and cannot get a row in %', TG_TABLE_NAME USING ERRCODE = 'check_violation';
  END IF;
  IF v_line.delivery <> 'physical' OR v_line.variant_id IS NULL THEN
    RAISE EXCEPTION 'shipment_line.not_physical: only goods that are shipped go in a parcel' USING ERRCODE = 'check_violation';
  END IF;
  SELECT coalesce(sum(sl.quantity), 0)::integer INTO v_sent
    FROM commerce.shipment_lines sl JOIN commerce.shipments s ON s.store_id = sl.store_id AND s.id = sl.shipment_id
   WHERE sl.order_line_id = NEW.order_line_id AND s.undone_at IS NULL;
  IF v_sent + NEW.quantity > v_line.quantity THEN
    RAISE EXCEPTION 'shipment_line.too_many: % units of a line of % would be in parcels', v_sent + NEW.quantity, v_line.quantity USING ERRCODE = 'check_violation';
  END IF;
  v_closed := commerce.closed_quantity(NEW.order_line_id);
  IF v_sent + NEW.quantity > v_line.quantity - v_closed THEN
    RAISE EXCEPTION 'shipment_line.too_many: % units of a line of %, % of them closed as not to be sent, would be in parcels', v_sent + NEW.quantity, v_line.quantity, v_closed
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: shipments_edit_pending(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.shipments_edit_pending() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM commerce.order_edits e WHERE e.store_id = NEW.store_id AND e.order_id = NEW.order_id AND e.status = 'awaiting_payment') THEN
    RAISE EXCEPTION 'shipment.edit_pending: a change to this order waits for the customer''s payment; nothing is sent until it is paid, cancelled or expired'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: shipments_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.shipments_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'shipment.append_only: a parcel is a record; it is undone, never removed' USING ERRCODE = 'restrict_violation';
  END IF;
  IF (to_jsonb(NEW) - ARRAY['legacy', 'undone_at', 'undone_by', 'undo_reason', 'label_cost_minor', 'label_cost_carrier'])
     IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['legacy', 'undone_at', 'undone_by', 'undo_reason', 'label_cost_minor', 'label_cost_carrier']) THEN
    RAISE EXCEPTION 'shipment.frozen: a parcel''s carrier, tracking, label and order are a record and are not changed' USING ERRCODE = 'restrict_violation';
  END IF;
  -- What the label cost (D415): written once, from nothing, both together.
  IF (NEW.label_cost_minor IS DISTINCT FROM OLD.label_cost_minor OR NEW.label_cost_carrier IS DISTINCT FROM OLD.label_cost_carrier)
     AND (OLD.label_cost_minor IS NOT NULL OR OLD.label_cost_carrier IS NOT NULL OR NEW.label_cost_minor IS NULL) THEN
    RAISE EXCEPTION 'shipment.label_cost: what a label cost is kept once and not changed' USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW.legacy IS DISTINCT FROM OLD.legacy AND NOT (NEW.legacy AND NOT OLD.legacy) THEN
    RAISE EXCEPTION 'shipment.legacy: a parcel recorded before parcels named their lines stays so' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.undone_at IS NOT NULL THEN
    IF NEW.undone_at IS DISTINCT FROM OLD.undone_at OR NEW.undone_by IS DISTINCT FROM OLD.undone_by
       OR (NEW.undo_reason IS DISTINCT FROM OLD.undo_reason
           AND NOT (NEW.undo_reason = '[removed]' AND coalesce(current_setting('commerce.anonymising', true), '') = 'on')) THEN
      RAISE EXCEPTION 'shipment.undone_final: an undone parcel stays undone, as it was recorded' USING ERRCODE = 'restrict_violation';
    END IF;
  ELSIF NEW.undone_at IS NOT NULL OR NEW.undone_by IS NOT NULL OR NEW.undo_reason IS NOT NULL THEN
    IF coalesce(current_setting('kaizen.shipment_undo', true), '') <> OLD.id::text THEN
      RAISE EXCEPTION 'shipment.undo_function: a parcel is undone only by commerce.undo_shipment()' USING ERRCODE = 'restrict_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: shipments_method_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.shipments_method_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_method text;
BEGIN
  SELECT o.delivery_method INTO v_method FROM commerce.orders o WHERE o.store_id = NEW.store_id AND o.id = NEW.order_id;
  IF NEW.method = 'parcel' AND v_method = 'pickup' THEN
    RAISE EXCEPTION 'shipment.pickup_order: the customer collects this order; mark it collected instead of sending it' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.method IN ('pickup', 'local') AND v_method IS DISTINCT FROM NEW.method THEN
    RAISE EXCEPTION 'shipment.method: a % handover is only for an order delivered so (this one is %)', NEW.method, v_method USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: shipments_not_held(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.shipments_not_held() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM commerce.orders o WHERE o.store_id = NEW.store_id AND o.id = NEW.order_id AND o.held_at IS NOT NULL) THEN
    RAISE EXCEPTION 'shipments.held: this order is on hold; release it before anything of it is sent' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: shipping_methods_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.shipping_methods_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND (NEW.store_id <> OLD.store_id OR NEW.market_code <> OLD.market_code OR NEW.currency <> OLD.currency) THEN
    RAISE EXCEPTION 'shipping_methods.market_fixed: a method stays in its market and currency' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'INSERT' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('shipping_methods:' || NEW.store_id::text || ':' || NEW.market_code, 0));
    IF (SELECT count(*) FROM commerce.shipping_methods m WHERE m.store_id = NEW.store_id AND m.market_code = NEW.market_code) >= 10 THEN
      RAISE EXCEPTION 'shipping_methods.limit: a country has at most 10 shipping methods' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: shipping_profiles_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.shipping_profiles_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.store_id <> OLD.store_id THEN
    RAISE EXCEPTION 'shipping_profiles.store_fixed: a profile stays with its store' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'INSERT' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('shipping_profiles:' || NEW.store_id::text, 0));
    IF (SELECT count(*) FROM commerce.shipping_profiles p WHERE p.store_id = NEW.store_id) >= 20 THEN
      RAISE EXCEPTION 'shipping_profiles.limit: a store has at most 20 shipping profiles besides General' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: shipping_rate_group_problem(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.shipping_rate_group_problem(p_store uuid, p_method uuid, p_zone uuid, p_profile uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_count integer;
  v_bases integer;
  v_basis text;
  v_expected bigint := 0;
  v_open boolean := false;
  r record;
BEGIN
  SELECT count(*), count(DISTINCT basis), min(basis) INTO v_count, v_bases, v_basis
    FROM commerce.shipping_method_rates
   WHERE store_id = p_store AND method_id = p_method AND zone_id IS NOT DISTINCT FROM p_zone AND profile_id IS NOT DISTINCT FROM p_profile;
  IF v_count = 0 THEN RETURN NULL; END IF;
  IF p_zone IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM commerce.shipping_zones z JOIN commerce.shipping_methods m ON m.store_id = z.store_id AND m.market_code = z.market_code
     WHERE z.store_id = p_store AND z.id = p_zone AND m.id = p_method
  ) THEN
    RETURN 'shipping_rates.zone_market';
  END IF;
  IF v_count > 10 THEN RETURN 'shipping_rates.too_many'; END IF;
  IF v_bases > 1 THEN RETURN 'shipping_rates.mixed_basis'; END IF;
  IF v_basis = 'flat' THEN
    RETURN CASE WHEN v_count > 1 THEN 'shipping_rates.two_flat' END;
  END IF;
  FOR r IN
    SELECT min_value, max_value FROM commerce.shipping_method_rates
     WHERE store_id = p_store AND method_id = p_method AND zone_id IS NOT DISTINCT FROM p_zone AND profile_id IS NOT DISTINCT FROM p_profile
     ORDER BY min_value, max_value NULLS LAST, id
  LOOP
    IF v_open OR r.min_value < v_expected THEN RETURN 'shipping_rates.overlap'; END IF;
    IF r.min_value > v_expected THEN RETURN 'shipping_rates.gap'; END IF;
    IF r.max_value IS NULL THEN v_open := true; ELSE v_expected := r.max_value; END IF;
  END LOOP;
  RETURN NULL;
END;
$$;


--
-- Name: shipping_rates_tiers(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.shipping_rates_tiers() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_problem text;
BEGIN
  IF TG_OP <> 'DELETE' THEN
    v_problem := commerce.shipping_rate_group_problem(NEW.store_id, NEW.method_id, NEW.zone_id, NEW.profile_id);
    IF v_problem IS NOT NULL THEN
      RAISE EXCEPTION '%: the rates of a method for one zone and profile are one flat price or tiers from 0 that meet without a gap (at most 10), in the method''s own country',
        v_problem USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF TG_OP <> 'INSERT' THEN
    v_problem := commerce.shipping_rate_group_problem(OLD.store_id, OLD.method_id, OLD.zone_id, OLD.profile_id);
    IF v_problem IS NOT NULL THEN
      RAISE EXCEPTION '%: the rates of a method for one zone and profile are one flat price or tiers from 0 that meet without a gap (at most 10), in the method''s own country',
        v_problem USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: shipping_vat_rule(character); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.shipping_vat_rule(p_country character) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce(
    (SELECT s.rule FROM commerce.shipping_vat_rules s WHERE s.country_code = p_country AND s.verified_at IS NOT NULL),
    'standard'
  )
$$;


--
-- Name: shipping_zones_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.shipping_zones_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_problem text;
  v_taken record;
BEGIN
  IF TG_OP = 'UPDATE' AND (NEW.store_id <> OLD.store_id OR NEW.market_code <> OLD.market_code) THEN
    RAISE EXCEPTION 'shipping_zones.market_fixed: a zone stays in its market' USING ERRCODE = 'check_violation';
  END IF;
  v_problem := commerce.postal_patterns_problem(NEW.patterns);
  IF v_problem IS NOT NULL THEN
    RAISE EXCEPTION '%: the zone''s postal codes are not a list of codes and prefixes (at most 10 characters each, 3,000 in all, none twice)', v_problem
      USING ERRCODE = 'check_violation';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('shipping_zones:' || NEW.store_id::text || ':' || NEW.market_code, 0));
  IF TG_OP = 'INSERT' AND (SELECT count(*) FROM commerce.shipping_zones z WHERE z.store_id = NEW.store_id AND z.market_code = NEW.market_code) >= 20 THEN
    RAISE EXCEPTION 'shipping_zones.limit: a country has at most 20 zones' USING ERRCODE = 'check_violation';
  END IF;
  SELECT z.name, p INTO v_taken
    FROM commerce.shipping_zones z, unnest(z.patterns) p
   WHERE z.store_id = NEW.store_id AND z.market_code = NEW.market_code AND z.id <> NEW.id AND p = ANY (NEW.patterns)
   LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'shipping_zones.taken: % is already in the zone %', v_taken.p, v_taken.name USING ERRCODE = 'unique_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: site_layout_is_type(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.site_layout_is_type() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.header_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM commerce.pages p
     WHERE p.id = NEW.header_id AND p.type = 'header'
       AND (TG_TABLE_NAME <> 'platform_settings' OR p.store_id IS NULL)
  ) THEN
    RAISE EXCEPTION 'a site''s header must be one of its headers';
  END IF;
  IF NEW.footer_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM commerce.pages p
     WHERE p.id = NEW.footer_id AND p.type = 'footer'
       AND (TG_TABLE_NAME <> 'platform_settings' OR p.store_id IS NULL)
  ) THEN
    RAISE EXCEPTION 'a site''s footer must be one of its footers';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sms_consent_events_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.sms_consent_events_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF current_setting('kaizen.sms_consent_event', true) IS DISTINCT FROM 'on' THEN
      RAISE EXCEPTION 'sms_consent_events.writer: the history is written by the subscribers'' rules' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    RAISE EXCEPTION 'sms_consent_events.fixed: the history is never changed' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (SELECT 1 FROM commerce.sms_subscribers s WHERE s.store_id = OLD.store_id AND s.id = OLD.subscriber_id) THEN
    RAISE EXCEPTION 'sms_consent_events.kept: the history goes only with its number' USING ERRCODE = 'check_violation';
  END IF;
  RETURN OLD;
END;
$$;


--
-- Name: sms_messages_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.sms_messages_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF (TG_OP = 'INSERT' OR (NEW.status = 'sent' AND OLD.status = 'queued'))
     AND NOT EXISTS (SELECT 1 FROM commerce.sms_subscribers s WHERE s.store_id = NEW.store_id AND s.id = NEW.subscriber_id AND s.status = 'subscribed') THEN
    RAISE EXCEPTION 'sms_messages.consent: a text goes only to a subscribed number' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NEW.campaign_id <> OLD.campaign_id OR NEW.subscriber_id <> OLD.subscriber_id OR NEW.store_id <> OLD.store_id THEN
      RAISE EXCEPTION 'sms_messages.fixed: a message keeps its campaign and number' USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.status IN ('failed', 'skipped', 'delivered') AND NEW.status <> OLD.status THEN
      RAISE EXCEPTION 'sms_messages.final: % is final', OLD.status USING ERRCODE = 'check_violation';
    END IF;
    NEW.updated_at := now();
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sms_subscribers_first_event(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.sms_subscribers_first_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM set_config('kaizen.sms_consent_event', 'on', true);
  INSERT INTO commerce.sms_consent_events (store_id, subscriber_id, kind, source, consent_text)
  VALUES (NEW.store_id, NEW.id, CASE NEW.status WHEN 'pending' THEN 'requested' ELSE NEW.status END, NEW.source, NEW.consent_text);
  PERFORM set_config('kaizen.sms_consent_event', '', true);
  RETURN NULL;
END;
$$;


--
-- Name: sms_subscribers_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.sms_subscribers_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status NOT IN ('pending', 'subscribed') THEN
      RAISE EXCEPTION 'sms_subscribers.insert: a number starts pending or subscribed' USING ERRCODE = 'check_violation';
    END IF;
    NEW.unsubscribed_at := NULL;
    NEW.unsubscribe_source := NULL;
  ELSE
    IF NEW.id <> OLD.id OR NEW.store_id <> OLD.store_id OR NEW.phone <> OLD.phone OR NEW.token <> OLD.token OR NEW.created_at <> OLD.created_at THEN
      RAISE EXCEPTION 'sms_subscribers.fixed: the number, its token and its store are fixed' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status = OLD.status AND OLD.status = 'subscribed'
       AND (NEW.consent_text <> OLD.consent_text OR NEW.consented_at <> OLD.consented_at OR NEW.source <> OLD.source
            OR NEW.source_ref IS DISTINCT FROM OLD.source_ref) THEN
      RAISE EXCEPTION 'sms_subscribers.consent: a subscribed number keeps the consent it gave' USING ERRCODE = 'check_violation';
    END IF;
    IF NOT (
      (OLD.status = 'pending' AND NEW.status IN ('pending', 'subscribed', 'unsubscribed'))
      OR (OLD.status = 'subscribed' AND NEW.status IN ('subscribed', 'unsubscribed'))
      OR (OLD.status = 'unsubscribed' AND NEW.status IN ('unsubscribed', 'pending', 'subscribed'))
    ) THEN
      RAISE EXCEPTION 'sms_subscribers.move: % cannot become %', OLD.status, NEW.status USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status = 'unsubscribed' AND OLD.status = 'unsubscribed'
       AND (NEW.unsubscribed_at IS DISTINCT FROM OLD.unsubscribed_at OR NEW.unsubscribe_source IS DISTINCT FROM OLD.unsubscribe_source) THEN
      RAISE EXCEPTION 'sms_subscribers.left: a number that left keeps when and how' USING ERRCODE = 'check_violation';
    END IF;
    NEW.updated_at := now();
  END IF;

  IF NEW.status = 'unsubscribed' THEN
    IF NEW.unsubscribe_source IS NULL THEN
      RAISE EXCEPTION 'sms_subscribers.unsubscribed: leaving says how' USING ERRCODE = 'check_violation';
    END IF;
    IF TG_OP = 'INSERT' OR OLD.status <> 'unsubscribed' THEN
      NEW.unsubscribed_at := now();
    END IF;
  ELSE
    NEW.unsubscribed_at := NULL;
    NEW.unsubscribe_source := NULL;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.status <> OLD.status THEN
    PERFORM set_config('kaizen.sms_consent_event', 'on', true);
    INSERT INTO commerce.sms_consent_events (store_id, subscriber_id, kind, source, consent_text)
    VALUES (NEW.store_id, NEW.id, CASE NEW.status WHEN 'pending' THEN 'requested' ELSE NEW.status END,
            CASE WHEN NEW.status = 'unsubscribed' THEN NEW.unsubscribe_source ELSE NEW.source END,
            CASE WHEN NEW.status = 'unsubscribed' THEN NULL ELSE NEW.consent_text END);
    PERFORM set_config('kaizen.sms_consent_event', '', true);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: start_export_job(uuid, text, uuid, jsonb, integer); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.start_export_job(p_store uuid, p_kind text, p_requested_by uuid, p_options jsonb, p_max integer) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_active integer;
  v_id uuid;
BEGIN
  IF p_kind NOT IN ('product_export', 'order_export', 'customer_export', 'redirect_export', 'inventory_export') THEN
    RAISE EXCEPTION 'data_job.kind: % is not an export', p_kind USING ERRCODE = 'check_violation';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('data_jobs:' || p_store::text, 0));
  SELECT count(*)::integer INTO v_active
    FROM commerce.data_jobs
   WHERE store_id = p_store AND kind NOT IN ('product_import', 'redirect_import', 'inventory_import', 'customer_import', 'order_history_import') AND status IN ('queued', 'running');
  IF v_active >= p_max THEN
    RAISE EXCEPTION 'data_job.too_many_exports: % exports are already being made for this store', v_active USING ERRCODE = 'check_violation';
  END IF;
  INSERT INTO commerce.data_jobs (store_id, kind, status, phase, format, options, requested_by)
  VALUES (p_store, p_kind, 'queued', 'write', 'kaizen', coalesce(p_options, '{}'::jsonb), p_requested_by)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: starter_offered_source(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.starter_offered_source(p_starter uuid) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT s.id
    FROM commerce.store_starters st
    JOIN commerce.stores s ON s.id = COALESCE(st.published_store_id, st.store_id)
   WHERE st.id = p_starter AND st.kind = 'content' AND st.published AND st.archived_at IS NULL AND s.starter AND s.status = 'active'
$$;


--
-- Name: starter_source(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.starter_source(p_starter uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_store uuid;
BEGIN
  IF p_starter IS NULL THEN
    SELECT id INTO v_store FROM commerce.stores WHERE is_template;
    IF v_store IS NULL THEN
      RAISE EXCEPTION 'there is no template store';
    END IF;
    RETURN v_store;
  END IF;
  v_store := commerce.starter_offered_source(p_starter);
  IF v_store IS NULL THEN
    SELECT s.id INTO v_store
      FROM commerce.store_starters st
      JOIN commerce.stores s ON s.id = st.store_id
     WHERE st.id = p_starter AND st.kind = 'demo' AND st.archived_at IS NULL AND s.starter AND s.status = 'active';
  END IF;
  IF v_store IS NULL THEN
    RAISE EXCEPTION 'store_starters.not_offered: that store template is not offered' USING ERRCODE = 'check_violation';
  END IF;
  RETURN v_store;
END;
$$;


--
-- Name: stock_context(text, text, uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.stock_context(p_reason text, p_source text, p_account uuid DEFAULT NULL::uuid, p_order uuid DEFAULT NULL::uuid, p_return uuid DEFAULT NULL::uuid, p_job uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM set_config('kaizen.stock', jsonb_strip_nulls(jsonb_build_object(
    'reason', p_reason, 'source', p_source, 'account', p_account, 'order', p_order,
    'return', p_return, 'job', p_job, 'note', p_note))::text, true);
END;
$$;


--
-- Name: stock_context_clear(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.stock_context_clear() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM set_config('kaizen.stock', '', true);
END;
$$;


--
-- Name: stock_context_uuid(jsonb, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.stock_context_uuid(p_context jsonb, p_key text) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
BEGIN
  RETURN (p_context ->> p_key)::uuid;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END;
$$;


--
-- Name: stock_document_lines_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.stock_document_lines_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_transfer boolean := TG_TABLE_NAME = 'stock_transfer_lines';
  v_parent uuid;
  v_status text;
BEGIN
  v_parent := CASE WHEN v_transfer THEN (to_jsonb(coalesce(NEW, OLD)) ->> 'transfer_id')::uuid ELSE (to_jsonb(coalesce(NEW, OLD)) ->> 'purchase_order_id')::uuid END;
  IF v_transfer THEN
    SELECT t.status INTO v_status FROM commerce.stock_transfers t WHERE t.id = v_parent;
  ELSE
    SELECT p.status INTO v_status FROM commerce.purchase_orders p WHERE p.id = v_parent;
  END IF;
  -- The document itself going (a draft deleted) takes its lines with it.
  IF TG_OP = 'DELETE' AND v_status IS NULL THEN RETURN OLD; END IF;
  IF TG_OP IN ('INSERT', 'DELETE') THEN
    IF v_status <> 'draft' THEN
      RAISE EXCEPTION 'stock_document_lines.draft: lines change only while it is a draft' USING ERRCODE = 'check_violation';
    END IF;
    IF TG_OP = 'INSERT' AND NEW.received <> 0 THEN
      RAISE EXCEPTION 'stock_document_lines.received: nothing is received on a draft' USING ERRCODE = 'check_violation';
    END IF;
    RETURN coalesce(NEW, OLD);
  END IF;
  IF (to_jsonb(NEW) - 'received' - 'quantity' - 'unit_cost_minor') IS DISTINCT FROM (to_jsonb(OLD) - 'received' - 'quantity' - 'unit_cost_minor') THEN
    RAISE EXCEPTION 'stock_document_lines.fixed: a line keeps its document and variant' USING ERRCODE = 'check_violation';
  END IF;
  IF v_status = 'draft' THEN
    IF NEW.received <> 0 THEN
      RAISE EXCEPTION 'stock_document_lines.received: nothing is received on a draft' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF (to_jsonb(NEW) - 'received') IS DISTINCT FROM (to_jsonb(OLD) - 'received') THEN
    RAISE EXCEPTION 'stock_document_lines.fixed: a line is fixed once it is sent or ordered' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.received < OLD.received OR v_status NOT IN ('sent', 'ordered') THEN
    RAISE EXCEPTION 'stock_document_lines.received: units are received only forward, while it is open' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: stock_documents_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.stock_documents_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_open text := CASE WHEN TG_TABLE_NAME = 'stock_transfers' THEN 'sent' ELSE 'ordered' END;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status <> 'draft' THEN
      RAISE EXCEPTION 'stock_documents.kept: only a draft is deleted' USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'stock_documents.draft: a transfer or a purchase order starts as a draft' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.store_id <> OLD.store_id OR NEW.id <> OLD.id THEN
    RAISE EXCEPTION 'stock_documents.fixed: a document stays its store''s' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status <> OLD.status AND NOT (
       (OLD.status = 'draft' AND NEW.status IN (v_open, 'cancelled'))
    OR (OLD.status = v_open AND NEW.status IN ('received', 'cancelled'))
  ) THEN
    RAISE EXCEPTION 'stock_documents.status: % cannot become %', OLD.status, NEW.status USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.status <> 'draft' AND (
    CASE WHEN TG_TABLE_NAME = 'stock_transfers'
      THEN (to_jsonb(NEW) ->> 'origin_id', to_jsonb(NEW) ->> 'destination_id') IS DISTINCT FROM (to_jsonb(OLD) ->> 'origin_id', to_jsonb(OLD) ->> 'destination_id')
      ELSE (to_jsonb(NEW) ->> 'location_id', to_jsonb(NEW) ->> 'currency', to_jsonb(NEW) ->> 'supplier') IS DISTINCT FROM (to_jsonb(OLD) ->> 'location_id', to_jsonb(OLD) ->> 'currency', to_jsonb(OLD) ->> 'supplier')
    END
  ) THEN
    RAISE EXCEPTION 'stock_documents.fixed: where it goes is fixed once it is out of draft' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.status IN ('received', 'cancelled') AND to_jsonb(NEW) - 'updated_at' IS DISTINCT FROM to_jsonb(OLD) - 'updated_at' THEN
    RAISE EXCEPTION 'stock_documents.closed: a received or cancelled document stays as it closed' USING ERRCODE = 'check_violation';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: stock_requests_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.stock_requests_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status NOT IN ('pending', 'waiting') THEN
      RAISE EXCEPTION 'stock_requests.status: a request starts pending or waiting' USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    IF NEW.id <> OLD.id OR NEW.store_id <> OLD.store_id OR NEW.variant_id <> OLD.variant_id OR NEW.product_id <> OLD.product_id
      OR NEW.email <> OLD.email THEN
      RAISE EXCEPTION 'stock_requests.identity: a request stays itself' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status <> OLD.status AND NOT (
      (OLD.status = 'pending' AND NEW.status IN ('waiting', 'cancelled'))
      OR (OLD.status = 'waiting' AND NEW.status IN ('sent', 'cancelled'))
    ) THEN
      RAISE EXCEPTION 'stock_requests.status: % cannot become %', OLD.status, NEW.status USING ERRCODE = 'check_violation';
    END IF;
    NEW.updated_at := now();
  END IF;
  IF NEW.status = 'pending' AND (NEW.confirm_hash IS NULL OR NEW.confirm_until IS NULL) THEN
    RAISE EXCEPTION 'stock_requests.pending: a pending request needs its link' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status = 'sent' AND NEW.notified_at IS NULL THEN
    RAISE EXCEPTION 'stock_requests.sent: a sent request says when' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: storage_bytes_by_store(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.storage_bytes_by_store() RETURNS TABLE(store_id uuid, bytes bigint)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $_$
BEGIN
  IF to_regclass('storage.objects') IS NULL THEN
    RETURN QUERY
      SELECT m.store_id, coalesce(sum(m.size_bytes), 0)::bigint
        FROM commerce.media m
       GROUP BY m.store_id;
    RETURN;
  END IF;
  RETURN QUERY EXECUTE $sql$
    SELECT s.id, coalesce(sum((o.metadata ->> 'size')::bigint), 0)::bigint
      FROM storage.objects o
      LEFT JOIN commerce.stores s ON s.id::text = split_part(o.name, '/', 1)
     WHERE o.bucket_id IN ('product-media', 'page-videos', 'field-files', 'digital-files', 'documents', 'imports', 'exports')
       AND (s.id IS NOT NULL OR split_part(o.name, '/', 1) = 'platform')
     GROUP BY s.id
  $sql$;
END;
$_$;


--
-- Name: store_audience(text, text[]); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.store_audience(p_audience text, p_features text[]) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT CASE WHEN 'business' = ANY (p_features) AND commerce.feature_needs('business') <@ p_features THEN p_audience ELSE 'consumers' END
$$;


--
-- Name: store_billing_house(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.store_billing_house() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF (NEW.plan_id IS NOT NULL OR NEW.subscription_id IS NOT NULL OR NEW.trial_ends_at IS NOT NULL)
     AND EXISTS (SELECT 1 FROM commerce.stores s WHERE s.id = NEW.store_id AND s.house) THEN
    RAISE EXCEPTION 'store_billing.house: Kaizena Flow''s own store has no plan and no trial' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: store_day(uuid, timestamp with time zone); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.store_day(p_store uuid, p_at timestamp with time zone) RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT (p_at AT TIME ZONE coalesce((SELECT s.time_zone FROM commerce.stores s WHERE s.id = p_store), 'UTC'))::date
$$;


--
-- Name: store_domains_one_kind(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.store_domains_one_kind() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.market IS NOT NULL AND EXISTS (
    SELECT 1 FROM commerce.store_domains d WHERE d.store_id = NEW.store_id AND d.id <> NEW.id AND d.language IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'A store gives domains to its countries or to its languages, not both.' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.language IS NOT NULL AND EXISTS (
    SELECT 1 FROM commerce.store_domains d WHERE d.store_id = NEW.store_id AND d.id <> NEW.id AND d.market IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'A store gives domains to its countries or to its languages, not both.' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: store_event_order_paid(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.store_event_order_paid() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.copied_from IS NOT NULL OR NEW.status <> 'paid' THEN
    RETURN NULL;
  END IF;
  -- From either state complete_order_payment() accepts: waiting for payment, or cancelled for want of it (a hold that ran out before the
  -- shopper's session completed). The once key keeps a second payment from queuing it again.
  IF TG_OP = 'UPDATE' AND (OLD.status IS NULL OR OLD.status NOT IN ('pending_payment', 'authorized', 'cancelled')) THEN
    RETURN NULL;
  END IF;
  IF EXISTS (SELECT 1 FROM commerce.stores s WHERE s.id = NEW.store_id AND (s.is_template OR s.starter)) THEN
    RETURN NULL;
  END IF;
  PERFORM commerce.queue_store_event(NEW.store_id, 'order.paid', NEW.id);
  RETURN NULL;
END;
$$;


--
-- Name: store_event_return_requested(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.store_event_return_requested() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.status::text <> 'requested' THEN
    RETURN NULL;
  END IF;
  IF EXISTS (SELECT 1 FROM commerce.orders o WHERE o.store_id = NEW.store_id AND o.id = NEW.order_id AND o.copied_from IS NOT NULL) THEN
    RETURN NULL;
  END IF;
  PERFORM commerce.queue_store_event(NEW.store_id, 'return.requested', NEW.id);
  RETURN NULL;
END;
$$;


--
-- Name: store_is_active(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.store_is_active(p_store uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT COALESCE((SELECT s.status = 'active' AND NOT s.starter AND NOT s.sandbox FROM commerce.stores s WHERE s.id = p_store), false)
$$;


--
-- Name: store_locations_shipping_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.store_locations_shipping_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF (NEW.kind NOT IN ('shop', 'pickup') OR NEW.country <> OLD.country)
     AND EXISTS (SELECT 1 FROM commerce.pickup_options o WHERE o.store_id = OLD.store_id AND o.location_id = OLD.id) THEN
    RAISE EXCEPTION 'store_locations.pickup_option: customers collect at this place; switch its pickup off before making it an office or moving it to another country'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.country <> OLD.country
     AND EXISTS (SELECT 1 FROM commerce.local_delivery_areas a WHERE a.store_id = OLD.store_id AND a.location_id = OLD.id) THEN
    RAISE EXCEPTION 'store_locations.local_area: local delivery areas are measured from this place; remove them before moving it to another country'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.latitude IS NULL AND OLD.latitude IS NOT NULL
     AND EXISTS (SELECT 1 FROM commerce.local_delivery_areas a WHERE a.store_id = OLD.store_id AND a.location_id = OLD.id AND a.kind = 'radius' AND a.active) THEN
    RAISE EXCEPTION 'store_locations.radius_area: an active radius area is measured from this place''s position' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: store_member_left_apps(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.store_member_left_apps() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  -- A store being deleted takes its installations with it: nothing to end.
  IF NOT EXISTS (SELECT 1 FROM commerce.stores s WHERE s.id = OLD.store_id) THEN
    RETURN NULL;
  END IF;
  UPDATE commerce.oauth_tokens SET revoked_at = coalesce(revoked_at, now())
  WHERE grant_id IN (
    SELECT g.id FROM commerce.oauth_grants g
    WHERE g.account_id = OLD.account_id AND g.store_id = OLD.store_id AND g.resource = 'admin' AND g.revoked_at IS NULL
  );
  UPDATE commerce.assistant_approvals
     SET status = 'expired', decided_at = now(),
         result = jsonb_build_object('error', 'The connection that asked for it was ended, so it can no longer be approved.')
   WHERE status = 'pending' AND oauth_grant_id IN (
     SELECT g.id FROM commerce.oauth_grants g
     WHERE g.account_id = OLD.account_id AND g.store_id = OLD.store_id AND g.resource = 'admin' AND g.revoked_at IS NULL
   );
  UPDATE commerce.oauth_grants SET revoked_at = now()
  WHERE account_id = OLD.account_id AND store_id = OLD.store_id AND resource = 'admin' AND revoked_at IS NULL;
  RETURN NULL;
END;
$$;


--
-- Name: store_members_house(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.store_members_house() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.disabled_at IS NULL
     AND EXISTS (SELECT 1 FROM commerce.stores s WHERE s.id = NEW.store_id AND s.house)
     AND NOT EXISTS (
       SELECT 1 FROM commerce.accounts a
        WHERE a.id = NEW.account_id AND a.disabled_at IS NULL
          AND (a.platform_admin OR (a.platform_role IS NOT NULL AND NEW.role = 'admin'))
     ) THEN
    RAISE EXCEPTION 'store_members.house: only the platform''s team works in Kaizena Flow''s own store' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: store_members_sandbox(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.store_members_sandbox() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM commerce.stores s WHERE s.id = NEW.store_id AND s.sandbox)
     AND NEW.account_id IS DISTINCT FROM commerce.sandbox_account() THEN
    RAISE EXCEPTION 'store_members.sandbox: a sandbox has no member but the sandbox account' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: store_starters_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.store_starters_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF EXISTS (SELECT 1 FROM commerce.stores s WHERE s.made_from_starter = OLD.id AND s.starter_copy_of IS NULL) THEN
      RAISE EXCEPTION 'store_starters.used: stores were made from this store template; archive it instead' USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (SELECT 1 FROM commerce.access_requests r WHERE r.starter_id = OLD.id) THEN
      RAISE EXCEPTION 'store_starters.requested: an access request chose this store template; archive it instead' USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM commerce.stores s WHERE s.id = NEW.store_id AND s.starter AND s.starter_copy_of IS NULL)
     OR EXISTS (SELECT 1 FROM commerce.design_presets d WHERE d.workspace_store_id = NEW.store_id) THEN
    RAISE EXCEPTION 'store_starters.not_starter: only a store marked as a store template is described as one' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.published_store_id IS NOT NULL
     AND (TG_OP = 'INSERT' OR NEW.published_store_id IS DISTINCT FROM OLD.published_store_id)
     AND NOT EXISTS (SELECT 1 FROM commerce.stores s WHERE s.id = NEW.published_store_id AND s.starter AND s.starter_copy_of = NEW.id) THEN
    RAISE EXCEPTION 'store_starters.not_copy: a store template publishes only its own frozen copy' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NEW.store_id IS DISTINCT FROM OLD.store_id THEN
      RAISE EXCEPTION 'store_starters.store_fixed: a store template keeps its store' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.kind IS DISTINCT FROM OLD.kind THEN
      RAISE EXCEPTION 'store_starters.kind_fixed: a demo store stays a demo store, and starting content stays starting content' USING ERRCODE = 'check_violation';
    END IF;
    NEW.updated_at := now();
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: store_tax_profile_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.store_tax_profile_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_country char(2);
  v_prefix text;
  v_check record;
BEGIN
  -- The seller's number belongs to the country the store is in (Greece's prefix is EL).
  IF NEW.vat_number IS NOT NULL THEN
    SELECT s.country INTO v_country FROM commerce.stores s WHERE s.id = NEW.store_id;
    IF v_country IS NOT NULL THEN
      v_prefix := CASE WHEN v_country = 'GR' THEN 'EL' ELSE v_country END;
      IF left(NEW.vat_number, 2) <> v_prefix THEN
        RAISE EXCEPTION 'tax_profile_vat_prefix: the VAT number must be one of the store''s own country (%)', v_prefix
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
  END IF;

  -- IOSS applies to EU markets, each once.
  IF cardinality(NEW.ioss_markets) > 0 THEN
    IF EXISTS (SELECT 1 FROM unnest(NEW.ioss_markets) AS m WHERE NOT commerce.is_eu_country(m::char(2))) THEN
      RAISE EXCEPTION 'tax_profile_ioss_markets: IOSS markets are EU countries' USING ERRCODE = 'check_violation';
    END IF;
    IF (SELECT count(DISTINCT m) FROM unnest(NEW.ioss_markets) AS m) <> cardinality(NEW.ioss_markets) THEN
      RAISE EXCEPTION 'tax_profile_ioss_markets: a market is listed once' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  -- The Union scheme is registered in an EU member state.
  IF NEW.oss_scheme = 'union' AND NOT commerce.is_eu_country(NEW.oss_member_state) THEN
    RAISE EXCEPTION 'tax_profile_oss_member_state: the Union scheme is registered in an EU member state' USING ERRCODE = 'check_violation';
  END IF;

  -- A stored check is the seller's check of this very number, and its result is copied faithfully.
  IF NEW.vat_number_check_id IS NOT NULL THEN
    SELECT c.number, c.purpose, c.status INTO v_check
      FROM commerce.vat_checks c WHERE c.store_id = NEW.store_id AND c.id = NEW.vat_number_check_id;
    IF v_check.number IS DISTINCT FROM NEW.vat_number OR v_check.purpose IS DISTINCT FROM 'seller' THEN
      RAISE EXCEPTION 'tax_profile_check: the stored check is not the seller''s check of this number' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.vat_number_valid IS DISTINCT FROM (CASE v_check.status WHEN 'valid' THEN true WHEN 'invalid' THEN false END) THEN
      RAISE EXCEPTION 'tax_profile_check: the stored result is not the check''s result' USING ERRCODE = 'check_violation';
    END IF;
  ELSIF NEW.vat_number_valid IS NOT NULL OR NEW.vat_number_checked_at IS NOT NULL THEN
    RAISE EXCEPTION 'tax_profile_check: a result needs the check it comes from' USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: store_theme_installs_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.store_theme_installs_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.live THEN
      RAISE EXCEPTION 'store_theme_installs.live: the live theme is not removed; switch to another first' USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.store_id IS DISTINCT FROM OLD.store_id OR NEW.preset_id IS DISTINCT FROM OLD.preset_id
     OR NEW.installed_at IS DISTINCT FROM OLD.installed_at
     OR (NEW.installed_by IS DISTINCT FROM OLD.installed_by AND NEW.installed_by IS NOT NULL) THEN
    RAISE EXCEPTION 'store_theme_installs.fixed: an install keeps the theme it came from' USING ERRCODE = 'check_violation';
  END IF;
  -- The preset it was added with stays (its key, kept even while a version has no such preset).
  IF NEW.variation IS DISTINCT FROM OLD.variation THEN
    RAISE EXCEPTION 'store_theme_installs.variation: an install keeps the preset it was added with' USING ERRCODE = 'check_violation';
  END IF;
  -- An update (D245) moves the version, only ever to another version of the install's own theme.
  IF NEW.version_id IS DISTINCT FROM OLD.version_id AND (
       NEW.version_id IS NULL OR NEW.preset_id IS NULL
       OR NOT EXISTS (SELECT 1 FROM commerce.design_preset_versions v WHERE v.id = NEW.version_id AND v.preset_id = NEW.preset_id)
     ) THEN
    RAISE EXCEPTION 'store_theme_installs.version: an install moves only to another version of its own theme' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: stores_experiment_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.stores_experiment_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF OLD.header_id IS NOT NULL AND NEW.header_id IS DISTINCT FROM OLD.header_id
     AND EXISTS (SELECT 1 FROM commerce.experiments e WHERE e.store_id = OLD.id AND e.status = 'running' AND e.target_page_id = OLD.header_id) THEN
    RAISE EXCEPTION 'stores.experiment: the header is in a running test: stop the test before choosing another header' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.footer_id IS NOT NULL AND NEW.footer_id IS DISTINCT FROM OLD.footer_id
     AND EXISTS (SELECT 1 FROM commerce.experiments e WHERE e.store_id = OLD.id AND e.status = 'running' AND e.target_page_id = OLD.footer_id) THEN
    RAISE EXCEPTION 'stores.experiment: the footer is in a running test: stop the test before choosing another footer' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.front_page_id IS NOT NULL AND NEW.front_page_id IS DISTINCT FROM OLD.front_page_id
     AND EXISTS (SELECT 1 FROM commerce.experiments e WHERE e.store_id = OLD.id AND e.status = 'running' AND e.target_page_id = OLD.front_page_id) THEN
    RAISE EXCEPTION 'stores.experiment: the front page is in a running test: stop the test before choosing another front page' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.products_page_id IS NOT NULL AND NEW.products_page_id IS DISTINCT FROM OLD.products_page_id
     AND EXISTS (SELECT 1 FROM commerce.experiments e WHERE e.store_id = OLD.id AND e.status = 'running' AND e.target_page_id = OLD.products_page_id) THEN
    RAISE EXCEPTION 'stores.experiment: the All products page is in a running test: stop the test before choosing another page' USING ERRCODE = 'restrict_violation';
  END IF;
  -- A page in a running test is not put on the front page or the All products page: the test would then be of something else.
  IF NEW.front_page_id IS NOT NULL AND NEW.front_page_id IS DISTINCT FROM OLD.front_page_id
     AND EXISTS (SELECT 1 FROM commerce.experiments e WHERE e.store_id = OLD.id AND e.status = 'running' AND e.target_page_id = NEW.front_page_id) THEN
    RAISE EXCEPTION 'stores.experiment: the page is in a running test: stop the test before making it the front page' USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW.products_page_id IS NOT NULL AND NEW.products_page_id IS DISTINCT FROM OLD.products_page_id
     AND EXISTS (SELECT 1 FROM commerce.experiments e WHERE e.store_id = OLD.id AND e.status = 'running' AND e.target_page_id = NEW.products_page_id) THEN
    RAISE EXCEPTION 'stores.experiment: the page is in a running test: stop the test before making it the All products page' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: stores_features_after(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.stores_features_after() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.features IS NOT DISTINCT FROM OLD.features THEN
    RETURN NULL;
  END IF;
  IF commerce.store_audience(OLD.audience, OLD.features) <> 'consumers'
     AND commerce.store_audience(NEW.audience, NEW.features) = 'consumers' THEN
    UPDATE commerce.carts
       SET company_name = NULL, organisation_number = NULL, vat_number = NULL, vat_check_id = NULL
     WHERE store_id = NEW.id AND status = 'open'
       AND (company_name IS NOT NULL OR organisation_number IS NOT NULL OR vat_number IS NOT NULL OR vat_check_id IS NOT NULL);
  END IF;
  IF ('bonus' = ANY (commerce.features_effective(OLD.features))) IS DISTINCT FROM ('bonus' = ANY (commerce.features_effective(NEW.features))) THEN
    PERFORM commerce.bonus_pause_sync(NEW.id);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: stores_features_sync(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.stores_features_sync() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_on text[];
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- A store inserted with a module (tests, older code) has its features.
    IF 'bookings' = ANY (NEW.modules) AND NOT (NEW.features && array['appointments', 'bookings']) THEN
      NEW.features := NEW.features || array['appointments', 'bookings'];
    END IF;
    IF 'deliveries' = ANY (NEW.modules) AND NOT ('boxes' = ANY (NEW.features)) THEN
      NEW.features := NEW.features || array['boxes'];
    END IF;
  ELSIF NEW.features IS NOT DISTINCT FROM OLD.features THEN
    -- Only the modules were written: a module switched on or off moves its features.
    IF ('bookings' = ANY (NEW.modules)) IS DISTINCT FROM ('bookings' = ANY (OLD.modules)) THEN
      IF 'bookings' = ANY (NEW.modules) THEN
        NEW.features := NEW.features || array['appointments', 'bookings'];
      ELSE
        NEW.features := array_remove(array_remove(NEW.features, 'appointments'), 'bookings');
      END IF;
    END IF;
    IF ('deliveries' = ANY (NEW.modules)) IS DISTINCT FROM ('deliveries' = ANY (OLD.modules)) THEN
      IF 'deliveries' = ANY (NEW.modules) THEN
        NEW.features := NEW.features || array['boxes'];
      ELSE
        NEW.features := array_remove(NEW.features, 'boxes');
      END IF;
    END IF;
  END IF;

  NEW.features := (SELECT coalesce(array_agg(DISTINCT f ORDER BY f), '{}'::text[]) FROM unnest(NEW.features) f);
  v_on := commerce.features_effective(NEW.features);

  -- The modules follow what is on (the shop's switch included); `work` is not a feature and is left as it is.
  IF v_on && array['appointments', 'bookings'] THEN
    IF NOT ('bookings' = ANY (NEW.modules)) THEN NEW.modules := NEW.modules || array['bookings']; END IF;
  ELSE
    NEW.modules := array_remove(NEW.modules, 'bookings');
  END IF;
  IF 'boxes' = ANY (v_on) THEN
    IF NOT ('deliveries' = ANY (NEW.modules)) THEN NEW.modules := NEW.modules || array['deliveries']; END IF;
  ELSE
    NEW.modules := array_remove(NEW.modules, 'deliveries');
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: stores_first_blog(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.stores_first_blog() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  INSERT INTO commerce.blogs (store_id, handle, main) VALUES (NEW.id, 'blog', true) ON CONFLICT DO NOTHING;
  RETURN NULL;
END;
$$;


--
-- Name: stores_first_install(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.stores_first_install() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  INSERT INTO commerce.store_theme_installs (store_id, title, live, switched_at) VALUES (NEW.id, 'Custom', true, now());
  RETURN NULL;
END;
$$;


--
-- Name: stores_front_page_is_page(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.stores_front_page_is_page() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.front_page_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM commerce.pages p WHERE p.id = NEW.front_page_id AND p.type <> 'page'
  ) THEN
    RAISE EXCEPTION 'a front page must be a page, not an article';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: stores_house_public(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.stores_house_public() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.house AND NEW.private_mode AND NOT OLD.private_mode
     AND EXISTS (SELECT 1 FROM commerce.platform_settings p WHERE p.site_from_store) THEN
    RAISE EXCEPTION 'stores.house_public: Kaizena Flow''s own store serves the site and cannot be made private; switch the site back first'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: stores_house_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.stores_house_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' AND NEW.house AND COALESCE(current_setting('commerce.house_change', true), '') <> 'make' THEN
    RAISE EXCEPTION 'stores.house_fixed: only make_house_store() makes Kaizena Flow''s own store' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.house IS DISTINCT FROM NEW.house THEN
    RAISE EXCEPTION 'stores.house_fixed: Kaizena Flow''s own store stays its own, and no other store becomes it' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.house AND NEW.status <> 'active' THEN
    RAISE EXCEPTION 'stores.house_open: Kaizena Flow''s own store is never closed or suspended' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: stores_open_theme_purchases(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.stores_open_theme_purchases() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  UPDATE commerce.theme_purchases p
     SET status = 'due', due_at = now(), updated_at = now(),
         amount_minor = least(p.amount_minor, coalesce(
           (SELECT tp.amount_minor FROM commerce.theme_prices tp WHERE tp.preset_id = p.preset_id AND tp.currency = p.currency), p.amount_minor))
   WHERE p.store_id = NEW.id AND p.status = 'owed';
  RETURN NULL;
END;
$$;


--
-- Name: stores_sandbox_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.stores_sandbox_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_allowed boolean := COALESCE(current_setting('commerce.sandbox_change', true), '') = NEW.id::text;
BEGIN
  IF TG_OP = 'INSERT' AND NEW.sandbox THEN
    RAISE EXCEPTION 'stores.sandbox_fixed: only make_sandbox() makes a sandbox' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.sandbox IS DISTINCT FROM OLD.sandbox AND NOT v_allowed THEN
    RAISE EXCEPTION 'stores.sandbox_fixed: a store becomes or stops being a sandbox only through its own functions' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.sandbox THEN
    IF NOT NEW.private_mode THEN
      RAISE EXCEPTION 'stores.sandbox_private: a sandbox stays private' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.shopping_agents OR NEW.domain_buying THEN
      RAISE EXCEPTION 'stores.sandbox_closed_doors: a sandbox serves no shopping agents and buys no domain' USING ERRCODE = 'check_violation';
    END IF;
    IF TG_OP = 'UPDATE' AND NEW.slug IS DISTINCT FROM OLD.slug AND NOT v_allowed THEN
      RAISE EXCEPTION 'stores.sandbox_address: a sandbox keeps its address' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: stores_starter_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.stores_starter_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.starter AND NOT NEW.starter THEN
    RAISE EXCEPTION 'stores.starter_fixed: a store template stays a store template' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.starter AND (TG_OP = 'INSERT' OR NOT OLD.starter) THEN
    IF EXISTS (SELECT 1 FROM commerce.orders o WHERE o.store_id = NEW.id)
       OR EXISTS (SELECT 1 FROM commerce.customers c WHERE c.store_id = NEW.id) THEN
      RAISE EXCEPTION 'stores.starter_has_sales: a store that has orders or customers cannot become a store template'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: stores_status_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.stores_status_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;
  IF NOT (
    (OLD.status = 'active' AND NEW.status IN ('suspended', 'closed'))
    OR (OLD.status = 'suspended' AND NEW.status IN ('active', 'closed'))
    OR (OLD.status = 'closed' AND NEW.status = 'active')
  ) THEN
    RAISE EXCEPTION 'stores.status_step: a store cannot go from % to %', OLD.status, NEW.status USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.is_template THEN
    RAISE EXCEPTION 'stores.template_status: the template store stays active' USING ERRCODE = 'check_violation';
  END IF;
  NEW.status_changed_at := now();
  IF NEW.status = 'closed' THEN
    NEW.closed_at := now();
  ELSIF NEW.status = 'active' THEN
    NEW.closed_at := NULL;
    NEW.status_reason := NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: supplier_invoice_fixed(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.supplier_invoice_fixed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'supplier_invoice.fixed: a bill is never deleted' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.paid_entry_id IS NOT NULL
     OR (to_jsonb(NEW) - 'paid_entry_id' - 'paid_on') IS DISTINCT FROM (to_jsonb(OLD) - 'paid_entry_id' - 'paid_on') THEN
    RAISE EXCEPTION 'supplier_invoice.fixed: a bill changes only by its payment, once' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: support_actions_store(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.support_actions_store() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  SELECT c.store_id INTO NEW.store_id FROM commerce.support_conversations c WHERE c.id = NEW.conversation_id;
  RETURN NEW;
END;
$$;


--
-- Name: support_add_message(uuid, text, uuid, text, text, jsonb, uuid, jsonb); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.support_add_message(p_conversation uuid, p_author text, p_account uuid, p_body text, p_kind text DEFAULT NULL::text, p_data jsonb DEFAULT NULL::jsonb, p_action uuid DEFAULT NULL::uuid, p_tools jsonb DEFAULT NULL::jsonb) RETURNS TABLE(id uuid, seq integer)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  c commerce.support_conversations%ROWTYPE;
  v_seq integer;
  v_id uuid;
BEGIN
  SELECT * INTO c FROM commerce.support_conversations sc WHERE sc.id = p_conversation FOR UPDATE;
  IF NOT FOUND OR c.anonymised_at IS NOT NULL THEN
    RAISE EXCEPTION 'support_gone' USING ERRCODE = 'check_violation';
  END IF;
  IF p_author = 'ai' AND (c.handler <> 'ai' OR c.status <> 'open') THEN
    RETURN;
  END IF;
  IF c.status <> 'open' AND p_author NOT IN ('system', 'note') THEN
    RAISE EXCEPTION 'support_ended' USING ERRCODE = 'check_violation';
  END IF;
  IF p_author = 'agent' AND (c.handler <> 'human' OR c.assignee_id IS DISTINCT FROM p_account) THEN
    RAISE EXCEPTION 'support_not_yours' USING ERRCODE = 'check_violation';
  END IF;
  IF p_author = 'ai' AND commerce.support_mode(c.store_id) = 'people' THEN
    RAISE EXCEPTION 'support_no_ai' USING ERRCODE = 'check_violation';
  END IF;

  v_seq := c.message_seq + 1;
  PERFORM set_config('kaizen.support_writer', 'on', true);
  UPDATE commerce.support_conversations sc SET
    message_seq = v_seq,
    last_message_at = CASE WHEN p_author IN ('note', 'partner') THEN sc.last_message_at ELSE now() END,
    last_customer_at = CASE WHEN p_author = 'customer' THEN now() ELSE sc.last_customer_at END,
    first_agent_at = CASE WHEN p_author = 'agent' THEN coalesce(sc.first_agent_at, now()) ELSE sc.first_agent_at END
  WHERE sc.id = p_conversation;
  INSERT INTO commerce.support_messages AS m (conversation_id, store_id, seq, author, account_id, body, kind, data, action_id, tools)
  VALUES (p_conversation, c.store_id, v_seq, p_author, p_account, p_body, p_kind, p_data, p_action, p_tools)
  RETURNING m.id INTO v_id;
  PERFORM set_config('kaizen.support_writer', '', true);

  id := v_id;
  seq := v_seq;
  RETURN NEXT;
END;
$$;


--
-- Name: support_conversations_desk_mode(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.support_conversations_desk_mode() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.desk_mode := commerce.support_mode(NEW.store_id);
  ELSE
    NEW.desk_mode := OLD.desk_mode;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: support_conversations_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.support_conversations_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_mode text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_mode := commerce.support_mode(NEW.store_id);
    IF NEW.source = 'form' AND (NEW.store_id IS NULL OR v_mode = 'off') THEN
      RAISE EXCEPTION 'support_off' USING ERRCODE = 'check_violation',
        DETAIL = 'A form''s message reaches the inbox only of a store''s desk that is on.';
    END IF;
    IF NEW.status <> 'open' OR NEW.assignee_id IS NOT NULL
       OR NEW.handler <> (CASE WHEN v_mode = 'people' OR NEW.source = 'form' THEN 'queue' ELSE 'ai' END)
       OR NEW.message_seq <> 0 THEN
      RAISE EXCEPTION 'support_bad_event' USING ERRCODE = 'check_violation',
        DETAIL = 'A conversation starts open, with nobody, at its desk''s first handler.';
    END IF;
    IF NEW.handler = 'queue' THEN
      NEW.queued_at := coalesce(NEW.queued_at, now());
    END IF;
    RETURN NEW;
  END IF;
  IF (NEW.status, NEW.handler, NEW.assignee_id) IS DISTINCT FROM (OLD.status, OLD.handler, OLD.assignee_id)
     AND coalesce(current_setting('kaizen.support_transition', true), '') <> 'on' THEN
    RAISE EXCEPTION 'support_bad_event' USING ERRCODE = 'check_violation',
      DETAIL = 'A conversation''s state changes only through commerce.support_transition().';
  END IF;
  IF NEW.message_seq <> OLD.message_seq AND coalesce(current_setting('kaizen.support_writer', true), '') <> 'on' THEN
    RAISE EXCEPTION 'support_bad_event' USING ERRCODE = 'check_violation',
      DETAIL = 'Messages are numbered only by commerce.support_add_message().';
  END IF;
  IF NEW.source = 'form' AND NEW.handler = 'ai' THEN
    RAISE EXCEPTION 'support_no_ai' USING ERRCODE = 'check_violation',
      DETAIL = 'A form''s message is answered by people only.';
  END IF;
  IF NEW.source = 'form' AND NEW.summary_status = 'pending' THEN
    NEW.summary_status := 'skipped';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: support_messages_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.support_messages_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF coalesce(current_setting('kaizen.support_tone', true), '') = 'on'
       AND OLD.author = 'customer' AND OLD.tone IS NULL AND NEW.tone IS NOT NULL
       AND (to_jsonb(NEW) - 'tone' - 'tone_label') = (to_jsonb(OLD) - 'tone' - 'tone_label') THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'support_bad_event' USING ERRCODE = 'check_violation', DETAIL = 'A support message is never changed (only its tone, once).';
  END IF;
  IF coalesce(current_setting('kaizen.support_writer', true), '') <> 'on' THEN
    RAISE EXCEPTION 'support_bad_event' USING ERRCODE = 'check_violation',
      DETAIL = 'Support messages are written only by commerce.support_add_message().';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: support_mode(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.support_mode(p_store uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce(
    (SELECT CASE WHEN s.sensitive AND s.mode <> 'off' THEN 'people' ELSE s.mode END
     FROM commerce.support_settings s WHERE s.store_id IS NOT DISTINCT FROM p_store),
    'off');
$$;


--
-- Name: support_ping(text, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.support_ping(p_topic text, p_event text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
BEGIN
  IF to_regprocedure('realtime.send(jsonb,text,text,boolean)') IS NULL THEN
    RETURN;
  END IF;
  EXECUTE 'SELECT realtime.send($1, $2, $3, false)' USING jsonb_build_object('at', now()), p_event, p_topic;
EXCEPTION WHEN OTHERS THEN
  -- A ping is a hint: clients poll anyway. It never undoes what it was about.
  RETURN;
END;
$_$;


--
-- Name: support_ping_message(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.support_ping_message() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_conversation text;
  v_desk text;
BEGIN
  SELECT c.channel_key, s.channel_key INTO v_conversation, v_desk
  FROM commerce.support_conversations c
  LEFT JOIN commerce.support_settings s ON s.store_id IS NOT DISTINCT FROM c.store_id
  WHERE c.id = NEW.conversation_id;
  IF NEW.author NOT IN ('note', 'partner') THEN
    PERFORM commerce.support_ping('sc:' || v_conversation, 'm');
  END IF;
  IF v_desk IS NOT NULL THEN
    PERFORM commerce.support_ping('sd:' || v_desk, 'm');
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: support_ping_state(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.support_ping_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_desk text;
BEGIN
  SELECT s.channel_key INTO v_desk FROM commerce.support_settings s WHERE s.store_id IS NOT DISTINCT FROM NEW.store_id;
  PERFORM commerce.support_ping('sc:' || NEW.channel_key, 's');
  IF v_desk IS NOT NULL THEN
    PERFORM commerce.support_ping('sd:' || v_desk, 's');
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: support_record_tone(uuid, integer, integer, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.support_record_tone(p_conversation uuid, p_seq integer, p_score integer, p_label text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_done boolean;
BEGIN
  PERFORM set_config('kaizen.support_tone', 'on', true);
  UPDATE commerce.support_messages m SET tone = p_score, tone_label = p_label
  WHERE m.conversation_id = p_conversation AND m.seq = p_seq AND m.author = 'customer' AND m.tone IS NULL
    AND EXISTS (SELECT 1 FROM commerce.support_conversations c WHERE c.id = p_conversation AND c.anonymised_at IS NULL);
  v_done := FOUND;
  PERFORM set_config('kaizen.support_tone', '', true);
  RETURN v_done;
END;
$$;


--
-- Name: support_take_partner_turn(uuid, integer); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.support_take_partner_turn(p_conversation uuid, p_seq integer) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_taken boolean;
BEGIN
  UPDATE commerce.support_conversations sc SET partner_seq = p_seq
  WHERE sc.id = p_conversation AND sc.partner_seq < p_seq AND NOT sc.partner_paused
    AND sc.status = 'open' AND sc.anonymised_at IS NULL AND p_seq <= sc.message_seq
  RETURNING true INTO v_taken;
  RETURN coalesce(v_taken, false);
END;
$$;


--
-- Name: support_touch(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.support_touch() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: support_transition(uuid, text, text, uuid, uuid, text, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.support_transition(p_conversation uuid, p_event text, p_actor_kind text, p_actor uuid DEFAULT NULL::uuid, p_target uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_name text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  c commerce.support_conversations%ROWTYPE;
  v_mode text;
  v_open boolean;
  v_agent uuid := CASE WHEN p_actor_kind = 'agent' THEN p_actor END;
  v_assignee_acts boolean;
  v_status text;
  v_handler text;
  v_assignee uuid;
  v_lines text[];
  v_line text;
  v_name_data jsonb := CASE WHEN p_name IS NULL THEN NULL ELSE jsonb_build_object('name', p_name) END;
BEGIN
  IF p_actor_kind NOT IN ('customer', 'ai', 'system', 'agent') OR (p_actor_kind = 'agent' AND p_actor IS NULL) THEN
    RAISE EXCEPTION 'support_bad_event' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO c FROM commerce.support_conversations sc WHERE sc.id = p_conversation FOR UPDATE;
  IF NOT FOUND OR c.anonymised_at IS NOT NULL THEN
    RAISE EXCEPTION 'support_gone' USING ERRCODE = 'check_violation';
  END IF;
  v_mode := commerce.support_mode(c.store_id);
  v_open := c.status = 'open';
  v_assignee_acts := v_agent IS NOT NULL AND c.handler = 'human' AND c.assignee_id = v_agent;

  CASE p_event
  WHEN 'handoff' THEN
    IF NOT v_open THEN RAISE EXCEPTION 'support_ended' USING ERRCODE = 'check_violation'; END IF;
    IF v_mode = 'off' THEN RAISE EXCEPTION 'support_off' USING ERRCODE = 'check_violation'; END IF;
    -- On a desk that works as people only (people, or a store that handles sensitive information, PSI AST-08), a conversation the AI
    -- held before the desk changed is still handed to a person; only a desk with the AI first starts new ones with the AI.
    IF c.handler <> 'ai' OR p_actor_kind = 'agent' THEN RAISE EXCEPTION 'support_bad_event' USING ERRCODE = 'check_violation'; END IF;
    v_status := 'open'; v_handler := 'queue'; v_assignee := NULL; v_lines := ARRAY['queued'];
  WHEN 'claim' THEN
    IF NOT v_open THEN RAISE EXCEPTION 'support_ended' USING ERRCODE = 'check_violation'; END IF;
    IF v_mode = 'off' THEN RAISE EXCEPTION 'support_off' USING ERRCODE = 'check_violation'; END IF;
    IF v_agent IS NULL THEN RAISE EXCEPTION 'support_bad_event' USING ERRCODE = 'check_violation'; END IF;
    IF c.handler = 'human' THEN
      IF c.assignee_id = v_agent THEN RAISE EXCEPTION 'support_bad_event' USING ERRCODE = 'check_violation'; END IF;
      RAISE EXCEPTION 'support_taken' USING ERRCODE = 'check_violation';
    END IF;
    v_status := 'open'; v_handler := 'human'; v_assignee := v_agent; v_lines := ARRAY['joined'];
  WHEN 'transfer' THEN
    IF NOT v_open THEN RAISE EXCEPTION 'support_ended' USING ERRCODE = 'check_violation'; END IF;
    IF v_mode = 'off' THEN RAISE EXCEPTION 'support_off' USING ERRCODE = 'check_violation'; END IF;
    IF NOT v_assignee_acts THEN
      IF c.handler = 'human' THEN RAISE EXCEPTION 'support_not_yours' USING ERRCODE = 'check_violation'; END IF;
      RAISE EXCEPTION 'support_bad_event' USING ERRCODE = 'check_violation';
    END IF;
    IF p_target = v_agent THEN RAISE EXCEPTION 'support_bad_event' USING ERRCODE = 'check_violation'; END IF;
    IF p_target IS NULL THEN
      v_status := 'open'; v_handler := 'queue'; v_assignee := NULL; v_lines := ARRAY['queued'];
    ELSE
      v_status := 'open'; v_handler := 'human'; v_assignee := p_target; v_lines := ARRAY['joined'];
    END IF;
  WHEN 'hand_back' THEN
    IF NOT v_open THEN RAISE EXCEPTION 'support_ended' USING ERRCODE = 'check_violation'; END IF;
    IF v_mode = 'off' THEN RAISE EXCEPTION 'support_off' USING ERRCODE = 'check_violation'; END IF;
    IF v_mode <> 'ai_first' THEN RAISE EXCEPTION 'support_no_ai' USING ERRCODE = 'check_violation'; END IF;
    IF c.handler = 'queue' AND p_actor_kind = 'customer' THEN
      v_lines := ARRAY['assistant_back'];
    ELSIF c.handler = 'human' AND v_assignee_acts THEN
      v_lines := ARRAY['left', 'assistant_back'];
    ELSIF c.handler = 'human' AND v_agent IS NOT NULL THEN
      RAISE EXCEPTION 'support_not_yours' USING ERRCODE = 'check_violation';
    ELSE
      RAISE EXCEPTION 'support_bad_event' USING ERRCODE = 'check_violation';
    END IF;
    v_status := 'open'; v_handler := 'ai'; v_assignee := NULL;
  WHEN 'end' THEN
    IF NOT v_open THEN RAISE EXCEPTION 'support_ended' USING ERRCODE = 'check_violation'; END IF;
    IF NOT (p_actor_kind IN ('customer', 'system') OR v_assignee_acts) THEN
      IF v_agent IS NOT NULL AND c.handler = 'human' THEN RAISE EXCEPTION 'support_not_yours' USING ERRCODE = 'check_violation'; END IF;
      RAISE EXCEPTION 'support_bad_event' USING ERRCODE = 'check_violation';
    END IF;
    v_status := 'ended'; v_handler := c.handler; v_assignee := NULL; v_lines := ARRAY['ended'];
  WHEN 'reopen' THEN
    IF v_open THEN RAISE EXCEPTION 'support_bad_event' USING ERRCODE = 'check_violation'; END IF;
    IF p_actor_kind = 'customer' THEN
      v_status := 'open'; v_handler := CASE WHEN v_mode = 'people' THEN 'queue' ELSE 'ai' END; v_assignee := NULL;
      v_lines := ARRAY['reopened'];
    ELSIF v_agent IS NOT NULL THEN
      IF v_mode = 'off' THEN RAISE EXCEPTION 'support_off' USING ERRCODE = 'check_violation'; END IF;
      v_status := 'open'; v_handler := 'human'; v_assignee := v_agent; v_lines := ARRAY['reopened', 'joined'];
    ELSE
      RAISE EXCEPTION 'support_bad_event' USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    RAISE EXCEPTION 'support_bad_event' USING ERRCODE = 'check_violation';
  END CASE;

  PERFORM set_config('kaizen.support_transition', 'on', true);
  UPDATE commerce.support_conversations sc SET
    status = v_status,
    handler = v_handler,
    assignee_id = v_assignee,
    handoff_reason = CASE WHEN p_event = 'handoff' THEN coalesce(p_reason, p_actor_kind) ELSE sc.handoff_reason END,
    queued_at = CASE WHEN v_handler = 'queue' AND v_status = 'open' AND sc.handler <> 'queue' THEN now() ELSE sc.queued_at END,
    claimed_at = CASE WHEN v_handler = 'human' AND v_assignee IS DISTINCT FROM sc.assignee_id THEN now() ELSE sc.claimed_at END,
    waiting_alert_at = CASE WHEN v_handler = 'queue' THEN sc.waiting_alert_at ELSE NULL END,
    ended_at = CASE WHEN v_status = 'ended' THEN now() WHEN p_event = 'reopen' THEN NULL ELSE sc.ended_at END,
    ended_by = CASE
      WHEN v_status = 'ended' THEN CASE WHEN p_actor_kind <> 'system' THEN p_actor_kind WHEN p_reason = 'timeout' THEN 'timeout' ELSE 'system' END
      WHEN p_event = 'reopen' THEN NULL
      ELSE sc.ended_by END,
    summary_status = CASE
      WHEN v_status = 'ended' THEN CASE WHEN v_mode <> 'off' AND coalesce(
        (SELECT s.summaries_on FROM commerce.support_settings s WHERE s.store_id IS NOT DISTINCT FROM sc.store_id), false)
        THEN 'pending' ELSE 'skipped' END
      WHEN p_event = 'reopen' THEN 'none'
      ELSE sc.summary_status END,
    summary_tries = CASE WHEN p_event = 'reopen' THEN 0 ELSE sc.summary_tries END
  WHERE sc.id = p_conversation;
  PERFORM set_config('kaizen.support_transition', '', true);

  FOREACH v_line IN ARRAY v_lines LOOP
    PERFORM commerce.support_add_message(p_conversation, 'system', p_actor, '', v_line,
      CASE WHEN v_line IN ('joined', 'left') THEN v_name_data END);
  END LOOP;
  RETURN v_handler;
END;
$$;


--
-- Name: sync_standard_vat_rates(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.sync_standard_vat_rates() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_changed integer;
BEGIN
  WITH today AS (
    SELECT c.code,
           (SELECT r.rate FROM commerce.vat_rates r
             WHERE r.country_code = c.code AND r.category = 'standard'
               AND r.valid_from <= (now() AT TIME ZONE coalesce(c.time_zone, 'UTC'))::date
               AND (r.valid_to IS NULL OR r.valid_to > (now() AT TIME ZONE coalesce(c.time_zone, 'UTC'))::date)) AS rate
      FROM commerce.countries c
  )
  UPDATE commerce.countries c SET standard_vat_rate = t.rate
    FROM today t
   WHERE t.code = c.code AND t.rate IS NOT NULL AND c.standard_vat_rate IS DISTINCT FROM t.rate;
  GET DIAGNOSTICS v_changed = ROW_COUNT;
  RETURN v_changed;
END;
$$;


--
-- Name: tax_document_groups(uuid, date, date); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.tax_document_groups(p_store uuid, p_from date, p_to date) RETURNS TABLE(doc_kind text, tax_date date, original_tax_date date, market_code text, market_in_eu boolean, currency text, main_currency text, fx_state text, fx_rate numeric, vat_kind text, buyer_type text, has_physical boolean, has_download boolean, has_service boolean, dispatch_country text, dispatch_source text, seller_country text, seller_oss_member_state text, seller_source text, rate numeric, basis text, standard_rate numeric, documents bigint, orders bigint, currency_orders bigint, kind_documents bigint, net_minor bigint, vat_minor bigint, gross_minor bigint, net_main_minor bigint, vat_main_minor bigint, gross_main_minor bigint)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
#variable_conflict use_column
BEGIN
  RETURN QUERY
  -- MATERIALIZED: the planner would otherwise fold this one-row query into every place `main.code` is read and call the function once per
  -- document and place (it took a second for five thousand documents).
  WITH main AS MATERIALIZED (
    SELECT commerce.main_currency(p_store) AS code
  ), prof AS MATERIALIZED (
    SELECT coalesce(nullif(btrim(p.dispatch_country), ''), s.country) AS dispatch,
           s.country::text AS country, p.oss_member_state::text AS oss_msi
      FROM commerce.stores s
      LEFT JOIN commerce.store_tax_profile p ON p.store_id = s.id
     WHERE s.id = p_store
  ), docs AS (
    SELECT 'invoice'::text AS doc_kind, i.supply_date AS tax_date, NULL::date AS original_tax_date, i.id AS doc_id, i.order_id,
           i.currency::text AS currency, i.vat_kind, i.snapshot AS snap, i.snapshot AS inv_snap
      FROM commerce.invoices i
     WHERE i.store_id = p_store AND i.supply_date >= p_from AND i.supply_date < p_to
    UNION ALL
    SELECT 'credit_note'::text, c.issued_on, i.supply_date, c.id, i.order_id,
           c.currency::text, i.vat_kind, c.snapshot, i.snapshot
      FROM commerce.credit_notes c
      JOIN commerce.invoices i ON i.store_id = c.store_id AND i.id = c.invoice_id
     WHERE c.store_id = p_store AND c.issued_on >= p_from AND c.issued_on < p_to
  ), parts AS (
    -- A snapshot is compressed in the table, and every `->` on it decompresses it again: each is opened once here, for the four
    -- parts the report needs (jsonb_to_record reads the object once), and everything below reads those small values.
    SELECT d.doc_kind, d.tax_date, d.original_tax_date, d.doc_id, d.order_id, d.currency, d.vat_kind,
           s.buckets, s."vatMain" AS vat_main, v.buyer, v.lines
      FROM docs d
     CROSS JOIN LATERAL jsonb_to_record(d.snap) AS s(buckets jsonb, "vatMain" jsonb)
     CROSS JOIN LATERAL jsonb_to_record(d.inv_snap) AS v(buyer jsonb, lines jsonb)
  ), per_currency AS (
    SELECT d.currency, count(DISTINCT d.order_id) AS n
      FROM parts d WHERE d.doc_kind = 'invoice' GROUP BY d.currency
  ), facts AS (
    SELECT d.*, o.market_code::text AS market_code, coalesce(co.in_eu, false) AS market_in_eu,
           main.code AS main_currency,
           CASE
             WHEN d.currency = main.code THEN 'same'
             WHEN jsonb_typeof(d.vat_main -> 'fxRate') = 'number' AND d.vat_main ->> 'currency' = main.code THEN 'stored'
             ELSE 'missing'
           END AS fx_state,
           CASE
             WHEN d.currency <> main.code AND jsonb_typeof(d.vat_main -> 'fxRate') = 'number' AND d.vat_main ->> 'currency' = main.code
               THEN (d.vat_main ->> 'fxRate')::numeric
           END AS fx_rate,
           CASE WHEN d.buyer ->> 'type' = 'business' THEN 'business' ELSE 'consumer' END AS buyer_type,
           nullif(btrim(o.vat_treatment ->> 'dispatchCountry'), '') AS frozen_dispatch,
           -- The seller as the order froze it: both keys present (a JSON null is a fact, an absent key is an order from before D161).
           (o.vat_treatment -> 'sellerCountry' IS NOT NULL AND o.vat_treatment -> 'ossMemberState' IS NOT NULL) AS seller_frozen,
           nullif(btrim(o.vat_treatment ->> 'sellerCountry'), '') AS frozen_seller_country,
           nullif(btrim(o.vat_treatment ->> 'ossMemberState'), '') AS frozen_msi
      FROM parts d
      JOIN commerce.orders o ON o.store_id = p_store AND o.id = d.order_id
      LEFT JOIN commerce.countries co ON co.code = o.market_code
      CROSS JOIN main
  ), lined AS (
    SELECT f.doc_kind, f.tax_date, f.original_tax_date, f.doc_id, f.order_id, f.currency, f.vat_kind, f.buckets, f.market_code, f.market_in_eu,
           f.main_currency, f.fx_state, f.fx_rate, f.buyer_type,
           k.has_physical, k.has_download, k.has_service,
           CASE WHEN f.seller_frozen THEN f.frozen_seller_country ELSE prof.country END AS seller_country,
           CASE WHEN f.seller_frozen THEN f.frozen_msi ELSE prof.oss_msi END AS seller_oss_member_state,
           CASE WHEN f.seller_frozen THEN 'order' ELSE 'profile' END AS seller_source,
           coalesce(f.frozen_dispatch, prof.dispatch) AS dispatch_country,
           CASE
             WHEN f.frozen_dispatch IS NOT NULL THEN 'order'
             WHEN prof.dispatch IS NOT NULL THEN 'profile'
             ELSE 'unknown'
           END AS dispatch_source
      FROM facts f
      LEFT JOIN prof ON true
     CROSS JOIN LATERAL (
       SELECT coalesce(bool_or(l ->> 'kind' IN ('goods', 'gift')), false) AS has_physical,
              coalesce(bool_or(l ->> 'kind' = 'download'), false) AS has_download,
              coalesce(bool_or(l ->> 'kind' IN ('service', 'booking')), false) AS has_service
         FROM jsonb_array_elements(f.lines) AS l
     ) k
  ), per_kind AS (
    SELECT l.doc_kind, l.currency, l.fx_state, count(DISTINCT l.doc_id) AS n
      FROM lined l GROUP BY l.doc_kind, l.currency, l.fx_state
  ), bucketed AS (
    SELECT l.*, (b ->> 'rate')::numeric AS rate, b ->> 'basis' AS basis,
           (b ->> 'netMinor')::bigint AS b_net, (b ->> 'vatMinor')::bigint AS b_vat, (b ->> 'grossMinor')::bigint AS b_gross
      FROM lined l
     CROSS JOIN LATERAL jsonb_array_elements(l.buckets) AS b
  ), converted AS (
    SELECT x.*,
           CASE x.fx_state WHEN 'same' THEN x.b_net WHEN 'stored' THEN commerce.convert_with(x.b_net, x.fx_rate) END AS m_net,
           CASE x.fx_state WHEN 'same' THEN x.b_vat WHEN 'stored' THEN commerce.convert_with(x.b_vat, x.fx_rate) END AS m_vat,
           CASE x.fx_state WHEN 'same' THEN x.b_gross WHEN 'stored' THEN commerce.convert_with(x.b_gross, x.fx_rate) END AS m_gross
      FROM bucketed x
  )
  SELECT x.doc_kind, x.tax_date, x.original_tax_date, x.market_code, x.market_in_eu, x.currency, x.main_currency, x.fx_state, x.fx_rate,
         x.vat_kind, x.buyer_type, x.has_physical, x.has_download, x.has_service, x.dispatch_country, x.dispatch_source,
         x.seller_country, x.seller_oss_member_state, x.seller_source, x.rate, x.basis,
         commerce.vat_rate(x.market_code::char(2), 'standard', (x.tax_date::timestamp + interval '12 hours') AT TIME ZONE 'UTC') AS standard_rate,
         count(DISTINCT x.doc_id)::bigint AS documents,
         CASE WHEN x.doc_kind = 'invoice' THEN count(DISTINCT x.order_id)::bigint ELSE 0::bigint END AS orders,
         coalesce(max(pc.n), 0)::bigint AS currency_orders,
         coalesce(max(pk.n), 0)::bigint AS kind_documents,
         coalesce(sum(x.b_net), 0)::bigint AS net_minor,
         coalesce(sum(x.b_vat), 0)::bigint AS vat_minor,
         coalesce(sum(x.b_gross), 0)::bigint AS gross_minor,
         sum(x.m_net)::bigint AS net_main_minor,
         sum(x.m_vat)::bigint AS vat_main_minor,
         sum(x.m_gross)::bigint AS gross_main_minor
    FROM converted x
    LEFT JOIN per_currency pc ON pc.currency = x.currency
    LEFT JOIN per_kind pk ON pk.doc_kind = x.doc_kind AND pk.currency = x.currency AND pk.fx_state = x.fx_state
   GROUP BY x.doc_kind, x.tax_date, x.original_tax_date, x.market_code, x.market_in_eu, x.currency, x.main_currency, x.fx_state, x.fx_rate,
            x.vat_kind, x.buyer_type, x.has_physical, x.has_download, x.has_service, x.dispatch_country, x.dispatch_source,
            x.seller_country, x.seller_oss_member_state, x.seller_source, x.rate, x.basis
   ORDER BY x.tax_date, x.doc_kind, x.market_code, x.currency, x.rate, x.basis;
END;
$$;


--
-- Name: tax_rate_overrides_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.tax_rate_overrides_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.rate_date > current_date THEN
    RAISE EXCEPTION 'tax_rate_override.future: a rate is entered for a day that has passed, not for %', NEW.rate_date
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: terms_leave_redirect(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.terms_leave_redirect() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_source text;
BEGIN
  IF NEW.content_type = 'product' AND NEW.store_id IS NOT NULL AND NEW.slug IS DISTINCT FROM OLD.slug THEN
    v_source := '/' || NEW.kind || '/' || OLD.slug;
    DELETE FROM commerce.redirects r WHERE r.store_id = NEW.store_id AND r.source = v_source AND r.kind <> 'manual';
    INSERT INTO commerce.redirects (store_id, kind, source, term_id, origin)
    VALUES (NEW.store_id, NEW.kind, v_source, NEW.id, 'system')
    ON CONFLICT ON CONSTRAINT redirects_store_source_key DO NOTHING;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: terms_parent_valid(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.terms_parent_valid() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  ancestor uuid := NEW.parent_id;
  depth integer := 0;
BEGIN
  IF NEW.parent_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM commerce.terms p
    WHERE p.id = NEW.parent_id
      AND p.kind = 'category'
      AND p.content_type = NEW.content_type
      AND p.store_id IS NOT DISTINCT FROM NEW.store_id
  ) THEN
    RAISE EXCEPTION 'a category''s parent is a category of the same kind of content' USING ERRCODE = 'check_violation';
  END IF;
  WHILE ancestor IS NOT NULL LOOP
    IF ancestor = NEW.id OR depth > 50 THEN
      RAISE EXCEPTION 'a category cannot be inside itself' USING ERRCODE = 'check_violation';
    END IF;
    SELECT t.parent_id INTO ancestor FROM commerce.terms t WHERE t.id = ancestor;
    depth := depth + 1;
  END LOOP;
  RETURN NEW;
END;
$$;


--
-- Name: terms_rules_without_members(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.terms_rules_without_members() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.rules IS NOT NULL AND EXISTS (SELECT 1 FROM commerce.product_terms pt WHERE pt.term_id = NEW.id) THEN
    RAISE EXCEPTION 'Take the products out of this category before it is filled by rules' USING ERRCODE = 'check_violation', HINT = 'terms.rules_members';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: terms_taken_address(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.terms_taken_address() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.content_type = 'product' AND NEW.store_id IS NOT NULL THEN
    DELETE FROM commerce.redirects r WHERE r.store_id = NEW.store_id AND r.source = '/' || NEW.kind || '/' || NEW.slug AND r.kind <> 'manual';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: theme_install_updates_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.theme_install_updates_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.store_id IS DISTINCT FROM OLD.store_id OR NEW.install_id IS DISTINCT FROM OLD.install_id
     OR NEW.before IS DISTINCT FROM OLD.before OR NEW.after IS DISTINCT FROM OLD.after OR NEW.kept IS DISTINCT FROM OLD.kept
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR (NEW.from_version_id IS DISTINCT FROM OLD.from_version_id AND NEW.from_version_id IS NOT NULL)
     OR (NEW.to_version_id IS DISTINCT FROM OLD.to_version_id AND NEW.to_version_id IS NOT NULL)
     OR (NEW.updated_by IS DISTINCT FROM OLD.updated_by AND NEW.updated_by IS NOT NULL) THEN
    RAISE EXCEPTION 'theme_install_updates.fixed: an update of a theme keeps what it recorded' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.undone_at IS NOT NULL AND NEW.undone_at IS DISTINCT FROM OLD.undone_at THEN
    RAISE EXCEPTION 'theme_install_updates.undone: this update was undone already' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: theme_installs_charge(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.theme_installs_charge() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_store record;
  v_price record;
  v_charge text := nullif(current_setting('kaizen.theme_charge', true), '');
  v_actor uuid := nullif(current_setting('kaizen.theme_actor', true), '')::uuid;
BEGIN
  IF NOT NEW.live OR (TG_OP = 'UPDATE' AND OLD.live) THEN
    RETURN NULL;
  END IF;
  -- Before the store opens only the theme live when it opens is owed.
  UPDATE commerce.theme_purchases p SET status = 'cancelled', ended_at = now(), updated_at = now()
   WHERE p.store_id = NEW.store_id AND p.status = 'owed' AND p.preset_id IS DISTINCT FROM NEW.preset_id;
  IF NEW.preset_id IS NULL THEN
    RETURN NULL;
  END IF;
  SELECT s.status, s.starter, s.is_template, s.sandbox, s.setup_completed_at INTO v_store FROM commerce.stores s WHERE s.id = NEW.store_id;
  -- A sandbox (D457) owes nothing: it is a try, purged when it ends; keeping it owes its live theme then (`adopt_sandbox()`).
  IF v_store.starter OR v_store.is_template OR v_store.sandbox OR v_store.status <> 'active' THEN
    RETURN NULL;
  END IF;
  IF EXISTS (
    SELECT 1 FROM commerce.theme_purchases p
     WHERE p.store_id = NEW.store_id AND p.preset_id = NEW.preset_id AND p.status IN ('owed', 'due', 'invoiced', 'paid', 'granted')
  ) THEN
    RETURN NULL;
  END IF;
  SELECT * INTO v_price FROM commerce.theme_price_for(NEW.store_id, NEW.preset_id);
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  IF v_charge = 'grant' THEN
    INSERT INTO commerce.theme_purchases (store_id, preset_id, status, currency, amount_minor, chosen_by)
    VALUES (NEW.store_id, NEW.preset_id, 'granted', v_price.currency, 0, coalesce(v_actor, NEW.installed_by));
    RETURN NULL;
  END IF;
  IF v_store.setup_completed_at IS NULL THEN
    INSERT INTO commerce.theme_purchases (store_id, preset_id, status, currency, amount_minor, chosen_by)
    VALUES (NEW.store_id, NEW.preset_id, 'owed', v_price.currency, v_price.amount_minor, coalesce(v_actor, NEW.installed_by));
    RETURN NULL;
  END IF;
  IF v_charge IS DISTINCT FROM v_price.currency || ':' || v_price.amount_minor THEN
    RAISE EXCEPTION 'theme_purchases.confirm: this theme costs % % and the price was not agreed to', v_price.currency, v_price.amount_minor
      USING ERRCODE = 'check_violation';
  END IF;
  INSERT INTO commerce.theme_purchases (store_id, preset_id, status, currency, amount_minor, chosen_by, due_at)
  VALUES (NEW.store_id, NEW.preset_id, 'due', v_price.currency, v_price.amount_minor, coalesce(v_actor, NEW.installed_by), now());
  RETURN NULL;
END;
$$;


--
-- Name: theme_price_for(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.theme_price_for(p_store uuid, p_preset uuid) RETURNS TABLE(currency text, amount_minor bigint)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT tp.currency::text, tp.amount_minor
    FROM commerce.theme_prices tp
   WHERE tp.preset_id = p_preset
   ORDER BY
     tp.currency = (SELECT pp.currency FROM commerce.store_billing b JOIN commerce.plan_prices pp ON pp.id = b.price_id WHERE b.store_id = p_store) DESC NULLS LAST,
     tp.currency = (SELECT m.currency FROM commerce.markets m WHERE m.store_id = p_store AND m.code = commerce.home_market(p_store) LIMIT 1) DESC NULLS LAST,
     tp.currency
   LIMIT 1
$$;


--
-- Name: theme_prices_author_free(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.theme_prices_author_free() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM commerce.design_presets p WHERE p.id = NEW.preset_id AND p.author_id IS NOT NULL) THEN
    RAISE EXCEPTION 'theme_prices.author_free: a theme from outside is free' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: theme_purchases_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.theme_purchases_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'theme_purchases.kept: a theme purchase is never deleted' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.store_id IS DISTINCT FROM OLD.store_id OR NEW.preset_id IS DISTINCT FROM OLD.preset_id
     OR NEW.currency IS DISTINCT FROM OLD.currency OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR (NEW.chosen_by IS DISTINCT FROM OLD.chosen_by AND NEW.chosen_by IS NOT NULL) THEN
    RAISE EXCEPTION 'theme_purchases.fixed: a theme purchase keeps its store, theme and currency' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
       (OLD.status = 'owed' AND NEW.status IN ('due', 'cancelled'))
    OR (OLD.status = 'due' AND NEW.status IN ('invoiced', 'cancelled'))
    OR (OLD.status = 'invoiced' AND NEW.status IN ('paid', 'void'))
  ) THEN
    RAISE EXCEPTION 'theme_purchases.forward: a theme purchase cannot go from % to %', OLD.status, NEW.status USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.amount_minor > OLD.amount_minor OR (NEW.amount_minor <> OLD.amount_minor AND NOT (OLD.status = 'owed' AND NEW.status = 'due')) THEN
    RAISE EXCEPTION 'theme_purchases.amount: what a theme costs a store is lowered only when the store opens' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.stripe_invoice_id IS NOT NULL AND NEW.stripe_invoice_id IS DISTINCT FROM OLD.stripe_invoice_id THEN
    RAISE EXCEPTION 'theme_purchases.invoice: a theme purchase keeps its invoice' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: theme_schedules_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.theme_schedules_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.install_id IS NULL OR NOT EXISTS (
      SELECT 1 FROM commerce.store_theme_installs i WHERE i.id = NEW.install_id AND i.store_id = NEW.store_id
    ) THEN
      RAISE EXCEPTION 'theme_schedules.install: a store schedules one of its own installed themes' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status <> 'waiting' OR NEW.before_install_id IS NOT NULL OR NEW.revert_status IS DISTINCT FROM (CASE WHEN NEW.revert_at IS NULL THEN NULL ELSE 'waiting' END) THEN
      RAISE EXCEPTION 'theme_schedules.new: a plan starts waiting' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.store_id <> OLD.store_id OR NEW.created_at <> OLD.created_at
     OR (NEW.install_id IS DISTINCT FROM OLD.install_id AND NEW.install_id IS NOT NULL) THEN
    RAISE EXCEPTION 'theme_schedules.fixed: a plan stays its store''s and its theme''s' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.status <> 'waiting' AND (NEW.status <> OLD.status OR NEW.live_at <> OLD.live_at OR NEW.revert_at IS DISTINCT FROM OLD.revert_at) THEN
    RAISE EXCEPTION 'theme_schedules.settled: a plan that ran or was cancelled is kept as it ended' USING ERRCODE = 'check_violation';
  END IF;
  -- The theme that was live is written once, when the plan runs, and only one of the store's; afterwards it can only be let go of.
  IF NEW.before_install_id IS DISTINCT FROM OLD.before_install_id AND NEW.before_install_id IS NOT NULL AND (
    OLD.status <> 'waiting' OR NOT EXISTS (
      SELECT 1 FROM commerce.store_theme_installs i WHERE i.id = NEW.before_install_id AND i.store_id = NEW.store_id
    )
  ) THEN
    RAISE EXCEPTION 'theme_schedules.before: the theme that was live is the store''s own, written when the plan runs' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.revert_status IN ('done', 'failed', 'cancelled') AND NEW.revert_status IS DISTINCT FROM OLD.revert_status THEN
    RAISE EXCEPTION 'theme_schedules.revert_settled: a way back that ran or was cancelled is kept as it ended' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.revert_status IN ('done', 'failed') AND OLD.revert_status = 'waiting' AND NEW.status <> 'done' THEN
    RAISE EXCEPTION 'theme_schedules.revert_order: a way back runs only after its plan' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status IN ('failed', 'cancelled') AND NEW.revert_status = 'waiting' THEN
    RAISE EXCEPTION 'theme_schedules.revert_orphan: a plan that did not happen has no way back waiting' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: theme_submissions_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.theme_submissions_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.content_starter_id IS NOT NULL THEN
      RAISE EXCEPTION 'theme_submissions.content: its pages are placed by its review' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status <> 'waiting' OR NEW.decided_by IS NOT NULL OR NEW.decided_at IS NOT NULL OR NEW.reason IS NOT NULL THEN
      RAISE EXCEPTION 'theme_submissions.new: a submission starts waiting' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.kind = 'theme' AND NEW.preset_id IS NOT NULL THEN
      RAISE EXCEPTION 'theme_submissions.new_theme: a new theme is made by its review' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.kind = 'update' AND NOT EXISTS (
      SELECT 1 FROM commerce.design_presets p WHERE p.id = NEW.preset_id AND p.author_id = NEW.account_id
    ) THEN
      RAISE EXCEPTION 'theme_submissions.author: only a theme''s author submits an update of it' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.account_id <> OLD.account_id OR NEW.store_id <> OLD.store_id OR NEW.kind <> OLD.kind OR NEW.snapshot <> OLD.snapshot
     OR NEW.title <> OLD.title OR NEW.summary <> OLD.summary OR NEW.description <> OLD.description
     OR NEW.notes IS DISTINCT FROM OLD.notes OR NEW.author_name <> OLD.author_name OR NEW.created_at <> OLD.created_at
     OR NEW.pages IS DISTINCT FROM OLD.pages THEN
    RAISE EXCEPTION 'theme_submissions.fixed: a submission is kept as it was submitted' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.preset_id IS DISTINCT FROM OLD.preset_id AND OLD.preset_id IS NOT NULL THEN
    RAISE EXCEPTION 'theme_submissions.preset: a submission''s theme is set once' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.content_starter_id IS DISTINCT FROM OLD.content_starter_id AND (OLD.content_starter_id IS NOT NULL OR NEW.pages IS NULL) THEN
    RAISE EXCEPTION 'theme_submissions.content: a submission''s content is placed once, and only for its pages' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status <> OLD.status AND NOT (
    (OLD.status = 'waiting' AND NEW.status IN ('reviewing', 'rejected', 'withdrawn'))
    OR (OLD.status = 'reviewing' AND NEW.status IN ('approved', 'rejected', 'withdrawn'))
  ) THEN
    RAISE EXCEPTION 'theme_submissions.status: a submission moves only forward' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.status IN ('approved', 'rejected', 'withdrawn') AND (
    NEW.reason IS DISTINCT FROM OLD.reason OR NEW.decided_by IS DISTINCT FROM OLD.decided_by OR NEW.decided_at IS DISTINCT FROM OLD.decided_at
  ) THEN
    RAISE EXCEPTION 'theme_submissions.decided: a decision is kept as it was made' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status = 'approved' AND NEW.preset_id IS NULL THEN
    RAISE EXCEPTION 'theme_submissions.approved: an approved submission names its theme' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: undo_shipment(uuid, uuid, uuid, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.undo_shipment(p_store uuid, p_shipment uuid, p_account uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_order_id uuid;
  v_order record;
  v_ship record;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_lines jsonb;
  v_units integer;
  v_left integer;
  v_reopened boolean := false;
BEGIN
  SELECT s.order_id INTO v_order_id FROM commerce.shipments s WHERE s.store_id = p_store AND s.id = p_shipment;
  IF v_order_id IS NULL THEN
    RAISE EXCEPTION 'shipment_undo.not_found: no such parcel in this store' USING ERRCODE = 'check_violation';
  END IF;
  SELECT o.id, o.status::text AS status, o.copied_from IS NOT NULL AS copied, o.delivered_at INTO v_order
    FROM commerce.orders o WHERE o.store_id = p_store AND o.id = v_order_id FOR UPDATE;
  SELECT s.* INTO v_ship FROM commerce.shipments s WHERE s.store_id = p_store AND s.id = p_shipment FOR UPDATE;
  IF v_order.copied THEN
    RAISE EXCEPTION 'shipment_undo.copied: a copied order is history' USING ERRCODE = 'check_violation';
  END IF;
  IF v_ship.undone_at IS NOT NULL THEN
    RAISE EXCEPTION 'shipment_undo.already_undone: this parcel was undone already' USING ERRCODE = 'check_violation';
  END IF;
  IF v_order.status NOT IN ('paid', 'fulfilled') THEN
    RAISE EXCEPTION 'shipment_undo.status: only a parcel of a paid or sent order is undone (the order is %)', v_order.status USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (SELECT 1 FROM commerce.order_edits e WHERE e.store_id = p_store AND e.order_id = v_order_id AND e.status = 'awaiting_payment') THEN
    RAISE EXCEPTION 'shipment_undo.edit_pending: a change to this order waits for the customer''s payment' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
       SELECT 1 FROM commerce.returns r
        WHERE r.store_id = p_store AND r.order_id = v_order_id AND r.status::text NOT IN ('declined', 'cancelled') AND r.created_at >= v_ship.created_at
     ) OR EXISTS (
       SELECT 1 FROM commerce.withdrawal_requests w
        WHERE w.store_id = p_store AND w.order_id = v_order_id AND w.status = 'confirmed' AND w.confirmed_at >= v_ship.created_at
     ) THEN
    RAISE EXCEPTION 'shipment_undo.return: a return or withdrawal was made after this parcel was recorded' USING ERRCODE = 'check_violation';
  END IF;
  IF char_length(coalesce(v_reason, '')) > 200 THEN
    RAISE EXCEPTION 'shipment_undo.reason_too_long: the reason is at most 200 characters' USING ERRCODE = 'check_violation';
  END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object('lineId', sl.order_line_id, 'sku', ol.sku, 'title', ol.title, 'quantity', sl.quantity) ORDER BY ol.title, ol.sku, ol.id), '[]'::jsonb),
         coalesce(sum(sl.quantity), 0)::integer
    INTO v_lines, v_units
    FROM commerce.shipment_lines sl
    JOIN commerce.order_lines ol ON ol.store_id = sl.store_id AND ol.id = sl.order_line_id
   WHERE sl.store_id = p_store AND sl.shipment_id = p_shipment;

  PERFORM set_config('kaizen.shipment_undo', p_shipment::text, true);
  UPDATE commerce.shipments SET undone_at = now(), undone_by = p_account, undo_reason = v_reason WHERE store_id = p_store AND id = p_shipment;
  PERFORM set_config('kaizen.shipment_undo', '', true);
  UPDATE commerce.shipment_tracking SET stopped = 'undone', stopped_at = now(), updated_at = now()
   WHERE store_id = p_store AND shipment_id = p_shipment AND stopped IS DISTINCT FROM 'undone';

  IF v_order.status = 'fulfilled' AND commerce.order_fulfilment(v_order_id) IS DISTINCT FROM 'sent' THEN
    UPDATE commerce.orders SET status = 'paid' WHERE store_id = p_store AND id = v_order_id;
    v_reopened := true;
  END IF;
  IF v_order.delivered_at IS NOT NULL THEN
    UPDATE commerce.orders SET delivered_at = NULL, delivered_source = NULL WHERE store_id = p_store AND id = v_order_id;
    INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
    VALUES (p_store, v_order_id, 'order.delivery_reopened', jsonb_build_object('was', v_order.delivered_at, 'undone', p_shipment), 'system');
  END IF;
  SELECT coalesce(sum(commerce.line_to_send(ol.id)), 0)::integer INTO v_left
    FROM commerce.order_lines ol WHERE ol.store_id = p_store AND ol.order_id = v_order_id;

  INSERT INTO commerce.order_events (store_id, order_id, type, data, actor)
  VALUES (p_store, v_order_id, 'order.shipment_undone',
          jsonb_strip_nulls(jsonb_build_object(
            'shipment', p_shipment, 'carrier', v_ship.carrier, 'tracking', v_ship.tracking_number, 'carrierId', v_ship.carrier_id,
            'legacy', v_ship.legacy, 'units', v_units, 'lines', v_lines, 'left', v_left, 'reopened', v_reopened, 'note', v_reason
          )),
          'staff');

  RETURN jsonb_build_object(
    'orderId', v_order_id, 'units', v_units, 'left', v_left, 'reopened', v_reopened, 'deliveredWas', v_order.delivered_at,
    'carrier', v_ship.carrier, 'carrierId', v_ship.carrier_id, 'consignment', v_ship.consignment_number, 'tracking', v_ship.tracking_number,
    'legacy', v_ship.legacy
  );
END;
$$;


--
-- Name: unit_price_required(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.unit_price_required(p_store uuid, p_product uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT COALESCE(
           (SELECT p.sold_by_measure FROM commerce.products p WHERE p.store_id = p_store AND p.id = p_product),
           false)
      OR EXISTS (
        WITH RECURSIVE up(id) AS (
          SELECT pt.term_id
            FROM commerce.product_terms pt
            JOIN commerce.terms t ON t.id = pt.term_id AND t.store_id = p_store AND t.kind = 'category'
           WHERE pt.store_id = p_store AND pt.product_id = p_product
          UNION
          SELECT t.parent_id
            FROM up
            JOIN commerce.terms t ON t.id = up.id AND t.store_id = p_store
           WHERE t.parent_id IS NOT NULL
        )
        SELECT 1
          FROM up
          JOIN commerce.terms t ON t.id = up.id AND t.store_id = p_store AND t.requires_unit_price
      );
$$;


--
-- Name: unsent_closures_refresh(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.unsent_closures_refresh() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM commerce.refresh_fulfilment(NEW.store_id, NEW.order_id);
  RETURN NULL;
END;
$$;


--
-- Name: unsent_closures_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.unsent_closures_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_order record;
  v_line record;
  v_left integer;
BEGIN
  SELECT o.status, o.copied_from IS NOT NULL AS copied INTO v_order
    FROM commerce.orders o WHERE o.store_id = NEW.store_id AND o.id = NEW.order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unsent_closure.order: the order is not this store''s' USING ERRCODE = 'check_violation';
  END IF;
  IF v_order.copied THEN
    RAISE EXCEPTION 'copied_order: an order copied from another store is history and cannot get a row in %', TG_TABLE_NAME USING ERRCODE = 'check_violation';
  END IF;
  IF v_order.status <> 'paid' THEN
    RAISE EXCEPTION 'unsent_closure.not_paid: only units of a paid order that is not sent in full are closed (the order is %)', v_order.status
      USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (SELECT 1 FROM commerce.order_edits e WHERE e.store_id = NEW.store_id AND e.order_id = NEW.order_id AND e.status = 'awaiting_payment') THEN
    RAISE EXCEPTION 'unsent_closure.edit_pending: a change to this order waits for the customer''s payment' USING ERRCODE = 'check_violation';
  END IF;
  SELECT ol.order_id, ol.delivery, ol.variant_id INTO v_line
    FROM commerce.order_lines ol WHERE ol.store_id = NEW.store_id AND ol.id = NEW.order_line_id;
  IF NOT FOUND OR v_line.order_id <> NEW.order_id THEN
    RAISE EXCEPTION 'unsent_closure.order: a closure names a line of its own order' USING ERRCODE = 'check_violation';
  END IF;
  IF v_line.delivery <> 'physical' OR v_line.variant_id IS NULL THEN
    RAISE EXCEPTION 'unsent_closure.not_physical: only goods that are shipped have units to send' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.refund_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM commerce.refunds r JOIN commerce.payments p ON p.store_id = r.store_id AND p.id = r.payment_id
     WHERE r.store_id = NEW.store_id AND r.id = NEW.refund_id AND p.order_id = NEW.order_id
  ) THEN
    RAISE EXCEPTION 'unsent_closure.refund: the refund named is not a refund of this order' USING ERRCODE = 'check_violation';
  END IF;
  v_left := commerce.line_to_send(NEW.order_line_id);
  IF NEW.quantity > v_left THEN
    RAISE EXCEPTION 'unsent_closure.too_many: % units closed of a line with % still to send', NEW.quantity, v_left USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: usd_per_euro(date); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.usd_per_euro(p_day date) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce(
    (SELECT r.rate FROM commerce.ecb_reference_rates r WHERE r.currency = 'USD' AND r.rate_date <= p_day ORDER BY r.rate_date DESC LIMIT 1),
    (SELECT r.rate FROM commerce.ecb_reference_rates r WHERE r.currency = 'USD' ORDER BY r.rate_date LIMIT 1),
    1::numeric
  )
$$;


--
-- Name: variant_cost_history_fixed(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.variant_cost_history_fixed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  RAISE EXCEPTION 'variant_cost_history.fixed: a cost change is kept as it was' USING ERRCODE = 'check_violation';
END;
$$;


--
-- Name: variant_cost_keep(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.variant_cost_keep() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_ctx jsonb;
  v_source text;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.cost_minor IS NOT DISTINCT FROM OLD.cost_minor THEN RETURN NULL; END IF;
  IF TG_OP = 'INSERT' AND NEW.cost_minor IS NULL THEN RETURN NULL; END IF;
  BEGIN
    v_ctx := nullif(current_setting('kaizen.cost_source', true), '')::jsonb;
  EXCEPTION WHEN OTHERS THEN
    v_ctx := NULL;
  END;
  v_source := coalesce(v_ctx ->> 'source', 'editor');
  IF v_source NOT IN ('editor', 'purchase_order', 'file', 'system') THEN v_source := 'editor'; END IF;
  INSERT INTO commerce.variant_cost_history (store_id, variant_id, cost_minor, source, purchase_order_id, source_currency, source_cost_minor, account_id)
  VALUES (NEW.store_id, NEW.id, NEW.cost_minor, v_source,
    CASE WHEN v_source = 'purchase_order' THEN (v_ctx ->> 'order')::uuid END,
    CASE WHEN v_source = 'purchase_order' THEN v_ctx ->> 'currency' END,
    CASE WHEN v_source = 'purchase_order' THEN (v_ctx ->> 'cost')::bigint END,
    (v_ctx ->> 'account')::uuid);
  RETURN NULL;
END;
$$;


--
-- Name: vat_categories_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.vat_categories_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'vat_category_kept: a VAT category is never deleted; switch it off' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.code <> OLD.code OR NEW.built_in <> OLD.built_in THEN
    RAISE EXCEPTION 'vat_category_fixed: a category keeps its code' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.built_in AND (NEW.name_en <> OLD.name_en OR NOT NEW.active) THEN
    RAISE EXCEPTION 'vat_category_built_in: a built-in category is not renamed or switched off' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: vat_checks_immutable(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.vat_checks_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF current_setting('commerce.anonymising', true) = 'on'
     AND (to_jsonb(NEW) - ARRAY['name', 'address', 'number']) IS NOT DISTINCT FROM (to_jsonb(OLD) - ARRAY['name', 'address', 'number']) THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'vat_check_immutable: a VAT number check is a record and is not changed' USING ERRCODE = 'check_violation';
END;
$$;


--
-- Name: vat_incl(bigint, numeric); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.vat_incl(p_amount bigint, p_rate numeric) RETURNS bigint
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT CASE WHEN p_rate IS NULL OR p_rate <= 0 OR p_amount <= 0 THEN 0::bigint
    ELSE (p_amount * round(p_rate * 10000)::bigint * 2 + (10000 + round(p_rate * 10000)::bigint))
         / (2 * (10000 + round(p_rate * 10000)::bigint))
  END
$$;


--
-- Name: vat_rate(character, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.vat_rate(p_country character, p_category text) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT CASE
    WHEN p_category = 'exempt' THEN 0::numeric
    ELSE coalesce(
      (SELECT r.rate FROM commerce.countries c
         JOIN commerce.vat_rates r ON r.country_code = c.code AND r.category = p_category
          AND r.valid_from <= (now() AT TIME ZONE coalesce(c.time_zone, 'UTC'))::date
          AND (r.valid_to IS NULL OR r.valid_to > (now() AT TIME ZONE coalesce(c.time_zone, 'UTC'))::date)
        WHERE c.code = p_country),
      (SELECT r.rate FROM commerce.countries c
         JOIN commerce.vat_rates r ON r.country_code = c.code AND r.category = 'standard'
          AND r.valid_from <= (now() AT TIME ZONE coalesce(c.time_zone, 'UTC'))::date
          AND (r.valid_to IS NULL OR r.valid_to > (now() AT TIME ZONE coalesce(c.time_zone, 'UTC'))::date)
        WHERE c.code = p_country),
      (SELECT c.standard_vat_rate FROM commerce.countries c WHERE c.code = p_country),
      0::numeric
    )
  END
$$;


--
-- Name: vat_rate(character, text, timestamp with time zone); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.vat_rate(p_country character, p_category text, p_at timestamp with time zone) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT CASE
    WHEN p_category = 'exempt' THEN 0::numeric
    ELSE coalesce(
      (SELECT r.rate FROM commerce.countries c
         JOIN commerce.vat_rates r ON r.country_code = c.code AND r.category = p_category
          AND r.valid_from <= (p_at AT TIME ZONE coalesce(c.time_zone, 'UTC'))::date
          AND (r.valid_to IS NULL OR r.valid_to > (p_at AT TIME ZONE coalesce(c.time_zone, 'UTC'))::date)
        WHERE c.code = p_country),
      (SELECT r.rate FROM commerce.countries c
         JOIN commerce.vat_rates r ON r.country_code = c.code AND r.category = 'standard'
          AND r.valid_from <= (p_at AT TIME ZONE coalesce(c.time_zone, 'UTC'))::date
          AND (r.valid_to IS NULL OR r.valid_to > (p_at AT TIME ZONE coalesce(c.time_zone, 'UTC'))::date)
        WHERE c.code = p_country),
      (SELECT c.standard_vat_rate FROM commerce.countries c WHERE c.code = p_country),
      0::numeric
    )
  END
$$;


--
-- Name: vat_rates_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.vat_rates_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'vat_rate_history: a rate is never deleted; end its period and add a new one' USING ERRCODE = 'check_violation';
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF EXISTS (
      SELECT 1 FROM commerce.vat_rates o
       WHERE o.country_code = NEW.country_code AND o.category = NEW.category
         AND NEW.valid_from < coalesce(o.valid_to, 'infinity'::date)
         AND coalesce(NEW.valid_to, 'infinity'::date) > o.valid_from
    ) THEN
      RAISE EXCEPTION 'vat_rate_overlap: the period overlaps another rate of the same country and category'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE: a period may be ended once, a rate verified or its note changed; nothing else.
  IF NEW.country_code <> OLD.country_code OR NEW.category <> OLD.category OR NEW.rate <> OLD.rate
     OR NEW.valid_from <> OLD.valid_from OR NEW.source <> OLD.source OR NEW.checked_on <> OLD.checked_on
     OR NEW.created_at <> OLD.created_at OR NEW.created_by IS DISTINCT FROM OLD.created_by THEN
    RAISE EXCEPTION 'vat_rate_history: a rate is never edited in place; end its period and add a new one'
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.valid_to IS NOT NULL AND NEW.valid_to IS DISTINCT FROM OLD.valid_to THEN
    RAISE EXCEPTION 'vat_rate_history: an ended period is not changed' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.verified_at IS NOT NULL AND (NEW.verified_at IS DISTINCT FROM OLD.verified_at OR NEW.verified_by IS DISTINCT FROM OLD.verified_by) THEN
    RAISE EXCEPTION 'vat_rate_verified: a verification is not taken back; add a new rate with a note' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: verify_retention_rule(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.verify_retention_rule(p_id uuid, p_account uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_kind text;
  v_country char(2);
BEGIN
  IF p_account IS NULL THEN
    RAISE EXCEPTION 'retention_rule_verified: a review names the person who made it' USING ERRCODE = 'check_violation';
  END IF;
  UPDATE commerce.retention_rules SET verified_by = p_account, verified_at = now()
   WHERE id = p_id AND verified_at IS NULL
  RETURNING kind, country INTO v_kind, v_country;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'retention_rule_verified: no such rule, or it is already reviewed' USING ERRCODE = 'check_violation';
  END IF;
  INSERT INTO commerce.audit_log (store_id, account_id, action, area, details)
  VALUES (NULL, p_account, 'retention.rule_verified', 'platform', jsonb_build_object('rule', p_id, 'kind', v_kind, 'country', v_country));
END;
$$;


--
-- Name: verify_vat_rate(character, text, date, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.verify_vat_rate(p_country character, p_category text, p_valid_from date, p_account uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF p_account IS NULL THEN
    RAISE EXCEPTION 'vat_rate_verified: a verification names the person who made it' USING ERRCODE = 'check_violation';
  END IF;
  UPDATE commerce.vat_rates SET verified_by = p_account, verified_at = now()
   WHERE country_code = p_country AND category = p_category AND valid_from = p_valid_from AND verified_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'vat_rate_verified: no such rate, or it is already verified' USING ERRCODE = 'check_violation';
  END IF;
  INSERT INTO commerce.audit_log (store_id, account_id, action, details)
  VALUES (NULL, p_account, 'vat.rate_verified', jsonb_build_object(
    'country', p_country, 'category', p_category, 'valid_from', p_valid_from));
END;
$$;


--
-- Name: waiting_invoices(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.waiting_invoices(p_store uuid) RETURNS TABLE(order_id uuid, order_number text, paid_at timestamp with time zone, reason text, vat_kind text, total_minor bigint, currency text)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
BEGIN
  RETURN QUERY
  SELECT o.id, o.number, pe.paid_at,
         CASE WHEN commerce.invoice_readiness(o.id) = 'ready' THEN 'invoice_failed' ELSE commerce.invoice_readiness(o.id) END,
         o.vat_kind, o.total_minor, o.currency::text
    FROM commerce.orders o
    CROSS JOIN LATERAL (
      SELECT min(e.created_at) AS paid_at FROM commerce.order_events e WHERE e.store_id = o.store_id AND e.order_id = o.id AND e.type = 'order.paid'
    ) pe
   WHERE o.store_id = p_store AND o.copied_from IS NULL AND o.host_id IS NULL AND pe.paid_at IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM commerce.invoices i WHERE i.store_id = o.store_id AND i.order_id = o.id AND i.kind = 'order')
     AND commerce.invoice_eligibility(o.id) = 'ok'
   ORDER BY pe.paid_at, o.id;
END;
$$;


--
-- Name: withdrawal_request_lines_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.withdrawal_request_lines_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_req commerce.withdrawal_requests%ROWTYPE;
  v_line commerce.order_lines%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    -- Cascading from a deleted (unconfirmed) request finds no parent; deleting one by hand is only for a pending request.
    SELECT * INTO v_req FROM commerce.withdrawal_requests w WHERE w.store_id = OLD.store_id AND w.id = OLD.withdrawal_request_id;
    IF FOUND AND v_req.status <> 'pending' THEN
      RAISE EXCEPTION 'withdrawal_confirmed: the lines of a withdrawal that was confirmed are kept' USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF NEW.withdrawal_request_id <> OLD.withdrawal_request_id OR NEW.order_line_id <> OLD.order_line_id THEN
      RAISE EXCEPTION 'withdrawal_fixed: a line stays with its request' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  SELECT * INTO v_req FROM commerce.withdrawal_requests w WHERE w.store_id = NEW.store_id AND w.id = NEW.withdrawal_request_id;
  IF v_req.status <> 'pending' THEN
    RAISE EXCEPTION 'withdrawal_confirmed: a withdrawal that was confirmed (or lapsed) takes no more lines' USING ERRCODE = 'check_violation';
  END IF;

  -- The line must be one of the request's own order, and what is declared still left (a pending request holds nothing:
  -- the return's lines are the claim, and they are checked again when the request is confirmed).
  SELECT * INTO v_line FROM commerce.order_lines ol WHERE ol.store_id = NEW.store_id AND ol.id = NEW.order_line_id FOR NO KEY UPDATE;
  IF v_line.order_id <> v_req.order_id THEN
    RAISE EXCEPTION 'withdrawal_line_order: the line belongs to another order' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.quantity > v_line.quantity - commerce.returned_quantity(v_line.id) THEN
    RAISE EXCEPTION 'withdrawal_quantity: more is declared than is left to withdraw from' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: withdrawal_requests_rules(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.withdrawal_requests_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_status commerce.order_status;
  r record;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status = 'confirmed' THEN
      RAISE EXCEPTION 'withdrawal_confirmed: a confirmed withdrawal is a legal record and is kept'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  END IF;

  IF TG_OP = 'INSERT' THEN
    SELECT o.status INTO v_status FROM commerce.orders o WHERE o.store_id = NEW.store_id AND o.id = NEW.order_id;
    IF v_status IS NULL OR v_status NOT IN ('paid', 'fulfilled', 'closed') THEN
      RAISE EXCEPTION 'withdrawal_order_not_paid: an order that was not paid cannot be withdrawn from'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status <> 'pending' OR NEW.confirmed_at IS NOT NULL OR NEW.acknowledged_at IS NOT NULL THEN
      RAISE EXCEPTION 'withdrawal_starts_pending: a withdrawal starts as a pending request and is confirmed in a second step'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE
  IF NEW.id <> OLD.id OR NEW.store_id <> OLD.store_id OR NEW.order_id <> OLD.order_id THEN
    RAISE EXCEPTION 'withdrawal_fixed: a withdrawal stays with its order' USING ERRCODE = 'check_violation';
  END IF;
  IF ((NEW.name IS DISTINCT FROM OLD.name OR NEW.email IS DISTINCT FROM OLD.email) AND current_setting('commerce.anonymising', true) IS DISTINCT FROM 'on') OR NEW.channel IS DISTINCT FROM OLD.channel
     OR NEW.locale IS DISTINCT FROM OLD.locale OR NEW.market_code IS DISTINCT FROM OLD.market_code
     OR NEW.submitted_at IS DISTINCT FROM OLD.submitted_at OR NEW.expires_at IS DISTINCT FROM OLD.expires_at THEN
    RAISE EXCEPTION 'withdrawal_fixed: what the shopper declared is not changed afterwards' USING ERRCODE = 'check_violation';
  END IF;

  IF OLD.status = 'confirmed' THEN
    -- A legal record: only its acknowledgement may be recorded (or sent again), never taken back.
    IF NEW.status <> 'confirmed' OR NEW.confirmed_at IS DISTINCT FROM OLD.confirmed_at THEN
      RAISE EXCEPTION 'withdrawal_confirmed: a confirmed withdrawal cannot be changed' USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.acknowledged_at IS NOT NULL AND NEW.acknowledged_at IS NULL THEN
      RAISE EXCEPTION 'withdrawal_acknowledged: an acknowledgement that was sent is not taken back' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.status = 'expired' AND NEW.status <> 'expired' THEN
    RAISE EXCEPTION 'withdrawal_lapsed: a request that lapsed cannot be confirmed; the shopper starts again'
      USING ERRCODE = 'check_violation';
  END IF;

  IF OLD.status = 'pending' AND NEW.status = 'confirmed' THEN
    IF now() > OLD.expires_at THEN
      RAISE EXCEPTION 'withdrawal_lapsed: the request was not confirmed within its time; the shopper starts again'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM commerce.withdrawal_request_lines l WHERE l.store_id = OLD.store_id AND l.withdrawal_request_id = OLD.id
    ) THEN
      RAISE EXCEPTION 'withdrawal_no_lines: a withdrawal names at least one line' USING ERRCODE = 'check_violation';
    END IF;
    -- Taken again under the lines' locks: what is declared must still be left when it is confirmed.
    FOR r IN
      SELECT l.order_line_id, l.quantity, ol.quantity AS ordered
        FROM commerce.withdrawal_request_lines l
        JOIN commerce.order_lines ol ON ol.store_id = l.store_id AND ol.id = l.order_line_id
       WHERE l.store_id = OLD.store_id AND l.withdrawal_request_id = OLD.id
       ORDER BY l.order_line_id
       FOR NO KEY UPDATE OF ol
    LOOP
      IF r.quantity > r.ordered - commerce.returned_quantity(r.order_line_id) THEN
        RAISE EXCEPTION 'withdrawal_quantity: more is declared than is left to withdraw from' USING ERRCODE = 'check_violation';
      END IF;
    END LOOP;
    NEW.confirmed_at := coalesce(NEW.confirmed_at, now());
    RETURN NEW;
  END IF;

  IF OLD.status = 'pending' AND NEW.status = 'pending' AND NEW.confirmed_at IS NOT NULL THEN
    RAISE EXCEPTION 'withdrawal_confirmed: confirm a request by its status' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: withdrawn_quantity(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.withdrawn_quantity(p_order_line uuid) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce(sum(rl.quantity), 0)::integer
    FROM commerce.return_lines rl
    JOIN commerce.returns r ON r.store_id = rl.store_id AND r.id = rl.return_id
   WHERE rl.order_line_id = p_order_line
     AND rl.decision = 'accept'
     AND r.kind = 'withdrawal'
     AND r.status NOT IN ('declined', 'cancelled')
$$;


--
-- Name: work_credit_note_applied(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.work_credit_note_applied() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM commerce.work_refresh_invoice(NEW.store_id, NEW.invoice_id, NEW.created_by, NULL);
  PERFORM commerce.queue_integration_event(NEW.store_id, 'work_invoice.credited', NEW.invoice_id);
  RETURN NULL;
END;
$$;


--
-- Name: work_credit_note_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.work_credit_note_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_inv record;
  v_credited bigint;
BEGIN
  SELECT i.status, i.currency, i.total_minor INTO v_inv FROM commerce.work_invoices i
   WHERE i.store_id = NEW.store_id AND i.id = NEW.invoice_id FOR UPDATE;
  IF v_inv.status NOT IN ('sent', 'paid') THEN
    RAISE EXCEPTION 'work_credit_note.status: only an issued invoice that is not already credited can be credited'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_inv.currency <> NEW.currency THEN
    RAISE EXCEPTION 'work_credit_note.currency: the credit note must be in the invoice''s currency' USING ERRCODE = 'check_violation';
  END IF;
  SELECT coalesce(sum(c.total_minor), 0) INTO v_credited FROM commerce.work_credit_notes c
   WHERE c.store_id = NEW.store_id AND c.invoice_id = NEW.invoice_id;
  IF v_credited + NEW.total_minor > v_inv.total_minor THEN
    RAISE EXCEPTION 'work_credit_note.too_much: the credit notes would be more than the invoice' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: work_entry_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.work_entry_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_status text;
  v_imported boolean;
  v_line_assignment uuid;
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE') AND OLD.invoice_line_id IS NOT NULL THEN
    SELECT i.status INTO v_status
      FROM commerce.work_invoice_lines l
      JOIN commerce.work_invoices i ON i.store_id = l.store_id AND i.id = l.invoice_id
     WHERE l.store_id = OLD.store_id AND l.id = OLD.invoice_line_id;
    IF v_status IN ('sent', 'paid') THEN
      RAISE EXCEPTION 'work_time.immutable: time on an issued invoice cannot be changed or deleted' USING ERRCODE = 'restrict_violation';
    END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  IF NEW.invoice_line_id IS NOT NULL THEN
    IF NOT NEW.billable THEN
      RAISE EXCEPTION 'work_time.billable: only billable time can be put on an invoice' USING ERRCODE = 'check_violation';
    END IF;
    IF TG_OP = 'INSERT' OR NEW.invoice_line_id IS DISTINCT FROM OLD.invoice_line_id THEN
      SELECT i.status, i.imported, l.assignment_id INTO v_status, v_imported, v_line_assignment
        FROM commerce.work_invoice_lines l
        JOIN commerce.work_invoices i ON i.store_id = l.store_id AND i.id = l.invoice_id
       WHERE l.store_id = NEW.store_id AND l.id = NEW.invoice_line_id;
      IF v_status IS DISTINCT FROM 'draft'
         AND NOT (TG_OP = 'INSERT' AND v_imported AND current_setting('commerce.work_importing', true) IS NOT DISTINCT FROM 'on') THEN
        RAISE EXCEPTION 'work_time.draft_only: time can only be put on the lines of a draft invoice' USING ERRCODE = 'check_violation';
      END IF;
      IF v_line_assignment IS NOT NULL AND v_line_assignment <> NEW.assignment_id THEN
        RAISE EXCEPTION 'work_time.assignment: the time belongs to another assignment than the line' USING ERRCODE = 'check_violation';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: work_event(uuid, text, uuid, text, jsonb, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.work_event(p_store uuid, p_entity_type text, p_entity_id uuid, p_type text, p_data jsonb DEFAULT '{}'::jsonb, p_account uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  INSERT INTO commerce.work_events (store_id, entity_type, entity_id, type, data, account_id)
  VALUES (p_store, p_entity_type, p_entity_id, p_type, coalesce(p_data, '{}'::jsonb), p_account)
$$;


--
-- Name: work_invoice_amounts(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.work_invoice_amounts(p_store uuid, p_invoice uuid, OUT total_minor bigint, OUT paid_minor bigint, OUT credited_minor bigint, OUT outstanding_minor bigint) RETURNS record
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT i.total_minor,
         (SELECT coalesce(sum(p.amount_minor), 0)::bigint FROM commerce.work_invoice_payments p
           WHERE p.store_id = i.store_id AND p.invoice_id = i.id),
         (SELECT coalesce(sum(c.total_minor), 0)::bigint FROM commerce.work_credit_notes c
           WHERE c.store_id = i.store_id AND c.invoice_id = i.id),
         greatest(0, i.total_minor
           - (SELECT coalesce(sum(p.amount_minor), 0) FROM commerce.work_invoice_payments p
               WHERE p.store_id = i.store_id AND p.invoice_id = i.id)
           - (SELECT coalesce(sum(c.total_minor), 0) FROM commerce.work_credit_notes c
               WHERE c.store_id = i.store_id AND c.invoice_id = i.id)
           - commerce.work_invoice_lost(i.store_id, i.id))::bigint
  FROM commerce.work_invoices i
  WHERE i.store_id = p_store AND i.id = p_invoice
$$;


--
-- Name: work_invoice_computed(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.work_invoice_computed(p_store uuid, p_invoice uuid) RETURNS TABLE(line_id uuid, rate numeric, excl_minor bigint, vat_minor bigint)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  WITH s AS (
    SELECT st.country, coalesce(ws.vat_registered, true) AS registered
    FROM commerce.stores st LEFT JOIN commerce.work_settings ws ON ws.store_id = st.id
    WHERE st.id = p_store
  ), r AS (
    SELECT l.id, l.quantity_hundredths, l.unit_price_minor, l.discount_bp,
           CASE WHEN l.vat_category = 'standard' AND s.registered
                THEN commerce.vat_rate(s.country, 'standard') ELSE 0::numeric END AS rate
    FROM commerce.work_invoice_lines l, s
    WHERE l.store_id = p_store AND l.invoice_id = p_invoice
  ), x AS (
    SELECT r.id, r.rate, commerce.work_line_excl(r.quantity_hundredths, r.unit_price_minor, r.discount_bp) AS excl FROM r
  )
  SELECT x.id, x.rate, x.excl, commerce.work_line_vat(x.excl, x.rate) FROM x
$$;


--
-- Name: work_invoice_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.work_invoice_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_free text[] := ARRAY['status', 'paid_at', 'sent_to', 'public_token', 'updated_at'];
  v_amounts record;
  v_lost bigint;
  v_due bigint;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.imported THEN
      IF current_setting('commerce.work_importing', true) IS DISTINCT FROM 'on' THEN
        RAISE EXCEPTION 'work_invoice.imported_only: imported invoices are made by the Kaizen Life import only'
          USING ERRCODE = 'restrict_violation';
      END IF;
      -- Issued already, with its own number and amounts: goes on to the reference checks below.
    ELSIF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'work_invoice.draft_only: an invoice starts as a draft and is issued by issue_work_invoice'
        USING ERRCODE = 'restrict_violation';
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    IF OLD.status <> 'draft' THEN
      -- An import may take back a copy an import made (D495: the same invoice brought in twice, from Life and from Tripletex): an
      -- imported invoice with no payment, no credit note, no loss and no time on its lines, only while importing. Its lines go with it.
      IF OLD.imported
         AND current_setting('commerce.work_importing', true) IS NOT DISTINCT FROM 'on'
         AND NOT EXISTS (SELECT 1 FROM commerce.work_invoice_payments p WHERE p.store_id = OLD.store_id AND p.invoice_id = OLD.id)
         AND NOT EXISTS (SELECT 1 FROM commerce.work_credit_notes c WHERE c.store_id = OLD.store_id AND c.invoice_id = OLD.id)
         AND NOT EXISTS (SELECT 1 FROM commerce.work_invoice_losses l WHERE l.store_id = OLD.store_id AND l.invoice_id = OLD.id)
         AND NOT EXISTS (
           SELECT 1 FROM commerce.work_time_entries e
             JOIN commerce.work_invoice_lines l ON l.store_id = e.store_id AND l.id = e.invoice_line_id
            WHERE l.store_id = OLD.store_id AND l.invoice_id = OLD.id) THEN
        RETURN OLD;
      END IF;
      RAISE EXCEPTION 'work_invoice.immutable: an issued invoice cannot be deleted; credit it' USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN OLD;
  ELSIF OLD.status = 'draft' THEN
    IF NEW.status <> 'draft' THEN
      IF NEW.status <> 'sent' OR current_setting('commerce.work_issuing', true) IS DISTINCT FROM OLD.id::text THEN
        RAISE EXCEPTION 'work_invoice.draft_only: an invoice is issued by issue_work_invoice' USING ERRCODE = 'restrict_violation';
      END IF;
      RETURN NEW;
    END IF;
  ELSE
    -- An imported invoice that came without a number of its own (Life's) takes its number once, from an import (D494: the
    -- number Tripletex gave the same invoice), as its `document_number` too; nothing else of it changes, and a number once
    -- kept is never changed.
    IF OLD.imported AND OLD.legacy_number IS NULL AND NEW.legacy_number IS NOT NULL
       AND NEW.document_number IS NOT DISTINCT FROM NEW.legacy_number
       AND current_setting('commerce.work_importing', true) IS NOT DISTINCT FROM 'on'
       AND (to_jsonb(NEW) - v_free - ARRAY['legacy_number', 'document_number']) = (to_jsonb(OLD) - v_free - ARRAY['legacy_number', 'document_number']) THEN
      RETURN NEW;
    END IF;
    -- `imported` and `legacy_number` are not free otherwise: an issued invoice never becomes or stops being imported.
    IF (to_jsonb(NEW) - v_free) IS DISTINCT FROM (to_jsonb(OLD) - v_free) THEN
      RAISE EXCEPTION 'work_invoice.immutable: an issued invoice cannot be changed; credit it' USING ERRCODE = 'restrict_violation';
    END IF;
    IF NEW.status <> OLD.status THEN
      SELECT * INTO v_amounts FROM commerce.work_invoice_amounts(OLD.store_id, OLD.id);
      v_lost := commerce.work_invoice_lost(OLD.store_id, OLD.id);
      v_due := v_amounts.total_minor - v_amounts.credited_minor;
      IF NOT (
        (OLD.status IN ('sent', 'lost') AND NEW.status = 'paid' AND v_amounts.paid_minor >= v_due)
        OR (OLD.status IN ('paid', 'lost') AND NEW.status = 'sent' AND v_amounts.paid_minor + v_lost < v_due)
        OR (OLD.status IN ('sent', 'paid') AND NEW.status = 'lost' AND v_lost > 0 AND v_amounts.paid_minor < v_due
            AND v_amounts.paid_minor + v_lost >= v_due)
        OR (OLD.status IN ('sent', 'paid', 'lost') AND NEW.status = 'void' AND v_amounts.credited_minor >= v_amounts.total_minor)
      ) THEN
        RAISE EXCEPTION 'work_invoice.status: % to % is not allowed for this invoice', OLD.status, NEW.status
          USING ERRCODE = 'restrict_violation';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  -- A draft (new or edited), or an imported invoice, points only at its own client's assignment and templates.
  IF NEW.assignment_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM commerce.work_assignments a
    WHERE a.store_id = NEW.store_id AND a.id = NEW.assignment_id AND a.client_id = NEW.client_id
  ) THEN
    RAISE EXCEPTION 'work_invoice.assignment: the assignment belongs to another client' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.recurring_invoice_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM commerce.work_recurring_invoices r
    WHERE r.store_id = NEW.store_id AND r.id = NEW.recurring_invoice_id AND r.client_id = NEW.client_id
  ) THEN
    RAISE EXCEPTION 'work_invoice.recurring: the repeating invoice belongs to another client' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: work_invoice_lost(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.work_invoice_lost(p_store uuid, p_invoice uuid) RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce(sum(l.amount_minor), 0)::bigint FROM commerce.work_invoice_losses l
   WHERE l.store_id = p_store AND l.invoice_id = p_invoice
$$;


--
-- Name: work_invoice_problems(uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.work_invoice_problems(p_store uuid, p_invoice uuid) RETURNS text[]
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_inv record;
  v_s record;
  v_c record;
  v_p text[] := '{}';
  v_total bigint;
  v_lines integer;
BEGIN
  SELECT i.status, i.client_id INTO v_inv FROM commerce.work_invoices i WHERE i.store_id = p_store AND i.id = p_invoice;
  IF NOT FOUND THEN
    RETURN ARRAY['not_found'];
  END IF;
  IF v_inv.status <> 'draft' THEN
    RETURN ARRAY['not_draft'];
  END IF;
  SELECT st.legal_name, st.postal_address, st.country, st.organisation_number,
         coalesce(ws.vat_registered, true) AS registered, ws.vat_number, ws.bank_account
    INTO v_s
    FROM commerce.stores st LEFT JOIN commerce.work_settings ws ON ws.store_id = st.id
   WHERE st.id = p_store;
  SELECT c.name, c.country, c.billing_address, c.vat_number, c.vat_treatment INTO v_c
    FROM commerce.work_clients c WHERE c.store_id = p_store AND c.id = v_inv.client_id;

  IF coalesce(trim(v_s.legal_name), '') = '' THEN v_p := array_append(v_p, 'seller_name'); END IF;
  IF coalesce(trim(v_s.postal_address), '') = '' THEN v_p := array_append(v_p, 'seller_address'); END IF;
  IF v_s.country IS NULL THEN v_p := array_append(v_p, 'seller_country'); END IF;
  IF coalesce(trim(v_s.organisation_number), '') = '' THEN v_p := array_append(v_p, 'seller_organisation_number'); END IF;
  IF v_s.registered AND coalesce(trim(v_s.vat_number), '') = '' THEN v_p := array_append(v_p, 'seller_vat_number'); END IF;
  IF coalesce(trim(v_s.bank_account), '') = '' THEN v_p := array_append(v_p, 'seller_bank_account'); END IF;

  IF coalesce(trim(v_c.billing_address ->> 'line1'), '') = ''
     OR coalesce(trim(v_c.billing_address ->> 'postalCode'), '') = ''
     OR coalesce(trim(v_c.billing_address ->> 'city'), '') = '' THEN
    v_p := array_append(v_p, 'buyer_address');
  END IF;
  IF v_c.country IS NULL THEN v_p := array_append(v_p, 'buyer_country'); END IF;
  IF v_c.vat_treatment = 'reverse_charge' AND coalesce(trim(v_c.vat_number), '') = '' THEN
    v_p := array_append(v_p, 'buyer_vat_number');
  END IF;

  SELECT count(*) INTO v_lines FROM commerce.work_invoice_lines l WHERE l.store_id = p_store AND l.invoice_id = p_invoice;
  IF v_lines = 0 THEN
    v_p := array_append(v_p, 'no_lines');
  ELSE
    SELECT coalesce(sum(x.excl_minor + x.vat_minor), 0) INTO v_total FROM commerce.work_invoice_computed(p_store, p_invoice) x;
    IF v_total <= 0 THEN v_p := array_append(v_p, 'zero_total'); END IF;
    IF v_s.registered AND EXISTS (
      SELECT 1 FROM commerce.work_invoice_lines l
       WHERE l.store_id = p_store AND l.invoice_id = p_invoice
         AND NOT (CASE v_c.vat_treatment
                    WHEN 'domestic' THEN l.vat_category IN ('standard', 'exempt')
                    WHEN 'reverse_charge' THEN l.vat_category = 'reverse_charge'
                    WHEN 'outside_scope' THEN l.vat_category = 'outside_scope'
                    WHEN 'exempt' THEN l.vat_category = 'exempt'
                    ELSE false END)
    ) THEN
      v_p := array_append(v_p, 'vat_category_mismatch');
    END IF;
  END IF;
  RETURN v_p;
END;
$$;


--
-- Name: work_invoice_skip_deleted_period(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.work_invoice_skip_deleted_period() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF OLD.recurring_invoice_id IS NOT NULL AND OLD.recurring_period IS NOT NULL AND OLD.status = 'draft' THEN
    UPDATE commerce.work_recurring_invoices r
       SET skipped_periods = (SELECT array_agg(DISTINCT d ORDER BY d) FROM unnest(r.skipped_periods || OLD.recurring_period) AS d),
           updated_at = now()
     WHERE r.store_id = OLD.store_id AND r.id = OLD.recurring_invoice_id
       AND NOT (OLD.recurring_period = ANY (r.skipped_periods));
  END IF;
  RETURN OLD;
END;
$$;


--
-- Name: work_invoices_deal_win(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.work_invoices_deal_win() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM commerce.deal_win(
    NEW.store_id,
    ARRAY(SELECT l.deal_id FROM commerce.deal_links l WHERE l.store_id = NEW.store_id AND l.assignment_id = NEW.assignment_id),
    'work_invoice'
  );
  RETURN NULL;
END;
$$;


--
-- Name: work_line_excl(integer, bigint, integer); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.work_line_excl(p_quantity_hundredths integer, p_unit_price_minor bigint, p_discount_bp integer) RETURNS bigint
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT floor(p_quantity_hundredths::numeric * p_unit_price_minor * (10000 - p_discount_bp) / 1000000 + 0.5)::bigint
$$;


--
-- Name: work_line_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.work_line_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_status text;
  v_imported boolean;
BEGIN
  SELECT i.status, i.imported INTO v_status, v_imported FROM commerce.work_invoices i
   WHERE i.store_id = coalesce(NEW.store_id, OLD.store_id) AND i.id = coalesce(NEW.invoice_id, OLD.invoice_id);
  IF v_status IS NULL OR v_status = 'draft' THEN
    RETURN coalesce(NEW, OLD);
  END IF;
  IF TG_OP = 'INSERT' AND v_imported AND current_setting('commerce.work_importing', true) IS NOT DISTINCT FROM 'on' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE'
     AND (NEW.assignment_id IS NULL OR NEW.assignment_id IS NOT DISTINCT FROM OLD.assignment_id)
     AND (NEW.task_id IS NULL OR NEW.task_id IS NOT DISTINCT FROM OLD.task_id)
     AND (to_jsonb(NEW) - ARRAY['assignment_id', 'task_id']) = (to_jsonb(OLD) - ARRAY['assignment_id', 'task_id']) THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'work_invoice.immutable: the lines of an issued invoice cannot be % ; credit the invoice', lower(TG_OP)
    USING ERRCODE = 'restrict_violation';
END;
$$;


--
-- Name: work_line_vat(bigint, numeric); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.work_line_vat(p_excl_minor bigint, p_rate numeric) RETURNS bigint
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT floor(p_excl_minor::numeric * round(p_rate * 10000) / 10000 + 0.5)::bigint
$$;


--
-- Name: work_loss_applied(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.work_loss_applied() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM commerce.work_event(
    NEW.store_id, 'invoice', NEW.invoice_id,
    CASE WHEN NEW.reverses IS NOT NULL THEN 'loss.reversed' ELSE 'loss.written_off' END,
    jsonb_build_object('loss_id', NEW.id, 'amount_minor', NEW.amount_minor, 'currency', NEW.currency, 'written_off_on', NEW.written_off_on),
    NEW.recorded_by);
  PERFORM commerce.work_refresh_invoice(NEW.store_id, NEW.invoice_id, NEW.recorded_by, NULL);
  RETURN NULL;
END;
$$;


--
-- Name: work_loss_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.work_loss_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_inv record;
  v_amounts record;
  v_original record;
BEGIN
  SELECT i.status, i.currency INTO v_inv FROM commerce.work_invoices i
   WHERE i.store_id = NEW.store_id AND i.id = NEW.invoice_id FOR UPDATE;
  IF NOT FOUND OR v_inv.status NOT IN ('sent', 'lost') THEN
    RAISE EXCEPTION 'work_loss.status: only an issued invoice that is not paid or credited can be written off' USING ERRCODE = 'check_violation';
  END IF;
  IF v_inv.currency <> NEW.currency THEN
    RAISE EXCEPTION 'work_loss.currency: the loss is in % but the invoice is in %', NEW.currency, v_inv.currency USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.reverses IS NULL THEN
    SELECT * INTO v_amounts FROM commerce.work_invoice_amounts(NEW.store_id, NEW.invoice_id);
    IF NEW.amount_minor > v_amounts.outstanding_minor THEN
      RAISE EXCEPTION 'work_loss.too_much: only what is outstanding can be written off' USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    SELECT l.invoice_id, l.amount_minor, l.currency, l.reverses INTO v_original
      FROM commerce.work_invoice_losses l WHERE l.store_id = NEW.store_id AND l.id = NEW.reverses;
    IF v_original.invoice_id IS DISTINCT FROM NEW.invoice_id
       OR v_original.amount_minor IS DISTINCT FROM -NEW.amount_minor
       OR v_original.currency IS DISTINCT FROM NEW.currency
       OR v_original.reverses IS NOT NULL THEN
      RAISE EXCEPTION 'work_loss.reversal: a reversal takes back one loss of the same invoice, in full' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: work_payment_applied(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.work_payment_applied() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF current_setting('commerce.work_importing', true) IS DISTINCT FROM 'on' THEN
    PERFORM commerce.work_event(
      NEW.store_id, 'invoice', NEW.invoice_id,
      CASE WHEN NEW.reverses IS NOT NULL THEN 'payment.reversed'
           WHEN NEW.amount_minor < 0 THEN 'payment.refunded'
           ELSE 'payment.recorded' END,
      jsonb_build_object('payment_id', NEW.id, 'amount_minor', NEW.amount_minor, 'currency', NEW.currency,
                         'method', NEW.method, 'received_on', NEW.received_on),
      NEW.recorded_by);
  END IF;
  PERFORM commerce.work_refresh_invoice(NEW.store_id, NEW.invoice_id, NEW.recorded_by, NEW.received_on);
  RETURN NULL;
END;
$$;


--
-- Name: work_payment_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.work_payment_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_inv record;
  v_original record;
BEGIN
  SELECT i.status, i.currency INTO v_inv FROM commerce.work_invoices i
   WHERE i.store_id = NEW.store_id AND i.id = NEW.invoice_id FOR UPDATE;
  IF v_inv.status = 'draft' THEN
    RAISE EXCEPTION 'work_payment.draft: a draft invoice cannot be paid' USING ERRCODE = 'check_violation';
  END IF;
  IF v_inv.currency <> NEW.currency THEN
    RAISE EXCEPTION 'work_payment.currency: the payment is in % but the invoice is in %', NEW.currency, v_inv.currency
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_inv.status = 'void' AND NEW.amount_minor > 0 THEN
    RAISE EXCEPTION 'work_payment.void: a credited invoice takes no payment, only refunds' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.reverses IS NOT NULL THEN
    SELECT p.invoice_id, p.amount_minor, p.currency, p.reverses INTO v_original
      FROM commerce.work_invoice_payments p WHERE p.store_id = NEW.store_id AND p.id = NEW.reverses;
    IF v_original.invoice_id IS DISTINCT FROM NEW.invoice_id
       OR v_original.amount_minor IS DISTINCT FROM -NEW.amount_minor
       OR v_original.currency IS DISTINCT FROM NEW.currency
       OR v_original.reverses IS NOT NULL THEN
      RAISE EXCEPTION 'work_payment.reversal: a reversal takes back one payment of the same invoice, in full' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: work_refresh_invoice(uuid, uuid, uuid, date); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.work_refresh_invoice(p_store uuid, p_invoice uuid, p_account uuid, p_paid_on date) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_inv record;
  v_amounts record;
  v_due bigint;
  v_lost bigint;
BEGIN
  SELECT i.status, i.total_minor, s.time_zone INTO v_inv
    FROM commerce.work_invoices i JOIN commerce.stores s ON s.id = i.store_id
   WHERE i.store_id = p_store AND i.id = p_invoice
   FOR UPDATE OF i;
  IF NOT FOUND OR v_inv.status NOT IN ('sent', 'paid', 'lost') THEN
    RETURN;
  END IF;
  SELECT * INTO v_amounts FROM commerce.work_invoice_amounts(p_store, p_invoice);
  v_lost := commerce.work_invoice_lost(p_store, p_invoice);
  v_due := v_amounts.total_minor - v_amounts.credited_minor;
  IF v_amounts.credited_minor >= v_amounts.total_minor THEN
    UPDATE commerce.work_invoices SET status = 'void', updated_at = now()
     WHERE store_id = p_store AND id = p_invoice;
  ELSIF v_inv.status <> 'paid' AND v_amounts.paid_minor >= v_due THEN
    UPDATE commerce.work_invoices
       SET status = 'paid', updated_at = now(),
           paid_at = CASE WHEN p_paid_on IS NULL THEN now()
                          ELSE (p_paid_on::timestamp + interval '12 hours') AT TIME ZONE v_inv.time_zone END
     WHERE store_id = p_store AND id = p_invoice;
    IF current_setting('commerce.work_importing', true) IS DISTINCT FROM 'on' THEN
      PERFORM commerce.work_event(p_store, 'invoice', p_invoice, 'invoice.paid', '{}'::jsonb, p_account);
    END IF;
  ELSIF v_inv.status <> 'lost' AND v_lost > 0 AND v_amounts.paid_minor < v_due AND v_amounts.paid_minor + v_lost >= v_due THEN
    UPDATE commerce.work_invoices SET status = 'lost', paid_at = NULL, updated_at = now()
     WHERE store_id = p_store AND id = p_invoice;
    PERFORM commerce.work_event(p_store, 'invoice', p_invoice, 'invoice.lost', '{}'::jsonb, p_account);
  ELSIF v_inv.status <> 'sent' AND v_amounts.paid_minor + v_lost < v_due THEN
    UPDATE commerce.work_invoices SET status = 'sent', paid_at = NULL, updated_at = now()
     WHERE store_id = p_store AND id = p_invoice;
    PERFORM commerce.work_event(p_store, 'invoice', p_invoice, 'invoice.reopened', '{}'::jsonb, p_account);
  END IF;
END;
$$;


--
-- Name: work_series_guard(); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.work_series_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
BEGIN
  IF OLD.series NOT IN ('work_invoice', 'work_credit_note') THEN
    RETURN NEW;
  END IF;
  IF NEW.series <> OLD.series OR NEW.store_id <> OLD.store_id THEN
    RAISE EXCEPTION 'a work document series cannot be renamed or moved' USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW.prefix IS DISTINCT FROM OLD.prefix AND NEW.prefix !~ '^[A-Za-z0-9._/-]{0,10}$' THEN
    RAISE EXCEPTION 'work_series.prefix: a prefix is up to 10 letters, digits or . _ / -' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.next_number < OLD.next_number AND (
    (OLD.series = 'work_invoice' AND EXISTS (
      SELECT 1 FROM commerce.work_invoices i WHERE i.store_id = OLD.store_id AND i.number IS NOT NULL))
    OR (OLD.series = 'work_credit_note' AND EXISTS (
      SELECT 1 FROM commerce.work_credit_notes c WHERE c.store_id = OLD.store_id))
  ) THEN
    RAISE EXCEPTION 'work_series.lower: numbers already issued in % are not reused; the next number can only be raised', OLD.series
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$_$;


--
-- Name: work_set_series(uuid, text, text, bigint); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.work_set_series(p_store uuid, p_series text, p_prefix text, p_next_number bigint) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF p_series NOT IN ('work_invoice', 'work_credit_note') THEN
    RAISE EXCEPTION 'work_series.unknown: % is not a work series', p_series USING ERRCODE = 'check_violation';
  END IF;
  IF p_next_number IS NULL OR p_next_number < 1 THEN
    RAISE EXCEPTION 'work_series.number: the next number must be 1 or more' USING ERRCODE = 'check_violation';
  END IF;
  UPDATE commerce.document_series
     SET prefix = coalesce(p_prefix, ''), next_number = p_next_number
   WHERE store_id = p_store AND series = p_series;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'work_series.unknown: the store has no series %', p_series USING ERRCODE = 'no_data_found';
  END IF;
END;
$$;


--
-- Name: work_start_timer(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.work_start_timer(p_store uuid, p_account uuid, p_assignment uuid, p_task uuid DEFAULT NULL::uuid) RETURNS TABLE(timer_started_at timestamp with time zone, stopped_entry_id uuid)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_stopped uuid;
  v_one uuid;
  v_store uuid;
  v_started timestamptz;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('work_timer:' || p_account::text, 0));
  FOR v_store IN SELECT w.store_id FROM commerce.work_timers w WHERE w.account_id = p_account ORDER BY w.started_at LOOP
    SELECT e.id INTO v_one FROM commerce.work_stop_timer(v_store, p_account, NULL) e;
    v_stopped := coalesce(v_one, v_stopped);
  END LOOP;
  INSERT INTO commerce.work_timers (store_id, account_id, assignment_id, task_id)
  VALUES (p_store, p_account, p_assignment, p_task)
  RETURNING started_at INTO v_started;
  RETURN QUERY SELECT v_started, v_stopped;
END;
$$;


--
-- Name: work_time_entries; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.work_time_entries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    assignment_id uuid NOT NULL,
    task_id uuid,
    account_id uuid NOT NULL,
    work_date date NOT NULL,
    minutes integer NOT NULL,
    billable boolean DEFAULT true NOT NULL,
    note text,
    prepaid_minutes integer DEFAULT 0 NOT NULL,
    invoice_line_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT work_time_entries_minutes CHECK (((minutes >= 1) AND (minutes <= 1440))),
    CONSTRAINT work_time_entries_note CHECK ((length(COALESCE(note, ''::text)) <= 500)),
    CONSTRAINT work_time_entries_prepaid CHECK (((prepaid_minutes >= 0) AND (prepaid_minutes <= minutes)))
);


--
-- Name: work_stop_timer(uuid, uuid, text); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.work_stop_timer(p_store uuid, p_account uuid, p_note text DEFAULT NULL::text) RETURNS SETOF commerce.work_time_entries
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_timer commerce.work_timers;
  v_entry commerce.work_time_entries;
  v_zone text;
  v_minutes integer;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('work_timer:' || p_account::text, 0));
  DELETE FROM commerce.work_timers WHERE store_id = p_store AND account_id = p_account RETURNING * INTO v_timer;
  IF NOT FOUND THEN
    RETURN;
  END IF;
  SELECT s.time_zone INTO v_zone FROM commerce.stores s WHERE s.id = p_store;
  v_minutes := least(1440, greatest(1, ceil(extract(epoch FROM (now() - v_timer.started_at)) / 60)::integer));
  INSERT INTO commerce.work_time_entries (store_id, assignment_id, task_id, account_id, work_date, minutes, billable, note)
  VALUES (p_store, v_timer.assignment_id, v_timer.task_id, p_account,
          (v_timer.started_at AT TIME ZONE v_zone)::date, v_minutes, true, nullif(trim(p_note), ''))
  RETURNING * INTO v_entry;
  PERFORM commerce.work_event(
    p_store, 'time', v_entry.id, 'time.logged',
    jsonb_build_object('minutes', v_entry.minutes, 'assignment_id', v_entry.assignment_id,
                       'task_id', v_entry.task_id, 'source', 'timer'),
    p_account);
  RETURN NEXT v_entry;
END;
$$;


--
-- Name: work_today(uuid); Type: FUNCTION; Schema: commerce; Owner: -
--

CREATE FUNCTION commerce.work_today(p_store uuid) RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT (now() AT TIME ZONE s.time_zone)::date FROM commerce.stores s WHERE s.id = p_store
