--
-- Name: access_requests; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.access_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    email text NOT NULL,
    name text NOT NULL,
    store_name text NOT NULL,
    message text DEFAULT ''::text NOT NULL,
    status commerce.access_request_status DEFAULT 'pending'::commerce.access_request_status NOT NULL,
    decided_by uuid,
    decided_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    store_id uuid,
    referral_code text,
    starter_id uuid,
    design_preset_id uuid,
    design_variation text,
    locale text,
    domain text,
    self_serve boolean DEFAULT false NOT NULL,
    confirm_hash text,
    confirm_expires_at timestamp with time zone,
    confirmed_at timestamp with time zone,
    dream boolean DEFAULT false NOT NULL,
    terms_accepted_at timestamp with time zone,
    terms_version text,
    sandbox_id uuid,
    first_channel text,
    first_source text,
    first_campaign text,
    ad_consent_at timestamp with time zone,
