    CONSTRAINT access_requests_ad_signals CHECK (((ad_signals IS NULL) OR ((ad_consent_at IS NOT NULL) AND (jsonb_typeof(ad_signals) = 'object'::text) AND (length((ad_signals)::text) <= 2000)))),
    CONSTRAINT access_requests_confirm CHECK (((confirm_hash IS NULL) OR (self_serve AND (confirm_expires_at IS NOT NULL)))),
    CONSTRAINT access_requests_design_variation CHECK (((design_variation IS NULL) OR ((design_preset_id IS NOT NULL) AND (design_variation ~ '^[a-z0-9][a-z0-9-]{0,39}$'::text)))),
    CONSTRAINT access_requests_first_channel CHECK (((first_channel IS NULL) OR (first_channel = ANY (ARRAY['direct'::text, 'organic_search'::text, 'paid_search'::text, 'organic_social'::text, 'paid_social'::text, 'email'::text, 'affiliate'::text, 'referral'::text, 'ai_agent'::text, 'other'::text])))),
    CONSTRAINT access_requests_first_touch CHECK (((length(COALESCE(first_source, ''::text)) <= 120) AND (length(COALESCE(first_campaign, ''::text)) <= 120))),
    CONSTRAINT access_requests_locale CHECK (((locale IS NULL) OR (locale = ANY (ARRAY['en'::text, 'nb-NO'::text]))))
);


