--
-- Name: ai_providers; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.ai_providers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid,
    provider text NOT NULL,
    base_url text,
    api_key_encrypted text NOT NULL,
    api_key_hint text NOT NULL,
    embedding_model text,
    text_model text,
    min_similarity real DEFAULT 0.3 NOT NULL,
    embedding_eu_only boolean DEFAULT true NOT NULL,
    text_eu_only boolean DEFAULT true NOT NULL,
    zero_data_retention boolean DEFAULT true NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    transcription_model text,
    speech_model text,
    speech_voice text,
    image_model text,
    image_provider text,
    image_base_url text,
    image_api_key_encrypted text,
    image_api_key_hint text,
    image_quality text,
    live_model text,
    live_voice text,
    live_provider text,
    live_base_url text,
    live_api_key_encrypted text,
    live_api_key_hint text,
    vision_model text,
    image_edit_model text,
    CONSTRAINT ai_providers_base_url CHECK (((provider = 'custom'::text) = (base_url IS NOT NULL))),
    CONSTRAINT ai_providers_image_base_url CHECK (((NOT (image_provider IS DISTINCT FROM 'custom'::text)) = (image_base_url IS NOT NULL))),
    CONSTRAINT ai_providers_image_key CHECK ((((image_provider IS NULL) = (image_api_key_encrypted IS NULL)) AND ((image_api_key_encrypted IS NULL) = (image_api_key_hint IS NULL)))),
    CONSTRAINT ai_providers_image_model CHECK (COALESCE(((length(image_model) >= 1) AND (length(image_model) <= 200)), true)),
    CONSTRAINT ai_providers_image_provider CHECK (COALESCE((image_provider = ANY (ARRAY['gateway'::text, 'mistral'::text, 'openai'::text, 'openai_eu'::text, 'google'::text, 'custom'::text])), true)),
    CONSTRAINT ai_providers_image_quality CHECK (COALESCE((image_quality = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'auto'::text])), true)),
    CONSTRAINT ai_providers_live_base_url CHECK (((NOT (live_provider IS DISTINCT FROM 'custom'::text)) = (live_base_url IS NOT NULL))),
    CONSTRAINT ai_providers_live_key CHECK ((((live_provider IS NULL) = (live_api_key_encrypted IS NULL)) AND ((live_api_key_encrypted IS NULL) = (live_api_key_hint IS NULL)))),
    CONSTRAINT ai_providers_live_model CHECK ((COALESCE(((length(live_model) >= 1) AND (length(live_model) <= 200)), true) AND COALESCE(((length(live_voice) >= 1) AND (length(live_voice) <= 100)), true))),
    CONSTRAINT ai_providers_live_provider CHECK (COALESCE((live_provider = ANY (ARRAY['gateway'::text, 'mistral'::text, 'openai'::text, 'openai_eu'::text, 'google'::text, 'custom'::text])), true)),
    CONSTRAINT ai_providers_min_similarity CHECK (((min_similarity >= (0)::double precision) AND (min_similarity <= (1)::double precision))),
    CONSTRAINT ai_providers_models CHECK ((COALESCE(((length(embedding_model) >= 1) AND (length(embedding_model) <= 200)), true) AND COALESCE(((length(text_model) >= 1) AND (length(text_model) <= 200)), true))),
    CONSTRAINT ai_providers_provider CHECK ((provider = ANY (ARRAY['gateway'::text, 'mistral'::text, 'openai'::text, 'openai_eu'::text, 'google'::text, 'custom'::text]))),
    CONSTRAINT ai_providers_vision_model CHECK (COALESCE(((length(vision_model) >= 1) AND (length(vision_model) <= 200)), true)),
    CONSTRAINT ai_providers_voice_models CHECK ((COALESCE(((length(transcription_model) >= 1) AND (length(transcription_model) <= 200)), true) AND COALESCE(((length(speech_model) >= 1) AND (length(speech_model) <= 200)), true) AND COALESCE(((length(speech_voice) >= 1) AND (length(speech_voice) <= 100)), true)))
);


