    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT analytics_settings_amounts CHECK (((payment_fee_fixed_minor >= 0) AND (shipping_cost_minor >= 0) AND (fixed_costs_monthly_minor >= 0))),
