--
-- Name: analytics_targets; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.analytics_targets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    month date,
    revenue_target_minor bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    metric text DEFAULT 'net_sales'::text NOT NULL,
    period text DEFAULT 'month'::text NOT NULL,
    starts_on date NOT NULL,
    ends_on date NOT NULL,
    target_value bigint NOT NULL,
    CONSTRAINT analytics_targets_amount CHECK (((revenue_target_minor IS NULL) OR (revenue_target_minor > 0))),
    CONSTRAINT analytics_targets_bounds CHECK (((ends_on >= starts_on) AND (ends_on <= (starts_on + 730)) AND
CASE period
    WHEN 'week'::text THEN ((EXTRACT(isodow FROM starts_on) = (1)::numeric) AND (ends_on = (starts_on + 6)))
    WHEN 'month'::text THEN ((starts_on = (date_trunc('month'::text, (starts_on)::timestamp without time zone))::date) AND (ends_on = ((date_trunc('month'::text, (starts_on)::timestamp without time zone) + '1 mon -1 days'::interval))::date))
    WHEN 'quarter'::text THEN ((starts_on = (date_trunc('quarter'::text, (starts_on)::timestamp without time zone))::date) AND (ends_on = ((date_trunc('quarter'::text, (starts_on)::timestamp without time zone) + '3 mons -1 days'::interval))::date))
    ELSE true
END)),
    CONSTRAINT analytics_targets_first_form CHECK ((((month IS NULL) = (revenue_target_minor IS NULL)) AND ((month IS NULL) OR ((metric = 'net_sales'::text) AND (period = 'month'::text) AND (month = starts_on) AND (revenue_target_minor = target_value))))),
    CONSTRAINT analytics_targets_first_of_month CHECK (((month IS NULL) OR (month = (date_trunc('month'::text, (month)::timestamp without time zone))::date))),
    CONSTRAINT analytics_targets_metric CHECK ((metric = ANY (ARRAY['net_sales'::text, 'orders'::text, 'conversion'::text, 'aov'::text]))),
    CONSTRAINT analytics_targets_period CHECK ((period = ANY (ARRAY['week'::text, 'month'::text, 'quarter'::text, 'custom'::text]))),
    CONSTRAINT analytics_targets_value CHECK (((target_value > 0) AND ((metric <> 'conversion'::text) OR (target_value <= 10000))))
);


