-- Name: automations; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.automations (
    store_id uuid NOT NULL,
    kind text NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    enabled_at timestamp with time zone,
    delay_days integer,
    content jsonb,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT automations_content CHECK (((kind = 'back_in_stock'::text) = (content IS NULL))),
    CONSTRAINT automations_delay CHECK (
CASE kind
    WHEN 'welcome'::text THEN ((delay_days >= 0) AND (delay_days <= 30))
    WHEN 'after_purchase'::text THEN ((delay_days >= 1) AND (delay_days <= 90))
    WHEN 'win_back'::text THEN ((delay_days >= 30) AND (delay_days <= 730))
    ELSE (delay_days IS NULL)
END),
    CONSTRAINT automations_enabled_at CHECK (((NOT enabled) OR (enabled_at IS NOT NULL))),
    CONSTRAINT automations_kind CHECK ((kind = ANY (ARRAY['welcome'::text, 'after_purchase'::text, 'win_back'::text, 'back_in_stock'::text])))
);


