    backorder_quantity integer DEFAULT 0 NOT NULL,
    order_edit_id uuid,
    CONSTRAINT inventory_reservations_backorder_within CHECK (((backorder_quantity >= 0) AND (backorder_quantity <= quantity))),
    CONSTRAINT inventory_reservations_order_edit CHECK (((order_edit_id IS NULL) OR (order_id IS NOT NULL))),
