    CONSTRAINT inventory_reservations_quantity_positive CHECK ((quantity > 0))
);


--
-- Name: available_stock; Type: VIEW; Schema: commerce; Owner: -
--

CREATE VIEW commerce.available_stock WITH (security_invoker='true') AS
 SELECT store_id,
    variant_id,
    location_id,
    on_hand,
    (on_hand - COALESCE(( SELECT sum(r.quantity) AS sum
           FROM commerce.inventory_reservations r
          WHERE ((r.variant_id = l.variant_id) AND (r.location_id = l.location_id) AND (r.released_at IS NULL) AND (r.expires_at > now()))), (0)::bigint)) AS available
   FROM commerce.inventory_levels l;


