--
-- Name: campaigns; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.campaigns (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    name text NOT NULL,
    kind text NOT NULL,
    percent integer DEFAULT 0 NOT NULL,
    buy_quantity integer DEFAULT 0 NOT NULL,
    pay_quantity integer DEFAULT 0 NOT NULL,
    gift_variant_id uuid,
    gift_quantity integer DEFAULT 1 NOT NULL,
    thresholds jsonb DEFAULT '{}'::jsonb NOT NULL,
    product_ids jsonb DEFAULT '[]'::jsonb NOT NULL,
    term_ids jsonb DEFAULT '[]'::jsonb NOT NULL,
    starts_at timestamp with time zone,
    ends_at timestamp with time zone,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    tier_ids jsonb DEFAULT '[]'::jsonb NOT NULL,
    usage_limit integer,
    stacks boolean DEFAULT false NOT NULL,
    per_customer_limit integer,
    markets jsonb DEFAULT '[]'::jsonb NOT NULL,
    amounts jsonb DEFAULT '{}'::jsonb NOT NULL,
    tier_basis text,
    tiers jsonb DEFAULT '[]'::jsonb NOT NULL,
    buy_min_quantity integer,
    buy_min_amounts jsonb DEFAULT '{}'::jsonb NOT NULL,
    get_product_ids jsonb DEFAULT '[]'::jsonb NOT NULL,
    get_term_ids jsonb DEFAULT '[]'::jsonb NOT NULL,
    get_quantity integer DEFAULT 0 NOT NULL,
    get_kind text,
    get_percent integer,
    get_amounts jsonb DEFAULT '{}'::jsonb NOT NULL,
    uses_per_order integer,
    combines_with_codes boolean DEFAULT true NOT NULL,
    segment_id uuid,
    CONSTRAINT campaigns_amounts CHECK (((jsonb_typeof(amounts) = 'object'::text) AND ((kind = 'amount'::text) OR (amounts = '{}'::jsonb)))),
    CONSTRAINT campaigns_bxgy CHECK (COALESCE(((jsonb_typeof(buy_min_amounts) = 'object'::text) AND (jsonb_typeof(get_product_ids) = 'array'::text) AND (jsonb_typeof(get_term_ids) = 'array'::text) AND (jsonb_typeof(get_amounts) = 'object'::text) AND (((kind = 'bxgy'::text) AND ((((buy_min_quantity >= 1) AND (buy_min_quantity <= 100)) AND (buy_min_amounts = '{}'::jsonb)) OR ((buy_min_quantity IS NULL) AND (buy_min_amounts <> '{}'::jsonb))) AND ((get_quantity >= 1) AND (get_quantity <= 20)) AND (((get_kind = 'free'::text) AND (get_percent IS NULL) AND (get_amounts = '{}'::jsonb)) OR ((get_kind = 'percent'::text) AND ((get_percent >= 1) AND (get_percent <= 100)) AND (get_amounts = '{}'::jsonb)) OR ((get_kind = 'amount'::text) AND (get_percent IS NULL) AND (get_amounts <> '{}'::jsonb))) AND ((uses_per_order IS NULL) OR ((uses_per_order >= 1) AND (uses_per_order <= 100)))) OR ((kind <> 'bxgy'::text) AND (buy_min_quantity IS NULL) AND (buy_min_amounts = '{}'::jsonb) AND (get_product_ids = '[]'::jsonb) AND (get_term_ids = '[]'::jsonb) AND (get_quantity = 0) AND (get_kind IS NULL) AND (get_percent IS NULL) AND (get_amounts = '{}'::jsonb) AND (uses_per_order IS NULL)))), false)),
    CONSTRAINT campaigns_dates CHECK (((starts_at IS NULL) OR (ends_at IS NULL) OR (starts_at < ends_at))),
    CONSTRAINT campaigns_gift CHECK ((((kind = 'gift'::text) AND (gift_variant_id IS NOT NULL) AND ((gift_quantity >= 1) AND (gift_quantity <= 5))) OR ((kind <> 'gift'::text) AND (gift_variant_id IS NULL)))),
    CONSTRAINT campaigns_kind CHECK ((kind = ANY (ARRAY['percent'::text, 'multi_buy'::text, 'gift'::text, 'amount'::text, 'free_shipping'::text, 'tiered'::text, 'bxgy'::text]))),
    CONSTRAINT campaigns_multi_buy CHECK ((((kind = 'multi_buy'::text) AND ((buy_quantity >= 2) AND (buy_quantity <= 20)) AND ((pay_quantity >= 1) AND (pay_quantity <= (buy_quantity - 1)))) OR ((kind <> 'multi_buy'::text) AND (buy_quantity = 0) AND (pay_quantity = 0)))),
    CONSTRAINT campaigns_per_customer_limit CHECK (((per_customer_limit IS NULL) OR (per_customer_limit > 0))),
    CONSTRAINT campaigns_percent CHECK ((((kind = 'percent'::text) AND ((percent >= 1) AND (percent <= 100))) OR ((kind <> 'percent'::text) AND (percent = 0)))),
    CONSTRAINT campaigns_stacks CHECK (((NOT stacks) OR (kind = ANY (ARRAY['percent'::text, 'multi_buy'::text, 'tiered'::text])))),
    CONSTRAINT campaigns_tiers CHECK (((jsonb_typeof(tiers) = 'array'::text) AND (((kind = 'tiered'::text) AND (tier_basis = ANY (ARRAY['quantity'::text, 'spend'::text])) AND ((jsonb_array_length(tiers) >= 2) AND (jsonb_array_length(tiers) <= 5))) OR ((kind <> 'tiered'::text) AND (tier_basis IS NULL) AND (tiers = '[]'::jsonb))))),
    CONSTRAINT campaigns_usage_limit CHECK (((usage_limit IS NULL) OR (usage_limit > 0)))
);


