--
-- Name: connected_accounts; Type: VIEW; Schema: commerce; Owner: -
--

CREATE VIEW commerce.connected_accounts WITH (security_invoker='true') AS
 SELECT stripe_accounts.store_id,
    stripe_accounts.mode,
    stripe_accounts.account_id,
    NULL::uuid AS host_id,
    stripe_accounts.card_payments
   FROM commerce.stripe_accounts
UNION ALL
 SELECT host_stripe_accounts.store_id,
    host_stripe_accounts.mode,
    host_stripe_accounts.account_id,
    host_stripe_accounts.host_id,
    host_stripe_accounts.card_payments
   FROM commerce.host_stripe_accounts;


