    CONSTRAINT content_reports_good_faith CHECK (good_faith),
    CONSTRAINT content_reports_sender CHECK (((source = 'screening'::text) OR (category = 'minors'::text) OR (status <> 'received'::text) OR ((reporter_name IS NOT NULL) AND (reporter_email IS NOT NULL)))),
    CONSTRAINT content_reports_source CHECK ((source = ANY (ARRAY['notice'::text, 'screening'::text]))),
    CONSTRAINT content_reports_status CHECK ((status = ANY (ARRAY['received'::text, 'actioned'::text, 'no_action'::text]))),
    CONSTRAINT content_reports_url CHECK (((url ~ '^https?://'::text) AND (char_length(url) <= 2000)))
);


