    CONSTRAINT creators_code CHECK (((code IS NULL) OR (code ~ '^[a-z0-9]{6,16}$'::text))),
    CONSTRAINT creators_commission CHECK (((commission_bps IS NULL) OR ((commission_bps >= 0) AND (commission_bps <= 5000)))),
    CONSTRAINT creators_name CHECK ((char_length(name) <= 80)),
