-- Name: credit_notes; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.credit_notes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    invoice_id uuid NOT NULL,
    refund_id uuid,
    series text NOT NULL,
    number bigint NOT NULL,
    document_number text NOT NULL,
    currency character(3) NOT NULL,
    total_minor bigint NOT NULL,
    tax_minor bigint NOT NULL,
    issued_at timestamp with time zone DEFAULT now() NOT NULL,
    source text NOT NULL,
    return_id uuid,
    issued_on date NOT NULL,
    locale text NOT NULL,
    net_minor bigint NOT NULL,
    vat_home_currency character(3),
    vat_home_minor bigint,
    fx_rate numeric(18,8),
    fx_as_of date,
    fx_source text,
    snapshot jsonb NOT NULL,
    public_token text,
    pdf_path text,
    pdf_sha256 text,
    anonymised_at timestamp with time zone,
    order_edit_id uuid,
    CONSTRAINT credit_notes_fx_source CHECK (((fx_source IS NULL) OR (fx_source = ANY (ARRAY['ecb_auto'::text, 'owner'::text])))),
    CONSTRAINT credit_notes_pdf CHECK (((pdf_path IS NULL) = (pdf_sha256 IS NULL))),
    CONSTRAINT credit_notes_public_token CHECK ((((anonymised_at IS NULL) AND (public_token ~ '^crn_[A-Za-z0-9_-]{43}$'::text)) OR ((anonymised_at IS NOT NULL) AND (public_token IS NULL)))),
    CONSTRAINT credit_notes_series CHECK ((series = 'credit_note'::text)),
    CONSTRAINT credit_notes_snapshot CHECK (((jsonb_typeof(snapshot) = 'object'::text) AND ((snapshot ->> 'version'::text) = '1'::text))),
    CONSTRAINT credit_notes_source CHECK ((source = ANY (ARRAY['refund'::text, 'return_outside'::text, 'order_edit'::text, 'return_exchange'::text]))),
    CONSTRAINT credit_notes_source_ref CHECK ((((source = 'refund'::text) AND (refund_id IS NOT NULL) AND (return_id IS NULL) AND (order_edit_id IS NULL)) OR ((source = ANY (ARRAY['return_outside'::text, 'return_exchange'::text])) AND (return_id IS NOT NULL) AND (refund_id IS NULL) AND (order_edit_id IS NULL)) OR ((source = 'order_edit'::text) AND (order_edit_id IS NOT NULL) AND (refund_id IS NULL) AND (return_id IS NULL)))),
    CONSTRAINT credit_notes_total CHECK (((total_minor > 0) AND (total_minor = (net_minor + tax_minor)))),
    CONSTRAINT credit_notes_vat_home CHECK ((((vat_home_minor IS NULL) = (fx_rate IS NULL)) AND ((vat_home_minor IS NULL) = (vat_home_currency IS NULL))))
);


