    CONSTRAINT prices_valid_range CHECK (((valid_to IS NULL) OR (valid_to > valid_from)))
);


--
-- Name: product_variants; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.product_variants (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    product_id uuid NOT NULL,
    sku text NOT NULL,
    gtin text,
    tax_code text,
    options jsonb DEFAULT '{}'::jsonb NOT NULL,
    weight_grams integer,
    hs_code text,
    origin_country character(2),
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    delivery commerce.delivery DEFAULT 'physical'::commerce.delivery NOT NULL,
    rental_period text DEFAULT 'day'::text NOT NULL,
    image_url text,
    image_thumbnail_url text,
    cost_minor bigint,
    measure_amount numeric(12,4),
    measure_unit text,
    measure_base text,
    stock_policy text DEFAULT 'deny'::text NOT NULL,
    backorder_days integer,
    low_stock_threshold integer,
    min_quantity integer DEFAULT 1 NOT NULL,
    max_quantity integer,
    quantity_step integer DEFAULT 1 NOT NULL,
    preorder_until date,
    supplier_id uuid,
    CONSTRAINT product_variants_backorder_days CHECK (((backorder_days >= 1) AND (backorder_days <= 90))),
    CONSTRAINT product_variants_backorder_days_policy CHECK (((stock_policy = 'continue'::text) = (backorder_days IS NOT NULL))),
    CONSTRAINT product_variants_cost_minor CHECK ((cost_minor >= 0)),
    CONSTRAINT product_variants_gtin_digits CHECK ((gtin ~ '^[0-9]{8,14}$'::text)),
    CONSTRAINT product_variants_hs_code_digits CHECK ((hs_code ~ '^[0-9]{6,10}$'::text)),
    CONSTRAINT product_variants_image CHECK (((image_thumbnail_url IS NULL) OR (image_url IS NOT NULL))),
    CONSTRAINT product_variants_low_stock_threshold CHECK (((low_stock_threshold IS NULL) OR (((low_stock_threshold >= 0) AND (low_stock_threshold <= 1000000)) AND (delivery = 'physical'::commerce.delivery)))),
    CONSTRAINT product_variants_measure_amount CHECK (((measure_amount > (0)::numeric) AND (measure_amount <= (1000000)::numeric))),
    CONSTRAINT product_variants_measure_base CHECK (((measure_base IS NULL) OR ((measure_amount IS NOT NULL) AND (((measure_unit = ANY (ARRAY['g'::text, 'kg'::text])) AND (measure_base = ANY (ARRAY['kg'::text, '100g'::text]))) OR ((measure_unit = ANY (ARRAY['ml'::text, 'cl'::text, 'l'::text])) AND (measure_base = ANY (ARRAY['l'::text, '100ml'::text]))) OR ((measure_unit = ANY (ARRAY['cm'::text, 'm'::text])) AND (measure_base = 'm'::text)) OR ((measure_unit = 'm2'::text) AND (measure_base = 'm2'::text)) OR ((measure_unit = 'piece'::text) AND (measure_base = 'piece'::text)))))),
    CONSTRAINT product_variants_measure_pair CHECK (((measure_amount IS NULL) = (measure_unit IS NULL))),
    CONSTRAINT product_variants_measure_unit CHECK ((measure_unit = ANY (ARRAY['g'::text, 'kg'::text, 'ml'::text, 'cl'::text, 'l'::text, 'cm'::text, 'm'::text, 'm2'::text, 'piece'::text]))),
    CONSTRAINT product_variants_preorder CHECK (((preorder_until IS NULL) OR (stock_policy = 'continue'::text))),
    CONSTRAINT product_variants_quantity_max CHECK (((max_quantity IS NULL) OR (((max_quantity >= min_quantity) AND (max_quantity <= 9999)) AND ((max_quantity % quantity_step) = 0)))),
    CONSTRAINT product_variants_quantity_rule CHECK ((((min_quantity >= 1) AND (min_quantity <= 9999)) AND ((quantity_step >= 1) AND (quantity_step <= 9999)) AND ((min_quantity % quantity_step) = 0))),
    CONSTRAINT product_variants_rental_period CHECK ((rental_period = ANY (ARRAY['day'::text, 'half_day'::text, 'hour'::text]))),
    CONSTRAINT product_variants_stock_policy CHECK ((stock_policy = ANY (ARRAY['deny'::text, 'continue'::text]))),
    CONSTRAINT product_variants_stock_policy_goods CHECK (((stock_policy = 'deny'::text) OR (delivery = 'physical'::commerce.delivery))),
    CONSTRAINT product_variants_supplier_goods CHECK (((supplier_id IS NULL) OR (delivery = 'physical'::commerce.delivery))),
    CONSTRAINT product_variants_weight_positive CHECK ((weight_grams > 0))
);


--
-- Name: current_prices; Type: VIEW; Schema: commerce; Owner: -
--

CREATE VIEW commerce.current_prices WITH (security_invoker='true') AS
 SELECT store_id,
    variant_id,
    market_code,
    currency,
    amount_minor,
    valid_from,
    commerce.prior_price(variant_id, market_code, valid_from) AS prior_30d_minor
   FROM commerce.prices p
  WHERE ((valid_to IS NULL) AND (NOT (EXISTS ( SELECT 1
           FROM (commerce.product_variants v
             JOIN commerce.market_availability a ON (((a.store_id = v.store_id) AND (a.product_id = v.product_id) AND (a.market_code = p.market_code) AND ((a.variant_id IS NULL) OR (a.variant_id = v.id)))))
          WHERE (v.id = p.variant_id)))) AND (NOT (EXISTS ( SELECT 1
           FROM ((commerce.bundle_components bc
             JOIN commerce.product_variants cv ON ((cv.id = bc.component_variant_id)))
             JOIN commerce.market_availability a ON (((a.store_id = cv.store_id) AND (a.product_id = cv.product_id) AND (a.market_code = p.market_code) AND ((a.variant_id IS NULL) OR (a.variant_id = cv.id)))))
          WHERE (bc.bundle_variant_id = p.variant_id)))));


