    input_path text,
    input_name text,
    input_bytes integer,
    input_sha256 text,
    rows_total integer,
    rows_done integer,
    counts jsonb DEFAULT '{}'::jsonb NOT NULL,
    cursor jsonb DEFAULT '{}'::jsonb NOT NULL,
