    expires_at timestamp with time zone,
    purged_at timestamp with time zone,
    CONSTRAINT data_jobs_attempts CHECK ((attempts >= 0)),
    CONSTRAINT data_jobs_export_no_input CHECK (((kind = ANY (ARRAY['product_import'::text, 'redirect_import'::text, 'inventory_import'::text, 'customer_import'::text, 'order_history_import'::text])) OR ((input_path IS NULL) AND (input_sha256 IS NULL) AND (format IS DISTINCT FROM 'shopify'::text)))),
    CONSTRAINT data_jobs_finished CHECK (((status <> ALL (ARRAY['done'::text, 'failed'::text, 'cancelled'::text, 'expired'::text])) OR (finished_at IS NOT NULL))),
    CONSTRAINT data_jobs_format CHECK (((format IS NULL) OR (format = ANY (ARRAY['kaizen'::text, 'shopify'::text, 'woocommerce'::text])))),
    CONSTRAINT data_jobs_import_no_files CHECK (((kind <> ALL (ARRAY['product_import'::text, 'redirect_import'::text, 'inventory_import'::text, 'customer_import'::text, 'order_history_import'::text])) OR (files = '[]'::jsonb))),
    CONSTRAINT data_jobs_input_bytes CHECK (((input_bytes IS NULL) OR ((input_bytes >= 0) AND (input_bytes <= 15728640)))),
    CONSTRAINT data_jobs_input_sha256 CHECK (((input_sha256 IS NULL) OR (input_sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT data_jobs_json CHECK (((jsonb_typeof(options) = 'object'::text) AND (jsonb_typeof(counts) = 'object'::text) AND (jsonb_typeof(cursor) = 'object'::text) AND (jsonb_typeof(files) = 'array'::text))),
    CONSTRAINT data_jobs_kind CHECK ((kind = ANY (ARRAY['product_import'::text, 'product_export'::text, 'order_export'::text, 'customer_export'::text, 'redirect_import'::text, 'redirect_export'::text, 'inventory_import'::text, 'inventory_export'::text, 'customer_import'::text, 'order_history_import'::text]))),
    CONSTRAINT data_jobs_phase CHECK (((phase IS NULL) OR (phase = ANY (ARRAY['check'::text, 'apply'::text, 'write'::text, 'assemble'::text])))),
    CONSTRAINT data_jobs_problem CHECK (((problem IS NULL) OR (length(problem) <= 500))),
    CONSTRAINT data_jobs_rows CHECK (((rows_total IS NULL) OR (rows_total >= 0))),
    CONSTRAINT data_jobs_rows_done CHECK (((rows_done IS NULL) OR ((rows_done >= 0) AND ((rows_total IS NULL) OR (rows_done <= rows_total))))),
    CONSTRAINT data_jobs_status CHECK ((status = ANY (ARRAY['uploaded'::text, 'checking'::text, 'checked'::text, 'queued'::text, 'running'::text, 'done'::text, 'failed'::text, 'cancelled'::text, 'expired'::text])))
);


