--

CREATE TABLE commerce.discount_codes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    code text NOT NULL,
    kind text NOT NULL,
    percent integer DEFAULT 0 NOT NULL,
    amounts jsonb DEFAULT '{}'::jsonb NOT NULL,
