    product_ids jsonb,
    recurring boolean DEFAULT false NOT NULL,
    starts_at timestamp with time zone,
    ends_at timestamp with time zone,
    usage_limit integer,
    once_per_customer boolean DEFAULT false NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    term_ids jsonb DEFAULT '[]'::jsonb NOT NULL,
    min_quantity integer,
    tier_ids jsonb DEFAULT '[]'::jsonb NOT NULL,
    customer_ids jsonb DEFAULT '[]'::jsonb NOT NULL,
    unique_codes boolean DEFAULT false NOT NULL,
    combines_with jsonb DEFAULT '[]'::jsonb NOT NULL,
    combines_with_campaigns boolean DEFAULT true NOT NULL,
    segment_id uuid,
    reward boolean DEFAULT false NOT NULL,
    max_units integer,
    CONSTRAINT discount_codes_combines_with CHECK (((jsonb_typeof(combines_with) = 'array'::text) AND (combines_with <@ '["products", "order", "shipping"]'::jsonb))),
    CONSTRAINT discount_codes_customer_ids CHECK (((jsonb_typeof(customer_ids) = 'array'::text) AND (jsonb_array_length(customer_ids) <= 100))),
    CONSTRAINT discount_codes_dates CHECK (((starts_at IS NULL) OR (ends_at IS NULL) OR (starts_at < ends_at))),
    CONSTRAINT discount_codes_json_shapes CHECK (((jsonb_typeof(amounts) = 'object'::text) AND (jsonb_typeof(min_subtotals) = 'object'::text) AND ((product_ids IS NULL) OR (jsonb_typeof(product_ids) = 'array'::text)))),
    CONSTRAINT discount_codes_kind CHECK ((kind = ANY (ARRAY['percent'::text, 'fixed'::text, 'free_shipping'::text]))),
    CONSTRAINT discount_codes_max_units CHECK (((max_units IS NULL) OR (((max_units >= 1) AND (max_units <= 100)) AND reward))),
    CONSTRAINT discount_codes_min_quantity CHECK (((min_quantity IS NULL) OR ((min_quantity >= 1) AND (min_quantity <= 1000)))),
    CONSTRAINT discount_codes_percent CHECK ((((kind = 'percent'::text) AND ((percent >= 1) AND (percent <= 100))) OR ((kind <> 'percent'::text) AND (percent = 0)))),
    CONSTRAINT discount_codes_recurring CHECK (((NOT recurring) OR (kind = 'percent'::text))),
    CONSTRAINT discount_codes_term_ids CHECK ((jsonb_typeof(term_ids) = 'array'::text)),
    CONSTRAINT discount_codes_tier_ids CHECK ((jsonb_typeof(tier_ids) = 'array'::text)),
    CONSTRAINT discount_codes_upper CHECK ((code = upper(code))),
    CONSTRAINT discount_codes_usage_limit CHECK (((usage_limit IS NULL) OR (usage_limit > 0)))
);


