--
-- Name: docs_index; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.docs_index (
    id bigint NOT NULL,
    key text NOT NULL,
    doc text NOT NULL,
    item text NOT NULL,
    track text NOT NULL,
    kind text NOT NULL,
    lang text NOT NULL,
    areas text[] NOT NULL,
    features text[] DEFAULT '{}'::text[] NOT NULL,
    plans text[] DEFAULT '{}'::text[] NOT NULL,
    section text,
    section_title text,
    path text,
    url text NOT NULL,
    title text NOT NULL,
    headings text DEFAULT ''::text NOT NULL,
    code text,
    summary text NOT NULL,
    text text NOT NULL,
    "position" integer NOT NULL,
    reading integer NOT NULL,
    checked date,
    text_hash text NOT NULL,
    search tsvector GENERATED ALWAYS AS (((setweight(to_tsvector(commerce.search_config(lang), title), 'A'::"char") || setweight(to_tsvector(commerce.search_config(lang), ((headings || ' '::text) || COALESCE(code, ''::text))), 'B'::"char")) || setweight(to_tsvector(commerce.search_config(lang), text), 'C'::"char"))) STORED,
    words tsvector GENERATED ALWAYS AS (((setweight(to_tsvector('simple'::regconfig, title), 'A'::"char") || setweight(to_tsvector('simple'::regconfig, ((headings || ' '::text) || COALESCE(code, ''::text))), 'B'::"char")) || setweight(to_tsvector('simple'::regconfig, text), 'C'::"char"))) STORED,
    trgm text GENERATED ALWAYS AS (lower(((((title || ' '::text) || headings) || ' '::text) || COALESCE(code, ''::text)))) STORED,
    space text,
    embedding extensions.vector,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT docs_index_areas_check CHECK (((cardinality(areas) >= 1) AND (cardinality(areas) <= 20))),
    CONSTRAINT docs_index_doc_check CHECK (((char_length(doc) >= 3) AND (char_length(doc) <= 400))),
    CONSTRAINT docs_index_embedded CHECK (((space IS NULL) = (embedding IS NULL))),
    CONSTRAINT docs_index_item_check CHECK ((item = ANY (ARRAY['section'::text, 'changelog'::text, 'operation'::text, 'topic'::text, 'tool'::text, 'agent-tool'::text, 'error'::text, 'scope'::text]))),
    CONSTRAINT docs_index_key_check CHECK (((char_length(key) >= 3) AND (char_length(key) <= 400))),
    CONSTRAINT docs_index_kind_check CHECK ((kind = ANY (ARRAY['tutorial'::text, 'how-to'::text, 'concept'::text, 'reference'::text, 'troubleshooting'::text, 'changelog'::text]))),
    CONSTRAINT docs_index_lang_check CHECK ((lang = ANY (ARRAY['en'::text, 'nb'::text]))),
    CONSTRAINT docs_index_path_check CHECK (((path IS NULL) OR (path ~ '^[a-z0-9][a-z0-9-]*(/[a-z0-9][a-z0-9-]*){0,4}$'::text))),
    CONSTRAINT docs_index_position_check CHECK (("position" >= 0)),
    CONSTRAINT docs_index_reading_check CHECK ((reading >= 0)),
    CONSTRAINT docs_index_section_check CHECK (((section IS NULL) OR (section ~ '^(owners|developers)/[a-z0-9][a-z0-9-]*$'::text))),
    CONSTRAINT docs_index_space_check CHECK (((space IS NULL) OR ((char_length(space) >= 1) AND (char_length(space) <= 400)))),
    CONSTRAINT docs_index_text_check CHECK ((char_length(text) <= 4000)),
    CONSTRAINT docs_index_title_check CHECK (((char_length(title) >= 1) AND (char_length(title) <= 300))),
    CONSTRAINT docs_index_track_check CHECK ((track = ANY (ARRAY['owners'::text, 'developers'::text]))),
    CONSTRAINT docs_index_url_check CHECK (((url ~ '^[a-z0-9][a-z0-9-]*(/[a-z0-9][a-z0-9-]*){0,4}(#[a-z0-9][a-z0-9-]*)?$'::text) AND (char_length(url) <= 400)))
);


