    CONSTRAINT domain_purchases_status CHECK ((status = ANY (ARRAY['quoted'::text, 'invoiced'::text, 'paid'::text, 'registering'::text, 'done'::text, 'failed'::text, 'refunded'::text, 'void'::text]))),
    CONSTRAINT domain_purchases_vat_kind CHECK (((vat_kind IS NULL) OR (vat_kind = ANY (ARRAY['mva'::text, 'reverse_charge'::text, 'outside_scope'::text])))),
    CONSTRAINT domain_purchases_years CHECK (((years >= 1) AND (years <= 10)))
);


