    CONSTRAINT draft_order_lines_position CHECK (("position" >= 0)),
    CONSTRAINT draft_order_lines_price_requested CHECK (((NOT price_requested) OR ((variant_id IS NOT NULL) AND (unit_price_minor = 0)))),
    CONSTRAINT draft_order_lines_prices CHECK (((unit_price_minor >= 0) AND ((list_price_minor IS NULL) OR (list_price_minor >= 0)))),
    CONSTRAINT draft_order_lines_quantity CHECK (((quantity >= 1) AND (quantity <= 9999))),
    CONSTRAINT draft_order_lines_title CHECK (((char_length(title) >= 1) AND (char_length(title) <= 200)))
