--
-- Name: draft_orders; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.draft_orders (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    number text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    market_code character(2) NOT NULL,
    market_slug text NOT NULL,
    currency character(3) NOT NULL,
    locale text NOT NULL,
    customer_id uuid,
    email text,
    phone text,
    shipping_address jsonb DEFAULT '{}'::jsonb NOT NULL,
    billing_address jsonb DEFAULT '{}'::jsonb NOT NULL,
    company_name text,
    organisation_number text,
    note_to_buyer text,
    internal_note text,
    tags jsonb DEFAULT '[]'::jsonb NOT NULL,
    discount_kind text,
    discount_value bigint,
    discount_label text,
    shipping_kind text DEFAULT 'rate'::text NOT NULL,
    shipping_minor bigint,
    valid_days integer,
    order_id uuid,
    sent_at timestamp with time zone,
    expires_at timestamp with time zone,
    paid_at timestamp with time zone,
    pay_token_hash text,
    pay_sends_today integer DEFAULT 0 NOT NULL,
    pay_sent_on date,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    edited_at timestamp with time zone DEFAULT now() NOT NULL,
    source text DEFAULT 'staff'::text NOT NULL,
    request_note text,
    quote_declined_at timestamp with time zone,
    quote_reply text,
    request_company text,
    CONSTRAINT draft_orders_addresses CHECK (((jsonb_typeof(shipping_address) = 'object'::text) AND (jsonb_typeof(billing_address) = 'object'::text))),
    CONSTRAINT draft_orders_discount CHECK ((((discount_kind IS NULL) = (discount_value IS NULL)) AND ((discount_kind IS NULL) = (discount_label IS NULL)) AND ((discount_kind IS NULL) OR (discount_kind = ANY (ARRAY['percent'::text, 'amount'::text]))) AND ((discount_kind IS DISTINCT FROM 'percent'::text) OR ((discount_value >= 1) AND (discount_value <= 10000))) AND ((discount_kind IS DISTINCT FROM 'amount'::text) OR (discount_value > 0)) AND ((discount_label IS NULL) OR ((char_length(discount_label) >= 1) AND (char_length(discount_label) <= 60))))),
    CONSTRAINT draft_orders_email CHECK (((email IS NULL) OR (char_length(email) <= 254))),
    CONSTRAINT draft_orders_lifecycle CHECK ((((status = 'open'::text) AND (order_id IS NULL) AND (sent_at IS NULL) AND (expires_at IS NULL) AND (paid_at IS NULL) AND (pay_token_hash IS NULL)) OR ((status = ANY (ARRAY['sent'::text, 'expired'::text, 'cancelled'::text])) AND (order_id IS NOT NULL) AND (sent_at IS NOT NULL) AND (expires_at IS NOT NULL) AND (expires_at > sent_at) AND (paid_at IS NULL)) OR ((status = 'paid'::text) AND (order_id IS NOT NULL) AND (sent_at IS NOT NULL) AND (expires_at IS NOT NULL) AND (paid_at IS NOT NULL)))),
    CONSTRAINT draft_orders_notes CHECK (((char_length(note_to_buyer) <= 500) AND (char_length(internal_note) <= 1000))),
    CONSTRAINT draft_orders_number CHECK ((number ~ '^D-[0-9]+$'::text)),
    CONSTRAINT draft_orders_pay_sends CHECK ((pay_sends_today >= 0)),
    CONSTRAINT draft_orders_quote CHECK ((((source = 'quote'::text) OR ((request_note IS NULL) AND (quote_declined_at IS NULL))) AND ((quote_reply IS NULL) OR (quote_declined_at IS NOT NULL)) AND ((quote_declined_at IS NULL) OR (status = 'open'::text)) AND (char_length(request_note) <= 2000) AND (char_length(quote_reply) <= 1000))),
    CONSTRAINT draft_orders_request_company CHECK (((request_company IS NULL) OR ((source = 'quote'::text) AND (char_length(request_company) <= 120)))),
    CONSTRAINT draft_orders_shipping CHECK (((shipping_kind = ANY (ARRAY['rate'::text, 'free'::text, 'custom'::text])) AND ((shipping_kind = 'custom'::text) = (shipping_minor IS NOT NULL)) AND ((shipping_minor IS NULL) OR (shipping_minor >= 0)))),
    CONSTRAINT draft_orders_source CHECK ((source = ANY (ARRAY['staff'::text, 'quote'::text]))),
    CONSTRAINT draft_orders_status CHECK ((status = ANY (ARRAY['open'::text, 'sent'::text, 'paid'::text, 'expired'::text, 'cancelled'::text]))),
    CONSTRAINT draft_orders_tags CHECK (((jsonb_typeof(tags) = 'array'::text) AND (jsonb_array_length(tags) <= 250))),
    CONSTRAINT draft_orders_valid_days CHECK (((valid_days IS NULL) OR ((valid_days >= 1) AND (valid_days <= 30)))),
    CONSTRAINT draft_orders_version CHECK ((version >= 1))
);


