    CONSTRAINT duty_rates_applies_to CHECK ((applies_to = ANY (ARRAY['any'::text, 'scheme'::text, 'no_scheme'::text]))),
    CONSTRAINT duty_rates_base_origin CHECK (((hs_prefix <> ''::text) OR (origin IS NULL))),
    CONSTRAINT duty_rates_currency CHECK ((((threshold_minor IS NULL) AND (vat_threshold_minor IS NULL) AND (per_item_minor IS NULL)) OR ((threshold_currency IS NOT NULL) AND (threshold_currency ~ '^[A-Z]{3}$'::text)))),
    CONSTRAINT duty_rates_destination CHECK ((destination ~ '^[A-Z]{2}$'::text)),
    CONSTRAINT duty_rates_heading_row CHECK (((hs_prefix = ''::text) OR ((duty_rate_bps IS NOT NULL) AND (threshold_minor IS NULL) AND (vat_threshold_minor IS NULL) AND (per_item_minor IS NULL)))),
    CONSTRAINT duty_rates_import_vat CHECK (((import_vat_bps IS NULL) OR ((import_vat_bps >= 0) AND (import_vat_bps <= 10000)))),
    CONSTRAINT duty_rates_origin CHECK (((origin IS NULL) OR (origin ~ '^[A-Z]{2}$'::text))),
    CONSTRAINT duty_rates_period CHECK (((valid_from IS NULL) OR (valid_to IS NULL) OR (valid_to >= valid_from))),
    CONSTRAINT duty_rates_prefix CHECK ((hs_prefix ~ '^[0-9]{0,10}$'::text)),
    CONSTRAINT duty_rates_rate CHECK (((duty_rate_bps IS NULL) OR ((duty_rate_bps >= 0) AND (duty_rate_bps <= 100000)))),
    CONSTRAINT duty_rates_source CHECK (((source ~ '^https://'::text) AND (length(source) <= 400))),
    CONSTRAINT duty_rates_threshold_per CHECK ((threshold_per = ANY (ARRAY['consignment'::text, 'item'::text])))
);


