    schedule_problem text,
    CONSTRAINT experiments_applied CHECK (((applied_variant IS NOT NULL) = (status = 'applied'::text))),
    CONSTRAINT experiments_goal CHECK ((primary_goal = ANY (ARRAY['orders'::text, 'revenue'::text, 'cart'::text, 'checkout'::text, 'click'::text, 'form'::text]))),
    CONSTRAINT experiments_minimums CHECK (((min_visitors >= 0) AND ((min_days >= 1) AND (min_days <= 90)))),
    CONSTRAINT experiments_name CHECK ((((length(name) >= 1) AND (length(name) <= 120)) AND (length(hypothesis) <= 500))),
