    CONSTRAINT experiments_scheduled CHECK (((status <> 'scheduled'::text) OR (scheduled_start IS NOT NULL))),
    CONSTRAINT experiments_status CHECK ((status = ANY (ARRAY['draft'::text, 'scheduled'::text, 'running'::text, 'stopped'::text, 'applied'::text, 'discarded'::text]))),
    CONSTRAINT experiments_stop_reason CHECK (((stop_reason IS NULL) OR (stop_reason = ANY (ARRAY['person'::text, 'guardrail'::text, 'planned_end'::text])))),
    CONSTRAINT experiments_traffic CHECK (((traffic_share > (0)::numeric) AND (traffic_share <= (1)::numeric)))
);


