    CONSTRAINT kaizen_life_handoffs_status CHECK ((status = ANY (ARRAY['working'::text, 'waiting_for_you'::text, 'done'::text, 'declined'::text, 'failed'::text, 'cancelled'::text, 'expired'::text]))),
    CONSTRAINT kaizen_life_handoffs_store CHECK (((direction = 'to_life'::text) OR (store_id IS NOT NULL))),
    CONSTRAINT kaizen_life_handoffs_task CHECK (((length(task) >= 1) AND (length(task) <= 4000)))
);


