--
-- Name: kept_prices; Type: VIEW; Schema: commerce; Owner: -
--

CREATE VIEW commerce.kept_prices WITH (security_invoker='true') AS
 SELECT store_id,
    variant_id,
    market_code,
    currency,
    amount_minor,
    valid_from,
    commerce.prior_price(variant_id, market_code, valid_from) AS prior_30d_minor,
    derived
   FROM commerce.prices p
  WHERE (valid_to IS NULL);


--
-- Name: knowledge_chunks; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.knowledge_chunks (
    id bigint NOT NULL,
    store_id uuid,
    document_id uuid,
    page_id uuid,
    locale text,
    "position" integer NOT NULL,
    title text NOT NULL,
    path text,
    body text NOT NULL,
    version text NOT NULL,
    search tsvector GENERATED ALWAYS AS ((setweight(to_tsvector(commerce.search_config(COALESCE(locale, ''::text)), title), 'A'::"char") || setweight(to_tsvector(commerce.search_config(COALESCE(locale, ''::text)), body), 'C'::"char"))) STORED,
    space text,
    embedding extensions.vector,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    entry_id uuid,
    CONSTRAINT knowledge_chunks_body_check CHECK (((length(body) >= 1) AND (length(body) <= 4000))),
    CONSTRAINT knowledge_chunks_embedded CHECK (((space IS NULL) = (embedding IS NULL))),
    CONSTRAINT knowledge_chunks_path_check CHECK (((path IS NULL) OR (path ~ '^/'::text))),
    CONSTRAINT knowledge_chunks_position_check CHECK (("position" >= 0)),
    CONSTRAINT knowledge_chunks_source CHECK ((num_nonnulls(document_id, page_id, entry_id) = 1)),
    CONSTRAINT knowledge_chunks_space_check CHECK (((space IS NULL) OR ((length(space) >= 1) AND (length(space) <= 400)))),
    CONSTRAINT knowledge_chunks_title_check CHECK ((length(title) <= 300))
);


