-- Name: media; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.media (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid,
    kind text NOT NULL,
    url text NOT NULL,
    thumbnail_url text,
    bucket text NOT NULL,
    path text NOT NULL,
    thumbnail_path text,
    file_name text NOT NULL,
    content_type text NOT NULL,
    size_bytes bigint DEFAULT 0 NOT NULL,
    width integer,
    height integer,
    alt text DEFAULT ''::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    alt_translations jsonb DEFAULT '{}'::jsonb NOT NULL,
    alt_source text,
    alt_written_at timestamp with time zone,
    alt_tried_at timestamp with time zone,
    search tsvector GENERATED ALWAYS AS (((setweight(to_tsvector('simple'::regconfig, regexp_replace(file_name, '[._-]+'::text, ' '::text, 'g'::text)), 'A'::"char") || setweight(to_tsvector('simple'::regconfig, alt), 'B'::"char")) || setweight(jsonb_to_tsvector('simple'::regconfig, alt_translations, '["string"]'::jsonb), 'C'::"char"))) STORED,
    compressed_at timestamp with time zone,
    made_by text DEFAULT 'person'::text NOT NULL,
    edited_from uuid,
    ai_marked_at timestamp with time zone,
    CONSTRAINT media_alt CHECK ((length(alt) <= 500)),
    CONSTRAINT media_alt_source CHECK ((alt_source = ANY (ARRAY['ai'::text, 'staff'::text]))),
    CONSTRAINT media_alt_translations CHECK ((jsonb_typeof(alt_translations) = 'object'::text)),
    CONSTRAINT media_alt_written CHECK (((alt_source IS NULL) = ((alt = ''::text) AND (alt_translations = '{}'::jsonb)))),
    CONSTRAINT media_dimensions CHECK ((((width IS NULL) AND (height IS NULL)) OR ((width IS NOT NULL) AND (height IS NOT NULL) AND (width > 0) AND (height > 0)))),
    CONSTRAINT media_edited CHECK (((made_by = 'ai_edited'::text) OR (edited_from IS NULL))),
    CONSTRAINT media_file_name CHECK (((length(TRIM(BOTH FROM file_name)) >= 1) AND (length(TRIM(BOTH FROM file_name)) <= 255))),
    CONSTRAINT media_kind CHECK ((kind = ANY (ARRAY['image'::text, 'video'::text, 'model'::text]))),
    CONSTRAINT media_made_by CHECK ((made_by = ANY (ARRAY['person'::text, 'ai_made'::text, 'ai_edited'::text]))),
    CONSTRAINT media_size CHECK ((size_bytes >= 0))
);


