--
-- Name: products; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.products (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    handle text NOT NULL,
    status commerce.product_status DEFAULT 'draft'::commerce.product_status NOT NULL,
    manufacturer_id uuid,
    responsible_person_id uuid,
    tax_code text NOT NULL,
    withdrawal_exclusion commerce.withdrawal_exclusion DEFAULT 'none'::commerce.withdrawal_exclusion NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    delivery commerce.delivery DEFAULT 'physical'::commerce.delivery NOT NULL,
    download_limit integer,
    download_days integer,
    subscription_only boolean DEFAULT false NOT NULL,
    audience text DEFAULT 'all'::text NOT NULL,
    vat_category text DEFAULT 'standard'::text NOT NULL,
    kind text DEFAULT 'goods'::text NOT NULL,
    host_id uuid,
    product_layout_id uuid,
    sold_by_measure boolean DEFAULT false NOT NULL,
    first_active_at timestamp with time zone,
    shipping_profile_id uuid,
    bundle_pricing text,
    bundle_percent_off integer,
    standard_category text,
    standard_attributes jsonb DEFAULT '{}'::jsonb NOT NULL,
    price_words jsonb,
    price_on_request boolean DEFAULT false NOT NULL,
    group_id uuid,
    group_value jsonb DEFAULT '{}'::jsonb NOT NULL,
    group_swatch text,
    group_position integer DEFAULT 0 NOT NULL,
    CONSTRAINT products_audience CHECK ((audience = ANY (ARRAY['all'::text, 'consumers'::text, 'businesses'::text]))),
    CONSTRAINT products_bundle_pricing CHECK ((((kind = 'bundle'::text) = (bundle_pricing IS NOT NULL)) AND ((bundle_pricing IS NULL) OR (bundle_pricing = ANY (ARRAY['fixed'::text, 'computed'::text]))) AND ((bundle_percent_off IS NULL) = (bundle_pricing IS DISTINCT FROM 'computed'::text)) AND ((bundle_percent_off IS NULL) OR ((bundle_percent_off >= 0) AND (bundle_percent_off <= 90))))),
    CONSTRAINT products_download_days_positive CHECK ((download_days > 0)),
    CONSTRAINT products_download_limit_positive CHECK ((download_limit > 0)),
    CONSTRAINT products_group_swatch CHECK (((group_swatch IS NULL) OR (group_swatch ~ '^#[0-9a-f]{6}$'::text))),
    CONSTRAINT products_group_value CHECK (((jsonb_typeof(group_value) = 'object'::text) AND (length((group_value)::text) <= 1000))),
    CONSTRAINT products_handle_format CHECK ((handle ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text)),
    CONSTRAINT products_kind CHECK ((kind = ANY (ARRAY['goods'::text, 'appointment'::text, 'stay'::text, 'rental'::text, 'gift_card'::text, 'bundle'::text]))),
    CONSTRAINT products_price_on_request_goods CHECK (((NOT price_on_request) OR (kind = 'goods'::text))),
    CONSTRAINT products_price_words CHECK (((price_words IS NULL) OR COALESCE(((octet_length((price_words)::text) <= 4000) AND ((price_words = '{"mode": "none"}'::jsonb) OR (((price_words ->> 'mode'::text) = 'own'::text) AND (jsonb_typeof((price_words -> 'words'::text)) = 'object'::text) AND (NOT jsonb_path_exists(price_words, '$."words".*?(@.type() != "object")'::jsonpath)) AND (NOT jsonb_path_exists(price_words, '$."words".*.*?((@.type() != "string" || @ like_regex "^.{25}" flag "s") || @ like_regex "[<>]")'::jsonpath))))), false))),
    CONSTRAINT products_sold_by_measure_goods CHECK (((NOT sold_by_measure) OR (kind = 'goods'::text))),
    CONSTRAINT products_standard_attributes CHECK (((jsonb_typeof(standard_attributes) = 'object'::text) AND ((standard_category IS NOT NULL) OR (standard_attributes = '{}'::jsonb)))),
    CONSTRAINT products_standard_category CHECK ((standard_category ~ '^[a-z]{2}(-[0-9]+)*$'::text))
);


