    status_changed_by uuid,
    closed_at timestamp with time zone,
    starter boolean DEFAULT false NOT NULL,
    made_from_starter uuid,
    starter_copy_of uuid,
    features text[] DEFAULT '{shop}'::text[] NOT NULL,
    domain_dns_auto boolean DEFAULT false NOT NULL,
    domain_buying boolean DEFAULT false NOT NULL,
    private_mode boolean DEFAULT true NOT NULL,
    private_password text,
    private_version integer DEFAULT 1 NOT NULL,
    shopping_agents boolean DEFAULT false NOT NULL,
    customer_accounts text DEFAULT 'optional'::text NOT NULL,
    assistant_keep_months integer,
    price_decimals text DEFAULT 'always'::text NOT NULL,
    price_words jsonb DEFAULT '{}'::jsonb NOT NULL,
    quantity_picker text DEFAULT 'buttons'::text NOT NULL,
    sandbox boolean DEFAULT false NOT NULL,
    sales_pilot boolean DEFAULT false NOT NULL,
    house boolean DEFAULT false NOT NULL,
    language_rule text DEFAULT 'browser'::text NOT NULL,
    currency_follows_language boolean DEFAULT false NOT NULL,
    language_currencies jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT stores_assistant_keep_months CHECK (((assistant_keep_months IS NULL) OR ((assistant_keep_months >= 1) AND (assistant_keep_months <= 60)))),
    CONSTRAINT stores_audience CHECK ((audience = ANY (ARRAY['consumers'::text, 'businesses'::text, 'both'::text]))),
    CONSTRAINT stores_booking_reminder_hours CHECK (((booking_reminder_hours >= 0) AND (booking_reminder_hours <= 168))),
    CONSTRAINT stores_custom_css CHECK ((length(custom_css) <= 50000)),
    CONSTRAINT stores_customer_accounts CHECK ((customer_accounts = ANY (ARRAY['optional'::text, 'required'::text, 'off'::text]))),
    CONSTRAINT stores_features CHECK ((features <@ ARRAY['shop'::text, 'subscriptions'::text, 'boxes'::text, 'appointments'::text, 'bookings'::text, 'countries'::text, 'languages'::text, 'currencies'::text, 'business'::text, 'bonus'::text, 'referrals'::text, 'gift_cards'::text, 'reviews'::text, 'sales'::text])),
    CONSTRAINT stores_house_real CHECK ((NOT (house AND (is_template OR starter OR sandbox)))),
    CONSTRAINT stores_language_currencies CHECK (((jsonb_typeof(language_currencies) = 'object'::text) AND (octet_length((language_currencies)::text) <= 2000) AND (NOT jsonb_path_exists(language_currencies, '$.*?(@.type() != "string" || !(@ like_regex "^([A-Z]{3}|own)$"))'::jsonpath)))),
    CONSTRAINT stores_language_rule CHECK ((language_rule = ANY (ARRAY['own'::text, 'location'::text, 'location-browser'::text, 'browser'::text]))),
    CONSTRAINT stores_modules CHECK ((modules <@ ARRAY['bookings'::text, 'deliveries'::text, 'work'::text])),
    CONSTRAINT stores_navigation_object CHECK ((jsonb_typeof(navigation) = 'object'::text)),
    CONSTRAINT stores_price_decimals CHECK ((price_decimals = ANY (ARRAY['always'::text, 'hide_whole'::text]))),
    CONSTRAINT stores_price_words CHECK (((jsonb_typeof(price_words) = 'object'::text) AND (octet_length((price_words)::text) <= 4000) AND (NOT jsonb_path_exists(price_words, '$.*?(@.type() != "object")'::jsonpath)) AND (NOT jsonb_path_exists(price_words, '$.*.*?((@.type() != "string" || @ like_regex "^.{25}" flag "s") || @ like_regex "[<>]")'::jsonpath)))),
    CONSTRAINT stores_quantity_picker CHECK ((quantity_picker = ANY (ARRAY['buttons'::text, 'box'::text, 'hidden'::text]))),
    CONSTRAINT stores_sandbox_address CHECK (((NOT sandbox) OR (slug ~~ 'try-%'::text))),
    CONSTRAINT stores_sandbox_not_template CHECK ((NOT (sandbox AND (is_template OR starter)))),
    CONSTRAINT stores_slug_format CHECK ((slug ~ '^[a-z0-9](?:[a-z0-9-]{1,38}[a-z0-9])$'::text)),
    CONSTRAINT stores_starter_copy_is_starter CHECK (((starter_copy_of IS NULL) OR starter)),
    CONSTRAINT stores_starter_not_template CHECK ((NOT (starter AND is_template))),
    CONSTRAINT stores_terms_at_checkout CHECK ((terms_at_checkout = ANY (ARRAY['link'::text, 'checkbox'::text, 'off'::text])))
);


--
-- Name: missing_registrations; Type: VIEW; Schema: commerce; Owner: -
--

CREATE VIEW commerce.missing_registrations WITH (security_invoker='true') AS
 SELECT p.store_id,
    p.id AS product_id,
    p.handle,
    (g.market_code)::character(2) AS market_code,
    g.scheme,
    (NOT (s.is_template OR s.starter)) AS blocked
   FROM ((commerce.products p
     JOIN commerce.stores s ON ((s.id = p.store_id)))
     CROSS JOIN LATERAL commerce.registration_gaps(p.store_id, NULL::text, p.id) g(product_id, market_code, scheme, recorded))
  WHERE (p.status = 'active'::commerce.product_status);


