--
-- Name: order_edit_lines; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.order_edit_lines (
    store_id uuid NOT NULL,
    order_edit_id uuid NOT NULL,
    n integer NOT NULL,
    kind text NOT NULL,
    order_line_id uuid,
    variant_id uuid,
    sku text NOT NULL,
    title text NOT NULL,
    quantity integer NOT NULL,
    unit_price_minor bigint NOT NULL,
    list_price_minor bigint,
    total_minor bigint NOT NULL,
    discount_minor bigint NOT NULL,
    tax_minor bigint NOT NULL,
    tax_rate numeric(6,4) NOT NULL,
    parts jsonb DEFAULT '{}'::jsonb NOT NULL,
    before jsonb,
    backorder_quantity integer DEFAULT 0 NOT NULL,
    backorder_days integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT order_edit_lines_amounts CHECK (((unit_price_minor >= 0) AND (discount_minor >= 0) AND (total_minor >= 0) AND (tax_minor >= 0) AND (tax_minor <= total_minor) AND (total_minor = ((unit_price_minor * quantity) - discount_minor)) AND ((list_price_minor IS NULL) OR (list_price_minor >= 0)))),
    CONSTRAINT order_edit_lines_backorder CHECK ((((backorder_quantity >= 0) AND (backorder_quantity <= quantity)) AND ((backorder_days IS NULL) OR ((backorder_days >= 1) AND (backorder_days <= 90))) AND ((backorder_quantity = 0) OR (backorder_days IS NOT NULL)))),
    CONSTRAINT order_edit_lines_kind CHECK ((kind = ANY (ARRAY['add'::text, 'remove'::text, 'reduce'::text]))),
    CONSTRAINT order_edit_lines_n CHECK ((n >= 1)),
    CONSTRAINT order_edit_lines_parts CHECK ((jsonb_typeof(parts) = 'object'::text)),
    CONSTRAINT order_edit_lines_quantity CHECK ((quantity > 0)),
    CONSTRAINT order_edit_lines_rate CHECK (((tax_rate >= (0)::numeric) AND (tax_rate < (1)::numeric))),
    CONSTRAINT order_edit_lines_shape CHECK ((((kind = 'add'::text) AND (before IS NULL) AND (discount_minor = 0) AND (variant_id IS NOT NULL)) OR ((kind = ANY (ARRAY['remove'::text, 'reduce'::text])) AND (before IS NOT NULL) AND (jsonb_typeof(before) = 'object'::text) AND (order_line_id IS NOT NULL) AND (backorder_quantity = 0) AND (backorder_days IS NULL))))
);


--
-- Name: order_edits; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.order_edits (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    order_id uuid NOT NULL,
    seq integer NOT NULL,
    status text NOT NULL,
    reason text NOT NULL,
    notify boolean NOT NULL,
    restock boolean NOT NULL,
    currency character(3) NOT NULL,
    base jsonb NOT NULL,
    total_before bigint NOT NULL,
    total_after bigint NOT NULL,
    subtotal_delta bigint NOT NULL,
    shipping_before bigint NOT NULL,
    shipping_after bigint NOT NULL,
    discount_delta bigint NOT NULL,
    tax_delta bigint NOT NULL,
    difference_minor bigint NOT NULL,
    payment_id uuid,
    refund_id uuid,
    pay_token_hash text,
    expires_at timestamp with time zone,
    made_by uuid NOT NULL,
    documents text DEFAULT 'none'::text NOT NULL,
    applied_at timestamp with time zone,
    ended_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT order_edits_amounts CHECK (((total_before >= 0) AND (total_after >= 0) AND (shipping_before >= 0) AND (shipping_after >= 0) AND (difference_minor = (total_after - total_before)))),
    CONSTRAINT order_edits_base CHECK ((jsonb_typeof(base) = 'object'::text)),
    CONSTRAINT order_edits_documents CHECK ((documents = ANY (ARRAY['none'::text, 'issued'::text, 'waiting'::text, 'not_invoiced'::text, 'in_original'::text]))),
    CONSTRAINT order_edits_lifecycle CHECK ((((status = 'awaiting_payment'::text) AND (difference_minor > 0) AND (pay_token_hash IS NOT NULL) AND (expires_at IS NOT NULL) AND (applied_at IS NULL) AND (ended_at IS NULL) AND (payment_id IS NULL) AND (refund_id IS NULL) AND (documents = 'none'::text)) OR ((status = 'applied'::text) AND (applied_at IS NOT NULL) AND (ended_at IS NULL)) OR ((status = ANY (ARRAY['cancelled'::text, 'expired'::text])) AND (difference_minor > 0) AND (pay_token_hash IS NOT NULL) AND (ended_at IS NOT NULL) AND (applied_at IS NULL) AND (payment_id IS NULL) AND (refund_id IS NULL) AND (documents = 'none'::text)))),
    CONSTRAINT order_edits_money CHECK ((((difference_minor >= 0) OR (payment_id IS NULL)) AND ((difference_minor <= 0) OR (refund_id IS NULL)))),
    CONSTRAINT order_edits_reason CHECK ((reason = ANY (ARRAY['customer_request'::text, 'out_of_stock'::text, 'store_error'::text, 'other'::text]))),
    CONSTRAINT order_edits_seq CHECK ((seq >= 1)),
    CONSTRAINT order_edits_status CHECK ((status = ANY (ARRAY['awaiting_payment'::text, 'applied'::text, 'cancelled'::text, 'expired'::text]))),
    CONSTRAINT order_edits_token CHECK (((pay_token_hash IS NULL) OR (pay_token_hash ~ '^[A-Za-z0-9_-]{43}$'::text)))
);


