--
-- Name: order_lines; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.order_lines (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    order_id uuid NOT NULL,
    variant_id uuid,
    sku text NOT NULL,
    title text NOT NULL,
    quantity integer NOT NULL,
    unit_price_minor bigint NOT NULL,
    discount_minor bigint DEFAULT 0 NOT NULL,
    total_minor bigint NOT NULL,
    tax_minor bigint NOT NULL,
    tax_rate numeric(6,4) NOT NULL,
    tax_code text NOT NULL,
    withdrawal_exclusion commerce.withdrawal_exclusion DEFAULT 'none'::commerce.withdrawal_exclusion NOT NULL,
    delivery commerce.delivery DEFAULT 'physical'::commerce.delivery NOT NULL,
    selling_plan_id uuid,
    plan_interval commerce.plan_interval,
    plan_interval_count integer,
    venue_minor bigint DEFAULT 0 NOT NULL,
    booked_count integer,
    member_discount_minor bigint DEFAULT 0 NOT NULL,
    campaign_discount_minor bigint DEFAULT 0 NOT NULL,
    campaign_id uuid,
    gift boolean DEFAULT false NOT NULL,
    campaign_parts jsonb DEFAULT '[]'::jsonb NOT NULL,
    bonus_discount_minor bigint DEFAULT 0 NOT NULL,
    referral_discount_minor bigint DEFAULT 0 NOT NULL,
    unit_cost_minor bigint,
    vat_relief_minor bigint DEFAULT 0 NOT NULL,
    measure_amount numeric(12,4),
    measure_unit text,
    measure_base text,
    backorder_quantity integer DEFAULT 0 NOT NULL,
    backorder_days integer,
    list_price_minor bigint,
    custom boolean DEFAULT false NOT NULL,
    staff_discount_minor bigint DEFAULT 0 NOT NULL,
    order_edit_id uuid,
    gift_card_to text,
    gift_card_to_name text,
    gift_card_from text,
    gift_card_message text,
    gift_card_send_on date,
    price_list_id uuid,
    preorder_until date,
    CONSTRAINT order_lines_amounts_non_negative CHECK (((unit_price_minor >= 0) AND (discount_minor >= 0) AND (total_minor >= 0) AND (tax_minor >= 0))),
    CONSTRAINT order_lines_backorder_days CHECK (((backorder_days >= 1) AND (backorder_days <= 90))),
    CONSTRAINT order_lines_backorder_quantity CHECK (((backorder_quantity >= 0) AND (backorder_quantity <= quantity))),
    CONSTRAINT order_lines_backorder_stated CHECK (((backorder_quantity = 0) OR (backorder_days IS NOT NULL))),
    CONSTRAINT order_lines_bonus_discount CHECK (((bonus_discount_minor >= 0) AND (bonus_discount_minor <= discount_minor))),
    CONSTRAINT order_lines_campaign_discount CHECK (((campaign_discount_minor >= 0) AND (campaign_discount_minor <= discount_minor))),
    CONSTRAINT order_lines_custom CHECK (((NOT custom) OR ((variant_id IS NULL) AND (sku = 'CUSTOM'::text) AND (delivery = 'service'::commerce.delivery)))),
    CONSTRAINT order_lines_discount_parts CHECK (((staff_discount_minor = 0) OR ((((((member_discount_minor + campaign_discount_minor) + bonus_discount_minor) + referral_discount_minor) + vat_relief_minor) + staff_discount_minor) <= discount_minor))),
    CONSTRAINT order_lines_gift_card CHECK (((((gift_card_to IS NULL) AND (gift_card_to_name IS NULL) AND (gift_card_from IS NULL) AND (gift_card_message IS NULL) AND (gift_card_send_on IS NULL)) OR ((gift_card_to IS NOT NULL) AND (gift_card_send_on IS NOT NULL))) AND (char_length(gift_card_to) <= 254) AND (char_length(gift_card_to_name) <= 60) AND (char_length(gift_card_from) <= 60) AND (char_length(gift_card_message) <= 300) AND ((gift_card_message IS NULL) OR (cardinality(string_to_array(gift_card_message, chr(10))) <= 6)))),
    CONSTRAINT order_lines_list_price CHECK (((list_price_minor IS NULL) OR (list_price_minor >= 0))),
    CONSTRAINT order_lines_measure_amount CHECK (((measure_amount > (0)::numeric) AND (measure_amount <= (1000000)::numeric))),
    CONSTRAINT order_lines_measure_base CHECK ((((measure_amount IS NULL) = (measure_base IS NULL)) AND ((measure_base IS NULL) OR (((measure_unit = ANY (ARRAY['g'::text, 'kg'::text])) AND (measure_base = ANY (ARRAY['kg'::text, '100g'::text]))) OR ((measure_unit = ANY (ARRAY['ml'::text, 'cl'::text, 'l'::text])) AND (measure_base = ANY (ARRAY['l'::text, '100ml'::text]))) OR ((measure_unit = ANY (ARRAY['cm'::text, 'm'::text])) AND (measure_base = 'm'::text)) OR ((measure_unit = 'm2'::text) AND (measure_base = 'm2'::text)) OR ((measure_unit = 'piece'::text) AND (measure_base = 'piece'::text)))))),
    CONSTRAINT order_lines_measure_pair CHECK (((measure_amount IS NULL) = (measure_unit IS NULL))),
    CONSTRAINT order_lines_measure_unit CHECK ((measure_unit = ANY (ARRAY['g'::text, 'kg'::text, 'ml'::text, 'cl'::text, 'l'::text, 'cm'::text, 'm'::text, 'm2'::text, 'piece'::text]))),
    CONSTRAINT order_lines_member_discount CHECK (((member_discount_minor >= 0) AND (member_discount_minor <= discount_minor))),
    CONSTRAINT order_lines_quantity_positive CHECK ((quantity > 0)),
    CONSTRAINT order_lines_referral_discount CHECK (((referral_discount_minor >= 0) AND (referral_discount_minor <= discount_minor))),
    CONSTRAINT order_lines_staff_discount CHECK (((staff_discount_minor >= 0) AND (staff_discount_minor <= discount_minor))),
    CONSTRAINT order_lines_total_adds_up CHECK ((total_minor = ((unit_price_minor * quantity) - discount_minor))),
    CONSTRAINT order_lines_unit_cost CHECK ((unit_cost_minor >= 0)),
    CONSTRAINT order_lines_vat_relief CHECK (((vat_relief_minor >= 0) AND (vat_relief_minor <= discount_minor))),
    CONSTRAINT order_lines_venue CHECK (((venue_minor >= 0) AND (venue_minor <= total_minor)))
);


