    CONSTRAINT order_rules_match CHECK ((match = ANY (ARRAY['all'::text, 'any'::text]))),
    CONSTRAINT order_rules_name CHECK ((((char_length(name) >= 1) AND (char_length(name) <= 80)) AND (name = btrim(name)))),
    CONSTRAINT order_rules_position CHECK (("position" >= 0)),
    CONSTRAINT order_rules_version CHECK ((version >= 1))
);


