    delivery_method text DEFAULT 'ship'::text NOT NULL,
    pickup_location_id uuid,
    ready_for_pickup_at timestamp with time zone,
    delivery_note text,
    delivery_mismatch_at timestamp with time zone,
    delivered_source text,
    held_at timestamp with time zone,
    held_reason text,
    held_by_rule uuid,
    held_by uuid,
    exchange_id uuid,
    capture_mode text,
    capture_before timestamp with time zone,
    capture_warned_at timestamp with time zone,
    awaiting_bank_since timestamp with time zone,
    discount_code_item_id uuid,
    entered_codes text[],
    campaign_shipping jsonb,
    ad_consent_at timestamp with time zone,
    ad_signals jsonb,
    company_location_id uuid,
    po_number text,
    approval text,
    approval_decided_by uuid,
    approval_decided_at timestamp with time zone,
    duties_minor bigint DEFAULT 0 NOT NULL,
    customs jsonb,
    checkout_answers jsonb,
    rule_hidden_methods text[] DEFAULT '{}'::text[] NOT NULL,
    checkout_rules_applied uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    sold_at timestamp with time zone,
    service_request_at timestamp with time zone,
    CONSTRAINT orders_amounts_non_negative CHECK (((subtotal_minor >= 0) AND (shipping_minor >= 0) AND (discount_minor >= 0) AND (tax_minor >= 0))),
    CONSTRAINT orders_anonymised CHECK (((anonymised_at IS NULL) OR ((email = '[removed]'::text) AND (billing_address = '{}'::jsonb) AND (shipping_address = '{}'::jsonb) AND (company_name IS NULL) AND (organisation_number IS NULL) AND (NOT is_gift) AND (gift_to IS NULL) AND (gift_from IS NULL) AND (gift_message IS NULL) AND (delivery_note IS NULL)))),
    CONSTRAINT orders_approval CHECK (((approval IS NULL) OR (approval = ANY (ARRAY['waiting'::text, 'approved'::text, 'declined'::text])))),
    CONSTRAINT orders_archived_not_pending CHECK (((archived_at IS NULL) OR (status <> 'pending_payment'::commerce.order_status))),
    CONSTRAINT orders_balance CHECK (((balance_minor >= 0) AND (balance_minor <= total_minor))),
    CONSTRAINT orders_campaign_discount CHECK (((campaign_discount_minor >= 0) AND (campaign_discount_minor <= discount_minor))),
    CONSTRAINT orders_campaign_shipping CHECK (((campaign_shipping IS NULL) OR ((jsonb_typeof(campaign_shipping) = 'object'::text) AND ((((campaign_shipping ->> 'minor'::text))::bigint >= 0) AND (((campaign_shipping ->> 'minor'::text))::bigint <= campaign_discount_minor))))),
    CONSTRAINT orders_capture_before CHECK (((status <> 'authorized'::commerce.order_status) OR ((capture_mode IS NOT NULL) AND (capture_before IS NOT NULL)))),
    CONSTRAINT orders_capture_mode CHECK (((capture_mode IS NULL) OR (capture_mode = ANY (ARRAY['when_sent'::text, 'by_hand'::text])))),
    CONSTRAINT orders_copied_number CHECK (((copied_from IS NULL) OR (number ~~ 'C-%'::text))),
    CONSTRAINT orders_credit CHECK (((credit_minor >= 0) AND (credit_minor <= discount_minor))),
    CONSTRAINT orders_delivered_source CHECK (((delivered_source IS NULL) OR ((delivered_at IS NOT NULL) AND (delivered_source = ANY (ARRAY['staff'::text, 'handover'::text, 'carrier'::text]))))),
    CONSTRAINT orders_delivery_method CHECK ((delivery_method = ANY (ARRAY['ship'::text, 'pickup'::text, 'local'::text]))),
    CONSTRAINT orders_delivery_note CHECK (((delivery_note IS NULL) OR ((delivery_method = 'local'::text) AND ((char_length(delivery_note) >= 1) AND (char_length(delivery_note) <= 500))))),
    CONSTRAINT orders_duties_non_negative CHECK ((duties_minor >= 0)),
    CONSTRAINT orders_gift_fields CHECK (((is_gift OR ((gift_to IS NULL) AND (gift_from IS NULL) AND (gift_message IS NULL))) AND (char_length(gift_to) <= 60) AND (char_length(gift_from) <= 60) AND (char_length(gift_message) <= 300) AND ((gift_message IS NULL) OR (cardinality(string_to_array(gift_message, chr(10))) <= 6)))),
    CONSTRAINT orders_held CHECK ((((held_at IS NOT NULL) OR ((held_reason IS NULL) AND (held_by_rule IS NULL) AND (held_by IS NULL))) AND (NOT ((held_by_rule IS NOT NULL) AND (held_by IS NOT NULL))) AND ((held_reason IS NULL) OR ((char_length(held_reason) >= 1) AND (char_length(held_reason) <= 200))))),
    CONSTRAINT orders_member_discount CHECK (((member_discount_minor >= 0) AND (member_discount_minor <= discount_minor))),
    CONSTRAINT orders_pickup_location CHECK (((delivery_method = 'pickup'::text) = (pickup_location_id IS NOT NULL))),
    CONSTRAINT orders_po_number CHECK (((po_number IS NULL) OR ((char_length(po_number) >= 1) AND (char_length(po_number) <= 40)))),
    CONSTRAINT orders_ready_for_pickup CHECK (((ready_for_pickup_at IS NULL) OR (delivery_method = 'pickup'::text))),
    CONSTRAINT orders_return_cost_payer CHECK (((return_cost_payer IS NULL) OR (return_cost_payer = ANY (ARRAY['shopper'::text, 'store'::text])))),
    CONSTRAINT orders_shipping_tax_rate CHECK (((shipping_tax_rate IS NULL) OR ((shipping_tax_rate >= (0)::numeric) AND (shipping_tax_rate < (1)::numeric)))),
    CONSTRAINT orders_source CHECK ((source = ANY (ARRAY['checkout'::text, 'draft'::text, 'exchange'::text]))),
    CONSTRAINT orders_source_draft CHECK ((((source = 'draft'::text) = (draft_id IS NOT NULL)) AND ((source = ANY (ARRAY['draft'::text, 'exchange'::text])) = (made_by IS NOT NULL)))),
    CONSTRAINT orders_source_exchange CHECK (((source = 'exchange'::text) = (exchange_id IS NOT NULL))),
    CONSTRAINT orders_staff_discount CHECK (((staff_discount_minor >= 0) AND (staff_discount_minor <= discount_minor))),
    CONSTRAINT orders_staff_discount_label CHECK (((staff_discount_label IS NULL) OR ((staff_discount_minor > 0) AND ((char_length(staff_discount_label) >= 1) AND (char_length(staff_discount_label) <= 60))))),
    CONSTRAINT orders_standard_shipping CHECK (((standard_shipping_minor IS NULL) OR (standard_shipping_minor >= 0))),
    CONSTRAINT orders_tax_within_total CHECK ((tax_minor <= total_minor)),
    CONSTRAINT orders_total_adds_up CHECK ((total_minor = ((subtotal_minor + shipping_minor) - discount_minor))),
    CONSTRAINT orders_vat_kind CHECK ((vat_kind = ANY (ARRAY['standard'::text, 'reverse_charge'::text, 'ioss'::text]))),
    CONSTRAINT orders_vat_kind_relief CHECK ((((vat_kind = 'reverse_charge'::text) AND (tax_minor = 0) AND (vat_relief_minor > 0)) OR ((vat_kind <> 'reverse_charge'::text) AND (vat_relief_minor = 0)))),
    CONSTRAINT orders_vat_relief CHECK (((vat_relief_minor >= 0) AND (vat_relief_minor <= discount_minor)))
);


