-- Name: pages; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.pages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid,
    slug text NOT NULL,
    draft jsonb NOT NULL,
    published jsonb,
    published_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    type text DEFAULT 'page'::text NOT NULL,
    first_published_at timestamp with time zone,
    CONSTRAINT pages_article_slug_not_reserved CHECK (((type <> 'article'::text) OR (slug <> ALL (ARRAY['category'::text, 'page'::text, 'tag'::text])))),
    CONSTRAINT pages_product_layout_store CHECK (((type <> 'product_layout'::text) OR (store_id IS NOT NULL))),
    CONSTRAINT pages_published_together CHECK (((published IS NULL) = (published_at IS NULL))),
    CONSTRAINT pages_slug_format CHECK (((slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*(?:/[a-z0-9]+(?:-[a-z0-9]+)*){0,3}$'::text) AND (length(slug) <= 240) AND (slug !~ '[^/]{81}'::text) AND ((type = 'page'::text) OR (POSITION(('/'::text) IN (slug)) = 0)))),
    CONSTRAINT pages_slug_not_reserved CHECK (((store_id IS NOT NULL) OR (type <> 'page'::text) OR (split_part(slug, '/'::text, 1) <> ALL (ARRAY['account'::text, 'admin'::text, 'api'::text, 'app'::text, 'auth'::text, 'blog'::text, 'category'::text, 'cookies'::text, 'da'::text, 'en'::text, 'forgot-password'::text, 'help'::text, 'mail'::text, 'nb'::text, 'nn'::text, 'no'::text, 'platform'::text, 'robots'::text, 's'::text, 'setup'::text, 'sign-in'::text, 'sign-up'::text, 'sitemap'::text, 'status'::text, 'stores'::text, 'support'::text, 'sv'::text, 'tag'::text, 'themes'::text, 'unsubscribe'::text, 'www'::text])))),
    CONSTRAINT pages_store_slug_not_reserved CHECK (((store_id IS NULL) OR (type <> 'page'::text) OR (split_part(slug, '/'::text, 1) <> ALL (ARRAY['account'::text, 'blog'::text, 'cart'::text, 'category'::text, 'checkout'::text, 'cookies'::text, 'deliveries'::text, 'download'::text, 'order'::text, 'p'::text, 'products'::text, 'returns'::text, 'search'::text, 'subscription'::text, 'tag'::text, 'unsubscribe'::text, 'wishlist'::text, 'withdraw'::text])))),
    CONSTRAINT pages_type CHECK ((type = ANY (ARRAY['page'::text, 'article'::text, 'product_layout'::text, 'header'::text, 'footer'::text, 'variant'::text, 'entry_layout'::text]))),
    CONSTRAINT pages_variant_store CHECK (((type <> 'variant'::text) OR (store_id IS NOT NULL)))
);


