    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT payment_disputes_amount CHECK ((amount_minor > 0)),
    CONSTRAINT payment_disputes_closed CHECK (((closed_at IS NULL) = (outcome IS NULL))),
    CONSTRAINT payment_disputes_money CHECK ((((funds_withdrawn_minor IS NULL) OR (funds_withdrawn_minor >= 0)) AND ((fee_minor IS NULL) OR (fee_minor >= 0)))),
    CONSTRAINT payment_disputes_outcome CHECK (((outcome IS NULL) OR (outcome = ANY (ARRAY['won'::text, 'lost'::text])))),
    CONSTRAINT payment_disputes_provider CHECK ((provider = ANY (ARRAY['stripe'::text, 'mollie'::text]))),
    CONSTRAINT payment_disputes_reason CHECK (((reason IS NULL) OR (char_length(reason) <= 80))),
    CONSTRAINT payment_disputes_status CHECK ((status = ANY (ARRAY['warning_needs_response'::text, 'warning_under_review'::text, 'warning_closed'::text, 'needs_response'::text, 'under_review'::text, 'won'::text, 'lost'::text, 'prevented'::text])))
);


