-- Name: payments; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.payments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    order_id uuid NOT NULL,
    provider text NOT NULL,
    provider_reference text NOT NULL,
    amount_minor bigint NOT NULL,
    currency character(3) NOT NULL,
    status commerce.payment_status DEFAULT 'pending'::commerce.payment_status NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    provider_account text,
    client_secret text,
    kaizen_fee_minor bigint DEFAULT 0 NOT NULL,
    test_mode boolean DEFAULT false NOT NULL,
    method text,
    recorded_by uuid,
    received_on date,
    order_edit_id uuid,
    exchange_id uuid,
    transfer_refund_id uuid,
    method_type text,
    wallet text,
    card_brand text,
    risk_level text,
    risk_score smallint,
    charge_reference text,
    facts_read_at timestamp with time zone,
    provider_fee_minor bigint,
    application_fee_minor bigint,
    fee_currency character(3),
    gift_card_id uuid,
    CONSTRAINT payments_amount_positive CHECK ((amount_minor > 0)),
    CONSTRAINT payments_exchange_transfer CHECK ((((provider = 'exchange'::text) = (transfer_refund_id IS NOT NULL)) AND ((provider <> 'exchange'::text) OR (exchange_id IS NOT NULL)))),
    CONSTRAINT payments_facts_stripe CHECK (((provider = 'stripe'::text) OR ((method_type IS NULL) AND (wallet IS NULL) AND (card_brand IS NULL) AND (risk_level IS NULL) AND (charge_reference IS NULL)))),
    CONSTRAINT payments_gift_card CHECK ((((provider = 'gift_card'::text) = (gift_card_id IS NOT NULL)) AND ((provider <> 'gift_card'::text) OR (provider_account IS NULL)))),
    CONSTRAINT payments_manual_method CHECK ((((provider = 'manual'::text) = (method IS NOT NULL)) AND ((method IS NULL) OR (method = ANY (ARRAY['cash'::text, 'bank_transfer'::text, 'other'::text]))))),
    CONSTRAINT payments_manual_real CHECK (((provider <> 'manual'::text) OR (NOT test_mode))),
    CONSTRAINT payments_manual_recorded CHECK (((provider <> 'manual'::text) OR (recorded_by IS NOT NULL))),
    CONSTRAINT payments_provider_fee CHECK ((((provider_fee_minor IS NULL) = (fee_currency IS NULL)) AND ((application_fee_minor IS NULL) OR (provider_fee_minor IS NOT NULL)) AND ((provider_fee_minor IS NULL) OR ((provider = 'stripe'::text) AND (provider_fee_minor >= 0) AND (COALESCE(application_fee_minor, (0)::bigint) >= 0))))),
    CONSTRAINT payments_received_manual CHECK (((received_on IS NULL) OR (provider = 'manual'::text))),
    CONSTRAINT payments_risk_level CHECK (((risk_level IS NULL) OR (risk_level = ANY (ARRAY['normal'::text, 'elevated'::text, 'highest'::text, 'not_assessed'::text, 'unknown'::text])))),
    CONSTRAINT payments_risk_score CHECK (((risk_score IS NULL) OR ((risk_score >= 0) AND (risk_score <= 100))))
);


