CREATE TABLE commerce.price_list_breaks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    list_id uuid NOT NULL,
    variant_id uuid NOT NULL,
    from_quantity integer NOT NULL,
    percent integer,
    amounts jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT price_list_breaks_amounts CHECK (((amounts IS NULL) OR commerce.break_amounts_ok(amounts, 3))),
    CONSTRAINT price_list_breaks_from CHECK (((from_quantity >= 2) AND (from_quantity <= 9999))),
    CONSTRAINT price_list_breaks_one CHECK (((percent IS NULL) <> (amounts IS NULL))),
    CONSTRAINT price_list_breaks_percent CHECK (((percent >= 1) AND (percent <= 99)))
);


