    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT price_list_prices_amount CHECK ((amount_minor >= 0)),
    CONSTRAINT price_list_prices_currency CHECK ((currency ~ '^[A-Z]{3}$'::text))
);


