--
-- Name: price_list_quantity_rules; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.price_list_quantity_rules (
    store_id uuid NOT NULL,
    list_id uuid NOT NULL,
    variant_id uuid NOT NULL,
    min_quantity integer DEFAULT 1 NOT NULL,
    max_quantity integer,
    quantity_step integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT price_list_quantity_rules_max CHECK (((max_quantity IS NULL) OR (((max_quantity >= min_quantity) AND (max_quantity <= 9999)) AND ((max_quantity % quantity_step) = 0)))),
    CONSTRAINT price_list_quantity_rules_rule CHECK ((((min_quantity >= 1) AND (min_quantity <= 9999)) AND ((quantity_step >= 1) AND (quantity_step <= 9999)) AND ((min_quantity % quantity_step) = 0)))
);


