    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    exclusive boolean DEFAULT false NOT NULL,
    CONSTRAINT price_lists_name CHECK ((((char_length(name) >= 1) AND (char_length(name) <= 80)) AND (name = btrim(name)))),
    CONSTRAINT price_lists_percent CHECK (((percent IS NULL) OR ((percent >= 1) AND (percent <= 99))))
);


--
-- Name: prices_id_seq; Type: SEQUENCE; Schema: commerce; Owner: -
--

ALTER TABLE commerce.prices ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME commerce.prices_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: privacy_requests; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.privacy_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    kind text NOT NULL,
    channel text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    subject_customer_id uuid,
    subject_email text,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
    due_at timestamp with time zone NOT NULL,
    extended_until timestamp with time zone,
    extension_reason text,
    identity_doubt_at timestamp with time zone,
    completed_at timestamp with time zone,
    outcome text,
    refusal_reason text,
    refusal_note text,
    note text DEFAULT ''::text NOT NULL,
    plan_summary jsonb,
    steps jsonb DEFAULT '{}'::jsonb NOT NULL,
    handled_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT privacy_requests_channel CHECK ((channel = ANY (ARRAY['shopper'::text, 'staff'::text]))),
    CONSTRAINT privacy_requests_due CHECK ((due_at >= received_at)),
    CONSTRAINT privacy_requests_email CHECK (((subject_email IS NULL) OR (subject_email = lower(subject_email)))),
    CONSTRAINT privacy_requests_erased_email CHECK (((NOT ((kind = 'erasure'::text) AND (status = 'done'::text))) OR (subject_email IS NULL))),
    CONSTRAINT privacy_requests_extension CHECK (((extended_until IS NULL) OR ((extended_until > due_at) AND (extended_until <= (received_at + '3 mons'::interval))))),
    CONSTRAINT privacy_requests_kind CHECK ((kind = ANY (ARRAY['export'::text, 'erasure'::text]))),
    CONSTRAINT privacy_requests_outcome CHECK (((outcome IS NULL) OR (outcome = ANY (ARRAY['exported'::text, 'erased'::text, 'no_data'::text, 'refused'::text, 'cancelled'::text])))),
    CONSTRAINT privacy_requests_refusal_reason CHECK (((refusal_reason IS NULL) OR (refusal_reason = ANY (ARRAY['identity_not_confirmed'::text, 'manifestly_unfounded'::text, 'excessive'::text, 'legal_hold'::text, 'other'::text])))),
    CONSTRAINT privacy_requests_state CHECK ((((status = 'open'::text) AND (completed_at IS NULL) AND (outcome IS NULL)) OR ((status = 'done'::text) AND (completed_at IS NOT NULL) AND COALESCE((outcome = ANY (ARRAY['exported'::text, 'erased'::text, 'no_data'::text])), false)) OR ((status = 'refused'::text) AND (completed_at IS NOT NULL) AND COALESCE((outcome = 'refused'::text), false) AND (refusal_reason IS NOT NULL)) OR ((status = 'cancelled'::text) AND (completed_at IS NOT NULL) AND COALESCE((outcome = 'cancelled'::text), false)))),
    CONSTRAINT privacy_requests_status CHECK ((status = ANY (ARRAY['open'::text, 'done'::text, 'refused'::text, 'cancelled'::text])))
);


