    exemption text,
    show_number boolean DEFAULT false NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT producer_registrations_number_or_exemption CHECK ((((exemption IS NULL) AND (registration_number IS NOT NULL) AND (authority IS NOT NULL)) OR ((exemption IS NOT NULL) AND (registration_number IS NULL)))),
    CONSTRAINT producer_registrations_valid_range CHECK (((valid_to IS NULL) OR (valid_to >= valid_from)))
);


