--
-- Name: product_media; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.product_media (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    product_id uuid NOT NULL,
    url text NOT NULL,
    "position" integer DEFAULT 0 NOT NULL,
    alt jsonb DEFAULT '{}'::jsonb NOT NULL,
    thumbnail_url text,
    kind text DEFAULT 'image'::text NOT NULL,
    source text,
    media_url text,
    CONSTRAINT product_media_kind CHECK (
CASE kind
    WHEN 'image'::text THEN ((source IS NULL) AND (media_url IS NULL))
    WHEN 'video'::text THEN ((source = ANY (ARRAY['upload'::text, 'youtube'::text, 'vimeo'::text])) AND (media_url IS NOT NULL))
    WHEN 'model'::text THEN ((source IS NULL) AND (media_url IS NOT NULL))
    ELSE false
END)
);


