--
-- Name: product_reviews; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.product_reviews (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    product_id uuid NOT NULL,
    variant_id uuid,
    source text NOT NULL,
    order_id uuid,
    order_line_id uuid,
    buyer_key text,
    customer_id uuid,
    imported_from text,
    written_on date,
    author_name text NOT NULL,
    rating smallint NOT NULL,
    title text,
    body text,
    locale text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    hidden_reason text,
    moderated_at timestamp with time zone,
    moderated_by uuid,
    answer text,
    answered_at timestamp with time zone,
    answered_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    edited_at timestamp with time zone,
    CONSTRAINT product_reviews_answer CHECK ((((answer IS NULL) = (answered_at IS NULL)) AND ((answer IS NULL) OR ((length(TRIM(BOTH FROM answer)) >= 1) AND (length(TRIM(BOTH FROM answer)) <= 2000))))),
    CONSTRAINT product_reviews_hidden CHECK ((((status = 'hidden'::text) = (hidden_reason IS NOT NULL)) AND ((hidden_reason IS NULL) OR (hidden_reason = ANY (ARRAY['not_about_product'::text, 'offensive'::text, 'personal_data'::text, 'spam'::text, 'other'::text]))))),
    CONSTRAINT product_reviews_origin CHECK ((((source = 'buyer'::text) AND (order_id IS NOT NULL) AND (order_line_id IS NOT NULL) AND (variant_id IS NOT NULL) AND (buyer_key ~ '^(c:[0-9a-f-]{36}|e:[0-9a-f]{64})$'::text) AND (imported_from IS NULL) AND (written_on IS NULL)) OR ((source = 'import'::text) AND (order_id IS NULL) AND (order_line_id IS NULL) AND (buyer_key IS NULL) AND (customer_id IS NULL) AND ((length(TRIM(BOTH FROM imported_from)) >= 1) AND (length(TRIM(BOTH FROM imported_from)) <= 80)) AND (written_on IS NOT NULL)))),
    CONSTRAINT product_reviews_rating CHECK (((rating >= 1) AND (rating <= 5))),
    CONSTRAINT product_reviews_source CHECK ((source = ANY (ARRAY['buyer'::text, 'import'::text]))),
    CONSTRAINT product_reviews_status CHECK ((status = ANY (ARRAY['pending'::text, 'published'::text, 'hidden'::text]))),
    CONSTRAINT product_reviews_words CHECK ((((length(TRIM(BOTH FROM author_name)) >= 1) AND (length(TRIM(BOTH FROM author_name)) <= 60)) AND ((title IS NULL) OR ((length(TRIM(BOTH FROM title)) >= 1) AND (length(TRIM(BOTH FROM title)) <= 120))) AND ((body IS NULL) OR ((length(TRIM(BOTH FROM body)) >= 1) AND (length(TRIM(BOTH FROM body)) <= 5000)))))
);


