    CONSTRAINT product_safety_rules_responsible_person CHECK ((responsible_person = ANY (ARRAY['eu'::text, 'eea'::text, 'none'::text]))),
    CONSTRAINT product_safety_rules_status CHECK ((status = ANY (ARRAY['in_force'::text, 'not_incorporated'::text, 'incorporated_not_in_force'::text]))),
    CONSTRAINT product_safety_rules_status_none CHECK (((status = 'in_force'::text) OR (responsible_person = 'none'::text)))
);


