    CONSTRAINT purchase_orders_status CHECK ((status = ANY (ARRAY['draft'::text, 'ordered'::text, 'received'::text, 'cancelled'::text]))),
    CONSTRAINT purchase_orders_texts CHECK ((((length(supplier) >= 1) AND (length(supplier) <= 120)) AND COALESCE((length(reference) <= 60), true) AND COALESCE((length(note) <= 500), true)))
);


