    name text NOT NULL,
    match_text text NOT NULL,
    kind text NOT NULL,
    vat_rate integer NOT NULL,
    reverse_charge boolean DEFAULT false NOT NULL,
    every text NOT NULL,
    amount_minor bigint NOT NULL,
    currency character(3) NOT NULL,
    started_on date NOT NULL,
    ended_on date,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT recurring_costs_amount CHECK ((amount_minor > 0)),
    CONSTRAINT recurring_costs_days CHECK (((ended_on IS NULL) OR (ended_on >= started_on))),
    CONSTRAINT recurring_costs_every CHECK ((every = ANY (ARRAY['month'::text, 'year'::text]))),
    CONSTRAINT recurring_costs_kind CHECK ((kind ~ '^[a-z_]{2,30}$'::text)),
    CONSTRAINT recurring_costs_match_text CHECK (((char_length(TRIM(BOTH FROM match_text)) >= 3) AND (char_length(TRIM(BOTH FROM match_text)) <= 60))),
    CONSTRAINT recurring_costs_name CHECK (((char_length(TRIM(BOTH FROM name)) >= 1) AND (char_length(TRIM(BOTH FROM name)) <= 80))),
    CONSTRAINT recurring_costs_vat_rate CHECK (((vat_rate = ANY (ARRAY[0, 12, 15, 25])) AND ((NOT reverse_charge) OR (vat_rate = 0))))
);


--
-- Name: redirects; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.redirects (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    kind text NOT NULL,
    source text NOT NULL,
    target text,
    product_id uuid,
    term_id uuid,
    origin text NOT NULL,
    hits bigint DEFAULT 0 NOT NULL,
    last_hit_at timestamp with time zone,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    entry_id uuid,
    CONSTRAINT redirects_hits CHECK ((hits >= 0)),
    CONSTRAINT redirects_kind CHECK ((kind = ANY (ARRAY['manual'::text, 'product'::text, 'category'::text, 'tag'::text, 'entry'::text]))),
    CONSTRAINT redirects_kind_columns CHECK ((((kind = 'manual'::text) AND (target IS NOT NULL) AND (product_id IS NULL) AND (term_id IS NULL) AND (entry_id IS NULL)) OR ((kind = 'product'::text) AND (target IS NULL) AND (product_id IS NOT NULL) AND (term_id IS NULL) AND (entry_id IS NULL)) OR ((kind = ANY (ARRAY['category'::text, 'tag'::text])) AND (target IS NULL) AND (product_id IS NULL) AND (term_id IS NOT NULL) AND (entry_id IS NULL)) OR ((kind = 'entry'::text) AND (target IS NULL) AND (product_id IS NULL) AND (term_id IS NULL) AND (entry_id IS NOT NULL)))),
    CONSTRAINT redirects_origin CHECK ((origin = ANY (ARRAY['editor'::text, 'import'::text, 'report'::text, 'assistant'::text, 'system'::text]))),
    CONSTRAINT redirects_origin_kind CHECK (((kind = 'manual'::text) = (origin <> 'system'::text))),
    CONSTRAINT redirects_source_shape CHECK (((source ~ '^/[^[:space:][:cntrl:]?#]+$'::text) AND (strpos(source, chr(92)) = 0) AND (source !~ '//'::text) AND (source !~ '/$'::text) AND (source !~ '[A-Z]'::text) AND (length(source) <= 500))),
    CONSTRAINT redirects_target_shape CHECK (((target IS NULL) OR ((target ~ '^/[^[:space:][:cntrl:]]*$'::text) AND (strpos(target, chr(92)) = 0) AND (target !~ '^//'::text) AND (length(target) <= 2000))))
);


