    order_edit_id uuid,
    exchange_id uuid,
    kind text DEFAULT 'money'::text NOT NULL,
    CONSTRAINT refunds_amount_positive CHECK ((amount_minor > 0)),
    CONSTRAINT refunds_kind CHECK ((kind = ANY (ARRAY['money'::text, 'transfer'::text, 'release'::text, 'void'::text, 'store_credit'::text]))),
    CONSTRAINT refunds_release CHECK (((kind <> 'release'::text) OR ((provider_reference IS NULL) AND (status = 'succeeded'::commerce.refund_status) AND (exchange_id IS NULL) AND (order_edit_id IS NULL)))),
    CONSTRAINT refunds_store_credit CHECK (((kind <> 'store_credit'::text) OR ((status = 'succeeded'::commerce.refund_status) AND (exchange_id IS NULL) AND (order_edit_id IS NULL)))),
    CONSTRAINT refunds_transfer CHECK (((kind <> 'transfer'::text) OR ((exchange_id IS NOT NULL) AND (provider_reference IS NULL) AND (status = 'succeeded'::commerce.refund_status)))),
    CONSTRAINT refunds_void CHECK (((kind <> 'void'::text) OR ((provider_reference IS NULL) AND (status = 'succeeded'::commerce.refund_status) AND (exchange_id IS NULL) AND (order_edit_id IS NULL))))
);


