    CONSTRAINT retention_rules_counts_from CHECK ((counts_from = ANY (ARRAY['event'::text, 'end_of_year'::text]))),
    CONSTRAINT retention_rules_kind CHECK ((kind = ANY (ARRAY['bookkeeping'::text, 'host_bookkeeping'::text, 'unpaid_orders'::text, 'email_bodies'::text, 'security_emails'::text, 'carts'::text, 'delivery_quotes'::text, 'customer_codes'::text, 'customer_sessions'::text, 'webhook_payloads'::text, 'consents'::text, 'privacy_request_contact'::text, 'privacy_requests'::text, 'search_queries'::text, 'visits'::text, 'audit_log'::text, 'form_submissions'::text, 'integration_deliveries'::text, 'abandoned_checkouts'::text, 'recommendation_events'::text, 'ai_usage'::text, 'support_transcripts'::text, 'support_records'::text, 'blog_comments'::text, 'assistant_conversations'::text, 'access_requests'::text, 'unconfirmed_signups'::text, 'content_report_senders'::text, 'carrier_labels'::text, 'sandboxes'::text]))),
    CONSTRAINT retention_rules_period CHECK (((valid_to IS NULL) OR (valid_to > valid_from))),
    CONSTRAINT retention_rules_source CHECK (((length(source) >= 8) AND (length(source) <= 1000))),
    CONSTRAINT retention_rules_unit CHECK ((period_unit = ANY (ARRAY['days'::text, 'months'::text]))),
    CONSTRAINT retention_rules_value CHECK ((period_value > 0)),
    CONSTRAINT retention_rules_verified CHECK (((verified_at IS NULL) = (verified_by IS NULL))),
    CONSTRAINT retention_rules_year_end CHECK (((counts_from = 'event'::text) OR ((period_unit = 'months'::text) AND ((period_value % 12) = 0))))
);


