--
-- Name: return_exchanges; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.return_exchanges (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    return_id uuid NOT NULL,
    order_id uuid NOT NULL,
    seq integer NOT NULL,
    status text NOT NULL,
    currency character(3) NOT NULL,
    market_slug text NOT NULL,
    shipping_kind text DEFAULT 'free'::text NOT NULL,
    shipping_minor bigint DEFAULT 0 NOT NULL,
    delivery_address jsonb NOT NULL,
    credit_minor bigint NOT NULL,
    total_minor bigint NOT NULL,
    difference_minor bigint NOT NULL,
    credit_at_processing bigint,
    difference_at_processing bigint,
    token_hash text,
    expires_at timestamp with time zone,
    terms jsonb,
    confirmed_at timestamp with time zone,
    confirmed_by text,
    confirmed_channel text,
    exchange_order_id uuid,
    refund_id uuid,
    transfer_refund_id uuid,
    made_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    processed_at timestamp with time zone,
    settled_at timestamp with time zone,
    ended_at timestamp with time zone,
    CONSTRAINT return_exchanges_address CHECK ((jsonb_typeof(delivery_address) = 'object'::text)),
    CONSTRAINT return_exchanges_amounts CHECK (((credit_minor >= 0) AND (total_minor >= 0) AND (difference_minor = (total_minor - credit_minor)) AND ((credit_at_processing IS NULL) OR (credit_at_processing >= 0)) AND ((credit_at_processing IS NULL) = (difference_at_processing IS NULL)))),
    CONSTRAINT return_exchanges_confirmation CHECK ((((confirmed_at IS NULL) = (confirmed_by IS NULL)) AND ((confirmed_at IS NULL) = (confirmed_channel IS NULL)) AND ((confirmed_by IS NULL) OR (confirmed_by = ANY (ARRAY['customer'::text, 'staff'::text]))) AND ((confirmed_channel IS NULL) OR (confirmed_channel = ANY (ARRAY['web'::text, 'email'::text, 'letter'::text, 'phone'::text, 'in_person'::text, 'other'::text]))) AND (((confirmed_by = 'customer'::text) = (confirmed_channel = 'web'::text)) OR (confirmed_by IS NULL)))),
    CONSTRAINT return_exchanges_lifecycle CHECK ((((status = 'draft'::text) AND (confirmed_at IS NULL) AND (exchange_order_id IS NULL) AND (processed_at IS NULL) AND (settled_at IS NULL) AND (ended_at IS NULL)) OR ((status = 'proposed'::text) AND (token_hash IS NOT NULL) AND (expires_at IS NOT NULL) AND (confirmed_at IS NULL) AND (exchange_order_id IS NULL) AND (processed_at IS NULL) AND (settled_at IS NULL) AND (ended_at IS NULL)) OR ((status = 'confirmed'::text) AND (token_hash IS NOT NULL) AND (expires_at IS NOT NULL) AND (confirmed_at IS NOT NULL) AND (exchange_order_id IS NULL) AND (processed_at IS NULL) AND (settled_at IS NULL) AND (ended_at IS NULL)) OR ((status = 'processed'::text) AND (confirmed_at IS NOT NULL) AND (exchange_order_id IS NOT NULL) AND (processed_at IS NOT NULL) AND (credit_at_processing IS NOT NULL) AND (settled_at IS NULL) AND (ended_at IS NULL)) OR ((status = 'settled'::text) AND (confirmed_at IS NOT NULL) AND (exchange_order_id IS NOT NULL) AND (processed_at IS NOT NULL) AND (credit_at_processing IS NOT NULL) AND (settled_at IS NOT NULL) AND (ended_at IS NULL)) OR ((status = ANY (ARRAY['declined_by_customer'::text, 'cancelled'::text, 'expired'::text, 'superseded'::text])) AND (ended_at IS NOT NULL) AND (settled_at IS NULL)))),
    CONSTRAINT return_exchanges_market_slug CHECK ((market_slug ~ '^[a-z]{2}(-[a-z0-9]{2,8}){0,3}$'::text)),
    CONSTRAINT return_exchanges_seq CHECK (((seq >= 1) AND (seq <= 5))),
    CONSTRAINT return_exchanges_shipping CHECK (((shipping_kind = ANY (ARRAY['free'::text, 'standard'::text, 'set'::text])) AND (shipping_minor >= 0) AND ((shipping_kind <> 'free'::text) OR (shipping_minor = 0)))),
    CONSTRAINT return_exchanges_status CHECK ((status = ANY (ARRAY['draft'::text, 'proposed'::text, 'confirmed'::text, 'processed'::text, 'settled'::text, 'declined_by_customer'::text, 'cancelled'::text, 'expired'::text, 'superseded'::text]))),
    CONSTRAINT return_exchanges_terms CHECK (((terms IS NULL) OR (jsonb_typeof(terms) = 'array'::text))),
    CONSTRAINT return_exchanges_token CHECK (((token_hash IS NULL) OR (token_hash ~ '^[A-Za-z0-9_-]{43}$'::text)))
);


--
-- Name: return_lines; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.return_lines (
    store_id uuid NOT NULL,
    return_id uuid NOT NULL,
    order_line_id uuid NOT NULL,
    quantity integer NOT NULL,
    condition text,
    reason text,
    restock boolean DEFAULT false NOT NULL,
    deduction_minor bigint DEFAULT 0 NOT NULL,
    deduction_note text,
    decision text DEFAULT 'accept'::text NOT NULL,
    decline_reason text,
    CONSTRAINT return_lines_condition CHECK (((condition IS NULL) OR (condition = ANY (ARRAY['as_new'::text, 'opened'::text, 'used'::text, 'damaged'::text])))),
    CONSTRAINT return_lines_decision CHECK ((decision = ANY (ARRAY['accept'::text, 'decline'::text]))),
    CONSTRAINT return_lines_decline_reason CHECK (((decision = 'accept'::text) OR (length(TRIM(BOTH FROM COALESCE(decline_reason, ''::text))) > 0))),
    CONSTRAINT return_lines_declined_nothing CHECK (((decision = 'accept'::text) OR ((deduction_minor = 0) AND (NOT restock)))),
    CONSTRAINT return_lines_deduction CHECK ((deduction_minor >= 0)),
    CONSTRAINT return_lines_deduction_note CHECK (((deduction_note IS NULL) OR (length(deduction_note) <= 500))),
    CONSTRAINT return_lines_quantity_positive CHECK ((quantity > 0)),
    CONSTRAINT return_lines_reason CHECK (((reason IS NULL) OR (reason = ANY (ARRAY['changed_mind'::text, 'too_big'::text, 'too_small'::text, 'defective'::text, 'not_as_described'::text, 'damaged_in_transit'::text, 'wrong_item'::text, 'arrived_late'::text, 'other'::text]))))
);


--
-- Name: return_settings; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.return_settings (
