    return_address jsonb,
    b2b_returns boolean DEFAULT false NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    instructions_translations jsonb DEFAULT '{}'::jsonb NOT NULL,
    exchanges boolean DEFAULT true NOT NULL,
    label_carrier text,
    label_service text,
    label_auto boolean DEFAULT false NOT NULL,
    CONSTRAINT return_settings_instructions CHECK ((length(instructions) <= 2000)),
    CONSTRAINT return_settings_label_auto CHECK (((NOT label_auto) OR (label_carrier IS NOT NULL))),
    CONSTRAINT return_settings_label_carrier CHECK (((label_carrier IS NULL) OR (label_carrier = ANY (ARRAY['bring'::text, 'postnord'::text, 'porterbuddy'::text, 'helthjem'::text, 'instabox'::text, 'dhl'::text, 'ups'::text, 'dhl_paket'::text, 'nshift'::text, 'sendcloud'::text])))),
    CONSTRAINT return_settings_label_service CHECK (((label_service IS NULL) OR ((label_carrier IS NOT NULL) AND ((char_length(label_service) >= 1) AND (char_length(label_service) <= 20))))),
    CONSTRAINT return_settings_refund_when CHECK ((refund_when = ANY (ARRAY['received'::text, 'request'::text]))),
    CONSTRAINT return_settings_transit CHECK (((transit_days >= 0) AND (transit_days <= 14))),
    CONSTRAINT return_settings_who_pays CHECK ((who_pays_return = ANY (ARRAY['shopper'::text, 'store'::text]))),
    CONSTRAINT return_settings_window CHECK (((window_days >= 14) AND (window_days <= 100)))
);


--
-- Name: returns; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.returns (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    order_id uuid NOT NULL,
    withdrawal_request_id uuid,
    status commerce.return_status DEFAULT 'requested'::commerce.return_status NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    kind text DEFAULT 'return'::text NOT NULL,
    number text NOT NULL,
    reason text,
    reason_note text,
    instructions text,
    label_url text,
    return_address jsonb,
    decision_note text,
    staff_note text,
    approved_at timestamp with time zone,
    shipped_at timestamp with time zone,
    received_at timestamp with time zone,
    inspected_at timestamp with time zone,
    closed_at timestamp with time zone,
    outcome text,
    refund_id uuid,
    refund_computed_minor bigint,
    refund_minor bigint,
    refund_note text,
    refunded_at timestamp with time zone,
    refund_outside boolean DEFAULT false NOT NULL,
    return_shipping_minor bigint DEFAULT 0 NOT NULL,
    refund_deadline timestamp with time zone,
    shipping_refund_minor bigint DEFAULT 0 NOT NULL,
    refund_claimed_at timestamp with time zone,
    public_token text DEFAULT replace(((gen_random_uuid())::text || (gen_random_uuid())::text), '-'::text, ''::text) NOT NULL,
    refund_working jsonb,
    exchange_wish_at timestamp with time zone,
    exchange_wish_note text,
    label_source text,
    label_carrier_id text,
    label_service text,
    label_consignment_number text,
    label_tracking_number text,
    label_tracking_url text,
    label_carrier_url text,
    label_cost_minor bigint,
    label_cost_carrier jsonb,
    label_test boolean DEFAULT false NOT NULL,
    label_booked_at timestamp with time zone,
    label_tries integer DEFAULT 0 NOT NULL,
    CONSTRAINT returns_amounts CHECK (((return_shipping_minor >= 0) AND (refund_minor >= 0) AND (refund_computed_minor >= 0) AND (shipping_refund_minor >= 0))),
    CONSTRAINT returns_decision_note CHECK (((decision_note IS NULL) OR (length(decision_note) <= 1000))),
    CONSTRAINT returns_exchange_wish CHECK (((exchange_wish_note IS NULL) OR ((exchange_wish_at IS NOT NULL) AND (char_length(exchange_wish_note) <= 500)))),
    CONSTRAINT returns_instructions CHECK (((instructions IS NULL) OR (length(instructions) <= 2000))),
    CONSTRAINT returns_kind CHECK ((kind = ANY (ARRAY['withdrawal'::text, 'return'::text]))),
    CONSTRAINT returns_kind_request CHECK (((kind = 'withdrawal'::text) = (withdrawal_request_id IS NOT NULL))),
    CONSTRAINT returns_label_carrier CHECK ((((NOT (label_source IS DISTINCT FROM 'carrier'::text)) = ((label_carrier_id IS NOT NULL) AND (label_booked_at IS NOT NULL))) AND ((label_carrier_id IS NULL) OR (label_carrier_id = ANY (ARRAY['bring'::text, 'postnord'::text, 'porterbuddy'::text, 'helthjem'::text, 'instabox'::text, 'dhl'::text, 'ups'::text, 'dhl_paket'::text, 'nshift'::text, 'sendcloud'::text]))) AND ((NOT (label_source IS DISTINCT FROM 'carrier'::text)) OR ((label_service IS NULL) AND (label_consignment_number IS NULL) AND (label_tracking_number IS NULL) AND (label_tracking_url IS NULL) AND (label_carrier_url IS NULL) AND (label_cost_minor IS NULL) AND (label_cost_carrier IS NULL) AND (NOT label_test))))),
    CONSTRAINT returns_label_cost CHECK ((((label_cost_minor IS NULL) OR (label_cost_minor >= 0)) AND ((label_cost_carrier IS NULL) OR (jsonb_typeof(label_cost_carrier) = 'object'::text)))),
    CONSTRAINT returns_label_pasted CHECK (((NOT (label_source IS DISTINCT FROM 'pasted'::text)) = (label_url IS NOT NULL))),
    CONSTRAINT returns_label_source CHECK (((label_source IS NULL) OR (label_source = ANY (ARRAY['pasted'::text, 'carrier'::text])))),
    CONSTRAINT returns_label_tries CHECK ((label_tries >= 0)),
    CONSTRAINT returns_label_url CHECK (((label_url IS NULL) OR (label_url ~ '^https://'::text))),
    CONSTRAINT returns_label_urls CHECK ((((label_tracking_url IS NULL) OR (label_tracking_url ~ '^https://'::text)) AND ((label_carrier_url IS NULL) OR (label_carrier_url ~ '^https://'::text)))),
    CONSTRAINT returns_outcome CHECK (((outcome IS NULL) OR (outcome = ANY (ARRAY['refunded'::text, 'declined'::text, 'no_refund'::text, 'cancelled'::text, 'exchanged'::text])))),
    CONSTRAINT returns_reason CHECK (((reason IS NULL) OR (reason = ANY (ARRAY['changed_mind'::text, 'too_big'::text, 'too_small'::text, 'defective'::text, 'not_as_described'::text, 'damaged_in_transit'::text, 'wrong_item'::text, 'arrived_late'::text, 'other'::text])))),
    CONSTRAINT returns_reason_note CHECK (((reason_note IS NULL) OR (length(reason_note) <= 500))),
    CONSTRAINT returns_refund_outside CHECK (((NOT refund_outside) OR (refund_minor IS NOT NULL))),
    CONSTRAINT returns_refund_recorded CHECK (((refund_minor IS NULL) = (refunded_at IS NULL))),
    CONSTRAINT returns_refund_stripe CHECK (((refund_id IS NULL) OR ((refund_minor IS NOT NULL) AND (NOT refund_outside)))),
    CONSTRAINT returns_staff_note CHECK (((staff_note IS NULL) OR (length(staff_note) <= 2000))),
    CONSTRAINT returns_times_in_order CHECK ((((received_at IS NULL) OR (approved_at IS NULL) OR (received_at >= approved_at)) AND ((inspected_at IS NULL) OR (received_at IS NULL) OR (inspected_at >= received_at)) AND ((closed_at IS NULL) OR (inspected_at IS NULL) OR (closed_at >= inspected_at)) AND ((closed_at IS NULL) OR (received_at IS NULL) OR (closed_at >= received_at)) AND ((shipped_at IS NULL) OR (received_at IS NULL) OR (shipped_at <= received_at))))
);


