    CONSTRAINT review_pictures_bytes CHECK ((((bytes >= 1) AND (bytes <= 614400)) AND ((thumb_bytes >= 1) AND (thumb_bytes <= 153600)))),
    CONSTRAINT review_pictures_hidden CHECK (((hidden_at IS NULL) = (hidden_by IS NULL))),
    CONSTRAINT review_pictures_position CHECK ((("position" >= 0) AND ("position" <= 2))),
    CONSTRAINT review_pictures_size CHECK ((((width >= 1) AND (width <= 1600)) AND ((height >= 1) AND (height <= 1600)))),
    CONSTRAINT review_pictures_type CHECK ((type = ANY (ARRAY['image/webp'::text, 'image/jpeg'::text])))
);


