    visit_id uuid,
    CONSTRAINT search_queries_arm CHECK ((((arm IS NULL) = (experiment_id IS NULL)) AND COALESCE((arm = ANY (ARRAY['hybrid'::text, 'keyword'::text])), true))),
    CONSTRAINT search_queries_meaning CHECK (((meaning_results >= 0) AND (meaning_results <= results))),
    CONSTRAINT search_queries_query CHECK (((length(query) >= 1) AND (length(query) <= 100))),
    CONSTRAINT search_queries_results CHECK ((results >= 0))
);


--
-- Name: search_rules; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.search_rules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    action text NOT NULL,
    product_id uuid,
    term_id uuid,
    content_type text DEFAULT 'product'::text NOT NULL,
    target text,
    queries text[] DEFAULT '{}'::text[] NOT NULL,
    match text DEFAULT 'contains'::text NOT NULL,
    "position" integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT search_rules_action CHECK ((action = ANY (ARRAY['pin'::text, 'boost'::text, 'bury'::text, 'redirect'::text]))),
    CONSTRAINT search_rules_content_type CHECK ((content_type = 'product'::text)),
    CONSTRAINT search_rules_match CHECK ((match = ANY (ARRAY['contains'::text, 'exact'::text]))),
    CONSTRAINT search_rules_position CHECK ((("position" >= 0) AND ("position" <= 1000))),
    CONSTRAINT search_rules_queries CHECK ((cardinality(queries) <= 20)),
    CONSTRAINT search_rules_shape CHECK (
CASE action
    WHEN 'pin'::text THEN ((product_id IS NOT NULL) AND (term_id IS NULL) AND (target IS NULL) AND (cardinality(queries) >= 1))
    WHEN 'redirect'::text THEN ((target IS NOT NULL) AND (product_id IS NULL) AND (term_id IS NULL) AND (cardinality(queries) >= 1))
    ELSE ((target IS NULL) AND ((product_id IS NULL) <> (term_id IS NULL)))
END)
);


