--
-- Name: search_synonyms; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.search_synonyms (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    locale text NOT NULL,
    kind text NOT NULL,
    words text[] NOT NULL,
    means text[] DEFAULT '{}'::text[] NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT search_synonyms_kind CHECK ((kind = ANY (ARRAY['both'::text, 'one_way'::text]))),
    CONSTRAINT search_synonyms_locale CHECK (((length(locale) >= 2) AND (length(locale) <= 20))),
    CONSTRAINT search_synonyms_words CHECK (
CASE
    WHEN (kind = 'both'::text) THEN (((cardinality(words) >= 2) AND (cardinality(words) <= 20)) AND (cardinality(means) = 0))
    ELSE (((cardinality(words) >= 1) AND (cardinality(words) <= 20)) AND ((cardinality(means) >= 1) AND (cardinality(means) <= 20)))
END)
);


