    CONSTRAINT selling_plans_min_cycles CHECK (((min_cycles >= 0) AND (min_cycles <= 24))),
    CONSTRAINT selling_plans_signup_fee_object CHECK ((jsonb_typeof(signup_fee) = 'object'::text)),
