    CONSTRAINT shipment_tracking_stopped CHECK ((((stopped IS NULL) = (stopped_at IS NULL)) AND ((stopped IS NULL) OR (stopped = ANY (ARRAY['delivered'::text, 'returned'::text, 'old'::text, 'undone'::text, 'carrier_failing'::text, 'no_agreement'::text])))))
);


