    CONSTRAINT shipments_handover_bare CHECK (((method = 'parcel'::text) OR ((carrier = ''::text) AND (tracking_number = ''::text) AND (tracking_url IS NULL) AND (carrier_id IS NULL) AND (consignment_number IS NULL) AND (label_url IS NULL)))),
    CONSTRAINT shipments_label_cost CHECK (((label_cost_minor IS NULL) OR ((label_cost_minor >= 0) AND (method = 'parcel'::text)))),
    CONSTRAINT shipments_label_url CHECK (((label_url IS NULL) OR (label_url ~ '^https://'::text))),
    CONSTRAINT shipments_method CHECK ((method = ANY (ARRAY['parcel'::text, 'pickup'::text, 'local'::text]))),
    CONSTRAINT shipments_tracking_url CHECK ((tracking_url ~ '^https://'::text)),
    CONSTRAINT shipments_undo_reason CHECK (((undo_reason IS NULL) OR ((undone_at IS NOT NULL) AND (char_length(undo_reason) <= 200)))),
    CONSTRAINT shipments_undone_by CHECK (((undone_by IS NULL) OR (undone_at IS NOT NULL)))
);


