    mover_secret text,
    CONSTRAINT shop_moves_copy CHECK ((jsonb_typeof(copy) = 'object'::text)),
    CONSTRAINT shop_moves_mover CHECK (((mover_secret IS NULL) OR ((source = 'woocommerce'::text) AND (status = 'connected'::text)))),
    CONSTRAINT shop_moves_name CHECK (((length(shop_name) <= 200) AND ((primary_domain IS NULL) OR (length(primary_domain) <= 255)))),
    CONSTRAINT shop_moves_shop CHECK ((((source = 'shopify'::text) AND (shop_domain ~ '^[a-z0-9][a-z0-9-]*\.myshopify\.com$'::text) AND (length(shop_domain) <= 120)) OR ((source = 'woocommerce'::text) AND (shop_domain ~ '^[a-z0-9.-]{3,253}(/[a-z0-9._~-]{1,80})?$'::text) AND (length(shop_domain) <= 340)))),
    CONSTRAINT shop_moves_source CHECK ((source = ANY (ARRAY['shopify'::text, 'woocommerce'::text]))),
    CONSTRAINT shop_moves_status CHECK ((status = ANY (ARRAY['connected'::text, 'disconnected'::text]))),
    CONSTRAINT shop_moves_token CHECK (((status <> 'connected'::text) OR (access_token IS NOT NULL)))
);


