    CONSTRAINT store_domains_language_or_market CHECK (((language IS NULL) OR (market IS NULL))),
    CONSTRAINT store_domains_market CHECK (((market IS NULL) OR (market ~ '^[A-Z]{2}$'::text))),
    CONSTRAINT store_domains_primary_active CHECK (((NOT is_primary) OR (status = 'active'::text))),
    CONSTRAINT store_domains_primary_language CHECK (((NOT is_primary) OR (language IS NULL))),
    CONSTRAINT store_domains_primary_market CHECK (((NOT is_primary) OR (market IS NULL))),
    CONSTRAINT store_domains_status CHECK ((status = ANY (ARRAY['pending'::text, 'active'::text])))
);


