    archived_at timestamp with time zone,
    archived_by uuid,
    pack_key text,
    pack_version integer,
    pack_pictures jsonb DEFAULT '{}'::jsonb NOT NULL,
    pictures_wanted_by uuid,
    pictures_wanted_at timestamp with time zone,
    picture_claimed_until timestamp with time zone,
    picture_failures smallint DEFAULT 0 NOT NULL,
    picture_problem text,
    design_preset_id uuid,
    kind text DEFAULT 'content'::text NOT NULL,
    CONSTRAINT store_starters_archived_unpublished CHECK ((NOT (published AND (archived_at IS NOT NULL)))),
    CONSTRAINT store_starters_category CHECK ((category = ANY (ARRAY['appointments'::text, 'retail'::text, 'downloads'::text, 'rentals_stays'::text, 'subscriptions'::text, 'services'::text, 'other'::text]))),
    CONSTRAINT store_starters_demo CHECK (((kind <> 'demo'::text) OR ((design_preset_id IS NULL) AND (pack_key IS NULL) AND (published_store_id IS NULL)))),
    CONSTRAINT store_starters_description CHECK ((length(description) <= 2000)),
    CONSTRAINT store_starters_draft CHECK (((draft IS NULL) OR (jsonb_typeof(draft) = 'object'::text))),
    CONSTRAINT store_starters_kind CHECK ((kind = ANY (ARRAY['content'::text, 'demo'::text]))),
    CONSTRAINT store_starters_pack CHECK (((pack_version IS NULL) OR ((pack_key IS NOT NULL) AND (pack_version > 0)))),
    CONSTRAINT store_starters_pack_pictures CHECK ((jsonb_typeof(pack_pictures) = 'object'::text)),
    CONSTRAINT store_starters_picture_failures CHECK (((picture_failures >= 0) AND (picture_failures <= 20))),
    CONSTRAINT store_starters_picture_problem CHECK (((picture_problem IS NULL) OR (length(picture_problem) <= 500))),
    CONSTRAINT store_starters_picture_url CHECK (((picture_url IS NULL) OR ((length(picture_url) <= 2000) AND (picture_url ~ '^(https://|/[^/])'::text)))),
    CONSTRAINT store_starters_pictures_wanted CHECK ((((pictures_wanted_by IS NULL) = (pictures_wanted_at IS NULL)) AND ((pictures_wanted_at IS NULL) OR (pack_key IS NOT NULL)))),
    CONSTRAINT store_starters_summary CHECK ((length(summary) <= 200)),
    CONSTRAINT store_starters_title CHECK (((length(btrim(title)) >= 1) AND (length(btrim(title)) <= 80)))
);


