    CONSTRAINT store_tax_profile_vat_check CHECK (((vat_number IS NOT NULL) OR ((vat_number_check_id IS NULL) AND (vat_number_checked_at IS NULL) AND (vat_number_valid IS NULL)))),
    CONSTRAINT store_tax_profile_vat_number CHECK (((vat_number IS NULL) OR (vat_number ~ '^[A-Z]{2}[0-9A-Z+*.]{2,12}$'::text)))
