    CONSTRAINT suppliers_drop_ship_texts CHECK (((length(return_address) <= 500) AND (length(order_note) <= 500))),
    CONSTRAINT suppliers_name CHECK (((char_length(TRIM(BOTH FROM name)) >= 1) AND (char_length(TRIM(BOTH FROM name)) <= 120))),
    CONSTRAINT suppliers_order_email CHECK (((order_email IS NULL) OR (((length(order_email) >= 3) AND (length(order_email) <= 254)) AND (order_email ~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$'::text)))),
