    CONSTRAINT suppliers_order_method CHECK ((order_method = ANY (ARRAY['email'::text, 'connected'::text, 'file'::text]))),
    CONSTRAINT suppliers_organisation_number CHECK (((organisation_number IS NULL) OR (organisation_number ~ '^[0-9A-Za-z -]{4,30}$'::text))),
    CONSTRAINT suppliers_ships_from CHECK (((ships_from IS NULL) OR (ships_from ~ '^[A-Z]{2}$'::text))),
    CONSTRAINT suppliers_usual_kind CHECK (((usual_kind IS NULL) OR (usual_kind ~ '^[a-z_]{2,30}$'::text)))
);


