    handler text NOT NULL,
    assignee_id uuid,
    token_hash text,
    email_token_hash text,
    customer_id uuid,
    requester_id uuid,
    about_store_id uuid,
    market text,
    locale text NOT NULL,
    contact_name text,
    contact_email text,
    page_path text,
    tone smallint,
    tone_alert_at timestamp with time zone,
    handoff_reason text,
    ai_reason text,
    message_seq integer DEFAULT 0 NOT NULL,
    partner_seq integer DEFAULT 0 NOT NULL,
    partner_paused boolean DEFAULT false NOT NULL,
    visitor_seen_at timestamp with time zone,
    email_sent_seq integer DEFAULT 0 NOT NULL,
    email_count smallint DEFAULT 0 NOT NULL,
    contact_changes smallint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    last_message_at timestamp with time zone DEFAULT now() NOT NULL,
    last_customer_at timestamp with time zone,
    first_agent_at timestamp with time zone,
    queued_at timestamp with time zone,
    claimed_at timestamp with time zone,
    ended_at timestamp with time zone,
    ended_by text,
    waiting_alert_at timestamp with time zone,
    summary jsonb,
    summary_status text DEFAULT 'none'::text NOT NULL,
    summary_tries smallint DEFAULT 0 NOT NULL,
    brief jsonb,
    rating text,
    rating_comment text,
    channel_key text DEFAULT replace((gen_random_uuid())::text, '-'::text, ''::text) NOT NULL,
    anonymised_at timestamp with time zone,
    email_sent_at timestamp with time zone,
    desk_mode text,
    reply_key text,
    email_subject text,
    email_message_id text,
    CONSTRAINT support_conversations_assignee CHECK ((((assignee_id IS NOT NULL) = ((status = 'open'::text) AND (handler = 'human'::text))) OR (anonymised_at IS NOT NULL))),
    CONSTRAINT support_conversations_desk_mode CHECK (((desk_mode IS NULL) OR (desk_mode = ANY (ARRAY['off'::text, 'ai_first'::text, 'people'::text])))),
    CONSTRAINT support_conversations_email_fields CHECK ((COALESCE((length(email_subject) <= 200), true) AND COALESCE((length(email_message_id) <= 998), true))),
    CONSTRAINT support_conversations_emails CHECK ((((email_count >= 0) AND (email_count <= 20)) AND ((contact_changes >= 0) AND (contact_changes <= 3)))),
    CONSTRAINT support_conversations_ended_by CHECK (((ended_by IS NULL) OR (ended_by = ANY (ARRAY['customer'::text, 'agent'::text, 'timeout'::text, 'system'::text])))),
    CONSTRAINT support_conversations_handler CHECK ((handler = ANY (ARRAY['ai'::text, 'queue'::text, 'human'::text]))),
    CONSTRAINT support_conversations_handoff_reason CHECK (((handoff_reason IS NULL) OR (handoff_reason = ANY (ARRAY['customer'::text, 'ai'::text, 'tone'::text, 'no_ai'::text, 'limit'::text])))),
    CONSTRAINT support_conversations_kaizen_customer CHECK (((store_id IS NOT NULL) OR (customer_id IS NULL))),
    CONSTRAINT support_conversations_lengths CHECK ((COALESCE((length(contact_name) <= 120), true) AND COALESCE((length(contact_email) <= 254), true) AND COALESCE((length(page_path) <= 300), true) AND COALESCE((length(ai_reason) <= 200), true) AND COALESCE((length(rating_comment) <= 500), true) AND ((length(locale) >= 2) AND (length(locale) <= 16)))),
    CONSTRAINT support_conversations_rating CHECK (((rating IS NULL) OR (rating = ANY (ARRAY['good'::text, 'bad'::text])))),
    CONSTRAINT support_conversations_reply_key_shape CHECK (((reply_key IS NULL) OR (reply_key ~ '^[a-z0-9]{12,32}$'::text))),
    CONSTRAINT support_conversations_requester CHECK ((((source = 'admin'::text) = (requester_id IS NOT NULL)) OR (anonymised_at IS NOT NULL))),
    CONSTRAINT support_conversations_source CHECK ((source = ANY (ARRAY['site'::text, 'admin'::text, 'email'::text, 'form'::text]))),
    CONSTRAINT support_conversations_status CHECK ((status = ANY (ARRAY['open'::text, 'ended'::text]))),
    CONSTRAINT support_conversations_summary_status CHECK ((summary_status = ANY (ARRAY['none'::text, 'pending'::text, 'done'::text, 'failed'::text, 'skipped'::text]))),
    CONSTRAINT support_conversations_token CHECK (((source <> 'site'::text) OR (token_hash IS NOT NULL) OR (anonymised_at IS NOT NULL))),
    CONSTRAINT support_conversations_tone CHECK (((tone IS NULL) OR ((tone >= '-100'::integer) AND (tone <= 100))))
);


