--
-- Name: support_messages; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.support_messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    conversation_id uuid NOT NULL,
    store_id uuid,
    seq integer NOT NULL,
    author text NOT NULL,
    account_id uuid,
    body text NOT NULL,
    kind text,
    data jsonb,
    action_id uuid,
    tone smallint,
    tone_label text,
    tools jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT support_messages_author CHECK ((author = ANY (ARRAY['customer'::text, 'ai'::text, 'agent'::text, 'system'::text, 'note'::text, 'partner'::text]))),
    CONSTRAINT support_messages_body CHECK (
CASE author
    WHEN 'customer'::text THEN ((length(body) >= 1) AND (length(body) <= 1000))
    WHEN 'ai'::text THEN ((length(body) >= 1) AND (length(body) <= 2000))
    WHEN 'agent'::text THEN ((length(body) >= 1) AND (length(body) <= 4000))
    WHEN 'note'::text THEN ((length(body) >= 1) AND (length(body) <= 2000))
    WHEN 'partner'::text THEN (length(body) <= 3000)
    ELSE (body = ''::text)
END),
    CONSTRAINT support_messages_tone CHECK (((tone IS NULL) OR ((author = 'customer'::text) AND ((tone >= '-100'::integer) AND (tone <= 100))))),
    CONSTRAINT support_messages_tone_label CHECK (((tone_label IS NULL) OR (tone_label = ANY (ARRAY['happy'::text, 'calm'::text, 'neutral'::text, 'confused'::text, 'worried'::text, 'frustrated'::text, 'angry'::text]))))
);


