    CONSTRAINT terms_image_pair CHECK (((image_thumbnail_url IS NULL) OR (image_url IS NOT NULL))),
    CONSTRAINT terms_kind CHECK ((kind = ANY (ARRAY['category'::text, 'tag'::text]))),
    CONSTRAINT terms_name CHECK (((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 80))),
    CONSTRAINT terms_not_own_parent CHECK (((parent_id IS NULL) OR (parent_id <> id))),
    CONSTRAINT terms_page_parts CHECK ((((description IS NULL) AND (image_url IS NULL) AND (texts = '{}'::jsonb)) OR ((content_type = 'product'::text) AND (store_id IS NOT NULL)))),
    CONSTRAINT terms_product_layout CHECK (((product_layout_id IS NULL) OR (content_type = 'product'::text))),
    CONSTRAINT terms_products_in_stores CHECK (((content_type <> 'product'::text) OR (store_id IS NOT NULL))),
    CONSTRAINT terms_requires_unit_price CHECK (((NOT requires_unit_price) OR ((content_type = 'product'::text) AND (kind = 'category'::text)))),
    CONSTRAINT terms_rules CHECK (((rules IS NULL) OR ((jsonb_typeof(rules) = 'object'::text) AND (content_type = 'product'::text) AND (store_id IS NOT NULL) AND (NOT requires_unit_price)))),
    CONSTRAINT terms_seo_object CHECK ((jsonb_typeof(seo) = 'object'::text)),
    CONSTRAINT terms_slug_format CHECK (((slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'::text) AND (length(slug) <= 80))),
    CONSTRAINT terms_tags_flat CHECK (((kind = 'category'::text) OR (parent_id IS NULL))),
    CONSTRAINT terms_texts_object CHECK ((jsonb_typeof(texts) = 'object'::text))
);


