--
-- Name: variant_availability; Type: VIEW; Schema: commerce; Owner: -
--

CREATE VIEW commerce.variant_availability AS
 SELECT v.store_id,
    v.id AS variant_id,
    (v.delivery)::text AS delivery,
    (
        CASE
            WHEN (b.components > 0) THEN b.free
            ELSE a.free
        END)::integer AS in_stock,
    (
        CASE
            WHEN (b.components > 0) THEN b.free
            ELSE a.available
        END)::integer AS raw_available,
    v.stock_policy,
    v.backorder_days,
        CASE
            WHEN (b.components > 0) THEN (b.free > (0)::numeric)
            ELSE ((a.free > (0)::numeric) OR (v.stock_policy = 'continue'::text))
        END AS can_buy,
        CASE
            WHEN (v.preorder_until > CURRENT_DATE) THEN v.preorder_until
            ELSE NULL::date
        END AS preorder_until
   FROM ((commerce.product_variants v
     CROSS JOIN LATERAL ( SELECT COALESCE(sum(s.available), (0)::numeric) AS available,
            COALESCE(sum(GREATEST(s.available, (0)::bigint)), (0)::numeric) AS free
           FROM (commerce.available_stock s
             JOIN commerce.inventory_locations loc ON (((loc.store_id = s.store_id) AND (loc.id = s.location_id) AND loc.active AND loc.fulfils_online)))
          WHERE ((s.store_id = v.store_id) AND (s.variant_id = v.id))) a)
     CROSS JOIN LATERAL ( SELECT count(*) AS components,
                CASE
                    WHEN (count(*) = 0) THEN (0)::numeric
                    WHEN (COALESCE(sum(bc.quantity), (0)::bigint) < 2) THEN (0)::numeric
                    WHEN bool_or(((NOT cv.active) OR (cp.status = 'archived'::commerce.product_status) OR (cp.kind <> 'goods'::text) OR (cv.delivery <> 'physical'::commerce.delivery) OR (cp.vat_category <> bp.vat_category))) THEN (0)::numeric
                    ELSE COALESCE(min(floor((cf.free / (bc.quantity)::numeric))), (0)::numeric)
                END AS free
           FROM ((((commerce.bundle_components bc
             JOIN commerce.products bp ON (((bp.store_id = v.store_id) AND (bp.id = v.product_id))))
             JOIN commerce.product_variants cv ON (((cv.store_id = bc.store_id) AND (cv.id = bc.component_variant_id))))
             JOIN commerce.products cp ON (((cp.store_id = cv.store_id) AND (cp.id = cv.product_id))))
             CROSS JOIN LATERAL ( SELECT COALESCE(sum(GREATEST(s.available, (0)::bigint)), (0)::numeric) AS free
                   FROM (commerce.available_stock s
                     JOIN commerce.inventory_locations loc ON (((loc.store_id = s.store_id) AND (loc.id = s.location_id) AND loc.active AND loc.fulfils_online)))
                  WHERE ((s.store_id = cv.store_id) AND (s.variant_id = cv.id))) cf)
          WHERE ((bc.store_id = v.store_id) AND (bc.bundle_variant_id = v.id))) b);


