    "position" integer DEFAULT 0 NOT NULL,
    assignment_id uuid,
    task_id uuid,
    description text NOT NULL,
    unit text DEFAULT 'hour'::text NOT NULL,
    quantity_hundredths integer DEFAULT 0 NOT NULL,
    unit_price_minor bigint DEFAULT 0 NOT NULL,
    discount_bp integer DEFAULT 0 NOT NULL,
    vat_category text DEFAULT 'standard'::text NOT NULL,
    vat_rate numeric(6,4) DEFAULT '0'::numeric NOT NULL,
    excl_minor bigint DEFAULT 0 NOT NULL,
    vat_minor bigint DEFAULT 0 NOT NULL,
    incl_minor bigint DEFAULT 0 NOT NULL,
    quantity_manual boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT work_invoice_lines_amounts CHECK (((excl_minor >= 0) AND (vat_minor >= 0) AND (incl_minor = (excl_minor + vat_minor)))),
    CONSTRAINT work_invoice_lines_description CHECK (((length(TRIM(BOTH FROM description)) >= 1) AND (length(TRIM(BOTH FROM description)) <= 500))),
    CONSTRAINT work_invoice_lines_discount CHECK (((discount_bp >= 0) AND (discount_bp <= 10000))),
    CONSTRAINT work_invoice_lines_price CHECK (((unit_price_minor >= 0) AND (unit_price_minor <= 1000000000))),
    CONSTRAINT work_invoice_lines_quantity CHECK (((quantity_hundredths >= 0) AND (quantity_hundredths <= 10000000))),
    CONSTRAINT work_invoice_lines_unit CHECK ((unit = ANY (ARRAY['hour'::text, 'unit'::text]))),
    CONSTRAINT work_invoice_lines_vat_category CHECK ((vat_category = ANY (ARRAY['standard'::text, 'exempt'::text, 'reverse_charge'::text, 'outside_scope'::text]))),
    CONSTRAINT work_invoice_lines_vat_rate CHECK (((vat_rate >= (0)::numeric) AND (vat_rate < (1)::numeric) AND ((vat_category = 'standard'::text) OR (vat_rate = (0)::numeric))))
);


--
-- Name: work_invoice_losses; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.work_invoice_losses (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    invoice_id uuid NOT NULL,
    amount_minor bigint NOT NULL,
    currency character(3) NOT NULL,
    written_off_on date NOT NULL,
    reason text,
    reverses uuid,
    recorded_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT work_invoice_losses_amount CHECK (((amount_minor <> 0) AND ((reverses IS NULL) = (amount_minor > 0)))),
    CONSTRAINT work_invoice_losses_currency CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT work_invoice_losses_reason CHECK ((length(COALESCE(reason, ''::text)) <= 500))
);


--
-- Name: work_invoice_payments; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.work_invoice_payments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    invoice_id uuid NOT NULL,
    amount_minor bigint NOT NULL,
    currency character(3) NOT NULL,
    received_on date NOT NULL,
    method text NOT NULL,
    reference text,
    provider_reference text,
    reverses uuid,
    recorded_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT work_invoice_payments_amount CHECK ((amount_minor <> 0)),
    CONSTRAINT work_invoice_payments_currency CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT work_invoice_payments_method CHECK ((method = ANY (ARRAY['bank'::text, 'card'::text, 'cash'::text, 'other'::text, 'stripe'::text, 'prepaid'::text]))),
    CONSTRAINT work_invoice_payments_reversal CHECK (((reverses IS NULL) OR (amount_minor < 0))),
    CONSTRAINT work_invoice_payments_texts CHECK ((length(COALESCE(reference, ''::text)) <= 200))
);


--
-- Name: work_recurring_invoices; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.work_recurring_invoices (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    client_id uuid NOT NULL,
    name text NOT NULL,
    description text NOT NULL,
    unit text DEFAULT 'unit'::text NOT NULL,
    quantity_hundredths integer DEFAULT 100 NOT NULL,
    unit_price_minor bigint NOT NULL,
    discount_bp integer DEFAULT 0 NOT NULL,
    vat_category text DEFAULT 'standard'::text NOT NULL,
    currency character(3) NOT NULL,
    recurrence_interval integer DEFAULT 1 NOT NULL,
    recurrence_period text DEFAULT 'month'::text NOT NULL,
    start_date date NOT NULL,
    end_date date,
    payment_days integer,
    auto_issue boolean DEFAULT false NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    skipped_periods date[] DEFAULT '{}'::date[] NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT work_recurring_invoices_currency CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT work_recurring_invoices_dates CHECK (((end_date IS NULL) OR (end_date >= start_date))),
    CONSTRAINT work_recurring_invoices_description CHECK (((length(TRIM(BOTH FROM description)) >= 1) AND (length(TRIM(BOTH FROM description)) <= 500))),
    CONSTRAINT work_recurring_invoices_discount CHECK (((discount_bp >= 0) AND (discount_bp <= 10000))),
    CONSTRAINT work_recurring_invoices_interval CHECK (((recurrence_interval >= 1) AND (recurrence_interval <= 4))),
    CONSTRAINT work_recurring_invoices_name CHECK (((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 120))),
    CONSTRAINT work_recurring_invoices_payment_days CHECK (((payment_days IS NULL) OR ((payment_days >= 1) AND (payment_days <= 90)))),
    CONSTRAINT work_recurring_invoices_period CHECK ((recurrence_period = ANY (ARRAY['week'::text, 'month'::text, 'year'::text]))),
    CONSTRAINT work_recurring_invoices_price CHECK (((unit_price_minor >= 0) AND (unit_price_minor <= 1000000000))),
    CONSTRAINT work_recurring_invoices_quantity CHECK (((quantity_hundredths >= 0) AND (quantity_hundredths <= 10000000))),
    CONSTRAINT work_recurring_invoices_unit CHECK ((unit = ANY (ARRAY['hour'::text, 'unit'::text]))),
    CONSTRAINT work_recurring_invoices_vat_category CHECK ((vat_category = ANY (ARRAY['standard'::text, 'exempt'::text, 'reverse_charge'::text, 'outside_scope'::text])))
);


--
-- Name: work_settings; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.work_settings (
    store_id uuid NOT NULL,
    vat_registered boolean DEFAULT true NOT NULL,
    vat_number text,
    default_payment_days integer DEFAULT 14,
    default_currency character(3),
    bank_account text,
    bic text,
    payment_note text,
    invoice_footer text,
    late_payment_note text,
    estimate_alert_minutes integer DEFAULT 10,
    estimate_alert_popup boolean DEFAULT true NOT NULL,
    estimate_alert_sound boolean DEFAULT false NOT NULL,
    show_time_notes_to_clients boolean DEFAULT false NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT work_settings_currency CHECK (((default_currency IS NULL) OR (default_currency ~ '^[A-Z]{3}$'::text))),
    CONSTRAINT work_settings_estimate_alert CHECK (((estimate_alert_minutes IS NULL) OR ((estimate_alert_minutes >= 1) AND (estimate_alert_minutes <= 480)))),
    CONSTRAINT work_settings_payment_days CHECK (((default_payment_days IS NULL) OR ((default_payment_days >= 1) AND (default_payment_days <= 90)))),
    CONSTRAINT work_settings_texts CHECK (((length(COALESCE(payment_note, ''::text)) <= 1000) AND (length(COALESCE(invoice_footer, ''::text)) <= 2000) AND (length(COALESCE(late_payment_note, ''::text)) <= 2000)))
);


--
-- Name: work_tasks; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.work_tasks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    assignment_id uuid NOT NULL,
    title text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    estimated_minutes integer,
    sort_order integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT work_tasks_estimate CHECK (((estimated_minutes IS NULL) OR (estimated_minutes >= 0))),
    CONSTRAINT work_tasks_status CHECK ((status = ANY (ARRAY['open'::text, 'done'::text]))),
    CONSTRAINT work_tasks_title CHECK (((length(TRIM(BOTH FROM title)) >= 1) AND (length(TRIM(BOTH FROM title)) <= 200)))
);


--
-- Name: work_timers; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.work_timers (
    store_id uuid NOT NULL,
    account_id uuid NOT NULL,
    assignment_id uuid NOT NULL,
    task_id uuid,
    started_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: workflow_runs; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.workflow_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    workflow_id uuid NOT NULL,
    event text NOT NULL,
    subject_id uuid,
    event_key text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    matched boolean,
    outcome jsonb,
    claimed_until timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    CONSTRAINT workflow_runs_status CHECK ((status = ANY (ARRAY['pending'::text, 'done'::text, 'failed'::text, 'capped'::text])))
);


--
-- Name: workflows; Type: TABLE; Schema: commerce; Owner: -
--

CREATE TABLE commerce.workflows (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    name text NOT NULL,
    trigger text NOT NULL,
    schedule jsonb,
    conditions jsonb DEFAULT '[]'::jsonb NOT NULL,
    actions jsonb NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    tested_version integer,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT workflows_name CHECK (((char_length(name) >= 1) AND (char_length(name) <= 80))),
    CONSTRAINT workflows_on_when_tested CHECK (((NOT enabled) OR (tested_version = version))),
    CONSTRAINT workflows_trigger CHECK ((trigger = ANY (ARRAY['order.paid'::text, 'order.sent'::text, 'order.cancelled'::text, 'order.refunded'::text, 'customer.created'::text, 'subscription.started'::text, 'subscription.cancelled'::text, 'return.requested'::text, 'withdrawal.received'::text, 'product.created'::text, 'product.updated'::text, 'stock.low'::text, 'discount.created'::text, 'inventory.updated'::text, 'product.archived'::text, 'order.created'::text, 'order.updated'::text, 'fulfilment.created'::text, 'fulfilment.updated'::text, 'refund.created'::text, 'return.updated'::text, 'quote.requested'::text, 'draft.sent'::text, 'customer.updated'::text, 'customer.erased'::text, 'subscription.renewed'::text, 'subscription.payment_failed'::text, 'gift_card.issued'::text, 'review.created'::text, 'support.waiting'::text, 'schedule'::text])))
);


